-- Bổ sung lộ trình A0–B2, giữ nguyên 25 buổi cũ và mọi tiến độ hiện có.
-- Dữ liệu nguồn: scripts/grammar-gen/out/*.json; tạo lại bằng build-curriculum-migration.py.
-- Nội dung AI hỗ trợ biên soạn, cần tiếp tục giám định sư phạm theo từng bài.
begin;
-- 01. personal-pronouns
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('personal-pronouns', 'Personal Pronouns', 'Đại từ nhân xưng', 'beginner', 1)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Đại từ nhân xưng', '**Đại từ nhân xưng** (Personal Pronouns) như *I, you, he, she, it, we, they* dùng để thay thế cho danh từ chỉ người hoặc vật đã được đề cập hoặc người nghe đã biết, giúp tránh lặp lại. Chúng thay đổi hình thức tùy thuộc vào việc chúng làm chủ ngữ hay tân ngữ trong câu.', $grammar$[{"en":"They live near us.","vi":"Họ sống gần chúng tôi.","note":"They là chủ ngữ; us sau giới từ.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"live","start":5,"end":9,"role":"verb"},{"word":"near","start":10,"end":14,"role":"preposition"},{"word":"us","start":15,"end":17,"role":"pronoun"}]},{"en":"Can you help me?","vi":"Bạn có thể giúp tôi không?","note":"you là chủ ngữ; me là tân ngữ.","annotations":[{"word":"Can","start":0,"end":3,"role":"modal"},{"word":"you","start":4,"end":7,"role":"pronoun"},{"word":"help","start":8,"end":12,"role":"verb"},{"word":"me","start":13,"end":15,"role":"pronoun"}]},{"en":"He sent her an email.","vi":"Anh ấy gửi cho cô ấy một email.","note":"He làm chủ ngữ; her làm tân ngữ.","annotations":[{"word":"He","start":0,"end":2,"role":"pronoun"},{"word":"sent","start":3,"end":7,"role":"verb"},{"word":"her","start":8,"end":11,"role":"pronoun"},{"word":"an","start":12,"end":14,"role":"article"},{"word":"email","start":15,"end":20,"role":"noun"}]},{"en":"The book is interesting. It has ten chapters.","vi":"Cuốn sách thú vị. Nó có mười chương.","note":"It thay cho the book.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"book","start":4,"end":8,"role":"noun"},{"word":"is","start":9,"end":11,"role":"auxiliary"},{"word":"interesting","start":12,"end":23,"role":"adjective"},{"word":"It","start":25,"end":27,"role":"pronoun"},{"word":"has","start":28,"end":31,"role":"verb"},{"word":"ten","start":32,"end":35,"role":"other"},{"word":"chapters","start":36,"end":44,"role":"noun"}]},{"en":"Lan and I are classmates. We study together.","vi":"Lan và tôi là bạn cùng lớp. Chúng tôi học cùng nhau.","note":"We thay cho Lan and I.","annotations":[{"word":"Lan","start":0,"end":3,"role":"noun"},{"word":"and","start":4,"end":7,"role":"conjunction"},{"word":"I","start":8,"end":9,"role":"pronoun"},{"word":"are","start":10,"end":13,"role":"auxiliary"},{"word":"classmates","start":14,"end":24,"role":"noun"},{"word":"We","start":26,"end":28,"role":"pronoun"},{"word":"study","start":29,"end":34,"role":"verb"},{"word":"together","start":35,"end":43,"role":"adverb"}]},{"en":"Please wait for them.","vi":"Vui lòng đợi họ.","note":"Sau giới từ for dùng them.","annotations":[{"word":"Please","start":0,"end":6,"role":"adverb"},{"word":"wait","start":7,"end":11,"role":"verb"},{"word":"for","start":12,"end":15,"role":"preposition"},{"word":"them","start":16,"end":20,"role":"pronoun"}]}]$grammar$::jsonb, $grammar${"definition":"**Đại từ nhân xưng** (Personal Pronouns) như *I, you, he, she, it, we, they* dùng để thay thế cho danh từ chỉ người hoặc vật đã được đề cập hoặc người nghe đã biết, giúp tránh lặp lại. Chúng thay đổi hình thức tùy thuộc vào việc chúng làm chủ ngữ hay tân ngữ trong câu.","usage":[{"icon":"👤","label":"Làm chủ ngữ của câu","en":"She works here.","vi":"Cô ấy làm việc ở đây."},{"icon":"🎯","label":"Làm tân ngữ của động từ","en":"I called him yesterday.","vi":"Tôi đã gọi cho anh ấy hôm qua."},{"icon":"🔗","label":"Đứng sau giới từ","en":"This gift is for them.","vi":"Món quà này dành cho họ."},{"icon":"🔁","label":"Thay danh từ để tránh lặp","en":"Mai has a cat. It is white.","vi":"Mai có một con mèo. Nó màu trắng."}],"formula":{"rows":[{"form":"Chủ ngữ","structure":"I / you / he / she / it / we / they + V","example":"They know me."},{"form":"Tân ngữ","structure":"V + me / you / him / her / it / us / them","example":"I know them."},{"form":"Sau giới từ","structure":"preposition + object pronoun","example":"with her, for us"}],"note":"Đọc cấu trúc cùng ví dụ và luôn kiểm tra vai trò, số lượng hoặc dạng động từ theo từng trường hợp."},"rules":[{"case":"Nam / nữ","rule":"he-him / she-her","example":"He called her."},{"case":"Vật hoặc con vật","rule":"it ở cả chủ ngữ và tân ngữ","example":"It is new. I bought it."},{"case":"Người nói + người khác","rule":"we-us","example":"We invited them."},{"case":"Nhiều người/vật khác","rule":"they-them","example":"They helped us."}],"signals":["trước động từ chính","sau động từ","sau for/to/with/about","thay danh từ đã nhắc"],"examples":[{"en":"They live near us.","vi":"Họ sống gần chúng tôi.","note":"They là chủ ngữ; us sau giới từ.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"live","start":5,"end":9,"role":"verb"},{"word":"near","start":10,"end":14,"role":"preposition"},{"word":"us","start":15,"end":17,"role":"pronoun"}]},{"en":"Can you help me?","vi":"Bạn có thể giúp tôi không?","note":"you là chủ ngữ; me là tân ngữ.","annotations":[{"word":"Can","start":0,"end":3,"role":"modal"},{"word":"you","start":4,"end":7,"role":"pronoun"},{"word":"help","start":8,"end":12,"role":"verb"},{"word":"me","start":13,"end":15,"role":"pronoun"}]},{"en":"He sent her an email.","vi":"Anh ấy gửi cho cô ấy một email.","note":"He làm chủ ngữ; her làm tân ngữ.","annotations":[{"word":"He","start":0,"end":2,"role":"pronoun"},{"word":"sent","start":3,"end":7,"role":"verb"},{"word":"her","start":8,"end":11,"role":"pronoun"},{"word":"an","start":12,"end":14,"role":"article"},{"word":"email","start":15,"end":20,"role":"noun"}]},{"en":"The book is interesting. It has ten chapters.","vi":"Cuốn sách thú vị. Nó có mười chương.","note":"It thay cho the book.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"book","start":4,"end":8,"role":"noun"},{"word":"is","start":9,"end":11,"role":"auxiliary"},{"word":"interesting","start":12,"end":23,"role":"adjective"},{"word":"It","start":25,"end":27,"role":"pronoun"},{"word":"has","start":28,"end":31,"role":"verb"},{"word":"ten","start":32,"end":35,"role":"other"},{"word":"chapters","start":36,"end":44,"role":"noun"}]},{"en":"Lan and I are classmates. We study together.","vi":"Lan và tôi là bạn cùng lớp. Chúng tôi học cùng nhau.","note":"We thay cho Lan and I.","annotations":[{"word":"Lan","start":0,"end":3,"role":"noun"},{"word":"and","start":4,"end":7,"role":"conjunction"},{"word":"I","start":8,"end":9,"role":"pronoun"},{"word":"are","start":10,"end":13,"role":"auxiliary"},{"word":"classmates","start":14,"end":24,"role":"noun"},{"word":"We","start":26,"end":28,"role":"pronoun"},{"word":"study","start":29,"end":34,"role":"verb"},{"word":"together","start":35,"end":43,"role":"adverb"}]},{"en":"Please wait for them.","vi":"Vui lòng đợi họ.","note":"Sau giới từ for dùng them.","annotations":[{"word":"Please","start":0,"end":6,"role":"adverb"},{"word":"wait","start":7,"end":11,"role":"verb"},{"word":"for","start":12,"end":15,"role":"preposition"},{"word":"them","start":16,"end":20,"role":"pronoun"}]}],"mistakes":[{"wrong":"Me am tired.","right":"I am tired.","why":"Vị trí chủ ngữ phải dùng I."},{"wrong":"She called he.","right":"She called him.","why":"Sau động từ called cần đại từ tân ngữ him."},{"wrong":"This is for they.","right":"This is for them.","why":"Sau giới từ for dùng đại từ tân ngữ."},{"wrong":"Me and him went to the party.","right":"He and I went to the party.","why":"Vị trí CHỦ NGỮ dùng đại từ chủ ngữ (he, I) — me/him chỉ làm tân ngữ."},{"wrong":"Her is my best friend.","right":"She is my best friend.","why":"Chủ ngữ câu phải là SHE; her là dạng tân ngữ/sở hữu."}],"tips":"**Mẹo:** Đứng trước động từ chia thì → chọn đại từ chủ ngữ. Đứng sau động từ hoặc giới từ → chọn đại từ tân ngữ. Học theo cặp: I–me, he–him, she–her, we–us, they–them.","comparison":"**subject vs object pronouns:** *She likes him*: she thực hiện hành động, him nhận hành động. **it vs they:** it thay một vật; they thay nhiều người hoặc vật.","timeline":null}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"Tom is my friend. ___ lives nearby.","opts":["He","Him","His"],"answer":"He","fb":"Vị trí chủ ngữ trước lives cần He."},{"type":"mcq","q":"I see Anna every day. I see ___ at school.","opts":["she","her","hers"],"answer":"her","fb":"Sau động từ see cần tân ngữ her."},{"type":"mcq","q":"Our teacher gave ___ extra homework.","opts":["we","us","our"],"answer":"us","fb":"Sau gave cần tân ngữ us."},{"type":"fill","q":"My parents are kind. ___ help me a lot.","answer":["they"],"fb":"Thay my parents ở vị trí chủ ngữ bằng they."},{"type":"fill","q":"Please listen to ___. (I)","answer":["me"],"fb":"Sau giới từ to dùng me."},{"type":"fill","q":"I like these shoes, so I bought ___.","answer":["them"],"fb":"Thay shoes số nhiều ở vị trí tân ngữ bằng them."},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"Me am tired.\"","answer":false,"fb":"SAI. Vị trí chủ ngữ phải dùng I. Câu đúng: \"I am tired.\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"She called he.\"","answer":false,"fb":"SAI. Sau động từ called cần đại từ tân ngữ him. Câu đúng: \"She called him.\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"This is for they.\"","answer":false,"fb":"SAI. Sau giới từ for dùng đại từ tân ngữ. Câu đúng: \"This is for them.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["They live near us.","Me am tired.","The book is interesting. It has ten chapters."],"answer":"Me am tired.","fb":"Vị trí chủ ngữ phải dùng I. Câu đúng: \"I am tired.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["Can you help me?","She called he.","Lan and I are classmates. We study together."],"answer":"She called he.","fb":"Sau động từ called cần đại từ tân ngữ him. Câu đúng: \"She called him.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["He sent her an email.","This is for they.","Please wait for them."],"answer":"This is for they.","fb":"Sau giới từ for dùng đại từ tân ngữ. Câu đúng: \"This is for them.\""}]$grammar$::jsonb, 'ai-golden', 1
from public.grammar_topics t where t.slug = 'personal-pronouns'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 02. verb-to-be
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('verb-to-be', 'Verb to be (am / is / are)', 'Động từ to be (am / is / are)', 'beginner', 2)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Động từ to be (am / is / are)', 'Động từ **to be** ở hiện tại có ba dạng: **am, is, are**. Ta dùng to be để nói ai đó hoặc vật gì đó **là ai, như thế nào, ở đâu**. To be tự tạo câu phủ định và câu hỏi, không cần dùng do hoặc does.', $grammar$[{"en":"I am a student.","vi":"Tôi là học sinh.","note":"Chủ ngữ I luôn đi với am.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"am","start":2,"end":4,"role":"verb"},{"word":"a","start":5,"end":6,"role":"article"},{"word":"student","start":7,"end":14,"role":"noun"}]},{"en":"She is very kind.","vi":"Cô ấy rất tốt bụng.","note":"She đi với is; kind miêu tả tính cách.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"is","start":4,"end":6,"role":"verb"},{"word":"very","start":7,"end":11,"role":"adverb"},{"word":"kind","start":12,"end":16,"role":"adjective"}]},{"en":"We are not tired.","vi":"Chúng tôi không mệt.","note":"Thêm not sau are để tạo câu phủ định.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"are","start":3,"end":6,"role":"verb"},{"word":"not","start":7,"end":10,"role":"adverb"},{"word":"tired","start":11,"end":16,"role":"adjective"}]},{"en":"Is he at home?","vi":"Anh ấy có ở nhà không?","note":"Đưa is lên trước he để tạo câu hỏi.","annotations":[{"word":"Is","start":0,"end":2,"role":"verb"},{"word":"he","start":3,"end":5,"role":"pronoun"},{"word":"at","start":6,"end":8,"role":"preposition"},{"word":"home","start":9,"end":13,"role":"noun"}]},{"en":"Are they your friends?","vi":"Họ có phải là bạn của bạn không?","note":"They đi với are.","annotations":[{"word":"Are","start":0,"end":3,"role":"verb"},{"word":"they","start":4,"end":8,"role":"pronoun"},{"word":"your","start":9,"end":13,"role":"determiner"},{"word":"friends","start":14,"end":21,"role":"noun"}]},{"en":"My parents are teachers.","vi":"Bố mẹ tôi là giáo viên.","note":"Parents là số nhiều nên dùng are.","annotations":[{"word":"My","start":0,"end":2,"role":"determiner"},{"word":"parents","start":3,"end":10,"role":"noun"},{"word":"are","start":11,"end":14,"role":"verb"},{"word":"teachers","start":15,"end":23,"role":"noun"}]},{"en":"Where are you from?","vi":"Bạn đến từ đâu?","note":"Câu hỏi Wh- đặt where trước are.","annotations":[{"word":"Where","start":0,"end":5,"role":"adverb"},{"word":"are","start":6,"end":9,"role":"verb"},{"word":"you","start":10,"end":13,"role":"pronoun"},{"word":"from","start":14,"end":18,"role":"preposition"}]},{"en":"It isn't cold today.","vi":"Hôm nay trời không lạnh.","note":"Isn't là dạng rút gọn của is not.","annotations":[{"word":"It","start":0,"end":2,"role":"pronoun"},{"word":"isn't","start":3,"end":8,"role":"verb"},{"word":"cold","start":9,"end":13,"role":"adjective"},{"word":"today","start":14,"end":19,"role":"adverb"}]}]$grammar$::jsonb, $grammar${"definition":"Động từ **to be** ở hiện tại có ba dạng: **am, is, are**. Ta dùng to be để nói ai đó hoặc vật gì đó **là ai, như thế nào, ở đâu**. To be tự tạo câu phủ định và câu hỏi, không cần dùng do hoặc does.","usage":[{"icon":"👤","label":"Giới thiệu tên, nghề nghiệp hoặc vai trò","en":"I am a student.","vi":"Tôi là học sinh."},{"icon":"😊","label":"Miêu tả đặc điểm hoặc cảm xúc","en":"She is happy.","vi":"Cô ấy vui."},{"icon":"📍","label":"Nói vị trí","en":"The keys are on the table.","vi":"Chìa khóa ở trên bàn."},{"icon":"🎂","label":"Nói tuổi, quốc tịch hoặc nguồn gốc","en":"He is ten years old.","vi":"Cậu ấy mười tuổi."}],"formula":{"rows":[{"form":"(+) Khẳng định","singular":"I am · He/She/It is","plural":"You/We/They are"},{"form":"(−) Phủ định","singular":"I am not · He/She/It is not","plural":"You/We/They are not"},{"form":"(?) Nghi vấn","singular":"Am I...? · Is he/she/it...?","plural":"Are you/we/they...?"}],"note":"Để hỏi, đưa am/is/are lên trước chủ ngữ. Để phủ định, thêm not ngay sau am/is/are."},"rules":[{"case":"Chủ ngữ I","rule":"dùng am","example":"I am ready."},{"case":"He, She, It hoặc một người/vật","rule":"dùng is","example":"Lan is kind. The cat is small."},{"case":"You, We, They hoặc nhiều người/vật","rule":"dùng are","example":"You are nice. The books are new."},{"case":"Dạng rút gọn","rule":"I'm · he's/she's/it's · you're/we're/they're","example":"I'm fine. They're at home."}],"signals":["am","is","are","am not","isn't","aren't"],"examples":[{"en":"I am a student.","vi":"Tôi là học sinh.","note":"Chủ ngữ I luôn đi với am.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"am","start":2,"end":4,"role":"verb"},{"word":"a","start":5,"end":6,"role":"article"},{"word":"student","start":7,"end":14,"role":"noun"}]},{"en":"She is very kind.","vi":"Cô ấy rất tốt bụng.","note":"She đi với is; kind miêu tả tính cách.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"is","start":4,"end":6,"role":"verb"},{"word":"very","start":7,"end":11,"role":"adverb"},{"word":"kind","start":12,"end":16,"role":"adjective"}]},{"en":"We are not tired.","vi":"Chúng tôi không mệt.","note":"Thêm not sau are để tạo câu phủ định.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"are","start":3,"end":6,"role":"verb"},{"word":"not","start":7,"end":10,"role":"adverb"},{"word":"tired","start":11,"end":16,"role":"adjective"}]},{"en":"Is he at home?","vi":"Anh ấy có ở nhà không?","note":"Đưa is lên trước he để tạo câu hỏi.","annotations":[{"word":"Is","start":0,"end":2,"role":"verb"},{"word":"he","start":3,"end":5,"role":"pronoun"},{"word":"at","start":6,"end":8,"role":"preposition"},{"word":"home","start":9,"end":13,"role":"noun"}]},{"en":"Are they your friends?","vi":"Họ có phải là bạn của bạn không?","note":"They đi với are.","annotations":[{"word":"Are","start":0,"end":3,"role":"verb"},{"word":"they","start":4,"end":8,"role":"pronoun"},{"word":"your","start":9,"end":13,"role":"determiner"},{"word":"friends","start":14,"end":21,"role":"noun"}]},{"en":"My parents are teachers.","vi":"Bố mẹ tôi là giáo viên.","note":"Parents là số nhiều nên dùng are.","annotations":[{"word":"My","start":0,"end":2,"role":"determiner"},{"word":"parents","start":3,"end":10,"role":"noun"},{"word":"are","start":11,"end":14,"role":"verb"},{"word":"teachers","start":15,"end":23,"role":"noun"}]},{"en":"Where are you from?","vi":"Bạn đến từ đâu?","note":"Câu hỏi Wh- đặt where trước are.","annotations":[{"word":"Where","start":0,"end":5,"role":"adverb"},{"word":"are","start":6,"end":9,"role":"verb"},{"word":"you","start":10,"end":13,"role":"pronoun"},{"word":"from","start":14,"end":18,"role":"preposition"}]},{"en":"It isn't cold today.","vi":"Hôm nay trời không lạnh.","note":"Isn't là dạng rút gọn của is not.","annotations":[{"word":"It","start":0,"end":2,"role":"pronoun"},{"word":"isn't","start":3,"end":8,"role":"verb"},{"word":"cold","start":9,"end":13,"role":"adjective"},{"word":"today","start":14,"end":19,"role":"adverb"}]}],"mistakes":[{"wrong":"I is a student.","right":"I am a student.","why":"Chủ ngữ I chỉ đi với am."},{"wrong":"They is happy.","right":"They are happy.","why":"They là chủ ngữ số nhiều nên dùng are."},{"wrong":"She not is tired.","right":"She is not tired.","why":"Not phải đứng sau am/is/are."},{"wrong":"Do you are ready?","right":"Are you ready?","why":"Câu hỏi với to be không dùng do; chỉ đưa are lên trước chủ ngữ."}],"tips":"**Mẹo nhớ:** **I am**, **một người/vật is**, **nhiều người/vật are**. Hỏi thì đảo to be lên đầu; phủ định thì thêm **not** sau to be.","comparison":"**To be và động từ thường:** To be tự tạo câu hỏi/phủ định (*Is she happy? She isn't happy.*). Động từ thường cần do/does (*Does she work? She doesn't work.*). Không nói *Does she be happy?*.","timeline":null}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"Choose the correct **to be**: I ___ from Vietnam.","options":["am","is","are","be"],"correct_answer":"am","explanation":"Chủ ngữ I luôn đi với am. Is dùng với he/she/it hoặc một người/vật; are dùng với you/we/they hoặc số nhiều; be không dùng trực tiếp ở hiện tại đơn như câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **to be**: She ___ my teacher.","options":["is","am","are","be"],"correct_answer":"is","explanation":"She là ngôi thứ ba số ít nên dùng is. Am chỉ dùng với I; are dùng với you/we/they hoặc danh từ số nhiều; be không phù hợp trong câu khẳng định hiện tại đơn này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question form**: ___ you a student?","options":["Are","Is","Am","Be"],"correct_answer":"Are","explanation":"Với chủ ngữ you, câu hỏi dùng Are đứng trước chủ ngữ. Is dùng với he/she/it; am dùng với I; be không dùng làm trợ động từ trực tiếp ở đây.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb form**: My parents ___ at home.","options":["are","is","am","be"],"correct_answer":"are","explanation":"My parents là danh từ số nhiều nên dùng are. Is dùng cho số ít; am chỉ dùng với I; be không đúng trong cấu trúc này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **negative form**: The door ___ not open.","options":["is","are","am","be"],"correct_answer":"is","explanation":"The door là một vật số ít nên dùng is not. Are not dùng cho số nhiều hoặc you/we/they; am not chỉ đi với I; be not không đúng ở hiện tại đơn này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **short answer**: Are they ready? Yes, they ___.","options":["are","is","am","be"],"correct_answer":"are","explanation":"Câu hỏi bắt đầu bằng Are they nên câu trả lời ngắn khẳng định là they are. Is và am không hòa hợp với they; be không dùng trong short answer này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **contraction**: She is my sister. = ___ my sister.","options":["She's","She're","She'm","She"],"correct_answer":"She's","explanation":"She is có dạng rút gọn là She's. She're và She'm sai vì she không đi với are hoặc am; She thiếu động từ to be.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **to be**: This book ___ interesting.","options":["is","are","am","be"],"correct_answer":"is","explanation":"This book là một vật số ít nên dùng is. Are dùng cho số nhiều; am chỉ dùng với I; be không đúng trong câu hiện tại đơn này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **subject agreement**: You and Mai ___ classmates.","options":["are","is","am","be"],"correct_answer":"are","explanation":"You and Mai chỉ hai người nên là chủ ngữ số nhiều, dùng are. Is dùng cho số ít; am chỉ dùng với I; be không phù hợp ở đây.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **verb form**: I ___ eleven years old.","options":["am","is","are","be"],"correct_answer":"am","explanation":"Khi nói tuổi với chủ ngữ I, ta dùng I am. Is, are và be không hòa hợp với I trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **to be**: The cats ___ under the chair.","options":["are","is","am","be"],"correct_answer":"are","explanation":"The cats là danh từ số nhiều nên dùng are. Is dùng với một con mèo hoặc một vật/người số ít; am chỉ dùng với I; be không đúng ở đây.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **negative form**: We ___ not tired.","options":["are","is","am","be"],"correct_answer":"are","explanation":"We đi với are, nên câu đúng là We are not tired. Is dùng với he/she/it; am dùng với I; be không dùng trực tiếp sau we trong câu hiện tại đơn này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **question form**: ___ he your brother?","options":["Is","Are","Am","Be"],"correct_answer":"Is","explanation":"He là ngôi thứ ba số ít nên câu hỏi dùng Is he. Are dùng với you/we/they hoặc số nhiều; am dùng với I; be không đúng trong câu hỏi này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb form**: These pencils ___ new.","options":["are","is","am","be"],"correct_answer":"are","explanation":"These pencils là danh từ số nhiều nên dùng are. Is dùng cho số ít; am chỉ dùng với I; be không phù hợp trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **to be**: It ___ a sunny day.","options":["is","are","am","be"],"correct_answer":"is","explanation":"It là chủ ngữ số ít nên dùng is. Are dùng cho số nhiều hoặc you/we/they; am chỉ dùng với I; be không đúng ở hiện tại đơn này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **short answer**: Is your mother a doctor? No, she ___.","options":["isn't","aren't","am not","be not"],"correct_answer":"isn't","explanation":"Câu hỏi dùng Is your mother, nên câu trả lời phủ định ngắn là she isn't. Aren't dùng với are; am not dùng với I; be not không tự nhiên trong cấu trúc này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **contraction**: They are in the classroom. = ___ in the classroom.","options":["They're","They's","They'm","They is"],"correct_answer":"They're","explanation":"They are được rút gọn thành They're. They's, They'm và They is đều sai vì they phải đi với are.","difficulty":2},{"type":"error_correction","question":"Find the error: I is happy today.","options":["I","is","happy","today"],"correct_answer":"is","explanation":"Lỗi là is vì chủ ngữ I phải đi với am: I am happy today. Các từ I, happy và today không sai trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: They is in the park.","options":["They","is","in","the park"],"correct_answer":"is","explanation":"They phải đi với are, nên câu đúng là They are in the park. They, in và the park không phải lỗi ngữ pháp ở đây.","difficulty":1},{"type":"error_correction","question":"Find the error: She are very kind.","options":["She","are","very","kind"],"correct_answer":"are","explanation":"She là số ít nên phải dùng is: She is very kind. She, very và kind đều phù hợp trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: We am classmates.","options":["We","am","classmates","."],"correct_answer":"am","explanation":"We phải đi với are, nên câu đúng là We are classmates. We và classmates đúng; dấu chấm không phải lỗi ngữ pháp cần sửa.","difficulty":1},{"type":"error_correction","question":"Find the error: Are she your friend?","options":["Are","she","your","friend"],"correct_answer":"Are","explanation":"Với she, câu hỏi phải bắt đầu bằng Is: Is she your friend? She, your và friend không sai trong câu hỏi này.","difficulty":2},{"type":"error_correction","question":"Find the error: My bags is heavy.","options":["My bags","is","heavy","."],"correct_answer":"is","explanation":"My bags là số nhiều nên phải dùng are: My bags are heavy. My bags và heavy đúng; dấu chấm không phải lỗi cần sửa.","difficulty":2},{"type":"error_correction","question":"Find the error: You is not late.","options":["You","is not","late","."],"correct_answer":"is not","explanation":"You phải đi với are, nên dạng phủ định đúng là are not: You are not late. You và late không sai; dấu chấm không phải lỗi ngữ pháp.","difficulty":2},{"type":"error_correction","question":"Find the error: He's are my cousin.","options":["He's","are","my","cousin"],"correct_answer":"are","explanation":"He's đã có nghĩa là He is, nên không được thêm are sau đó. Câu đúng là He's my cousin hoặc He is my cousin; my và cousin đúng trong câu.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **to be**: I ___ a little hungry.","options":["am","is","are","be"],"correct_answer":"am","explanation":"Với chủ ngữ I, ta dùng am. Is dùng cho he/she/it hoặc một danh từ số ít; are dùng cho you/we/they hoặc số nhiều; be không dùng trực tiếp trong câu hiện tại đơn này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb form**: Tom ___ in the kitchen.","options":["is","am","are","be"],"correct_answer":"is","explanation":"Tom là một người số ít, tương đương he, nên dùng is. Am chỉ đi với I, are đi với chủ ngữ số nhiều hoặc you, còn be không phù hợp ở hiện tại đơn.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **agreement**: The windows ___ clean.","options":["are","am","is","be"],"correct_answer":"are","explanation":"The windows là danh từ số nhiều nên dùng are. Is dùng cho danh từ số ít, am chỉ dùng với I, be không phải dạng chia đúng trong câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question form**: ___ your name Anna?","options":["Is","Are","Am","Be"],"correct_answer":"Is","explanation":"Your name là danh từ số ít, nên câu hỏi dùng Is ở đầu câu. Are dùng với số nhiều/you, Am dùng với I, Be không dùng để bắt đầu câu hỏi hiện tại đơn như vậy.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **negative form**: His shoes ___ not blue.","options":["are","is","am","be"],"correct_answer":"are","explanation":"His shoes là danh từ số nhiều nên dùng are not. Is not dùng cho số ít, am not chỉ đi với I, còn be not không đúng ở hiện tại đơn.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **short answer**: Is the baby asleep? Yes, it ___.","options":["is","are","am","be"],"correct_answer":"is","explanation":"The baby có thể thay bằng it, nên câu trả lời ngắn là Yes, it is. Are và am không hợp với it, còn be không dùng trong short answer này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **contraction**: We are on the bus. = ___ on the bus.","options":["We're","They're","You're","I'm"],"correct_answer":"We're","explanation":"We are rút gọn thành We're. They're là they are, You're là you are, còn I'm là I am nên không đúng nghĩa chủ ngữ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **to be**: These oranges ___ sweet.","options":["are","is","am","be"],"correct_answer":"are","explanation":"These oranges là nhiều quả cam, nên dùng are. Is dùng cho một vật/người số ít, am chỉ dùng với I, be không phải dạng chia ở đây.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **word order**: ___ cold today?","options":["Is it","It is","Are it","Am it"],"correct_answer":"Is it","explanation":"Câu hỏi với it dùng cấu trúc Is + it + tính từ. It is là câu khẳng định, còn Are it và Am it sai vì it đi với is.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **to be**: My phone ___ on the desk.","options":["is","am","are","be"],"correct_answer":"is","explanation":"My phone là một vật số ít nên dùng is. Am chỉ dùng với I, are dùng cho số nhiều hoặc you/we/they, còn be không phù hợp trong câu hiện tại đơn.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb form**: You ___ my best friend.","options":["are","am","is","be"],"correct_answer":"are","explanation":"Chủ ngữ you luôn đi với are trong hiện tại đơn. Am chỉ đi với I, is đi với he/she/it hoặc số ít, be không đúng dạng chia.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **negative form**: I ___ not afraid.","options":["am","is","are","be"],"correct_answer":"am","explanation":"Với I ở câu phủ định, ta dùng am not. Is not và are not dùng cho chủ ngữ khác, còn be not không phải cách chia đúng ở đây.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **question form**: ___ the girls in the garden?","options":["Are","Is","Am","Be"],"correct_answer":"Are","explanation":"The girls là danh từ số nhiều nên câu hỏi bắt đầu bằng Are. Is dùng cho số ít, Am dùng với I, Be không dùng trực tiếp trong cấu trúc này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **short answer**: Are your socks white? No, they ___.","options":["aren't","isn't","am not","be not"],"correct_answer":"aren't","explanation":"Your socks là số nhiều, thay bằng they, nên phủ định ngắn là they aren't. Isn't dùng cho số ít, am not dùng với I, be not không đúng trong câu này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **contraction**: It is a red apple. = ___ a red apple.","options":["It's","He's","She's","They're"],"correct_answer":"It's","explanation":"It is rút gọn thành It's. He's là he is, She's là she is, They're là they are nên không thay thế được it is.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **to be**: Ben and I ___ neighbors.","options":["are","am","is","be"],"correct_answer":"are","explanation":"Ben and I nghĩa là chúng tôi, tương đương we, nên dùng are. Am chỉ đi với I đứng một mình, is dùng cho số ít, be không phù hợp.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **verb form**: The soup ___ hot.","options":["is","are","am","be"],"correct_answer":"is","explanation":"The soup là danh từ không đếm được và được xem như số ít, nên dùng is. Are dùng cho số nhiều, am dùng với I, be không đúng dạng chia.","difficulty":2},{"type":"error_correction","question":"Find the error: He am seven years old.","options":["He","am","seven years old","old"],"correct_answer":"am","explanation":"He phải đi với is, nên lỗi là am. He là chủ ngữ đúng, seven years old là cụm nói tuổi đúng, và old không sai trong cụm này.","difficulty":1},{"type":"error_correction","question":"Find the error: The flowers is beautiful.","options":["The flowers","is","beautiful","flowers"],"correct_answer":"is","explanation":"The flowers là danh từ số nhiều nên phải dùng are. The flowers và flowers đúng về nghĩa số nhiều, beautiful là tính từ đúng sau to be.","difficulty":1},{"type":"error_correction","question":"Find the error: Am you okay now?","options":["Am","you","okay","now"],"correct_answer":"Am","explanation":"Với chủ ngữ you, câu hỏi phải bắt đầu bằng Are, không phải Am. You là chủ ngữ đúng, okay là tính từ đúng, now là trạng từ thời gian đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: I are at the supermarket.","options":["I","are","at","the supermarket"],"correct_answer":"are","explanation":"I luôn đi với am, nên are là lỗi. I là chủ ngữ đúng, at chỉ vị trí đúng, và the supermarket là địa điểm đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: The rice are in the bowl.","options":["The rice","are","in","the bowl"],"correct_answer":"are","explanation":"Rice là danh từ không đếm được, thường xem như số ít, nên dùng is. The rice là chủ ngữ đúng, in và the bowl tạo cụm vị trí đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: Your eyes is green.","options":["Your eyes","is","green","eyes"],"correct_answer":"is","explanation":"Your eyes là số nhiều nên phải dùng are. Your eyes là chủ ngữ đúng, green là tính từ đúng, và eyes thể hiện số nhiều đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: They am not from Korea.","options":["They","am not","from","Korea"],"correct_answer":"am not","explanation":"They phải đi với are not, nên am not là lỗi. They là chủ ngữ đúng, from dùng để nói nguồn gốc đúng, và Korea là tên quốc gia đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: Mia and Leo is twins.","options":["Mia and Leo","is","twins","Leo"],"correct_answer":"is","explanation":"Mia and Leo là hai người, tương đương they, nên dùng are. Mia and Leo là chủ ngữ số nhiều đúng, twins là danh từ số nhiều đúng, Leo không sai.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **verb form**: Sarah ___ my sister.","options":["is","am","are","be"],"correct_answer":"is","explanation":"Sarah là một người số ít nên dùng is. Am chỉ đi với I, are đi với chủ ngữ số nhiều hoặc you, còn be không phù hợp trong câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **agreement**: The chairs ___ in the classroom.","options":["are","is","am","be"],"correct_answer":"are","explanation":"The chairs là danh từ số nhiều nên dùng are. Is dùng cho số ít, am dùng với I, be không phải dạng chia đúng ở hiện tại đơn.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question form**: ___ your father a doctor?","options":["Is","Are","Am","Be"],"correct_answer":"Is","explanation":"Your father là một người số ít nên câu hỏi bắt đầu bằng Is. Are dùng với you/we/they hoặc số nhiều; Am chỉ dùng với I; Be không đứng đầu câu hỏi kiểu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **short answer**: Are the children noisy? Yes, they ___.","options":["are","is","am","be"],"correct_answer":"are","explanation":"Câu hỏi dùng Are với the children, nên câu trả lời ngắn là Yes, they are. Is và am không khớp với they; be không phải dạng trả lời đúng.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **contraction**: You are early. = ___ early.","options":["You're","I'm","She's","They're"],"correct_answer":"You're","explanation":"You are rút gọn thành You're. I'm là I am, She's là She is, They're là They are nên không đúng với chủ ngữ you.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **word order**: ___ the tickets on the table?","options":["Are","Is","Am","Be"],"correct_answer":"Are","explanation":"The tickets là danh từ số nhiều nên câu hỏi dùng Are. Is dùng cho số ít, Am dùng với I, Be không dùng để mở câu hỏi hiện tại đơn như vậy.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **to be**: This cake ___ delicious.","options":["is","are","am","be"],"correct_answer":"is","explanation":"This cake là một vật số ít nên dùng is. Are dùng cho số nhiều, am dùng với I, còn be không được chia theo chủ ngữ.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **to be**: We ___ ready for class.","options":["are","is","am","be"],"correct_answer":"are","explanation":"We luôn đi với are ở hiện tại. Is dùng với he/she/it hoặc danh từ số ít, am dùng với I, be không phải dạng chia đúng trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb form**: The dog ___ under the bed.","options":["is","are","am","be"],"correct_answer":"is","explanation":"The dog là một con vật số ít nên dùng is. Are dùng cho số nhiều, am dùng với I, be không phù hợp sau chủ ngữ này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **negative form**: They ___ not at school today.","options":["are","is","am","be"],"correct_answer":"are","explanation":"They đi với are, nên phủ định là are not. Is not dùng với số ít, am not dùng với I, be not không đúng trong câu hiện tại đơn này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **question form**: ___ I late for the meeting?","options":["Am","Is","Are","Be"],"correct_answer":"Am","explanation":"Trong câu hỏi với chủ ngữ I, ta dùng Am I. Is và Are không đi trực tiếp với I trong cấu trúc này; Be không đúng dạng.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **short answer**: Is your room clean? No, it ___.","options":["isn't","aren't","am not","be not"],"correct_answer":"isn't","explanation":"Your room là it, nên câu trả lời phủ định ngắn là No, it isn't. Aren't dùng với are, am not dùng với I, be not không tự nhiên và không đúng ở mức này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **contraction**: They are my neighbors. = ___ my neighbors.","options":["They're","We're","You're","He's"],"correct_answer":"They're","explanation":"They are rút gọn thành They're. We're là We are, You're là You are, He's là He is nên không đúng chủ ngữ.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **agreement**: Anna and Mark ___ in the park.","options":["are","is","am","be"],"correct_answer":"are","explanation":"Anna and Mark là hai người, tức chủ ngữ số nhiều, nên dùng are. Is dùng cho một người/vật số ít, am dùng với I, be không chia đúng.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **to be**: My mother ___ very kind.","options":["is","are","am","be"],"correct_answer":"is","explanation":"My mother là một người số ít nên dùng is. Are dùng với số nhiều hoặc you; am chỉ dùng với I; be không đúng trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: The students is in the library.","options":["The students","is","in","the library"],"correct_answer":"is","explanation":"The students là số nhiều nên phải dùng are, không dùng is. Các phần còn lại đúng về nghĩa và vị trí trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: Is they your classmates?","options":["Is","they","your","classmates"],"correct_answer":"Is","explanation":"They phải đi với are trong câu hỏi: Are they your classmates? Các từ they, your, classmates đều phù hợp trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: I is twelve years old.","options":["I","is","twelve","years old"],"correct_answer":"is","explanation":"Chủ ngữ I phải đi với am, nên câu đúng là I am twelve years old. Các phần khác không sai trong câu nói tuổi.","difficulty":1},{"type":"error_correction","question":"Find the error: Her brothers am tall.","options":["Her brothers","am","tall","Her"],"correct_answer":"am","explanation":"Her brothers là số nhiều nên phải dùng are, không dùng am. Tall là tính từ đúng, và Her brothers là chủ ngữ phù hợp.","difficulty":1},{"type":"error_correction","question":"Find the error: You am welcome here.","options":["You","am","welcome","here"],"correct_answer":"am","explanation":"You luôn đi với are ở hiện tại, nên câu đúng là You are welcome here. Các từ còn lại đúng về nghĩa và trật tự.","difficulty":1},{"type":"error_correction","question":"Find the error: The milk are cold.","options":["The milk","are","cold","milk"],"correct_answer":"are","explanation":"The milk được xem là danh từ không đếm được số ít nên dùng is. Cold là tính từ đúng, và The milk là chủ ngữ đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: Are it your pencil?","options":["Are","it","your","pencil"],"correct_answer":"Are","explanation":"It phải đi với is trong câu hỏi: Is it your pencil? Các từ it, your, pencil đều phù hợp với nghĩa câu.","difficulty":1},{"type":"error_correction","question":"Find the error: We're is at home now.","options":["We're","is","at home","now"],"correct_answer":"is","explanation":"We're đã có nghĩa là We are, nên không thêm is sau đó. At home và now là các cụm đúng để nói vị trí và thời gian.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **to be**: I ___ in grade six.","options":["am","is","are","be"],"correct_answer":"am","explanation":"Với chủ ngữ I, ta dùng am. Is dùng với he/she/it hoặc một người/vật; are dùng với you/we/they hoặc số nhiều; be không dùng trực tiếp ở thì hiện tại đơn như câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb form**: My backpack ___ blue.","options":["is","am","are","be"],"correct_answer":"is","explanation":"My backpack là một vật số ít nên dùng is. Am chỉ đi với I; are dùng với chủ ngữ số nhiều hoặc you/we/they; be không phù hợp trong câu khẳng định hiện tại đơn này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **agreement**: You and I ___ in the same class.","options":["are","am","is","be"],"correct_answer":"are","explanation":"You and I tương đương we, nên dùng are. Am chỉ dùng với I đứng một mình; is dùng với chủ ngữ số ít; be không phải dạng chia đúng ở đây.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **question form**: ___ your grandparents at home?","options":["Are","Is","Am","Be"],"correct_answer":"Are","explanation":"Your grandparents là chủ ngữ số nhiều nên câu hỏi dùng Are ở đầu câu. Is dùng cho số ít; Am dùng với I; Be không đứng đầu câu hỏi hiện tại đơn như vậy.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **negative form**: The soup ___ hot.","options":["is not","are not","am not","be not"],"correct_answer":"is not","explanation":"The soup là danh từ không đếm được, xem như số ít nên dùng is not. Are not dùng với số nhiều; am not chỉ đi với I; be not không tự nhiên trong mẫu câu này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **short answer**: Is Tom from Canada? Yes, he ___.","options":["is","are","am","isn't"],"correct_answer":"is","explanation":"Câu hỏi bắt đầu bằng Is và chủ ngữ là Tom = he, nên câu trả lời ngắn là Yes, he is. Are và am không hợp với he; isn't là phủ định nên sai với Yes.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **contraction**: She is my teacher. = ___ my teacher.","options":["She's","She're","She'm","Shes"],"correct_answer":"She's","explanation":"She is được rút gọn thành She's. She're và She'm không tồn tại; Shes thiếu dấu nháy và không phải dạng rút gọn chuẩn.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **word order**: ___ your new shoes expensive?","options":["Are","Is","Am","Do"],"correct_answer":"Are","explanation":"Your new shoes là số nhiều nên dùng Are trong câu hỏi. Is dùng cho số ít; Am dùng với I; Do không dùng để tạo câu hỏi với động từ to be.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **to be**: My best friend and I ___ from Vietnam.","options":["are","is","am","be"],"correct_answer":"are","explanation":"My best friend and I là hai người, nghĩa là we, nên dùng are. Is dùng cho một người/vật; am chỉ dùng với I đứng riêng; be không phải dạng chia đúng.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **to be**: It ___ sunny today.","options":["is","am","are","be"],"correct_answer":"is","explanation":"It đi với is trong thì hiện tại. Am chỉ dùng với I; are dùng với you/we/they hoặc số nhiều; be không phù hợp sau It trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb form**: I ___ not tired.","options":["am","is","are","be"],"correct_answer":"am","explanation":"Với chủ ngữ I, dạng phủ định là I am not. Is not và are not dùng với chủ ngữ khác; be not không phải cấu trúc cơ bản trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **agreement**: These oranges ___ sweet.","options":["are","is","am","be"],"correct_answer":"are","explanation":"These oranges là danh từ số nhiều nên dùng are. Is dùng cho số ít; am chỉ đi với I; be không phải dạng chia đúng ở hiện tại đơn.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **question form**: ___ she your cousin?","options":["Is","Are","Am","Be"],"correct_answer":"Is","explanation":"She là chủ ngữ ngôi thứ ba số ít nên câu hỏi bắt đầu bằng Is. Are không đi với she; Am chỉ dùng với I; Be không đúng trong câu hỏi hiện tại đơn này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **negative form**: We ___ at the bus stop.","options":["are not","is not","am not","be not"],"correct_answer":"are not","explanation":"We đi với are, nên dạng phủ định là are not. Is not dùng với số ít; am not dùng với I; be not không phải mẫu câu cơ bản ở đây.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **short answer**: Are you hungry? No, I ___.","options":["am not","is not","are not","be not"],"correct_answer":"am not","explanation":"Khi trả lời về you nhưng người nói nói về bản thân, ta dùng I am not. Is not không đi với I; are not đi với you/we/they; be not sai trong mẫu này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **contraction**: We are on the train. = ___ on the train.","options":["We're","We's","I'm","They're"],"correct_answer":"We're","explanation":"We are được rút gọn thành We're. We's không đúng; I'm nghĩa là I am; They're nghĩa là they are nên không giữ đúng chủ ngữ we.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **to be**: His new phone ___ very small.","options":["is","are","am","be"],"correct_answer":"is","explanation":"His new phone là một vật số ít nên dùng is. Are dùng với số nhiều; am dùng với I; be không được chia theo chủ ngữ ở câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: My hands is cold.","options":["My hands","is","cold","My"],"correct_answer":"is","explanation":"My hands là số nhiều nên phải dùng are, không dùng is. Cold là tính từ đúng; My hands là chủ ngữ đúng về nghĩa; My không phải lỗi ngữ pháp trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: Are your sister at school?","options":["Are","your sister","at school","school"],"correct_answer":"Are","explanation":"Your sister là một người số ít nên câu hỏi phải là Is your sister at school? Your sister và at school đúng; school chỉ là danh từ trong cụm vị trí.","difficulty":1},{"type":"error_correction","question":"Find the error: I am not a doctor?","options":["I","am not","a doctor","?"],"correct_answer":"?","explanation":"Đây là trật tự câu khẳng định/phủ định, không phải câu hỏi, nên không nên dùng dấu hỏi. Nếu muốn hỏi, phải viết Am I not a doctor? Các phần I, am not, a doctor đều đúng trong câu phủ định.","difficulty":3},{"type":"error_correction","question":"Find the error: The baby are asleep.","options":["The baby","are","asleep","baby"],"correct_answer":"are","explanation":"The baby là một người số ít nên phải dùng is. Asleep là tính từ đúng; The baby là chủ ngữ đúng; baby không phải lỗi riêng trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: We is in the kitchen.","options":["We","is","in","the kitchen"],"correct_answer":"is","explanation":"We phải đi với are, nên is là lỗi. We là chủ ngữ đúng; in và the kitchen tạo cụm chỉ vị trí đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: Is the socks in your bag?","options":["Is","the socks","in","your bag"],"correct_answer":"Is","explanation":"The socks là danh từ số nhiều nên câu hỏi phải dùng Are. The socks, in và your bag đều đúng về nghĩa và cấu trúc vị trí.","difficulty":2},{"type":"error_correction","question":"Find the error: He's are my uncle.","options":["He's","are","my","uncle"],"correct_answer":"are","explanation":"He's đã có nghĩa là He is, nên không được thêm are sau đó. My và uncle đúng trong cụm my uncle; lỗi chính là dùng thừa are.","difficulty":2},{"type":"error_correction","question":"Find the error: Their house am near the river.","options":["Their house","am","near","the river"],"correct_answer":"am","explanation":"Their house là một vật số ít nên phải dùng is. Am chỉ dùng với I; near the river là cụm chỉ vị trí đúng.","difficulty":2}]$grammar$::jsonb, 'ai-golden', 2
from public.grammar_topics t where t.slug = 'verb-to-be'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 03. demonstratives
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('demonstratives', 'Demonstratives (this/that/these/those)', 'Từ chỉ định (this/that/these/those)', 'beginner', 3)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Từ chỉ định (this/that/these/those)', '**Từ chỉ định** (Demonstratives: *this, that, these, those*) được dùng để xác định, chỉ ra một người, vật hoặc ý tưởng cụ thể mà ta đang nói đến. Chúng chỉ rõ danh từ được nhắc đến là số ít hay số nhiều, và khoảng cách gần hay xa so với người nói.', $grammar$[{"en":"This apple is sweet.","vi":"Quả táo này ngọt.","note":"Gần và số ít.","annotations":[{"word":"This","start":0,"end":4,"role":"determiner"},{"word":"apple","start":5,"end":10,"role":"noun"},{"word":"is","start":11,"end":13,"role":"auxiliary"},{"word":"sweet","start":14,"end":19,"role":"adjective"}]},{"en":"That car over there is expensive.","vi":"Chiếc xe đằng kia đắt tiền.","note":"Xa và số ít.","annotations":[{"word":"That","start":0,"end":4,"role":"determiner"},{"word":"car","start":5,"end":8,"role":"noun"},{"word":"over","start":9,"end":13,"role":"preposition"},{"word":"there","start":14,"end":19,"role":"adverb"},{"word":"is","start":20,"end":22,"role":"auxiliary"},{"word":"expensive","start":23,"end":32,"role":"adjective"}]},{"en":"These shoes fit me well.","vi":"Đôi giày này vừa với tôi.","note":"Gần và số nhiều.","annotations":[{"word":"These","start":0,"end":5,"role":"determiner"},{"word":"shoes","start":6,"end":11,"role":"noun"},{"word":"fit","start":12,"end":15,"role":"verb"},{"word":"me","start":16,"end":18,"role":"pronoun"},{"word":"well","start":19,"end":23,"role":"adverb"}]},{"en":"Those birds are flying south.","vi":"Những con chim kia đang bay về phía nam.","note":"Xa và số nhiều.","annotations":[{"word":"Those","start":0,"end":5,"role":"determiner"},{"word":"birds","start":6,"end":11,"role":"noun"},{"word":"are","start":12,"end":15,"role":"auxiliary"},{"word":"flying","start":16,"end":22,"role":"verb"},{"word":"south","start":23,"end":28,"role":"adverb"}]},{"en":"Who is that?","vi":"Ai đó?","note":"that chỉ một người ở xa hoặc qua điện thoại.","annotations":[{"word":"Who","start":0,"end":3,"role":"pronoun"},{"word":"is","start":4,"end":6,"role":"auxiliary"},{"word":"that","start":7,"end":11,"role":"determiner"}]},{"en":"This is my colleague, Nam.","vi":"Đây là đồng nghiệp của tôi, Nam.","note":"This is dùng để giới thiệu.","annotations":[{"word":"This","start":0,"end":4,"role":"determiner"},{"word":"is","start":5,"end":7,"role":"auxiliary"},{"word":"my","start":8,"end":10,"role":"determiner"},{"word":"colleague","start":11,"end":20,"role":"noun"},{"word":"Nam","start":22,"end":25,"role":"noun"}]}]$grammar$::jsonb, $grammar${"definition":"**Từ chỉ định** (Demonstratives: *this, that, these, those*) được dùng để xác định, chỉ ra một người, vật hoặc ý tưởng cụ thể mà ta đang nói đến. Chúng chỉ rõ danh từ được nhắc đến là số ít hay số nhiều, và khoảng cách gần hay xa so với người nói.","usage":[{"icon":"📍","label":"Một vật ở gần","en":"This key is mine.","vi":"Chìa khóa này là của tôi."},{"icon":"🔭","label":"Một vật ở xa","en":"That building is a museum.","vi":"Tòa nhà kia là bảo tàng."},{"icon":"📚","label":"Nhiều vật ở gần","en":"These books are useful.","vi":"Những cuốn sách này hữu ích."},{"icon":"🏔️","label":"Nhiều vật ở xa","en":"Those mountains are beautiful.","vi":"Những ngọn núi kia rất đẹp."}],"formula":{"rows":[{"form":"Gần + số ít","structure":"this + singular noun / This is...","example":"this cup"},{"form":"Xa + số ít","structure":"that + singular noun / That is...","example":"that cup"},{"form":"Gần + số nhiều","structure":"these + plural noun / These are...","example":"these cups"},{"form":"Xa + số nhiều","structure":"those + plural noun / Those are...","example":"those cups"}],"note":"Đọc cấu trúc cùng ví dụ và luôn kiểm tra vai trò, số lượng hoặc dạng động từ theo từng trường hợp."},"rules":[{"case":"this / that","rule":"Đi với is và danh từ số ít","example":"This is a chair."},{"case":"these / those","rule":"Đi với are và danh từ số nhiều","example":"Those are chairs."},{"case":"Đứng trước danh từ","rule":"Không dùng a/an sau từ chỉ định","example":"this phone, không phải this a phone"},{"case":"Giới thiệu người","rule":"Dùng This is... khi giới thiệu","example":"This is my friend, Mai."}],"signals":["here/near me","over there/far away","singular","plural","these days / that day"],"examples":[{"en":"This apple is sweet.","vi":"Quả táo này ngọt.","note":"Gần và số ít.","annotations":[{"word":"This","start":0,"end":4,"role":"determiner"},{"word":"apple","start":5,"end":10,"role":"noun"},{"word":"is","start":11,"end":13,"role":"auxiliary"},{"word":"sweet","start":14,"end":19,"role":"adjective"}]},{"en":"That car over there is expensive.","vi":"Chiếc xe đằng kia đắt tiền.","note":"Xa và số ít.","annotations":[{"word":"That","start":0,"end":4,"role":"determiner"},{"word":"car","start":5,"end":8,"role":"noun"},{"word":"over","start":9,"end":13,"role":"preposition"},{"word":"there","start":14,"end":19,"role":"adverb"},{"word":"is","start":20,"end":22,"role":"auxiliary"},{"word":"expensive","start":23,"end":32,"role":"adjective"}]},{"en":"These shoes fit me well.","vi":"Đôi giày này vừa với tôi.","note":"Gần và số nhiều.","annotations":[{"word":"These","start":0,"end":5,"role":"determiner"},{"word":"shoes","start":6,"end":11,"role":"noun"},{"word":"fit","start":12,"end":15,"role":"verb"},{"word":"me","start":16,"end":18,"role":"pronoun"},{"word":"well","start":19,"end":23,"role":"adverb"}]},{"en":"Those birds are flying south.","vi":"Những con chim kia đang bay về phía nam.","note":"Xa và số nhiều.","annotations":[{"word":"Those","start":0,"end":5,"role":"determiner"},{"word":"birds","start":6,"end":11,"role":"noun"},{"word":"are","start":12,"end":15,"role":"auxiliary"},{"word":"flying","start":16,"end":22,"role":"verb"},{"word":"south","start":23,"end":28,"role":"adverb"}]},{"en":"Who is that?","vi":"Ai đó?","note":"that chỉ một người ở xa hoặc qua điện thoại.","annotations":[{"word":"Who","start":0,"end":3,"role":"pronoun"},{"word":"is","start":4,"end":6,"role":"auxiliary"},{"word":"that","start":7,"end":11,"role":"determiner"}]},{"en":"This is my colleague, Nam.","vi":"Đây là đồng nghiệp của tôi, Nam.","note":"This is dùng để giới thiệu.","annotations":[{"word":"This","start":0,"end":4,"role":"determiner"},{"word":"is","start":5,"end":7,"role":"auxiliary"},{"word":"my","start":8,"end":10,"role":"determiner"},{"word":"colleague","start":11,"end":20,"role":"noun"},{"word":"Nam","start":22,"end":25,"role":"noun"}]}],"mistakes":[{"wrong":"This books are new.","right":"These books are new.","why":"Books là số nhiều nên dùng these."},{"wrong":"Those car is fast.","right":"That car is fast.","why":"Car là số ít nên dùng that."},{"wrong":"This is a my bag.","right":"This is my bag.","why":"Không dùng a trước cụm my bag."},{"wrong":"This books are mine.","right":"These books are mine.","why":"Danh từ số nhiều đi với THESE/THOSE; this/that chỉ cho số ít."},{"wrong":"That is my keys.","right":"Those are my keys.","why":"Keys số nhiều → those are, không dùng that is."}],"tips":"**Mẹo 2×2:** gần: **this/these**; xa: **that/those**. Số ít kết thúc bằng **-t** (this, that); số nhiều có âm /z/ ở cuối (these, those). Luôn kiểm tra is/are và danh từ số ít/số nhiều.","comparison":"**this vs it:** *This is my phone* dùng khi chỉ/giới thiệu điện thoại; *It is new* dùng it để nhắc lại vật đã xác định. **that vs those:** cùng chỉ xa nhưng that số ít, those số nhiều.","timeline":null}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"___ flowers here smell wonderful.","opts":["This","These","That"],"answer":"These","fb":"Flowers số nhiều và ở gần."},{"type":"mcq","q":"Look at ___ star over there.","opts":["this","these","that"],"answer":"that","fb":"Star số ít và ở xa."},{"type":"mcq","q":"___ are my parents in this photo.","opts":["This","These","That"],"answer":"These","fb":"Parents là số nhiều."},{"type":"fill","q":"___ is my desk here. (near, singular)","answer":["this"],"fb":"Gần và số ít dùng this."},{"type":"fill","q":"___ houses across the river are old. (far, plural)","answer":["those"],"fb":"Xa và số nhiều dùng those."},{"type":"fill","q":"___ are fresh cookies on this plate. (near, plural)","answer":["these"],"fb":"Gần và số nhiều dùng these."},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"This books are new.\"","answer":false,"fb":"SAI. Books là số nhiều nên dùng these. Câu đúng: \"These books are new.\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"Those car is fast.\"","answer":false,"fb":"SAI. Car là số ít nên dùng that. Câu đúng: \"That car is fast.\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"This is a my bag.\"","answer":false,"fb":"SAI. Không dùng a trước cụm my bag. Câu đúng: \"This is my bag.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["This apple is sweet.","This books are new.","Those birds are flying south."],"answer":"This books are new.","fb":"Books là số nhiều nên dùng these. Câu đúng: \"These books are new.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["That car over there is expensive.","Those car is fast.","Who is that?"],"answer":"Those car is fast.","fb":"Car là số ít nên dùng that. Câu đúng: \"That car is fast.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["These shoes fit me well.","This is a my bag.","This is my colleague, Nam."],"answer":"This is a my bag.","fb":"Không dùng a trước cụm my bag. Câu đúng: \"This is my bag.\""},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ pen in my hand is blue.","options":["This","That","These","Those"],"correct_answer":"This","explanation":"Dùng \"This\" vì cây bút ở gần người nói và là số ít. \"That\" dùng cho vật ở xa; \"These\" và \"Those\" dùng cho số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ birds in the tree over there are noisy.","options":["Those","This","That","These"],"correct_answer":"Those","explanation":"Dùng \"Those\" vì có nhiều con chim và chúng ở xa. \"This/That\" dùng cho số ít; \"These\" dùng cho nhiều vật ở gần.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb**: These shoes ___ too small for me.","options":["are","is","am","be"],"correct_answer":"are","explanation":"\"These\" đi với danh từ số nhiều nên dùng \"are\". \"Is\" dùng với số ít; \"am\" chỉ đi với \"I\"; \"be\" không phù hợp trong câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ is my sister, Lan.","options":["This","These","Those","That book"],"correct_answer":"This","explanation":"Khi giới thiệu người ở gần hoặc trong tình huống trực tiếp, dùng \"This is...\". \"These/Those\" là số nhiều; \"That book\" không dùng để giới thiệu người.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **noun form**: That ___ is very old.","options":["watch","watches","watchs","a watch"],"correct_answer":"watch","explanation":"\"That\" đi với danh từ số ít, nên dùng \"watch\". \"Watches\" là số nhiều; \"watchs\" sai chính tả; không dùng \"that a watch\" trước danh từ.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ oranges in this basket are sweet.","options":["These","This","That","Those"],"correct_answer":"These","explanation":"Dùng \"These\" vì có nhiều quả cam và chúng ở gần trong cái giỏ này. \"This/That\" dùng cho số ít; \"Those\" dùng cho nhiều vật ở xa.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **sentence**:","options":["This is my teacher.","These is my teacher.","That are my teacher.","Those is my teacher."],"correct_answer":"This is my teacher.","explanation":"\"This is...\" đúng khi nói về một người. \"These/Those\" là số nhiều nên không đi với \"is\" trong các câu kia; \"That are\" cũng sai vì \"that\" là số ít.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: Can you see ___ bus at the end of the street?","options":["that","this","these","those"],"correct_answer":"that","explanation":"Dùng \"that\" vì chiếc xe buýt ở xa và là số ít. \"This\" dùng cho vật gần; \"these/those\" dùng cho số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **form**: ___ are my new glasses.","options":["These","This","That","A these"],"correct_answer":"These","explanation":"\"Glasses\" là danh từ số nhiều nên dùng \"These are\" khi ở gần. \"This/That\" là số ít; \"A these\" sai vì không dùng mạo từ \"a\" trước từ chỉ định.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ cup beside me is hot.","options":["This","That","These","Those"],"correct_answer":"This","explanation":"Chiếc cốc ở ngay bên cạnh người nói nên dùng \"This\" cho số ít, ở gần. \"That\" là số ít nhưng ở xa; \"These/Those\" dùng cho số nhiều.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ trees on the hill are tall.","options":["Those","These","This","That"],"correct_answer":"Those","explanation":"Có nhiều cây và chúng ở trên ngọn đồi xa, nên dùng \"Those\". \"These\" dùng cho nhiều vật ở gần; \"This/That\" dùng cho số ít.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ is my phone, not yours.","options":["This","These","Those","A this"],"correct_answer":"This","explanation":"\"Phone\" được hiểu là một vật số ít ở gần, nên dùng \"This is\". \"These/Those\" là số nhiều; \"A this\" sai vì không dùng \"a\" trước từ chỉ định.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ children in the playground are my cousins.","options":["Those","That","This","A those"],"correct_answer":"Those","explanation":"\"Children\" là số nhiều và ở sân chơi xa người nói, nên dùng \"Those\". \"This/That\" dùng cho số ít; \"A those\" sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **verb**: That cat ___ under the car.","options":["is","are","am","be"],"correct_answer":"is","explanation":"\"That cat\" là danh từ số ít, nên động từ đúng là \"is\". \"Are\" dùng cho số nhiều; \"am\" chỉ đi với \"I\"; \"be\" không dùng trực tiếp ở thì hiện tại đơn như vậy.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: I like ___ pictures on your phone.","options":["these","this","that","a these"],"correct_answer":"these","explanation":"\"Pictures\" là số nhiều và ở gần trên điện thoại của người nghe, nên dùng \"these\". \"This/that\" dùng cho số ít; \"a these\" sai vì \"these\" không đi với \"a\".","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ man across the road is our doctor.","options":["That","This","These","Those"],"correct_answer":"That","explanation":"\"Man\" là số ít và ở bên kia đường, tức là xa, nên dùng \"That\". \"This\" dùng cho người/vật ở gần; \"These/Those\" dùng cho số nhiều.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb**: Those bags ___ very heavy.","options":["are","is","am","being"],"correct_answer":"are","explanation":"\"Those bags\" là cụm danh từ số nhiều nên dùng \"are\". \"Is\" dùng cho số ít; \"am\" đi với \"I\"; \"being\" không phù hợp ở câu hiện tại đơn này.","difficulty":1},{"type":"error_correction","question":"Find the error: **This/These** apples are from my garden.","options":["This","apples","are","from my garden"],"correct_answer":"This","explanation":"\"Apples\" là số nhiều nên phải dùng \"These apples\". \"Are\" đúng với số nhiều; các cụm còn lại không sai ngữ pháp trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: **That/Those** pencils is on the shelf.","options":["That","pencils","is","on the shelf"],"correct_answer":"That","explanation":"\"Pencils\" là số nhiều nên phải dùng \"Those pencils are\" hoặc \"These pencils are\" tùy khoảng cách. \"That\" sai vì dùng cho số ít; câu cũng cần \"are\" nếu giữ danh từ số nhiều.","difficulty":2},{"type":"error_correction","question":"Find the error: **These/This** sandwich is for you.","options":["These","sandwich","is","for you"],"correct_answer":"These","explanation":"\"Sandwich\" là số ít nên phải dùng \"This sandwich\" nếu ở gần. \"Is\" đúng với danh từ số ít; các phần còn lại không sai.","difficulty":1},{"type":"error_correction","question":"Find the error: **Those/That** are my aunt in the photo.","options":["Those","are","my aunt","in the photo"],"correct_answer":"Those","explanation":"\"My aunt\" là một người số ít, nên dùng \"That is my aunt\" hoặc \"This is my aunt\". \"Those are\" dùng cho nhiều người/vật, nên không hợp với \"my aunt\".","difficulty":2},{"type":"error_correction","question":"Find the error: **No a/an** I want this a notebook.","options":["I want","this a notebook","notebook","this"],"correct_answer":"this a notebook","explanation":"Không dùng \"a\" sau từ chỉ định trước danh từ; câu đúng là \"I want this notebook.\" \"I want\", \"notebook\" và \"this\" riêng lẻ không phải lỗi chính.","difficulty":2},{"type":"error_correction","question":"Find the error: **These/Those** are that socks under the bed.","options":["These","are","that socks","under the bed"],"correct_answer":"that socks","explanation":"\"Socks\" là số nhiều nên phải dùng \"these socks\" hoặc \"those socks\", không dùng \"that socks\". \"Are\" đúng với chủ ngữ số nhiều; các cụm còn lại có thể đúng tùy ngữ cảnh.","difficulty":3},{"type":"error_correction","question":"Find the error: **This/These** are my favorite song.","options":["This","are","my favorite","song"],"correct_answer":"are","explanation":"\"This\" và \"song\" là số ít nên động từ phải là \"is\": \"This is my favorite song.\" \"This\" phù hợp với số ít; \"my favorite\" và \"song\" không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: **That/Those** posters near us are expensive.","options":["That","posters","near us","are expensive"],"correct_answer":"That","explanation":"\"Posters\" là số nhiều nên phải dùng \"These posters\" nếu ở gần hoặc \"Those posters\" nếu ở xa. \"That\" sai vì chỉ dùng với danh từ số ít.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ backpack next to me is red.","options":["This","That","These","Those"],"correct_answer":"This","explanation":"Dùng “This” vì “backpack” là danh từ số ít và ở gần người nói (“next to me”). “That” chỉ vật ở xa, còn “These/Those” dùng cho số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ houses across the river are small.","options":["Those","These","This","That"],"correct_answer":"Those","explanation":"Dùng “Those” vì “houses” là số nhiều và ở xa (“across the river”). “These” dùng cho nhiều vật ở gần, còn “This/That” dùng cho số ít.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb**: This room ___ very quiet.","options":["is","are","am","be"],"correct_answer":"is","explanation":"“This room” là danh từ số ít nên đi với “is”. “Are” dùng cho số nhiều, “am” đi với “I”, còn “be” không phù hợp trong câu hiện tại đơn này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **noun form**: These ___ are clean.","options":["plates","plate","a plate","the plate"],"correct_answer":"plates","explanation":"“These” dùng với danh từ số nhiều, nên cần “plates”. “Plate” và “a plate” là số ít, còn “the plate” không phù hợp với “These”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ cookies on this plate are for you.","options":["These","Those","This","That"],"correct_answer":"These","explanation":"Dùng “These” vì “cookies” là số nhiều và ở gần (“on this plate”). “Those” chỉ số nhiều ở xa, còn “This/That” dùng cho số ít.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **form**: ___ are my parents in the photo.","options":["Those","That","This","It"],"correct_answer":"Those","explanation":"Dùng “Those are” vì “parents” là số nhiều và trong ảnh thường là người/vật được chỉ ra ở khoảng cách xa hơn. “That/This/It” dùng cho số ít.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: Is ___ your umbrella over there?","options":["that","this","these","those"],"correct_answer":"that","explanation":"“Umbrella” là số ít và “over there” cho biết ở xa, nên dùng “that”. “This” dùng cho gần, còn “these/those” dùng cho số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **word order**:","options":["This is my teacher.","This my is teacher.","Is this my teacher.","This is teacher my."],"correct_answer":"This is my teacher.","explanation":"Khi giới thiệu người, mẫu đúng là “This is + người”. Các lựa chọn khác sai trật tự từ hoặc thiếu dấu câu phù hợp nếu là câu hỏi.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ laptop on my desk is new.","options":["This","That","These","Those"],"correct_answer":"This","explanation":"“Laptop” là số ít và ở gần người nói (“on my desk”), nên dùng “This”. “That” chỉ xa, còn “These/Those” dùng cho số nhiều.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ stars in the sky are bright tonight.","options":["Those","These","This","That"],"correct_answer":"Those","explanation":"“Stars” là số nhiều và ở xa trên bầu trời, nên dùng “Those”. “These” chỉ nhiều vật ở gần, còn “This/That” dùng cho số ít.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb**: Those flowers ___ beautiful.","options":["are","is","am","be"],"correct_answer":"are","explanation":"“Those flowers” là chủ ngữ số nhiều nên đi với “are”. “Is” dùng cho số ít, “am” đi với “I”, còn “be” không đúng trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ is my brother, Minh.","options":["This","These","Those","They"],"correct_answer":"This","explanation":"Khi giới thiệu một người, ta dùng “This is...”. “These/Those/They” dùng cho số nhiều nên không phù hợp với một người.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **noun form**: That ___ is closed today.","options":["shop","shops","a shop","shopes"],"correct_answer":"shop","explanation":"“That” đứng trước danh từ số ít, nên dùng “shop”. “Shops” là số nhiều, “a shop” sai vì không dùng “a/an” sau “that”, còn “shopes” sai chính tả.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ chairs near the window are free.","options":["These","Those","This","That"],"correct_answer":"These","explanation":"“Chairs” là số nhiều và ở gần (“near the window”), nên dùng “These”. “Those” chỉ số nhiều ở xa, còn “This/That” dùng cho số ít.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: I don't like ___ noise from the next room.","options":["that","these","those","thises"],"correct_answer":"that","explanation":"“Noise” là danh từ không đếm được, thường được xem như số ít; “from the next room” gợi ý ở xa hơn nên dùng “that”. “These/Those” dùng cho số nhiều, còn “thises” không phải dạng đúng.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **form**: ___ are not my keys; my keys are here.","options":["Those","That","This","It"],"correct_answer":"Those","explanation":"“Keys” là số nhiều, nên dùng “Those are”. “That/This/It” dùng cho số ít nên không hợp với “are” và “keys”.","difficulty":2},{"type":"error_correction","question":"Find the error: **This** shoes are wet.","options":["This","shoes","are","wet"],"correct_answer":"This","explanation":"“Shoes” là danh từ số nhiều, nên phải dùng “These shoes are wet”. “Are” đúng với số nhiều, còn “shoes” và “wet” không sai.","difficulty":1},{"type":"error_correction","question":"Find the error: That **books** is on the table.","options":["That","books","is","on the table"],"correct_answer":"books","explanation":"“That” đi với danh từ số ít, nên phải là “That book is on the table”. “That” và “is” đúng cho số ít, “on the table” là cụm chỉ nơi chốn đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: These cups **is** clean.","options":["These","cups","is","clean"],"correct_answer":"is","explanation":"“These cups” là số nhiều nên động từ đúng là “are”. “These” và “cups” phù hợp với số nhiều, còn “clean” là tính từ đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: I want **that a** pencil.","options":["I","want","that a","pencil"],"correct_answer":"that a","explanation":"Không dùng “a/an” ngay sau từ chỉ định; câu đúng là “I want that pencil”. Các phần “I”, “want” và “pencil” không sai trong cấu trúc này.","difficulty":2},{"type":"error_correction","question":"Find the error: **Those** girl is my classmate.","options":["Those","girl","is","my classmate"],"correct_answer":"Those","explanation":"“Girl” là danh từ số ít nên phải dùng “That girl” hoặc “This girl”. “Is” đúng với số ít, còn “girl” và “my classmate” không sai.","difficulty":1},{"type":"error_correction","question":"Find the error: This is **a** my father.","options":["This","is","a","my father"],"correct_answer":"a","explanation":"Không dùng mạo từ “a” trước cụm sở hữu “my father”; câu đúng là “This is my father”. “This is” đúng khi giới thiệu người, và “my father” là cụm danh từ đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: **Those** milk is cold.","options":["Those","milk","is","cold"],"correct_answer":"Those","explanation":"“Milk” là danh từ không đếm được và thường được xem như số ít, nên dùng “This/That milk is cold”. “Is” đúng với danh từ số ít/không đếm được, còn “milk” và “cold” không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: These are my **book**.","options":["These","are","my","book"],"correct_answer":"book","explanation":"“These are” dùng cho số nhiều, nên danh từ phải là “books”. “These” và “are” đúng cho số nhiều, còn “my” là tính từ sở hữu đúng.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ trees on the hill are very tall.","options":["Those","That","This","These"],"correct_answer":"Those","explanation":"Dùng \"Those\" vì \"trees\" là số nhiều và ở xa trên ngọn đồi. \"These\" dùng cho số nhiều ở gần, còn \"This/That\" dùng cho số ít.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb**: These apples ___ fresh.","options":["are","is","am","be"],"correct_answer":"are","explanation":"\"These apples\" là chủ ngữ số nhiều nên đi với \"are\". \"Is\" dùng cho số ít, \"am\" dùng với \"I\", còn \"be\" không đúng trong câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **form**: ___ is my new teacher, Ms. Lan.","options":["This","These","Those","They"],"correct_answer":"This","explanation":"Khi giới thiệu một người ở gần, ta dùng \"This is...\". \"These/Those\" dùng cho số nhiều, còn \"They\" không phải từ chỉ định trong mẫu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: Are ___ your bicycles near the gate?","options":["these","this","that","it"],"correct_answer":"these","explanation":"\"Bicycles\" là số nhiều và ở gần cổng, nên dùng \"these\". \"This/that\" dùng cho số ít, còn \"it\" không đi trực tiếp với danh từ số nhiều như vậy.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ cups in this box are for the party.","options":["These","This","That","Those"],"correct_answer":"These","explanation":"\"Cups\" là số nhiều và ở trong chiếc hộp gần người nói, nên dùng \"These\". \"Those\" chỉ số nhiều ở xa, còn \"This/That\" dùng cho số ít.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ cat on my lap is sleeping.","options":["This","That","These","Those"],"correct_answer":"This","explanation":"Con mèo ở trên đùi người nói nên rất gần và là số ít, vì vậy dùng \"This\". \"That\" chỉ số ít ở xa, còn \"These/Those\" chỉ số nhiều.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ birds in that tree are noisy.","options":["Those","These","This","That"],"correct_answer":"Those","explanation":"\"Birds\" là số nhiều và ở cái cây kia, nên dùng \"Those\". \"These\" dùng cho số nhiều ở gần; \"This/That\" dùng cho số ít.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb**: That door ___ open.","options":["is","are","am","be"],"correct_answer":"is","explanation":"\"That door\" là danh từ số ít nên đi với \"is\". \"Are\" dùng cho số nhiều, \"am\" dùng với \"I\", còn \"be\" không đúng ở thì hiện tại đơn trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **noun form**: These ___ are heavy.","options":["bags","bag","bag's","bagging"],"correct_answer":"bags","explanation":"\"These\" đi với danh từ số nhiều, nên cần \"bags\". \"Bag\" là số ít, \"bag's\" là sở hữu/cách viết khác, còn \"bagging\" không phải danh từ phù hợp ở đây.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: Who is ___ man at the bus stop?","options":["that","these","those","they"],"correct_answer":"that","explanation":"\"Man\" là số ít và ở xa tại trạm xe buýt, nên dùng \"that\". \"These/Those\" dùng cho số nhiều, còn \"they\" không đứng trước danh từ số ít như vậy.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **form**: ___ are my classmates, Nam and Hoa.","options":["These","This","That","It"],"correct_answer":"These","explanation":"Có hai người được giới thiệu nên dùng \"These are\". \"This/That/It\" chỉ một người hoặc một vật số ít.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: I like ___ picture here on the wall.","options":["this","that","these","those"],"correct_answer":"this","explanation":"\"Picture\" là số ít và có \"here\" nên ở gần người nói, vì vậy dùng \"this\". \"That\" chỉ số ít ở xa, còn \"these/those\" dùng cho số nhiều.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb**: Those plates ___ dirty.","options":["are","is","am","being"],"correct_answer":"are","explanation":"\"Those plates\" là chủ ngữ số nhiều nên dùng \"are\". \"Is\" dùng cho số ít, \"am\" dùng với \"I\", còn \"being\" không tạo câu đúng ở đây.","difficulty":1},{"type":"error_correction","question":"Find the error: **These** dog is very friendly.","options":["These","dog","is","friendly"],"correct_answer":"These","explanation":"\"Dog\" là danh từ số ít nên phải dùng \"This\" hoặc \"That\", không dùng \"These\". Các từ \"dog\", \"is\", \"friendly\" đều phù hợp với chủ ngữ số ít.","difficulty":1},{"type":"error_correction","question":"Find the error: That cars are parked outside.","options":["That","cars","are","outside"],"correct_answer":"That","explanation":"\"Cars\" là danh từ số nhiều nên phải dùng \"Those\" hoặc \"These\", không dùng \"That\". \"Are\" đúng với danh từ số nhiều, các phần còn lại không sai.","difficulty":1},{"type":"error_correction","question":"Find the error: This boxes are under the table.","options":["This","boxes","are","under"],"correct_answer":"This","explanation":"\"Boxes\" là số nhiều nên phải dùng \"These\" hoặc \"Those\". \"Are\" đúng với danh từ số nhiều, còn \"under the table\" dùng đúng để chỉ vị trí.","difficulty":1},{"type":"error_correction","question":"Find the error: Those child is my cousin.","options":["Those","child","is","cousin"],"correct_answer":"Those","explanation":"\"Child\" là danh từ số ít nên cần \"That\" hoặc \"This\", không dùng \"Those\". \"Is\" đúng với danh từ số ít, và các từ còn lại phù hợp nghĩa câu.","difficulty":2},{"type":"error_correction","question":"Find the error: I like this a song.","options":["I","like","this a","song"],"correct_answer":"this a","explanation":"Sau từ chỉ định \"this\" không dùng thêm \"a/an\" trước danh từ. Câu đúng là \"I like this song\"; các phần khác không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: These is my sister, Linh.","options":["These","is","my sister","Linh"],"correct_answer":"These","explanation":"Khi giới thiệu một người, dùng \"This is...\", không dùng \"These is\". \"Is\" đúng với \"This\", còn \"my sister\" và tên riêng không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: Those are my pencil case.","options":["Those","are","my","pencil case"],"correct_answer":"Those","explanation":"\"Pencil case\" là một vật số ít, nên phải dùng \"That is\" hoặc \"This is\". \"Are\" chỉ đúng nếu chủ ngữ và danh từ đều số nhiều, còn \"my\" và \"pencil case\" không sai về nghĩa.","difficulty":2},{"type":"error_correction","question":"Find the error: This glasses are mine.","options":["This","glasses","are","mine"],"correct_answer":"This","explanation":"\"Glasses\" là danh từ số nhiều nên phải dùng \"These\" hoặc \"Those\". \"Are\" đúng với danh từ số nhiều, và \"mine\" dùng đúng để chỉ sở hữu.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: ___ clouds over there are dark.","options":["This","That","These","Those"],"correct_answer":"Those","explanation":"“Clouds” là danh từ số nhiều và “over there” chỉ ở xa, nên dùng “Those”. “These” dùng cho số nhiều ở gần; “This/That” dùng cho số ít.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb form**: That orange ___ sweet.","options":["is","are","am","be"],"correct_answer":"is","explanation":"“That orange” là chủ ngữ số ít, nên đi với “is”. “Are” dùng cho số nhiều; “am” đi với “I”; “be” không dùng trực tiếp sau chủ ngữ này ở hiện tại đơn.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **form**: Hello, class. ___ is my cousin, Minh.","options":["This","That","These","Those"],"correct_answer":"This","explanation":"Khi giới thiệu một người đang ở gần hoặc đang được đưa vào cuộc trò chuyện, ta dùng “This is...”. “That” thường chỉ người/vật ở xa; “These/Those” dùng cho số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **noun form**: These ___ are red.","options":["flowers","flower","a flower","floweres"],"correct_answer":"flowers","explanation":"“These” dùng với danh từ số nhiều, nên cần “flowers”. “Flower” và “a flower” là số ít; “floweres” sai chính tả dạng số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **phrase**: I need ___ notebook on your desk.","options":["that","those","these","this a"],"correct_answer":"that","explanation":"“Notebook” là số ít và ở trên bàn của người khác, thường hiểu là xa người nói, nên dùng “that”. “Those/these” dùng với số nhiều; “this a” sai vì không dùng “a” sau từ chỉ định.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ sandwich here is for you.","options":["This","That","These","Those"],"correct_answer":"This","explanation":"“Sandwich” là số ít và “here” cho biết ở gần, nên dùng “This”. “That” chỉ số ít ở xa; “These/Those” dùng cho số nhiều.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: ___ houses across the river are old.","options":["This","That","These","Those"],"correct_answer":"Those","explanation":"“Houses” là số nhiều và “across the river” cho thấy ở xa, nên dùng “Those”. “These” dùng cho số nhiều ở gần; “This/That” dùng cho số ít.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **verb**: These socks ___ dry now.","options":["are","is","am","be"],"correct_answer":"are","explanation":"“These socks” là chủ ngữ số nhiều, nên đi với “are”. “Is” dùng cho số ít; “am” chỉ đi với “I”; “be” không phù hợp trong câu hiện tại đơn này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **form**: ___ is not my umbrella; mine is black.","options":["This","These","Those","Are"],"correct_answer":"This","explanation":"“Umbrella” là danh từ số ít, nên dùng “This” hoặc “That”; trong các lựa chọn chỉ “This” phù hợp ngữ pháp. “These/Those” dùng cho số nhiều; “Are” là động từ, không phải từ chỉ định đứng trước “is”.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **noun form**: Those ___ are expensive.","options":["watches","watch","a watch","watchs"],"correct_answer":"watches","explanation":"“Those” cần danh từ số nhiều, nên đáp án đúng là “watches”. “Watch” và “a watch” là số ít; “watchs” là dạng số nhiều sai chính tả.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **demonstrative**: Can you see ___ plane in the sky?","options":["that","this","these","those"],"correct_answer":"that","explanation":"“Plane” là số ít và ở xa trên bầu trời, nên dùng “that”. “This” chỉ số ít ở gần; “these/those” dùng cho số nhiều.","difficulty":1},{"type":"error_correction","question":"Find the error: **These** chair is near the window.","options":["These","chair","is","near the window"],"correct_answer":"These","explanation":"“Chair” là danh từ số ít, nên phải dùng “This” hoặc “That”, không dùng “These”. Các phần còn lại phù hợp với câu số ít: “chair” và “is” đi với nhau đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: That **bananas** is on the shelf.","options":["That","bananas","is","on the shelf"],"correct_answer":"bananas","explanation":"“That” và “is” đều dùng cho số ít, nên danh từ phải là “banana”. “Bananas” là số nhiều nên sai trong cấu trúc này.","difficulty":1},{"type":"error_correction","question":"Find the error: Those bags **is** under the bed.","options":["Those","bags","is","under the bed"],"correct_answer":"is","explanation":"“Those bags” là chủ ngữ số nhiều, nên động từ phải là “are”. “Those” và “bags” đã đúng vì đều ở dạng số nhiều.","difficulty":1},{"type":"error_correction","question":"Find the error: I want **this an** eraser.","options":["I","want","this an","eraser"],"correct_answer":"this an","explanation":"Không dùng “a/an” sau từ chỉ định trước danh từ; phải nói “this eraser”. “I want” đúng cấu trúc, và “eraser” là danh từ phù hợp.","difficulty":2},{"type":"error_correction","question":"Find the error: **That** notebooks are in my bag.","options":["That","notebooks","are","in my bag"],"correct_answer":"That","explanation":"“Notebooks” là danh từ số nhiều, nên phải dùng “These” hoặc “Those”, không dùng “That”. “Are” đúng với chủ ngữ số nhiều.","difficulty":2},{"type":"error_correction","question":"Find the error: This **are** my headphones.","options":["This","are","my","headphones"],"correct_answer":"are","explanation":"“This” là số ít nên đi với “is”, không đi với “are”. Nếu muốn giữ “headphones” số nhiều, câu nên là “These are my headphones.”","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **demonstrative**: My keys are lost. I think I left them on ___ table over there.","options":["this","that","these","those"],"correct_answer":"that","explanation":"Từ 'table' là danh từ số ít, nên ta cần dùng từ chỉ định số ít (this/that). Vì cái bàn ở 'over there' (đằng kia, xa), ta dùng 'that' để chỉ vật ở xa và số ít. Các lựa chọn 'these' và 'those' dùng cho danh từ số nhiều.","difficulty":1}]$grammar$::jsonb, 'ai-golden', 3
from public.grammar_topics t where t.slug = 'demonstratives'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 04. possessives
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('possessives', 'Possessive Adjectives & Pronouns', 'Tính từ & đại từ sở hữu', 'beginner', 4)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Tính từ & đại từ sở hữu', '**Tính từ sở hữu** (*my, your, his, her, its, our, their*) đứng trước danh từ để chỉ sự sở hữu hoặc mối quan hệ với danh từ đó. **Đại từ sở hữu** (*mine, yours, his, hers, ours, theirs*) thay thế cho cả một cụm danh từ sở hữu và đứng độc lập. **Its** không có dạng đại từ sở hữu thông dụng.', $grammar$[{"en":"My brother is a doctor.","vi":"Anh trai tôi là bác sĩ.","note":"my đứng trước danh từ brother.","annotations":[{"end":2,"role":"determiner","word":"My","start":0},{"end":10,"role":"noun","word":"brother","start":3},{"end":13,"role":"auxiliary","word":"is","start":11},{"end":15,"role":"article","word":"a","start":14},{"end":22,"role":"noun","word":"doctor","start":16}]},{"en":"That red umbrella is hers.","vi":"Chiếc ô màu đỏ kia là của cô ấy.","note":"hers thay cho her umbrella.","annotations":[{"end":4,"role":"determiner","word":"That","start":0},{"end":8,"role":"adjective","word":"red","start":5},{"end":17,"role":"noun","word":"umbrella","start":9},{"end":20,"role":"auxiliary","word":"is","start":18},{"end":25,"role":"pronoun","word":"hers","start":21}]},{"en":"Our classroom is larger than theirs.","vi":"Lớp học của chúng tôi lớn hơn lớp của họ.","note":"our + noun; theirs đứng độc lập.","annotations":[{"end":3,"role":"determiner","word":"Our","start":0},{"end":13,"role":"noun","word":"classroom","start":4},{"end":16,"role":"auxiliary","word":"is","start":14},{"end":23,"role":"adjective","word":"larger","start":17},{"end":28,"role":"conjunction","word":"than","start":24},{"end":35,"role":"pronoun","word":"theirs","start":29}]},{"en":"Is this pen yours?","vi":"Cây bút này là của bạn phải không?","note":"yours không có danh từ theo sau.","annotations":[{"end":2,"role":"auxiliary","word":"Is","start":0},{"end":7,"role":"determiner","word":"this","start":3},{"end":11,"role":"noun","word":"pen","start":8},{"end":17,"role":"pronoun","word":"yours","start":12}]},{"en":"The cat is washing its paws.","vi":"Con mèo đang rửa chân của nó.","note":"its là tính từ sở hữu, không có dấu nháy.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":7,"role":"noun","word":"cat","start":4},{"end":10,"role":"auxiliary","word":"is","start":8},{"end":18,"role":"verb","word":"washing","start":11},{"end":22,"role":"determiner","word":"its","start":19},{"end":27,"role":"noun","word":"paws","start":23}]},{"en":"His answer is different from mine.","vi":"Câu trả lời của anh ấy khác câu trả lời của tôi.","note":"his có thể đứng trước noun; mine thay cả cụm my answer.","annotations":[{"end":3,"role":"determiner","word":"His","start":0},{"end":10,"role":"noun","word":"answer","start":4},{"end":13,"role":"auxiliary","word":"is","start":11},{"end":23,"role":"adjective","word":"different","start":14},{"end":28,"role":"preposition","word":"from","start":24},{"end":33,"role":"pronoun","word":"mine","start":29}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo:** Có danh từ ngay sau chỗ trống → chọn tính từ sở hữu. Không có danh từ sau chỗ trống → chọn đại từ sở hữu. Riêng **his** giống nhau ở cả hai vai trò; **its** không có dạng đại từ sở hữu thông dụng.","rules":[{"case":"I / we","rule":"my / our → mine / ours","example":"our room → The room is ours."},{"case":"you","rule":"your → yours","example":"your key → The key is yours."},{"case":"he / she","rule":"his / her → his / hers","example":"her bike → The bike is hers."},{"case":"it / they","rule":"its: không có đại từ sở hữu riêng / their → theirs","example":"their plan → The plan is theirs."}],"usage":[{"en":"This is my notebook. It is mine.","vi":"Đây là vở của tôi. Nó là của tôi.","icon":"👤","label":"Nói người nói sở hữu"},{"en":"Is this your seat or hers?","vi":"Đây là chỗ của bạn hay của cô ấy?","icon":"🤝","label":"Nói người nghe sở hữu"},{"en":"Their house is next to ours.","vi":"Nhà của họ ở cạnh nhà của chúng tôi.","icon":"👨‍👩‍👧","label":"Nói người hoặc vật khác sở hữu"},{"en":"My bag is blue; yours is black.","vi":"Túi của tôi màu xanh; túi của bạn màu đen.","icon":"🔁","label":"Tránh lặp lại danh từ"}],"formula":{"note":"Đọc cấu trúc cùng ví dụ và luôn kiểm tra vai trò, số lượng hoặc dạng động từ theo từng trường hợp.","rows":[{"form":"Tính từ sở hữu","example":"my phone, their books","structure":"possessive adjective + noun"},{"form":"Đại từ sở hữu","example":"The phone is mine.","structure":"possessive pronoun (không + noun)"},{"form":"Hỏi chủ sở hữu","example":"Whose coat is this?","structure":"Whose + noun + be ...?"}]},"signals":["Whose...?","belong to","my/your/his/her/its/our/their + noun","mine/yours/his/hers/ours/theirs"],"examples":[{"en":"My brother is a doctor.","vi":"Anh trai tôi là bác sĩ.","note":"my đứng trước danh từ brother.","annotations":[{"end":2,"role":"determiner","word":"My","start":0},{"end":10,"role":"noun","word":"brother","start":3},{"end":13,"role":"auxiliary","word":"is","start":11},{"end":15,"role":"article","word":"a","start":14},{"end":22,"role":"noun","word":"doctor","start":16}]},{"en":"That red umbrella is hers.","vi":"Chiếc ô màu đỏ kia là của cô ấy.","note":"hers thay cho her umbrella.","annotations":[{"end":4,"role":"determiner","word":"That","start":0},{"end":8,"role":"adjective","word":"red","start":5},{"end":17,"role":"noun","word":"umbrella","start":9},{"end":20,"role":"auxiliary","word":"is","start":18},{"end":25,"role":"pronoun","word":"hers","start":21}]},{"en":"Our classroom is larger than theirs.","vi":"Lớp học của chúng tôi lớn hơn lớp của họ.","note":"our + noun; theirs đứng độc lập.","annotations":[{"end":3,"role":"determiner","word":"Our","start":0},{"end":13,"role":"noun","word":"classroom","start":4},{"end":16,"role":"auxiliary","word":"is","start":14},{"end":23,"role":"adjective","word":"larger","start":17},{"end":28,"role":"conjunction","word":"than","start":24},{"end":35,"role":"pronoun","word":"theirs","start":29}]},{"en":"Is this pen yours?","vi":"Cây bút này là của bạn phải không?","note":"yours không có danh từ theo sau.","annotations":[{"end":2,"role":"auxiliary","word":"Is","start":0},{"end":7,"role":"determiner","word":"this","start":3},{"end":11,"role":"noun","word":"pen","start":8},{"end":17,"role":"pronoun","word":"yours","start":12}]},{"en":"The cat is washing its paws.","vi":"Con mèo đang rửa chân của nó.","note":"its là tính từ sở hữu, không có dấu nháy.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":7,"role":"noun","word":"cat","start":4},{"end":10,"role":"auxiliary","word":"is","start":8},{"end":18,"role":"verb","word":"washing","start":11},{"end":22,"role":"determiner","word":"its","start":19},{"end":27,"role":"noun","word":"paws","start":23}]},{"en":"His answer is different from mine.","vi":"Câu trả lời của anh ấy khác câu trả lời của tôi.","note":"his có thể đứng trước noun; mine thay cả cụm my answer.","annotations":[{"end":3,"role":"determiner","word":"His","start":0},{"end":10,"role":"noun","word":"answer","start":4},{"end":13,"role":"auxiliary","word":"is","start":11},{"end":23,"role":"adjective","word":"different","start":14},{"end":28,"role":"preposition","word":"from","start":24},{"end":33,"role":"pronoun","word":"mine","start":29}]}],"mistakes":[{"wrong":"This is the book of my brother.","right":"This is my brother's book.","why":"Sở hữu của người dùng 's, không dùng cấu trúc of kiểu dịch từ tiếng Việt."},{"wrong":"Its a nice car.","right":"It's a nice car.","why":"It's = it is; ITS (không phẩy) mới là tính từ sở hữu."},{"wrong":"This bag is my.","right":"This bag is mine.","why":"Cuối câu dùng đại từ sở hữu (mine), không dùng tính từ sở hữu (my)."},{"wrong":"Their going home now.","right":"They're going home now.","why":"They're = they are; their là tính từ sở hữu — hai từ khác nghĩa."}],"timeline":null,"comparison":"**my vs mine:** *my book* cần danh từ; *the book is mine* không thêm danh từ. **its vs it’s:** *its tail* = cái đuôi của nó; *it’s long* = it is long.","definition":"**Tính từ sở hữu** (*my, your, his, her, its, our, their*) đứng trước danh từ để chỉ sự sở hữu hoặc mối quan hệ với danh từ đó. **Đại từ sở hữu** (*mine, yours, his, hers, ours, theirs*) thay thế cho cả một cụm danh từ sở hữu và đứng độc lập. **Its** không có dạng đại từ sở hữu thông dụng."}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"This laptop belongs to me. It is ___.","opts":["my","mine","me"],"answer":"mine","fb":"mine thay cho my laptop."},{"type":"mcq","q":"Lan has a new bike. ___ bike is green.","opts":["Her","Hers","She"],"answer":"Her","fb":"Her đứng trước danh từ bike."},{"type":"mcq","q":"We own this house. It is ___.","opts":["our","ours","us"],"answer":"ours","fb":"Ours là đại từ sở hữu đứng độc lập."},{"type":"fill","q":"They brought ___ children to the party. (they)","answer":["their"],"fb":"Cần tính từ sở hữu trước children."},{"type":"fill","q":"This seat is ___. (you)","answer":["yours"],"fb":"Cần đại từ sở hữu đứng độc lập."},{"type":"fill","q":"The cat hurt ___ leg. (it)","answer":["its"],"fb":"its chỉ sự sở hữu."},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"This is mine book.\"","answer":false,"fb":"SAI. Trước danh từ book phải dùng tính từ sở hữu my. Câu đúng: \"This is my book.\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"That bicycle is her.\"","answer":false,"fb":"SAI. Đứng độc lập để chỉ sở hữu phải dùng hers. Câu đúng: \"That bicycle is hers.\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"The dog is eating it’s food.\"","answer":false,"fb":"SAI. its là sở hữu; it’s là dạng rút gọn của it is/it has. Câu đúng: \"The dog is eating its food.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["My brother is a doctor.","This is mine book.","Is this pen yours?"],"answer":"This is mine book.","fb":"Trước danh từ book phải dùng tính từ sở hữu my. Câu đúng: \"This is my book.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["That red umbrella is hers.","That bicycle is her.","The cat is washing its paws."],"answer":"That bicycle is her.","fb":"Đứng độc lập để chỉ sở hữu phải dùng hers. Câu đúng: \"That bicycle is hers.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["Our classroom is larger than theirs.","The dog is eating it’s food.","His answer is different from mine."],"answer":"The dog is eating it’s food.","fb":"its là sở hữu; it’s là dạng rút gọn của it is/it has. Câu đúng: \"The dog is eating its food.\""}]$grammar$::jsonb, 'ai-golden', 4
from public.grammar_topics t where t.slug = 'possessives'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 05. plural-nouns
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('plural-nouns', 'Plural Nouns', 'Danh từ số nhiều', 'beginner', 5)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Danh từ số nhiều', '**Danh từ số nhiều** (Plural Nouns) được sử dụng để chỉ có từ hai người, địa điểm, sự vật hoặc khái niệm trở lên. Phần lớn danh từ được tạo thành số nhiều bằng cách thêm ''-s'' hoặc ''-es'', nhưng cũng có những danh từ có dạng số nhiều bất quy tắc cần ghi nhớ.', $grammar$[{"en":"Three buses stop here.","vi":"Ba chiếc xe buýt dừng ở đây.","note":"bus tận cùng s nên thêm es.","annotations":[{"word":"Three","start":0,"end":5,"role":"other"},{"word":"buses","start":6,"end":11,"role":"noun"},{"word":"stop","start":12,"end":16,"role":"verb"},{"word":"here","start":17,"end":21,"role":"adverb"}]},{"en":"The babies are sleeping.","vi":"Những em bé đang ngủ.","note":"baby: phụ âm + y → babies.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"babies","start":4,"end":10,"role":"noun"},{"word":"are","start":11,"end":14,"role":"auxiliary"},{"word":"sleeping","start":15,"end":23,"role":"verb"}]},{"en":"We need four knives.","vi":"Chúng tôi cần bốn con dao.","note":"knife là dạng f/fe → ves.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"need","start":3,"end":7,"role":"verb"},{"word":"four","start":8,"end":12,"role":"other"},{"word":"knives","start":13,"end":19,"role":"noun"}]},{"en":"Two children are in the garden.","vi":"Hai đứa trẻ ở trong vườn.","note":"child → children là bất quy tắc.","annotations":[{"word":"Two","start":0,"end":3,"role":"other"},{"word":"children","start":4,"end":12,"role":"noun"},{"word":"are","start":13,"end":16,"role":"auxiliary"},{"word":"in","start":17,"end":19,"role":"preposition"},{"word":"the","start":20,"end":23,"role":"article"},{"word":"garden","start":24,"end":30,"role":"noun"}]},{"en":"Those sheep belong to my uncle.","vi":"Những con cừu kia thuộc về chú tôi.","note":"sheep giữ nguyên ở số nhiều.","annotations":[{"word":"Those","start":0,"end":5,"role":"determiner"},{"word":"sheep","start":6,"end":11,"role":"noun"},{"word":"belong","start":12,"end":18,"role":"verb"},{"word":"to","start":19,"end":21,"role":"preposition"},{"word":"my","start":22,"end":24,"role":"determiner"},{"word":"uncle","start":25,"end":30,"role":"noun"}]},{"en":"Her feet are cold.","vi":"Hai bàn chân cô ấy lạnh.","note":"foot → feet là bất quy tắc.","annotations":[{"word":"Her","start":0,"end":3,"role":"determiner"},{"word":"feet","start":4,"end":8,"role":"noun"},{"word":"are","start":9,"end":12,"role":"auxiliary"},{"word":"cold","start":13,"end":17,"role":"adjective"}]}]$grammar$::jsonb, $grammar${"definition":"**Danh từ số nhiều** (Plural Nouns) được sử dụng để chỉ có từ hai người, địa điểm, sự vật hoặc khái niệm trở lên. Phần lớn danh từ được tạo thành số nhiều bằng cách thêm '-s' hoặc '-es', nhưng cũng có những danh từ có dạng số nhiều bất quy tắc cần ghi nhớ.","usage":[{"icon":"2️⃣","label":"Nói số lượng từ hai trở lên","en":"I have two sisters.","vi":"Tôi có hai chị/em gái."},{"icon":"📦","label":"Sau many, several, a few","en":"There are many boxes.","vi":"Có nhiều chiếc hộp."},{"icon":"👥","label":"Chủ ngữ số nhiều đi với are/V nguyên thể","en":"The children are playing.","vi":"Những đứa trẻ đang chơi."},{"icon":"🌍","label":"Nói chung về một loại","en":"Dogs are loyal animals.","vi":"Chó là loài vật trung thành."}],"formula":{"rows":[{"form":"Thông thường","structure":"noun + s","example":"book → books"},{"form":"Tận cùng s, x, z, ch, sh","structure":"noun + es","example":"box → boxes"},{"form":"Phụ âm + y","structure":"y → ies","example":"city → cities"},{"form":"Một số f/fe","structure":"f/fe → ves","example":"knife → knives"},{"form":"Bất quy tắc","structure":"đổi dạng / không đổi","example":"child → children; sheep → sheep"}],"note":"Đọc cấu trúc cùng ví dụ và luôn kiểm tra vai trò, số lượng hoặc dạng động từ theo từng trường hợp."},"rules":[{"case":"Nguyên âm + y","rule":"Giữ y rồi thêm s","example":"toy → toys"},{"case":"Phụ âm + y","rule":"Đổi y thành ies","example":"baby → babies"},{"case":"Một số tận cùng o","rule":"Thêm es; có ngoại lệ","example":"tomato → tomatoes; photo → photos"},{"case":"Danh từ bất quy tắc","rule":"Học từng dạng","example":"man → men; mouse → mice"}],"signals":["two/three...","many","several","a few","these/those","are"],"examples":[{"en":"Three buses stop here.","vi":"Ba chiếc xe buýt dừng ở đây.","note":"bus tận cùng s nên thêm es.","annotations":[{"word":"Three","start":0,"end":5,"role":"other"},{"word":"buses","start":6,"end":11,"role":"noun"},{"word":"stop","start":12,"end":16,"role":"verb"},{"word":"here","start":17,"end":21,"role":"adverb"}]},{"en":"The babies are sleeping.","vi":"Những em bé đang ngủ.","note":"baby: phụ âm + y → babies.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"babies","start":4,"end":10,"role":"noun"},{"word":"are","start":11,"end":14,"role":"auxiliary"},{"word":"sleeping","start":15,"end":23,"role":"verb"}]},{"en":"We need four knives.","vi":"Chúng tôi cần bốn con dao.","note":"knife là dạng f/fe → ves.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"need","start":3,"end":7,"role":"verb"},{"word":"four","start":8,"end":12,"role":"other"},{"word":"knives","start":13,"end":19,"role":"noun"}]},{"en":"Two children are in the garden.","vi":"Hai đứa trẻ ở trong vườn.","note":"child → children là bất quy tắc.","annotations":[{"word":"Two","start":0,"end":3,"role":"other"},{"word":"children","start":4,"end":12,"role":"noun"},{"word":"are","start":13,"end":16,"role":"auxiliary"},{"word":"in","start":17,"end":19,"role":"preposition"},{"word":"the","start":20,"end":23,"role":"article"},{"word":"garden","start":24,"end":30,"role":"noun"}]},{"en":"Those sheep belong to my uncle.","vi":"Những con cừu kia thuộc về chú tôi.","note":"sheep giữ nguyên ở số nhiều.","annotations":[{"word":"Those","start":0,"end":5,"role":"determiner"},{"word":"sheep","start":6,"end":11,"role":"noun"},{"word":"belong","start":12,"end":18,"role":"verb"},{"word":"to","start":19,"end":21,"role":"preposition"},{"word":"my","start":22,"end":24,"role":"determiner"},{"word":"uncle","start":25,"end":30,"role":"noun"}]},{"en":"Her feet are cold.","vi":"Hai bàn chân cô ấy lạnh.","note":"foot → feet là bất quy tắc.","annotations":[{"word":"Her","start":0,"end":3,"role":"determiner"},{"word":"feet","start":4,"end":8,"role":"noun"},{"word":"are","start":9,"end":12,"role":"auxiliary"},{"word":"cold","start":13,"end":17,"role":"adjective"}]}],"mistakes":[{"wrong":"two childs","right":"two children","why":"Child có dạng số nhiều bất quy tắc children."},{"wrong":"three boxs","right":"three boxes","why":"Danh từ tận cùng x thêm -es."},{"wrong":"many citys","right":"many cities","why":"Phụ âm + y: đổi y thành ies."},{"wrong":"She has two childs.","right":"She has two children.","why":"Child là danh từ bất quy tắc — số nhiều là CHILDREN, không thêm -s."},{"wrong":"He gave me many informations.","right":"He gave me a lot of information.","why":"Information KHÔNG đếm được — không có dạng số nhiều, không đi với many."}],"tips":"**Mẹo:** Trước tiên kiểm tra danh từ có bất quy tắc không. Nếu không, nhìn chữ cuối: s/x/z/ch/sh → **-es**; phụ âm + y → **-ies**; còn lại thường thêm **-s**. Sau số đếm lớn hơn một phải dùng số nhiều.","comparison":"**Regular vs irregular plurals:** dạng thường theo quy tắc (*book → books*); dạng bất quy tắc đổi từ (*person → people*) hoặc giữ nguyên (*sheep → sheep*). **Countable vs uncountable:** không thêm -s cho danh từ không đếm được như information, furniture.","timeline":null}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"What is the plural of “class”?","opts":["classs","classes","classies"],"answer":"classes","fb":"class tận cùng s nên thêm es."},{"type":"mcq","q":"What is the plural of “woman”?","opts":["womans","women","womanses"],"answer":"women","fb":"woman → women là bất quy tắc."},{"type":"mcq","q":"Choose the correct phrase.","opts":["three potatoes","three potatos","three potato"],"answer":"three potatoes","fb":"potato thường thêm es. Các danh từ kết thúc bằng o (như potato, tomato) thường được thêm es ở dạng số nhiều."},{"type":"fill","q":"There are five ___ on the shelf. (box)","answer":["boxes"],"fb":"box tận cùng x nên thêm es."},{"type":"fill","q":"Two ___ are playing outside. (child)","answer":["children"],"fb":"child có số nhiều bất quy tắc children."},{"type":"fill","q":"She bought three ___. (toy)","answer":["toys"],"fb":"Nguyên âm + y: giữ y và thêm s."},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"two childs\"","answer":false,"fb":"SAI. Child có dạng số nhiều bất quy tắc children. Câu đúng: \"two children\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"three boxs\"","answer":false,"fb":"SAI. Danh từ tận cùng x thêm -es. Câu đúng: \"three boxes\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"many citys\"","answer":false,"fb":"SAI. Phụ âm + y: đổi y thành ies. Câu đúng: \"many cities\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["Three buses stop here.","two childs","Two children are in the garden."],"answer":"two childs","fb":"Child có dạng số nhiều bất quy tắc children. Câu đúng: \"two children\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["The babies are sleeping.","three boxs","Those sheep belong to my uncle."],"answer":"three boxs","fb":"Danh từ tận cùng x thêm -es. Câu đúng: \"three boxes\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["We need four knives.","many citys","Her feet are cold."],"answer":"many citys","fb":"Phụ âm + y: đổi y thành ies. Câu đúng: \"many cities\""}]$grammar$::jsonb, 'ai-golden', 5
from public.grammar_topics t where t.slug = 'plural-nouns'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 06. adjectives-basic
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('adjectives-basic', 'Adjectives (basic)', 'Tính từ cơ bản', 'beginner', 6)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Tính từ cơ bản', '**Tính từ** (Adjectives) là những từ dùng để mô tả, bổ sung thông tin về đặc điểm, tính chất của danh từ hoặc đại từ. Chúng thường đứng trước danh từ mà chúng bổ nghĩa hoặc sau động từ nối để làm rõ nghĩa.', $grammar$[{"en":"She bought a beautiful dress.","vi":"Cô ấy mua một chiếc váy đẹp.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"verb","word":"bought","start":4},{"end":12,"role":"article","word":"a","start":11},{"end":22,"role":"adjective","word":"beautiful","start":13},{"end":28,"role":"noun","word":"dress","start":23}]},{"en":"The soup smells delicious.","vi":"Món súp có mùi thơm ngon.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"soup","start":4},{"end":15,"role":"verb","word":"smells","start":9},{"end":25,"role":"adjective","word":"delicious","start":16}]},{"en":"This exercise is easy.","vi":"Bài tập này dễ.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":13,"role":"noun","word":"exercise","start":5},{"end":16,"role":"auxiliary","word":"is","start":14},{"end":21,"role":"adjective","word":"easy","start":17}]},{"en":"We need something cheaper.","vi":"Chúng tôi cần thứ gì đó rẻ hơn.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"verb","word":"need","start":3},{"end":17,"role":"pronoun","word":"something","start":8},{"end":25,"role":"adjective","word":"cheaper","start":18}]},{"en":"He feels tired today.","vi":"Hôm nay anh ấy cảm thấy mệt.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":8,"role":"verb","word":"feels","start":3},{"end":14,"role":"adjective","word":"tired","start":9},{"end":20,"role":"adverb","word":"today","start":15}]},{"en":"They painted the door blue.","vi":"Họ sơn cánh cửa màu xanh.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":12,"role":"verb","word":"painted","start":5},{"end":16,"role":"article","word":"the","start":13},{"end":21,"role":"noun","word":"door","start":17},{"end":26,"role":"adjective","word":"blue","start":22}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **adjective + noun** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"adjective + noun","example":"She bought a beautiful dress."},{"case":"Kiểm tra thành phần theo sau","rule":"be/seem/look/feel + adjective","example":"The soup smells delicious."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"something/anything + adjective","example":"This exercise is easy."}],"usage":[{"en":"She bought a beautiful dress.","vi":"Cô ấy đã mua một chiếc váy đẹp.","icon":"🎨","label":"Đứng trước danh từ để miêu tả"},{"en":"The soup smells delicious.","vi":"Món súp có mùi thơm ngon quá.","icon":"🔗","label":"Đứng sau động từ nối (be, look, smell...)"},{"en":"I am tired after the long trip.","vi":"Tôi mệt sau chuyến đi dài.","icon":"😊","label":"Miêu tả cảm xúc, trạng thái của người"},{"en":"We need something cheaper.","vi":"Chúng ta cần thứ gì đó rẻ hơn.","icon":"🔍","label":"Đứng sau đại từ bất định (something, anything...)"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"adjective + noun","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"be/seem/look/feel + adjective","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"something/anything + adjective","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["nice","beautiful","tall","young","old","wooden","round","interesting"],"examples":[{"en":"She bought a beautiful dress.","vi":"Cô ấy mua một chiếc váy đẹp.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"verb","word":"bought","start":4},{"end":12,"role":"article","word":"a","start":11},{"end":22,"role":"adjective","word":"beautiful","start":13},{"end":28,"role":"noun","word":"dress","start":23}]},{"en":"The soup smells delicious.","vi":"Món súp có mùi thơm ngon.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"soup","start":4},{"end":15,"role":"verb","word":"smells","start":9},{"end":25,"role":"adjective","word":"delicious","start":16}]},{"en":"This exercise is easy.","vi":"Bài tập này dễ.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":13,"role":"noun","word":"exercise","start":5},{"end":16,"role":"auxiliary","word":"is","start":14},{"end":21,"role":"adjective","word":"easy","start":17}]},{"en":"We need something cheaper.","vi":"Chúng tôi cần thứ gì đó rẻ hơn.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"verb","word":"need","start":3},{"end":17,"role":"pronoun","word":"something","start":8},{"end":25,"role":"adjective","word":"cheaper","start":18}]},{"en":"He feels tired today.","vi":"Hôm nay anh ấy cảm thấy mệt.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":8,"role":"verb","word":"feels","start":3},{"end":14,"role":"adjective","word":"tired","start":9},{"end":20,"role":"adverb","word":"today","start":15}]},{"en":"They painted the door blue.","vi":"Họ sơn cánh cửa màu xanh.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":12,"role":"verb","word":"painted","start":5},{"end":16,"role":"article","word":"the","start":13},{"end":21,"role":"noun","word":"door","start":17},{"end":26,"role":"adjective","word":"blue","start":22}]}],"mistakes":[{"wrong":"She has a car red.","right":"She has a red car.","why":"Tính từ đứng TRƯỚC danh từ trong tiếng Anh (ngược tiếng Việt)."},{"wrong":"They are happys.","right":"They are happy.","why":"Tính từ không chia số nhiều — không thêm -s."},{"wrong":"He is more tall than me.","right":"He is taller than me.","why":"Tính từ ngắn 1 âm tiết thêm -er, không dùng more."},{"wrong":"It is a interesting book.","right":"It is an interesting book.","why":"Trước nguyên âm (i) dùng AN, không dùng a."}],"timeline":null,"comparison":"**Tính từ vs Trạng từ:** Tính từ mô tả DANH TỪ, đứng trước danh từ hoặc sau động từ nối (be, look, seem): *Sam is a careful driver.* Trạng từ mô tả cách hành động diễn ra, bổ nghĩa cho ĐỘNG TỪ: *Sam drove carefully.* Nhớ: nói về NGƯỜI/VẬT → tính từ; nói về CÁCH LÀM → trạng từ.","definition":"**Tính từ** (Adjectives) là những từ dùng để mô tả, bổ sung thông tin về đặc điểm, tính chất của danh từ hoặc đại từ. Chúng thường đứng trước danh từ mà chúng bổ nghĩa hoặc sau động từ nối để làm rõ nghĩa."}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"She has a ___ dress.","opts":["beautiful","beautifully","beauty"],"answer":"beautiful","fb":"Trước danh từ dress dùng tính từ beautiful."},{"type":"mcq","q":"The soup smells ___.","opts":["delicious","deliciously","delight"],"answer":"delicious","fb":"Sau động từ nối smells dùng tính từ delicious."},{"type":"fill","q":"I am ___ today. (happy / happily)","answer":["happy"],"fb":"Sau am dùng tính từ happy."},{"type":"mcq","q":"Choose the correct sentence.","opts":["She is tired.","She is tiredly.","She tired is."],"answer":"She is tired.","fb":"Be + tính từ: She is tired."},{"type":"fill","q":"This is a ___ book. (new / newly)","answer":["new"],"fb":"Trước danh từ book dùng tính từ new."},{"type":"mcq","q":"The flowers look ___.","opts":["nice","nicely","niceness"],"answer":"nice","fb":"Look là động từ nối ở đây, sau đó dùng tính từ nice."},{"type":"fill","q":"The room is ___. (small / smallly)","answer":["small"],"fb":"Sau is dùng tính từ small."},{"type":"mcq","q":"Which phrase describes a big house?","opts":["a big house","a house big","a bigly house"],"answer":"a big house","fb":"Tính từ big đứng trước danh từ house."}]$grammar$::jsonb, 'ai-golden', 6
from public.grammar_topics t where t.slug = 'adjectives-basic'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 07. there-is-there-are
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('there-is-there-are', 'There is / There are', 'Cấu trúc There is / There are', 'beginner', 7)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Cấu trúc There is / There are', 'Cấu trúc **There is / There are** dùng để giới thiệu sự tồn tại hoặc hiện diện của một người, vật hoặc sự việc nào đó trong một ngữ cảnh cụ thể. **There is** đi với danh từ số ít hoặc danh từ không đếm được, còn **there are** đi với danh từ số nhiều.', $grammar$[{"en":"There is a pharmacy near my house.","vi":"Có một hiệu thuốc gần nhà tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":8,"role":"verb","word":"is","start":6},{"end":10,"role":"article","word":"a","start":9},{"end":19,"role":"noun","word":"pharmacy","start":11},{"end":24,"role":"preposition","word":"near","start":20},{"end":27,"role":"determiner","word":"my","start":25},{"end":33,"role":"noun","word":"house","start":28}]},{"en":"There are two messages for you.","vi":"Có hai tin nhắn dành cho bạn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":9,"role":"verb","word":"are","start":6},{"end":13,"role":"other","word":"two","start":10},{"end":22,"role":"noun","word":"messages","start":14},{"end":26,"role":"preposition","word":"for","start":23},{"end":30,"role":"pronoun","word":"you","start":27}]},{"en":"There isn't any milk left.","vi":"Không còn chút sữa nào.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":11,"role":"auxiliary","word":"isn't","start":6},{"end":15,"role":"determiner","word":"any","start":12},{"end":20,"role":"noun","word":"milk","start":16},{"end":25,"role":"adjective","word":"left","start":21}]},{"en":"Are there enough chairs?","vi":"Có đủ ghế không?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Are","start":0},{"end":9,"role":"adverb","word":"there","start":4},{"end":16,"role":"determiner","word":"enough","start":10},{"end":23,"role":"noun","word":"chairs","start":17}]},{"en":"There was a power cut last night.","vi":"Tối qua đã có một vụ mất điện.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":9,"role":"verb","word":"was","start":6},{"end":11,"role":"article","word":"a","start":10},{"end":17,"role":"noun","word":"power","start":12},{"end":21,"role":"verb","word":"cut","start":18},{"end":26,"role":"adjective","word":"last","start":22},{"end":32,"role":"noun","word":"night","start":27}]},{"en":"There will be a meeting tomorrow.","vi":"Ngày mai sẽ có một cuộc họp.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":10,"role":"modal","word":"will","start":6},{"end":13,"role":"verb","word":"be","start":11},{"end":15,"role":"article","word":"a","start":14},{"end":23,"role":"noun","word":"meeting","start":16},{"end":32,"role":"noun","word":"tomorrow","start":24}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **There is + danh từ số ít/không đếm được** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"There is + danh từ số ít/không đếm được","example":"There is a pharmacy near my house."},{"case":"Kiểm tra thành phần theo sau","rule":"There are + danh từ số nhiều","example":"There are two messages for you."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Is there ...? / Are there ...?","example":"There isn't any milk left."}],"usage":[{"en":"There is a pharmacy near my house.","vi":"Có một hiệu thuốc gần nhà tôi.","icon":"📍","label":"Giới thiệu sự tồn tại của một vật (số ít)"},{"en":"There are two messages for you.","vi":"Có hai tin nhắn cho bạn.","icon":"👥","label":"Giới thiệu nhiều vật, nhiều người (số nhiều)"},{"en":"There isn't any milk left.","vi":"Không còn chút sữa nào cả.","icon":"🚫","label":"Phủ định sự tồn tại với not any / no"},{"en":"Are there enough chairs for everyone?","vi":"Có đủ ghế cho mọi người không?","icon":"❓","label":"Hỏi xem có tồn tại hay không (đảo Is/Are lên trước)"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"There is + danh từ số ít/không đếm được","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"There are + danh từ số nhiều","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Is there ...? / Are there ...?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["there is","there are","there was","there were","there will be","there has been"],"examples":[{"en":"There is a pharmacy near my house.","vi":"Có một hiệu thuốc gần nhà tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":8,"role":"verb","word":"is","start":6},{"end":10,"role":"article","word":"a","start":9},{"end":19,"role":"noun","word":"pharmacy","start":11},{"end":24,"role":"preposition","word":"near","start":20},{"end":27,"role":"determiner","word":"my","start":25},{"end":33,"role":"noun","word":"house","start":28}]},{"en":"There are two messages for you.","vi":"Có hai tin nhắn dành cho bạn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":9,"role":"verb","word":"are","start":6},{"end":13,"role":"other","word":"two","start":10},{"end":22,"role":"noun","word":"messages","start":14},{"end":26,"role":"preposition","word":"for","start":23},{"end":30,"role":"pronoun","word":"you","start":27}]},{"en":"There isn't any milk left.","vi":"Không còn chút sữa nào.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":11,"role":"auxiliary","word":"isn't","start":6},{"end":15,"role":"determiner","word":"any","start":12},{"end":20,"role":"noun","word":"milk","start":16},{"end":25,"role":"adjective","word":"left","start":21}]},{"en":"Are there enough chairs?","vi":"Có đủ ghế không?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Are","start":0},{"end":9,"role":"adverb","word":"there","start":4},{"end":16,"role":"determiner","word":"enough","start":10},{"end":23,"role":"noun","word":"chairs","start":17}]},{"en":"There was a power cut last night.","vi":"Tối qua đã có một vụ mất điện.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":9,"role":"verb","word":"was","start":6},{"end":11,"role":"article","word":"a","start":10},{"end":17,"role":"noun","word":"power","start":12},{"end":21,"role":"verb","word":"cut","start":18},{"end":26,"role":"adjective","word":"last","start":22},{"end":32,"role":"noun","word":"night","start":27}]},{"en":"There will be a meeting tomorrow.","vi":"Ngày mai sẽ có một cuộc họp.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":10,"role":"modal","word":"will","start":6},{"end":13,"role":"verb","word":"be","start":11},{"end":15,"role":"article","word":"a","start":14},{"end":23,"role":"noun","word":"meeting","start":16},{"end":32,"role":"noun","word":"tomorrow","start":24}]}],"mistakes":[{"wrong":"There are a book on the table.","right":"There is a book on the table.","why":"Danh từ số ít (a book) đi với THERE IS."},{"wrong":"There is three chairs here.","right":"There are three chairs here.","why":"Danh từ số nhiều (three chairs) đi với THERE ARE."},{"wrong":"It is a park near my house.","right":"There is a park near my house.","why":"Giới thiệu sự tồn tại lần đầu dùng THERE, không dùng it."},{"wrong":"Have many people in the room.","right":"There are many people in the room.","why":"Không dịch \"có\" thành have — dùng there are."}],"timeline":null,"comparison":"**There vs It:** Dùng *there is/are* khi giới thiệu một thứ TỒN TẠI lần đầu: *There is a new restaurant.* Dùng *it* khi nhắc lại thứ đã nói đến: *It is very good.* Người Việt hay dịch \"có\" và \"nó\" lẫn lộn thành *It was a lot of traffic* — sai.","definition":"Cấu trúc **There is / There are** dùng để giới thiệu sự tồn tại hoặc hiện diện của một người, vật hoặc sự việc nào đó trong một ngữ cảnh cụ thể. **There is** đi với danh từ số ít hoặc danh từ không đếm được, còn **there are** đi với danh từ số nhiều."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: There ___ two messages for you.","answer":["are"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 7
from public.grammar_topics t where t.slug = 'there-is-there-are'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 08. articles
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('articles', 'Articles (a / an / the)', 'Mạo từ (a / an / the)', 'beginner', 8)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Mạo từ (a / an / the)', '**Mạo từ** (Articles: a/an/the) là những từ đứng trước danh từ để chỉ định danh từ đó là **cụ thể** hay **không cụ thể**. Ta dùng **a/an** để nói về một danh từ đếm được, số ít, không xác định hoặc được đề cập lần đầu, còn **the** dùng cho danh từ đã xác định rõ ràng, đã được biết đến hoặc được đề cập trước đó.', $grammar$[{"en":"I have a car.","vi":"Tôi có một chiếc xe.","note":"Dùng **a** vì danh từ 'car' không cụ thể.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"a","start":7,"end":8,"role":"article"},{"word":"car","start":9,"end":12,"role":"noun"}]},{"en":"I am reading an article.","vi":"Tôi đang đọc một bài viết.","note":"Dùng **an** vì danh từ 'article' bắt đầu bằng nguyên âm.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"am","start":2,"end":4,"role":"auxiliary"},{"word":"reading","start":5,"end":12,"role":"verb"},{"word":"an","start":13,"end":15,"role":"article"},{"word":"article","start":16,"end":23,"role":"noun"}]},{"en":"I saw the movie yesterday.","vi":"Tôi xem phim đó vào ngày hôm qua.","note":"Dùng **the** vì danh từ 'movie' đã được nhắc đến trước đó.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"saw","start":2,"end":5,"role":"verb"},{"word":"the","start":6,"end":9,"role":"article"},{"word":"movie","start":10,"end":15,"role":"noun"},{"word":"yesterday","start":16,"end":25,"role":"adverb"}]},{"en":"The book on the table is mine.","vi":"Cuốn sách trên bàn là của tôi.","note":"Dùng **the** vì danh từ 'book' cụ thể.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"book","start":4,"end":8,"role":"noun"},{"word":"on","start":9,"end":11,"role":"preposition"},{"word":"the","start":12,"end":15,"role":"article"},{"word":"table","start":16,"end":21,"role":"noun"},{"word":"is","start":22,"end":24,"role":"auxiliary"},{"word":"mine","start":25,"end":29,"role":"pronoun"}]},{"en":"I have a brother and a sister.","vi":"Tôi có một anh trai và một chị gái.","note":"Dùng **a** vì danh từ 'brother' và 'sister' không cụ thể.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"a","start":7,"end":8,"role":"article"},{"word":"brother","start":9,"end":16,"role":"noun"},{"word":"and","start":17,"end":20,"role":"conjunction"},{"word":"a","start":21,"end":22,"role":"article"},{"word":"sister","start":23,"end":29,"role":"noun"}]},{"en":"The teacher gave us an assignment.","vi":"Giáo viên đã giao cho chúng tôi một nhiệm vụ.","note":"Dùng **an** vì danh từ 'assignment' bắt đầu bằng nguyên âm.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"teacher","start":4,"end":11,"role":"noun"},{"word":"gave","start":12,"end":16,"role":"verb"},{"word":"us","start":17,"end":19,"role":"pronoun"},{"word":"an","start":20,"end":22,"role":"article"},{"word":"assignment","start":23,"end":33,"role":"noun"}]}]$grammar$::jsonb, $grammar${"definition":"**Mạo từ** (Articles: a/an/the) là những từ đứng trước danh từ để chỉ định danh từ đó là **cụ thể** hay **không cụ thể**. Ta dùng **a/an** để nói về một danh từ đếm được, số ít, không xác định hoặc được đề cập lần đầu, còn **the** dùng cho danh từ đã xác định rõ ràng, đã được biết đến hoặc được đề cập trước đó.","usage":[{"icon":"👉","label":"Dùng **a** trước danh từ bắt đầu bằng phụ âm","en":"I have a book.","vi":"Tôi có một cuốn sách."},{"icon":"👉","label":"Dùng **an** trước danh từ bắt đầu bằng nguyên âm","en":"I have an apple.","vi":"Tôi có một quả táo."},{"icon":"👉","label":"Dùng **the** cho danh từ cụ thể","en":"I am reading the book.","vi":"Tôi đang đọc cuốn sách."},{"icon":"👉","label":"Dùng **the** cho danh từ đã được nhắc đến trước đó","en":"I saw a dog. The dog was very big.","vi":"Tôi thấy một con chó. Con chó đó rất lớn."}],"formula":{"rows":[{"form":"Danh từ không cụ thể","mạo_từ":"a / an"},{"form":"Danh từ cụ thể","mạo_từ":"the"},{"form":"Danh từ đã được nhắc đến","mạo_từ":"the"}],"note":"**A** và **an** được dùng cho danh từ không cụ thể, trong khi **the** được dùng cho danh từ cụ thể hoặc đã được nhắc đến trước đó."},"rules":[{"case":"Danh từ bắt đầu bằng phụ âm","rule":"Dùng **a**","example":"cat → a cat"},{"case":"Danh từ bắt đầu bằng nguyên âm","rule":"Dùng **an**","example":"apple → an apple"},{"case":"Danh từ cụ thể","rule":"Dùng **the**","example":"book → the book"}],"signals":["specific","general","previously mentioned","a","an","the","lần đầu nhắc đến","đã xác định","zero article"],"examples":[{"en":"I have a car.","vi":"Tôi có một chiếc xe.","note":"Dùng **a** vì danh từ 'car' không cụ thể.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"a","start":7,"end":8,"role":"article"},{"word":"car","start":9,"end":12,"role":"noun"}]},{"en":"I am reading an article.","vi":"Tôi đang đọc một bài viết.","note":"Dùng **an** vì danh từ 'article' bắt đầu bằng nguyên âm.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"am","start":2,"end":4,"role":"auxiliary"},{"word":"reading","start":5,"end":12,"role":"verb"},{"word":"an","start":13,"end":15,"role":"article"},{"word":"article","start":16,"end":23,"role":"noun"}]},{"en":"I saw the movie yesterday.","vi":"Tôi xem phim đó vào ngày hôm qua.","note":"Dùng **the** vì danh từ 'movie' đã được nhắc đến trước đó.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"saw","start":2,"end":5,"role":"verb"},{"word":"the","start":6,"end":9,"role":"article"},{"word":"movie","start":10,"end":15,"role":"noun"},{"word":"yesterday","start":16,"end":25,"role":"adverb"}]},{"en":"The book on the table is mine.","vi":"Cuốn sách trên bàn là của tôi.","note":"Dùng **the** vì danh từ 'book' cụ thể.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"book","start":4,"end":8,"role":"noun"},{"word":"on","start":9,"end":11,"role":"preposition"},{"word":"the","start":12,"end":15,"role":"article"},{"word":"table","start":16,"end":21,"role":"noun"},{"word":"is","start":22,"end":24,"role":"auxiliary"},{"word":"mine","start":25,"end":29,"role":"pronoun"}]},{"en":"I have a brother and a sister.","vi":"Tôi có một anh trai và một chị gái.","note":"Dùng **a** vì danh từ 'brother' và 'sister' không cụ thể.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"a","start":7,"end":8,"role":"article"},{"word":"brother","start":9,"end":16,"role":"noun"},{"word":"and","start":17,"end":20,"role":"conjunction"},{"word":"a","start":21,"end":22,"role":"article"},{"word":"sister","start":23,"end":29,"role":"noun"}]},{"en":"The teacher gave us an assignment.","vi":"Giáo viên đã giao cho chúng tôi một nhiệm vụ.","note":"Dùng **an** vì danh từ 'assignment' bắt đầu bằng nguyên âm.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"teacher","start":4,"end":11,"role":"noun"},{"word":"gave","start":12,"end":16,"role":"verb"},{"word":"us","start":17,"end":19,"role":"pronoun"},{"word":"an","start":20,"end":22,"role":"article"},{"word":"assignment","start":23,"end":33,"role":"noun"}]}],"mistakes":[{"wrong":"I have the book.","right":"I have a book.","why":"Chưa xác định danh từ 'book' là cụ thể hay không."},{"wrong":"I am reading an book.","right":"I am reading a book.","vi":"Sai vì danh từ 'book' bắt đầu bằng phụ âm, dùng **a**.","why":"Danh từ 'book' bắt đầu bằng phụ âm, nên dùng **a**."},{"wrong":"I saw dog.","right":"I saw a dog.","why":"Chưa xác định danh từ 'dog' là cụ thể hay không."},{"wrong":"I bought apple.","right":"I bought an apple.","why":"Danh từ đếm được số ít apple cần mạo từ; dùng an trước âm nguyên âm."},{"wrong":"Sun is bright today.","right":"The sun is bright today.","why":"Dùng the với sự vật duy nhất và đã được xác định như the sun."}],"tips":"**Mẹo nhớ:** Dùng **a** trước danh từ bắt đầu bằng phụ âm, dùng **an** trước danh từ bắt đầu bằng nguyên âm. Dùng **the** cho danh từ cụ thể hoặc đã được nhắc đến trước đó.","comparison":"**Sự khác biệt giữa a, an, và the:** Dùng **a** và **an** cho danh từ không cụ thể, dùng **the** cho danh từ cụ thể hoặc đã được nhắc đến trước đó.","timeline":null}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"I have ___ book.","opts":["a","an","the"],"answer":"a","fb":"Book bắt đầu bằng âm phụ âm; nhắc lần đầu dùng a."},{"type":"mcq","q":"She has ___ apple.","opts":["an","a","some"],"answer":"an","fb":"Apple bắt đầu bằng âm nguyên âm; dùng an."},{"type":"fill","q":"He is ___ teacher. (a / an)","answer":["a"],"fb":"Teacher bắt đầu bằng âm /t/; dùng a."},{"type":"mcq","q":"I saw a dog. ___ dog was black.","opts":["The","A","An"],"answer":"The","fb":"Đã nhắc a dog rồi, lần sau dùng the dog."},{"type":"fill","q":"This is ___ orange. (a / an)","answer":["an"],"fb":"Orange bắt đầu bằng âm nguyên âm; dùng an."},{"type":"mcq","q":"Choose the correct phrase.","opts":["an umbrella","a umbrella","the umbrella for the first mention"],"answer":"an umbrella","fb":"Umbrella bắt đầu bằng âm nguyên âm; lần đầu nhắc dùng an umbrella."},{"type":"fill","q":"Please close ___ door. (the / a; both people know which door)","answer":["the"],"fb":"Hai người đều biết cánh cửa nào nên dùng the."},{"type":"mcq","q":"She bought a pen. Where is ___ pen now?","opts":["the","a","an"],"answer":"the","fb":"Chiếc bút đã được xác định ở câu trước."}]$grammar$::jsonb, 'ai-golden', 8
from public.grammar_topics t where t.slug = 'articles'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 09. present-simple
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('present-simple', 'Present Simple', 'Thì Hiện tại đơn', 'beginner', 9)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Hiện tại đơn', '**Thì Hiện tại đơn** (Present Simple) là một trong những thì cơ bản của tiếng Anh, được sử dụng để diễn tả những hành động **lặp đi lặp lại**, những **sự thật hiển nhiên**, hoặc **lịch trình cố định**. Đây là thì nền tảng đầu tiên mà mọi người học tiếng Anh cần nắm vững.', $grammar$[{"en":"She teaches English every day.","vi":"Cô ấy dạy tiếng Anh mỗi ngày.","note":"Khẳng định, ngôi thứ 3 số ít → teaches.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"teaches","start":4,"end":11,"role":"verb"},{"word":"English","start":12,"end":19,"role":"noun"},{"word":"every","start":20,"end":25,"role":"determiner"},{"word":"day","start":26,"end":29,"role":"noun"}]},{"en":"They don't watch TV on weekdays.","vi":"Họ không xem TV vào các ngày trong tuần.","note":"Phủ định với don't + V nguyên thể.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"don't","start":5,"end":10,"role":"auxiliary"},{"word":"watch","start":11,"end":16,"role":"verb"},{"word":"TV","start":17,"end":19,"role":"noun"},{"word":"on","start":20,"end":22,"role":"preposition"},{"word":"weekdays","start":23,"end":31,"role":"noun"}]},{"en":"Does he play football?","vi":"Anh ấy có chơi bóng đá không?","note":"Nghi vấn với Does + V nguyên thể.","annotations":[{"word":"Does","start":0,"end":4,"role":"auxiliary"},{"word":"he","start":5,"end":7,"role":"pronoun"},{"word":"play","start":8,"end":12,"role":"verb"},{"word":"football","start":13,"end":21,"role":"noun"}]},{"en":"Water boils at 100°C.","vi":"Nước sôi ở 100 độ C.","note":"Sự thật hiển nhiên.","annotations":[{"word":"Water","start":0,"end":5,"role":"noun"},{"word":"boils","start":6,"end":11,"role":"verb"},{"word":"at","start":12,"end":14,"role":"preposition"},{"word":"100°C","start":15,"end":20,"role":"other"}]},{"en":"I usually get up at six.","vi":"Tôi thường thức dậy lúc 6 giờ.","note":"Trạng từ tần suất 'usually' đứng trước động từ.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"usually","start":2,"end":9,"role":"adverb"},{"word":"get","start":10,"end":13,"role":"verb"},{"word":"up","start":14,"end":16,"role":"adverb"},{"word":"at","start":17,"end":19,"role":"preposition"},{"word":"six","start":20,"end":23,"role":"other"}]},{"en":"My father works in a bank.","vi":"Bố tôi làm việc ở ngân hàng.","note":"Thói quen / sự thật về công việc.","annotations":[{"word":"My","start":0,"end":2,"role":"determiner"},{"word":"father","start":3,"end":9,"role":"noun"},{"word":"works","start":10,"end":15,"role":"verb"},{"word":"in","start":16,"end":18,"role":"preposition"},{"word":"a","start":19,"end":20,"role":"article"},{"word":"bank","start":21,"end":25,"role":"noun"}]},{"en":"We don't live in Hanoi.","vi":"Chúng tôi không sống ở Hà Nội.","note":"Phủ định ngôi số nhiều.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"don't","start":3,"end":8,"role":"auxiliary"},{"word":"live","start":9,"end":13,"role":"verb"},{"word":"in","start":14,"end":16,"role":"preposition"},{"word":"Hanoi","start":17,"end":22,"role":"noun"}]},{"en":"What time does the shop open?","vi":"Cửa hàng mở cửa lúc mấy giờ?","note":"Câu hỏi Wh- + does.","annotations":[{"word":"What","start":0,"end":4,"role":"determiner"},{"word":"time","start":5,"end":9,"role":"noun"},{"word":"does","start":10,"end":14,"role":"auxiliary"},{"word":"the","start":15,"end":18,"role":"article"},{"word":"shop","start":19,"end":23,"role":"noun"},{"word":"open","start":24,"end":28,"role":"verb"}]}]$grammar$::jsonb, $grammar${"definition":"**Thì Hiện tại đơn** (Present Simple) là một trong những thì cơ bản của tiếng Anh, được sử dụng để diễn tả những hành động **lặp đi lặp lại**, những **sự thật hiển nhiên**, hoặc **lịch trình cố định**. Đây là thì nền tảng đầu tiên mà mọi người học tiếng Anh cần nắm vững.","usage":[{"icon":"🔁","label":"Thói quen, hành động lặp lại","en":"I drink coffee every morning.","vi":"Tôi uống cà phê mỗi sáng."},{"icon":"🌍","label":"Sự thật hiển nhiên, chân lý","en":"The Earth revolves around the Sun.","vi":"Trái đất quay quanh Mặt trời."},{"icon":"🕐","label":"Lịch trình, thời gian biểu cố định","en":"The bus leaves at 7 a.m.","vi":"Xe buýt khởi hành lúc 7 giờ sáng."},{"icon":"💭","label":"Cảm xúc, sở hữu, trạng thái","en":"She loves reading books. I have a pet cat.","vi":"Cô ấy yêu đọc sách. Tôi có một con mèo cưng."}],"formula":{"rows":[{"form":"(+) Khẳng định","base":"S + V(nguyên thể)","third":"S + V-s/es"},{"form":"(−) Phủ định","base":"S + don't + V","third":"S + doesn't + V"},{"form":"(?) Nghi vấn","base":"Do + S + V?","third":"Does + S + V?"}],"note":"He / She / It → thêm -s/es ở dạng khẳng định, nhưng dùng doesn't / Does (động từ về nguyên thể)."},"rules":[{"case":"Đa số động từ","rule":"+ s","example":"work → works"},{"case":"Tận cùng o, s, x, ch, sh","rule":"+ es","example":"go → goes · watch → watches"},{"case":"Phụ âm + y (chữ trước y là phụ âm)","rule":"đổi y → ies","example":"study → studies (d = phụ âm)"},{"case":"Nguyên âm + y (a,e,i,o,u trước y)","rule":"giữ y, + s","example":"play → plays (a = nguyên âm)"}],"signals":["always","usually","often","sometimes","rarely","never","every day","on Mondays","twice a week"],"examples":[{"en":"She teaches English every day.","vi":"Cô ấy dạy tiếng Anh mỗi ngày.","note":"Khẳng định, ngôi thứ 3 số ít → teaches.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"teaches","start":4,"end":11,"role":"verb"},{"word":"English","start":12,"end":19,"role":"noun"},{"word":"every","start":20,"end":25,"role":"determiner"},{"word":"day","start":26,"end":29,"role":"noun"}]},{"en":"They don't watch TV on weekdays.","vi":"Họ không xem TV vào các ngày trong tuần.","note":"Phủ định với don't + V nguyên thể.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"don't","start":5,"end":10,"role":"auxiliary"},{"word":"watch","start":11,"end":16,"role":"verb"},{"word":"TV","start":17,"end":19,"role":"noun"},{"word":"on","start":20,"end":22,"role":"preposition"},{"word":"weekdays","start":23,"end":31,"role":"noun"}]},{"en":"Does he play football?","vi":"Anh ấy có chơi bóng đá không?","note":"Nghi vấn với Does + V nguyên thể.","annotations":[{"word":"Does","start":0,"end":4,"role":"auxiliary"},{"word":"he","start":5,"end":7,"role":"pronoun"},{"word":"play","start":8,"end":12,"role":"verb"},{"word":"football","start":13,"end":21,"role":"noun"}]},{"en":"Water boils at 100°C.","vi":"Nước sôi ở 100 độ C.","note":"Sự thật hiển nhiên.","annotations":[{"word":"Water","start":0,"end":5,"role":"noun"},{"word":"boils","start":6,"end":11,"role":"verb"},{"word":"at","start":12,"end":14,"role":"preposition"},{"word":"100°C","start":15,"end":20,"role":"other"}]},{"en":"I usually get up at six.","vi":"Tôi thường thức dậy lúc 6 giờ.","note":"Trạng từ tần suất 'usually' đứng trước động từ.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"usually","start":2,"end":9,"role":"adverb"},{"word":"get","start":10,"end":13,"role":"verb"},{"word":"up","start":14,"end":16,"role":"adverb"},{"word":"at","start":17,"end":19,"role":"preposition"},{"word":"six","start":20,"end":23,"role":"other"}]},{"en":"My father works in a bank.","vi":"Bố tôi làm việc ở ngân hàng.","note":"Thói quen / sự thật về công việc.","annotations":[{"word":"My","start":0,"end":2,"role":"determiner"},{"word":"father","start":3,"end":9,"role":"noun"},{"word":"works","start":10,"end":15,"role":"verb"},{"word":"in","start":16,"end":18,"role":"preposition"},{"word":"a","start":19,"end":20,"role":"article"},{"word":"bank","start":21,"end":25,"role":"noun"}]},{"en":"We don't live in Hanoi.","vi":"Chúng tôi không sống ở Hà Nội.","note":"Phủ định ngôi số nhiều.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"don't","start":3,"end":8,"role":"auxiliary"},{"word":"live","start":9,"end":13,"role":"verb"},{"word":"in","start":14,"end":16,"role":"preposition"},{"word":"Hanoi","start":17,"end":22,"role":"noun"}]},{"en":"What time does the shop open?","vi":"Cửa hàng mở cửa lúc mấy giờ?","note":"Câu hỏi Wh- + does.","annotations":[{"word":"What","start":0,"end":4,"role":"determiner"},{"word":"time","start":5,"end":9,"role":"noun"},{"word":"does","start":10,"end":14,"role":"auxiliary"},{"word":"the","start":15,"end":18,"role":"article"},{"word":"shop","start":19,"end":23,"role":"noun"},{"word":"open","start":24,"end":28,"role":"verb"}]}],"mistakes":[{"wrong":"He go to school.","right":"He goes to school.","why":"Quên thêm -s/es với He/She/It ở dạng khẳng định."},{"wrong":"She doesn't likes tea.","right":"She doesn't like tea.","why":"Sau doesn't/don't, động từ trở về NGUYÊN thể."},{"wrong":"Do she work here?","right":"Does she work here?","why":"He/She/It dùng Does, không dùng Do."},{"wrong":"I am play tennis every day.","right":"I play tennis every day.","why":"Hiện tại đơn không dùng 'am/is/are' với động từ thường."},{"wrong":"She have a dog.","right":"She has a dog.","why":"Với chủ ngữ ngôi thứ ba số ít, động từ have đổi thành has."},{"wrong":"He not like sushi.","right":"He does not like sushi.","why":"Câu phủ định hiện tại đơn với He/She/It cần does not + động từ nguyên thể."}],"tips":"**Mẹo nhớ:** \"He / She / It → thêm s\". Nhưng khi đã có **does / doesn't** thì động từ được \"nghỉ\", trở về nguyên thể. Trạng từ tần suất (always, usually, never...) đứng **trước** động từ thường nhưng **sau** động từ to be.","comparison":"**Hiện tại đơn vs Hiện tại tiếp diễn:** Đơn = sự thật / thói quen, mang tính lâu dài (*Water boils at 100°C* — chân lý). Tiếp diễn = tạm thời, đang diễn ra quanh lúc nói (*The water is boiling — be careful!* — ngay lúc này).","timeline":{"caption":"Ví dụ \"I drink coffee every morning\" — mỗi ☕ là một buổi sáng, lặp lại đều quanh hiện tại, không quan tâm bắt đầu hay kết thúc.","points":[{"label":"☕ T2","note":"quá khứ"},{"label":"☕ T3","note":""},{"label":"☕ hôm nay","note":"hiện tại"},{"label":"☕ T6","note":""},{"label":"☕ T7","note":"tương lai"}]}}$grammar$::jsonb, $grammar$[{"type":"fill","q":"My mother ____ (be) a nurse.","opts":[],"answer":"is","fb":"mother = một người → is"},{"type":"fill","q":"Lan ____ (come) from Thai Nguyen.","opts":[],"answer":"comes","fb":"Lan = một người → thêm -s"},{"type":"fill","q":"They ____ (not / be) at home now.","opts":[],"answer":"aren't","fb":"câu có be → thêm not vào be"},{"type":"fill","q":"My brother ____ (not / do) his homework at night.","opts":[],"answer":"doesn't do","fb":"V thường + he → doesn't + V để trơ"},{"type":"fill","q":"I ____ (be) very hungry now.","opts":[],"answer":"am","fb":"I luôn đi với am"},{"type":"fill","q":"It ____ (rain) a lot in my hometown.","opts":[],"answer":"rains","fb":"It = một thứ → thêm -s"},{"type":"fill","q":"____ (be) your school big?","opts":[],"answer":"Is","fb":"câu hỏi có be → be lên trước chủ ngữ"},{"type":"fill","q":"My brother ____ (get) up at 6 a.m. every morning.","opts":[],"answer":"gets","fb":"every morning · He → -s"},{"type":"fill","q":"____ your sister ____ (study) English every day?","opts":[],"answer":"Does … study","fb":"every day · she → Does + V trơ"},{"type":"fill","q":"I will text you when I ____ (get) to Ha Noi.","opts":[],"answer":"get","fb":"vế when nói tương lai → hiện tại đơn, cấm will"},{"type":"fill","q":"Don't turn off the computer until I ____ (say) so.","opts":[],"answer":"say","fb":"vế until cấm will → hiện tại đơn"},{"type":"fill","q":"She ____ (call) you tomorrow as soon as she ____ (receive) the letter.","opts":[],"answer":"will call / receives","fb":"as soon as nói tương lai → hiện tại đơn, vế kia mới will"},{"type":"fill","q":"Violets ____ (bloom) in spring.","opts":[],"answer":"bloom","fb":"sự thật hiển nhiên → hiện tại đơn"},{"type":"fill","q":"I always ____ (buy) lottery tickets but I never ____ (win) anything.","opts":[],"answer":"buy / win","fb":"always, never = thói quen → hiện tại đơn"},{"type":"fill","q":"This kind of cloth ____ (not / use) to make shirts.","opts":[],"answer":"isn't used","fb":"hiện tại đơn phủ định → isn't + V3"},{"type":"fill","q":"People grow rice in the Mekong Delta.  →  Rice ____ in the Mekong Delta.","opts":[],"answer":"is grown","fb":"People → cắt by · hiện tại đơn → is + V3"},{"type":"fill","q":"She is tired of ____ (do) the same thing every day.","opts":[],"answer":"doing","fb":"of là giới từ → V-ing"},{"type":"fill","q":"I was born ____ October 12th.","opts":[],"answer":"on","fb":"ngày cụ thể → on"},{"type":"fill","q":"We often have a big meal ____ Christmas.","opts":[],"answer":"at","fb":"Christmas nằm trong nhóm at"},{"type":"fill","q":"There are some new books ____ the table.","opts":[],"answer":"on","fb":"nằm trên bề mặt bàn → on"},{"type":"fill","q":"My uncle has lived ____ Da Nang for ten years.","opts":[],"answer":"in","fb":"thành phố → in"},{"type":"fill","q":"The train to Hue leaves ____ half past six.","opts":[],"answer":"at","fb":"giờ chính xác → at"},{"type":"fill","q":"My father usually reads the news ____ the morning.","opts":[],"answer":"in","fb":"buổi trong ngày → in"},{"type":"fill","q":"She is famous ____ her beautiful voice.","opts":[],"answer":"for","fb":"famous for = nổi tiếng vì cái gì"},{"type":"fill","q":"I'm not very good ____ remembering names.","opts":[],"answer":"at","fb":"good at = giỏi việc gì"},{"type":"fill","q":"____ the high salary, he decided to quit the job.","opts":[],"answer":"Despite / In spite of","fb":"the high salary là cụm danh từ → despite"},{"type":"fill","q":"____ (Despite of / Despite) the loud music next door, the baby slept well.","opts":[],"answer":"Despite","fb":"despite không bao giờ đi với of"},{"type":"fill","q":"The train was delayed for two hours. ____, we missed the wedding.","opts":[],"answer":"Therefore","fb":"đứng đầu câu mới và nêu kết quả → Therefore"},{"type":"fill","q":"Edison's ____ (invent) of the light bulb changed the world.","opts":[],"answer":"invention","fb":"sau sở hữu Edison's → cần danh từ"},{"type":"fill","q":"My grandmother is still very ____ (health) at eighty.","opts":[],"answer":"healthy","fb":"sau to be → cần tính từ"},{"type":"fill","q":"This machine is out of order, ____?","opts":[],"answer":"isn't it","fb":"vế trước khẳng định → đuôi phủ định"},{"type":"fill","q":"Everybody enjoyed the trip, ____?","opts":[],"answer":"didn't they","fb":"vế trước khẳng định ở quá khứ → didn't, và Everybody thay bằng they"},{"type":"fill","q":"Sắp xếp: My father drives a (Japanese / small / new) car.","opts":[],"answer":"a small new Japanese car","fb":"kích cỡ → tuổi → xuất xứ"},{"type":"fill","q":"Sắp xếp: They live in a (wooden / lovely / old) house.","opts":[],"answer":"a lovely old wooden house","fb":"ý kiến → tuổi → chất liệu"},{"type":"fill","q":"A. confused   B. faced   C. cried   D. defined","opts":[],"answer":"B. faced","fb":"faced: trước -ed là /s/ → /t/ · ba từ kia → /d/"},{"type":"fill","q":"A. agreed   B. kissed   C. liked   D. coughed","opts":[],"answer":"A. agreed","fb":"agreed: trước -ed là nguyên âm → /d/ · ba từ kia → /t/"},{"type":"fill","q":"A. cats   B. tapes   C. rides   D. cooks","opts":[],"answer":"C. rides","fb":"rides: trước -s là /d/ → /z/ · ba từ kia → /s/"},{"type":"fill","q":"A. hours   B. fathers   C. brothers   D. thinks","opts":[],"answer":"D. thinks","fb":"thinks: trước -s là /k/ → /s/ · ba từ kia → /z/"},{"type":"fill","q":"A. resources   B. stages   C. preserves   D. focuses","opts":[],"answer":"C. preserves","fb":"preserves: trước -s là /v/ → /z/ · ba từ kia sau âm rít /s/ /dʒ/ → /ɪz/"},{"type":"fill","q":"A. paper   B. police   C. people   D. cinema","opts":[],"answer":"B. police","fb":"police nhấn âm 2 · ba từ kia nhấn âm 1"},{"type":"fill","q":"A. problem   B. invent   C. destroy   D. demand","opts":[],"answer":"A. problem","fb":"problem là danh từ 2 âm tiết nhấn âm 1 · ba từ kia là động từ nhấn âm 2"},{"type":"fill","q":"A. automatic   B. reasonable   C. mathematics   D. preservation","opts":[],"answer":"B. reasonable","fb":"-ic / -ics / -tion kéo trọng âm về ngay trước (âm 3) · reasonable nhấn âm 1"},{"type":"fill","q":"A. measurement   B. information   C. economic   D. engineer","opts":[],"answer":"A. measurement","fb":"-tion, -ic, -eer đều đẩy trọng âm ra âm 3 · measurement nhấn âm 1"},{"type":"fill","q":"You have finished your homework, ____?  (A do you · B have you · C haven't you · D don't you)","opts":[],"answer":"C haven't you","fb":"Vế trước khẳng định với have nên đuôi hỏi là haven't you · buổi 23"},{"type":"fill","q":"Ba ____ to the library every Sunday.  (A go · B goes · C is going · D went)","opts":[],"answer":"B goes","fb":"every Sunday và Ba là số ít → hiện tại đơn thêm -es · buổi 2"}]$grammar$::jsonb, 'ai-golden', 9
from public.grammar_topics t where t.slug = 'present-simple'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 10. have-got
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('have-got', 'Have got / Has got', 'Cấu trúc have got / has got', 'beginner', 10)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Cấu trúc have got / has got', '**Have got / has got** có nghĩa là **có, sở hữu**. Cấu trúc này rất phổ biến trong tiếng Anh Anh và thường dùng để nói về đồ vật, gia đình, đặc điểm cơ thể hoặc tình trạng hiện tại. **Have got** đi với I/you/we/they; **has got** đi với he/she/it.', $grammar$[{"en":"I have got a new bike.","vi":"Tôi có một chiếc xe đạp mới.","note":"I đi với have got.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"auxiliary"},{"word":"got","start":7,"end":10,"role":"verb"},{"word":"a","start":11,"end":12,"role":"article"},{"word":"new","start":13,"end":16,"role":"adjective"},{"word":"bike","start":17,"end":21,"role":"noun"}]},{"en":"She has got two sisters.","vi":"Cô ấy có hai chị/em gái.","note":"She đi với has got.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"has","start":4,"end":7,"role":"auxiliary"},{"word":"got","start":8,"end":11,"role":"verb"},{"word":"two","start":12,"end":15,"role":"determiner"},{"word":"sisters","start":16,"end":23,"role":"noun"}]},{"en":"We haven't got any milk.","vi":"Chúng tôi không có chút sữa nào.","note":"Haven't got là dạng phủ định của have got.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"haven't","start":3,"end":10,"role":"auxiliary"},{"word":"got","start":11,"end":14,"role":"verb"},{"word":"any","start":15,"end":18,"role":"determiner"},{"word":"milk","start":19,"end":23,"role":"noun"}]},{"en":"Has he got a phone?","vi":"Cậu ấy có điện thoại không?","note":"Đưa has lên trước he để tạo câu hỏi.","annotations":[{"word":"Has","start":0,"end":3,"role":"auxiliary"},{"word":"he","start":4,"end":6,"role":"pronoun"},{"word":"got","start":7,"end":10,"role":"verb"},{"word":"a","start":11,"end":12,"role":"article"},{"word":"phone","start":13,"end":18,"role":"noun"}]},{"en":"Have they got blue eyes?","vi":"Họ có đôi mắt xanh không?","note":"They dùng have trong câu hỏi.","annotations":[{"word":"Have","start":0,"end":4,"role":"auxiliary"},{"word":"they","start":5,"end":9,"role":"pronoun"},{"word":"got","start":10,"end":13,"role":"verb"},{"word":"blue","start":14,"end":18,"role":"adjective"},{"word":"eyes","start":19,"end":23,"role":"noun"}]},{"en":"My dog has got a long tail.","vi":"Con chó của tôi có một chiếc đuôi dài.","note":"My dog là một con vật nên dùng has got.","annotations":[{"word":"My","start":0,"end":2,"role":"determiner"},{"word":"dog","start":3,"end":6,"role":"noun"},{"word":"has","start":7,"end":10,"role":"auxiliary"},{"word":"got","start":11,"end":14,"role":"verb"},{"word":"a","start":15,"end":16,"role":"article"},{"word":"long","start":17,"end":21,"role":"adjective"},{"word":"tail","start":22,"end":26,"role":"noun"}]},{"en":"I've got a headache.","vi":"Tôi bị đau đầu.","note":"I've got là dạng rút gọn của I have got.","annotations":[{"word":"I've","start":0,"end":4,"role":"auxiliary"},{"word":"got","start":5,"end":8,"role":"verb"},{"word":"a","start":9,"end":10,"role":"article"},{"word":"headache","start":11,"end":19,"role":"noun"}]},{"en":"She hasn't got much time.","vi":"Cô ấy không có nhiều thời gian.","note":"Hasn't got là dạng phủ định của has got.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"hasn't","start":4,"end":10,"role":"auxiliary"},{"word":"got","start":11,"end":14,"role":"verb"},{"word":"much","start":15,"end":19,"role":"determiner"},{"word":"time","start":20,"end":24,"role":"noun"}]}]$grammar$::jsonb, $grammar${"definition":"**Have got / has got** có nghĩa là **có, sở hữu**. Cấu trúc này rất phổ biến trong tiếng Anh Anh và thường dùng để nói về đồ vật, gia đình, đặc điểm cơ thể hoặc tình trạng hiện tại. **Have got** đi với I/you/we/they; **has got** đi với he/she/it.","usage":[{"icon":"🎒","label":"Nói về đồ vật mình sở hữu","en":"I have got a new bag.","vi":"Tôi có một chiếc túi mới."},{"icon":"👨‍👩‍👧","label":"Nói về gia đình và các mối quan hệ","en":"She has got two brothers.","vi":"Cô ấy có hai anh/em trai."},{"icon":"👀","label":"Miêu tả đặc điểm cơ thể","en":"He has got brown eyes.","vi":"Cậu ấy có đôi mắt nâu."},{"icon":"🤕","label":"Nói tình trạng hoặc vấn đề hiện tại","en":"I have got a headache.","vi":"Tôi bị đau đầu."}],"formula":{"rows":[{"form":"(+) Khẳng định","base":"I/You/We/They + have got","third":"He/She/It + has got"},{"form":"(−) Phủ định","base":"I/You/We/They + haven't got","third":"He/She/It + hasn't got"},{"form":"(?) Nghi vấn","base":"Have + I/you/we/they + got...?","third":"Has + he/she/it + got...?"}],"note":"Trong câu hỏi và phủ định, have/has hoạt động như trợ động từ. Không dùng do/does với cấu trúc have got."},"rules":[{"case":"I, You, We, They","rule":"dùng have got","example":"We have got a car."},{"case":"He, She, It hoặc một người/vật","rule":"dùng has got","example":"Mai has got a bicycle."},{"case":"Dạng phủ định","rule":"haven't got / hasn't got","example":"They haven't got a map. He hasn't got a map."},{"case":"Dạng rút gọn khẳng định","rule":"'ve got / 's got","example":"I've got a pen. She's got a pen."}],"signals":["have got","has got","'ve got","'s got","haven't got","hasn't got"],"examples":[{"en":"I have got a new bike.","vi":"Tôi có một chiếc xe đạp mới.","note":"I đi với have got.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"auxiliary"},{"word":"got","start":7,"end":10,"role":"verb"},{"word":"a","start":11,"end":12,"role":"article"},{"word":"new","start":13,"end":16,"role":"adjective"},{"word":"bike","start":17,"end":21,"role":"noun"}]},{"en":"She has got two sisters.","vi":"Cô ấy có hai chị/em gái.","note":"She đi với has got.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"has","start":4,"end":7,"role":"auxiliary"},{"word":"got","start":8,"end":11,"role":"verb"},{"word":"two","start":12,"end":15,"role":"determiner"},{"word":"sisters","start":16,"end":23,"role":"noun"}]},{"en":"We haven't got any milk.","vi":"Chúng tôi không có chút sữa nào.","note":"Haven't got là dạng phủ định của have got.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"haven't","start":3,"end":10,"role":"auxiliary"},{"word":"got","start":11,"end":14,"role":"verb"},{"word":"any","start":15,"end":18,"role":"determiner"},{"word":"milk","start":19,"end":23,"role":"noun"}]},{"en":"Has he got a phone?","vi":"Cậu ấy có điện thoại không?","note":"Đưa has lên trước he để tạo câu hỏi.","annotations":[{"word":"Has","start":0,"end":3,"role":"auxiliary"},{"word":"he","start":4,"end":6,"role":"pronoun"},{"word":"got","start":7,"end":10,"role":"verb"},{"word":"a","start":11,"end":12,"role":"article"},{"word":"phone","start":13,"end":18,"role":"noun"}]},{"en":"Have they got blue eyes?","vi":"Họ có đôi mắt xanh không?","note":"They dùng have trong câu hỏi.","annotations":[{"word":"Have","start":0,"end":4,"role":"auxiliary"},{"word":"they","start":5,"end":9,"role":"pronoun"},{"word":"got","start":10,"end":13,"role":"verb"},{"word":"blue","start":14,"end":18,"role":"adjective"},{"word":"eyes","start":19,"end":23,"role":"noun"}]},{"en":"My dog has got a long tail.","vi":"Con chó của tôi có một chiếc đuôi dài.","note":"My dog là một con vật nên dùng has got.","annotations":[{"word":"My","start":0,"end":2,"role":"determiner"},{"word":"dog","start":3,"end":6,"role":"noun"},{"word":"has","start":7,"end":10,"role":"auxiliary"},{"word":"got","start":11,"end":14,"role":"verb"},{"word":"a","start":15,"end":16,"role":"article"},{"word":"long","start":17,"end":21,"role":"adjective"},{"word":"tail","start":22,"end":26,"role":"noun"}]},{"en":"I've got a headache.","vi":"Tôi bị đau đầu.","note":"I've got là dạng rút gọn của I have got.","annotations":[{"word":"I've","start":0,"end":4,"role":"auxiliary"},{"word":"got","start":5,"end":8,"role":"verb"},{"word":"a","start":9,"end":10,"role":"article"},{"word":"headache","start":11,"end":19,"role":"noun"}]},{"en":"She hasn't got much time.","vi":"Cô ấy không có nhiều thời gian.","note":"Hasn't got là dạng phủ định của has got.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"hasn't","start":4,"end":10,"role":"auxiliary"},{"word":"got","start":11,"end":14,"role":"verb"},{"word":"much","start":15,"end":19,"role":"determiner"},{"word":"time","start":20,"end":24,"role":"noun"}]}],"mistakes":[{"wrong":"She have got a cat.","right":"She has got a cat.","why":"She đi với has got, không đi với have got."},{"wrong":"I haven't a bike.","right":"I haven't got a bike.","why":"Trong cấu trúc have got, không được bỏ got."},{"wrong":"Does he have got a car?","right":"Has he got a car?","why":"Câu hỏi với have got không dùng do/does; đưa have/has lên đầu."},{"wrong":"He hasn't got no money.","right":"He hasn't got any money.","why":"Sau câu phủ định, dùng any thay vì no để tránh hai từ phủ định."}],"tips":"**Mẹo nhớ:** **He/She/It has got**; các chủ ngữ còn lại dùng **have got**. Hỏi thì đưa have/has lên đầu; phủ định đổi thành **haven't/hasn't got**.","comparison":"**Have got và have:** Cả *I have got a car* và *I have a car* đều nghĩa là “Tôi có một chiếc xe”. Với **have got**, hỏi *Have you got...?*; với **have** theo cách dùng phổ biến, hỏi *Do you have...?*. Không trộn hai mẫu thành *Do you have got...?*.","timeline":null}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"I ___ got a pencil.","opts":["have","has","am"],"answer":"have","fb":"I đi với have got."},{"type":"mcq","q":"Nam ___ got a new backpack.","opts":["have","has","is"],"answer":"has","fb":"Nam là một người, tương đương he, nên dùng has got."},{"type":"fill","q":"We ___ got any homework today. (phủ định, dạng rút gọn)","answer":["haven't","have not"],"fb":"We dùng haven't got hoặc have not got."},{"type":"fill","q":"___ she got a sister? (Have/Has)","answer":["has"],"fb":"She đi với has; trong câu hỏi đưa Has lên đầu."},{"type":"fill","q":"My cat ___ got green eyes. (have/has)","answer":["has"],"fb":"My cat là một con vật, tương đương it, nên dùng has got."},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"They have got two children.\"","answer":true,"fb":"ĐÚNG. They đi với have got."},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"He have got a cold.\"","answer":false,"fb":"SAI. He phải đi với has got."},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["I've got a question.","She has got a car.","We has got a problem."],"answer":"We has got a problem.","fb":"We phải đi với have got."},{"type":"mcq","q":"Dạng câu hỏi đúng của \"He has got a bike.\" là:","opts":["Has he got a bike?","Does he has got a bike?","Have he got a bike?"],"answer":"Has he got a bike?","fb":"Đưa has lên trước he; không dùng does."},{"type":"mcq","q":"Dạng phủ định đúng của \"She has got time.\" là:","opts":["She hasn't got time.","She doesn't has got time.","She not has got time."],"answer":"She hasn't got time.","fb":"Has not rút gọn thành hasn't; giữ got."},{"type":"fill","q":"Viết dạng rút gọn: I have got a dog. → ___ got a dog.","answer":["I've","i've"],"fb":"I have rút gọn thành I've."},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["Have you got a pen?","Has Mai got a brother?","Do they have got a car?"],"answer":"Do they have got a car?","fb":"Không dùng do với have got. Câu đúng là \"Have they got a car?\""},{"type":"multiple_choice","question":"My parents ___ got a big house. Choose the correct **form**.","options":["have","has","haven't","hasn't"],"correct_answer":"have","explanation":"Chủ ngữ \"My parents\" (bố mẹ tôi) là số nhiều (tương đương \"they\"), vì vậy chúng ta dùng \"have got\". \"Has got\" dùng cho chủ ngữ số ít (he/she/it).","difficulty":1},{"type":"multiple_choice","question":"The old car ___ got a flat tire. Choose the correct **verb**.","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Chủ ngữ \"The old car\" (chiếc ô tô cũ) là số ít (tương đương \"it\"), vì vậy chúng ta dùng \"has got\".","difficulty":1},{"type":"multiple_choice","question":"We ___ got enough time for the movie. Choose the correct **negative form**.","options":["haven't","hasn't","don't","doesn't"],"correct_answer":"haven't","explanation":"Chủ ngữ \"We\" (chúng tôi) đi với \"have got\", dạng phủ định là \"haven't got\". Các lựa chọn khác không đúng với chủ ngữ \"We\" hoặc không phải cấu trúc \"have got\".","difficulty":2},{"type":"multiple_choice","question":"My sister ___ got a new phone. Choose the correct **short form**.","options":["'ve","'s","have","has"],"correct_answer":"'s","explanation":"Chủ ngữ \"My sister\" (chị gái tôi) là số ít (tương đương \"she\"), vì vậy dùng \"has got\". Dạng rút gọn của \"has got\" là \"'s got\".","difficulty":2},{"type":"multiple_choice","question":"___ you got any plans for the weekend? Choose the correct **auxiliary verb**.","options":["Has","Have","Do","Does"],"correct_answer":"Have","explanation":"Chủ ngữ \"you\" (bạn) đi với \"have got\". Trong câu hỏi, \"Have\" đứng đầu câu. \"Do/Does\" không dùng với cấu trúc \"have got\".","difficulty":1},{"type":"multiple_choice","question":"She ___ got long, blonde hair. Choose the correct **verb**.","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Chủ ngữ \"She\" (cô ấy) là số ít, vì vậy chúng ta dùng \"has got\" để miêu tả đặc điểm cơ thể.","difficulty":1},{"type":"multiple_choice","question":"I ___ got a lot of work to do today. Choose the correct **short form**.","options":["has","have","'s","'ve"],"correct_answer":"'ve","explanation":"Chủ ngữ \"I\" (tôi) đi với \"have got\". Dạng rút gọn của \"I have got\" là \"I've got\".","difficulty":2},{"type":"multiple_choice","question":"Choose the **correct sentence**.","options":["He has got a new job.","He have got a new job.","He got a new job.","He has get a new job."],"correct_answer":"He has got a new job.","explanation":"Chủ ngữ \"He\" (anh ấy) đi với \"has got\". Các lựa chọn khác sai ngữ pháp vì dùng \"have\" với \"he\" hoặc dùng sai dạng động từ \"get\".","difficulty":2},{"type":"multiple_choice","question":"They ___ got any money. Choose the correct **negative short form**.","options":["haven't","hasn't","don't have","doesn't have"],"correct_answer":"haven't","explanation":"Chủ ngữ \"They\" (họ) đi với \"have got\". Dạng phủ định rút gọn là \"haven't got\".","difficulty":2},{"type":"fill_blank","question":"My brother and I ___ got many comic books. Fill in the **blank**.","options":["have","has","haven't","hasn't"],"correct_answer":"have","explanation":"Chủ ngữ \"My brother and I\" (anh trai tôi và tôi) là số nhiều (tương đương \"we\"), vì vậy chúng ta dùng \"have got\".","difficulty":1},{"type":"fill_blank","question":"The dog ___ got a fluffy tail. Fill in the **blank**.","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Chủ ngữ \"The dog\" (con chó) là số ít (tương đương \"it\"), vì vậy chúng ta dùng \"has got\" để miêu tả đặc điểm cơ thể.","difficulty":1},{"type":"fill_blank","question":"___ your friend got a car? Fill in the **blank** with 'Have' or 'Has'.","options":["Have","Has","Do","Does"],"correct_answer":"Has","explanation":"Chủ ngữ \"your friend\" (bạn của bạn) là số ít (tương đương \"he\" hoặc \"she\"), vì vậy chúng ta dùng \"Has\" trong câu hỏi.","difficulty":2},{"type":"fill_blank","question":"We ___ got any milk in the fridge. Complete the sentence with the **negative form**.","options":["haven't","hasn't","don't have","doesn't have"],"correct_answer":"haven't","explanation":"Chủ ngữ \"We\" (chúng tôi) đi với \"have got\". Dạng phủ định của \"have got\" là \"haven't got\".","difficulty":1},{"type":"fill_blank","question":"She ___ got a beautiful voice. Fill in the **blank** with the short form.","options":["'ve","'s","have","has"],"correct_answer":"'s","explanation":"Chủ ngữ \"She\" (cô ấy) đi với \"has got\". Dạng rút gọn của \"has got\" là \"'s got\".","difficulty":2},{"type":"fill_blank","question":"I ___ got a terrible cold. Fill in the **blank** with the **short form**.","options":["'ve","'s","have","has"],"correct_answer":"'ve","explanation":"Chủ ngữ \"I\" (tôi) đi với \"have got\". Dạng rút gọn của \"I have got\" là \"I've got\".","difficulty":1},{"type":"fill_blank","question":"The students ___ got a test tomorrow. Fill in the **blank**.","options":["have","has","haven't","hasn't"],"correct_answer":"have","explanation":"Chủ ngữ \"The students\" (các học sinh) là số nhiều (tương đương \"they\"), vì vậy chúng ta dùng \"have got\".","difficulty":1},{"type":"fill_blank","question":"My phone ___ got a low battery. Fill in the **blank**.","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Chủ ngữ \"My phone\" (điện thoại của tôi) là số ít (tương đương \"it\"), vì vậy chúng ta dùng \"has got\".","difficulty":1},{"type":"error_correction","question":"My sister have got a new bicycle. Identify the **error**.","options":["My","sister","have","got"],"correct_answer":"have","explanation":"Chủ ngữ \"My sister\" (chị gái tôi) là số ít, nên phải dùng \"has got\" thay vì \"have got\".","difficulty":1},{"type":"error_correction","question":"They hasn't got a big garden. Correct the **negative form**.","options":["They haven't got a big garden.","They don't have a big garden.","They doesn't got a big garden.","They hasn't have a big garden."],"correct_answer":"They haven't got a big garden.","explanation":"Chủ ngữ \"They\" (họ) là số nhiều, nên dạng phủ định của \"have got\" là \"haven't got\". \"Hasn't\" dùng cho chủ ngữ số ít.","difficulty":2},{"type":"error_correction","question":"Has you got a pen? Correct the **question form**.","options":["Have you got a pen?","Do you got a pen?","Does you got a pen?","You has got a pen?"],"correct_answer":"Have you got a pen?","explanation":"Chủ ngữ \"you\" (bạn) đi với \"have got\", vì vậy trong câu hỏi phải dùng \"Have\" thay vì \"Has\".","difficulty":1},{"type":"error_correction","question":"I's got a new job. Correct the **short form**.","options":["I've got a new job.","I has got a new job.","I have got a new job.","I is got a new job."],"correct_answer":"I've got a new job.","explanation":"Dạng rút gọn của \"I have got\" là \"I've got\". \"I's\" là sai ngữ pháp.","difficulty":2},{"type":"error_correction","question":"We has got a problem. Correct the **subject-verb agreement**.","options":["We have got a problem.","We has get a problem.","We got a problem.","We haven't got a problem."],"correct_answer":"We have got a problem.","explanation":"Chủ ngữ \"We\" (chúng tôi) là số nhiều, nên phải dùng \"have got\" thay vì \"has got\".","difficulty":1},{"type":"error_correction","question":"He has get a lot of books. Correct the **verb form**.","options":["He has got a lot of books.","He have got a lot of books.","He got a lot of books.","He has getting a lot of books."],"correct_answer":"He has got a lot of books.","explanation":"Cấu trúc đúng là \"has got\". \"Get\" là dạng nguyên thể, không dùng sau \"has\" trong cấu trúc này.","difficulty":2},{"type":"error_correction","question":"She don't got any money. Correct the **negative structure**.","options":["She hasn't got any money.","She doesn't have any money.","She haven't got any money.","She not got any money."],"correct_answer":"She hasn't got any money.","explanation":"Với cấu trúc \"have got\", dạng phủ định là \"haven't got\" hoặc \"hasn't got\". Chủ ngữ \"She\" là số ít nên phải dùng \"hasn't got\".","difficulty":3},{"type":"error_correction","question":"Do you have got a pet? Correct the **question structure**.","options":["Have you got a pet?","Do you have a pet?","Are you got a pet?","You have got a pet?"],"correct_answer":"Have you got a pet?","explanation":"Trong cấu trúc \"have got\", chúng ta không dùng \"Do/Does\" để tạo câu hỏi. Thay vào đó, \"Have/Has\" được đảo lên trước chủ ngữ.","difficulty":3},{"type":"multiple_choice","question":"Chọn từ đúng để hoàn thành câu: \"They ___ got a big family.\"","options":["has","have","is","are"],"correct_answer":"have","explanation":"Với chủ ngữ số nhiều 'They', chúng ta dùng 'have got'. 'Has got' dùng cho chủ ngữ số ít.","difficulty":1},{"type":"fill_blank","question":"Điền từ thích hợp vào chỗ trống: \"My friend ___ got a new laptop.\"","options":["has","have","is","are"],"correct_answer":"has","explanation":"Chủ ngữ 'My friend' là ngôi thứ ba số ít, vì vậy chúng ta dùng 'has got'.","difficulty":1},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"Our teacher have got a lot of experience.\"","options":["Our teacher has got a lot of experience.","Our teacher is got a lot of experience.","Our teacher have got a lots of experience.","Our teacher got a lot of experience."],"correct_answer":"Our teacher has got a lot of experience.","explanation":"Chủ ngữ 'Our teacher' là ngôi thứ ba số ít, nên phải dùng 'has got' thay vì 'have got'.","difficulty":1},{"type":"multiple_choice","question":"Chọn dạng phủ định đúng của câu: \"I have got a lot of free time.\"","options":["I haven't got a lot of free time.","I don't got a lot of free time.","I hasn't got a lot of free time.","I am not got a lot of free time."],"correct_answer":"I haven't got a lot of free time.","explanation":"Dạng phủ định của 'have got' là 'haven't got'. Các lựa chọn khác không đúng ngữ pháp với cấu trúc này.","difficulty":2},{"type":"fill_blank","question":"Hoàn thành câu với dạng phủ định rút gọn: \"He ___ got any money for lunch.\"","options":["hasn't","haven't","don't","doesn't"],"correct_answer":"hasn't","explanation":"Với chủ ngữ 'He', dạng phủ định rút gọn của 'has got' là 'hasn't got'.","difficulty":2},{"type":"error_correction","question":"Sửa lỗi trong câu: \"The children doesn't got many toys.\"","options":["The children haven't got many toys.","The children hasn't got many toys.","The children don't got many toys.","The children not got many toys."],"correct_answer":"The children haven't got many toys.","explanation":"Với chủ ngữ số nhiều 'The children', chúng ta dùng 'haven't got' cho dạng phủ định, không dùng 'doesn't got'.","difficulty":2},{"type":"multiple_choice","question":"Chọn câu có dạng rút gọn đúng: \"She has got a beautiful smile.\"","options":["She's got a beautiful smile.","She've got a beautiful smile.","She got a beautiful smile.","She'd got a beautiful smile."],"correct_answer":"She's got a beautiful smile.","explanation":"Dạng rút gọn của 'has got' là 's got'. 'She's' là viết tắt của 'She has'.","difficulty":1},{"type":"fill_blank","question":"Điền dạng rút gọn vào chỗ trống: \"We'___ got an important meeting tomorrow.\"","options":["ve","s","re","d"],"correct_answer":"ve","explanation":"Với chủ ngữ 'We', dạng rút gọn của 'have got' là 'We've got'.","difficulty":1},{"type":"error_correction","question":"Sửa lỗi trong câu: \"You's got to finish your homework.\"","options":["You've got to finish your homework.","You has got to finish your homework.","You got to finish your homework.","You're got to finish your homework."],"correct_answer":"You've got to finish your homework.","explanation":"Với chủ ngữ 'You', dạng rút gọn của 'have got' là 'You've got', không phải 'You's got'.","difficulty":2},{"type":"multiple_choice","question":"Chọn dạng câu hỏi đúng cho \"They have got a new car.\"","options":["Have they got a new car?","Do they have got a new car?","Has they got a new car?","Are they got a new car?"],"correct_answer":"Have they got a new car?","explanation":"Để tạo câu hỏi với 'have got', chúng ta đảo 'have' lên trước chủ ngữ. 'Have they got...?' là cấu trúc đúng.","difficulty":2},{"type":"fill_blank","question":"Hoàn thành câu hỏi: \"___ it got enough power?\"","options":["Has","Have","Is","Does"],"correct_answer":"Has","explanation":"Với chủ ngữ 'it', chúng ta dùng 'Has' để tạo câu hỏi với 'has got'.","difficulty":2},{"type":"error_correction","question":"Sửa lỗi trong câu: \"Do he has got a pet?\"","options":["Has he got a pet?","Does he has got a pet?","Do he have got a pet?","Is he got a pet?"],"correct_answer":"Has he got a pet?","explanation":"Khi dùng 'have got/has got' trong câu hỏi, chúng ta không dùng trợ động từ 'Do/Does'. Thay vào đó, chúng ta đảo 'Has' lên trước chủ ngữ 'he'.","difficulty":2},{"type":"multiple_choice","question":"Chọn từ đúng để hoàn thành câu: \"The school ___ got a new library.\"","options":["has","have","is","are"],"correct_answer":"has","explanation":"Chủ ngữ 'The school' là danh từ số ít, nên chúng ta dùng 'has got'.","difficulty":1},{"type":"fill_blank","question":"Điền từ thích hợp vào chỗ trống: \"My grandmother ___ got white hair.\"","options":["has","have","is","are"],"correct_answer":"has","explanation":"Chủ ngữ 'My grandmother' là ngôi thứ ba số ít, nên dùng 'has got' để miêu tả đặc điểm cơ thể.","difficulty":1},{"type":"error_correction","question":"Sửa lỗi trong câu: \"I has got a terrible cold.\"","options":["I have got a terrible cold.","I am got a terrible cold.","I has gets a terrible cold.","I got a terrible cold."],"correct_answer":"I have got a terrible cold.","explanation":"Với chủ ngữ 'I', chúng ta luôn dùng 'have got' để nói về tình trạng hiện tại.","difficulty":1},{"type":"multiple_choice","question":"Chọn câu đúng ngữ pháp:","options":["He have got a bicycle.","They has got a dog.","She has got a cat.","We hasn't got time."],"correct_answer":"She has got a cat.","explanation":"Chủ ngữ 'She' đi với 'has got'. Các lựa chọn khác sai về sự hòa hợp chủ ngữ-động từ hoặc dạng phủ định.","difficulty":2},{"type":"fill_blank","question":"Hoàn thành câu với dạng phủ định: \"We ___ got any plans for the holiday yet.\"","options":["haven't","hasn't","don't","doesn't"],"correct_answer":"haven't","explanation":"Với chủ ngữ 'We', dạng phủ định của 'have got' là 'haven't got'.","difficulty":1},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"My brother has get a new car.\"","options":["My brother has got a new car.","My brother have get a new car.","My brother has getting a new car.","My brother got a new car."],"correct_answer":"My brother has got a new car.","explanation":"Cấu trúc đúng là 'has got', không phải 'has get'.","difficulty":1},{"type":"multiple_choice","question":"Chọn từ đúng để hoàn thành câu: \"My cousin ___ got a baby sister.\"","options":["has","have","is","are"],"correct_answer":"has","explanation":"Chủ ngữ 'My cousin' là ngôi thứ ba số ít, vì vậy chúng ta dùng 'has got'.","difficulty":1},{"type":"fill_blank","question":"Điền từ thích hợp vào chỗ trống để tạo câu hỏi: \"___ your parents got a big garden?\"","options":["Have","Has","Do","Are"],"correct_answer":"Have","explanation":"Chủ ngữ 'your parents' là số nhiều, nên chúng ta dùng 'Have' để hỏi với 'have got'.","difficulty":2},{"type":"error_correction","question":"Sửa lỗi trong câu: \"It've got a strange smell.\"","options":["It's got a strange smell.","It have got a strange smell.","It got a strange smell.","It is got a strange smell."],"correct_answer":"It's got a strange smell.","explanation":"Với chủ ngữ 'It', dạng rút gọn của 'has got' là 'It's got', không phải 'It've got'.","difficulty":2},{"type":"multiple_choice","question":"Câu nào sau đây **SAI** ngữ pháp?","options":["I've got a lot of friends.","She's got a new job.","They has got a big house.","We haven't got much time."],"correct_answer":"They has got a big house.","explanation":"Với chủ ngữ 'They' (số nhiều), chúng ta phải dùng 'have got' hoặc 'haven't got', không phải 'has got'.","difficulty":2},{"type":"fill_blank","question":"Hoàn thành câu với dạng phủ định rút gọn: \"The old TV ___ got a remote control.\"","options":["hasn't","haven't","don't","doesn't"],"correct_answer":"hasn't","explanation":"Chủ ngữ 'The old TV' tương đương với 'it', nên chúng ta dùng 'hasn't got' cho dạng phủ định rút gọn.","difficulty":2},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"Lan and Mai has got new bicycles.\"","options":["Lan and Mai have got new bicycles.","Lan and Mai has gets new bicycles.","Lan and Mai got new bicycles.","Lan and Mai is got new bicycles."],"correct_answer":"Lan and Mai have got new bicycles.","explanation":"Khi có hai chủ ngữ nối với 'and' ('Lan and Mai'), chúng ta coi đó là chủ ngữ số nhiều, nên phải dùng 'have got' thay vì 'has got'.","difficulty":3},{"type":"multiple_choice","question":"Chọn từ thích hợp nhất để hoàn thành câu: \"Oh no! I ___ got a flat tire on my bike.\"","options":["have","has","am","is"],"correct_answer":"have","explanation":"Chủ ngữ 'I' luôn đi với 'have got'. Đây là cách diễn đạt một vấn đề hoặc tình trạng hiện tại.","difficulty":1},{"type":"multiple_choice","question":"Chọn từ đúng để hoàn thành câu: \"My cat ___ got green eyes.\"","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Chủ ngữ \"My cat\" (con mèo của tôi) là số ít, tương đương với \"it\", vì vậy chúng ta dùng \"has got\".","difficulty":1},{"type":"fill_blank","question":"Điền từ thích hợp vào chỗ trống: \"I ___ got a lot of homework tonight.\"","options":["have","has","haven't","hasn't"],"correct_answer":"have","explanation":"Với chủ ngữ \"I\", chúng ta dùng \"have got\".","difficulty":1},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"He have got a lot of friends.\"","options":["He have got","He has got","He haven't got","He hasn't got"],"correct_answer":"He has got","explanation":"Chủ ngữ \"He\" là số ít, vì vậy phải dùng \"has got\" chứ không phải \"have got\".","difficulty":1},{"type":"multiple_choice","question":"Chọn câu có dạng **rút gọn** đúng:","options":["She've got a new dress.","They's got a nice house.","We've got a big dog.","He's have got a cold."],"correct_answer":"We've got a big dog.","explanation":"Dạng rút gọn của \"We have got\" là \"We've got\". Các lựa chọn khác sai ngữ pháp.","difficulty":2},{"type":"fill_blank","question":"Hoàn thành câu với dạng phủ định rút gọn: \"My parents ___ got any free time today.\"","options":["haven't","hasn't","don't have","not have"],"correct_answer":"haven't","explanation":"Chủ ngữ \"My parents\" (bố mẹ tôi) là số nhiều, tương đương với \"they\", vì vậy chúng ta dùng \"haven't got\" (dạng phủ định rút gọn).","difficulty":1},{"type":"error_correction","question":"Sửa lỗi trong câu: \"We hasn't got enough time for the project.\"","options":["We hasn't got","We haven't got","We don't got","We has got"],"correct_answer":"We haven't got","explanation":"Với chủ ngữ \"We\", dạng phủ định phải là \"haven't got\".","difficulty":1},{"type":"multiple_choice","question":"Chọn từ đúng để hoàn thành câu: \"They ___ got a beautiful garden.\"","options":["have","has","haven't","hasn't"],"correct_answer":"have","explanation":"Chủ ngữ \"They\" (họ) là số nhiều, vì vậy chúng ta dùng \"have got\".","difficulty":1},{"type":"fill_blank","question":"Điền từ thích hợp vào chỗ trống: \"She ___ got long, blonde hair.\"","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Với chủ ngữ \"She\", chúng ta dùng \"has got\" để miêu tả đặc điểm cơ thể.","difficulty":1},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"Have she got a new phone?\"","options":["Have she got","Has she got","Does she have got","Is she got"],"correct_answer":"Has she got","explanation":"Với chủ ngữ \"She\", dạng câu hỏi phải dùng \"Has\" chứ không phải \"Have\".","difficulty":1},{"type":"multiple_choice","question":"Câu nào sau đây sử dụng **have got / has got** đúng ngữ pháp?","options":["I has got a big family.","He have got a red car.","They've got a lot of books.","She haven't got any sisters."],"correct_answer":"They've got a lot of books.","explanation":"Với chủ ngữ \"They\", chúng ta dùng \"have got\", và dạng rút gọn \"'ve got\" là đúng. Các câu còn lại sai ở sự hòa hợp chủ ngữ-động từ.","difficulty":2},{"type":"fill_blank","question":"Hoàn thành câu hỏi: \"___ you got any plans for the weekend?\"","options":["Have","Has","Do","Are"],"correct_answer":"Have","explanation":"Với chủ ngữ \"you\" trong cấu trúc \"have got\", dạng câu hỏi bắt đầu bằng \"Have\".","difficulty":1},{"type":"error_correction","question":"Sửa lỗi trong câu: \"It've got a comfortable bed.\"","options":["It've got","It's got","It has got","It have got"],"correct_answer":"It's got","explanation":"Dạng rút gọn của \"It has got\" là \"It's got\". \"It've got\" là sai.","difficulty":2},{"type":"multiple_choice","question":"Chọn từ đúng để hoàn thành câu: \"The new restaurant ___ got delicious food.\"","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Chủ ngữ \"The new restaurant\" là số ít, tương đương với \"it\", vì vậy chúng ta dùng \"has got\".","difficulty":1},{"type":"fill_blank","question":"Điền dạng rút gọn vào chỗ trống: \"My brother'___ got a new job.\"","options":["ve","s","re","m"],"correct_answer":"s","explanation":"Chủ ngữ \"My brother\" là số ít, tương đương với \"he\", vì vậy dạng rút gọn của \"has got\" là \"'s got\".","difficulty":1},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"The children hasn't got many toys.\"","options":["The children hasn't got","The children haven't got","The children don't got","The children not got"],"correct_answer":"The children haven't got","explanation":"Chủ ngữ \"The children\" (những đứa trẻ) là số nhiều, tương đương với \"they\", vì vậy phải dùng \"haven't got\".","difficulty":2},{"type":"multiple_choice","question":"Chọn dạng phủ định đúng của câu: \"He has got a lot of energy.\"","options":["He haven't got a lot of energy.","He hasn't got a lot of energy.","He don't got a lot of energy.","He not got a lot of energy."],"correct_answer":"He hasn't got a lot of energy.","explanation":"Với chủ ngữ \"He\", dạng phủ định của \"has got\" là \"hasn't got\".","difficulty":1},{"type":"fill_blank","question":"Hoàn thành câu với dạng phủ định: \"We ___ got any milk left.\"","options":["haven't","hasn't","don't have","not have"],"correct_answer":"haven't","explanation":"Với chủ ngữ \"We\", dạng phủ định của \"have got\" là \"haven't got\".","difficulty":1},{"type":"error_correction","question":"Sửa lỗi trong câu: \"You's got a very busy schedule.\"","options":["You's got","You've got","You have got","You has got"],"correct_answer":"You've got","explanation":"Dạng rút gọn của \"You have got\" là \"You've got\". \"You's got\" là sai.","difficulty":2},{"type":"multiple_choice","question":"Chọn câu hỏi đúng ngữ pháp:","options":["Has you got a problem?","Have he got a car?","Have they got any food?","Does she has got a pet?"],"correct_answer":"Have they got any food?","explanation":"Với chủ ngữ \"they\", dạng câu hỏi đúng là \"Have they got...\". Các lựa chọn khác sai ở sự hòa hợp chủ ngữ-động từ hoặc cấu trúc câu hỏi.","difficulty":2},{"type":"fill_blank","question":"Điền từ thích hợp vào chỗ trống: \"My new phone ___ got a great camera.\"","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Chủ ngữ \"My new phone\" là số ít, tương đương với \"it\", vì vậy chúng ta dùng \"has got\".","difficulty":1},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"I has got a lot of things to do.\"","options":["I has got","I have got","I haven't got","I am got"],"correct_answer":"I have got","explanation":"Với chủ ngữ \"I\", chúng ta phải dùng \"have got\" chứ không phải \"has got\".","difficulty":1},{"type":"multiple_choice","question":"Chọn câu có dạng rút gọn **phủ định** đúng:","options":["She's not got a passport.","They haven't got a map.","He hasn't got any brothers.","We've not got much time."],"correct_answer":"He hasn't got any brothers.","explanation":"Dạng rút gọn phủ định của \"He has got\" là \"He hasn't got\". \"She's not got\" và \"We've not got\" không phải là dạng rút gọn phủ định chuẩn. \"They haven't got\" cũng đúng nhưng câu hỏi yêu cầu chọn câu có dạng rút gọn phủ định đúng, và \"He hasn't got\" là một ví dụ rõ ràng.","difficulty":3},{"type":"fill_blank","question":"Hoàn thành câu: \"The old house ___ got a beautiful garden.\"","options":["have","has","haven't","hasn't"],"correct_answer":"has","explanation":"Chủ ngữ \"The old house\" là số ít, tương đương với \"it\", vì vậy chúng ta dùng \"has got\".","difficulty":1},{"type":"error_correction","question":"Sửa lỗi trong câu: \"My parents has got two cars.\"","options":["My parents has got","My parents have got","My parents haven't got","My parents is got"],"correct_answer":"My parents have got","explanation":"Chủ ngữ \"My parents\" (bố mẹ tôi) là số nhiều, vì vậy phải dùng \"have got\" chứ không phải \"has got\".","difficulty":1},{"type":"multiple_choice","question":"Chọn từ thích hợp nhất để hoàn thành câu: \"Oh no! I ___ got a headache.\"","options":["have","has","haven't","hasn't"],"correct_answer":"have","explanation":"Với chủ ngữ \"I\", chúng ta dùng \"have got\" để nói về tình trạng sức khỏe hiện tại.","difficulty":1},{"type":"multiple_choice","question":"Chọn từ đúng để hoàn thành câu: \"My friend and I **___** a lot of fun together.\"","options":["have got","has got","got","are got"],"correct_answer":"have got","explanation":"Chủ ngữ \"My friend and I\" là số nhiều (tương đương \"we\"), nên dùng \"have got\". \"Has got\" dùng cho chủ ngữ số ít (he/she/it). \"Got\" đứng một mình không đúng ngữ pháp trong cấu trúc này. \"Are got\" không phải cấu trúc ngữ pháp đúng.","difficulty":1},{"type":"fill_blank","question":"Hoàn thành câu với dạng phủ định: \"The school **___** a big library.\"","options":["hasn't got","haven't got","didn't got","not got"],"correct_answer":"hasn't got","explanation":"Chủ ngữ \"The school\" là số ít (tương đương \"it\"), nên dùng \"hasn't got\" cho dạng phủ định. \"Haven't got\" dùng cho chủ ngữ số nhiều. Các lựa chọn khác không đúng ngữ pháp.","difficulty":1},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"My parents **has got** a new car last month.\"","options":["has got -> have got","has got -> had got","has got -> have gets","has got -> got"],"correct_answer":"has got -> have got","explanation":"Chủ ngữ \"My parents\" là số nhiều, nên phải dùng \"have got\", không phải \"has got\". Mặc dù có \"last month\" nhưng cấu trúc \"have got\" vẫn dùng để nói về sở hữu hiện tại (vẫn có xe mới).","difficulty":1},{"type":"multiple_choice","question":"Chọn từ thích hợp để hoàn thành câu: \"I **___** a blue backpack for school.\"","options":["have got","has got","got","am got"],"correct_answer":"have got","explanation":"Chủ ngữ \"I\" luôn đi với \"have got\". \"Has got\" dùng cho ngôi thứ ba số ít. \"Got\" đứng một mình không đúng cấu trúc. \"Am got\" không đúng ngữ pháp.","difficulty":1},{"type":"fill_blank","question":"Hoàn thành câu với dạng rút gọn khẳng định: \"She**___** a beautiful voice.\"","options":["'s got","'ve got","is got","has get"],"correct_answer":"'s got","explanation":"Chủ ngữ \"She\" là ngôi thứ ba số ít, nên dùng \"has got\". Dạng rút gọn của \"has got\" là \"'s got\". \"'ve got\" dùng cho I/you/we/they.","difficulty":1},{"type":"error_correction","question":"Sửa lỗi trong câu: \"They **haven't gets** a lot of homework today.\"","options":["haven't gets -> haven't got","haven't gets -> hasn't got","haven't gets -> don't got","haven't gets -> hasn't gets"],"correct_answer":"haven't gets -> haven't got","explanation":"Cấu trúc phủ định là \"haven't got\" hoặc \"hasn't got\". Động từ chính luôn là \"got\", không phải \"gets\". Vì chủ ngữ là \"They\" nên dùng \"haven't got\".","difficulty":1},{"type":"multiple_choice","question":"Câu nào sau đây sử dụng **have got / has got** đúng để miêu tả đặc điểm cơ thể?","options":["He has got brown eyes.","She have got long hair.","They has got short legs.","I's got a small nose."],"correct_answer":"He has got brown eyes.","explanation":"Chủ ngữ \"He\" là ngôi thứ ba số ít, đi với \"has got\". Các câu khác sai ngữ pháp: \"She\" phải đi với \"has got\"; \"They\" phải đi với \"have got\"; \"I\" phải đi với \"I've got\" hoặc \"I have got\".","difficulty":1},{"type":"fill_blank","question":"Điền dạng rút gọn vào chỗ trống: \"We**___** a new teacher this year.\"","options":["'ve got","'s got","are got","have get"],"correct_answer":"'ve got","explanation":"Chủ ngữ \"We\" đi với \"have got\". Dạng rút gọn của \"have got\" là \"'ve got\". \"'s got\" dùng cho he/she/it.","difficulty":1},{"type":"error_correction","question":"Tìm và sửa lỗi sai trong câu: \"The children **has got** many toys to play with.\"","options":["has got -> have got","has got -> gets","has got -> haven't got","has got -> has gets"],"correct_answer":"has got -> have got","explanation":"Chủ ngữ \"The children\" là số nhiều, nên phải dùng \"have got\", không phải \"has got\". \"Gets\" hoặc \"haven't got\" không phù hợp với ý nghĩa khẳng định và số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Chọn từ đúng để hoàn thành câu về tình trạng hiện tại: \"I **___** a terrible cold, I need to rest.\"","options":["have got","has got","got","am having"],"correct_answer":"have got","explanation":"Chủ ngữ \"I\" đi với \"have got\". Cấu trúc \"have got\" được dùng để nói về tình trạng hoặc vấn đề hiện tại (như bị ốm). \"Has got\" dùng cho ngôi thứ ba số ít. \"Got\" đứng một mình không đúng cấu trúc. \"Am having\" cũng đúng ngữ pháp nhưng \"have got\" là cấu trúc được yêu cầu.","difficulty":1},{"type":"fill_blank","question":"Hoàn thành câu với dạng phủ định: \"My brother **___** a mustache.\" (miêu tả đặc điểm cơ thể)","options":["hasn't got","haven't got","don't got","not got"],"correct_answer":"hasn't got","explanation":"Chủ ngữ \"My brother\" là số ít (tương đương \"he\"), nên dùng \"hasn't got\" cho dạng phủ định. \"Haven't got\" dùng cho chủ ngữ số nhiều. Các lựa chọn khác không đúng ngữ pháp.","difficulty":1},{"type":"error_correction","question":"Sửa lỗi trong câu: \"It **have got** a beautiful view from the window.\"","options":["have got -> has got","have got -> got","have got -> is got","have got -> have gets"],"correct_answer":"have got -> has got","explanation":"Chủ ngữ \"It\" là ngôi thứ ba số ít, nên phải dùng \"has got\", không phải \"have got\". \"Got\", \"is got\" hoặc \"have gets\" không đúng ngữ pháp.","difficulty":1},{"type":"multiple_choice","question":"Câu nào sau đây là dạng phủ định đúng của \"We have got a lot of time\"?","options":["We haven't got a lot of time.","We hasn't got a lot of time.","We don't got a lot of time.","We not got a lot of time."],"correct_answer":"We haven't got a lot of time.","explanation":"Dạng phủ định của \"have got\" là \"haven't got\". Vì chủ ngữ là \"We\" (số nhiều), nên dùng \"haven't got\". \"Hasn't got\" dùng cho chủ ngữ số ít. Các lựa chọn khác không đúng cấu trúc phủ định của \"have got\".","difficulty":1}]$grammar$::jsonb, 'ai-golden', 10
from public.grammar_topics t where t.slug = 'have-got'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
