on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu hỏi với từ để hỏi (Wh-)', '**Câu hỏi Wh-** (Wh- questions) bắt đầu bằng các từ hỏi như ''who'', ''what'', ''where'', ''when'', ''why'', ''which'', ''whose'' hoặc ''how'' để yêu cầu thông tin cụ thể thay vì câu trả lời có/không. Trong câu hỏi Wh-, động từ trợ giúp thường được đảo lên trước chủ ngữ, trừ khi từ hỏi chính là chủ ngữ.', $grammar$[{"en":"Where do you live?","vi":"Bạn sống ở đâu?","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"Where","start":0},{"end":8,"role":"auxiliary","word":"do","start":6},{"end":12,"role":"pronoun","word":"you","start":9},{"end":17,"role":"verb","word":"live","start":13}]},{"en":"Why was she upset?","vi":"Tại sao cô ấy buồn?","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"Why","start":0},{"end":7,"role":"auxiliary","word":"was","start":4},{"end":11,"role":"pronoun","word":"she","start":8},{"end":17,"role":"adjective","word":"upset","start":12}]},{"en":"Who called you last night?","vi":"Ai đã gọi bạn tối qua?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"Who","start":0},{"end":10,"role":"verb","word":"called","start":4},{"end":14,"role":"pronoun","word":"you","start":11},{"end":19,"role":"adjective","word":"last","start":15},{"end":25,"role":"noun","word":"night","start":20}]},{"en":"How much does it cost?","vi":"Nó giá bao nhiêu?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"How","start":0},{"end":8,"role":"adverb","word":"much","start":4},{"end":13,"role":"auxiliary","word":"does","start":9},{"end":16,"role":"pronoun","word":"it","start":14},{"end":21,"role":"verb","word":"cost","start":17}]},{"en":"Which bus goes downtown?","vi":"Xe buýt nào đi vào trung tâm?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"determiner","word":"Which","start":0},{"end":9,"role":"noun","word":"bus","start":6},{"end":14,"role":"verb","word":"goes","start":10},{"end":23,"role":"noun","word":"downtown","start":15}]},{"en":"What are they discussing?","vi":"Họ đang thảo luận điều gì?","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"What","start":0},{"end":8,"role":"auxiliary","word":"are","start":5},{"end":13,"role":"pronoun","word":"they","start":9},{"end":24,"role":"verb","word":"discussing","start":14}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **Wh-word + auxiliary + S + V?** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"Wh-word + auxiliary + S + V?","example":"Where do you live?"},{"case":"Kiểm tra thành phần theo sau","rule":"Wh-word + be + S?","example":"Why was she upset?"},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Who/What làm chủ ngữ + V?","example":"Who called you last night?"}],"usage":[{"en":"Where do you live?","vi":"Bạn sống ở đâu?","icon":"📍","label":"Hỏi nơi chốn với Where"},{"en":"Why was she upset?","vi":"Tại sao cô ấy buồn?","icon":"🤔","label":"Hỏi lý do với Why"},{"en":"Who called you last night?","vi":"Ai đã gọi cho bạn tối qua?","icon":"🙋","label":"Hỏi chủ ngữ với Who (không cần trợ động từ)"},{"en":"How much does it cost?","vi":"Cái này giá bao nhiêu?","icon":"💰","label":"Hỏi số lượng, giá cả với How much / How many"},{"en":"When does the class start?","vi":"Khi nào lớp học bắt đầu?","icon":"⏰","label":"Hỏi thời gian với When"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"Wh-word + auxiliary + S + V?","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Wh-word + be + S?","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Who/What làm chủ ngữ + V?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["who","what","which","whose","where","when","why","how"],"examples":[{"en":"Where do you live?","vi":"Bạn sống ở đâu?","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"Where","start":0},{"end":8,"role":"auxiliary","word":"do","start":6},{"end":12,"role":"pronoun","word":"you","start":9},{"end":17,"role":"verb","word":"live","start":13}]},{"en":"Why was she upset?","vi":"Tại sao cô ấy buồn?","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"Why","start":0},{"end":7,"role":"auxiliary","word":"was","start":4},{"end":11,"role":"pronoun","word":"she","start":8},{"end":17,"role":"adjective","word":"upset","start":12}]},{"en":"Who called you last night?","vi":"Ai đã gọi bạn tối qua?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"Who","start":0},{"end":10,"role":"verb","word":"called","start":4},{"end":14,"role":"pronoun","word":"you","start":11},{"end":19,"role":"adjective","word":"last","start":15},{"end":25,"role":"noun","word":"night","start":20}]},{"en":"How much does it cost?","vi":"Nó giá bao nhiêu?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"How","start":0},{"end":8,"role":"adverb","word":"much","start":4},{"end":13,"role":"auxiliary","word":"does","start":9},{"end":16,"role":"pronoun","word":"it","start":14},{"end":21,"role":"verb","word":"cost","start":17}]},{"en":"Which bus goes downtown?","vi":"Xe buýt nào đi vào trung tâm?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"determiner","word":"Which","start":0},{"end":9,"role":"noun","word":"bus","start":6},{"end":14,"role":"verb","word":"goes","start":10},{"end":23,"role":"noun","word":"downtown","start":15}]},{"en":"What are they discussing?","vi":"Họ đang thảo luận điều gì?","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"What","start":0},{"end":8,"role":"auxiliary","word":"are","start":5},{"end":13,"role":"pronoun","word":"they","start":9},{"end":24,"role":"verb","word":"discussing","start":14}]}],"mistakes":[{"wrong":"Where you are from?","right":"Where are you from?","why":"Câu hỏi đảo trợ động từ/be lên trước chủ ngữ."},{"wrong":"What you do yesterday?","right":"What did you do yesterday?","why":"Câu hỏi quá khứ cần trợ động từ DID + động từ nguyên thể."},{"wrong":"Who did phone you?","right":"Who phoned you?","why":"Khi từ để hỏi là chủ ngữ, không dùng did."},{"wrong":"How much you pay?","right":"How much did you pay?","why":"Thiếu trợ động từ did trong câu hỏi quá khứ."}],"timeline":null,"comparison":"**Wh-word làm CHỦ NGỮ vs làm TÂN NGỮ:** Khi từ để hỏi là chủ ngữ, giữ nguyên trật tự câu kể, KHÔNG dùng do/does/did: *Who phoned Emma?* (ai gọi?). Khi từ để hỏi là tân ngữ, phải có trợ động từ trước chủ ngữ: *Who did Emma phone?* (Emma gọi ai?). Cùng một chữ Who nhưng hai cấu trúc khác hẳn nhau.","definition":"**Câu hỏi Wh-** (Wh- questions) bắt đầu bằng các từ hỏi như 'who', 'what', 'where', 'when', 'why', 'which', 'whose' hoặc 'how' để yêu cầu thông tin cụ thể thay vì câu trả lời có/không. Trong câu hỏi Wh-, động từ trợ giúp thường được đảo lên trước chủ ngữ, trừ khi từ hỏi chính là chủ ngữ."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: Why ___ she upset?","answer":["was"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 11
from public.grammar_topics t where t.slug = 'wh-questions'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 12. adverbs-frequency
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('adverbs-frequency', 'Adverbs of Frequency', 'Trạng từ chỉ tần suất', 'beginner', 12)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Trạng từ chỉ tần suất', '**Trạng từ chỉ tần suất** (như always, often, never) được sử dụng để xác định mức độ thường xuyên của một hành động, giúp người nói làm rõ thói quen hoặc tần suất xuất hiện của sự việc. Các từ này thường đứng trước động từ thường và sau động từ to-be, đóng vai trò then chốt trong việc mô tả tính quy luật của các hoạt động trong đời sống.', $grammar$[{"en":"I usually walk to work.","vi":"Tôi thường đi bộ đến chỗ làm.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":9,"role":"adverb","word":"usually","start":2},{"end":14,"role":"verb","word":"walk","start":10},{"end":17,"role":"preposition","word":"to","start":15},{"end":22,"role":"noun","word":"work","start":18}]},{"en":"She is always helpful.","vi":"Cô ấy luôn nhiệt tình giúp đỡ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":6,"role":"auxiliary","word":"is","start":4},{"end":13,"role":"adverb","word":"always","start":7},{"end":21,"role":"adjective","word":"helpful","start":14}]},{"en":"We rarely eat out.","vi":"Chúng tôi hiếm khi ăn ngoài.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":9,"role":"adverb","word":"rarely","start":3},{"end":13,"role":"verb","word":"eat","start":10},{"end":17,"role":"adverb","word":"out","start":14}]},{"en":"Do you often call your parents?","vi":"Bạn có thường gọi cho bố mẹ không?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"auxiliary","word":"Do","start":0},{"end":6,"role":"pronoun","word":"you","start":3},{"end":12,"role":"adverb","word":"often","start":7},{"end":17,"role":"verb","word":"call","start":13},{"end":22,"role":"determiner","word":"your","start":18},{"end":30,"role":"noun","word":"parents","start":23}]},{"en":"Sometimes, he works from home.","vi":"Đôi khi anh ấy làm việc tại nhà.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":9,"role":"adverb","word":"Sometimes","start":0},{"end":13,"role":"pronoun","word":"he","start":11},{"end":19,"role":"verb","word":"works","start":14},{"end":24,"role":"preposition","word":"from","start":20},{"end":29,"role":"noun","word":"home","start":25}]},{"en":"They never arrive late.","vi":"Họ không bao giờ đến muộn.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":10,"role":"adverb","word":"never","start":5},{"end":17,"role":"verb","word":"arrive","start":11},{"end":22,"role":"adjective","word":"late","start":18}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + adverb + động từ thường** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + adverb + động từ thường","example":"I usually walk to work."},{"case":"Kiểm tra thành phần theo sau","rule":"S + be + adverb","example":"She is always helpful."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"sometimes/usually có thể đứng đầu câu","example":"We rarely eat out."}],"usage":[{"en":"I usually walk to work.","vi":"Tôi thường đi bộ đến chỗ làm.","icon":"🔁","label":"Đứng trước động từ thường"},{"en":"She is always helpful.","vi":"Cô ấy lúc nào cũng nhiệt tình giúp đỡ.","icon":"🧲","label":"Đứng sau động từ to be"},{"en":"We rarely eat out.","vi":"Chúng tôi hiếm khi ăn ngoài.","icon":"📉","label":"Diễn tả tần suất thấp (rarely, seldom, never)"},{"en":"Do you often call your parents?","vi":"Bạn có hay gọi điện cho bố mẹ không?","icon":"❓","label":"Dùng often/usually trong câu hỏi về thói quen"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + adverb + động từ thường","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + be + adverb","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"sometimes/usually có thể đứng đầu câu","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["always","usually","often","sometimes","seldom","rarely","never"],"examples":[{"en":"I usually walk to work.","vi":"Tôi thường đi bộ đến chỗ làm.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":9,"role":"adverb","word":"usually","start":2},{"end":14,"role":"verb","word":"walk","start":10},{"end":17,"role":"preposition","word":"to","start":15},{"end":22,"role":"noun","word":"work","start":18}]},{"en":"She is always helpful.","vi":"Cô ấy luôn nhiệt tình giúp đỡ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":6,"role":"auxiliary","word":"is","start":4},{"end":13,"role":"adverb","word":"always","start":7},{"end":21,"role":"adjective","word":"helpful","start":14}]},{"en":"We rarely eat out.","vi":"Chúng tôi hiếm khi ăn ngoài.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":9,"role":"adverb","word":"rarely","start":3},{"end":13,"role":"verb","word":"eat","start":10},{"end":17,"role":"adverb","word":"out","start":14}]},{"en":"Do you often call your parents?","vi":"Bạn có thường gọi cho bố mẹ không?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"auxiliary","word":"Do","start":0},{"end":6,"role":"pronoun","word":"you","start":3},{"end":12,"role":"adverb","word":"often","start":7},{"end":17,"role":"verb","word":"call","start":13},{"end":22,"role":"determiner","word":"your","start":18},{"end":30,"role":"noun","word":"parents","start":23}]},{"en":"Sometimes, he works from home.","vi":"Đôi khi anh ấy làm việc tại nhà.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":9,"role":"adverb","word":"Sometimes","start":0},{"end":13,"role":"pronoun","word":"he","start":11},{"end":19,"role":"verb","word":"works","start":14},{"end":24,"role":"preposition","word":"from","start":20},{"end":29,"role":"noun","word":"home","start":25}]},{"en":"They never arrive late.","vi":"Họ không bao giờ đến muộn.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":10,"role":"adverb","word":"never","start":5},{"end":17,"role":"verb","word":"arrive","start":11},{"end":22,"role":"adjective","word":"late","start":18}]}],"mistakes":[{"wrong":"I go always to school by bike.","right":"I always go to school by bike.","why":"Trạng từ tần suất đứng TRƯỚC động từ thường."},{"wrong":"She always is late.","right":"She is always late.","why":"Với động từ be, trạng từ tần suất đứng SAU be."},{"wrong":"He usual watches TV.","right":"He usually watches TV.","why":"Dùng trạng từ (usually), không dùng tính từ (usual)."},{"wrong":"Never I eat meat.","right":"I never eat meat.","why":"Never đứng giữa câu, trước động từ thường — không mở đầu câu (trừ đảo ngữ trang trọng)."}],"timeline":null,"comparison":"**Vị trí với động từ thường vs động từ be:** Trạng từ tần suất đứng TRƯỚC động từ thường (*Emily always drives to work*) nhưng đứng SAU am/is/are/was/were (*You are always late*). Đây là cặp vị trí học sinh hay đảo ngược nhất.","definition":"**Trạng từ chỉ tần suất** (như always, often, never) được sử dụng để xác định mức độ thường xuyên của một hành động, giúp người nói làm rõ thói quen hoặc tần suất xuất hiện của sự việc. Các từ này thường đứng trước động từ thường và sau động từ to-be, đóng vai trò then chốt trong việc mô tả tính quy luật của các hoạt động trong đời sống."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ always helpful.","answer":["is"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."},{"type":"multiple_choice","question":"Choose the correct **adverb position**: My brother ___ plays soccer after school.","options":["often","oftenly","is often","does often"],"correct_answer":"often","explanation":"Đáp án đúng là 'often' vì trạng từ chỉ tần suất đứng trước động từ thường 'plays'. 'Oftenly' không phải từ đúng, còn 'is often' và 'does often' không phù hợp trong câu khẳng định này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **frequency adverb**: I ___ drink coffee at night because I cannot sleep.","options":["never","every","many","much"],"correct_answer":"never","explanation":"'Never' diễn tả tần suất bằng 0 và phù hợp với ý 'không uống cà phê vào ban đêm'. 'Every' cần danh từ theo sau, còn 'many' và 'much' nói về số lượng, không phải tần suất.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **word order**: They are ___ tired after work.","options":["usually","usual","usually are","tired usually"],"correct_answer":"usually","explanation":"Với động từ 'be', trạng từ tần suất đứng sau 'are': 'are usually tired'. 'Usual' là tính từ, còn các lựa chọn khác sai trật tự từ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question form**: ___ you often watch TV in the evening?","options":["Do","Are","Does","Is"],"correct_answer":"Do","explanation":"Với chủ ngữ 'you' và động từ thường 'watch', câu hỏi hiện tại đơn dùng 'Do'. 'Does' dùng cho he/she/it, còn 'Are/Is' dùng với động từ 'be'.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **negative form**: Anna ___ goes to bed after midnight.","options":["never","does never","is never","not never"],"correct_answer":"never","explanation":"'Never' đã mang nghĩa phủ định nên đứng trước động từ thường 'goes'. 'Does never', 'is never' và 'not never' không đúng cấu trúc trong câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **sentence** with a frequency adverb.","options":["He sometimes cooks dinner.","He cooks sometimes dinner.","Sometimes he cooks dinner.","He cook sometimes dinner."],"correct_answer":"He sometimes cooks dinner.","explanation":"'He sometimes cooks dinner' đúng vì trạng từ đứng trước động từ thường và động từ thêm -s với 'he'. Câu 'Sometimes he cooks dinner' cũng tự nhiên nhưng bài yêu cầu chọn vị trí cơ bản trong câu; các câu còn lại sai trật tự hoặc sai dạng động từ.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **be placement**: The classroom ___ quiet in the morning.","options":["is always","always is","always","does always"],"correct_answer":"is always","explanation":"Với động từ 'be', cấu trúc đúng là 'S + be + adverb': 'The classroom is always quiet'. Các đáp án khác thiếu 'be' hoặc đặt trạng từ sai vị trí.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **frequency phrase**: We go swimming ___.","options":["twice a week","twice week","two a week","two times week"],"correct_answer":"twice a week","explanation":"'Twice a week' là cụm chỉ tần suất đúng, nghĩa là hai lần một tuần. Các lựa chọn còn lại thiếu 'a' hoặc dùng sai dạng diễn đạt.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **adverb meaning**: 'rarely' means ___.","options":["not often","every day","all the time","very fast"],"correct_answer":"not often","explanation":"'Rarely' nghĩa là hiếm khi, tức là 'not often'. Các đáp án còn lại chỉ tần suất cao hoặc tốc độ, không đúng nghĩa.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **frequency adverb**: I ___ brush my teeth before bed.","options":["always","yesterday","soon","fast"],"correct_answer":"always","explanation":"'Always' phù hợp vì diễn tả thói quen xảy ra mọi lần. 'Yesterday' là thời gian quá khứ, 'soon' là tương lai gần, còn 'fast' chỉ cách hành động xảy ra.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **adverb position**: Mark ___ eats breakfast at 7 a.m.","options":["usually","is usually","usually is","usual"],"correct_answer":"usually","explanation":"Với động từ thường 'eats', trạng từ tần suất đứng trước động từ: 'usually eats'. Các lựa chọn có 'is' không phù hợp, còn 'usual' là tính từ.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **be form**: My parents are ___ busy on Mondays.","options":["sometimes","sometimes are","do sometimes","usual"],"correct_answer":"sometimes","explanation":"Sau động từ 'are', ta đặt trạng từ tần suất 'sometimes'. Các đáp án khác sai trật tự, sai trợ động từ hoặc sai loại từ.","difficulty":1},{"type":"fill_blank","question":"Complete the question with the correct **auxiliary**: ___ she usually take the bus?","options":["Does","Do","Is","Are"],"correct_answer":"Does","explanation":"Chủ ngữ 'she' đi với trợ động từ 'Does' trong câu hỏi hiện tại đơn. 'Do' dùng cho I/you/we/they, còn 'Is/Are' dùng với động từ 'be'.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **main verb**: Peter often ___ his homework after dinner.","options":["does","do","is doing","doing"],"correct_answer":"does","explanation":"Với chủ ngữ 'Peter' số ít, động từ thường ở hiện tại đơn thêm -s: 'does'. 'Do', 'doing' và 'is doing' không đúng cấu trúc thói quen ở đây.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **word order**: Lisa is ___ late for class.","options":["hardly ever","hard ever","ever hardly","hardly"],"correct_answer":"hardly ever","explanation":"'Hardly ever' nghĩa là hầu như không bao giờ và đứng sau 'is'. 'Hard ever' và 'ever hardly' sai cụm, còn 'hardly' một mình không diễn tả tần suất tự nhiên bằng cụm này.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **frequency phrase**: I visit my grandmother ___.","options":["once a month","one month","once month","one time month"],"correct_answer":"once a month","explanation":"'Once a month' là cách nói đúng cho 'một lần mỗi tháng'. Các lựa chọn còn lại thiếu 'a' hoặc dùng sai cấu trúc tần suất.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **sentence adverb**: ___, we have lunch at school.","options":["Sometimes","Neverly","Oftenly","Usually are"],"correct_answer":"Sometimes","explanation":"'Sometimes' có thể đứng đầu câu để nói 'đôi khi'. 'Neverly' và 'Oftenly' không phải từ đúng, còn 'Usually are' không phù hợp đầu câu này.","difficulty":2},{"type":"error_correction","question":"Find the error: He **always** **go** **to** **school** by bike.","options":["always","go","to","school"],"correct_answer":"go","explanation":"Lỗi là 'go' vì chủ ngữ 'He' cần động từ hiện tại đơn thêm -s: 'goes'. 'Always' đúng vị trí trước động từ thường, còn 'to' và 'school' đúng trong cụm 'goes to school'.","difficulty":1},{"type":"error_correction","question":"Find the error: My sister **is** **often** **goes** **shopping** on Sundays.","options":["is","often","goes","shopping"],"correct_answer":"is","explanation":"Lỗi là 'is' vì câu dùng động từ thường 'goes', không cần 'be'. Câu đúng là 'My sister often goes shopping on Sundays'; 'often', 'goes' và 'shopping' đều phù hợp.","difficulty":2},{"type":"error_correction","question":"Find the error: They **usually** **are** **happy** **after lunch**.","options":["usually","are","happy","after lunch"],"correct_answer":"usually","explanation":"Lỗi là vị trí 'usually' trong câu này; với động từ 'be', nên nói 'They are usually happy after lunch'. 'Are', 'happy' và 'after lunch' đều đúng chức năng.","difficulty":2},{"type":"error_correction","question":"Find the error: Do **your brother** **often** **play** **tennis**?","options":["your brother","often","play","tennis"],"correct_answer":"your brother","explanation":"Lỗi là 'your brother' vì chủ ngữ số ít cần trợ động từ 'Does': 'Does your brother often play tennis?'. 'Often' đứng đúng trước động từ thường, 'play' dùng nguyên mẫu sau 'does', và 'tennis' đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: She **never** **doesn't** **eat** **meat**.","options":["never","doesn't","eat","meat"],"correct_answer":"doesn't","explanation":"Lỗi là 'doesn't' vì 'never' đã mang nghĩa phủ định, không dùng thêm phủ định nữa. Câu đúng là 'She never eats meat'; 'never', 'eat/meat' phù hợp về nghĩa nhưng động từ sẽ đổi thành 'eats'.","difficulty":2},{"type":"error_correction","question":"Find the error: We **oftenly** **clean** **our room** **on Saturday**.","options":["oftenly","clean","our room","on Saturday"],"correct_answer":"oftenly","explanation":"Lỗi là 'oftenly' vì từ đúng là 'often'. 'Clean', 'our room' và 'on Saturday' đều đúng trong câu nói về thói quen.","difficulty":1},{"type":"error_correction","question":"Find the error: Tom **hardly ever** **is** **angry** **at home**.","options":["hardly ever","is","angry","at home"],"correct_answer":"hardly ever","explanation":"Lỗi là vị trí 'hardly ever'; với động từ 'be', câu đúng là 'Tom is hardly ever angry at home'. 'Is', 'angry' và 'at home' đều đúng.","difficulty":3},{"type":"error_correction","question":"Find the error: My friends **seldom** **plays** **computer games** **at night**.","options":["seldom","plays","computer games","at night"],"correct_answer":"plays","explanation":"Lỗi là 'plays' vì chủ ngữ số nhiều 'My friends' cần động từ nguyên mẫu 'play'. 'Seldom' đúng vị trí trước động từ thường, còn các cụm còn lại đúng nghĩa.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **adverb position**: Sarah ___ cooks dinner at home.","options":["usually","is usually","usually is","does usually"],"correct_answer":"usually","explanation":"Với động từ thường “cooks”, trạng từ tần suất đứng trước động từ: “Sarah usually cooks...”. Các lựa chọn có “is” hoặc “does” làm câu sai cấu trúc vì câu khẳng định hiện tại đơn không cần trợ động từ ở đây.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **be position**: Ben is ___ ready for class.","options":["always","always is","does always","ready always"],"correct_answer":"always","explanation":"Với động từ “be”, trạng từ tần suất đứng sau “be”: “Ben is always ready...”. “always is” đảo sai vị trí, “does always” không dùng với “be”, còn “ready always” đặt trạng từ sai chỗ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **frequency adverb**: I ___ forget my keys because I check my bag.","options":["never","always","usually","often"],"correct_answer":"never","explanation":"Vì người nói kiểm tra túi nên ý phù hợp là “không bao giờ quên”: “I never forget...”. “Always”, “usually”, “often” đều diễn tả có xảy ra, trái nghĩa với ngữ cảnh.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question order**: How often ___ your mother cook dinner?","options":["does","do","is","are"],"correct_answer":"does","explanation":"Chủ ngữ “your mother” là ngôi thứ ba số ít nên câu hỏi hiện tại đơn dùng “does”. “Do” dùng với I/you/we/they, còn “is/are” không dùng với động từ thường “cook” trong câu hỏi này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **sentence order**: ___ go to the park on Sundays.","options":["We sometimes","Sometimes we","We are sometimes","Sometimes are we"],"correct_answer":"We sometimes","explanation":"Với động từ thường “go”, trạng từ tần suất có thể đứng trước động từ: “We sometimes go...”. “Sometimes we” cũng có thể đúng nếu viết thành cả câu, nhưng lựa chọn này thiếu vị trí tự nhiên theo phần trống đã cho; hai lựa chọn có “are” sai vì “go” là động từ thường.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **verb form**: David often ___ emails in the morning.","options":["checks","check","checking","is check"],"correct_answer":"checks","explanation":"Chủ ngữ “David” là ngôi thứ ba số ít nên động từ hiện tại đơn thêm -s: “checks”. “Check” thiếu -s, “checking” thiếu động từ “be”, còn “is check” sai cấu trúc.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **meaning**: “hardly ever” means ___.","options":["almost never","every day","many times","at all times"],"correct_answer":"almost never","explanation":"“Hardly ever” nghĩa là “hầu như không bao giờ”, gần với “almost never”. Các lựa chọn còn lại diễn tả tần suất cao, không đúng nghĩa.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **negative idea**: Mia ___ eats fast food because she likes healthy meals.","options":["rarely","always","usually","often"],"correct_answer":"rarely","explanation":"Ngữ cảnh nói Mia thích đồ ăn lành mạnh nên “rarely eats fast food” là hợp lý. “Always”, “usually”, “often” đều chỉ tần suất cao, không phù hợp.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **front adverb**: ___, I read before bed.","options":["Usually","Usual","I usually","Usually I am"],"correct_answer":"Usually","explanation":"“Usually” có thể đứng đầu câu và theo sau bằng dấu phẩy: “Usually, I read...”. “Usual” là tính từ, “I usually” không phù hợp sau dấu phẩy, và “Usually I am” thừa “am” trước động từ thường “read”.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **frequency adverb**: Nina ___ drinks tea after lunch.","options":["often","does often","is often","often is"],"correct_answer":"often","explanation":"Với động từ thường “drinks”, trạng từ tần suất đứng trước động từ: “Nina often drinks...”. Các lựa chọn có “does” hoặc “is” làm câu sai vì đây là câu khẳng định hiện tại đơn với động từ thường.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **be placement**: The shops are ___ closed on holidays.","options":["usually","usually are","do usually","closed usually"],"correct_answer":"usually","explanation":"Sau động từ “be”, ta đặt trạng từ tần suất: “are usually closed”. “Usually are” đảo sai vị trí trong câu này, “do usually” không dùng với “be”, và “closed usually” kém tự nhiên, sai trọng tâm ngữ pháp.","difficulty":1},{"type":"fill_blank","question":"Complete the question with the correct **auxiliary**: ___ they always eat breakfast at home?","options":["Do","Does","Are","Is"],"correct_answer":"Do","explanation":"Chủ ngữ “they” dùng trợ động từ “do” trong câu hỏi hiện tại đơn. “Does” dùng cho ngôi thứ ba số ít, còn “are/is” không dùng với động từ thường “eat” ở cấu trúc này.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **main verb**: Lucy usually ___ her room on Friday.","options":["cleans","clean","cleaning","is clean"],"correct_answer":"cleans","explanation":"“Lucy” là ngôi thứ ba số ít nên động từ hiện tại đơn cần thêm -s: “cleans”. “Clean” thiếu -s, “cleaning” thiếu “be”, còn “is clean” biến “clean” thành tính từ nên sai nghĩa.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **adverb position**: My cousins ___ visit us in summer.","options":["sometimes","are sometimes","sometimes are","do sometimes"],"correct_answer":"sometimes","explanation":"Với động từ thường “visit”, trạng từ tần suất đứng trước động từ: “My cousins sometimes visit...”. Các lựa chọn còn lại thêm “are/do” không cần thiết hoặc đặt sai vị trí.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **frequency phrase**: We have English class ___.","options":["twice a week","twice week","two a week","two time week"],"correct_answer":"twice a week","explanation":"Cụm đúng là “twice a week” nghĩa là “hai lần một tuần”. Các lựa chọn còn lại sai dạng diễn đạt tần suất trong tiếng Anh.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **word order**: Emma is ___ at the library after school.","options":["often","often is","does often","at often"],"correct_answer":"often","explanation":"Với “be”, trạng từ tần suất đứng sau động từ “is”: “Emma is often at the library”. Các lựa chọn khác sai vị trí hoặc dùng trợ động từ không phù hợp.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **sentence start**: ___, Dad makes pancakes on Sunday.","options":["Sometimes","Some times","Sometimes he","He sometimes"],"correct_answer":"Sometimes","explanation":"“Sometimes” là trạng từ tần suất và có thể đứng đầu câu. “Some times” nghĩa khác và không tự nhiên ở đây, còn “Sometimes he” và “He sometimes” làm câu bị thừa chủ ngữ khi đã có “Dad”.","difficulty":2},{"type":"error_correction","question":"Find the error: Maria **usually** **walk** **to work** **on Mondays**.","options":["usually","walk","to work","on Mondays"],"correct_answer":"walk","explanation":"“Maria” là ngôi thứ ba số ít nên động từ phải là “walks”. “Usually” đúng vị trí trước động từ thường, còn “to work” và “on Mondays” đúng nghĩa.","difficulty":1},{"type":"error_correction","question":"Find the error: The baby **often** **is** **sleepy** **after lunch**.","options":["often","is","sleepy","after lunch"],"correct_answer":"often","explanation":"Với động từ “be”, trạng từ tần suất đứng sau “is”: “The baby is often sleepy...”. Các phần “is”, “sleepy”, “after lunch” đều đúng nếu đặt lại trạng từ đúng vị trí.","difficulty":2},{"type":"error_correction","question":"Find the error: **Does** **Mike** **usually goes** **to bed early**?","options":["Does","Mike","usually goes","to bed early"],"correct_answer":"usually goes","explanation":"Sau “Does”, động từ chính dùng dạng nguyên mẫu: “usually go”. “Does” đúng cho chủ ngữ “Mike”, và các phần còn lại không sai.","difficulty":1},{"type":"error_correction","question":"Find the error: We **are** **never** **take** **the bus** to school.","options":["are","never","take","the bus"],"correct_answer":"are","explanation":"Với động từ thường “take”, câu khẳng định không dùng “are”: “We never take the bus...”. “Never” đúng vị trí trước động từ thường, “take” đúng với “we”, và “the bus” đúng cụm từ.","difficulty":2},{"type":"error_correction","question":"Find the error: Jack **seldom** **eat** **breakfast** **before seven**.","options":["seldom","eat","breakfast","before seven"],"correct_answer":"eat","explanation":"“Jack” là ngôi thứ ba số ít nên cần “eats”. “Seldom” đúng vị trí trước động từ thường, còn “breakfast” và “before seven” đúng ngữ cảnh.","difficulty":1},{"type":"error_correction","question":"Find the error: They **hardly ever** **watch** **TV** **never** at night.","options":["hardly ever","watch","TV","never"],"correct_answer":"never","explanation":"Không dùng thêm “never” khi đã có “hardly ever” trong cùng ý tần suất. “Hardly ever watch TV at night” đã đủ nghĩa “hầu như không bao giờ xem TV vào buổi tối”.","difficulty":3},{"type":"error_correction","question":"Find the error: **Are** **you** **often visit** **your aunt**?","options":["Are","you","often visit","your aunt"],"correct_answer":"Are","explanation":"Với động từ thường “visit”, câu hỏi hiện tại đơn dùng “Do”: “Do you often visit your aunt?”. “You”, “often visit”, và “your aunt” đúng nếu thay “Are” bằng “Do”.","difficulty":1},{"type":"error_correction","question":"Find the error: Our teacher **is** **always** **gives** **clear examples**.","options":["is","always","gives","clear examples"],"correct_answer":"is","explanation":"Với động từ thường “gives”, không dùng “is” trong câu khẳng định hiện tại đơn: “Our teacher always gives...”. “Always” đúng vị trí trước động từ thường, “gives” đúng với chủ ngữ số ít, và “clear examples” đúng nghĩa.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **adverb position**: Liam ___ brushes his teeth after breakfast.","options":["always","brushes always","is always","always is"],"correct_answer":"always","explanation":"Với động từ thường “brushes”, trạng từ chỉ tần suất đứng trước động từ chính: “always brushes”. Các lựa chọn còn lại đặt trạng từ sai vị trí hoặc thêm “is” không cần thiết.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **be position**: The classroom is ___ quiet in the morning.","options":["usually","usually is","quiet usually","is usually"],"correct_answer":"usually","explanation":"Sau động từ “be” ta đặt trạng từ tần suất: “is usually quiet”. “usually is” lặp lại “is”, còn “quiet usually” và “is usually” không phù hợp với chỗ trống sau “is”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question order**: ___ you usually drink milk at breakfast?","options":["Do","Are","Does","Is"],"correct_answer":"Do","explanation":"Câu hỏi với chủ ngữ “you” và động từ thường “drink” dùng trợ động từ “Do”. “Does” dùng cho he/she/it, còn “Are/Is” dùng với động từ “be” hoặc tiếp diễn.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb form**: Anna sometimes ___ the guitar after school.","options":["plays","play","playing","is play"],"correct_answer":"plays","explanation":"Chủ ngữ “Anna” là ngôi thứ ba số ít nên động từ thường thêm “s”: “plays”. “play” thiếu -s, “playing” thiếu trợ động từ, và “is play” sai cấu trúc.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **frequency meaning**: “once a week” means ___.","options":["one time every week","every day","two times a week","never"],"correct_answer":"one time every week","explanation":"“Once a week” nghĩa là một lần mỗi tuần. Các lựa chọn khác diễn tả tần suất khác: mỗi ngày, hai lần một tuần, hoặc không bao giờ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **negative sentence**: He ___ late for school.","options":["is never","never is","never are","does never"],"correct_answer":"is never","explanation":"Với động từ “be”, trạng từ tần suất đứng sau “be”: “He is never late”. “never is” sai vị trí thông thường, “never are” sai động từ, và “does never” không dùng với tính từ “late”.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **word order**: We visit Grandma ___.","options":["every Sunday","Sunday every","every on Sunday","on every Sunday"],"correct_answer":"every Sunday","explanation":"Cụm tần suất đúng là “every Sunday”. Các cách “Sunday every”, “every on Sunday”, và “on every Sunday” sai trật tự hoặc thừa giới từ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **answer**: “How often do you exercise?” - “___.”","options":["Twice a week","At the gym","Because I like it","With my brother"],"correct_answer":"Twice a week","explanation":"“How often” hỏi về tần suất, nên “Twice a week” là câu trả lời đúng. Các lựa chọn khác trả lời nơi chốn, lý do hoặc người đi cùng.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **front position**: ___, we have soup for dinner.","options":["Sometimes","Neverly","Oftenly","Alwaysly"],"correct_answer":"Sometimes","explanation":"“Sometimes” có thể đứng đầu câu để nói thỉnh thoảng. “Neverly”, “Oftenly”, và “Alwaysly” không phải dạng trạng từ tần suất đúng.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **frequency adverb**: I ___ make my bed in the morning.","options":["usually","usual","am usually","usually am"],"correct_answer":"usually","explanation":"Với động từ thường “make”, trạng từ tần suất đứng trước động từ: “usually make”. “usual” là tính từ, còn hai lựa chọn có “am” không phù hợp với động từ thường này.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **be placement**: My parents are ___ busy on weekdays.","options":["often","often are","busy often","are often"],"correct_answer":"often","explanation":"Sau “are”, ta đặt trạng từ tần suất: “are often busy”. Các lựa chọn còn lại sai vị trí hoặc lặp lại động từ “are”.","difficulty":1},{"type":"fill_blank","question":"Complete the question with the correct **auxiliary**: ___ your sister always walk to school?","options":["Does","Do","Is","Are"],"correct_answer":"Does","explanation":"Chủ ngữ “your sister” là ngôi thứ ba số ít nên câu hỏi với động từ thường dùng “Does”. “Do” dùng cho I/you/we/they, còn “Is/Are” không dùng với động từ thường “walk” trong câu này.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **verb form**: Peter rarely ___ coffee at night.","options":["drinks","drink","drinking","is drink"],"correct_answer":"drinks","explanation":"“Peter” là ngôi thứ ba số ít nên động từ thêm “s”: “drinks”. “drink” thiếu -s, “drinking” thiếu trợ động từ, và “is drink” sai ngữ pháp.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **frequency phrase**: We clean the kitchen ___.","options":["every evening","evening every","every in evening","on every evening"],"correct_answer":"every evening","explanation":"Cụm đúng là “every evening” để nói mỗi tối. Các lựa chọn khác sai trật tự hoặc dùng thừa giới từ.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **adverb position**: Chloe ___ forgets her homework.","options":["hardly ever","ever hardly","is hardly ever","hardly ever is"],"correct_answer":"hardly ever","explanation":"Với động từ thường “forgets”, cụm “hardly ever” đứng trước động từ chính. Các lựa chọn khác đảo sai trật tự hoặc thêm “is” không cần thiết.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **sentence start**: ___, I ride my bike to school.","options":["Usually","Usual","Usually I am","I usually am"],"correct_answer":"Usually","explanation":"“Usually” có thể đứng đầu câu để nhấn mạnh thói quen. “Usual” là tính từ, còn hai lựa chọn có “am” sai vì câu đã có động từ thường “ride”.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **question phrase**: ___ do they go swimming?","options":["How often","How many","How old","How much"],"correct_answer":"How often","explanation":"“How often” dùng để hỏi tần suất. Các lựa chọn khác hỏi số lượng, tuổi hoặc lượng không đếm được.","difficulty":1},{"type":"error_correction","question":"Find the error: Grace **usually** **go** **shopping** **after lunch**.","options":["usually","go","shopping","after lunch"],"correct_answer":"go","explanation":"Chủ ngữ “Grace” là ngôi thứ ba số ít nên động từ phải là “goes”. Các phần còn lại đúng: “usually” đúng vị trí, “shopping” và “after lunch” phù hợp ngữ cảnh.","difficulty":1},{"type":"error_correction","question":"Find the error: My uncle **is** **often** **drive** **to work**.","options":["is","often","drive","to work"],"correct_answer":"is","explanation":"Với động từ thường “drive”, không dùng “is”; câu đúng là “My uncle often drives to work.” “often” đúng vị trí, “drive” cần đổi thành “drives” sau khi bỏ “is”, và “to work” đúng nghĩa.","difficulty":2},{"type":"error_correction","question":"Find the error: **Does** **Ella** **always helps** **her mom**?","options":["Does","Ella","always helps","her mom"],"correct_answer":"always helps","explanation":"Sau “Does”, động từ chính phải ở dạng nguyên mẫu: “always help”. “Does”, “Ella”, và “her mom” đều phù hợp trong câu hỏi này.","difficulty":2},{"type":"error_correction","question":"Find the error: The buses **always** **are** **full** **at six**.","options":["always","are","full","at six"],"correct_answer":"always","explanation":"Với động từ “be”, trạng từ tần suất đứng sau “are”: “The buses are always full”. Các phần “are”, “full”, và “at six” đúng trong câu.","difficulty":2},{"type":"error_correction","question":"Find the error: We **never** **don't drink** **soda** **at home**.","options":["never","don't drink","soda","at home"],"correct_answer":"don't drink","explanation":"“Never” đã mang nghĩa phủ định, nên không dùng thêm “don’t”; câu đúng là “We never drink soda at home.” Các phần còn lại đúng nghĩa và đúng vị trí.","difficulty":2},{"type":"error_correction","question":"Find the error: Jenny **sometimes** **watchs** **cartoons** **on Friday**.","options":["sometimes","watchs","cartoons","on Friday"],"correct_answer":"watchs","explanation":"Động từ “watch” thêm “es” với chủ ngữ ngôi thứ ba số ít: “watches”. “sometimes” đúng vị trí, “cartoons” và “on Friday” phù hợp.","difficulty":1},{"type":"error_correction","question":"Find the error: **Do** **the children** **usually plays** **outside**?","options":["Do","the children","usually plays","outside"],"correct_answer":"usually plays","explanation":"Sau “Do”, động từ chính ở dạng nguyên mẫu: “usually play”. “Do” đúng với chủ ngữ số nhiều, còn “the children” và “outside” đúng trong câu.","difficulty":2},{"type":"error_correction","question":"Find the error: Our dog **rarely** **barks** **loudly** **never**.","options":["rarely","barks","loudly","never"],"correct_answer":"never","explanation":"Không dùng thêm “never” khi câu đã có “rarely”; câu đúng là “Our dog rarely barks loudly.” Các phần “rarely”, “barks”, và “loudly” đều đúng.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **adverb position**: Tom ___ reads a book before bed.","options":["always","is always","always is","does always"],"correct_answer":"always","explanation":"Đáp án đúng là “always” vì trạng từ tần suất đứng trước động từ thường “reads”. “is always” và “always is” dùng sai vì không có động từ to-be trong câu; “does always” không dùng trong câu khẳng định đơn giản này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **be position**: My brother is ___ hungry after school.","options":["usually","usually is","does usually","hungry usually"],"correct_answer":"usually","explanation":"Đáp án đúng là “usually” vì với động từ to-be, trạng từ tần suất đứng sau “is”. Các lựa chọn khác làm sai trật tự câu hoặc thêm trợ động từ không cần thiết.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question order**: Does Maria ___ listen to music in the evening?","options":["often","is often","often listens","listens often"],"correct_answer":"often","explanation":"Đáp án đúng là “often” vì trong câu hỏi với “Does”, động từ chính dùng dạng nguyên mẫu “listen” và trạng từ đứng trước động từ chính. “often listens” và “listens often” sai dạng/trật tự; “is often” sai vì không dùng to-be ở đây.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **sentence**:","options":["Ben never eats fish.","Ben eats never fish.","Ben is never eats fish.","Ben never eat fish."],"correct_answer":"Ben never eats fish.","explanation":"Đáp án đúng là “Ben never eats fish” vì “never” đứng trước động từ thường và chủ ngữ ngôi ba số ít cần “eats”. Các câu còn lại sai vị trí trạng từ, thừa “is”, hoặc sai dạng động từ.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **frequency phrase**: I go to the library ___.","options":["twice a month","twice month","two a month","twice in month"],"correct_answer":"twice a month","explanation":"Đáp án đúng là “twice a month”, nghĩa là hai lần mỗi tháng. Các lựa chọn khác thiếu mạo từ “a” hoặc dùng cấu trúc không tự nhiên trong tiếng Anh.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **frequency adverb**: We ___ play football on Sundays.","options":["usually","are usually","usually are","does usually"],"correct_answer":"usually","explanation":"Đáp án đúng là “usually” vì trạng từ tần suất đứng trước động từ thường “play”. Các đáp án có “are” hoặc “does” không phù hợp với cấu trúc câu khẳng định này.","difficulty":1},{"type":"fill_blank","question":"Complete the question with the correct **question phrase**: ___ do you visit your grandparents?","options":["How often","How many","What often","When often"],"correct_answer":"How often","explanation":"Đáp án đúng là “How often” vì cụm này dùng để hỏi tần suất. “How many” hỏi số lượng, còn “What often” và “When often” không phải cấu trúc đúng.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **verb form**: Lucy seldom ___ her room before breakfast.","options":["cleans","clean","cleaning","is clean"],"correct_answer":"cleans","explanation":"Đáp án đúng là “cleans” vì chủ ngữ “Lucy” là ngôi ba số ít ở hiện tại đơn. “clean” thiếu -s, “cleaning” thiếu trợ động từ, và “is clean” sai nghĩa/cấu trúc.","difficulty":2},{"type":"error_correction","question":"Find the error: Nina **usually** **walk** **to school** **on weekdays**.","options":["usually","walk","to school","on weekdays"],"correct_answer":"walk","explanation":"Lỗi là “walk” vì chủ ngữ “Nina” là ngôi ba số ít nên cần “walks”. “usually” đúng vị trí trước động từ thường, còn “to school” và “on weekdays” đúng về nghĩa.","difficulty":1},{"type":"error_correction","question":"Find the error: The baby **is** **never** **cries** **at night**.","options":["is","never","cries","at night"],"correct_answer":"is","explanation":"Lỗi là “is” vì câu dùng động từ thường “cries”, không cần thêm to-be. Câu đúng là “The baby never cries at night”; “never” đứng đúng trước động từ thường.","difficulty":2},{"type":"error_correction","question":"Find the error: **Do** **your friends** **always are** **kind**?","options":["Do","your friends","always are","kind"],"correct_answer":"Do","explanation":"Lỗi là “Do” vì câu hỏi với động từ to-be phải dùng “Are your friends always kind?”. “your friends”, “always are” trong câu gốc bị ảnh hưởng bởi trợ động từ sai, và “kind” là tính từ đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: Dad **sometimes** **cooks** **never** **on Saturday**.","options":["sometimes","cooks","never","on Saturday"],"correct_answer":"never","explanation":"Lỗi là “never” vì không nên dùng hai trạng từ tần suất “sometimes” và “never” cùng mô tả một hành động trong câu đơn này. “sometimes” đứng đúng trước “cooks”, và các phần còn lại đúng cấu trúc.","difficulty":2},{"type":"multiple_choice","question":"Choose the sentence where the adverb of frequency is used **correctly**:","options":["My cat often is sleeping on the sofa.","They don't never visit their grandparents.","We usually play football on Saturdays.","He always has sometimes breakfast at 7 AM."],"correct_answer":"We usually play football on Saturdays.","explanation":"Trạng từ \"usually\" đứng trước động từ thường \"play\" và câu diễn tả một hành động thường xuyên diễn ra vào thứ Bảy, ngữ pháp và nghĩa đều đúng. Các lựa chọn khác sai về vị trí trạng từ (A), cấu trúc phủ định (lặp từ phủ định - B) hoặc lạm dụng trạng từ (D).","difficulty":2}]$grammar$::jsonb, 'ai-golden', 12
from public.grammar_topics t where t.slug = 'adverbs-frequency'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 13. present-continuous
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('present-continuous', 'Present Continuous', 'Thì Hiện tại tiếp diễn', 'beginner', 13)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Hiện tại tiếp diễn', 'Thì **Hiện tại tiếp diễn** (Present Continuous) diễn tả những hành động **đang diễn ra** ngay tại thời điểm nói hoặc xung quanh thời điểm nói. Nó cũng có thể dùng để nói về những **kế hoạch đã được sắp xếp** trong tương lai gần. Đây là thì rất quan trọng để mô tả những gì đang xảy ra trong cuộc sống của bạn.', $grammar$[{"en":"She is reading a book right now.","vi":"Cô ấy đang đọc sách ngay bây giờ.","note":"Hành động đang diễn ra tại thời điểm nói.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"is","start":4,"end":6,"role":"auxiliary"},{"word":"reading","start":7,"end":14,"role":"verb"},{"word":"a","start":15,"end":16,"role":"article"},{"word":"book","start":17,"end":21,"role":"noun"},{"word":"right","start":22,"end":27,"role":"adverb"},{"word":"now","start":28,"end":31,"role":"adverb"}]},{"en":"They aren't watching TV at the moment.","vi":"Họ không đang xem TV vào lúc này.","note":"Phủ định, hành động không diễn ra.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"aren't","start":5,"end":11,"role":"auxiliary"},{"word":"watching","start":12,"end":20,"role":"verb"},{"word":"TV","start":21,"end":23,"role":"noun"},{"word":"at","start":24,"end":26,"role":"preposition"},{"word":"the","start":27,"end":30,"role":"article"},{"word":"moment","start":31,"end":37,"role":"noun"}]},{"en":"Are you listening to me?","vi":"Bạn có đang nghe tôi nói không?","note":"Câu hỏi nghi vấn.","annotations":[{"word":"Are","start":0,"end":3,"role":"auxiliary"},{"word":"you","start":4,"end":7,"role":"pronoun"},{"word":"listening","start":8,"end":17,"role":"verb"},{"word":"to","start":18,"end":20,"role":"preposition"},{"word":"me","start":21,"end":23,"role":"pronoun"}]},{"en":"My brother is working on a new project this month.","vi":"Anh trai tôi đang làm một dự án mới tháng này.","note":"Hành động tạm thời, kéo dài xung quanh hiện tại.","annotations":[{"word":"My","start":0,"end":2,"role":"determiner"},{"word":"brother","start":3,"end":10,"role":"noun"},{"word":"is","start":11,"end":13,"role":"auxiliary"},{"word":"working","start":14,"end":21,"role":"verb"},{"word":"on","start":22,"end":24,"role":"preposition"},{"word":"a","start":25,"end":26,"role":"article"},{"word":"new","start":27,"end":30,"role":"adjective"},{"word":"project","start":31,"end":38,"role":"noun"},{"word":"this","start":39,"end":43,"role":"determiner"},{"word":"month","start":44,"end":49,"role":"noun"}]},{"en":"We are having dinner with friends tomorrow evening.","vi":"Chúng tôi sẽ ăn tối với bạn bè vào tối mai.","note":"Kế hoạch đã được sắp xếp trong tương lai gần.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"are","start":3,"end":6,"role":"auxiliary"},{"word":"having","start":7,"end":13,"role":"verb"},{"word":"dinner","start":14,"end":20,"role":"noun"},{"word":"with","start":21,"end":25,"role":"preposition"},{"word":"friends","start":26,"end":33,"role":"noun"},{"word":"tomorrow","start":34,"end":42,"role":"determiner"},{"word":"evening","start":43,"end":50,"role":"noun"}]},{"en":"Look! It is raining heavily outside.","vi":"Nhìn kìa! Trời đang mưa to bên ngoài.","note":"Dấu hiệu 'Look!' chỉ hành động đang diễn ra.","annotations":[{"word":"Look","start":0,"end":4,"role":"verb"},{"word":"It","start":6,"end":8,"role":"pronoun"},{"word":"is","start":9,"end":11,"role":"auxiliary"},{"word":"raining","start":12,"end":19,"role":"verb"},{"word":"heavily","start":20,"end":27,"role":"adverb"},{"word":"outside","start":28,"end":35,"role":"adverb"}]},{"en":"Why are you always interrupting me?","vi":"Sao bạn lúc nào cũng ngắt lời tôi vậy?","note":"Diễn tả sự khó chịu về một hành động lặp lại.","annotations":[{"word":"Why","start":0,"end":3,"role":"adverb"},{"word":"are","start":4,"end":7,"role":"auxiliary"},{"word":"you","start":8,"end":11,"role":"pronoun"},{"word":"always","start":12,"end":18,"role":"adverb"},{"word":"interrupting","start":19,"end":31,"role":"verb"},{"word":"me","start":32,"end":34,"role":"pronoun"}]},{"en":"I am not feeling well today.","vi":"Hôm nay tôi không cảm thấy khỏe.","note":"Phủ định, trạng thái tạm thời.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"am","start":2,"end":4,"role":"auxiliary"},{"word":"not","start":5,"end":8,"role":"adverb"},{"word":"feeling","start":9,"end":16,"role":"verb"},{"word":"well","start":17,"end":21,"role":"adverb"},{"word":"today","start":22,"end":27,"role":"adverb"}]}]$grammar$::jsonb, $grammar${"definition":"Thì **Hiện tại tiếp diễn** (Present Continuous) diễn tả những hành động **đang diễn ra** ngay tại thời điểm nói hoặc xung quanh thời điểm nói. Nó cũng có thể dùng để nói về những **kế hoạch đã được sắp xếp** trong tương lai gần. Đây là thì rất quan trọng để mô tả những gì đang xảy ra trong cuộc sống của bạn.","usage":[{"icon":"⏰","label":"Hành động đang diễn ra ngay lúc nói","en":"I am studying English now.","vi":"Tôi đang học tiếng Anh bây giờ."},{"icon":"🗓️","label":"Hành động tạm thời xung quanh hiện tại","en":"She is living with her aunt this month.","vi":"Cô ấy đang sống với dì của mình tháng này."},{"icon":"✈️","label":"Kế hoạch, sắp xếp trong tương lai gần (đã định trước)","en":"We are flying to Japan next week.","vi":"Chúng tôi sẽ bay đến Nhật Bản vào tuần tới."},{"icon":"😠","label":"Hành động lặp đi lặp lại gây khó chịu (thường với 'always')","en":"He is always complaining about something.","vi":"Anh ấy lúc nào cũng than phiền về điều gì đó."}],"formula":{"rows":[{"form":"(+) Khẳng định","base":"S + am/is/are + V-ing"},{"form":"(−) Phủ định","base":"S + am/is/are + not + V-ing"},{"form":"(?) Nghi vấn","base":"Am/Is/Are + S + V-ing?"}],"note":"Cách chia động từ 'to be':\n-   **I** đi với **am**\n-   **He / She / It / Danh từ số ít** đi với **is**\n-   **You / We / They / Danh từ số nhiều** đi với **are**\n\nDạng rút gọn:\n-   I'm, You're, He's, She's, It's, We're, They're\n-   isn't (is not), aren't (are not)"},"rules":[{"case":"Đa số động từ","rule":"+ ing","example":"work → working · play → playing"},{"case":"Động từ tận cùng bằng -e","rule":"bỏ -e rồi + ing","example":"make → making · write → writing"},{"case":"Động từ tận cùng bằng -ie","rule":"đổi -ie thành -y rồi + ing","example":"lie → lying · die → dying"},{"case":"Động từ một âm tiết, tận cùng là phụ âm + nguyên âm + phụ âm (trừ h, w, y, x)","rule":"gấp đôi phụ âm cuối rồi + ing","example":"run → running (r-u-n) · stop → stopping (s-t-o-p) · swim → swimming (s-w-i-m)\n*Giải thích:* **Phụ âm** là các chữ cái không phải nguyên âm. **Nguyên âm** là a, e, i, o, u."}],"signals":["now","right now","at the moment","at present","currently","today","tonight","this week/month/year","listen!","look!"],"examples":[{"en":"She is reading a book right now.","vi":"Cô ấy đang đọc sách ngay bây giờ.","note":"Hành động đang diễn ra tại thời điểm nói.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"is","start":4,"end":6,"role":"auxiliary"},{"word":"reading","start":7,"end":14,"role":"verb"},{"word":"a","start":15,"end":16,"role":"article"},{"word":"book","start":17,"end":21,"role":"noun"},{"word":"right","start":22,"end":27,"role":"adverb"},{"word":"now","start":28,"end":31,"role":"adverb"}]},{"en":"They aren't watching TV at the moment.","vi":"Họ không đang xem TV vào lúc này.","note":"Phủ định, hành động không diễn ra.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"aren't","start":5,"end":11,"role":"auxiliary"},{"word":"watching","start":12,"end":20,"role":"verb"},{"word":"TV","start":21,"end":23,"role":"noun"},{"word":"at","start":24,"end":26,"role":"preposition"},{"word":"the","start":27,"end":30,"role":"article"},{"word":"moment","start":31,"end":37,"role":"noun"}]},{"en":"Are you listening to me?","vi":"Bạn có đang nghe tôi nói không?","note":"Câu hỏi nghi vấn.","annotations":[{"word":"Are","start":0,"end":3,"role":"auxiliary"},{"word":"you","start":4,"end":7,"role":"pronoun"},{"word":"listening","start":8,"end":17,"role":"verb"},{"word":"to","start":18,"end":20,"role":"preposition"},{"word":"me","start":21,"end":23,"role":"pronoun"}]},{"en":"My brother is working on a new project this month.","vi":"Anh trai tôi đang làm một dự án mới tháng này.","note":"Hành động tạm thời, kéo dài xung quanh hiện tại.","annotations":[{"word":"My","start":0,"end":2,"role":"determiner"},{"word":"brother","start":3,"end":10,"role":"noun"},{"word":"is","start":11,"end":13,"role":"auxiliary"},{"word":"working","start":14,"end":21,"role":"verb"},{"word":"on","start":22,"end":24,"role":"preposition"},{"word":"a","start":25,"end":26,"role":"article"},{"word":"new","start":27,"end":30,"role":"adjective"},{"word":"project","start":31,"end":38,"role":"noun"},{"word":"this","start":39,"end":43,"role":"determiner"},{"word":"month","start":44,"end":49,"role":"noun"}]},{"en":"We are having dinner with friends tomorrow evening.","vi":"Chúng tôi sẽ ăn tối với bạn bè vào tối mai.","note":"Kế hoạch đã được sắp xếp trong tương lai gần.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"are","start":3,"end":6,"role":"auxiliary"},{"word":"having","start":7,"end":13,"role":"verb"},{"word":"dinner","start":14,"end":20,"role":"noun"},{"word":"with","start":21,"end":25,"role":"preposition"},{"word":"friends","start":26,"end":33,"role":"noun"},{"word":"tomorrow","start":34,"end":42,"role":"determiner"},{"word":"evening","start":43,"end":50,"role":"noun"}]},{"en":"Look! It is raining heavily outside.","vi":"Nhìn kìa! Trời đang mưa to bên ngoài.","note":"Dấu hiệu 'Look!' chỉ hành động đang diễn ra.","annotations":[{"word":"Look","start":0,"end":4,"role":"verb"},{"word":"It","start":6,"end":8,"role":"pronoun"},{"word":"is","start":9,"end":11,"role":"auxiliary"},{"word":"raining","start":12,"end":19,"role":"verb"},{"word":"heavily","start":20,"end":27,"role":"adverb"},{"word":"outside","start":28,"end":35,"role":"adverb"}]},{"en":"Why are you always interrupting me?","vi":"Sao bạn lúc nào cũng ngắt lời tôi vậy?","note":"Diễn tả sự khó chịu về một hành động lặp lại.","annotations":[{"word":"Why","start":0,"end":3,"role":"adverb"},{"word":"are","start":4,"end":7,"role":"auxiliary"},{"word":"you","start":8,"end":11,"role":"pronoun"},{"word":"always","start":12,"end":18,"role":"adverb"},{"word":"interrupting","start":19,"end":31,"role":"verb"},{"word":"me","start":32,"end":34,"role":"pronoun"}]},{"en":"I am not feeling well today.","vi":"Hôm nay tôi không cảm thấy khỏe.","note":"Phủ định, trạng thái tạm thời.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"am","start":2,"end":4,"role":"auxiliary"},{"word":"not","start":5,"end":8,"role":"adverb"},{"word":"feeling","start":9,"end":16,"role":"verb"},{"word":"well","start":17,"end":21,"role":"adverb"},{"word":"today","start":22,"end":27,"role":"adverb"}]}],"mistakes":[{"wrong":"She studying now.","right":"She **is** studying now.","why":"Quên động từ 'to be' (am/is/are) là lỗi rất phổ biến. Thì Hiện tại tiếp diễn LUÔN CÓ 'to be' + V-ing."},{"wrong":"They are play football.","right":"They are play**ing** football.","why":"Động từ chính phải thêm -ing. 'To be' không thể đứng một mình với động từ thường."},{"wrong":"I am runing fast.","right":"I am runn**ing** fast.","why":"Động từ 'run' có cấu trúc phụ âm + nguyên âm + phụ âm, cần gấp đôi phụ âm cuối 'n' trước khi thêm -ing."},{"wrong":"He is makeing a cake.","right":"He is mak**ing** a cake.","why":"Động từ tận cùng bằng -e (make), phải bỏ -e rồi mới thêm -ing."},{"wrong":"I am loving this song.","right":"I love this song.","why":"Một số động từ trạng thái (state verbs) như 'love', 'hate', 'know', 'understand', 'want', 'need', 'believe' KHÔNG dùng ở thì tiếp diễn."},{"wrong":"I am wanting something to eat.","right":"I want something to eat.","why":"Want là động từ trạng thái nên thông thường không dùng ở thì tiếp diễn."},{"wrong":"I going to the convenience store.","right":"I am going to the convenience store.","why":"Hiện tại tiếp diễn luôn cần am/is/are trước động từ V-ing."}],"tips":"**Mẹo nhớ:**\n-   **3 chữ cái thần kỳ:** S + **be** + **V-ing**. Nhớ đủ 3 thành phần này là đúng cấu trúc thì Hiện tại tiếp diễn.\n-   **Đang diễn ra:** Cứ thấy cái gì \"đang\" thì nghĩ ngay đến Hiện tại tiếp diễn.\n-   **Cẩn thận -ing:** Luôn kiểm tra quy tắc thêm -ing (bỏ -e, gấp đôi phụ âm, đổi -ie thành -y, v.v.) để tránh sai chính tả.","comparison":"**Hiện tại tiếp diễn vs Hiện tại đơn:** Tiếp diễn = tình huống TẠM THỜI (*I'm living with friends until I find my own place* — ở tạm). Đơn = tình huống LÂU DÀI / cố định (*My parents live in London. They have lived there all their lives.* — ổn định).","timeline":{"caption":"Ví dụ \"I am studying English now\" — hành động bắt đầu trước hiện tại, tiếp diễn xuyên qua hiện tại, và sẽ kết thúc trong tương lai gần.","points":[{"label":"Bắt đầu học","note":"quá khứ"},{"label":"ĐANG HỌC","note":"HIỆN TẠI"},{"label":"Sẽ kết thúc","note":"tương lai"}]}}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Listen! Someone ____ (cry) in the next room.","opts":[],"answer":"is crying","fb":"Listen! = ngay lúc này"},{"type":"fill","q":"Tom ____ (not / like) coffee.","opts":[],"answer":"doesn't like","fb":"like = trong đầu → đơn, phủ định doesn't"},{"type":"fill","q":"We ____ (watch) TV every night.","opts":[],"answer":"watch","fb":"every night · We → V trơ"},{"type":"fill","q":"Where ____ she ____ (go) now?","opts":[],"answer":"is … going","fb":"now → tiếp diễn"},{"type":"fill","q":"My mother ____ (want) a new phone at the moment.","opts":[],"answer":"wants","fb":"want = trong đầu → đơn dù có at the moment"},{"type":"fill","q":"They ____ (build) a new school in my village this year.","opts":[],"answer":"are building","fb":"this year = giai đoạn tạm thời"},{"type":"fill","q":"The train ____ (leave) at 8 a.m. tomorrow.","opts":[],"answer":"leaves","fb":"thời gian biểu cố định → đơn"},{"type":"fill","q":"You ____ always ____ (leave) your phone at home!","opts":[],"answer":"are always leaving","fb":"always + bực mình → tiếp diễn"},{"type":"fill","q":"I ____ (fly) to Da Nang at 6 a.m. tomorrow. My ticket is booked.","opts":[],"answer":"am flying","fb":"đã đặt vé, chốt giờ → hiện tại tiếp diễn"},{"type":"fill","q":"We ____ (have) a big birthday party next weekend. The invitations are sent.","opts":[],"answer":"are having","fb":"thiệp đã gửi = lịch chốt → hiện tại tiếp diễn"},{"type":"fill","q":"Look! That man ____ (try) to open the door of your car.","opts":[],"answer":"is trying","fb":"Look! đầu câu → hiện tại tiếp diễn"},{"type":"fill","q":"Don't come in — the floor ____ (wash) at the moment.","opts":[],"answer":"is being washed","fb":"at the moment = đang xảy ra → is being + V3"},{"type":"fill","q":"Rút gọn: The bridge which was destroyed in the storm is being repaired.","opts":[],"answer":"The bridge destroyed in the storm is being repaired.","fb":"was destroyed bị động → giữ destroyed"}]$grammar$::jsonb, 'ai-golden', 13
from public.grammar_topics t where t.slug = 'present-continuous'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 14. prepositions-place
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('prepositions-place', 'Prepositions of Place', 'Giới từ chỉ nơi chốn', 'beginner', 14)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Giới từ chỉ nơi chốn', '**Giới từ chỉ nơi chốn** (Prepositions of Place) như *in, on, at* mô tả vị trí hoặc phương hướng của người hoặc vật trong không gian. Mỗi giới từ có cách dùng riêng biệt để chỉ sự ở bên trong, trên bề mặt, hay tại một điểm cụ thể.', $grammar$[{"en":"The keys are in my bag.","vi":"Chìa khóa ở trong túi tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"keys","start":4},{"end":12,"role":"auxiliary","word":"are","start":9},{"end":15,"role":"preposition","word":"in","start":13},{"end":18,"role":"determiner","word":"my","start":16},{"end":22,"role":"noun","word":"bag","start":19}]},{"en":"Your phone is on the desk.","vi":"Điện thoại của bạn ở trên bàn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"Your","start":0},{"end":10,"role":"noun","word":"phone","start":5},{"end":13,"role":"auxiliary","word":"is","start":11},{"end":16,"role":"preposition","word":"on","start":14},{"end":20,"role":"article","word":"the","start":17},{"end":25,"role":"noun","word":"desk","start":21}]},{"en":"Meet me at the entrance.","vi":"Gặp tôi ở lối vào.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"verb","word":"Meet","start":0},{"end":7,"role":"pronoun","word":"me","start":5},{"end":10,"role":"preposition","word":"at","start":8},{"end":14,"role":"article","word":"the","start":11},{"end":23,"role":"noun","word":"entrance","start":15}]},{"en":"The bank is opposite the post office.","vi":"Ngân hàng đối diện bưu điện.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"bank","start":4},{"end":11,"role":"auxiliary","word":"is","start":9},{"end":20,"role":"preposition","word":"opposite","start":12},{"end":24,"role":"article","word":"the","start":21},{"end":29,"role":"noun","word":"post","start":25},{"end":36,"role":"noun","word":"office","start":30}]},{"en":"A lamp hangs above the table.","vi":"Một chiếc đèn treo phía trên bàn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"article","word":"A","start":0},{"end":6,"role":"noun","word":"lamp","start":2},{"end":12,"role":"verb","word":"hangs","start":7},{"end":18,"role":"preposition","word":"above","start":13},{"end":22,"role":"article","word":"the","start":19},{"end":28,"role":"noun","word":"table","start":23}]},{"en":"She sat between Minh and Lan.","vi":"Cô ấy ngồi giữa Minh và Lan.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"verb","word":"sat","start":4},{"end":15,"role":"preposition","word":"between","start":8},{"end":20,"role":"noun","word":"Minh","start":16},{"end":24,"role":"conjunction","word":"and","start":21},{"end":28,"role":"noun","word":"Lan","start":25}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **in + không gian bao quanh** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"in + không gian bao quanh","example":"The keys are in my bag."},{"case":"Kiểm tra thành phần theo sau","rule":"on + bề mặt","example":"Your phone is on the desk."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"at + một điểm/vị trí cụ thể","example":"Meet me at the entrance."}],"usage":[{"en":"The keys are in my bag.","vi":"Chìa khóa ở trong túi của tôi.","icon":"📦","label":"IN — bên trong một không gian kín"},{"en":"Your phone is on the desk.","vi":"Điện thoại của bạn ở trên bàn.","icon":"🪑","label":"ON — trên bề mặt"},{"en":"Meet me at the entrance.","vi":"Gặp tôi ở lối vào nhé.","icon":"📌","label":"AT — tại một điểm cụ thể"},{"en":"The bank is opposite the post office.","vi":"Ngân hàng nằm đối diện bưu điện.","icon":"🧭","label":"Chỉ vị trí tương đối (opposite, next to, between)"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"in + không gian bao quanh","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"on + bề mặt","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"at + một điểm/vị trí cụ thể","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["in","on","at","under","behind","in front of","next to","between"],"examples":[{"en":"The keys are in my bag.","vi":"Chìa khóa ở trong túi tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"keys","start":4},{"end":12,"role":"auxiliary","word":"are","start":9},{"end":15,"role":"preposition","word":"in","start":13},{"end":18,"role":"determiner","word":"my","start":16},{"end":22,"role":"noun","word":"bag","start":19}]},{"en":"Your phone is on the desk.","vi":"Điện thoại của bạn ở trên bàn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"Your","start":0},{"end":10,"role":"noun","word":"phone","start":5},{"end":13,"role":"auxiliary","word":"is","start":11},{"end":16,"role":"preposition","word":"on","start":14},{"end":20,"role":"article","word":"the","start":17},{"end":25,"role":"noun","word":"desk","start":21}]},{"en":"Meet me at the entrance.","vi":"Gặp tôi ở lối vào.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"verb","word":"Meet","start":0},{"end":7,"role":"pronoun","word":"me","start":5},{"end":10,"role":"preposition","word":"at","start":8},{"end":14,"role":"article","word":"the","start":11},{"end":23,"role":"noun","word":"entrance","start":15}]},{"en":"The bank is opposite the post office.","vi":"Ngân hàng đối diện bưu điện.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"bank","start":4},{"end":11,"role":"auxiliary","word":"is","start":9},{"end":20,"role":"preposition","word":"opposite","start":12},{"end":24,"role":"article","word":"the","start":21},{"end":29,"role":"noun","word":"post","start":25},{"end":36,"role":"noun","word":"office","start":30}]},{"en":"A lamp hangs above the table.","vi":"Một chiếc đèn treo phía trên bàn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"article","word":"A","start":0},{"end":6,"role":"noun","word":"lamp","start":2},{"end":12,"role":"verb","word":"hangs","start":7},{"end":18,"role":"preposition","word":"above","start":13},{"end":22,"role":"article","word":"the","start":19},{"end":28,"role":"noun","word":"table","start":23}]},{"en":"She sat between Minh and Lan.","vi":"Cô ấy ngồi giữa Minh và Lan.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"verb","word":"sat","start":4},{"end":15,"role":"preposition","word":"between","start":8},{"end":20,"role":"noun","word":"Minh","start":16},{"end":24,"role":"conjunction","word":"and","start":21},{"end":28,"role":"noun","word":"Lan","start":25}]}],"mistakes":[{"wrong":"The cat is in the table.","right":"The cat is on the table.","why":"Trên bề mặt phẳng dùng ON, không dùng in."},{"wrong":"I live at Hanoi.","right":"I live in Hanoi.","why":"Thành phố/quốc gia dùng IN, không dùng at."},{"wrong":"She is standing in the bus stop.","right":"She is standing at the bus stop.","why":"Tại một điểm cụ thể dùng AT."},{"wrong":"The picture is in the wall.","right":"The picture is on the wall.","why":"Treo trên bề mặt tường dùng ON."}],"timeline":null,"comparison":"**In vs On vs At:** *In* = bên trong không gian 3 chiều (in the bottle, in Hanoi). *On* = trên bề mặt phẳng, tầng nhà (on the table, on the second floor). *At* = tại một điểm/sự kiện (at the bus stop, at a conference). Cặp ví dụ: *water IN the bottle* vs *a label ON the bottle*.","definition":"**Giới từ chỉ nơi chốn** (Prepositions of Place) như *in, on, at* mô tả vị trí hoặc phương hướng của người hoặc vật trong không gian. Mỗi giới từ có cách dùng riêng biệt để chỉ sự ở bên trong, trên bề mặt, hay tại một điểm cụ thể."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: Your phone ___ on the desk.","answer":["is"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 14
from public.grammar_topics t where t.slug = 'prepositions-place'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 15. imperatives
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('imperatives', 'Imperatives', 'Câu mệnh lệnh', 'beginner', 15)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu mệnh lệnh', '**Câu mệnh lệnh** (imperatives) sử dụng dạng nguyên thể của động từ để đưa ra mệnh lệnh, chỉ dẫn, yêu cầu hoặc lời khuyên trực tiếp. Cấu trúc này thường lược bỏ chủ ngữ và có thể kết thúc bằng dấu chấm hoặc dấu chấm than để thể hiện mức độ khẩn cấp.', $grammar$[{"en":"Please write your name here.","vi":"Vui lòng viết tên của bạn ở đây.","note":"Please làm yêu cầu lịch sự.","annotations":[{"word":"Please","start":0,"end":6,"role":"interjection"},{"word":"write","start":7,"end":12,"role":"verb"},{"word":"your","start":13,"end":17,"role":"determiner"},{"word":"name","start":18,"end":22,"role":"noun"},{"word":"here","start":23,"end":27,"role":"adverb"}]},{"en":"Don't open the window.","vi":"Đừng mở cửa sổ.","note":"Don't + động từ nguyên thể.","annotations":[{"word":"Don't","start":0,"end":5,"role":"auxiliary"},{"word":"open","start":6,"end":10,"role":"verb"},{"word":"the","start":11,"end":14,"role":"article"},{"word":"window","start":15,"end":21,"role":"noun"}]},{"en":"Be quiet during the test.","vi":"Hãy giữ im lặng trong lúc kiểm tra.","note":"Mệnh lệnh với động từ be.","annotations":[{"word":"Be","start":0,"end":2,"role":"verb"},{"word":"quiet","start":3,"end":8,"role":"adjective"},{"word":"during","start":9,"end":15,"role":"preposition"},{"word":"the","start":16,"end":19,"role":"noun"},{"word":"test","start":20,"end":24,"role":"other"}]},{"en":"Let's cook dinner together.","vi":"Chúng ta cùng nấu bữa tối nhé.","note":"Let's dùng để rủ cùng làm.","annotations":[{"word":"Let's","start":0,"end":5,"role":"modal"},{"word":"cook","start":6,"end":10,"role":"verb"},{"word":"dinner","start":11,"end":17,"role":"noun"},{"word":"together","start":18,"end":26,"role":"adverb"}]},{"en":"Take the second road on the right.","vi":"Đi vào con đường thứ hai bên phải.","note":"Câu chỉ đường.","annotations":[{"word":"Take","start":0,"end":4,"role":"verb"},{"word":"the","start":5,"end":8,"role":"article"},{"word":"second","start":9,"end":15,"role":"adjective"},{"word":"road","start":16,"end":20,"role":"noun"},{"word":"on","start":21,"end":23,"role":"preposition"},{"word":"the","start":24,"end":27,"role":"article"},{"word":"right","start":28,"end":33,"role":"adjective"}]},{"en":"Let's not tell anyone yet.","vi":"Chúng ta chưa nói với ai nhé.","note":"Let's not + V là lời rủ phủ định.","annotations":[{"word":"Let's","start":0,"end":5,"role":"modal"},{"word":"not","start":6,"end":9,"role":"adverb"},{"word":"tell","start":10,"end":14,"role":"verb"},{"word":"anyone","start":15,"end":21,"role":"pronoun"},{"word":"yet","start":22,"end":25,"role":"adverb"}]}]$grammar$::jsonb, $grammar${"definition":"**Câu mệnh lệnh** (imperatives) sử dụng dạng nguyên thể của động từ để đưa ra mệnh lệnh, chỉ dẫn, yêu cầu hoặc lời khuyên trực tiếp. Cấu trúc này thường lược bỏ chủ ngữ và có thể kết thúc bằng dấu chấm hoặc dấu chấm than để thể hiện mức độ khẩn cấp.","usage":[{"icon":"📣","label":"Ra lệnh hoặc yêu cầu","en":"Close the door, please.","vi":"Vui lòng đóng cửa."},{"icon":"🧭","label":"Hướng dẫn, chỉ đường","en":"Turn left at the bank.","vi":"Rẽ trái tại ngân hàng."},{"icon":"⚠️","label":"Cảnh báo hoặc cấm đoán","en":"Don’t touch that wire.","vi":"Đừng chạm vào dây điện đó."},{"icon":"🤝","label":"Rủ cùng làm với Let’s","en":"Let’s take a short break.","vi":"Chúng ta nghỉ giải lao ngắn nhé."}],"formula":{"rows":[{"form":"Khẳng định","structure":"V nguyên thể + ...","example":"Sit down."},{"form":"Phủ định","structure":"Don't + V nguyên thể + ...","example":"Don't run."},{"form":"Rủ cùng làm","structure":"Let's + V nguyên thể + ...","example":"Let's begin."},{"form":"Lịch sự","structure":"Please + imperative / imperative + please","example":"Please wait."}],"note":"Đọc cấu trúc cùng ví dụ và luôn kiểm tra vai trò, số lượng hoặc dạng động từ theo từng trường hợp."},"rules":[{"case":"Động từ đầu câu","rule":"Dùng nguyên thể không to","example":"Open the window."},{"case":"Chủ ngữ","rule":"Thường bỏ you","example":"Be careful."},{"case":"Phủ định","rule":"Đặt don't trước động từ, kể cả be","example":"Don't be late."},{"case":"Let’s phủ định","rule":"Dùng Let's not + V","example":"Let's not argue."}],"signals":["please","don't","let's","first/next/finally","cảnh báo trên biển báo"],"examples":[{"en":"Please write your name here.","vi":"Vui lòng viết tên của bạn ở đây.","note":"Please làm yêu cầu lịch sự.","annotations":[{"word":"Please","start":0,"end":6,"role":"interjection"},{"word":"write","start":7,"end":12,"role":"verb"},{"word":"your","start":13,"end":17,"role":"determiner"},{"word":"name","start":18,"end":22,"role":"noun"},{"word":"here","start":23,"end":27,"role":"adverb"}]},{"en":"Don't open the window.","vi":"Đừng mở cửa sổ.","note":"Don't + động từ nguyên thể.","annotations":[{"word":"Don't","start":0,"end":5,"role":"auxiliary"},{"word":"open","start":6,"end":10,"role":"verb"},{"word":"the","start":11,"end":14,"role":"article"},{"word":"window","start":15,"end":21,"role":"noun"}]},{"en":"Be quiet during the test.","vi":"Hãy giữ im lặng trong lúc kiểm tra.","note":"Mệnh lệnh với động từ be.","annotations":[{"word":"Be","start":0,"end":2,"role":"verb"},{"word":"quiet","start":3,"end":8,"role":"adjective"},{"word":"during","start":9,"end":15,"role":"preposition"},{"word":"the","start":16,"end":19,"role":"noun"},{"word":"test","start":20,"end":24,"role":"other"}]},{"en":"Let's cook dinner together.","vi":"Chúng ta cùng nấu bữa tối nhé.","note":"Let's dùng để rủ cùng làm.","annotations":[{"word":"Let's","start":0,"end":5,"role":"modal"},{"word":"cook","start":6,"end":10,"role":"verb"},{"word":"dinner","start":11,"end":17,"role":"noun"},{"word":"together","start":18,"end":26,"role":"adverb"}]},{"en":"Take the second road on the right.","vi":"Đi vào con đường thứ hai bên phải.","note":"Câu chỉ đường.","annotations":[{"word":"Take","start":0,"end":4,"role":"verb"},{"word":"the","start":5,"end":8,"role":"article"},{"word":"second","start":9,"end":15,"role":"adjective"},{"word":"road","start":16,"end":20,"role":"noun"},{"word":"on","start":21,"end":23,"role":"preposition"},{"word":"the","start":24,"end":27,"role":"article"},{"word":"right","start":28,"end":33,"role":"adjective"}]},{"en":"Let's not tell anyone yet.","vi":"Chúng ta chưa nói với ai nhé.","note":"Let's not + V là lời rủ phủ định.","annotations":[{"word":"Let's","start":0,"end":5,"role":"modal"},{"word":"not","start":6,"end":9,"role":"adverb"},{"word":"tell","start":10,"end":14,"role":"verb"},{"word":"anyone","start":15,"end":21,"role":"pronoun"},{"word":"yet","start":22,"end":25,"role":"adverb"}]}],"mistakes":[{"wrong":"You close the door!","right":"Close the door!","why":"Câu mệnh lệnh thông thường lược bỏ chủ ngữ you."},{"wrong":"Don't to worry.","right":"Don't worry.","why":"Sau don't dùng động từ nguyên thể không to."},{"wrong":"Let's to go home.","right":"Let's go home.","why":"Sau let's dùng động từ nguyên thể không to."},{"wrong":"You open the door, please!","right":"Open the door, please!","why":"Câu mệnh lệnh BỎ chủ ngữ — bắt đầu thẳng bằng động từ nguyên thể."},{"wrong":"Don't to touch that button.","right":"Don't touch that button.","why":"Sau don't là động từ nguyên thể KHÔNG TO."}],"tips":"**Mẹo:** Bắt đầu thẳng bằng động từ nguyên thể. Muốn nói “đừng” dùng **Don’t + V**; muốn rủ “chúng ta cùng...” dùng **Let’s + V**; thêm **please** để giảm sắc thái ra lệnh.","comparison":"**Imperative vs câu trần thuật:** *You open the file* mô tả hành động; *Open the file* yêu cầu người nghe làm. **Don’t be...** là mệnh lệnh phủ định, còn **You aren’t...** là câu trần thuật.","timeline":null}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"___ careful when you cross the road.","opts":["Be","Are","To be"],"answer":"Be","fb":"Mệnh lệnh dùng động từ nguyên thể."},{"type":"mcq","q":"Choose the polite request.","opts":["Give me water.","Please give me some water.","You give water."],"answer":"Please give me some water.","fb":"Please làm yêu cầu lịch sự hơn."},{"type":"mcq","q":"Choose the correct negative imperative.","opts":["Not talk.","Don't talk.","Doesn't talk."],"answer":"Don't talk.","fb":"Phủ định dùng don't + V."},{"type":"fill","q":"___ the medicine after lunch. (take)","answer":["take"],"fb":"Bắt đầu bằng động từ nguyên thể."},{"type":"fill","q":"___ be noisy in the library. (don't)","answer":["don't"],"fb":"Don't đứng trước be."},{"type":"fill","q":"Let's ___ a taxi. (call)","answer":["call"],"fb":"Sau let's dùng V nguyên thể."},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"You close the door!\"","answer":false,"fb":"SAI. Câu mệnh lệnh thông thường lược bỏ chủ ngữ you. Câu đúng: \"Close the door!\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"Don't to worry.\"","answer":false,"fb":"SAI. Sau don't dùng động từ nguyên thể không to. Câu đúng: \"Don't worry.\""},{"type":"tf","q":"Câu sau đúng ngữ pháp không? → \"Let's to go home.\"","answer":false,"fb":"SAI. Sau let's dùng động từ nguyên thể không to. Câu đúng: \"Let's go home.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["Please write your name here.","You close the door!","Let's cook dinner together."],"answer":"You close the door!","fb":"Câu mệnh lệnh thông thường lược bỏ chủ ngữ you. Câu đúng: \"Close the door!\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["Don't open the window.","Don't to worry.","Take the second road on the right."],"answer":"Don't to worry.","fb":"Sau don't dùng động từ nguyên thể không to. Câu đúng: \"Don't worry.\""},{"type":"error","q":"Câu nào SAI ngữ pháp?","opts":["Be quiet during the test.","Let's to go home.","Let's not tell anyone yet."],"answer":"Let's to go home.","fb":"Sau let's dùng động từ nguyên thể không to. Câu đúng: \"Let's go home.\""}]$grammar$::jsonb, 'ai-golden', 15
from public.grammar_topics t where t.slug = 'imperatives'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 16. modals-ability
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('modals-ability', 'Modals: Ability (can/could)', 'Động từ khuyết thiếu: khả năng (can/could)', 'beginner', 16)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Động từ khuyết thiếu: khả năng (can/could)', 'Động từ khuyết thiếu **''can''** dùng để diễn tả khả năng, sự cho phép hoặc điều có thể xảy ra ở hiện tại. Dạng quá khứ của nó là **''could''**, dùng cho khả năng chung trong quá khứ hoặc lời đề nghị lịch sự, trong khi **''was/were able to''** hoặc **''managed to''** thường dùng cho thành công ở một tình huống cụ thể.', $grammar$[{"en":"Mai can speak Japanese.","vi":"Mai có thể nói tiếng Nhật.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"Mai","start":0},{"end":7,"role":"modal","word":"can","start":4},{"end":13,"role":"verb","word":"speak","start":8},{"end":22,"role":"noun","word":"Japanese","start":14}]},{"en":"I couldn't swim when I was five.","vi":"Tôi không biết bơi khi lên năm.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":10,"role":"modal","word":"couldn't","start":2},{"end":15,"role":"verb","word":"swim","start":11},{"end":20,"role":"conjunction","word":"when","start":16},{"end":22,"role":"pronoun","word":"I","start":21},{"end":26,"role":"auxiliary","word":"was","start":23},{"end":31,"role":"other","word":"five","start":27}]},{"en":"Can you hear me?","vi":"Bạn có nghe thấy tôi không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"modal","word":"Can","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":12,"role":"verb","word":"hear","start":8},{"end":15,"role":"pronoun","word":"me","start":13}]},{"en":"She was able to solve the problem.","vi":"Cô ấy đã giải quyết được vấn đề.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"was","start":4},{"end":12,"role":"adjective","word":"able","start":8},{"end":15,"role":"preposition","word":"to","start":13},{"end":21,"role":"verb","word":"solve","start":16},{"end":25,"role":"article","word":"the","start":22},{"end":33,"role":"noun","word":"problem","start":26}]},{"en":"We'll be able to meet tomorrow.","vi":"Ngày mai chúng ta sẽ có thể gặp nhau.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"pronoun","word":"We'll","start":0},{"end":8,"role":"auxiliary","word":"be","start":6},{"end":13,"role":"adjective","word":"able","start":9},{"end":16,"role":"preposition","word":"to","start":14},{"end":21,"role":"verb","word":"meet","start":17},{"end":30,"role":"adverb","word":"tomorrow","start":22}]},{"en":"He can be very patient.","vi":"Anh ấy đôi khi có thể rất kiên nhẫn.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":6,"role":"modal","word":"can","start":3},{"end":9,"role":"verb","word":"be","start":7},{"end":14,"role":"adverb","word":"very","start":10},{"end":22,"role":"adjective","word":"patient","start":15}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + can/could + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + can/could + V","example":"Mai can speak Japanese."},{"case":"Kiểm tra thành phần theo sau","rule":"S + cannot/could not + V","example":"I couldn't swim when I was five."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"be able to + V","example":"Can you hear me?"}],"usage":[{"en":"Mai can speak Japanese.","vi":"Mai có thể nói tiếng Nhật.","icon":"💪","label":"CAN — khả năng ở hiện tại"},{"en":"I couldn't swim when I was five.","vi":"Hồi năm tuổi tôi chưa biết bơi.","icon":"⏪","label":"COULD — khả năng chung trong quá khứ"},{"en":"Can you hear me?","vi":"Bạn có nghe thấy tôi nói không?","icon":"👂","label":"CAN với động từ tri giác (see, hear, smell)"},{"en":"She was able to solve the problem.","vi":"Cô ấy đã giải được bài toán đó.","icon":"🏆","label":"WAS/WERE ABLE TO — làm được việc cụ thể một lần trong quá khứ"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + can/could + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + cannot/could not + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"be able to + V","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["can","can't","could","couldn't","be able to","managed to"],"examples":[{"en":"Mai can speak Japanese.","vi":"Mai có thể nói tiếng Nhật.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"Mai","start":0},{"end":7,"role":"modal","word":"can","start":4},{"end":13,"role":"verb","word":"speak","start":8},{"end":22,"role":"noun","word":"Japanese","start":14}]},{"en":"I couldn't swim when I was five.","vi":"Tôi không biết bơi khi lên năm.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":10,"role":"modal","word":"couldn't","start":2},{"end":15,"role":"verb","word":"swim","start":11},{"end":20,"role":"conjunction","word":"when","start":16},{"end":22,"role":"pronoun","word":"I","start":21},{"end":26,"role":"auxiliary","word":"was","start":23},{"end":31,"role":"other","word":"five","start":27}]},{"en":"Can you hear me?","vi":"Bạn có nghe thấy tôi không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"modal","word":"Can","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":12,"role":"verb","word":"hear","start":8},{"end":15,"role":"pronoun","word":"me","start":13}]},{"en":"She was able to solve the problem.","vi":"Cô ấy đã giải quyết được vấn đề.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"was","start":4},{"end":12,"role":"adjective","word":"able","start":8},{"end":15,"role":"preposition","word":"to","start":13},{"end":21,"role":"verb","word":"solve","start":16},{"end":25,"role":"article","word":"the","start":22},{"end":33,"role":"noun","word":"problem","start":26}]},{"en":"We'll be able to meet tomorrow.","vi":"Ngày mai chúng ta sẽ có thể gặp nhau.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"pronoun","word":"We'll","start":0},{"end":8,"role":"auxiliary","word":"be","start":6},{"end":13,"role":"adjective","word":"able","start":9},{"end":16,"role":"preposition","word":"to","start":14},{"end":21,"role":"verb","word":"meet","start":17},{"end":30,"role":"adverb","word":"tomorrow","start":22}]},{"en":"He can be very patient.","vi":"Anh ấy đôi khi có thể rất kiên nhẫn.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":6,"role":"modal","word":"can","start":3},{"end":9,"role":"verb","word":"be","start":7},{"end":14,"role":"adverb","word":"very","start":10},{"end":22,"role":"adjective","word":"patient","start":15}]}],"mistakes":[{"wrong":"I can to swim.","right":"I can swim.","why":"Sau can là động từ nguyên thể KHÔNG to."},{"wrong":"She cans drive.","right":"She can drive.","why":"Can là modal — không chia -s theo ngôi."},{"wrong":"He can't to come.","right":"He can't come.","why":"Sau can't cũng là động từ nguyên thể không to."},{"wrong":"The fire spread, but everybody could escape.","right":"The fire spread, but everybody was able to escape.","why":"Thành công trong tình huống cụ thể quá khứ dùng was able to, không dùng could."}],"timeline":null,"comparison":"**Could vs Was able to:** *Could* = khả năng CHUNG trong quá khứ (*My grandfather could swim* — biết bơi nói chung). *Was/were able to / managed to* = THÀNH CÔNG trong một tình huống cụ thể (*He was able to swim to safety* — thoát được lần đó). Tình huống cụ thể thành công → không dùng could.","definition":"Động từ khuyết thiếu **'can'** dùng để diễn tả khả năng, sự cho phép hoặc điều có thể xảy ra ở hiện tại. Dạng quá khứ của nó là **'could'**, dùng cho khả năng chung trong quá khứ hoặc lời đề nghị lịch sự, trong khi **'was/were able to'** hoặc **'managed to'** thường dùng cho thành công ở một tình huống cụ thể."}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"I ___ swim.","opts":["can","cans","can to"],"answer":"can","fb":"Can + động từ nguyên thể swim."},{"type":"mcq","q":"She can ___ English.","opts":["speak","speaks","to speak"],"answer":"speak","fb":"Sau can dùng speak, không thêm -s hoặc to."},{"type":"fill","q":"He ___ ride a bike. (can / cans)","answer":["can"],"fb":"Can không đổi theo chủ ngữ he."},{"type":"mcq","q":"Choose the negative sentence.","opts":["I cannot swim.","I not can swim.","I can not to swim."],"answer":"I cannot swim.","fb":"Phủ định của can là cannot hoặc can't."},{"type":"fill","q":"___ you help me? (Can / Cans)","answer":["Can"],"fb":"Câu hỏi: Can + you + động từ nguyên thể?"},{"type":"mcq","q":"Can Mai sing? Choose the short positive answer.","opts":["Yes, she can.","Yes, she cans.","Yes, she is."],"answer":"Yes, she can.","fb":"Trả lời ngắn với can: Yes, she can."},{"type":"fill","q":"They ___ play football. (can / cans)","answer":["can"],"fb":"Với they vẫn dùng can."},{"type":"mcq","q":"Which sentence asks about ability?","opts":["Can you cook?","You can cook?","Do can you cook?"],"answer":"Can you cook?","fb":"Đưa can lên trước chủ ngữ để hỏi."}]$grammar$::jsonb, 'ai-golden', 16
from public.grammar_topics t where t.slug = 'modals-ability'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 17. countable-uncountable
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('countable-uncountable', 'Countable & Uncountable Nouns', 'Danh từ đếm được & không đếm được', 'beginner', 17)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Danh từ đếm được & không đếm được', '**Danh từ đếm được** (Countable Nouns) là danh từ chỉ các sự vật, hiện tượng có thể đếm được bằng số, có cả dạng số ít và số nhiều (ví dụ: *books*, *chairs*). Ngược lại, **danh từ không đếm được** (Uncountable Nouns) chỉ các chất liệu, khái niệm hoặc sự vật không thể tách rời thành đơn vị đếm được và chỉ có một dạng duy nhất (ví dụ: *water*, *information*).', $grammar$[{"en":"I have two dogs.","vi":"Tôi có hai con chó.","note":"Sử dụng số đếm với danh từ đếm được.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"two","start":7,"end":10,"role":"other"},{"word":"dogs","start":11,"end":15,"role":"noun"}]},{"en":"I need some water.","vi":"Tôi cần một chút nước.","note":"Sử dụng 'some' với danh từ không đếm được.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"need","start":2,"end":6,"role":"verb"},{"word":"some","start":7,"end":11,"role":"determiner"},{"word":"water","start":12,"end":17,"role":"noun"}]},{"en":"I have a book.","vi":"Tôi có một cuốn sách.","note":"Sử dụng 'a' với danh từ đếm được bắt đầu bằng phụ âm.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"a","start":7,"end":8,"role":"article"},{"word":"book","start":9,"end":13,"role":"noun"}]},{"en":"I have an apple.","vi":"Tôi có một quả táo.","note":"Sử dụng 'an' với danh từ đếm được bắt đầu bằng nguyên âm.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"an","start":7,"end":9,"role":"article"},{"word":"apple","start":10,"end":15,"role":"noun"}]},{"en":"I don't have any money.","vi":"Tôi không có tiền.","note":"Sử dụng 'any' với danh từ không đếm được trong câu phủ định.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"don't","start":2,"end":7,"role":"auxiliary"},{"word":"have","start":8,"end":12,"role":"verb"},{"word":"any","start":13,"end":16,"role":"determiner"},{"word":"money","start":17,"end":22,"role":"noun"}]},{"en":"How much water do you need?","vi":"Bạn cần bao nhiêu nước?","note":"Sử dụng 'much' với danh từ không đếm được để hỏi về lượng.","annotations":[{"word":"How","start":0,"end":3,"role":"adverb"},{"word":"much","start":4,"end":8,"role":"determiner"},{"word":"water","start":9,"end":14,"role":"noun"},{"word":"do","start":15,"end":17,"role":"auxiliary"},{"word":"you","start":18,"end":21,"role":"pronoun"},{"word":"need","start":22,"end":26,"role":"verb"}]}]$grammar$::jsonb, $grammar${"definition":"**Danh từ đếm được** (Countable Nouns) là danh từ chỉ các sự vật, hiện tượng có thể đếm được bằng số, có cả dạng số ít và số nhiều (ví dụ: *books*, *chairs*). Ngược lại, **danh từ không đếm được** (Uncountable Nouns) chỉ các chất liệu, khái niệm hoặc sự vật không thể tách rời thành đơn vị đếm được và chỉ có một dạng duy nhất (ví dụ: *water*, *information*).","usage":[{"icon":"📚","label":"Danh từ đếm được","en":"I have two books.","vi":"Tôi có hai cuốn sách."},{"icon":"💧","label":"Danh từ không đếm được","en":"I need water to drink.","vi":"Tôi cần nước để uống."},{"icon":"🍎","label":"Sử dụng 'a' hoặc 'an' với danh từ đếm được","en":"I have an apple.","vi":"Tôi có một quả táo."},{"icon":"📦","label":"Sử dụng 'some' hoặc 'any' với danh từ không đếm được","en":"I need some water.","vi":"Tôi cần một chút nước."}],"formula":{"rows":[{"form":"Danh từ đếm được số ít","base":"a/an + danh từ","note":"a book, an apple"},{"form":"Danh từ đếm được số nhiều","base":"số đếm + danh từ số nhiều","note":"two books, three apples"},{"form":"Danh từ không đếm được","base":"some + danh từ; đơn vị + of + danh từ","note":"some water, two bottles of water"}],"note":"Không đặt số đếm hoặc a/an trực tiếp trước water, advice, furniture. Muốn đếm, dùng đơn vị như bottle hoặc piece."},"rules":[{"case":"Danh từ đếm được","rule":"Có thể sử dụng số đếm","example":"one book, two books"},{"case":"Danh từ không đếm được","rule":"Không sử dụng số đếm","example":"water, air"},{"case":"Sử dụng 'a' hoặc 'an' với danh từ đếm được","rule":"Sử dụng 'a' trước danh từ bắt đầu bằng phụ âm, sử dụng 'an' trước danh từ bắt đầu bằng nguyên âm","example":"a book, an apple"}],"signals":["some","any","much","little","a","an"],"examples":[{"en":"I have two dogs.","vi":"Tôi có hai con chó.","note":"Sử dụng số đếm với danh từ đếm được.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"two","start":7,"end":10,"role":"other"},{"word":"dogs","start":11,"end":15,"role":"noun"}]},{"en":"I need some water.","vi":"Tôi cần một chút nước.","note":"Sử dụng 'some' với danh từ không đếm được.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"need","start":2,"end":6,"role":"verb"},{"word":"some","start":7,"end":11,"role":"determiner"},{"word":"water","start":12,"end":17,"role":"noun"}]},{"en":"I have a book.","vi":"Tôi có một cuốn sách.","note":"Sử dụng 'a' với danh từ đếm được bắt đầu bằng phụ âm.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"a","start":7,"end":8,"role":"article"},{"word":"book","start":9,"end":13,"role":"noun"}]},{"en":"I have an apple.","vi":"Tôi có một quả táo.","note":"Sử dụng 'an' với danh từ đếm được bắt đầu bằng nguyên âm.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"an","start":7,"end":9,"role":"article"},{"word":"apple","start":10,"end":15,"role":"noun"}]},{"en":"I don't have any money.","vi":"Tôi không có tiền.","note":"Sử dụng 'any' với danh từ không đếm được trong câu phủ định.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"don't","start":2,"end":7,"role":"auxiliary"},{"word":"have","start":8,"end":12,"role":"verb"},{"word":"any","start":13,"end":16,"role":"determiner"},{"word":"money","start":17,"end":22,"role":"noun"}]},{"en":"How much water do you need?","vi":"Bạn cần bao nhiêu nước?","note":"Sử dụng 'much' với danh từ không đếm được để hỏi về lượng.","annotations":[{"word":"How","start":0,"end":3,"role":"adverb"},{"word":"much","start":4,"end":8,"role":"determiner"},{"word":"water","start":9,"end":14,"role":"noun"},{"word":"do","start":15,"end":17,"role":"auxiliary"},{"word":"you","start":18,"end":21,"role":"pronoun"},{"word":"need","start":22,"end":26,"role":"verb"}]}],"mistakes":[{"wrong":"I have two waters.","right":"I have two bottles of water.","why":"Danh từ không đếm được không sử dụng số đếm."},{"wrong":"I need a water.","right":"I need some water.","note":"Sử dụng 'some' với danh từ không đếm được."},{"wrong":"I have any books.","right":"I have some books.","note":"Sử dụng 'some' với danh từ đếm được trong câu khẳng định."},{"wrong":"She gave me many advices.","right":"She gave me a lot of advice.","why":"Advice là danh từ không đếm được, không thêm -s và không đi trực tiếp với many."},{"wrong":"He bought two furnitures.","right":"He bought two pieces of furniture.","why":"Furniture là danh từ không đếm được; dùng đơn vị pieces of để đếm."}],"tips":"**Mẹo nhớ:** Danh từ đếm được sử dụng số đếm, danh từ không đếm được sử dụng 'some', 'any', 'much', 'little'. Sử dụng 'a' hoặc 'an' với danh từ đếm được tùy thuộc vào cách phát âm.","comparison":"**Danh từ đếm được vs không đếm được:** Danh từ đếm được có dạng số ít/số nhiều và đi trực tiếp với số đếm (*one apple, two apples*). Danh từ không đếm được không dùng trực tiếp với số đếm hoặc *a/an*; muốn đếm phải thêm đơn vị (*two pieces of advice*, không nói *two advices*).","timeline":null}$grammar$::jsonb, $grammar$[{"type":"mcq","q":"I have ___ book on my desk.","opts":["a","an","two"],"answer":"a","fb":"Book đếm được, số ít và bắt đầu bằng âm /b/: a book."},{"type":"mcq","q":"She has ___ apples.","opts":["two","a","an"],"answer":"two","fb":"Apples là số nhiều, có thể đi với số đếm two."},{"type":"fill","q":"I need ___ water. (some / a)","answer":["some"],"fb":"Water không đếm được; dùng some water."},{"type":"fill","q":"We bought two ___ of water. (bottle)","answer":["bottles"],"fb":"Đếm đơn vị chứa nước: two bottles of water."},{"type":"tf","q":"Is this standard English? 'I have two books.'","answer":true,"fb":"Books đếm được và ở dạng số nhiều sau two."},{"type":"tf","q":"Is this standard English? 'She gave me two advices.'","answer":false,"fb":"Advice không đếm được; nói two pieces of advice."},{"type":"error","q":"Which sentence is incorrect?","opts":["I have two books.","I need some water.","I need a water to drink."],"answer":"I need a water to drink.","fb":"Khi nói chung về nước, dùng some water; a water chỉ có thể dùng trong ngữ cảnh gọi một phần nước."},{"type":"mcq","q":"Which noun is usually uncountable?","opts":["furniture","chair","table"],"answer":"furniture","fb":"Furniture không có dạng số nhiều furnitures trong tiếng Anh chuẩn."},{"type":"fill","q":"She gave me a piece of ___. (advice / advices)","answer":["advice"],"fb":"Advice không thêm -s; dùng a piece of advice."},{"type":"mcq","q":"Choose the natural phrase for two individual items of furniture.","opts":["two pieces of furniture","two furnitures","two furniture"],"answer":"two pieces of furniture","fb":"Đếm furniture qua đơn vị: two pieces of furniture."},{"type":"fill","q":"There are three ___ on the table. (apple)","answer":["apples"],"fb":"Sau three, danh từ đếm được apple chuyển thành apples."},{"type":"mcq","q":"Which phrase names one apple?","opts":["an apple","a apple","one apples"],"answer":"an apple","fb":"Apple bắt đầu bằng âm nguyên âm: an apple."},{"type":"multiple_choice","question":"Choose the correct **article**: I saw ___ dog in the park.","options":["a","an","some","any"],"correct_answer":"a","explanation":"“Dog” là danh từ đếm được số ít và bắt đầu bằng âm phụ âm, nên dùng “a”. “An” dùng trước âm nguyên âm, còn “some/any” không phù hợp với danh từ đếm được số ít ở câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **plural noun**: There are three ___ on the table.","options":["cup","cups","milk","rice"],"correct_answer":"cups","explanation":"Sau số đếm “three”, cần danh từ đếm được số nhiều, nên “cups” đúng. “Cup” là số ít, còn “milk” và “rice” là danh từ không đếm được nên không dùng trực tiếp với số đếm.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **quantifier**: We don't have ___ rice for dinner.","options":["many","any","a","an"],"correct_answer":"any","explanation":"“Rice” là danh từ không đếm được; trong câu phủ định thường dùng “any”. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với danh từ không đếm được.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **quantity word**: Can I have a ___ of coffee?","options":["cup","many","rice","chairs"],"correct_answer":"cup","explanation":"“Coffee” là danh từ không đếm được, nên cần đơn vị đo như “a cup of coffee”. Các lựa chọn còn lại không tạo cụm danh từ đúng trong câu này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **noun form**: I need two ___ for the classroom.","options":["chair","chairs","furniture","air"],"correct_answer":"chairs","explanation":"Sau số đếm “two”, dùng danh từ đếm được số nhiều: “chairs”. “Chair” là số ít, còn “furniture” và “air” là danh từ không đếm được.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question word**: How ___ sugar do you want?","options":["many","much","a","an"],"correct_answer":"much","explanation":"“Sugar” là danh từ không đếm được, nên hỏi số lượng bằng “How much”. “How many” dùng với danh từ đếm được số nhiều, còn “a/an” không phù hợp.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **quantifier**: There are ___ students in the room.","options":["some","much","a","an"],"correct_answer":"some","explanation":"“Students” là danh từ đếm được số nhiều, nên có thể dùng “some”. “Much” dùng với danh từ không đếm được, còn “a/an” chỉ đi với danh từ đếm được số ít.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **measure phrase**: She bought two ___ of bread.","options":["loaves","bread","many","informations"],"correct_answer":"loaves","explanation":"“Bread” thường là danh từ không đếm được, nên cần đơn vị đếm như “loaves”. “Bread” không dùng trực tiếp sau “two” ở nghĩa này; “many” và “informations” sai ngữ pháp.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **noun type**: Which noun is uncountable?","options":["music","banana","ticket","window"],"correct_answer":"music","explanation":"“Music” là danh từ không đếm được trong tiếng Anh. “Banana”, “ticket” và “window” là danh từ đếm được vì có thể nói “one banana”, “two tickets”, “three windows”.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **article**: She has ___ umbrella.","options":["a","an","some","many"],"correct_answer":"an","explanation":"“Umbrella” là danh từ đếm được số ít và bắt đầu bằng âm nguyên âm, nên dùng “an”. “A” dùng trước âm phụ âm; “some/many” không dùng cho danh từ số ít trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **quantifier**: There isn't ___ milk in the fridge.","options":["any","many","a","an"],"correct_answer":"any","explanation":"“Milk” là danh từ không đếm được; trong câu phủ định thường dùng “any”. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với “milk”.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **plural form**: We need five ___ for the game.","options":["ball","balls","water","homework"],"correct_answer":"balls","explanation":"Sau số đếm “five”, danh từ đếm được phải ở dạng số nhiều: “balls”. “Ball” là số ít, còn “water” và “homework” là danh từ không đếm được.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **quantity word**: I ate a ___ of cheese.","options":["piece","many","few","cheeses"],"correct_answer":"piece","explanation":"“Cheese” thường là danh từ không đếm được, nên dùng đơn vị như “a piece of cheese”. “Many/few” dùng với danh từ đếm được số nhiều; “cheeses” không phù hợp với nghĩa thông thường ở câu này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **question word**: How ___ oranges are in the bag?","options":["many","much","some","any"],"correct_answer":"many","explanation":"“Oranges” là danh từ đếm được số nhiều, nên dùng “How many”. “How much” dùng với danh từ không đếm được; “some/any” không dùng để hỏi số lượng theo mẫu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **noun form**: I have a lot of ___ today.","options":["homework","homeworks","chair","chairs"],"correct_answer":"homework","explanation":"“Homework” là danh từ không đếm được, không thêm “s”. “Homeworks” sai trong cách dùng thông thường; “chair/chairs” không hợp nghĩa với câu này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **quantifier**: Do you have ___ money?","options":["any","many","an","a"],"correct_answer":"any","explanation":"“Money” là danh từ không đếm được; trong câu hỏi thường dùng “any”. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không đứng trực tiếp trước “money”.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **measure phrase**: Please buy a ___ of juice.","options":["bottle","many","few","juices"],"correct_answer":"bottle","explanation":"“Juice” là danh từ không đếm được, nên dùng đơn vị chứa như “a bottle of juice”. “Many/few” dùng với danh từ đếm được số nhiều; “juices” không phù hợp trong câu cơ bản này.","difficulty":2},{"type":"error_correction","question":"Find the error: He has three **furniture** in his room.","options":["He","has","three furniture","in his room"],"correct_answer":"three furniture","explanation":"“Furniture” là danh từ không đếm được, nên không nói “three furniture”. Có thể sửa thành “three pieces of furniture”; các phần còn lại không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: I need an **orange juice** after lunch.","options":["I","need","an orange juice","after lunch"],"correct_answer":"an orange juice","explanation":"“Orange juice” thường là danh từ không đếm được, nên không dùng “an” trực tiếp. Có thể nói “some orange juice” hoặc “a glass of orange juice”.","difficulty":2},{"type":"error_correction","question":"Find the error: There is **many** salt in the soup.","options":["There is","many","salt","in the soup"],"correct_answer":"many","explanation":"“Salt” là danh từ không đếm được, nên dùng “much” hoặc “a lot of”, không dùng “many”. Các phần khác đúng cấu trúc cơ bản của câu.","difficulty":2},{"type":"error_correction","question":"Find the error: She bought two **bread** at the bakery.","options":["She","bought","two bread","at the bakery"],"correct_answer":"two bread","explanation":"“Bread” là danh từ không đếm được, nên không dùng trực tiếp với số đếm “two”. Có thể sửa thành “two loaves of bread” hoặc “two pieces of bread”.","difficulty":2},{"type":"error_correction","question":"Find the error: We saw a lot of **child** in the park.","options":["We","saw","a lot of child","in the park"],"correct_answer":"a lot of child","explanation":"“A lot of” đi với danh từ đếm được số nhiều hoặc danh từ không đếm được; “child” số nhiều bất quy tắc là “children”. Câu đúng là “a lot of children”.","difficulty":2},{"type":"error_correction","question":"Find the error: Can you give me a **advice**?","options":["Can you","give me","a advice","?"],"correct_answer":"a advice","explanation":"“Advice” là danh từ không đếm được, nên không dùng “a” trực tiếp. Có thể nói “some advice” hoặc “a piece of advice”.","difficulty":2},{"type":"error_correction","question":"Find the error: There are **much** eggs in the basket.","options":["There are","much","eggs","in the basket"],"correct_answer":"much","explanation":"“Eggs” là danh từ đếm được số nhiều, nên dùng “many”, không dùng “much”. “Much” dùng với danh từ không đếm được.","difficulty":1},{"type":"error_correction","question":"Find the error: This **news** are very important.","options":["This","news","are","very important"],"correct_answer":"are","explanation":"“News” là danh từ không đếm được và đi với động từ số ít. Câu đúng là “This news is very important”; các từ còn lại không phải lỗi chính.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **article**: My brother wants ___ new bike.","options":["a","an","some","many"],"correct_answer":"a","explanation":"“Bike” là danh từ đếm được số ít và bắt đầu bằng âm phụ âm, nên dùng “a”. “An” dùng trước âm nguyên âm; “some” và “many” không dùng trước danh từ số ít dạng này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **article**: Anna has ___ egg for breakfast.","options":["an","a","some","any"],"correct_answer":"an","explanation":"“Egg” là danh từ đếm được số ít và bắt đầu bằng âm nguyên âm, nên dùng “an”. “A” dùng trước âm phụ âm; “some/any” không phù hợp với danh từ số ít ở câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **plural noun**: I can see four ___ in the photo.","options":["cats","cat","water","milks"],"correct_answer":"cats","explanation":"Sau số đếm “four”, danh từ đếm được phải ở dạng số nhiều: “cats”. “Cat” là số ít; “water” không đếm được; “milks” không dùng theo nghĩa thông thường ở trình độ này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **quantifier**: There is ___ tea in the cup.","options":["some","a","many","an"],"correct_answer":"some","explanation":"“Tea” là danh từ không đếm được, nên có thể dùng “some”. “A/an” không đứng trực tiếp trước danh từ không đếm được; “many” dùng với danh từ đếm được số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **noun type**: Which noun is countable?","options":["pencil","milk","music","snow"],"correct_answer":"pencil","explanation":"“Pencil” là danh từ đếm được vì có thể nói “one pencil, two pencils”. “Milk”, “music” và “snow” thường là danh từ không đếm được.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question word**: How ___ bottles of water do we need?","options":["many","much","some","any"],"correct_answer":"many","explanation":"“Bottles” là danh từ đếm được số nhiều, nên dùng “How many”. “How much” dùng với danh từ không đếm được; “some/any” không dùng để hỏi số lượng theo mẫu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **measure phrase**: Please buy a ___ of soap.","options":["bar","slice","bowl","pair"],"correct_answer":"bar","explanation":"Cụm đúng là “a bar of soap” để chỉ một bánh xà phòng. “Slice” dùng cho lát, “bowl” dùng cho bát, “pair” dùng cho một đôi.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **noun form**: We have six ___ in our kitchen.","options":["plates","plate","oil","waters"],"correct_answer":"plates","explanation":"Sau số đếm “six”, danh từ đếm được phải ở dạng số nhiều: “plates”. “Plate” là số ít; “oil” không đếm được; “waters” không phù hợp trong ngữ cảnh cơ bản này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **quantifier**: I don't have ___ time today.","options":["much","many","a","an"],"correct_answer":"much","explanation":"“Time” trong nghĩa thời gian là danh từ không đếm được, nên dùng “much” trong câu phủ định. “Many” dùng với danh từ đếm được số nhiều; “a/an” không đứng trực tiếp trước “time” theo nghĩa này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **article**: We need ___ table for the living room.","options":["a","an","some","many"],"correct_answer":"a","explanation":"“Table” là danh từ đếm được số ít và bắt đầu bằng âm phụ âm, nên dùng “a”. “An” dùng trước âm nguyên âm; “some/many” không phù hợp với danh từ số ít này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **article**: He is eating ___ ice cream.","options":["an","a","many","any"],"correct_answer":"an","explanation":"“Ice cream” ở đây là một phần/que kem đếm được trong ngữ cảnh đơn giản, bắt đầu bằng âm nguyên âm nên dùng “an”. “A” sai vì không đi với âm nguyên âm; “many/any” không phù hợp với câu khẳng định số ít.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **plural form**: There are seven ___ near the school.","options":["buses","bus","busies","buss"],"correct_answer":"buses","explanation":"Danh từ “bus” thêm “-es” khi ở số nhiều: “buses”. “Bus” là số ít; “busies” và “buss” là dạng sai.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **quantifier**: There is ___ soup in the bowl.","options":["some","many","a","an"],"correct_answer":"some","explanation":"“Soup” là danh từ không đếm được, nên dùng “some” trong câu khẳng định. “Many” dùng với danh từ đếm được số nhiều; “a/an” không đứng trực tiếp trước “soup”.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **question word**: How ___ homework do you have tonight?","options":["much","many","a","some"],"correct_answer":"much","explanation":"“Homework” là danh từ không đếm được, nên hỏi bằng “How much”. “Many” dùng với danh từ đếm được số nhiều; “a/some” không tạo câu hỏi đúng ở đây.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **measure phrase**: She drinks a ___ of milk every morning.","options":["glass","piece","slice","pair"],"correct_answer":"glass","explanation":"Cụm tự nhiên là “a glass of milk” để chỉ một ly sữa. “Piece”, “slice” và “pair” không dùng để đo lượng sữa.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **noun form**: My sister bought three ___ yesterday.","options":["dresses","dress","cloth","luggage"],"correct_answer":"dresses","explanation":"Sau số đếm “three”, danh từ đếm được phải ở dạng số nhiều: “dresses”. “Dress” là số ít; “cloth” và “luggage” không phù hợp với cấu trúc này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **quantifier**: Do you need ___ help with this exercise?","options":["any","many","a","an"],"correct_answer":"any","explanation":"“Help” là danh từ không đếm được và trong câu hỏi thường dùng “any”. “Many” dùng với danh từ đếm được số nhiều; “a/an” không đứng trực tiếp trước “help” theo nghĩa này.","difficulty":2},{"type":"error_correction","question":"Find the error: She has two **luggages** for the trip.","options":["She","has","two luggages","for the trip"],"correct_answer":"two luggages","explanation":"“Luggage” là danh từ không đếm được, không dùng trực tiếp với số đếm hoặc thêm “-s”; nên nói “two bags” hoặc “some luggage”. Các phần còn lại đúng về ngữ pháp trong câu.","difficulty":2},{"type":"error_correction","question":"Find the error: I bought a **milk** at the shop.","options":["I","bought","a milk","at the shop"],"correct_answer":"a milk","explanation":"“Milk” thường là danh từ không đếm được, nên không dùng “a” trực tiếp. Có thể nói “some milk” hoặc “a bottle of milk”; các phần khác không sai.","difficulty":1},{"type":"error_correction","question":"Find the error: There are three **juice** on the table.","options":["There are","three juice","on","the table"],"correct_answer":"three juice","explanation":"“Juice” là danh từ không đếm được, không dùng trực tiếp với số đếm. Nên nói “three glasses of juice” hoặc “some juice”; các phần còn lại phù hợp với cấu trúc câu.","difficulty":2},{"type":"error_correction","question":"Find the error: We need much **chairs** for the party.","options":["We","need","much chairs","for the party"],"correct_answer":"much chairs","explanation":"“Chairs” là danh từ đếm được số nhiều, nên dùng “many chairs”, không dùng “much”. “Much” dùng với danh từ không đếm được; các phần khác đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: He gave me an **information** about the bus.","options":["He","gave me","an information","about the bus"],"correct_answer":"an information","explanation":"“Information” là danh từ không đếm được, không dùng “an” trực tiếp. Nên nói “some information” hoặc “a piece of information”; các cụm khác đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: I have five **toothbrush** in my bag.","options":["I","have","five toothbrush","in my bag"],"correct_answer":"five toothbrush","explanation":"Sau số đếm “five”, danh từ đếm được phải ở dạng số nhiều: “toothbrushes”. “I”, “have” và “in my bag” đều đúng trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: There is many **sand** on the beach.","options":["There is","many sand","on","the beach"],"correct_answer":"many sand","explanation":"“Sand” là danh từ không đếm được, nên không dùng “many”; dùng “much sand” hoặc “a lot of sand”. Các phần còn lại có thể đúng khi nói về một lượng cát.","difficulty":2},{"type":"error_correction","question":"Find the error: She needs a **paper** to write a note.","options":["She","needs","a paper","to write a note"],"correct_answer":"a paper","explanation":"“Paper” nghĩa là giấy viết thường không đếm được, nên không dùng “a” trực tiếp. Nên nói “a piece of paper”; các phần khác đúng về nghĩa và cấu trúc.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **article**: I need ___ umbrella today.","options":["a","an","some","many"],"correct_answer":"an","explanation":"“Umbrella” là danh từ đếm được số ít và bắt đầu bằng âm nguyên âm /ʌ/, nên dùng “an”. “A” dùng trước âm phụ âm, còn “some” và “many” không phù hợp với danh từ số ít này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **noun form**: There are two ___ on the desk.","options":["pen","pens","water","rice"],"correct_answer":"pens","explanation":"Sau số đếm “two”, danh từ đếm được phải ở dạng số nhiều: “pens”. “Pen” là số ít, còn “water” và “rice” là danh từ không đếm được nên không đi trực tiếp với “two”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **quantifier**: We need ___ sugar for the cake.","options":["some","a","many","one"],"correct_answer":"some","explanation":"“Sugar” là danh từ không đếm được, nên có thể dùng “some” để nói một lượng không xác định. “A”, “one” dùng với danh từ đếm được số ít; “many” dùng với danh từ đếm được số nhiều.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question word**: How ___ apples are in the bag?","options":["many","much","some","any"],"correct_answer":"many","explanation":"“Apples” là danh từ đếm được số nhiều, nên dùng “How many”. “How much” dùng cho danh từ không đếm được; “some” và “any” không tạo câu hỏi số lượng theo cấu trúc này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **measure phrase**: I want a ___ of coffee.","options":["cup","piece","slice","bottle"],"correct_answer":"cup","explanation":"Với “coffee” không đếm được, ta thường dùng đơn vị đo như “a cup of coffee”. “Piece” thường dùng với advice/information/furniture, “slice” với bánh hoặc bánh mì lát, “bottle” không tự nhiên bằng “cup” trong câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **plural form**: She has three ___.","options":["boxs","boxes","box","boxies"],"correct_answer":"boxes","explanation":"Danh từ “box” kết thúc bằng “x”, nên dạng số nhiều là “boxes”. “Boxs” và “boxies” sai chính tả; “box” là số ít.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **quantifier**: There isn't ___ cheese in the fridge.","options":["much","many","a","one"],"correct_answer":"much","explanation":"“Cheese” thường là danh từ không đếm được, nên dùng “much” trong câu phủ định. “Many” dùng với danh từ đếm được số nhiều, còn “a” và “one” cần danh từ đếm được số ít.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **sentence**: Which sentence is correct?","options":["I have a banana.","I have a water.","I have two rice.","I have many money."],"correct_answer":"I have a banana.","explanation":"“Banana” là danh từ đếm được số ít nên dùng được với “a”. “Water”, “rice” và “money” là danh từ không đếm được nên không dùng trực tiếp với “a”, “two”, hoặc “many” trong nghĩa thông thường.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **article**: She has ___ orange in her lunch box.","options":["an","a","some","many"],"correct_answer":"an","explanation":"“Orange” là danh từ đếm được số ít và bắt đầu bằng âm nguyên âm, nên dùng “an”. “A” dùng trước âm phụ âm, còn “some” và “many” không phù hợp với danh từ số ít này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **plural noun**: I can see five ___ in the garden.","options":["flowers","flower","grass","air"],"correct_answer":"flowers","explanation":"Sau số đếm “five”, cần danh từ đếm được số nhiều: “flowers”. “Flower” là số ít, còn “grass” và “air” là danh từ không đếm được.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **quantifier**: Do you have ___ salt?","options":["any","a","many","one"],"correct_answer":"any","explanation":"Trong câu hỏi với danh từ không đếm được “salt”, ta thường dùng “any”. “A”, “one” dùng với danh từ đếm được số ít; “many” dùng với danh từ đếm được số nhiều.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **question word**: How ___ water is in the bottle?","options":["much","many","a","an"],"correct_answer":"much","explanation":"“Water” là danh từ không đếm được, nên dùng “How much”. “How many” dùng với danh từ đếm được số nhiều; “a” và “an” là mạo từ, không dùng để hỏi số lượng như vậy.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **measure phrase**: Please give me a ___ of bread.","options":["slice","cup","bowl","bag"],"correct_answer":"slice","explanation":"“Bread” thường là danh từ không đếm được, nên dùng cụm đo lường như “a slice of bread”. “Cup”, “bowl” và “bag” không phù hợp tự nhiên bằng “slice” trong câu này.","difficulty":2},{"type":"fill_blank","question":"Fill in the correct **noun form**: My mother bought four ___ for the kitchen.","options":["plates","plate","oil","flour"],"correct_answer":"plates","explanation":"Sau số đếm “four”, cần danh từ đếm được số nhiều: “plates”. “Plate” là số ít, còn “oil” và “flour” là danh từ không đếm được.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **quantifier**: There are ___ tomatoes in the fridge.","options":["some","much","a","one"],"correct_answer":"some","explanation":"“Tomatoes” là danh từ đếm được số nhiều, nên có thể dùng “some”. “Much” dùng với danh từ không đếm được; “a” và “one” dùng với danh từ số ít.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **article**: He is reading ___ interesting book.","options":["an","a","some","any"],"correct_answer":"an","explanation":"“Book” là danh từ đếm được số ít, và tính từ “interesting” bắt đầu bằng âm nguyên âm nên dùng “an”. “A” dùng trước âm phụ âm, còn “some” và “any” không đi với danh từ số ít trong câu này.","difficulty":2},{"type":"error_correction","question":"Find the error: I need two **waters** after the game.","options":["I","need","two waters","after the game"],"correct_answer":"two waters","explanation":"“Water” là danh từ không đếm được, không dùng trực tiếp với số đếm “two”. Có thể sửa thành “two bottles of water” hoặc “some water”; các phần còn lại trong câu đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: There is a lot of **cars** on the street.","options":["There is","a lot of","cars","on the street"],"correct_answer":"There is","explanation":"“Cars” là danh từ đếm được số nhiều, nên động từ phải là “There are”. “A lot of cars” đúng, và cụm “on the street” cũng đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: She wants many **butter** on her toast.","options":["She","wants","many butter","on her toast"],"correct_answer":"many butter","explanation":"“Butter” là danh từ không đếm được, nên không dùng “many”. Nên dùng “some butter” hoặc “much butter”; các phần khác của câu đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: We have three **mouse** in the classroom.","options":["We","have","three mouse","in the classroom"],"correct_answer":"three mouse","explanation":"Sau “three”, danh từ đếm được phải ở số nhiều; dạng số nhiều của “mouse” là “mice”. “We have” và “in the classroom” đều đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: He gave me a **homework** yesterday.","options":["He","gave","me","a homework"],"correct_answer":"a homework","explanation":"“Homework” là danh từ không đếm được, nên không dùng “a”. Có thể sửa thành “some homework” hoặc “a piece of homework”; các phần còn lại đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: I don't have many **money** today.","options":["I","don't have","many money","today"],"correct_answer":"many money","explanation":"“Money” là danh từ không đếm được, nên không dùng “many”. Cần dùng “much money” trong câu phủ định; các phần khác đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: There are two **person** at the door.","options":["There are","two person","at","the door"],"correct_answer":"two person","explanation":"Sau số đếm “two”, danh từ “person” phải đổi sang số nhiều là “people”. “There are” đúng vì chủ ngữ là số nhiều, và phần còn lại không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: Can I have an **cup** of tea?","options":["Can I have","an cup","of tea","?"],"correct_answer":"an cup","explanation":"“Cup” bắt đầu bằng âm phụ âm /k/, nên dùng “a cup”, không dùng “an cup”. “Of tea” đúng vì “tea” là danh từ không đếm được và cần đơn vị đo như “cup”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **quantifier**: There are ___ eggs in the box.","options":["many","much","a little","a"],"correct_answer":"many","explanation":"“Eggs” là danh từ đếm được số nhiều nên dùng “many”. “Much” và “a little” dùng với danh từ không đếm được; “a” chỉ dùng với danh từ đếm được số ít.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **article**: I saw ___ elephant at the zoo.","options":["an","a","some","any"],"correct_answer":"an","explanation":"“Elephant” là danh từ đếm được số ít và bắt đầu bằng âm nguyên âm nên dùng “an”. “A” dùng trước âm phụ âm; “some/any” không phù hợp với danh từ số ít trong câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **measure phrase**: Please buy a ___ of toothpaste.","options":["tube","slice","bowl","cup"],"correct_answer":"tube","explanation":"Kem đánh răng thường được đếm bằng “a tube of toothpaste”. “Slice”, “bowl” và “cup” dùng cho đồ ăn/thức uống khác, không tự nhiên với toothpaste.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **quantifier**: There is ___ rice in the bowl.","options":["some","many","a","an"],"correct_answer":"some","explanation":"“Rice” là danh từ không đếm được nên có thể dùng “some”. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với “rice”.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **article**: She wants ___ sandwich for lunch.","options":["a","an","some","much"],"correct_answer":"a","explanation":"“Sandwich” là danh từ đếm được số ít và bắt đầu bằng âm phụ âm nên dùng “a”. “An” dùng trước âm nguyên âm; “some/much” không phù hợp với danh từ số ít này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **plural noun**: Two ___ stop here every morning.","options":["buses","bus","buss","busies"],"correct_answer":"buses","explanation":"Sau số “two” cần danh từ số nhiều, và số nhiều của “bus” là “buses”. “Bus” là số ít; “buss” và “busies” là dạng sai.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **quantifier**: There isn't ___ coffee in the pot.","options":["much","many","a","an"],"correct_answer":"much","explanation":"“Coffee” là danh từ không đếm được nên dùng “much” trong câu phủ định. “Many” dùng với danh từ đếm được số nhiều; “a/an” không dùng trực tiếp với “coffee”.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **measure phrase**: He eats a ___ of soup for dinner.","options":["bowl","can","slice","bar"],"correct_answer":"bowl","explanation":"Với “soup”, ta thường nói “a bowl of soup”. “Slice” và “bar” dùng cho đồ có dạng miếng/thanh; “can” không tự nhiên trong câu này.","difficulty":1},{"type":"fill_blank","question":"Fill in the correct **noun form**: Put the two ___ on the table.","options":["knives","knife","knifes","knive"],"correct_answer":"knives","explanation":"Sau “two” cần danh từ số nhiều, và số nhiều của “knife” là “knives”. “Knife” là số ít; “knifes” và “knive” là dạng sai.","difficulty":2},{"type":"error_correction","question":"Find the error: I bought three **bread** at the bakery.","options":["I","bought","three","bread"],"correct_answer":"bread","explanation":"“Bread” là danh từ không đếm được nên không đứng trực tiếp sau số đếm; nên nói “three loaves of bread” hoặc “three pieces of bread”. Các phần “I”, “bought” và “three” không sai nếu có đơn vị đếm phù hợp.","difficulty":2},{"type":"error_correction","question":"Find the error: There aren't **much** bananas in the basket.","options":["There aren't","much","bananas","in the basket"],"correct_answer":"much","explanation":"“Bananas” là danh từ đếm được số nhiều nên cần “many”, không phải “much”. Các cụm còn lại đúng về ngữ pháp trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: She has a lot of **furnitures** in her room.","options":["She has","a lot of","furnitures","in her room"],"correct_answer":"furnitures","explanation":"“Furniture” là danh từ không đếm được nên không thêm “s”. “A lot of” dùng được với danh từ không đếm được, còn các cụm khác không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: This **luggage** are heavy at the airport.","options":["This luggage","are","heavy","at the airport"],"correct_answer":"are","explanation":"“Luggage” là danh từ không đếm được và được xem như số ít, nên phải dùng “is”. “This luggage”, “heavy” và “at the airport” đều phù hợp trong câu.","difficulty":2},{"type":"error_correction","question":"Find the **error**: She gave me an **advice** about my studies.","options":["She gave","me","an advice","about my studies"],"correct_answer":"an advice","explanation":"Danh từ 'advice' (lời khuyên) là danh từ không đếm được, vì vậy không thể sử dụng mạo từ 'an' (hoặc 'a') trực tiếp trước nó. Chúng ta có thể nói 'some advice' hoặc 'a piece of advice'.","difficulty":1}]$grammar$::jsonb, 'ai-golden', 17
from public.grammar_topics t where t.slug = 'countable-uncountable'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 18. quantifiers
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('quantifiers', 'Quantifiers (some/any/much/many)', 'Lượng từ (some/any/much/many)', 'beginner', 18)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Lượng từ (some/any/much/many)', '**Lượng từ** như ''some'', ''any'', ''much'' và ''many'' là các từ hạn định giúp xác định số lượng của danh từ mà không cần con số cụ thể. Việc sử dụng chính xác các từ này phụ thuộc vào tính chất đếm được hay không đếm được của danh từ, cũng như loại câu (khẳng định, phủ định hay nghi vấn).', $grammar$[{"en":"We have a few questions.","vi":"Chúng tôi có vài câu hỏi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"verb","word":"have","start":3},{"end":9,"role":"article","word":"a","start":8},{"end":13,"role":"determiner","word":"few","start":10},{"end":23,"role":"noun","word":"questions","start":14}]},{"en":"There isn't much time.","vi":"Không còn nhiều thời gian.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":11,"role":"auxiliary","word":"isn't","start":6},{"end":16,"role":"determiner","word":"much","start":12},{"end":21,"role":"noun","word":"time","start":17}]},{"en":"Do you need any help?","vi":"Bạn có cần giúp gì không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"auxiliary","word":"Do","start":0},{"end":6,"role":"pronoun","word":"you","start":3},{"end":11,"role":"verb","word":"need","start":7},{"end":15,"role":"determiner","word":"any","start":12},{"end":20,"role":"noun","word":"help","start":16}]},{"en":"She bought some apples.","vi":"Cô ấy mua vài quả táo.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"verb","word":"bought","start":4},{"end":15,"role":"determiner","word":"some","start":11},{"end":22,"role":"noun","word":"apples","start":16}]},{"en":"Very few people knew.","vi":"Rất ít người biết.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"adverb","word":"Very","start":0},{"end":8,"role":"determiner","word":"few","start":5},{"end":15,"role":"noun","word":"people","start":9},{"end":20,"role":"verb","word":"knew","start":16}]},{"en":"I drink a little milk each day.","vi":"Tôi uống một ít sữa mỗi ngày.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":7,"role":"verb","word":"drink","start":2},{"end":9,"role":"article","word":"a","start":8},{"end":16,"role":"determiner","word":"little","start":10},{"end":21,"role":"noun","word":"milk","start":17},{"end":26,"role":"determiner","word":"each","start":22},{"end":30,"role":"noun","word":"day","start":27}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **many/few + danh từ đếm được số nhiều** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"many/few + danh từ đếm được số nhiều","example":"We have a few questions."},{"case":"Kiểm tra thành phần theo sau","rule":"much/little + danh từ không đếm được","example":"There isn't much time."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"some/any/a lot of + danh từ phù hợp","example":"Do you need any help?"}],"usage":[{"en":"She bought some apples. Would you like some tea?","vi":"Cô ấy mua vài quả táo. Bạn dùng chút trà nhé?","icon":"➕","label":"SOME — câu khẳng định và lời mời"},{"en":"Do you need any help?","vi":"Bạn có cần giúp gì không?","icon":"❓","label":"ANY — câu phủ định và câu hỏi"},{"en":"There isn't much time.","vi":"Không còn nhiều thời gian đâu.","icon":"🥛","label":"MUCH — đi với danh từ không đếm được"},{"en":"How many students are there?","vi":"Có bao nhiêu học sinh?","icon":"📚","label":"MANY — đi với danh từ đếm được số nhiều"},{"en":"We have a few questions.","vi":"Chúng tôi có một vài câu hỏi.","icon":"🤏","label":"A FEW / A LITTLE — số lượng nhỏ nhưng đủ dùng"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"many/few + danh từ đếm được số nhiều","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"much/little + danh từ không đếm được","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"some/any/a lot of + danh từ phù hợp","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["some","any","much","many","few","little","a lot of","plenty of"],"examples":[{"en":"We have a few questions.","vi":"Chúng tôi có vài câu hỏi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"verb","word":"have","start":3},{"end":9,"role":"article","word":"a","start":8},{"end":13,"role":"determiner","word":"few","start":10},{"end":23,"role":"noun","word":"questions","start":14}]},{"en":"There isn't much time.","vi":"Không còn nhiều thời gian.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"There","start":0},{"end":11,"role":"auxiliary","word":"isn't","start":6},{"end":16,"role":"determiner","word":"much","start":12},{"end":21,"role":"noun","word":"time","start":17}]},{"en":"Do you need any help?","vi":"Bạn có cần giúp gì không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"auxiliary","word":"Do","start":0},{"end":6,"role":"pronoun","word":"you","start":3},{"end":11,"role":"verb","word":"need","start":7},{"end":15,"role":"determiner","word":"any","start":12},{"end":20,"role":"noun","word":"help","start":16}]},{"en":"She bought some apples.","vi":"Cô ấy mua vài quả táo.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"verb","word":"bought","start":4},{"end":15,"role":"determiner","word":"some","start":11},{"end":22,"role":"noun","word":"apples","start":16}]},{"en":"Very few people knew.","vi":"Rất ít người biết.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"adverb","word":"Very","start":0},{"end":8,"role":"determiner","word":"few","start":5},{"end":15,"role":"noun","word":"people","start":9},{"end":20,"role":"verb","word":"knew","start":16}]},{"en":"I drink a little milk each day.","vi":"Tôi uống một ít sữa mỗi ngày.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":7,"role":"verb","word":"drink","start":2},{"end":9,"role":"article","word":"a","start":8},{"end":16,"role":"determiner","word":"little","start":10},{"end":21,"role":"noun","word":"milk","start":17},{"end":26,"role":"determiner","word":"each","start":22},{"end":30,"role":"noun","word":"day","start":27}]}],"mistakes":[{"wrong":"I have many money.","right":"I have a lot of money.","why":"Money không đếm được — không đi với many; dùng a lot of."},{"wrong":"There are much cars.","right":"There are many cars.","why":"Cars đếm được số nhiều dùng many, không dùng much."},{"wrong":"I don't have some time.","right":"I don't have any time.","why":"Câu phủ định dùng ANY, không dùng some."},{"wrong":"She has few money.","right":"She has little money.","why":"Money không đếm được dùng little, không dùng few."}],"timeline":null,"comparison":"**Many/Few vs Much/Little:** *many, few* đi với danh từ ĐẾM ĐƯỢC số nhiều (*few friends*); *much, little* đi với danh từ KHÔNG đếm được (*little time*). Câu khẳng định văn nói chuộng *a lot of* thay cho much/many.","definition":"**Lượng từ** như 'some', 'any', 'much' và 'many' là các từ hạn định giúp xác định số lượng của danh từ mà không cần con số cụ thể. Việc sử dụng chính xác các từ này phụ thuộc vào tính chất đếm được hay không đếm được của danh từ, cũng như loại câu (khẳng định, phủ định hay nghi vấn)."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"We ____ (have) English on Monday and Friday.","opts":[],"answer":"have","fb":"We = số nhiều → V để trơ"},{"type":"fill","q":"____ your parents ____ (work) in a factory?","opts":[],"answer":"Do … work","fb":"parents = số nhiều → Do + V để trơ"},{"type":"fill","q":"Hoa and her sister ____ (go) to school by bike.","opts":[],"answer":"go","fb":"and nối 2 người → số nhiều, V để trơ"},{"type":"fill","q":"Every player in the team ____ (want) to win.","opts":[],"answer":"wants","fb":"Every + danh từ số ít → V số ít"},{"type":"fill","q":"One of my brothers ____ (live) in Da Nang.","opts":[],"answer":"lives","fb":"chủ ngữ chính là “One” → số ít"},{"type":"fill","q":"The cost of these books ____ (be) too high.","opts":[],"answer":"is","fb":"chia theo “The cost” đứng trước of"},{"type":"fill","q":"Neither Bill nor Mary ____ (be) going to the party tonight.","opts":[],"answer":"is","fb":"vế sau là “Mary” → số ít"},{"type":"fill","q":"Some of the money ____ (be) still in the box.","opts":[],"answer":"is","fb":"some of + money không đếm được → số ít"},{"type":"fill","q":"There ____ (be) no girls in this class.","opts":[],"answer":"are","fb":"There + be theo “no girls” số nhiều"},{"type":"fill","q":"Each item in the bill ____ (be) correct.","opts":[],"answer":"is","fb":"Each + danh từ số ít → số ít"},{"type":"fill","q":"Half of the students in my class ____ (wear) glasses.","opts":[],"answer":"wear","fb":"half of + students số nhiều → số nhiều"},{"type":"fill","q":"The boy with his two dogs ____ (be) waiting outside.","opts":[],"answer":"is","fb":"with → theo “The boy” đứng trước"},{"type":"fill","q":"Not only my parents but also my sister ____ (like) this song.","opts":[],"answer":"likes","fb":"vế sau là “my sister” → số ít"},{"type":"fill","q":"These exercises ____ (check) by the teacher every Friday.","opts":[],"answer":"are checked","fb":"exercises số nhiều + every Friday → are + V3"},{"type":"fill","q":"The company sent the customers a free gift.  →  The customers ____ a free gift.","opts":[],"answer":"were sent","fb":"Người lên đầu, số nhiều → were + V3"},{"type":"fill","q":"My mother is ____ nurse at a big hospital.","opts":[],"answer":"a","fb":"nghề nghiệp, đếm được số ít → a"},{"type":"fill","q":"Many students in my class like ____ computer games.","opts":[],"answer":"∅","fb":"danh từ số nhiều nói chung → để trống"},{"type":"fill","q":"Neither Lan nor her friends ____ late for class.  (A is · B am · C are · D was)","opts":[],"answer":"C are","fb":"Neither… nor chia theo chủ ngữ gần nhất là her friends · buổi 8"}]$grammar$::jsonb, 'ai-golden', 18
from public.grammar_topics t where t.slug = 'quantifiers'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 19. prepositions-time
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('prepositions-time', 'Prepositions of Time (in/on/at)', 'Giới từ chỉ thời gian (in/on/at)', 'beginner', 19)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Giới từ chỉ thời gian (in/on/at)', '**Giới từ chỉ thời gian** (*in, on, at*) được sử dụng để xác định thời điểm, ngày tháng, hoặc khoảng thời gian diễn ra một sự kiện. Thông thường, *in* dùng cho tháng, năm, mùa; *on* dùng cho ngày cụ thể; và *at* dùng cho giờ hoặc thời điểm chính xác.', $grammar$[{"en":"I have a meeting in May.","vi":"Tôi có một cuộc họp vào tháng năm.","note":"Sử dụng **in** với tháng.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"a","start":7,"end":8,"role":"article"},{"word":"meeting","start":9,"end":16,"role":"noun"},{"word":"in","start":17,"end":19,"role":"preposition"},{"word":"May","start":20,"end":23,"role":"noun"}]},{"en":"The party is on Saturday.","vi":"Bữa tiệc vào thứ bảy.","note":"Sử dụng **on** với ngày trong tuần.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"party","start":4,"end":9,"role":"noun"},{"word":"is","start":10,"end":12,"role":"auxiliary"},{"word":"on","start":13,"end":15,"role":"preposition"},{"word":"Saturday","start":16,"end":24,"role":"noun"}]},{"en":"I'll meet you at 7 o'clock.","vi":"Tôi sẽ gặp bạn vào lúc 7 giờ.","note":"Sử dụng **at** với giờ.","annotations":[{"word":"I'll","start":0,"end":4,"role":"modal"},{"word":"meet","start":5,"end":9,"role":"verb"},{"word":"you","start":10,"end":13,"role":"pronoun"},{"word":"at","start":14,"end":16,"role":"preposition"},{"word":"7","start":17,"end":18,"role":"other"},{"word":"o'clock","start":19,"end":26,"role":"noun"}]},{"en":"She was born in 1990.","vi":"Cô ấy sinh ra vào năm 1990.","note":"Sử dụng **in** với năm.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"was","start":4,"end":7,"role":"auxiliary"},{"word":"born","start":8,"end":12,"role":"verb"},{"word":"in","start":13,"end":15,"role":"preposition"},{"word":"1990","start":16,"end":20,"role":"other"}]},{"en":"We're going to the beach in summer.","vi":"Chúng tôi sẽ đi đến bãi biển vào mùa hè.","note":"Sử dụng **in** với mùa.","annotations":[{"word":"We're","start":0,"end":5,"role":"pronoun"},{"word":"going","start":6,"end":11,"role":"auxiliary"},{"word":"to","start":12,"end":14,"role":"verb"},{"word":"the","start":15,"end":18,"role":"preposition"},{"word":"beach","start":19,"end":24,"role":"article"},{"word":"in","start":25,"end":27,"role":"noun"},{"word":"summer","start":28,"end":34,"role":"preposition"}]},{"en":"The store is open on Sundays.","vi":"Cửa hàng mở cửa vào chủ nhật.","note":"Sử dụng **on** với ngày trong tuần.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"store","start":4,"end":9,"role":"noun"},{"word":"is","start":10,"end":12,"role":"auxiliary"},{"word":"open","start":13,"end":17,"role":"adjective"},{"word":"on","start":18,"end":20,"role":"preposition"},{"word":"Sundays","start":21,"end":28,"role":"noun"}]},{"en":"The meeting starts at 9 am.","vi":"Cuộc họp bắt đầu vào lúc 9 giờ sáng.","note":"Sử dụng **at** với giờ.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"meeting","start":4,"end":11,"role":"noun"},{"word":"starts","start":12,"end":18,"role":"verb"},{"word":"at","start":19,"end":21,"role":"preposition"},{"word":"9","start":22,"end":23,"role":"other"},{"word":"am","start":24,"end":26,"role":"noun"}]}]$grammar$::jsonb, $grammar${"definition":"**Giới từ chỉ thời gian** (*in, on, at*) được sử dụng để xác định thời điểm, ngày tháng, hoặc khoảng thời gian diễn ra một sự kiện. Thông thường, *in* dùng cho tháng, năm, mùa; *on* dùng cho ngày cụ thể; và *at* dùng cho giờ hoặc thời điểm chính xác.","usage":[{"icon":"📆","label":"Tháng, năm, thế kỷ","en":"I was born in June.","vi":"Tôi sinh ra vào tháng sáu."},{"icon":"🕰️","label":"Giờ, thời điểm cụ thể","en":"The meeting starts at 5 o'clock.","vi":"Cuộc họp bắt đầu vào lúc 5 giờ."},{"icon":"📅","label":"Ngày trong tuần, ngày lễ","en":"I have a meeting on Monday.","vi":"Tôi có một cuộc họp vào thứ hai."},{"icon":"🌞","label":"Mùa","en":"I love swimming in summer.","vi":"Tôi yêu thích bơi lội vào mùa hè."}],"formula":{"rows":[{"form":"In","time":"tháng, năm, thế kỷ, mùa","note":"Sử dụng với tháng, năm, thế kỷ, mùa"},{"form":"On","time":"ngày trong tuần, ngày lễ","note":"Sử dụng với ngày trong tuần, ngày lễ"},{"form":"At","time":"giờ, thời điểm cụ thể","note":"Sử dụng với giờ, thời điểm cụ thể"}],"note":"Lưu ý: Không sử dụng **in** với ngày trong tuần, không sử dụng **on** với giờ, và không sử dụng **at** với tháng hoặc năm."},"rules":[{"case":"Tháng","rule":"sử dụng **in**","example":"I was born in June."},{"case":"Ngày trong tuần","rule":"sử dụng **on**","example":"I have a meeting on Monday."},{"case":"Giờ","rule":"sử dụng **at**","example":"The meeting starts at 5 o'clock."}],"signals":["yesterday","today","tomorrow","next week","last year"],"examples":[{"en":"I have a meeting in May.","vi":"Tôi có một cuộc họp vào tháng năm.","note":"Sử dụng **in** với tháng.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"verb"},{"word":"a","start":7,"end":8,"role":"article"},{"word":"meeting","start":9,"end":16,"role":"noun"},{"word":"in","start":17,"end":19,"role":"preposition"},{"word":"May","start":20,"end":23,"role":"noun"}]},{"en":"The party is on Saturday.","vi":"Bữa tiệc vào thứ bảy.","note":"Sử dụng **on** với ngày trong tuần.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"party","start":4,"end":9,"role":"noun"},{"word":"is","start":10,"end":12,"role":"auxiliary"},{"word":"on","start":13,"end":15,"role":"preposition"},{"word":"Saturday","start":16,"end":24,"role":"noun"}]},{"en":"I'll meet you at 7 o'clock.","vi":"Tôi sẽ gặp bạn vào lúc 7 giờ.","note":"Sử dụng **at** với giờ.","annotations":[{"word":"I'll","start":0,"end":4,"role":"modal"},{"word":"meet","start":5,"end":9,"role":"verb"},{"word":"you","start":10,"end":13,"role":"pronoun"},{"word":"at","start":14,"end":16,"role":"preposition"},{"word":"7","start":17,"end":18,"role":"other"},{"word":"o'clock","start":19,"end":26,"role":"noun"}]},{"en":"She was born in 1990.","vi":"Cô ấy sinh ra vào năm 1990.","note":"Sử dụng **in** với năm.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"was","start":4,"end":7,"role":"auxiliary"},{"word":"born","start":8,"end":12,"role":"verb"},{"word":"in","start":13,"end":15,"role":"preposition"},{"word":"1990","start":16,"end":20,"role":"other"}]},{"en":"We're going to the beach in summer.","vi":"Chúng tôi sẽ đi đến bãi biển vào mùa hè.","note":"Sử dụng **in** với mùa.","annotations":[{"word":"We're","start":0,"end":5,"role":"pronoun"},{"word":"going","start":6,"end":11,"role":"auxiliary"},{"word":"to","start":12,"end":14,"role":"verb"},{"word":"the","start":15,"end":18,"role":"preposition"},{"word":"beach","start":19,"end":24,"role":"article"},{"word":"in","start":25,"end":27,"role":"noun"},{"word":"summer","start":28,"end":34,"role":"preposition"}]},{"en":"The store is open on Sundays.","vi":"Cửa hàng mở cửa vào chủ nhật.","note":"Sử dụng **on** với ngày trong tuần.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"store","start":4,"end":9,"role":"noun"},{"word":"is","start":10,"end":12,"role":"auxiliary"},{"word":"open","start":13,"end":17,"role":"adjective"},{"word":"on","start":18,"end":20,"role":"preposition"},{"word":"Sundays","start":21,"end":28,"role":"noun"}]},{"en":"The meeting starts at 9 am.","vi":"Cuộc họp bắt đầu vào lúc 9 giờ sáng.","note":"Sử dụng **at** với giờ.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"meeting","start":4,"end":11,"role":"noun"},{"word":"starts","start":12,"end":18,"role":"verb"},{"word":"at","start":19,"end":21,"role":"preposition"},{"word":"9","start":22,"end":23,"role":"other"},{"word":"am","start":24,"end":26,"role":"noun"}]}],"mistakes":[{"wrong":"I have a meeting on May.","right":"I have a meeting in May.","why":"Sử dụng **in** với tháng."},{"wrong":"The party is in Saturday.","right":"The party is on Saturday.","why":"Sử dụng **on** với ngày trong tuần."},{"wrong":"I'll meet you in 7 o'clock.","right":"I'll meet you at 7 o'clock.","why":"Sử dụng **at** với giờ."},{"wrong":"I was born at 2001.","right":"I was born in 2001.","why":"Dùng in với năm."},{"wrong":"We will meet in Friday.","right":"We will meet on Friday.","why":"Dùng on với ngày trong tuần."}],"tips":"**Mẹo nhớ:** Sử dụng **in** với tháng, năm, thế kỷ, mùa; sử dụng **on** với ngày trong tuần, ngày lễ; sử dụng **at** với giờ, thời điểm cụ thể.","comparison":"**In**, **on**, và **at** là ba giới từ chỉ thời gian khác nhau. Sử dụng **in** với thời gian dài, sử dụng **on** với thời gian ngắn, và sử dụng **at** với thời điểm cụ thể.","timeline":null}$grammar$::jsonb, $grammar$[{"type":"fill","q":"My father gave me a new laptop.  →  I ____ a new laptop by my father.","opts":[],"answer":"was given","fb":"Người lên đầu → be + V3, không thêm giới từ"},{"type":"fill","q":"She is good ____ Maths.  (A in · B at · C on · D for)","opts":[],"answer":"B at","fb":"good đi cố định với giới từ at · buổi 21"}]$grammar$::jsonb, 'ai-golden', 19
from public.grammar_topics t where t.slug = 'prepositions-time'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 20. past-simple
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('past-simple', 'Past Simple', 'Thì Quá khứ đơn', 'beginner', 20)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Quá khứ đơn', '**Thì Quá khứ đơn** (Past Simple) là thì dùng để diễn tả những hành động **đã xảy ra và kết thúc** trong quá khứ. Đây là một trong những thì cơ bản nhất trong tiếng Anh, thường được sử dụng để kể lại những sự kiện đã xảy ra trước đây.', $grammar$[{"en":"I ate breakfast at 7 a.m.","vi":"Tôi đã ăn bữa sáng vào lúc 7 giờ sáng.","note":"Khẳng định, hành động đã xảy ra và kết thúc.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"verb","word":"ate","start":2},{"end":15,"role":"noun","word":"breakfast","start":6},{"end":18,"role":"preposition","word":"at","start":16},{"end":20,"role":"other","word":"7","start":19},{"end":24,"role":"other","word":"a.m","start":21}]},{"en":"She didn't go to the party.","vi":"Cô ấy đã không đi dự tiệc.","note":"Phủ định, sử dụng didn't + V nguyên thể.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"auxiliary","word":"didn't","start":4},{"end":13,"role":"verb","word":"go","start":11},{"end":16,"role":"preposition","word":"to","start":14},{"end":20,"role":"article","word":"the","start":17},{"end":26,"role":"noun","word":"party","start":21}]},{"en":"Did you finish your homework?","vi":"Bạn đã hoàn thành bài tập về nhà chưa?","note":"Nghi vấn, sử dụng Did + S + V nguyên thể.","annotations":[{"end":3,"role":"auxiliary","word":"Did","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":14,"role":"verb","word":"finish","start":8},{"end":19,"role":"determiner","word":"your","start":15},{"end":28,"role":"noun","word":"homework","start":20}]},{"en":"They got married in 2015.","vi":"Họ đã kết hôn vào năm 2015.","note":"Hành động đã xảy ra và kết thúc trong quá khứ.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":8,"role":"verb","word":"got","start":5},{"end":16,"role":"verb","word":"married","start":9},{"end":19,"role":"preposition","word":"in","start":17},{"end":24,"role":"other","word":"2015","start":20}]},{"en":"He studied law at university.","vi":"Anh ấy đã học luật tại trường đại học.","note":"Trình độ học vấn, sử dụng quá khứ đơn.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":10,"role":"verb","word":"studied","start":3},{"end":14,"role":"noun","word":"law","start":11},{"end":17,"role":"preposition","word":"at","start":15},{"end":28,"role":"noun","word":"university","start":18}]},{"en":"We didn't travel to Japan last year.","vi":"Chúng tôi đã không đi du lịch đến Nhật Bản năm ngoái.","note":"Phủ định, sử dụng didn't + V nguyên thể.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":9,"role":"auxiliary","word":"didn't","start":3},{"end":16,"role":"verb","word":"travel","start":10},{"end":19,"role":"preposition","word":"to","start":17},{"end":25,"role":"noun","word":"Japan","start":20},{"end":30,"role":"determiner","word":"last","start":26},{"end":35,"role":"noun","word":"year","start":31}]},{"en":"What did you eat for lunch yesterday?","vi":"Bạn đã ăn gì cho bữa trưa vào ngày hôm qua?","note":"Câu hỏi Wh- + Did + S + V nguyên thể.","annotations":[{"end":4,"role":"other","word":"What","start":0},{"end":8,"role":"auxiliary","word":"did","start":5},{"end":12,"role":"pronoun","word":"you","start":9},{"end":16,"role":"verb","word":"eat","start":13},{"end":20,"role":"preposition","word":"for","start":17},{"end":26,"role":"noun","word":"lunch","start":21},{"end":36,"role":"noun","word":"yesterday","start":27}]},{"en":"She didn't like the movie.","vi":"Cô ấy đã không thích bộ phim.","note":"Phủ định, sử dụng didn't + V nguyên thể.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"auxiliary","word":"didn't","start":4},{"end":15,"role":"verb","word":"like","start":11},{"end":19,"role":"article","word":"the","start":16},{"end":25,"role":"noun","word":"movie","start":20}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** Sử dụng thì quá khứ đơn để diễn tả những hành động đã xảy ra và kết thúc trong quá khứ. Đa số động từ thêm -ed để tạo thành quá khứ đơn.","rules":[{"case":"Đa số động từ","rule":"thêm -ed","example":"walk → walked"},{"case":"Tận cùng -e","rule":"thêm -d","example":"love → loved"},{"case":"Tận cùng -y (chữ trước y là phụ âm)","rule":"thay y bằng -ied","example":"study → studied"},{"case":"Nguyên âm + y","rule":"thêm -ed","example":"play → played"}],"usage":[{"en":"I went to the store yesterday.","vi":"Hôm qua tôi đã đi đến cửa hàng.","icon":"🕐","label":"Hành động đã xảy ra và kết thúc tại thời điểm xác định trong quá khứ"},{"en":"She woke up, brushed her teeth, and left for work.","vi":"Cô ấy thức dậy, đánh răng rồi đi làm.","icon":"📖","label":"Chuỗi hành động nối tiếp nhau trong quá khứ (kể chuyện)"},{"en":"We played football every weekend when we were kids.","vi":"Hồi nhỏ, cuối tuần nào chúng tôi cũng chơi bóng đá.","icon":"🔁","label":"Thói quen hoặc trạng thái trong quá khứ (nay không còn)"},{"en":"He lived in Da Nang for five years before moving to Hanoi.","vi":"Anh ấy đã sống ở Đà Nẵng năm năm trước khi chuyển ra Hà Nội.","icon":"⏳","label":"Sự việc kéo dài một khoảng thời gian trong quá khứ, nay đã chấm dứt"},{"en":"The company opened its first office in 2010.","vi":"Công ty mở văn phòng đầu tiên vào năm 2010.","icon":"📅","label":"Sự kiện lịch sử, mốc thời gian cụ thể trong quá khứ"}],"formula":{"note":"Một số động từ bất quy tắc không thêm -ed. Ví dụ: go → went, take → took.","rows":[{"base":"S + V-ed (quá khứ)","form":"(+) Khẳng định","note":"Đa số động từ thêm -ed"},{"base":"S + did not + V (nguyên thể)","form":"(-) Phủ định","note":"Dùng did not + V nguyên thể"},{"base":"Did + S + V (nguyên thể)?","form":"(?) Nghi vấn","note":"Dùng Did + S + V nguyên thể"}]},"signals":["yesterday","last week","last month","last year","ago","in 2019","when I was a child"],"examples":[{"en":"I ate breakfast at 7 a.m.","vi":"Tôi đã ăn bữa sáng vào lúc 7 giờ sáng.","note":"Khẳng định, hành động đã xảy ra và kết thúc.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"verb","word":"ate","start":2},{"end":15,"role":"noun","word":"breakfast","start":6},{"end":18,"role":"preposition","word":"at","start":16},{"end":20,"role":"other","word":"7","start":19},{"end":24,"role":"other","word":"a.m","start":21}]},{"en":"She didn't go to the party.","vi":"Cô ấy đã không đi dự tiệc.","note":"Phủ định, sử dụng didn't + V nguyên thể.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"auxiliary","word":"didn't","start":4},{"end":13,"role":"verb","word":"go","start":11},{"end":16,"role":"preposition","word":"to","start":14},{"end":20,"role":"article","word":"the","start":17},{"end":26,"role":"noun","word":"party","start":21}]},{"en":"Did you finish your homework?","vi":"Bạn đã hoàn thành bài tập về nhà chưa?","note":"Nghi vấn, sử dụng Did + S + V nguyên thể.","annotations":[{"end":3,"role":"auxiliary","word":"Did","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":14,"role":"verb","word":"finish","start":8},{"end":19,"role":"determiner","word":"your","start":15},{"end":28,"role":"noun","word":"homework","start":20}]},{"en":"They got married in 2015.","vi":"Họ đã kết hôn vào năm 2015.","note":"Hành động đã xảy ra và kết thúc trong quá khứ.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":8,"role":"verb","word":"got","start":5},{"end":16,"role":"verb","word":"married","start":9},{"end":19,"role":"preposition","word":"in","start":17},{"end":24,"role":"other","word":"2015","start":20}]},{"en":"He studied law at university.","vi":"Anh ấy đã học luật tại trường đại học.","note":"Trình độ học vấn, sử dụng quá khứ đơn.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":10,"role":"verb","word":"studied","start":3},{"end":14,"role":"noun","word":"law","start":11},{"end":17,"role":"preposition","word":"at","start":15},{"end":28,"role":"noun","word":"university","start":18}]},{"en":"We didn't travel to Japan last year.","vi":"Chúng tôi đã không đi du lịch đến Nhật Bản năm ngoái.","note":"Phủ định, sử dụng didn't + V nguyên thể.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":9,"role":"auxiliary","word":"didn't","start":3},{"end":16,"role":"verb","word":"travel","start":10},{"end":19,"role":"preposition","word":"to","start":17},{"end":25,"role":"noun","word":"Japan","start":20},{"end":30,"role":"determiner","word":"last","start":26},{"end":35,"role":"noun","word":"year","start":31}]},{"en":"What did you eat for lunch yesterday?","vi":"Bạn đã ăn gì cho bữa trưa vào ngày hôm qua?","note":"Câu hỏi Wh- + Did + S + V nguyên thể.","annotations":[{"end":4,"role":"other","word":"What","start":0},{"end":8,"role":"auxiliary","word":"did","start":5},{"end":12,"role":"pronoun","word":"you","start":9},{"end":16,"role":"verb","word":"eat","start":13},{"end":20,"role":"preposition","word":"for","start":17},{"end":26,"role":"noun","word":"lunch","start":21},{"end":36,"role":"noun","word":"yesterday","start":27}]},{"en":"She didn't like the movie.","vi":"Cô ấy đã không thích bộ phim.","note":"Phủ định, sử dụng didn't + V nguyên thể.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"auxiliary","word":"didn't","start":4},{"end":15,"role":"verb","word":"like","start":11},{"end":19,"role":"article","word":"the","start":16},{"end":25,"role":"noun","word":"movie","start":20}]}],"mistakes":[{"wrong":"I go to the store yesterday.","right":"I went to the store yesterday.","why":"Có mốc thời gian quá khứ (yesterday) → động từ phải chia quá khứ: go → went."},{"wrong":"She don't like coffee.","right":"She didn't like the coffee.","why":"Phủ định quá khứ đơn dùng didn't + động từ nguyên thể, không dùng don't (thì hiện tại)."},{"wrong":"Did she went to the party?","right":"Did she go to the party?","why":"Sau trợ động từ did, động từ chính về NGUYÊN THỂ (go), không chia quá khứ (went)."},{"wrong":"I eat breakfast at 7 a.m. yesterday.","right":"I ate breakfast at 7 a.m. yesterday.","why":"Hành động đã xảy ra và kết thúc trong quá khứ (yesterday) → dùng quá khứ đơn: eat → ate."},{"wrong":"She buyed a new dress.","right":"She bought a new dress.","why":"Buy là động từ bất quy tắc; quá khứ là bought, không thêm -ed."},{"wrong":"He teached English.","right":"He taught English.","why":"Teach là động từ bất quy tắc; quá khứ là taught, không thêm -ed."}],"timeline":{"points":[{"note":"Quá khứ","label":"Hôm qua"},{"note":"Hiện tại","label":"Ngày hôm nay"},{"note":"Tương lai","label":"Ngày mai"}],"caption":"Ví dụ \"I went to the store yesterday\" — hành động đã xảy ra và kết thúc vào ngày hôm qua."},"comparison":"**Quá khứ đơn vs Quá khứ tiếp diễn:** Đơn = hành động ĐÃ hoàn tất (*We drove home* — về tới nơi). Tiếp diễn = đang GIỮA CHỪNG hành động (*We were driving home* — đang trên đường).","definition":"**Thì Quá khứ đơn** (Past Simple) là thì dùng để diễn tả những hành động **đã xảy ra và kết thúc** trong quá khứ. Đây là một trong những thì cơ bản nhất trong tiếng Anh, thường được sử dụng để kể lại những sự kiện đã xảy ra trước đây."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"The biscuit factory ____ (close) last year.","opts":[],"answer":"closed","fb":"last year = mốc quá khứ"},{"type":"fill","q":"Bill ____ (have) breakfast when I ____ (stop) at his house.","opts":[],"answer":"was having / stopped","fb":"ăn sáng = việc dài · stop = việc ngắn xen vào"},{"type":"fill","q":"I last ____ (go) to Spain in 1990.","opts":[],"answer":"went","fb":"in 1990 = mốc quá khứ"},{"type":"fill","q":"She ____ (not / know) my address then.","opts":[],"answer":"didn't know","fb":"know = trong đầu → không -ing"},{"type":"fill","q":"____ you ____ (spend) a lot of money last month?","opts":[],"answer":"Did … spend","fb":"câu hỏi QK → Did + V trơ"},{"type":"fill","q":"When she ____ (be) young, she ____ (be) very beautiful.","opts":[],"answer":"was / was","fb":"trạng thái trong quá khứ → QK đơn"},{"type":"fill","q":"They ____ (visit) the zoo at ten o'clock yesterday.","opts":[],"answer":"were visiting","fb":"at ten o'clock yesterday → đang giữa việc"},{"type":"fill","q":"When the teacher ____ (come) in, the students ____ (stand) up.","opts":[],"answer":"came / stood","fb":"2 việc ngắn nối nhau → cả 2 đơn"},{"type":"fill","q":"Bob ____ (buy) a new laptop last Sunday.","opts":[],"answer":"bought","fb":"last Sunday = mốc chết → quá khứ đơn"},{"type":"fill","q":"My family ____ (move) to Ha Noi three years ago.","opts":[],"answer":"moved","fb":"… ago = mốc chết → quá khứ đơn"},{"type":"fill","q":"When I ____ (open) the door yesterday, the cat ____ (sleep) on the sofa.","opts":[],"answer":"opened / was sleeping","fb":"mở cửa = việc ngắn · mèo đang ngủ sẵn"},{"type":"fill","q":"As soon as the rain ____ (stop) yesterday afternoon, the children ____ (run) outside.","opts":[],"answer":"stopped / ran","fb":"hai việc ngắn nối đuôi → cả hai quá khứ đơn"},{"type":"fill","q":"While Nam ____ (walk) along the beach last week, he ____ (find) a wallet.","opts":[],"answer":"was walking / found","fb":"đi dạo = việc dài · nhặt được ví = việc ngắn"},{"type":"fill","q":"After we ____ (finish) the exam last June, we ____ (have) a big party.","opts":[],"answer":"finished / had","fb":"After + hai việc nối đuôi trong quá khứ → cả hai đơn"},{"type":"fill","q":"Before I ____ (go) to bed last night, I ____ (turn) off all the lights.","opts":[],"answer":"went / turned","fb":"Before + hai việc nối đuôi trong quá khứ → cả hai đơn"},{"type":"fill","q":"What ____ you ____ (do) when the earthquake ____ (happen) last month?","opts":[],"answer":"were … doing / happened","fb":"động đất = việc ngắn cắt ngang việc em đang làm dở"},{"type":"fill","q":"Gold ____ (discover) in California in the 19th century.","opts":[],"answer":"was discovered","fb":"in the 19th century = quá khứ đơn → was + V3"},{"type":"fill","q":"Lots of houses ____ (destroy) by the earthquake last week.","opts":[],"answer":"were destroyed","fb":"houses số nhiều + last week → were + V3"},{"type":"fill","q":"A surprise party ____ (organize) by the children last night.","opts":[],"answer":"was organized","fb":"last night = quá khứ đơn · party số ít → was + V3"},{"type":"fill","q":"Somebody stole my phone yesterday.  →  My phone ____ yesterday.","opts":[],"answer":"was stolen","fb":"Somebody → cắt by · quá khứ đơn → was + V3"},{"type":"fill","q":"My cold is ____ (good) today than it was yesterday.","opts":[],"answer":"better","fb":"good là bất quy tắc → better"},{"type":"fill","q":"My best friend, ____ moved to Da Nang, called me yesterday.","opts":[],"answer":"who","fb":"có phẩy + người → who, cấm that"},{"type":"fill","q":"Nam wishes he ____ (not / break) his mother's vase yesterday.","opts":[],"answer":"hadn't broken","fb":"yesterday = chuyện đã qua → hadn't + V3"},{"type":"fill","q":"My best friend lives in Hue. I wish he ____ (live) closer to me.","opts":[],"answer":"lived","fb":"Chuyện bây giờ, không có mốc quá khứ → V2"},{"type":"fill","q":"Đổi sang gián tiếp: “Did you go with your mother yesterday?” he asked me.","opts":[],"answer":"He asked me if I had gone with my mother the day before.","fb":"hỏi yes/no nên nối bằng if · quá khứ đơn lùi thành had gone"},{"type":"fill","q":"Everyone in the office ____ leave the building for a fire drill yesterday. (must / had to)","opts":[],"answer":"had to","fb":"chuyện quá khứ nên dùng had to"},{"type":"fill","q":"By the time we arrived, the film ____ already started.  (A has · B had · C was · D did)","opts":[],"answer":"B had","fb":"Xong trước một mốc quá khứ → had + V3 · buổi 6"}]$grammar$::jsonb, 'ai-golden', 20
from public.grammar_topics t where t.slug = 'past-simple'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 21. past-continuous
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('past-continuous', 'Past Continuous', 'Thì Quá khứ tiếp diễn', 'beginner', 21)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Quá khứ tiếp diễn', '**Thì Quá khứ tiếp diễn** (Past Continuous) diễn tả hành động **đang diễn ra** tại một thời điểm cụ thể trong quá khứ. Nó thường được sử dụng để mô tả một hành động **đang xảy ra** khi một hành động khác **xảy ra**.', $grammar$[{"en":"They were playing football when it started raining.","vi":"Họ đang chơi bóng đá khi trời bắt đầu mưa.","note":"Mô tả hai hành động cùng xảy ra.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"were","start":5,"end":9,"role":"auxiliary"},{"word":"playing","start":10,"end":17,"role":"verb"},{"word":"football","start":18,"end":26,"role":"noun"},{"word":"when","start":27,"end":31,"role":"conjunction"},{"word":"it","start":32,"end":34,"role":"pronoun"},{"word":"started","start":35,"end":42,"role":"verb"},{"word":"raining","start":43,"end":50,"role":"verb"}]},{"en":"I was studying English at 8 pm last night.","vi":"Tôi đang học tiếng Anh vào lúc 8 giờ tối đêm qua.","note":"Mô tả hành động đang diễn ra.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"was","start":2,"end":5,"role":"auxiliary"},{"word":"studying","start":6,"end":14,"role":"verb"},{"word":"English","start":15,"end":22,"role":"noun"},{"word":"at","start":23,"end":25,"role":"preposition"},{"word":"8","start":26,"end":27,"role":"other"},{"word":"pm","start":28,"end":30,"role":"noun"},{"word":"last","start":31,"end":35,"role":"determiner"},{"word":"night","start":36,"end":41,"role":"noun"}]},{"en":"She was not watching TV at that time.","vi":"Cô ấy không xem TV vào thời điểm đó.","note":"Phủ định.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"was","start":4,"end":7,"role":"auxiliary"},{"word":"not","start":8,"end":11,"role":"adverb"},{"word":"watching","start":12,"end":20,"role":"verb"},{"word":"TV","start":21,"end":23,"role":"noun"},{"word":"at","start":24,"end":26,"role":"preposition"},{"word":"that","start":27,"end":31,"role":"determiner"},{"word":"time","start":32,"end":36,"role":"noun"}]},{"en":"Were you sleeping when I called?","vi":"Bạn có đang ngủ khi tôi gọi không?","note":"Nghi vấn.","annotations":[{"word":"Were","start":0,"end":4,"role":"auxiliary"},{"word":"you","start":5,"end":8,"role":"pronoun"},{"word":"sleeping","start":9,"end":17,"role":"verb"},{"word":"when","start":18,"end":22,"role":"conjunction"},{"word":"I","start":23,"end":24,"role":"pronoun"},{"word":"called","start":25,"end":31,"role":"verb"}]},{"en":"They were having a party when the police arrived.","vi":"Họ đang tổ chức một bữa tiệc khi cảnh sát đến.","note":"Mô tả hành động đang diễn ra.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"were","start":5,"end":9,"role":"auxiliary"},{"word":"having","start":10,"end":16,"role":"verb"},{"word":"a","start":17,"end":18,"role":"article"},{"word":"party","start":19,"end":24,"role":"noun"},{"word":"when","start":25,"end":29,"role":"conjunction"},{"word":"the","start":30,"end":33,"role":"article"},{"word":"police","start":34,"end":40,"role":"noun"},{"word":"arrived","start":41,"end":48,"role":"verb"}]},{"en":"The baby was crying when the mother came home.","vi":"Em bé đang khóc khi mẹ về nhà.","note":"Mô tả hành động gây ra một sự kiện.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"baby","start":4,"end":8,"role":"noun"},{"word":"was","start":9,"end":12,"role":"auxiliary"},{"word":"crying","start":13,"end":19,"role":"verb"},{"word":"when","start":20,"end":24,"role":"conjunction"},{"word":"the","start":25,"end":28,"role":"article"},{"word":"mother","start":29,"end":35,"role":"noun"},{"word":"came","start":36,"end":40,"role":"verb"},{"word":"home","start":41,"end":45,"role":"other"}]}]$grammar$::jsonb, $grammar${"definition":"**Thì Quá khứ tiếp diễn** (Past Continuous) diễn tả hành động **đang diễn ra** tại một thời điểm cụ thể trong quá khứ. Nó thường được sử dụng để mô tả một hành động **đang xảy ra** khi một hành động khác **xảy ra**.","usage":[{"icon":"🕐","label":"Hành động đang diễn ra tại một thời điểm xác định trong quá khứ","en":"I was studying English at 8 p.m. last night.","vi":"Tối qua lúc 8 giờ tôi đang học tiếng Anh."},{"icon":"⚡","label":"Hành động đang diễn ra thì bị một hành động khác xen vào (quá khứ đơn)","en":"They were talking on the phone when I arrived.","vi":"Họ đang nói chuyện điện thoại thì tôi đến."},{"icon":"🔀","label":"Hai hành động diễn ra song song trong quá khứ (thường với while)","en":"She was cooking dinner while I was watching TV.","vi":"Cô ấy đang nấu bữa tối trong khi tôi đang xem TV."},{"icon":"🎬","label":"Miêu tả bối cảnh, khung cảnh trong câu chuyện quá khứ","en":"The sun was shining and birds were singing when we set off.","vi":"Mặt trời đang chiếu sáng và chim đang hót khi chúng tôi khởi hành."}],"formula":{"rows":[{"form":"(+) Khẳng định","base":"S + was/were + V-ing"},{"form":"(-) Phủ định","base":"S + was/were + not + V-ing"},{"form":"(?) Nghi vấn","base":"Was/Were + S + V-ing?"}],"note":"Dạng **was** được sử dụng cho **I**, **he**, **she**, **it**, trong khi **were** được sử dụng cho **you**, **we**, **they**."},"rules":[{"case":"Động từ thường","rule":"thêm -ing","example":"walk → walking"},{"case":"Động từ tận cùng -e","rule":"bỏ -e và thêm -ing","example":"love → loving"},{"case":"Động từ có một âm tiết và tận cùng -y","rule":"thêm -ing","example":"try → trying"},{"case":"Động từ có hai âm tiết và tận cùng -y","rule":"thêm -ing hoặc thay -y bằng -i và thêm -ng","example":"carry → carrying hoặc study → studying"}],"signals":["while","when","as","at the same time","meanwhile","at that moment"],"examples":[{"en":"They were playing football when it started raining.","vi":"Họ đang chơi bóng đá khi trời bắt đầu mưa.","note":"Mô tả hai hành động cùng xảy ra.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"were","start":5,"end":9,"role":"auxiliary"},{"word":"playing","start":10,"end":17,"role":"verb"},{"word":"football","start":18,"end":26,"role":"noun"},{"word":"when","start":27,"end":31,"role":"conjunction"},{"word":"it","start":32,"end":34,"role":"pronoun"},{"word":"started","start":35,"end":42,"role":"verb"},{"word":"raining","start":43,"end":50,"role":"verb"}]},{"en":"I was studying English at 8 pm last night.","vi":"Tôi đang học tiếng Anh vào lúc 8 giờ tối đêm qua.","note":"Mô tả hành động đang diễn ra.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"was","start":2,"end":5,"role":"auxiliary"},{"word":"studying","start":6,"end":14,"role":"verb"},{"word":"English","start":15,"end":22,"role":"noun"},{"word":"at","start":23,"end":25,"role":"preposition"},{"word":"8","start":26,"end":27,"role":"other"},{"word":"pm","start":28,"end":30,"role":"noun"},{"word":"last","start":31,"end":35,"role":"determiner"},{"word":"night","start":36,"end":41,"role":"noun"}]},{"en":"She was not watching TV at that time.","vi":"Cô ấy không xem TV vào thời điểm đó.","note":"Phủ định.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"was","start":4,"end":7,"role":"auxiliary"},{"word":"not","start":8,"end":11,"role":"adverb"},{"word":"watching","start":12,"end":20,"role":"verb"},{"word":"TV","start":21,"end":23,"role":"noun"},{"word":"at","start":24,"end":26,"role":"preposition"},{"word":"that","start":27,"end":31,"role":"determiner"},{"word":"time","start":32,"end":36,"role":"noun"}]},{"en":"Were you sleeping when I called?","vi":"Bạn có đang ngủ khi tôi gọi không?","note":"Nghi vấn.","annotations":[{"word":"Were","start":0,"end":4,"role":"auxiliary"},{"word":"you","start":5,"end":8,"role":"pronoun"},{"word":"sleeping","start":9,"end":17,"role":"verb"},{"word":"when","start":18,"end":22,"role":"conjunction"},{"word":"I","start":23,"end":24,"role":"pronoun"},{"word":"called","start":25,"end":31,"role":"verb"}]},{"en":"They were having a party when the police arrived.","vi":"Họ đang tổ chức một bữa tiệc khi cảnh sát đến.","note":"Mô tả hành động đang diễn ra.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"were","start":5,"end":9,"role":"auxiliary"},{"word":"having","start":10,"end":16,"role":"verb"},{"word":"a","start":17,"end":18,"role":"article"},{"word":"party","start":19,"end":24,"role":"noun"},{"word":"when","start":25,"end":29,"role":"conjunction"},{"word":"the","start":30,"end":33,"role":"article"},{"word":"police","start":34,"end":40,"role":"noun"},{"word":"arrived","start":41,"end":48,"role":"verb"}]},{"en":"The baby was crying when the mother came home.","vi":"Em bé đang khóc khi mẹ về nhà.","note":"Mô tả hành động gây ra một sự kiện.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"baby","start":4,"end":8,"role":"noun"},{"word":"was","start":9,"end":12,"role":"auxiliary"},{"word":"crying","start":13,"end":19,"role":"verb"},{"word":"when","start":20,"end":24,"role":"conjunction"},{"word":"the","start":25,"end":28,"role":"article"},{"word":"mother","start":29,"end":35,"role":"noun"},{"word":"came","start":36,"end":40,"role":"verb"},{"word":"home","start":41,"end":45,"role":"other"}]}],"mistakes":[{"wrong":"I was go to school.","right":"I was going to school.","why":"Quên thêm -ing vào động từ."},{"wrong":"They was playing football.","right":"They were playing football.","why":"Sử dụng sai **was** và **were**."},{"wrong":"She were not watching TV.","right":"She was not watching TV.","why":"Sử dụng sai **was** và **were** trong phủ định."},{"wrong":"While I watched TV, the phone rang.","right":"While I was watching TV, the phone rang.","why":"Hành động NỀN đang kéo dài dùng quá khứ tiếp diễn; hành động xen vào dùng quá khứ đơn."},{"wrong":"I was knowing the answer.","right":"I knew the answer.","why":"Động từ trạng thái (know, like, want) không dùng dạng tiếp diễn."}],"tips":"**Mẹo nhớ:** Để tạo dạng **Past Continuous**, thêm **-ing** vào động từ thường. Với **I**, **he**, **she**, **it**, sử dụng **was**, và với **you**, **we**, **they**, sử dụng **were**.","comparison":"**Quá khứ tiếp diễn vs Quá khứ đơn (hành động cắt ngang):** Tiếp diễn = bối cảnh dài đang diễn ra (*We were having dinner* — đang ăn tối). Đơn = hành động ngắn XEN VÀO cắt ngang (*Matt phoned while we were having dinner* — chuông gọi xen vào).","timeline":{"caption":"Ví dụ \"I was studying English at 8 pm last night\" — hành động **đang diễn ra** tại một thời điểm cụ thể trong quá khứ.","points":[{"label":"7:30 pm","note":"bắt đầu học"},{"label":"8:00 pm","note":"đang học"},{"label":"9:00 pm","note":"kết thúc học"}]}}$grammar$::jsonb, $grammar$[{"type":"fill","q":"At 8 p.m. last night my father ____ (feed) the pigeons.","opts":[],"answer":"was feeding","fb":"at + giờ + quá khứ → tiếp diễn"},{"type":"fill","q":"While I ____ (do) my homework, my sister ____ (listen) to music.","opts":[],"answer":"was doing / was listening","fb":"2 việc dài song song → cả 2 tiếp diễn"},{"type":"fill","q":"At 7 p.m. yesterday my father ____ (watch) the news when the phone ____ (ring).","opts":[],"answer":"was watching / rang","fb":"at 7 p.m. yesterday = đang giữa chừng · chuông reo = việc ngắn"},{"type":"fill","q":"At 9 p.m. yesterday I ____ (help) my mother in the kitchen.","opts":[],"answer":"was helping","fb":"at + giờ + quá khứ → quá khứ tiếp diễn"}]$grammar$::jsonb, 'ai-golden', 21
from public.grammar_topics t where t.slug = 'past-continuous'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 22. be-going-to
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('be-going-to', 'Future: be going to', 'Tương lai gần (be going to)', 'beginner', 22)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Tương lai gần (be going to)', '**Tương lai gần** (Future: be going to) là một trong những cách nói về tương lai trong tiếng Anh. Nó được sử dụng để nói về kế hoạch, dự định, hoặc những sự kiện sắp xảy ra trong tương lai gần. **Be going to** thường được dùng khi chúng ta đã có kế hoạch hoặc dự định từ trước, hoặc khi có một số dấu hiệu cho thấy một sự kiện sẽ xảy ra.', $grammar$[{"en":"I'm going to learn how to play the guitar.","vi":"Tôi sẽ học cách chơi ghi-ta.","note":"Dự định học một kỹ năng mới.","annotations":[{"word":"I'm","start":0,"end":3,"role":"auxiliary"},{"word":"going","start":4,"end":9,"role":"verb"},{"word":"to","start":10,"end":12,"role":"other"},{"word":"learn","start":13,"end":18,"role":"verb"},{"word":"how","start":19,"end":22,"role":"adverb"},{"word":"to","start":23,"end":25,"role":"other"},{"word":"play","start":26,"end":30,"role":"verb"},{"word":"the","start":31,"end":34,"role":"article"},{"word":"guitar","start":35,"end":41,"role":"noun"}]},{"en":"They are not going to come to the party.","vi":"Họ sẽ không đến dự tiệc.","note":"Phủ định dự định.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"are","start":5,"end":8,"role":"auxiliary"},{"word":"not","start":9,"end":12,"role":"adverb"},{"word":"going","start":13,"end":18,"role":"verb"},{"word":"to","start":19,"end":21,"role":"other"},{"word":"come","start":22,"end":26,"role":"verb"},{"word":"to","start":27,"end":29,"role":"preposition"},{"word":"the","start":30,"end":33,"role":"article"},{"word":"party","start":34,"end":39,"role":"noun"}]},{"en":"Is she going to finish the project on time?","vi":"Cô ấy có hoàn thành dự án đúng hạn không?","note":"Nghi vấn về khả năng hoàn thành dự án.","annotations":[{"word":"Is","start":0,"end":2,"role":"auxiliary"},{"word":"she","start":3,"end":6,"role":"pronoun"},{"word":"going","start":7,"end":12,"role":"verb"},{"word":"to","start":13,"end":15,"role":"other"},{"word":"finish","start":16,"end":22,"role":"verb"},{"word":"the","start":23,"end":26,"role":"article"},{"word":"project","start":27,"end":34,"role":"noun"},{"word":"on","start":35,"end":37,"role":"preposition"},{"word":"time","start":38,"end":42,"role":"noun"}]},{"en":"It's going to be a beautiful day tomorrow.","vi":"Ngày mai sẽ là một ngày tuyệt đẹp.","note":"Dự đoán về thời tiết.","annotations":[{"word":"It's","start":0,"end":4,"role":"auxiliary"},{"word":"going","start":5,"end":10,"role":"verb"},{"word":"to","start":11,"end":13,"role":"other"},{"word":"be","start":14,"end":16,"role":"auxiliary"},{"word":"a","start":17,"end":18,"role":"article"},{"word":"beautiful","start":19,"end":28,"role":"adjective"},{"word":"day","start":29,"end":32,"role":"noun"},{"word":"tomorrow","start":33,"end":41,"role":"adverb"}]},{"en":"We are going to have a meeting at 2 PM.","vi":"Chúng tôi sẽ có một cuộc họp vào 2 giờ chiều.","note":"Kế hoạch họp.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"are","start":3,"end":6,"role":"auxiliary"},{"word":"going","start":7,"end":12,"role":"verb"},{"word":"to","start":13,"end":15,"role":"other"},{"word":"have","start":16,"end":20,"role":"verb"},{"word":"a","start":21,"end":22,"role":"article"},{"word":"meeting","start":23,"end":30,"role":"noun"},{"word":"at","start":31,"end":33,"role":"preposition"},{"word":"2","start":34,"end":35,"role":"other"},{"word":"PM","start":36,"end":38,"role":"other"}]},{"en":"He's going to travel around the world next year.","vi":"Anh ấy sẽ đi du lịch quanh thế giới vào năm tới.","note":"Dự định du lịch.","annotations":[{"word":"He's","start":0,"end":4,"role":"pronoun"},{"word":"going","start":5,"end":10,"role":"auxiliary"},{"word":"to","start":11,"end":13,"role":"verb"},{"word":"travel","start":14,"end":20,"role":"other"},{"word":"around","start":21,"end":27,"role":"verb"},{"word":"the","start":28,"end":31,"role":"preposition"},{"word":"world","start":32,"end":37,"role":"article"},{"word":"next","start":38,"end":42,"role":"noun"},{"word":"year","start":43,"end":47,"role":"adverb"}]},{"en":"They are not going to sell their house.","vi":"Họ sẽ không bán nhà của họ.","note":"Phủ định dự định bán nhà.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"are","start":5,"end":8,"role":"auxiliary"},{"word":"not","start":9,"end":12,"role":"adverb"},{"word":"going","start":13,"end":18,"role":"verb"},{"word":"to","start":19,"end":21,"role":"other"},{"word":"sell","start":22,"end":26,"role":"verb"},{"word":"their","start":27,"end":32,"role":"determiner"},{"word":"house","start":33,"end":38,"role":"noun"}]},{"en":"Are you going to attend the conference?","vi":"Bạn có dự định tham dự hội nghị không?","note":"Nghi vấn về dự định tham dự.","annotations":[{"word":"Are","start":0,"end":3,"role":"auxiliary"},{"word":"you","start":4,"end":7,"role":"pronoun"},{"word":"going","start":8,"end":13,"role":"verb"},{"word":"to","start":14,"end":16,"role":"other"},{"word":"attend","start":17,"end":23,"role":"verb"},{"word":"the","start":24,"end":27,"role":"article"},{"word":"conference","start":28,"end":38,"role":"noun"}]}]$grammar$::jsonb, $grammar${"definition":"**Tương lai gần** (Future: be going to) là một trong những cách nói về tương lai trong tiếng Anh. Nó được sử dụng để nói về kế hoạch, dự định, hoặc những sự kiện sắp xảy ra trong tương lai gần. **Be going to** thường được dùng khi chúng ta đã có kế hoạch hoặc dự định từ trước, hoặc khi có một số dấu hiệu cho thấy một sự kiện sẽ xảy ra.","usage":[{"icon":"📅","label":"Kế hoạch, dự định","en":"I'm going to visit my friend next week.","vi":"Tôi sẽ đến thăm bạn tôi vào tuần sau."},{"icon":"🚨","label":"Dấu hiệu cho thấy sự kiện sẽ xảy ra","en":"It's going to rain, so take an umbrella.","vi":"Sắp có mưa, vậy hãy mang theo ô."},{"icon":"📝","label":"Dự định làm việc gì đó","en":"She's going to apply for a job.","vi":"Cô ấy sẽ nộp đơn xin việc."},{"icon":"🚫","label":"Cảnh báo về một sự kiện không mong muốn","en":"Be careful, the road is going to be closed.","vi":"Cẩn thận, con đường sẽ bị đóng."}],"formula":{"rows":[{"form":"(+) Khẳng định","base":"S + am/is/are + going to + V"},{"form":"(−) Phủ định","base":"S + am/is/are + not + going to + V"},{"form":"(?) Nghi vấn","base":"Am/Is/Are + S + going to + V?"}],"note":"Lưu ý sử dụng **am/is/are** phù hợp với chủ ngữ."},"rules":[{"case":"Sử dụng 'am' với I","rule":"I am going to","example":"I am going to eat dinner."},{"case":"Sử dụng 'is' với He/She/It","rule":"He/She/It is going to","example":"He is going to study tonight."},{"case":"Sử dụng 'are' với We/You/They","rule":"We/You/They are going to","example":"We are going to the movies tonight."}],"signals":["soon","next week","tomorrow","in a few minutes","later"],"examples":[{"en":"I'm going to learn how to play the guitar.","vi":"Tôi sẽ học cách chơi ghi-ta.","note":"Dự định học một kỹ năng mới.","annotations":[{"word":"I'm","start":0,"end":3,"role":"auxiliary"},{"word":"going","start":4,"end":9,"role":"verb"},{"word":"to","start":10,"end":12,"role":"other"},{"word":"learn","start":13,"end":18,"role":"verb"},{"word":"how","start":19,"end":22,"role":"adverb"},{"word":"to","start":23,"end":25,"role":"other"},{"word":"play","start":26,"end":30,"role":"verb"},{"word":"the","start":31,"end":34,"role":"article"},{"word":"guitar","start":35,"end":41,"role":"noun"}]},{"en":"They are not going to come to the party.","vi":"Họ sẽ không đến dự tiệc.","note":"Phủ định dự định.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"are","start":5,"end":8,"role":"auxiliary"},{"word":"not","start":9,"end":12,"role":"adverb"},{"word":"going","start":13,"end":18,"role":"verb"},{"word":"to","start":19,"end":21,"role":"other"},{"word":"come","start":22,"end":26,"role":"verb"},{"word":"to","start":27,"end":29,"role":"preposition"},{"word":"the","start":30,"end":33,"role":"article"},{"word":"party","start":34,"end":39,"role":"noun"}]},{"en":"Is she going to finish the project on time?","vi":"Cô ấy có hoàn thành dự án đúng hạn không?","note":"Nghi vấn về khả năng hoàn thành dự án.","annotations":[{"word":"Is","start":0,"end":2,"role":"auxiliary"},{"word":"she","start":3,"end":6,"role":"pronoun"},{"word":"going","start":7,"end":12,"role":"verb"},{"word":"to","start":13,"end":15,"role":"other"},{"word":"finish","start":16,"end":22,"role":"verb"},{"word":"the","start":23,"end":26,"role":"article"},{"word":"project","start":27,"end":34,"role":"noun"},{"word":"on","start":35,"end":37,"role":"preposition"},{"word":"time","start":38,"end":42,"role":"noun"}]},{"en":"It's going to be a beautiful day tomorrow.","vi":"Ngày mai sẽ là một ngày tuyệt đẹp.","note":"Dự đoán về thời tiết.","annotations":[{"word":"It's","start":0,"end":4,"role":"auxiliary"},{"word":"going","start":5,"end":10,"role":"verb"},{"word":"to","start":11,"end":13,"role":"other"},{"word":"be","start":14,"end":16,"role":"auxiliary"},{"word":"a","start":17,"end":18,"role":"article"},{"word":"beautiful","start":19,"end":28,"role":"adjective"},{"word":"day","start":29,"end":32,"role":"noun"},{"word":"tomorrow","start":33,"end":41,"role":"adverb"}]},{"en":"We are going to have a meeting at 2 PM.","vi":"Chúng tôi sẽ có một cuộc họp vào 2 giờ chiều.","note":"Kế hoạch họp.","annotations":[{"word":"We","start":0,"end":2,"role":"pronoun"},{"word":"are","start":3,"end":6,"role":"auxiliary"},{"word":"going","start":7,"end":12,"role":"verb"},{"word":"to","start":13,"end":15,"role":"other"},{"word":"have","start":16,"end":20,"role":"verb"},{"word":"a","start":21,"end":22,"role":"article"},{"word":"meeting","start":23,"end":30,"role":"noun"},{"word":"at","start":31,"end":33,"role":"preposition"},{"word":"2","start":34,"end":35,"role":"other"},{"word":"PM","start":36,"end":38,"role":"other"}]},{"en":"He's going to travel around the world next year.","vi":"Anh ấy sẽ đi du lịch quanh thế giới vào năm tới.","note":"Dự định du lịch.","annotations":[{"word":"He's","start":0,"end":4,"role":"pronoun"},{"word":"going","start":5,"end":10,"role":"auxiliary"},{"word":"to","start":11,"end":13,"role":"verb"},{"word":"travel","start":14,"end":20,"role":"other"},{"word":"around","start":21,"end":27,"role":"verb"},{"word":"the","start":28,"end":31,"role":"preposition"},{"word":"world","start":32,"end":37,"role":"article"},{"word":"next","start":38,"end":42,"role":"noun"},{"word":"year","start":43,"end":47,"role":"adverb"}]},{"en":"They are not going to sell their house.","vi":"Họ sẽ không bán nhà của họ.","note":"Phủ định dự định bán nhà.","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"are","start":5,"end":8,"role":"auxiliary"},{"word":"not","start":9,"end":12,"role":"adverb"},{"word":"going","start":13,"end":18,"role":"verb"},{"word":"to","start":19,"end":21,"role":"other"},{"word":"sell","start":22,"end":26,"role":"verb"},{"word":"their","start":27,"end":32,"role":"determiner"},{"word":"house","start":33,"end":38,"role":"noun"}]},{"en":"Are you going to attend the conference?","vi":"Bạn có dự định tham dự hội nghị không?","note":"Nghi vấn về dự định tham dự.","annotations":[{"word":"Are","start":0,"end":3,"role":"auxiliary"},{"word":"you","start":4,"end":7,"role":"pronoun"},{"word":"going","start":8,"end":13,"role":"verb"},{"word":"to","start":14,"end":16,"role":"other"},{"word":"attend","start":17,"end":23,"role":"verb"},{"word":"the","start":24,"end":27,"role":"article"},{"word":"conference","start":28,"end":38,"role":"noun"}]}],"mistakes":[{"wrong":"I going to the store.","right":"I'm going to the store.","why":"Quên sử dụng 'am' (I'm) trước 'going to'."},{"wrong":"She go to the party.","right":"She's going to the party.","why":"Quên sử dụng 'is' (She's) trước 'going to'."},{"wrong":"They not going to come.","right":"They're not going to come.","why":"Quên sử dụng 'are' (They're) trước 'not going to'."},{"wrong":"I am go to the movies.","right":"I'm going to the movies.","why":"Sử dụng 'am' không đúng cách trước 'going to'."}],"tips":"**Mẹo nhớ:** Luôn nhớ sử dụng **am/is/are** trước **going to** khi nói về kế hoạch hoặc dự định trong tương lai gần.","comparison":"**Be going to vs Hiện tại tiếp diễn (nói về tương lai):** Going to = DỰ ĐỊNH / ý định, chưa chắc đã sắp xếp (*We're going to have a party* — định tổ chức). Tiếp diễn = lịch đã SẮP XẾP cố định với người khác (*We're having a party next week* — đã chốt, mời khách rồi).","timeline":{"caption":"Going to = kế hoạch/dấu hiệu CÓ TỪ TRƯỚC now, mũi tên đã giương sẵn về tương lai (khác will = quyết định ngay tại chỗ).","points":[{"label":"đã lên kế hoạch 📋","note":"trước now"},{"label":"NOW: going to...","note":""},{"label":"→ hành động","note":"tương lai"}]}}$grammar$::jsonb, $grammar$[{"type":"fill","q":"The baby's face is red. She ____ (cry).","opts":[],"answer":"is going to cry","fb":"mặt đỏ = dấu hiệu thấy được → be going to"},{"type":"fill","q":"My parents ____ (buy) a new house next year. They have saved money.","opts":[],"answer":"are going to buy","fb":"đã dành tiền = kế hoạch có sẵn"},{"type":"fill","q":"They are going to build a new bridge here.  →  A new bridge ____ here.","opts":[],"answer":"is going to be built","fb":"Tương lai gần → is going to be + V3, cắt by them"}]$grammar$::jsonb, 'ai-golden', 22
from public.grammar_topics t where t.slug = 'be-going-to'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 23. future-will
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('future-will', 'Future Simple (will)', 'Thì Tương lai đơn (will)', 'beginner', 23)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Tương lai đơn (will)', '**Tương lai đơn với will** diễn tả quyết định ngay lúc nói, dự đoán dựa trên ý kiến, lời hứa, lời đề nghị và sự việc tương lai được xem là chắc chắn. **Will** dùng như nhau với mọi chủ ngữ và động từ sau will luôn ở nguyên thể.', $grammar$[{"en":"I'll call you tonight.","vi":"Tối nay tôi sẽ gọi cho bạn.","note":"Lời hứa hoặc quyết định.","annotations":[{"word":"I'll","start":0,"end":4,"role":"pronoun"},{"word":"call","start":5,"end":9,"role":"verb"},{"word":"you","start":10,"end":13,"role":"pronoun"},{"word":"tonight","start":14,"end":21,"role":"adverb"}]},{"en":"She won't attend the meeting.","vi":"Cô ấy sẽ không dự cuộc họp.","note":"won't + V nguyên thể.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"won't","start":4,"end":9,"role":"auxiliary"},{"word":"attend","start":10,"end":16,"role":"verb"},{"word":"the","start":17,"end":20,"role":"article"},{"word":"meeting","start":21,"end":28,"role":"noun"}]},{"en":"Will they arrive before noon?","vi":"Họ sẽ đến trước buổi trưa chứ?","note":"Câu hỏi đảo will lên trước chủ ngữ.","annotations":[{"word":"Will","start":0,"end":4,"role":"modal"},{"word":"they","start":5,"end":9,"role":"pronoun"},{"word":"arrive","start":10,"end":16,"role":"verb"},{"word":"before","start":17,"end":23,"role":"preposition"},{"word":"noon","start":24,"end":28,"role":"noun"}]},{"en":"I think our team will win.","vi":"Tôi nghĩ đội chúng ta sẽ thắng.","note":"Dự đoán dựa trên ý kiến.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"think","start":2,"end":7,"role":"verb"},{"word":"our","start":8,"end":11,"role":"determiner"},{"word":"team","start":12,"end":16,"role":"noun"},{"word":"will","start":17,"end":21,"role":"modal"},{"word":"win","start":22,"end":25,"role":"verb"}]},{"en":"Don't worry; I'll carry the box.","vi":"Đừng lo; tôi sẽ mang chiếc hộp.","note":"Quyết định giúp ngay lúc nói.","annotations":[{"word":"Don't","start":0,"end":5,"role":"auxiliary"},{"word":"worry","start":6,"end":11,"role":"verb"},{"word":"I'll","start":13,"end":17,"role":"pronoun"},{"word":"carry","start":18,"end":23,"role":"modal"},{"word":"the","start":24,"end":27,"role":"verb"},{"word":"box","start":28,"end":31,"role":"article"}]},{"en":"The sun will rise at 5:30 tomorrow.","vi":"Ngày mai mặt trời sẽ mọc lúc 5:30.","note":"Sự việc tương lai.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"sun","start":4,"end":7,"role":"noun"},{"word":"will","start":8,"end":12,"role":"modal"},{"word":"rise","start":13,"end":17,"role":"verb"},{"word":"at","start":18,"end":20,"role":"preposition"},{"word":"5:30","start":21,"end":25,"role":"other"},{"word":"tomorrow","start":26,"end":34,"role":"adverb"}]}]$grammar$::jsonb, $grammar${"definition":"**Tương lai đơn với will** diễn tả quyết định ngay lúc nói, dự đoán dựa trên ý kiến, lời hứa, lời đề nghị và sự việc tương lai được xem là chắc chắn. **Will** dùng như nhau với mọi chủ ngữ và động từ sau will luôn ở nguyên thể.","usage":[{"icon":"⚡","label":"Quyết định ngay lúc nói","en":"The phone is ringing. I’ll answer it.","vi":"Điện thoại đang reo. Tôi sẽ nghe."},{"icon":"🔮","label":"Dự đoán hoặc ý kiến","en":"I think it will rain tomorrow.","vi":"Tôi nghĩ ngày mai trời sẽ mưa."},{"icon":"🤝","label":"Lời hứa hoặc đề nghị giúp","en":"I’ll help you with your bags.","vi":"Tôi sẽ giúp bạn mang túi."},{"icon":"📅","label":"Sự việc tương lai","en":"She will be twenty next month.","vi":"Tháng sau cô ấy sẽ tròn hai mươi tuổi."}],"formula":{"rows":[{"form":"Khẳng định","structure":"S + will + V / S'll + V","example":"They'll arrive soon."},{"form":"Phủ định","structure":"S + will not + V / won't + V","example":"He won't forget."},{"form":"Nghi vấn","structure":"Will + S + V?","example":"Will you come?"},{"form":"Trả lời ngắn","structure":"Yes, S will. / No, S won't.","example":"Yes, I will."}],"note":"Đọc cấu trúc cùng ví dụ và luôn kiểm tra vai trò, số lượng hoặc dạng động từ theo từng trường hợp."},"rules":[{"case":"Mọi chủ ngữ","rule":"Dùng will giống nhau","example":"I/She/They will go."},{"case":"Sau will","rule":"Dùng V nguyên thể không to","example":"will study, không phải will studies"},{"case":"Phủ định","rule":"will not = won't","example":"We won't be late."},{"case":"Câu hỏi đề nghị","rule":"Will you + V...?","example":"Will you open the door?"}],"signals":["tomorrow","next week/year","soon","I think","probably","I promise"],"examples":[{"en":"I'll call you tonight.","vi":"Tối nay tôi sẽ gọi cho bạn.","note":"Lời hứa hoặc quyết định.","annotations":[{"word":"I'll","start":0,"end":4,"role":"pronoun"},{"word":"call","start":5,"end":9,"role":"verb"},{"word":"you","start":10,"end":13,"role":"pronoun"},{"word":"tonight","start":14,"end":21,"role":"adverb"}]},{"en":"She won't attend the meeting.","vi":"Cô ấy sẽ không dự cuộc họp.","note":"won't + V nguyên thể.","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"won't","start":4,"end":9,"role":"auxiliary"},{"word":"attend","start":10,"end":16,"role":"verb"},{"word":"the","start":17,"end":20,"role":"article"},{"word":"meeting","start":21,"end":28,"role":"noun"}]},{"en":"Will they arrive before noon?","vi":"Họ sẽ đến trước buổi trưa chứ?","note":"Câu hỏi đảo will lên trước chủ ngữ.","annotations":[{"word":"Will","start":0,"end":4,"role":"modal"},{"word":"they","start":5,"end":9,"role":"pronoun"},{"word":"arrive","start":10,"end":16,"role":"verb"},{"word":"before","start":17,"end":23,"role":"preposition"},{"word":"noon","start":24,"end":28,"role":"noun"}]},{"en":"I think our team will win.","vi":"Tôi nghĩ đội chúng ta sẽ thắng.","note":"Dự đoán dựa trên ý kiến.","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"think","start":2,"end":7,"role":"verb"},{"word":"our","start":8,"end":11,"role":"determiner"},{"word":"team","start":12,"end":16,"role":"noun"},{"word":"will","start":17,"end":21,"role":"modal"},{"word":"win","start":22,"end":25,"role":"verb"}]},{"en":"Don't worry; I'll carry the box.","vi":"Đừng lo; tôi sẽ mang chiếc hộp.","note":"Quyết định giúp ngay lúc nói.","annotations":[{"word":"Don't","start":0,"end":5,"role":"auxiliary"},{"word":"worry","start":6,"end":11,"role":"verb"},{"word":"I'll","start":13,"end":17,"role":"pronoun"},{"word":"carry","start":18,"end":23,"role":"modal"},{"word":"the","start":24,"end":27,"role":"verb"},{"word":"box","start":28,"end":31,"role":"article"}]},{"en":"The sun will rise at 5:30 tomorrow.","vi":"Ngày mai mặt trời sẽ mọc lúc 5:30.","note":"Sự việc tương lai.","annotations":[{"word":"The","start":0,"end":3,"role":"article"},{"word":"sun","start":4,"end":7,"role":"noun"},{"word":"will","start":8,"end":12,"role":"modal"},{"word":"rise","start":13,"end":17,"role":"verb"},{"word":"at","start":18,"end":20,"role":"preposition"},{"word":"5:30","start":21,"end":25,"role":"other"},{"word":"tomorrow","start":26,"end":34,"role":"adverb"}]}],"mistakes":[{"wrong":"She will goes tomorrow.","right":"She will go tomorrow.","why":"Sau will dùng động từ nguyên thể."},{"wrong":"I won't to forget.","right":"I won't forget.","why":"Sau won't không dùng to."},{"wrong":"Will you will come?","right":"Will you come?","why":"Trong câu hỏi chỉ dùng một will trước chủ ngữ."},{"wrong":"I'll to help you with the homework.","right":"I'll help you with the homework.","why":"Sau will/'ll là động từ NGUYÊN THỂ KHÔNG TO."},{"wrong":"He wills come tomorrow.","right":"He will come tomorrow.","why":"Will là modal — không chia -s theo ngôi."}],"tips":"**Mẹo:** Sau **will/won’t** luôn đặt động từ nguyên thể. Gặp quyết định tức thời, lời hứa, đề nghị giúp hoặc cụm **I think/probably**, hãy cân nhắc dùng will.","comparison":"**Will vs Be going to:** Will = quyết định BỘT PHÁT ngay lúc nói (*I'll turn on the light* — vừa nghĩ ra). Be going to = dự định đã có TRƯỚC khi nói (*I'm going to clean my shoes* — đã định từ trước).","timeline":{"caption":"Will = đứng ở NOW quyết định/dự đoán ngay tại chỗ cho việc phía trước — chưa có kế hoạch từ trước.","points":[{"label":"NOW: quyết định 💡","note":"I'll help you!"},{"label":"→ hành động","note":"tương lai"}]}}$grammar$::jsonb, $grammar$[{"type":"fill","q":"I'm sure our team ____ (win) the match tomorrow.","opts":[],"answer":"will win","fb":"I'm sure = tin chắc, chỉ là đoán → will"},{"type":"fill","q":"I don't think it ____ (rain) this evening.","opts":[],"answer":"will rain","fb":"I don't think = đoán, chưa thấy bằng chứng nào → will"},{"type":"fill","q":"The phone is ringing! — Don't stand up, I ____ (answer) it.","opts":[],"answer":"will answer","fb":"vừa nghe chuông mới quyết nhận giúp → will"},{"type":"fill","q":"Nam is very sad now. — Don't worry, I ____ (not / tell) him the truth.","opts":[],"answer":"won't tell","fb":"hứa ngay lúc nói → will, phủ định là won't"},{"type":"fill","q":"In 2030 people ____ (live) on the Moon, I think.","opts":[],"answer":"will live","fb":"I think = đoán chuyện xa → will"},{"type":"fill","q":"The new stadium will ____ (open) next June.","opts":[],"answer":"be opened","fb":"sau will → be + V3"},{"type":"fill","q":"People expect that the price will fall.  →  The price ____ to fall.","opts":[],"answer":"is expected","fb":"Chủ ngữ thật lên đầu · việc ở vế sau xảy ra SAU → to + V (will fall → to fall)"},{"type":"fill","q":"If Minh ____ (come) to my house tomorrow, we ____ (play) football together.","opts":[],"answer":"comes / will play","fb":"tomorrow còn xảy ra được → loại 1, Minh = he nên thêm -s"},{"type":"fill","q":"If Nam ____ (not / wake) up early, he ____ (be) late for school tomorrow.","opts":[],"answer":"doesn't wake / will be","fb":"tomorrow → loại 1 · Nam = he nên dùng doesn't"},{"type":"fill","q":"If it ____ (not / rain) this weekend, we ____ (go) camping.","opts":[],"answer":"doesn't rain / will go","fb":"this weekend còn xảy ra được → loại 1"},{"type":"fill","q":"Viết lại dùng unless: If you don't turn off the lights, the bill will be very high.","opts":[],"answer":"Unless you turn off the lights, the bill will be very high.","fb":"unless đã mang nghĩa “không” → bỏ don't"},{"type":"fill","q":"If my parents ____ (agree), I ____ (join) the English club next month.","opts":[],"answer":"agree / will join","fb":"next month → loại 1"},{"type":"fill","q":"Đổi sang gián tiếp: Lan said to me: “I will call you tonight.”","opts":[],"answer":"Lan told me (that) she would call me that night.","fb":"said to me → told me · will lùi thành would · tonight → that night"},{"type":"fill","q":"I don't know where Mai is. She ____ in the library. (may be / must be)","opts":[],"answer":"may be","fb":"không biết chắc nên chỉ đoán → may be"},{"type":"fill","q":"Don't forget to lock the door, ____?","opts":[],"answer":"will you","fb":"câu mệnh lệnh → đuôi will you"},{"type":"fill","q":"If I ____ you, I would tell the truth.  (A am · B was · C were · D will be)","opts":[],"answer":"C were","fb":"Điều kiện loại 2 dùng were cho mọi chủ ngữ · buổi 15"}]$grammar$::jsonb, 'ai-golden', 23
from public.grammar_topics t where t.slug = 'future-will'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 24. comparatives-superlatives
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('comparatives-superlatives', 'Comparatives & Superlatives', 'So sánh hơn & so sánh nhất', 'beginner', 24)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'So sánh hơn & so sánh nhất', '**So sánh hơn** (comparatives) dùng để đối chiếu sự khác biệt giữa hai đối tượng, thường dùng đuôi ''-er'' hoặc ''more'' và đi với ''than''. **So sánh nhất** (superlatives) dùng với ''the'' cùng đuôi ''-est'' hoặc ''most'' để xác định đối tượng có đặc điểm cao nhất trong một nhóm.', $grammar$[{"en":"This room is brighter than mine.","vi":"Phòng này sáng hơn phòng tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":9,"role":"noun","word":"room","start":5},{"end":12,"role":"auxiliary","word":"is","start":10},{"end":21,"role":"adjective","word":"brighter","start":13},{"end":26,"role":"preposition","word":"than","start":22},{"end":31,"role":"pronoun","word":"mine","start":27}]},{"en":"Lan is the tallest student in the class.","vi":"Lan là học sinh cao nhất lớp.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"Lan","start":0},{"end":6,"role":"auxiliary","word":"is","start":4},{"end":10,"role":"article","word":"the","start":7},{"end":18,"role":"adjective","word":"tallest","start":11},{"end":26,"role":"noun","word":"student","start":19},{"end":29,"role":"preposition","word":"in","start":27},{"end":33,"role":"article","word":"the","start":30},{"end":39,"role":"noun","word":"class","start":34}]},{"en":"The train is more comfortable than the bus.","vi":"Tàu hỏa thoải mái hơn xe buýt.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"noun","word":"train","start":4},{"end":12,"role":"auxiliary","word":"is","start":10},{"end":17,"role":"adverb","word":"more","start":13},{"end":29,"role":"adjective","word":"comfortable","start":18},{"end":34,"role":"preposition","word":"than","start":30},{"end":38,"role":"article","word":"the","start":35},{"end":42,"role":"noun","word":"bus","start":39}]},{"en":"That was the most useful lesson.","vi":"Đó là bài học hữu ích nhất.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"That","start":0},{"end":8,"role":"auxiliary","word":"was","start":5},{"end":12,"role":"article","word":"the","start":9},{"end":17,"role":"adverb","word":"most","start":13},{"end":24,"role":"adjective","word":"useful","start":18},{"end":31,"role":"noun","word":"lesson","start":25}]},{"en":"Today is less humid than yesterday.","vi":"Hôm nay ít ẩm hơn hôm qua.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"Today","start":0},{"end":8,"role":"auxiliary","word":"is","start":6},{"end":13,"role":"adverb","word":"less","start":9},{"end":19,"role":"adjective","word":"humid","start":14},{"end":24,"role":"preposition","word":"than","start":20},{"end":34,"role":"noun","word":"yesterday","start":25}]},{"en":"Your bag is as heavy as mine.","vi":"Túi của bạn nặng bằng túi tôi.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"Your","start":0},{"end":8,"role":"noun","word":"bag","start":5},{"end":11,"role":"auxiliary","word":"is","start":9},{"end":14,"role":"adverb","word":"as","start":12},{"end":20,"role":"adjective","word":"heavy","start":15},{"end":23,"role":"preposition","word":"as","start":21},{"end":28,"role":"pronoun","word":"mine","start":24}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **short adjective + -er / the + -est** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"short adjective + -er / the + -est","example":"This room is brighter than mine."},{"case":"Kiểm tra thành phần theo sau","rule":"more / the most + long adjective","example":"Lan is the tallest student in the class."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"as + adjective + as","example":"The train is more comfortable than the bus."}],"usage":[{"en":"This room is brighter than mine.","vi":"Phòng này sáng hơn phòng của tôi.","icon":"⚖️","label":"So sánh hơn giữa hai đối tượng (-er + than)"},{"en":"Lan is the tallest student in the class.","vi":"Lan là học sinh cao nhất lớp.","icon":"🥇","label":"So sánh nhất trong một nhóm (the + -est)"},{"en":"The train is more comfortable than the bus.","vi":"Đi tàu thoải mái hơn đi xe buýt.","icon":"📏","label":"Tính từ dài: more + tính từ + than"},{"en":"That was the most useful lesson.","vi":"Đó là bài học hữu ích nhất.","icon":"👑","label":"Tính từ dài: the most + tính từ"},{"en":"This bag is as expensive as that one.","vi":"Chiếc túi này đắt ngang chiếc kia.","icon":"🤝","label":"So sánh bằng với as ... as"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"short adjective + -er / the + -est","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"more / the most + long adjective","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"as + adjective + as","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["than","as ... as","more","the most","-er","-est","less","least"],"examples":[{"en":"This room is brighter than mine.","vi":"Phòng này sáng hơn phòng tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":9,"role":"noun","word":"room","start":5},{"end":12,"role":"auxiliary","word":"is","start":10},{"end":21,"role":"adjective","word":"brighter","start":13},{"end":26,"role":"preposition","word":"than","start":22},{"end":31,"role":"pronoun","word":"mine","start":27}]},{"en":"Lan is the tallest student in the class.","vi":"Lan là học sinh cao nhất lớp.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"Lan","start":0},{"end":6,"role":"auxiliary","word":"is","start":4},{"end":10,"role":"article","word":"the","start":7},{"end":18,"role":"adjective","word":"tallest","start":11},{"end":26,"role":"noun","word":"student","start":19},{"end":29,"role":"preposition","word":"in","start":27},{"end":33,"role":"article","word":"the","start":30},{"end":39,"role":"noun","word":"class","start":34}]},{"en":"The train is more comfortable than the bus.","vi":"Tàu hỏa thoải mái hơn xe buýt.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"noun","word":"train","start":4},{"end":12,"role":"auxiliary","word":"is","start":10},{"end":17,"role":"adverb","word":"more","start":13},{"end":29,"role":"adjective","word":"comfortable","start":18},{"end":34,"role":"preposition","word":"than","start":30},{"end":38,"role":"article","word":"the","start":35},{"end":42,"role":"noun","word":"bus","start":39}]},{"en":"That was the most useful lesson.","vi":"Đó là bài học hữu ích nhất.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"That","start":0},{"end":8,"role":"auxiliary","word":"was","start":5},{"end":12,"role":"article","word":"the","start":9},{"end":17,"role":"adverb","word":"most","start":13},{"end":24,"role":"adjective","word":"useful","start":18},{"end":31,"role":"noun","word":"lesson","start":25}]},{"en":"Today is less humid than yesterday.","vi":"Hôm nay ít ẩm hơn hôm qua.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"Today","start":0},{"end":8,"role":"auxiliary","word":"is","start":6},{"end":13,"role":"adverb","word":"less","start":9},{"end":19,"role":"adjective","word":"humid","start":14},{"end":24,"role":"preposition","word":"than","start":20},{"end":34,"role":"noun","word":"yesterday","start":25}]},{"en":"Your bag is as heavy as mine.","vi":"Túi của bạn nặng bằng túi tôi.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"Your","start":0},{"end":8,"role":"noun","word":"bag","start":5},{"end":11,"role":"auxiliary","word":"is","start":9},{"end":14,"role":"adverb","word":"as","start":12},{"end":20,"role":"adjective","word":"heavy","start":15},{"end":23,"role":"preposition","word":"as","start":21},{"end":28,"role":"pronoun","word":"mine","start":24}]}],"mistakes":[{"wrong":"She is more tall than him.","right":"She is taller than him.","why":"Tính từ ngắn thêm -er, không dùng more."},{"wrong":"This is the most big house.","right":"This is the biggest house.","why":"Tính từ ngắn thêm -est, không dùng most."},{"wrong":"He is more clever than me.","right":"He is cleverer than me.","why":"Tính từ 2 âm tiết kết thúc bằng -er/-y thường thêm -er."},{"wrong":"That is the most cheapest one.","right":"That is the cheapest one.","why":"Không ghép most + -est (double superlative)."}],"timeline":null,"comparison":"**So sánh hơn vs so sánh nhất:** So sánh HƠN giữa 2 đối tượng: -er/more + than (*This hotel is cheaper than that one*). So sánh NHẤT trong nhóm ≥3: the + -est/most (*the cheapest in town*). Tính từ ngắn thêm đuôi, tính từ dài dùng more/most — không dùng cả hai cùng lúc.","definition":"**So sánh hơn** (comparatives) dùng để đối chiếu sự khác biệt giữa hai đối tượng, thường dùng đuôi '-er' hoặc 'more' và đi với 'than'. **So sánh nhất** (superlatives) dùng với 'the' cùng đuôi '-est' hoặc 'most' để xác định đối tượng có đặc điểm cao nhất trong một nhóm."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Your flat is ____ (large) than mine.","opts":[],"answer":"larger","fb":"than → hơn, large đã có e nên chỉ thêm r"},{"type":"fill","q":"Grace is ____ (old) girl in our class.","opts":[],"answer":"the oldest","fb":"in our class → nhất, old ngắn nên the + -est"},{"type":"fill","q":"She sings ____ (beautiful) in this school.","opts":[],"answer":"the most beautifully","fb":"in this school → nhất, bổ nghĩa cho sings nên là trạng từ dài"},{"type":"fill","q":"Jane is not ____ (intelligent) as her brother.","opts":[],"answer":"as intelligent","fb":"phủ định của so sánh bằng vẫn giữ tính từ gốc"},{"type":"fill","q":"____ Earth moves around ____ Sun.","opts":[],"answer":"The / the","fb":"Trái Đất và Mặt Trời đều là duy nhất → the"},{"type":"fill","q":"Nam is the ____ student in our class.  (A tall · B taller · C tallest · D most tall)","opts":[],"answer":"C tallest","fb":"So sánh nhất, tall là tính từ ngắn nên thêm -est · buổi 11"}]$grammar$::jsonb, 'ai-golden', 24
from public.grammar_topics t where t.slug = 'comparatives-superlatives'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 25. modals-permission
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('modals-permission', 'Modals: Permission & Requests', 'Khuyết thiếu: xin phép & yêu cầu', 'beginner', 25)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Khuyết thiếu: xin phép & yêu cầu', 'Các động từ khuyết thiếu như **''can'', ''could'', ''may''** được sử dụng để xin phép hoặc đưa ra yêu cầu một cách lịch sự. Trong khi ''can'' và ''could'' phổ biến trong giao tiếp hàng ngày, ''may'' mang sắc thái trang trọng hơn khi xin phép.', $grammar$[{"en":"May I come in?","vi":"Tôi vào được không ạ?","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"modal","word":"May","start":0},{"end":5,"role":"pronoun","word":"I","start":4},{"end":10,"role":"verb","word":"come","start":6},{"end":13,"role":"preposition","word":"in","start":11}]},{"en":"Could you open the window, please?","vi":"Bạn vui lòng mở cửa sổ được không?","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"modal","word":"Could","start":0},{"end":9,"role":"pronoun","word":"you","start":6},{"end":14,"role":"verb","word":"open","start":10},{"end":18,"role":"article","word":"the","start":15},{"end":25,"role":"noun","word":"window","start":19},{"end":33,"role":"adverb","word":"please","start":27}]},{"en":"Can I borrow your pen?","vi":"Tôi mượn bút của bạn được không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"modal","word":"Can","start":0},{"end":5,"role":"pronoun","word":"I","start":4},{"end":12,"role":"verb","word":"borrow","start":6},{"end":17,"role":"determiner","word":"your","start":13},{"end":21,"role":"noun","word":"pen","start":18}]},{"en":"Would you wait here for a moment?","vi":"Bạn vui lòng chờ ở đây một lát nhé?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"modal","word":"Would","start":0},{"end":9,"role":"pronoun","word":"you","start":6},{"end":14,"role":"verb","word":"wait","start":10},{"end":19,"role":"adverb","word":"here","start":15},{"end":23,"role":"preposition","word":"for","start":20},{"end":25,"role":"article","word":"a","start":24},{"end":32,"role":"noun","word":"moment","start":26}]},{"en":"Do you mind helping me?","vi":"Bạn có phiền giúp tôi không?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"auxiliary","word":"Do","start":0},{"end":6,"role":"pronoun","word":"you","start":3},{"end":11,"role":"verb","word":"mind","start":7},{"end":19,"role":"verb","word":"helping","start":12},{"end":22,"role":"pronoun","word":"me","start":20}]},{"en":"You may leave early today.","vi":"Hôm nay bạn được phép về sớm.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":7,"role":"modal","word":"may","start":4},{"end":13,"role":"verb","word":"leave","start":8},{"end":19,"role":"adverb","word":"early","start":14},{"end":25,"role":"adverb","word":"today","start":20}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **Can/Could/May + S + V?** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"Can/Could/May + S + V?","example":"May I come in?"},{"case":"Kiểm tra thành phần theo sau","rule":"Would you + V ...?","example":"Could you open the window, please?"},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Do you mind + V-ing ...?","example":"Can I borrow your pen?"}],"usage":[{"en":"May I come in?","vi":"Tôi vào được không ạ?","icon":"🎩","label":"MAY — xin phép trang trọng, lịch sự"},{"en":"Could you open the window, please?","vi":"Bạn mở giúp cửa sổ được không?","icon":"🙏","label":"COULD YOU — nhờ vả lịch sự"},{"en":"Can I borrow your pen?","vi":"Cho mình mượn bút nhé?","icon":"😊","label":"CAN — xin phép thân mật, suồng sã"},{"en":"Would you wait here for a moment?","vi":"Phiền anh/chị đợi ở đây một lát được không?","icon":"💼","label":"WOULD YOU — yêu cầu rất lịch sự, trang trọng"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"Can/Could/May + S + V?","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Would you + V ...?","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Do you mind + V-ing ...?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["can","could","may","allowed to","Do you mind if","Is it OK if"],"examples":[{"en":"May I come in?","vi":"Tôi vào được không ạ?","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"modal","word":"May","start":0},{"end":5,"role":"pronoun","word":"I","start":4},{"end":10,"role":"verb","word":"come","start":6},{"end":13,"role":"preposition","word":"in","start":11}]},{"en":"Could you open the window, please?","vi":"Bạn vui lòng mở cửa sổ được không?","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"modal","word":"Could","start":0},{"end":9,"role":"pronoun","word":"you","start":6},{"end":14,"role":"verb","word":"open","start":10},{"end":18,"role":"article","word":"the","start":15},{"end":25,"role":"noun","word":"window","start":19},{"end":33,"role":"adverb","word":"please","start":27}]},{"en":"Can I borrow your pen?","vi":"Tôi mượn bút của bạn được không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"modal","word":"Can","start":0},{"end":5,"role":"pronoun","word":"I","start":4},{"end":12,"role":"verb","word":"borrow","start":6},{"end":17,"role":"determiner","word":"your","start":13},{"end":21,"role":"noun","word":"pen","start":18}]},{"en":"Would you wait here for a moment?","vi":"Bạn vui lòng chờ ở đây một lát nhé?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"modal","word":"Would","start":0},{"end":9,"role":"pronoun","word":"you","start":6},{"end":14,"role":"verb","word":"wait","start":10},{"end":19,"role":"adverb","word":"here","start":15},{"end":23,"role":"preposition","word":"for","start":20},{"end":25,"role":"article","word":"a","start":24},{"end":32,"role":"noun","word":"moment","start":26}]},{"en":"Do you mind helping me?","vi":"Bạn có phiền giúp tôi không?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"auxiliary","word":"Do","start":0},{"end":6,"role":"pronoun","word":"you","start":3},{"end":11,"role":"verb","word":"mind","start":7},{"end":19,"role":"verb","word":"helping","start":12},{"end":22,"role":"pronoun","word":"me","start":20}]},{"en":"You may leave early today.","vi":"Hôm nay bạn được phép về sớm.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":7,"role":"modal","word":"may","start":4},{"end":13,"role":"verb","word":"leave","start":8},{"end":19,"role":"adverb","word":"early","start":14},{"end":25,"role":"adverb","word":"today","start":20}]}],"mistakes":[{"wrong":"Can I to use your phone?","right":"Can I use your phone?","why":"Sau can là động từ nguyên thể không to."},{"wrong":"May I borrowing your pen?","right":"May I borrow your pen?","why":"Sau may là động từ nguyên thể, không phải V-ing."},{"wrong":"He said we might wait here.","right":"He said we could wait here.","why":"Trong câu tường thuật, may (xin phép) lùi thành could."},{"wrong":"You mustn't go, it's optional.","right":"You don't have to go, it's optional.","why":"Mustn't = cấm; don't have to = không cần — không nhầm."}],"timeline":null,"comparison":"**Can vs May (xin phép):** Cả hai đều xin phép nhưng *may* trang trọng, lịch sự hơn; *can* dùng trong tình huống thân mật. *Can I use your phone?* (bạn bè) vs *May I use your phone?* (trang trọng). Trong reported speech, may → could.","definition":"Các động từ khuyết thiếu như **'can', 'could', 'may'** được sử dụng để xin phép hoặc đưa ra yêu cầu một cách lịch sự. Trong khi 'can' và 'could' phổ biến trong giao tiếp hàng ngày, 'may' mang sắc thái trang trọng hơn khi xin phép."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: ___ you open the window, please?","answer":["Could"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 25
from public.grammar_topics t where t.slug = 'modals-permission'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 26. modals-obligation
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('modals-obligation', 'Modals: Obligation (must/have to)', 'Khuyết thiếu: bắt buộc (must/have to)', 'beginner', 26)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Khuyết thiếu: bắt buộc (must/have to)', '**Động từ khuyết thiếu chỉ sự bắt buộc** như ''must'' và ''have to'' dùng để diễn tả nghĩa vụ hoặc sự cần thiết phải thực hiện một hành động. Trong đó, ''have to'' thường nhấn mạnh vào quy định khách quan từ bên ngoài, còn ''must'' thường mang sắc thái chủ quan hoặc mệnh lệnh nghiêm khắc từ chính người nói.', $grammar$[{"en":"You must wear a helmet.","vi":"Bạn phải đội mũ bảo hiểm.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":8,"role":"modal","word":"must","start":4},{"end":13,"role":"verb","word":"wear","start":9},{"end":15,"role":"article","word":"a","start":14},{"end":22,"role":"noun","word":"helmet","start":16}]},{"en":"I have to submit this today.","vi":"Tôi phải nộp việc này hôm nay.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"auxiliary","word":"have","start":2},{"end":9,"role":"preposition","word":"to","start":7},{"end":16,"role":"verb","word":"submit","start":10},{"end":21,"role":"determiner","word":"this","start":17},{"end":27,"role":"adverb","word":"today","start":22}]},{"en":"Visitors mustn't touch the paintings.","vi":"Khách tham quan không được chạm vào tranh.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":8,"role":"noun","word":"Visitors","start":0},{"end":16,"role":"modal","word":"mustn't","start":9},{"end":22,"role":"verb","word":"touch","start":17},{"end":26,"role":"article","word":"the","start":23},{"end":36,"role":"noun","word":"paintings","start":27}]},{"en":"You don't have to come early.","vi":"Bạn không cần đến sớm.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":9,"role":"determiner","word":"don't","start":4},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":17,"role":"preposition","word":"to","start":15},{"end":22,"role":"verb","word":"come","start":18},{"end":28,"role":"adverb","word":"early","start":23}]},{"en":"Did she have to pay a fee?","vi":"Cô ấy có phải trả phí không?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Did","start":0},{"end":7,"role":"pronoun","word":"she","start":4},{"end":12,"role":"auxiliary","word":"have","start":8},{"end":15,"role":"preposition","word":"to","start":13},{"end":19,"role":"verb","word":"pay","start":16},{"end":21,"role":"article","word":"a","start":20},{"end":25,"role":"noun","word":"fee","start":22}]},{"en":"We had to cancel the trip.","vi":"Chúng tôi đã phải hủy chuyến đi.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":6,"role":"auxiliary","word":"had","start":3},{"end":9,"role":"preposition","word":"to","start":7},{"end":16,"role":"verb","word":"cancel","start":10},{"end":20,"role":"article","word":"the","start":17},{"end":25,"role":"noun","word":"trip","start":21}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + must + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + must + V","example":"You must wear a helmet."},{"case":"Kiểm tra thành phần theo sau","rule":"S + have/has to + V","example":"I have to submit this today."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"mustn't + V / don't have to + V","example":"Visitors mustn't touch the paintings."}],"usage":[{"en":"You must wear a helmet.","vi":"Bạn phải đội mũ bảo hiểm.","icon":"🪖","label":"MUST — bắt buộc do người nói tự đặt ra"},{"en":"I have to submit this report today.","vi":"Hôm nay tôi phải nộp báo cáo này.","icon":"🏢","label":"HAVE TO — bắt buộc do quy định, hoàn cảnh bên ngoài"},{"en":"Visitors mustn't touch the paintings.","vi":"Khách tham quan không được chạm vào tranh.","icon":"⛔","label":"MUSTN'T — cấm, không được phép làm"},{"en":"You don't have to come early.","vi":"Bạn không cần phải đến sớm đâu.","icon":"🆓","label":"DON'T HAVE TO — không cần thiết phải làm"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + must + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + have/has to + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"mustn't + V / don't have to + V","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["must","mustn't","have to","don't have to","need to","had to"],"examples":[{"en":"You must wear a helmet.","vi":"Bạn phải đội mũ bảo hiểm.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":8,"role":"modal","word":"must","start":4},{"end":13,"role":"verb","word":"wear","start":9},{"end":15,"role":"article","word":"a","start":14},{"end":22,"role":"noun","word":"helmet","start":16}]},{"en":"I have to submit this today.","vi":"Tôi phải nộp việc này hôm nay.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"auxiliary","word":"have","start":2},{"end":9,"role":"preposition","word":"to","start":7},{"end":16,"role":"verb","word":"submit","start":10},{"end":21,"role":"determiner","word":"this","start":17},{"end":27,"role":"adverb","word":"today","start":22}]},{"en":"Visitors mustn't touch the paintings.","vi":"Khách tham quan không được chạm vào tranh.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":8,"role":"noun","word":"Visitors","start":0},{"end":16,"role":"modal","word":"mustn't","start":9},{"end":22,"role":"verb","word":"touch","start":17},{"end":26,"role":"article","word":"the","start":23},{"end":36,"role":"noun","word":"paintings","start":27}]},{"en":"You don't have to come early.","vi":"Bạn không cần đến sớm.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":9,"role":"determiner","word":"don't","start":4},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":17,"role":"preposition","word":"to","start":15},{"end":22,"role":"verb","word":"come","start":18},{"end":28,"role":"adverb","word":"early","start":23}]},{"en":"Did she have to pay a fee?","vi":"Cô ấy có phải trả phí không?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Did","start":0},{"end":7,"role":"pronoun","word":"she","start":4},{"end":12,"role":"auxiliary","word":"have","start":8},{"end":15,"role":"preposition","word":"to","start":13},{"end":19,"role":"verb","word":"pay","start":16},{"end":21,"role":"article","word":"a","start":20},{"end":25,"role":"noun","word":"fee","start":22}]},{"en":"We had to cancel the trip.","vi":"Chúng tôi đã phải hủy chuyến đi.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":6,"role":"auxiliary","word":"had","start":3},{"end":9,"role":"preposition","word":"to","start":7},{"end":16,"role":"verb","word":"cancel","start":10},{"end":20,"role":"article","word":"the","start":17},{"end":25,"role":"noun","word":"trip","start":21}]}],"mistakes":[{"wrong":"I must to finish this today.","right":"I must finish this today.","why":"Sau must là động từ nguyên thể không to."},{"wrong":"Yesterday I must walk home.","right":"Yesterday I had to walk home.","why":"Nghĩa vụ quá khứ dùng had to — must không có dạng quá khứ."},{"wrong":"You mustn't come, it's not necessary.","right":"You don't have to come, it's not necessary.","why":"Không bắt buộc dùng don't have to; mustn't nghĩa là CẤM."},{"wrong":"She must wears a uniform.","right":"She must wear a uniform.","why":"Sau must, động từ về nguyên thể — không chia -s."}],"timeline":null,"comparison":"**Mustn't vs Don't have to:** Dạng khẳng định must/have to gần nghĩa nhau, nhưng phủ định KHÁC HẲN: *You mustn't go* = CẤM đi. *You don't have to go* = KHÔNG CẦN đi (đi hay không tùy bạn). Đây là cặp gây hiểu nhầm nguy hiểm nhất của modal.","definition":"**Động từ khuyết thiếu chỉ sự bắt buộc** như 'must' và 'have to' dùng để diễn tả nghĩa vụ hoặc sự cần thiết phải thực hiện một hành động. Trong đó, 'have to' thường nhấn mạnh vào quy định khách quan từ bên ngoài, còn 'must' thường mang sắc thái chủ quan hoặc mệnh lệnh nghiêm khắc từ chính người nói."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Children ____ play with matches. (mustn't / needn't)","opts":[],"answer":"mustn't","fb":"nguy hiểm nên cấm hẳn → mustn't"},{"type":"fill","q":"It's Sunday tomorrow, so I ____ get up early. (needn't / mustn't)","opts":[],"answer":"needn't","fb":"chủ nhật nghỉ nên khỏi cần dậy sớm, không phải cấm"},{"type":"fill","q":"You ____ take photos in this museum. Look at the sign. (mustn't / needn't)","opts":[],"answer":"mustn't","fb":"có biển cấm → mustn't"}]$grammar$::jsonb, 'ai-golden', 26
from public.grammar_topics t where t.slug = 'modals-obligation'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 27. modals-advice
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('modals-advice', 'Modals: Advice (should/ought to)', 'Khuyết thiếu: lời khuyên (should)', 'beginner', 27)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Khuyết thiếu: lời khuyên (should)', '**Động từ khuyết thiếu chỉ lời khuyên** bao gồm ''should'' và ''ought to'', dùng để đưa ra gợi ý hoặc nhận định về một hành động được xem là đúng đắn hoặc phù hợp. Cấu trúc này không mang tính bắt buộc mà đóng vai trò định hướng hành vi, giúp người nghe cân nhắc lựa chọn tối ưu trong các tình huống cụ thể.', $grammar$[{"en":"You should get more sleep.","vi":"Bạn nên ngủ nhiều hơn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":10,"role":"modal","word":"should","start":4},{"end":14,"role":"verb","word":"get","start":11},{"end":19,"role":"determiner","word":"more","start":15},{"end":25,"role":"noun","word":"sleep","start":20}]},{"en":"We ought to apologize.","vi":"Chúng ta nên xin lỗi.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":8,"role":"modal","word":"ought","start":3},{"end":11,"role":"preposition","word":"to","start":9},{"end":21,"role":"verb","word":"apologize","start":12}]},{"en":"Should I call her now?","vi":"Tôi có nên gọi cô ấy bây giờ không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"modal","word":"Should","start":0},{"end":8,"role":"pronoun","word":"I","start":7},{"end":13,"role":"verb","word":"call","start":9},{"end":17,"role":"pronoun","word":"her","start":14},{"end":21,"role":"adverb","word":"now","start":18}]},{"en":"You shouldn't skip breakfast.","vi":"Bạn không nên bỏ bữa sáng.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":13,"role":"modal","word":"shouldn't","start":4},{"end":18,"role":"verb","word":"skip","start":14},{"end":28,"role":"noun","word":"breakfast","start":19}]},{"en":"You'd better take an umbrella.","vi":"Bạn nên mang ô thì hơn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"pronoun","word":"You'd","start":0},{"end":12,"role":"adverb","word":"better","start":6},{"end":17,"role":"verb","word":"take","start":13},{"end":20,"role":"article","word":"an","start":18},{"end":29,"role":"noun","word":"umbrella","start":21}]},{"en":"They should have checked the address.","vi":"Lẽ ra họ nên kiểm tra địa chỉ.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":11,"role":"modal","word":"should","start":5},{"end":16,"role":"auxiliary","word":"have","start":12},{"end":24,"role":"verb","word":"checked","start":17},{"end":28,"role":"article","word":"the","start":25},{"end":36,"role":"noun","word":"address","start":29}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + should/ought to + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + should/ought to + V","example":"You should get more sleep."},{"case":"Kiểm tra thành phần theo sau","rule":"S + shouldn't + V","example":"We ought to apologize."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"S + had better + V","example":"Should I call her now?"}],"usage":[{"en":"You should get more sleep.","vi":"Bạn nên ngủ nhiều hơn.","icon":"💡","label":"SHOULD — khuyên nên làm điều gì"},{"en":"We ought to apologize to her.","vi":"Chúng ta nên xin lỗi cô ấy mới phải.","icon":"📜","label":"OUGHT TO — lời khuyên mang tính đạo lý, đúng đắn"},{"en":"Should I call her now?","vi":"Tôi có nên gọi cho cô ấy bây giờ không?","icon":"❓","label":"SHOULD I...? — hỏi xin lời khuyên"},{"en":"You shouldn't skip breakfast.","vi":"Bạn không nên bỏ bữa sáng.","icon":"🚭","label":"SHOULDN'T — khuyên không nên làm"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + should/ought to + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + shouldn't + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + had better + V","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["should","shouldn't","ought to","had better","I would suggest"],"examples":[{"en":"You should get more sleep.","vi":"Bạn nên ngủ nhiều hơn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":10,"role":"modal","word":"should","start":4},{"end":14,"role":"verb","word":"get","start":11},{"end":19,"role":"determiner","word":"more","start":15},{"end":25,"role":"noun","word":"sleep","start":20}]},{"en":"We ought to apologize.","vi":"Chúng ta nên xin lỗi.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":8,"role":"modal","word":"ought","start":3},{"end":11,"role":"preposition","word":"to","start":9},{"end":21,"role":"verb","word":"apologize","start":12}]},{"en":"Should I call her now?","vi":"Tôi có nên gọi cô ấy bây giờ không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"modal","word":"Should","start":0},{"end":8,"role":"pronoun","word":"I","start":7},{"end":13,"role":"verb","word":"call","start":9},{"end":17,"role":"pronoun","word":"her","start":14},{"end":21,"role":"adverb","word":"now","start":18}]},{"en":"You shouldn't skip breakfast.","vi":"Bạn không nên bỏ bữa sáng.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":13,"role":"modal","word":"shouldn't","start":4},{"end":18,"role":"verb","word":"skip","start":14},{"end":28,"role":"noun","word":"breakfast","start":19}]},{"en":"You'd better take an umbrella.","vi":"Bạn nên mang ô thì hơn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"pronoun","word":"You'd","start":0},{"end":12,"role":"adverb","word":"better","start":6},{"end":17,"role":"verb","word":"take","start":13},{"end":20,"role":"article","word":"an","start":18},{"end":29,"role":"noun","word":"umbrella","start":21}]},{"en":"They should have checked the address.","vi":"Lẽ ra họ nên kiểm tra địa chỉ.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":11,"role":"modal","word":"should","start":5},{"end":16,"role":"auxiliary","word":"have","start":12},{"end":24,"role":"verb","word":"checked","start":17},{"end":28,"role":"article","word":"the","start":25},{"end":36,"role":"noun","word":"address","start":29}]}],"mistakes":[{"wrong":"You should to see a doctor.","right":"You should see a doctor.","why":"Sau should là động từ nguyên thể không to."},{"wrong":"He shoulds study harder.","right":"He should study harder.","why":"Should là modal — không chia -s."},{"wrong":"You had better to go now.","right":"You had better go now.","why":"Sau had better là động từ nguyên thể không to."},{"wrong":"I think everybody had better learn English.","right":"I think everybody should learn English.","why":"Lời khuyên chung dùng should; had better chỉ cho tình huống cụ thể."}],"timeline":null,"comparison":"**Should vs Had better:** *Should* = lời khuyên chung, \"làm thế là tốt\" (*You should go out more often*). *Had better* CHỈ dùng cho tình huống cụ thể có nguy cơ nếu không nghe (*It's late. You'd better go*). Không dùng had better cho lời khuyên chung chung.","definition":"**Động từ khuyết thiếu chỉ lời khuyên** bao gồm 'should' và 'ought to', dùng để đưa ra gợi ý hoặc nhận định về một hành động được xem là đúng đắn hoặc phù hợp. Cấu trúc này không mang tính bắt buộc mà đóng vai trò định hướng hành vi, giúp người nghe cân nhắc lựa chọn tối ưu trong các tình huống cụ thể."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"You should turn off the lights before you go to bed.  →  The lights ____ before you go to bed.","opts":[],"answer":"should be turned off","fb":"Modal should → should be + V3"},{"type":"fill","q":"I think you ____ go to bed earlier. (should / must)","opts":[],"answer":"should","fb":"I think + lời khuyên → should"},{"type":"fill","q":"It's a school rule: we ____ speak English in class. (have to / should)","opts":[],"answer":"have to","fb":"nội quy trường bắt → have to"},{"type":"fill","q":"You should avoid ____ (eat) too much sugar.","opts":[],"answer":"eating","fb":"avoid nằm nhóm V-ing"},{"type":"fill","q":"Children should not depend ____ their parents for everything.","opts":[],"answer":"on","fb":"depend luôn dính với on"}]$grammar$::jsonb, 'ai-golden', 27
from public.grammar_topics t where t.slug = 'modals-advice'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 28. conditionals-0-1
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('conditionals-0-1', 'Zero & First Conditional', 'Câu điều kiện loại 0 & loại 1', 'beginner', 28)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu điều kiện loại 0 & loại 1', 'Zero & First Conditional dùng **điều kiện loại 0 và loại 1** cho sự thật luôn đúng và khả năng thực tế trong tương lai. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"If you heat ice, it melts.","vi":"Nếu bạn làm nóng băng, nó tan.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":6,"role":"pronoun","word":"you","start":3},{"end":11,"role":"verb","word":"heat","start":7},{"end":15,"role":"noun","word":"ice","start":12},{"end":19,"role":"pronoun","word":"it","start":17},{"end":25,"role":"verb","word":"melts","start":20}]},{"en":"If it rains, we'll stay home.","vi":"Nếu trời mưa, chúng tôi sẽ ở nhà.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":5,"role":"pronoun","word":"it","start":3},{"end":11,"role":"verb","word":"rains","start":6},{"end":18,"role":"modal","word":"we'll","start":13},{"end":23,"role":"verb","word":"stay","start":19},{"end":28,"role":"noun","word":"home","start":24}]},{"en":"Plants die if they don't get water.","vi":"Cây chết nếu không có nước.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"noun","word":"Plants","start":0},{"end":10,"role":"verb","word":"die","start":7},{"end":13,"role":"conjunction","word":"if","start":11},{"end":18,"role":"pronoun","word":"they","start":14},{"end":24,"role":"auxiliary","word":"don't","start":19},{"end":28,"role":"verb","word":"get","start":25},{"end":34,"role":"noun","word":"water","start":29}]},{"en":"I'll call you if I arrive early.","vi":"Tôi sẽ gọi nếu đến sớm.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"I'll","start":0},{"end":9,"role":"modal","word":"call","start":5},{"end":13,"role":"verb","word":"you","start":10},{"end":16,"role":"pronoun","word":"if","start":14},{"end":18,"role":"conjunction","word":"I","start":17},{"end":25,"role":"pronoun","word":"arrive","start":19},{"end":31,"role":"verb","word":"early","start":26}]},{"en":"Unless you hurry, you'll miss the bus.","vi":"Nếu không nhanh lên, bạn sẽ lỡ xe buýt.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"conjunction","word":"Unless","start":0},{"end":10,"role":"pronoun","word":"you","start":7},{"end":16,"role":"verb","word":"hurry","start":11},{"end":24,"role":"pronoun","word":"you'll","start":18},{"end":29,"role":"modal","word":"miss","start":25},{"end":33,"role":"verb","word":"the","start":30},{"end":37,"role":"article","word":"bus","start":34}]},{"en":"If she studies, she may pass.","vi":"Nếu học, cô ấy có thể đỗ.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":6,"role":"pronoun","word":"she","start":3},{"end":14,"role":"verb","word":"studies","start":7},{"end":19,"role":"pronoun","word":"she","start":16},{"end":23,"role":"modal","word":"may","start":20},{"end":28,"role":"verb","word":"pass","start":24}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **If + present, present (loại 0)** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"If + present, present (loại 0)","example":"If you heat ice, it melts."},{"case":"Kiểm tra thành phần theo sau","rule":"If + present, will + V (loại 1)","example":"If it rains, we'll stay home."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Unless + present, will + V","example":"Plants die if they don't get water."}],"usage":[{"en":"If you heat ice, it melts.","vi":"Nếu bạn đun nóng đá, nó sẽ tan chảy.","icon":"🧊","label":"Loại 0 — chân lý, quy luật tự nhiên luôn đúng"},{"en":"Plants die if they don't get water.","vi":"Cây sẽ chết nếu không được tưới nước.","icon":"🌱","label":"Loại 0 — kết quả tất yếu lặp đi lặp lại"},{"en":"If it rains, we'll stay home.","vi":"Nếu trời mưa, chúng tôi sẽ ở nhà.","icon":"🌧️","label":"Loại 1 — điều kiện có thật ở tương lai"},{"en":"I'll call you if I arrive early.","vi":"Tôi sẽ gọi cho bạn nếu tôi đến sớm.","icon":"🤝","label":"Loại 1 — lời hứa, đề nghị kèm điều kiện"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"If + present, present (loại 0)","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"If + present, will + V (loại 1)","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Unless + present, will + V","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["if","unless","when","as soon as","will"],"examples":[{"en":"If you heat ice, it melts.","vi":"Nếu bạn làm nóng băng, nó tan.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":6,"role":"pronoun","word":"you","start":3},{"end":11,"role":"verb","word":"heat","start":7},{"end":15,"role":"noun","word":"ice","start":12},{"end":19,"role":"pronoun","word":"it","start":17},{"end":25,"role":"verb","word":"melts","start":20}]},{"en":"If it rains, we'll stay home.","vi":"Nếu trời mưa, chúng tôi sẽ ở nhà.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":5,"role":"pronoun","word":"it","start":3},{"end":11,"role":"verb","word":"rains","start":6},{"end":18,"role":"modal","word":"we'll","start":13},{"end":23,"role":"verb","word":"stay","start":19},{"end":28,"role":"noun","word":"home","start":24}]},{"en":"Plants die if they don't get water.","vi":"Cây chết nếu không có nước.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"noun","word":"Plants","start":0},{"end":10,"role":"verb","word":"die","start":7},{"end":13,"role":"conjunction","word":"if","start":11},{"end":18,"role":"pronoun","word":"they","start":14},{"end":24,"role":"auxiliary","word":"don't","start":19},{"end":28,"role":"verb","word":"get","start":25},{"end":34,"role":"noun","word":"water","start":29}]},{"en":"I'll call you if I arrive early.","vi":"Tôi sẽ gọi nếu đến sớm.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"I'll","start":0},{"end":9,"role":"modal","word":"call","start":5},{"end":13,"role":"verb","word":"you","start":10},{"end":16,"role":"pronoun","word":"if","start":14},{"end":18,"role":"conjunction","word":"I","start":17},{"end":25,"role":"pronoun","word":"arrive","start":19},{"end":31,"role":"verb","word":"early","start":26}]},{"en":"Unless you hurry, you'll miss the bus.","vi":"Nếu không nhanh lên, bạn sẽ lỡ xe buýt.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"conjunction","word":"Unless","start":0},{"end":10,"role":"pronoun","word":"you","start":7},{"end":16,"role":"verb","word":"hurry","start":11},{"end":24,"role":"pronoun","word":"you'll","start":18},{"end":29,"role":"modal","word":"miss","start":25},{"end":33,"role":"verb","word":"the","start":30},{"end":37,"role":"article","word":"bus","start":34}]},{"en":"If she studies, she may pass.","vi":"Nếu học, cô ấy có thể đỗ.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":6,"role":"pronoun","word":"she","start":3},{"end":14,"role":"verb","word":"studies","start":7},{"end":19,"role":"pronoun","word":"she","start":16},{"end":23,"role":"modal","word":"may","start":20},{"end":28,"role":"verb","word":"pass","start":24}]}],"mistakes":[{"wrong":"If it will rain, I will stay home.","right":"If it rains, I will stay home.","why":"Mệnh đề if không dùng will — dùng hiện tại đơn."},{"wrong":"If you heat ice, it melt.","right":"If you heat ice, it melts.","why":"Loại 0 dùng hiện tại đơn cả hai vế — ngôi 3 thêm -s."},{"wrong":"If I have time, I visit you.","right":"If I have time, I will visit you.","why":"Loại 1 vế kết quả cần WILL cho dự định tương lai."},{"wrong":"Unless you don't hurry, you will be late.","right":"Unless you hurry, you will be late.","why":"Unless đã mang nghĩa phủ định — không thêm don't."}],"timeline":{"points":[{"note":"luôn luôn, mọi lúc","label":"Loại 0: rain → wet"},{"note":"một khả năng tương lai","label":"Loại 1: rain tomorrow? → will stay home"}],"caption":"Loại 0 = vòng lặp luôn đúng (mọi lần mưa → ướt). Loại 1 = một nhánh tương lai (NẾU mai mưa → sẽ ở nhà)."},"comparison":"**Điều kiện loại 1 vs loại 0:** Loại 1 = khả năng CỤ THỂ trong tương lai (*If you are late, I will be angry* — có thể xảy ra). Loại 0 = chân lý / quy luật luôn đúng, không dùng will (*If you mix blue and yellow, you get green* — sự thật).","definition":"Zero & First Conditional dùng **điều kiện loại 0 và loại 1** cho sự thật luôn đúng và khả năng thực tế trong tương lai. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"Choose the correct **zero conditional** sentence.","options":["If water reaches 100°C, it boils.","If water reaches 100°C, it will boils.","If water will reach 100°C, it boils.","If water reach 100°C, it boil."],"correct_answer":"If water reaches 100°C, it boils.","explanation":"Câu điều kiện loại 0 dùng If + hiện tại đơn, hiện tại đơn để nói sự thật chung. Các đáp án khác sai vì dùng “will” trong mệnh đề if hoặc chia sai động từ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **first conditional** sentence.","options":["If I finish work early, I will cook dinner.","If I will finish work early, I cook dinner.","If I finished work early, I will cook dinner.","If I finish work early, I cooked dinner."],"correct_answer":"If I finish work early, I will cook dinner.","explanation":"Câu điều kiện loại 1 dùng If + hiện tại đơn, will + V cho khả năng thật trong tương lai. Không dùng “will” ngay sau “if”, và không dùng quá khứ ở đây.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **if-clause** form.","options":["If she studies tonight, she will understand the lesson.","If she will study tonight, she will understand the lesson.","If she studies tonight, she understands yesterday.","If she study tonight, she will understand the lesson."],"correct_answer":"If she studies tonight, she will understand the lesson.","explanation":"Sau “if” trong câu điều kiện loại 1 dùng hiện tại đơn: “she studies”. Các lựa chọn khác sai vì dùng “will” sau if, sai thì, hoặc thiếu -s với chủ ngữ “she”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **meaning** of the sentence: If you press this button, the machine starts.","options":["This is a general result.","This is an unreal dream.","This happened only yesterday.","This must use past tense."],"correct_answer":"This is a general result.","explanation":"Câu này là điều kiện loại 0: khi điều kiện xảy ra thì kết quả thường luôn đúng. Nó không nói về mơ ước không thật, quá khứ, hay bắt buộc dùng thì quá khứ.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **unless** sentence.","options":["Unless you hurry, you will miss the bus.","Unless you will hurry, you miss the bus.","Unless you hurry, you missed the bus.","Unless you hurries, you will miss the bus."],"correct_answer":"Unless you hurry, you will miss the bus.","explanation":"“Unless” nghĩa là “if not” và thường dùng cấu trúc Unless + hiện tại đơn, will + V. Các câu còn lại sai vì dùng “will” sau unless, sai thì, hoặc chia sai động từ.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **main clause**.","options":["If Dad comes home late, we will eat first.","If Dad comes home late, we eat yesterday.","If Dad comes home late, we will eats first.","If Dad comes home late, we eating first."],"correct_answer":"If Dad comes home late, we will eat first.","explanation":"Mệnh đề chính của câu điều kiện loại 1 dùng “will + động từ nguyên mẫu”. “Will eats”, “eating”, và “eat yesterday” đều không đúng trong ngữ cảnh này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **word order**.","options":["I will text you if the meeting ends early.","I will if text you the meeting ends early.","If will the meeting ends early, I text you.","The meeting if ends early I will text you."],"correct_answer":"I will text you if the meeting ends early.","explanation":"Mệnh đề if có thể đứng sau mệnh đề chính: will + V + if + hiện tại đơn. Các lựa chọn khác sai trật tự từ nên không tự nhiên hoặc sai ngữ pháp.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **habit result** sentence.","options":["If my phone battery is low, I charge it.","If my phone battery will be low, I charge it.","If my phone battery is low, I will charged it.","If my phone battery low, I charges it."],"correct_answer":"If my phone battery is low, I charge it.","explanation":"Câu này nói thói quen/kết quả thường xảy ra nên dùng điều kiện loại 0. Các đáp án khác sai vì dùng “will” trong mệnh đề if hoặc chia sai động từ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **future result** sentence.","options":["If the shop is open, we will buy milk.","If the shop will be open, we buy milk.","If the shop is open, we bought milk.","If the shop open, we will buys milk."],"correct_answer":"If the shop is open, we will buy milk.","explanation":"Đây là khả năng thật trong tương lai nên dùng If + hiện tại đơn, will + V. Các lựa chọn khác sai vì dùng “will” sau if, sai thì, hoặc chia sai động từ.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **verb form**: If salt mixes with water, it ___ .","options":["dissolves","will dissolves","dissolve","dissolved"],"correct_answer":"dissolves","explanation":"Đây là sự thật chung nên dùng hiện tại đơn ở cả hai mệnh đề. “It” cần động từ thêm -s: “dissolves”; các lựa chọn còn lại sai dạng hoặc sai thì.","difficulty":1},{"type":"fill_blank","question":"Complete the **first conditional**: If you call me, I ___ you the address.","options":["will send","send","sent","will sends"],"correct_answer":"will send","explanation":"Câu điều kiện loại 1 dùng mệnh đề chính “will + V”. “Send” là hiện tại đơn, “sent” là quá khứ, còn “will sends” sai vì sau will dùng động từ nguyên mẫu.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **if-clause**: I will wait here if the train ___ late.","options":["is","will be","be","was"],"correct_answer":"is","explanation":"Sau “if” trong câu điều kiện loại 1 dùng hiện tại đơn, nên chọn “is”. “Will be” không dùng sau if; “be” và “was” sai dạng trong câu này.","difficulty":1},{"type":"fill_blank","question":"Complete the **zero conditional**: When people eat too much sugar, they often ___ tired later.","options":["feel","will feel","feels","felt"],"correct_answer":"feel","explanation":"Với sự thật/thói quen chung, dùng hiện tại đơn: “people feel”. “Feels” sai hòa hợp chủ ngữ, còn “will feel” và “felt” không phù hợp với loại 0 ở đây.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **unless form**: Unless he leaves now, he ___ on time.","options":["will not arrive","does not arrive","will not arrives","did not arrive"],"correct_answer":"will not arrive","explanation":"“Unless + hiện tại đơn” đi với kết quả tương lai “will + V”. Các đáp án khác sai vì không diễn đạt kết quả tương lai đúng hoặc chia sai sau “will”.","difficulty":2},{"type":"fill_blank","question":"Complete the **future result**: If we save enough money, we ___ a new laptop.","options":["will buy","buy","bought","will bought"],"correct_answer":"will buy","explanation":"Đây là điều kiện có thể xảy ra trong tương lai nên mệnh đề chính dùng “will buy”. “Buy” là hiện tại đơn, “bought” là quá khứ, và “will bought” sai cấu trúc.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **present simple** form: If a child ___ hungry, he cries.","options":["is","will be","are","was"],"correct_answer":"is","explanation":"Câu điều kiện loại 0 dùng hiện tại đơn để nói kết quả thường đúng. “A child” là số ít nên dùng “is”; các đáp án khác sai thì hoặc sai hòa hợp.","difficulty":1},{"type":"fill_blank","question":"Complete the **negative condition**: If you do not wear a coat, you ___ cold.","options":["will feel","feel","felt","will felt"],"correct_answer":"will feel","explanation":"Câu này nói khả năng trong tương lai nên dùng “will + V” ở mệnh đề chính. “Feel” là hiện tại đơn, “felt” là quá khứ, còn “will felt” sai vì sau will phải là động từ nguyên mẫu.","difficulty":2},{"type":"error_correction","question":"Find the error: If she will arrive early, we will start the game.","options":["If","she will arrive","we will start","the game"],"correct_answer":"she will arrive","explanation":"Sau “if” trong câu điều kiện loại 1 không dùng “will”; phải nói “If she arrives early”. Các phần còn lại đúng trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: If water freeze, it becomes ice.","options":["If","water freeze","it becomes","ice"],"correct_answer":"water freeze","explanation":"“Water” là danh từ không đếm được số ít nên hiện tại đơn cần “freezes”. Các phần khác đúng cho câu điều kiện loại 0.","difficulty":1},{"type":"error_correction","question":"Find the error: If you touch fire, you will gets hurt.","options":["If you touch","fire","you will gets","hurt"],"correct_answer":"you will gets","explanation":"Sau “will” phải dùng động từ nguyên mẫu: “will get”. “If you touch fire” đúng vì mệnh đề if dùng hiện tại đơn.","difficulty":1},{"type":"error_correction","question":"Find the error: Unless it will stop soon, we will cancel the picnic.","options":["Unless","it will stop","soon","we will cancel"],"correct_answer":"it will stop","explanation":"Sau “unless” dùng hiện tại đơn, không dùng “will”: “Unless it stops soon”. Mệnh đề chính “we will cancel” đúng cho kết quả tương lai.","difficulty":2},{"type":"error_correction","question":"Find the error: If I am late tomorrow, I call you.","options":["If I am","late tomorrow","I call","you"],"correct_answer":"I call","explanation":"Vì có “tomorrow”, đây là khả năng tương lai nên mệnh đề chính cần “I will call”. “If I am” dùng hiện tại đơn sau if là đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: If the baby sleeps, please you turn off the TV.","options":["If the baby sleeps","please you turn","off","the TV"],"correct_answer":"please you turn","explanation":"Mệnh lệnh lịch sự dùng “please turn off”, không nói “please you turn”. Mệnh đề if dùng hiện tại đơn đúng cho tình huống thực tế.","difficulty":3},{"type":"error_correction","question":"Find the error: If he does not drinks water, he will feel weak.","options":["If","he does not drinks","water","he will feel"],"correct_answer":"he does not drinks","explanation":"Trong phủ định hiện tại đơn với “does not”, động từ chính phải ở dạng nguyên mẫu: “does not drink”. Mệnh đề chính “he will feel” đúng cho kết quả tương lai.","difficulty":2},{"type":"error_correction","question":"Find the error: If the class finishes early, we go to the cafe later today.","options":["If the class finishes","early","we go","later today"],"correct_answer":"we go","explanation":"“Later today” cho thấy kết quả tương lai cụ thể, nên dùng “we will go”. Mệnh đề if dùng hiện tại đơn “finishes” là đúng.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **meaning**: If water reaches 100°C, it boils.","options":["a general fact","an unreal dream","a past event","a future plan only"],"correct_answer":"a general fact","explanation":"Đây là câu điều kiện loại 0: if + hiện tại đơn, hiện tại đơn, dùng cho sự thật luôn đúng. Các lựa chọn khác sai vì câu không nói về mơ ước, quá khứ hay chỉ một kế hoạch tương lai.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **future condition** sentence.","options":["If we leave now, we will catch the bus.","If we will leave now, we catch the bus.","If we leave now, we catches the bus.","If we left now, we will catch the bus."],"correct_answer":"If we leave now, we will catch the bus.","explanation":"Câu đúng dùng loại 1: If + hiện tại đơn, will + V. Không dùng will trong mệnh đề if; “catches” sai sau will, và “left” không phù hợp với loại 1 cơ bản.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **zero conditional** sentence for a school rule.","options":["If students are late, the teacher marks them absent.","If students will be late, the teacher marks them absent.","If students are late, the teacher will marked them absent.","If students late, the teacher marks them absent."],"correct_answer":"If students are late, the teacher marks them absent.","explanation":"Quy tắc chung dùng loại 0: hiện tại đơn ở cả hai mệnh đề. Các câu còn lại sai vì dùng “will” trong if-clause, sai dạng “marked”, hoặc thiếu động từ “are”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **comma** placement.","options":["If you finish the quiz, I will check it.","If you finish, the quiz I will check it.","If, you finish the quiz I will check it.","If you finish the quiz I, will check it."],"correct_answer":"If you finish the quiz, I will check it.","explanation":"Khi mệnh đề if đứng đầu câu, thường đặt dấu phẩy sau mệnh đề đó. Các lựa chọn khác đặt dấu phẩy sai vị trí nên làm câu khó hiểu.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **unless** meaning: Unless you hurry, you will miss the bus.","options":["If you do not hurry, you will miss the bus.","If you hurry, you will miss the bus.","Because you hurry, you will miss the bus.","When you missed the bus, hurry."],"correct_answer":"If you do not hurry, you will miss the bus.","explanation":"“Unless” nghĩa là “if not”, nên câu tương đương là “If you do not hurry…”. Các lựa chọn khác đảo nghĩa, dùng lý do sai, hoặc sai ngữ pháp.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **main clause**: If Anna feels better tomorrow, ___","options":["she will come to class.","she comes to class yesterday.","she will comes to class.","she coming to class."],"correct_answer":"she will come to class.","explanation":"Với điều kiện có thể xảy ra trong tương lai, mệnh đề chính dùng “will + động từ nguyên mẫu”. “Comes” sau will, “yesterday”, và “coming” đều sai trong cấu trúc này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **if position** sentence.","options":["I will text you if the meeting ends early.","I will text you if the meeting will end early.","I text you will if the meeting ends early.","I will text you if ends early the meeting."],"correct_answer":"I will text you if the meeting ends early.","explanation":"Khi if-clause đứng sau, không cần dấu phẩy và vẫn dùng hiện tại đơn sau “if”. Các lựa chọn khác sai vì dùng “will” trong if-clause hoặc sai trật tự từ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **real possibility** sentence.","options":["If Dad works late, we will eat without him.","If Dad will work late, we eat without him.","If Dad works late, we eating without him.","If Dad worked late, we will ate without him."],"correct_answer":"If Dad works late, we will eat without him.","explanation":"Đây là khả năng thực tế trong tương lai, nên dùng If + hiện tại đơn, will + V. Các câu khác sai vì dùng “will” trong if-clause, thiếu “will + V”, hoặc sai dạng động từ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **general result** sentence.","options":["If phones lose battery, they turn off.","If phones will lose battery, they turn off.","If phones lose battery, they will turned off.","If phones loses battery, they turn off."],"correct_answer":"If phones lose battery, they turn off.","explanation":"Sự thật chung dùng loại 0 với hiện tại đơn ở cả hai mệnh đề. “Will” trong if-clause, “will turned”, và “phones loses” đều sai ngữ pháp.","difficulty":2},{"type":"fill_blank","question":"Complete the **zero conditional**: If milk stays outside for too long, it ___ bad.","options":["goes","will go","going","go"],"correct_answer":"goes","explanation":"Chủ ngữ “it” ở hiện tại đơn cần động từ thêm -s: “goes”. “Will go” là loại 1, “going” thiếu trợ động từ, và “go” không hòa hợp với “it”.","difficulty":1},{"type":"fill_blank","question":"Complete the **first conditional**: If I find your keys, I ___ you.","options":["will call","call","called","will calls"],"correct_answer":"will call","explanation":"Kết quả tương lai dùng “will + động từ nguyên mẫu”. “Call” thiếu will trong ngữ cảnh tương lai, “called” là quá khứ, và “will calls” sai vì sau will dùng động từ nguyên mẫu.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **if-clause** verb: I will open the window if the room ___ hot.","options":["gets","will get","get","getting"],"correct_answer":"gets","explanation":"Sau “if” trong câu điều kiện loại 1 dùng hiện tại đơn, nên “the room gets” là đúng. Không dùng “will get” trong if-clause; “get” sai hòa hợp, còn “getting” thiếu trợ động từ.","difficulty":1},{"type":"fill_blank","question":"Complete the **zero conditional**: If you add sugar to tea, it ___ sweeter.","options":["tastes","will taste","taste","tasted"],"correct_answer":"tastes","explanation":"Đây là kết quả chung, nên dùng hiện tại đơn: “it tastes”. “Will taste” nói về tương lai cụ thể, “taste” sai với “it”, và “tasted” là quá khứ.","difficulty":1},{"type":"fill_blank","question":"Complete the **unless clause**: Unless Mia studies tonight, she ___ ready for the test.","options":["will not be","is not","was not","will not is"],"correct_answer":"will not be","explanation":"“Unless + hiện tại đơn” đi với kết quả tương lai “will + V”. “Is not” là hiện tại đơn, “was not” là quá khứ, và “will not is” sai vì sau will dùng “be”.","difficulty":2},{"type":"fill_blank","question":"Choose the correct **present simple** form: If a dog ___ a stranger, it often barks.","options":["sees","will see","see","saw"],"correct_answer":"sees","explanation":"Loại 0 dùng hiện tại đơn; với chủ ngữ “a dog”, động từ là “sees”. “Will see” không dùng cho sự thật chung, “see” sai hòa hợp, và “saw” là quá khứ.","difficulty":1},{"type":"fill_blank","question":"Complete the **future result**: If the restaurant is full, we ___ another place.","options":["will try","try","tried","will trying"],"correct_answer":"will try","explanation":"Kết quả có thể xảy ra trong tương lai dùng “will + V”. “Try” thiếu will trong ý tương lai, “tried” là quá khứ, và “will trying” sai dạng động từ.","difficulty":1},{"type":"fill_blank","question":"Complete the **negative condition**: If you don't charge your phone, it ___ work later.","options":["will not","does not","did not","will not to"],"correct_answer":"will not","explanation":"Trong loại 1, kết quả tương lai phủ định là “will not + V”. “Does not” là hiện tại đơn, “did not” là quá khứ, và “will not to” sai vì sau will không dùng “to”.","difficulty":2},{"type":"error_correction","question":"Find the error: If the sun goes down, it will gets dark soon.","options":["If","goes down","will gets","soon"],"correct_answer":"will gets","explanation":"Sau “will” phải dùng động từ nguyên mẫu, nên phải là “will get”. Các phần còn lại đúng trong câu điều kiện loại 1.","difficulty":1},{"type":"error_correction","question":"Find the error: If coffee is too hot, I wait five minutes.","options":["If","is","too hot","wait"],"correct_answer":"wait","explanation":"Nếu nói về một lần có thể xảy ra trong tương lai, mệnh đề chính nên là “will wait”. Các phần khác đúng: if + hiện tại đơn và tính từ sau “is”.","difficulty":2},{"type":"error_correction","question":"Find the error: If you will need help, ask your teacher.","options":["If","will need","help","ask"],"correct_answer":"will need","explanation":"Trong mệnh đề if của loại 1, không dùng “will”; câu đúng là “If you need help…”. Các phần khác phù hợp với lời khuyên hoặc mệnh lệnh.","difficulty":1},{"type":"error_correction","question":"Find the error: If my sister miss the bus, she will walk home.","options":["If","miss","will walk","home"],"correct_answer":"miss","explanation":"Chủ ngữ “my sister” là ngôi thứ ba số ít nên hiện tại đơn phải là “misses”. “Will walk” đúng cho kết quả tương lai.","difficulty":1},{"type":"error_correction","question":"Find the error: Unless the store opens soon, we will waits outside.","options":["Unless","opens","will waits","outside"],"correct_answer":"will waits","explanation":"Sau “will” dùng động từ nguyên mẫu, nên phải là “will wait”. “Unless + hiện tại đơn” với “opens” là đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: If you mix yellow and blue, you will get green.","options":["If","mix","will get","green"],"correct_answer":"will get","explanation":"Đây là sự thật chung, nên dùng loại 0: “you get green”. “Will get” biến câu thành kết quả tương lai cụ thể, không phù hợp với ý quy luật chung.","difficulty":2},{"type":"error_correction","question":"Find the error: I will buy some fruit if the market will be open.","options":["will buy","fruit","if","will be"],"correct_answer":"will be","explanation":"Sau “if” trong loại 1 dùng hiện tại đơn, nên phải là “is open”. “Will buy” đúng ở mệnh đề chính vì nói về kết quả tương lai.","difficulty":2},{"type":"error_correction","question":"Find the error: When water gets cold enough, it turn into ice.","options":["When","gets","turn","ice"],"correct_answer":"turn","explanation":"Chủ ngữ “it” cần động từ hiện tại đơn thêm -s: “turns”. “When” có thể dùng như “if” cho sự thật chung, và các phần khác đúng.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **general fact** sentence.","options":["If people eat too much sugar, they often feel tired.","If people will eat too much sugar, they often feel tired.","If people eat too much sugar, they will often feels tired.","If people eats too much sugar, they often feel tired."],"correct_answer":"If people eat too much sugar, they often feel tired.","explanation":"Đây là sự thật chung nên dùng điều kiện loại 0: If + hiện tại đơn, hiện tại đơn. People là số nhiều nên dùng eat, feel; không dùng will trong mệnh đề if.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **order** sentence.","options":["I will text you if the meeting ends early.","I text you if the meeting will end early.","I will text you if the meeting will ends early.","I will texts you if the meeting ends early."],"correct_answer":"I will text you if the meeting ends early.","explanation":"Mệnh đề if có thể đứng sau mệnh đề chính và không cần dấu phẩy. Trong mệnh đề if vẫn dùng hiện tại đơn ends, còn mệnh đề chính dùng will text.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **negative condition** sentence.","options":["If you don't save the file, you will lose your work.","If you won't save the file, you lose your work.","If you don't save the file, you will loses your work.","If you doesn't save the file, you will lose your work."],"correct_answer":"If you don't save the file, you will lose your work.","explanation":"Điều kiện tương lai dùng hiện tại đơn ở mệnh đề if: don't save. Sau will dùng động từ nguyên mẫu lose; you không đi với doesn't.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **request condition** sentence.","options":["If you finish the report, please send it to me.","If you will finish the report, please send it to me.","If you finish the report, please sends it to me.","If you finishes the report, please send it to me."],"correct_answer":"If you finish the report, please send it to me.","explanation":"Trong câu điều kiện dùng để nhờ/yêu cầu, mệnh đề if vẫn dùng hiện tại đơn. Please + động từ nguyên mẫu là send, không phải sends; you đi với finish.","difficulty":2},{"type":"fill_blank","question":"Complete the **zero conditional**: If metal gets very hot, it ___ larger.","options":["becomes","will become","become","became"],"correct_answer":"becomes","explanation":"Đây là sự thật khoa học nên dùng hiện tại đơn ở mệnh đề kết quả. Metal là số ít nên động từ phải thêm -s: becomes; will become là loại 1, còn become/became sai dạng.","difficulty":1},{"type":"fill_blank","question":"Complete the **first conditional**: If Dad comes home early, we ___ dinner together.","options":["will have","have","has","had"],"correct_answer":"will have","explanation":"Câu nói về khả năng thật trong tương lai nên dùng will + V ở mệnh đề chính. Have là hiện tại đơn, has sai chủ ngữ we, còn had là quá khứ.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **if-clause** verb: We will go swimming if the weather ___ warm.","options":["is","will be","are","be"],"correct_answer":"is","explanation":"Trong câu điều kiện loại 1, mệnh đề if dùng hiện tại đơn, không dùng will. Weather là danh từ số ít/không đếm được nên dùng is, không dùng are hoặc be.","difficulty":1},{"type":"fill_blank","question":"Complete the **unless condition**: Unless the alarm rings, I ___ wake up early.","options":["won't","don't","am not","didn't"],"correct_answer":"won't","explanation":"Unless the alarm rings nghĩa là nếu chuông không reo; kết quả tương lai cần won't + V. Don't/am not/didn't không phù hợp với ý tương lai trong câu này.","difficulty":2},{"type":"fill_blank","question":"Complete the **general truth**: If children don't sleep enough, they ___ tired.","options":["feel","will feels","feels","felt"],"correct_answer":"feel","explanation":"Đây là sự thật chung nên dùng hiện tại đơn ở mệnh đề kết quả. Children là số nhiều nên dùng feel; feels sai chủ ngữ, felt là quá khứ, will feels sai vì sau will phải là động từ nguyên mẫu.","difficulty":1},{"type":"fill_blank","question":"Complete the **future plan**: If I see Lan at school, I ___ her your message.","options":["will give","give","gave","will gives"],"correct_answer":"will give","explanation":"Câu nói về việc có thể xảy ra trong tương lai nên dùng will give ở mệnh đề chính. Give là hiện tại đơn, gave là quá khứ, và will gives sai vì sau will không thêm -s.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **present simple** form: If this app ___ slowly, restart your phone.","options":["runs","will run","run","running"],"correct_answer":"runs","explanation":"Mệnh đề if trong câu chỉ lời khuyên dùng hiện tại đơn. This app là số ít nên dùng runs; không dùng will run, run hoặc running trong cấu trúc này.","difficulty":2},{"type":"fill_blank","question":"Complete the **real possibility**: If they invite us, we ___ to the party.","options":["will go","go","went","goes"],"correct_answer":"will go","explanation":"Đây là khả năng thật trong tương lai nên mệnh đề chính dùng will + V. Go ở hiện tại đơn không nêu rõ kết quả tương lai trong cấu trúc loại 1; went và goes sai thì/dạng.","difficulty":1},{"type":"fill_blank","question":"Complete the **zero conditional**: If you freeze water, it ___ ice.","options":["becomes","will become","become","is becoming"],"correct_answer":"becomes","explanation":"Đây là sự thật luôn đúng nên dùng điều kiện loại 0: hiện tại đơn, hiện tại đơn. It là số ít nên dùng becomes; các lựa chọn khác sai thì hoặc sai dạng.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If you will visit Grandma tomorrow, bring these photos.","options":["will visit","tomorrow","bring","these photos"],"correct_answer":"will visit","explanation":"Trong mệnh đề if của điều kiện loại 1 không dùng will; cần sửa thành visit. Các phần còn lại đúng trong câu: tomorrow chỉ thời gian tương lai, bring là mệnh lệnh đúng, these photos là tân ngữ đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If the door is locked, you will needs a key.","options":["the door","is locked","will needs","a key"],"correct_answer":"will needs","explanation":"Sau will phải dùng động từ nguyên mẫu, nên sửa will needs thành will need. The door, is locked và a key đều đúng trong ngữ cảnh này.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: Unless Jack calls, we don't leave soon.","options":["Unless","Jack calls","don't leave","soon"],"correct_answer":"don't leave","explanation":"Câu nói về kết quả tương lai nên cần won't leave, không phải don't leave. Unless và Jack calls đúng vì mệnh đề điều kiện dùng hiện tại đơn; soon là trạng từ thời gian phù hợp.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If eggs are fresh, they will sink in water.","options":["eggs","are fresh","will sink","in water"],"correct_answer":"will sink","explanation":"Câu này diễn tả một kết quả kiểm tra mang tính chung, nên dùng loại 0: they sink. Các phần eggs, are fresh và in water đều đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If Mark forgets his password, he reset it online.","options":["Mark","forgets","reset","online"],"correct_answer":"reset","explanation":"Với chủ ngữ he ở hiện tại đơn, động từ phải là resets nếu nói quy trình chung, hoặc will reset nếu nói tương lai. Mark, forgets và online không sai trong câu này.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If the shop closes before six, I won't bought bread.","options":["the shop","closes","won't bought","bread"],"correct_answer":"won't bought","explanation":"Sau won't phải dùng động từ nguyên mẫu, nên sửa thành won't buy. The shop là chủ ngữ đúng, closes đúng hiện tại đơn trong mệnh đề if, và bread là tân ngữ đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: I stay at home if it will snow tonight.","options":["stay","at home","will snow","tonight"],"correct_answer":"will snow","explanation":"Trong mệnh đề if của điều kiện loại 1 không dùng will, nên sửa thành snows. Stay at home có thể là mệnh đề chính hiện tại, nhưng để rõ ý tương lai thường nên nói will stay; lỗi ngữ pháp chính ở đây là will snow sau if.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If a student ask a question, the teacher answers it.","options":["a student","ask","the teacher","answers"],"correct_answer":"ask","explanation":"A student là số ít nên động từ hiện tại đơn phải là asks. The teacher answers it đúng vì teacher là số ít và đây là câu điều kiện loại 0.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **general rule** sentence.","options":["If you press the red button, the machine stops.","If you press the red button, the machine will stopped.","If you will press the red button, the machine stops.","If you presses the red button, the machine stops."],"correct_answer":"If you press the red button, the machine stops.","explanation":"Đây là quy tắc chung nên dùng câu điều kiện loại 0: hiện tại đơn ở cả hai mệnh đề. Các câu khác sai vì dùng sai dạng sau will, dùng will trong mệnh đề if, hoặc chia presses sai với you.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **sentence order**.","options":["The lights turn on if you open the door.","The lights will turns on if you open the door.","The lights turn on if you will open the door.","The lights turns on if you open the door."],"correct_answer":"The lights turn on if you open the door.","explanation":"Mệnh đề if có thể đứng sau mệnh đề chính; với sự thật/hoạt động thường đúng, dùng hiện tại đơn ở cả hai vế. Các câu sai vì will turns không đúng, dùng will trong mệnh đề if, hoặc chia turns sai với lights số nhiều.","difficulty":2},{"type":"fill_blank","question":"Complete the **zero conditional**: If bread gets wet, it ___ soft.","options":["becomes","will become","became","become"],"correct_answer":"becomes","explanation":"Đây là kết quả thường đúng nên dùng hiện tại đơn: it becomes. Will become dùng cho tương lai cụ thể, became là quá khứ, còn become thiếu -s với it.","difficulty":1},{"type":"fill_blank","question":"Complete the **first conditional**: If I finish work early, I ___ you a text.","options":["will send","send","sent","will sends"],"correct_answer":"will send","explanation":"Câu loại 1 nói khả năng trong tương lai: If + hiện tại đơn, will + V. Send là hiện tại đơn không diễn tả rõ kết quả tương lai ở đây, sent là quá khứ, will sends sai vì sau will dùng động từ nguyên mẫu.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **if-clause** verb: We will make tea if Mom ___ home soon.","options":["comes","will come","come","came"],"correct_answer":"comes","explanation":"Trong mệnh đề if của câu loại 1, dùng hiện tại đơn: Mom comes. Will come không dùng sau if trong cấu trúc này, come thiếu -s, came là quá khứ.","difficulty":1},{"type":"fill_blank","question":"Complete the **unless clause**: Unless Ben studies tonight, he ___ the quiz.","options":["will fail","fails","failed","will fails"],"correct_answer":"will fail","explanation":"Unless + hiện tại đơn diễn tả điều kiện; kết quả tương lai dùng will + V. Fails là hiện tại đơn không phù hợp bằng will fail trong kết quả tương lai, failed là quá khứ, will fails sai dạng động từ.","difficulty":2},{"type":"fill_blank","question":"Complete the **general fact**: If people eat too much salt, they ___ thirsty.","options":["get","will got","gets","got"],"correct_answer":"get","explanation":"Đây là sự thật chung nên dùng hiện tại đơn: people get. Gets sai vì people là số nhiều, got là quá khứ, will got sai vì sau will phải là get.","difficulty":1},{"type":"fill_blank","question":"Complete the **future condition**: I won't go outside if it ___ very windy.","options":["is","will be","was","be"],"correct_answer":"is","explanation":"Trong mệnh đề if của câu loại 1, dùng hiện tại đơn: it is. Will be không dùng trong mệnh đề if, was là quá khứ, be thiếu chủ ngữ/dạng chia phù hợp.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If the baby sleeps now, she will wakes up happy.","options":["sleeps","now","will wakes","happy"],"correct_answer":"will wakes","explanation":"Sau will phải dùng động từ nguyên mẫu: will wake. Sleeps đúng vì mệnh đề if dùng hiện tại đơn; now và happy không sai ngữ pháp trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If you touches this wire, it hurts.","options":["you","touches","this wire","hurts"],"correct_answer":"touches","explanation":"Với chủ ngữ you, động từ hiện tại đơn là touch, không thêm -es. It hurts đúng vì chủ ngữ it cần -s; các cụm còn lại không sai.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If Leo finds his keys, he call me.","options":["finds","his keys","call","me"],"correct_answer":"call","explanation":"Đây là kết quả tương lai nên cần he will call me. Finds đúng trong mệnh đề if; his keys và me không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: Unless the children are quiet, the movie won't starts.","options":["Unless","are quiet","won't starts","the movie"],"correct_answer":"won't starts","explanation":"Sau won't phải dùng động từ nguyên mẫu: won't start. Unless và are quiet đúng trong mệnh đề điều kiện; the movie là chủ ngữ hợp lý.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the **incorrect** word/phrase: If the soup boil, it makes bubbles.","options":["the soup","boil","makes","bubbles"],"correct_answer":"boil","explanation":"The soup là danh từ số ít nên hiện tại đơn phải là boils. Makes đúng vì chủ ngữ it là số ít; các cụm còn lại không sai.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct sentence for a **general truth** about colors.","options":["If you mix red and blue, you get purple.","If you will mix red and blue, you get purple.","If you mix red and blue, you will get purple.","If you mixed red and blue, you got purple."],"correct_answer":"If you mix red and blue, you get purple.","explanation":"Câu điều kiện loại 0 dùng thì hiện tại đơn ở cả hai mệnh đề để diễn tả một sự thật hiển nhiên hoặc một điều luôn đúng. Cấu trúc là \"If + S + V(hiện tại đơn), S + V(hiện tại đơn)\".","difficulty":1},{"type":"fill_blank","question":"Complete the sentence: If my brother **studies** hard, he ___ the exam easily.","options":["passes","will pass","passed","is passing"],"correct_answer":"will pass","explanation":"Đây là câu điều kiện loại 1, diễn tả một khả năng có thật trong tương lai. Mệnh đề If dùng thì hiện tại đơn (\"studies\"), còn mệnh đề chính dùng thì tương lai đơn (\"will + động từ nguyên mẫu\").","difficulty":1},{"type":"error_correction","question":"Find the **incorrect** word/phrase: If you **don't eats** breakfast, you feel hungry.","options":["don't eats","breakfast","feel","hungry"],"correct_answer":"don't eats","explanation":"Trong câu điều kiện loại 0, mệnh đề If dùng thì hiện tại đơn. Với chủ ngữ \"you\", động từ phủ định phải là \"don't eat\" (dạng nguyên mẫu), không phải \"don't eats\".","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **main clause** for the first conditional: If it rains tomorrow, ___.","options":["we stay home","we stayed home","we will stay home","we are staying home"],"correct_answer":"we will stay home","explanation":"Đây là câu điều kiện loại 1, diễn tả một khả năng có thể xảy ra trong tương lai. Mệnh đề If dùng thì hiện tại đơn (\"rains\"), và mệnh đề chính phải dùng thì tương lai đơn (\"will + động từ nguyên mẫu\").","difficulty":1}]$grammar$::jsonb, 'ai-golden', 28
from public.grammar_topics t where t.slug = 'conditionals-0-1'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 29. present-perfect
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('present-perfect', 'Present Perfect', 'Thì Hiện tại hoàn thành', 'intermediate', 29)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Hiện tại hoàn thành', 'Thì **Hiện tại hoàn thành** (Present Perfect) mô tả hành động **bắt đầu từ quá khứ** và **có liên quan đến hiện tại**. Hành động có thể đã hoàn thành hoặc vẫn tiếp tục. Đây là thì dùng để nối liền quá khứ với hiện tại.', $grammar$[{"en":"I have eaten breakfast.","vi":"Tôi đã ăn bữa sáng.","note":"Hành động đã hoàn thành","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"auxiliary"},{"word":"eaten","start":7,"end":12,"role":"verb"},{"word":"breakfast","start":13,"end":22,"role":"noun"}]},{"en":"She has been to the gym three times this week.","vi":"Cô ấy đã đến phòng tập thể dục ba lần trong tuần này.","note":"Hành động lặp lại","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"has","start":4,"end":7,"role":"auxiliary"},{"word":"been","start":8,"end":12,"role":"auxiliary"},{"word":"to","start":13,"end":15,"role":"preposition"},{"word":"the","start":16,"end":19,"role":"article"},{"word":"gym","start":20,"end":23,"role":"noun"},{"word":"three","start":24,"end":29,"role":"other"},{"word":"times","start":30,"end":35,"role":"noun"},{"word":"this","start":36,"end":40,"role":"determiner"},{"word":"week","start":41,"end":45,"role":"noun"}]},{"en":"They haven't seen that movie yet.","vi":"Họ chưa xem bộ phim đó.","note":"Hành động chưa xảy ra","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"haven't","start":5,"end":12,"role":"auxiliary"},{"word":"seen","start":13,"end":17,"role":"verb"},{"word":"that","start":18,"end":22,"role":"determiner"},{"word":"movie","start":23,"end":28,"role":"noun"},{"word":"yet","start":29,"end":32,"role":"adverb"}]},{"en":"He has never traveled by plane.","vi":"Anh ấy chưa bao giờ đi máy bay.","note":"Hành động chưa bao giờ xảy ra","annotations":[{"word":"He","start":0,"end":2,"role":"pronoun"},{"word":"has","start":3,"end":6,"role":"auxiliary"},{"word":"never","start":7,"end":12,"role":"adverb"},{"word":"traveled","start":13,"end":21,"role":"verb"},{"word":"by","start":22,"end":24,"role":"preposition"},{"word":"plane","start":25,"end":30,"role":"noun"}]},{"en":"What have you done today?","vi":"Bạn đã làm gì hôm nay?","note":"Câu hỏi về hành động đã xảy ra","annotations":[{"word":"What","start":0,"end":4,"role":"adverb"},{"word":"have","start":5,"end":9,"role":"auxiliary"},{"word":"you","start":10,"end":13,"role":"pronoun"},{"word":"done","start":14,"end":18,"role":"verb"},{"word":"today","start":19,"end":24,"role":"adverb"}]},{"en":"I have been studying English for five years.","vi":"Tôi đã học tiếng Anh được năm năm.","note":"Hành động bắt đầu từ quá khứ và vẫn tiếp tục","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"auxiliary"},{"word":"been","start":7,"end":11,"role":"auxiliary"},{"word":"studying","start":12,"end":20,"role":"verb"},{"word":"English","start":21,"end":28,"role":"noun"},{"word":"for","start":29,"end":32,"role":"preposition"},{"word":"five","start":33,"end":37,"role":"other"},{"word":"years","start":38,"end":43,"role":"noun"}]}]$grammar$::jsonb, $grammar${"definition":"Thì **Hiện tại hoàn thành** (Present Perfect) mô tả hành động **bắt đầu từ quá khứ** và **có liên quan đến hiện tại**. Hành động có thể đã hoàn thành hoặc vẫn tiếp tục. Đây là thì dùng để nối liền quá khứ với hiện tại.","usage":[{"icon":"🕰️","label":"Hành động bắt đầu từ quá khứ và kéo dài đến hiện tại","en":"I have been studying English for three years.","vi":"Tôi đã học tiếng Anh được ba năm rồi."},{"icon":"📚","label":"Hành động đã hoàn thành gần đây","en":"She has just finished her homework.","vi":"Cô ấy vừa hoàn thành bài tập về nhà."},{"icon":"👥","label":"Hành động lặp lại nhiều lần từ quá khứ đến hiện tại","en":"They have visited Paris three times.","vi":"Họ đã đến thăm Paris ba lần."},{"icon":"📆","label":"Hành động xảy ra tại một thời điểm không xác định trong quá khứ","en":"I have never been to the USA.","vi":"Tôi chưa bao giờ đến Mỹ."}],"formula":{"rows":[{"form":"(+) Khẳng định","base":"S + have/has + V-en","note":"V-en là dạng quá khứ phân từ của động từ"},{"form":"(-) Phủ định","base":"S + haven't/hasn't + V-en","note":"Dùng haven't với I/you/we/they, hasn't với he/she/it"},{"form":"(?) Nghi vấn","base":"Have/Has + S + V-en?","note":"Dùng have với I/you/we/they, has với he/she/it"}],"note":"Quan tâm đến sự khác biệt giữa **have** và **has** cho chủ ngữ số ít (he/she/it) và số nhiều (I/you/we/they)."},"rules":[{"case":"Động từ thường","rule":"thêm -ed","example":"walk → walked"},{"case":"Động từ tận cùng bằng -e","rule":"thêm -d","example":"love → loved"},{"case":"Động từ có một âm tiết và tận cùng bằng một phụ âm đơn","rule":"lặp lại phụ âm và thêm -ed","example":"run → ran"},{"case":"Động từ có hai âm tiết và tận cùng bằng -y","rule":"thay y bằng i và thêm -ed","example":"study → studied"}],"signals":["already","just","yet","ever","never","since","for","recently"],"examples":[{"en":"I have eaten breakfast.","vi":"Tôi đã ăn bữa sáng.","note":"Hành động đã hoàn thành","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"auxiliary"},{"word":"eaten","start":7,"end":12,"role":"verb"},{"word":"breakfast","start":13,"end":22,"role":"noun"}]},{"en":"She has been to the gym three times this week.","vi":"Cô ấy đã đến phòng tập thể dục ba lần trong tuần này.","note":"Hành động lặp lại","annotations":[{"word":"She","start":0,"end":3,"role":"pronoun"},{"word":"has","start":4,"end":7,"role":"auxiliary"},{"word":"been","start":8,"end":12,"role":"auxiliary"},{"word":"to","start":13,"end":15,"role":"preposition"},{"word":"the","start":16,"end":19,"role":"article"},{"word":"gym","start":20,"end":23,"role":"noun"},{"word":"three","start":24,"end":29,"role":"other"},{"word":"times","start":30,"end":35,"role":"noun"},{"word":"this","start":36,"end":40,"role":"determiner"},{"word":"week","start":41,"end":45,"role":"noun"}]},{"en":"They haven't seen that movie yet.","vi":"Họ chưa xem bộ phim đó.","note":"Hành động chưa xảy ra","annotations":[{"word":"They","start":0,"end":4,"role":"pronoun"},{"word":"haven't","start":5,"end":12,"role":"auxiliary"},{"word":"seen","start":13,"end":17,"role":"verb"},{"word":"that","start":18,"end":22,"role":"determiner"},{"word":"movie","start":23,"end":28,"role":"noun"},{"word":"yet","start":29,"end":32,"role":"adverb"}]},{"en":"He has never traveled by plane.","vi":"Anh ấy chưa bao giờ đi máy bay.","note":"Hành động chưa bao giờ xảy ra","annotations":[{"word":"He","start":0,"end":2,"role":"pronoun"},{"word":"has","start":3,"end":6,"role":"auxiliary"},{"word":"never","start":7,"end":12,"role":"adverb"},{"word":"traveled","start":13,"end":21,"role":"verb"},{"word":"by","start":22,"end":24,"role":"preposition"},{"word":"plane","start":25,"end":30,"role":"noun"}]},{"en":"What have you done today?","vi":"Bạn đã làm gì hôm nay?","note":"Câu hỏi về hành động đã xảy ra","annotations":[{"word":"What","start":0,"end":4,"role":"adverb"},{"word":"have","start":5,"end":9,"role":"auxiliary"},{"word":"you","start":10,"end":13,"role":"pronoun"},{"word":"done","start":14,"end":18,"role":"verb"},{"word":"today","start":19,"end":24,"role":"adverb"}]},{"en":"I have been studying English for five years.","vi":"Tôi đã học tiếng Anh được năm năm.","note":"Hành động bắt đầu từ quá khứ và vẫn tiếp tục","annotations":[{"word":"I","start":0,"end":1,"role":"pronoun"},{"word":"have","start":2,"end":6,"role":"auxiliary"},{"word":"been","start":7,"end":11,"role":"auxiliary"},{"word":"studying","start":12,"end":20,"role":"verb"},{"word":"English","start":21,"end":28,"role":"noun"},{"word":"for","start":29,"end":32,"role":"preposition"},{"word":"five","start":33,"end":37,"role":"other"},{"word":"years","start":38,"end":43,"role":"noun"}]}],"mistakes":[{"wrong":"I have go to school.","right":"I have gone to school.","why":"Sai dạng quá khứ phân từ"},{"wrong":"She hasn't eat breakfast.","right":"She hasn't eaten breakfast.","why":"Sai dạng quá khứ phân từ"},{"wrong":"They have went to the store.","right":"They have gone to the store.","why":"Sai dạng quá khứ phân từ"},{"wrong":"I have been to Paris last year.","right":"I went to Paris last year.","why":"Sai thì, nên dùng quá khứ đơn"},{"wrong":"Long ago dinosaurs have lived here.","right":"Long ago dinosaurs lived here.","why":"Sự kiện lịch sử đã kết thúc dùng quá khứ đơn, không dùng hiện tại hoàn thành."},{"wrong":"Who has invented the telephone?","right":"Who invented the telephone?","why":"Hỏi về một phát minh thuộc lịch sử đã hoàn tất dùng quá khứ đơn."}],"tips":"**Mẹo nhớ:** Hiện tại hoàn thành dùng để nối quá khứ với hiện tại. Cấu trúc: S + have/has + V-en.","comparison":"**Hiện tại hoàn thành vs Quá khứ đơn:** HTHT = khoảng thời gian CHƯA kết thúc, kéo dài tới hiện tại, KHÔNG đi với mốc thời gian rõ (*Tom has lost his key* — giờ vẫn chưa thấy). QKĐ = thời điểm ĐÃ kết thúc, có mốc cụ thể (*Tom lost his key yesterday* — chuyện hôm qua, xong rồi).","timeline":{"caption":"Ví dụ \"I have studied English for three years\" — hành động bắt đầu từ quá khứ và kéo dài đến hiện tại","points":[{"label":"Bắt đầu học tiếng Anh","note":"quá khứ"},{"label":"Tiếp tục học","note":"quá khứ → hiện tại"},{"label":"Vẫn tiếp tục học","note":"hiện tại"}]}}$grammar$::jsonb, $grammar$[{"type":"fill","q":"I ____ (already / finish) my exercise.","opts":[],"answer":"have already finished","fb":"already chèn giữa have và V3"},{"type":"fill","q":"Rashid ____ (just / pass) his driving test.","opts":[],"answer":"has just passed","fb":"just → hoàn thành (đứng giữa has và V3)"},{"type":"fill","q":"Nam and I ____ (be) pen pals for a long time.","opts":[],"answer":"have been","fb":"for + quãng → hoàn thành (be → been)"},{"type":"fill","q":"How long ____ they ____ (live) here? — Since 1990.","opts":[],"answer":"have … lived","fb":"How long + since → hiện tại hoàn thành"},{"type":"fill","q":"The teacher ____ (already / tell) us to be quiet.","opts":[],"answer":"has already told","fb":"already → hoàn thành (tell → told)"},{"type":"fill","q":"She ____ (not / see) him since Christmas.","opts":[],"answer":"hasn't seen","fb":"since + mốc → hoàn thành phủ định"},{"type":"fill","q":"____ you ____ (finish) your project yet?","opts":[],"answer":"Have … finished","fb":"yet trong câu hỏi → hiện tại hoàn thành"},{"type":"fill","q":"Karen ____ (study) Italian for three years and is still studying.","opts":[],"answer":"has studied","fb":"for + quãng, giờ vẫn học → hoàn thành"},{"type":"fill","q":"____ she ____ (visit) her grandma this Sunday? She has already bought a present.","opts":[],"answer":"Is … going to visit","fb":"đã mua quà sẵn = kế hoạch có từ trước → be going to"},{"type":"fill","q":"We ____ (live) in England for two years.","opts":[],"answer":"have lived","fb":"for → kéo dài tới giờ → hiện tại hoàn thành"},{"type":"fill","q":"The policeman ____ (not / stop) my father last Friday.","opts":[],"answer":"didn't stop","fb":"last Friday = mốc rõ → quá khứ; sau didn't để V trơ"},{"type":"fill","q":"How long ____ Bob and Mary ____ (be) married?","opts":[],"answer":"have … been","fb":"How long → hiện tại hoàn thành"},{"type":"fill","q":"She ____ (learn) German since 2022.","opts":[],"answer":"has learned","fb":"since + mốc → hiện tại hoàn thành"},{"type":"fill","q":"____ your brother ____ (finish) his homework yet?","opts":[],"answer":"Has … finished","fb":"yet → hoàn thành, đảo Has lên đầu"},{"type":"fill","q":"While my mother ____ (cook), the phone ____ (ring).","opts":[],"answer":"was cooking / rang","fb":"việc dài → tiếp diễn, việc ngắn xen vào → đơn"},{"type":"fill","q":"You ____ wash the dishes tonight — I've already done them. (mustn't / don't have to)","opts":[],"answer":"don't have to","fb":"rửa rồi nên khỏi cần, không phải cấm"},{"type":"fill","q":"Whose bag is this? It ____ Lan's — she has one just like it. (must be / can't be)","opts":[],"answer":"must be","fb":"có căn cứ nên đoán chắc → must be"}]$grammar$::jsonb, 'ai-golden', 29
from public.grammar_topics t where t.slug = 'present-perfect'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 30. present-perfect-continuous
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('present-perfect-continuous', 'Present Perfect Continuous', 'Hiện tại hoàn thành tiếp diễn', 'intermediate', 30)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Hiện tại hoàn thành tiếp diễn', 'Present Perfect Continuous dùng **hiện tại hoàn thành tiếp diễn** để nhấn mạnh quá trình bắt đầu trong quá khứ và còn tiếp tục hoặc vừa dừng nhưng có kết quả hiện tại. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"I have been studying for three hours.","vi":"Tôi đã học được ba tiếng rồi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"auxiliary","word":"have","start":2},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":20,"role":"verb","word":"studying","start":12},{"end":24,"role":"preposition","word":"for","start":21},{"end":30,"role":"other","word":"three","start":25},{"end":36,"role":"noun","word":"hours","start":31}]},{"en":"She has been crying; her eyes are red.","vi":"Cô ấy vừa khóc; mắt cô ấy đỏ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"has","start":4},{"end":12,"role":"auxiliary","word":"been","start":8},{"end":19,"role":"verb","word":"crying","start":13},{"end":24,"role":"pronoun","word":"her","start":21},{"end":29,"role":"noun","word":"eyes","start":25},{"end":33,"role":"auxiliary","word":"are","start":30},{"end":37,"role":"adjective","word":"red","start":34}]},{"en":"We haven't been sleeping well lately.","vi":"Gần đây chúng tôi ngủ không ngon.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":10,"role":"auxiliary","word":"haven't","start":3},{"end":15,"role":"auxiliary","word":"been","start":11},{"end":24,"role":"verb","word":"sleeping","start":16},{"end":29,"role":"adverb","word":"well","start":25},{"end":36,"role":"adverb","word":"lately","start":30}]},{"en":"How long have you been waiting?","vi":"Bạn đã chờ bao lâu rồi?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"How","start":0},{"end":8,"role":"adverb","word":"long","start":4},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":17,"role":"pronoun","word":"you","start":14},{"end":22,"role":"auxiliary","word":"been","start":18},{"end":30,"role":"verb","word":"waiting","start":23}]},{"en":"It has been raining since noon.","vi":"Trời đã mưa từ trưa.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":6,"role":"auxiliary","word":"has","start":3},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":19,"role":"verb","word":"raining","start":12},{"end":25,"role":"preposition","word":"since","start":20},{"end":30,"role":"noun","word":"noon","start":26}]},{"en":"They have been working here since 2022.","vi":"Họ đã làm việc ở đây từ năm 2022.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":9,"role":"auxiliary","word":"have","start":5},{"end":14,"role":"auxiliary","word":"been","start":10},{"end":22,"role":"verb","word":"working","start":15},{"end":27,"role":"adverb","word":"here","start":23},{"end":33,"role":"preposition","word":"since","start":28},{"end":38,"role":"other","word":"2022","start":34}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + have/has been + V-ing** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + have/has been + V-ing","example":"I have been studying for three hours."},{"case":"Kiểm tra thành phần theo sau","rule":"S + haven't/hasn't been + V-ing","example":"She has been crying; her eyes are red."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Have/Has + S + been + V-ing?","example":"We haven't been sleeping well lately."}],"usage":[{"en":"I have been studying for three hours.","vi":"Tôi đã học suốt ba tiếng đồng hồ rồi.","icon":"⏳","label":"Hành động kéo dài từ quá khứ đến nay, nhấn mạnh quá trình"},{"en":"She has been crying; her eyes are red.","vi":"Cô ấy vừa khóc xong; mắt cô ấy đỏ hoe.","icon":"👀","label":"Giải thích dấu vết, kết quả nhìn thấy ở hiện tại"},{"en":"We haven't been sleeping well lately.","vi":"Dạo này chúng tôi ngủ không ngon.","icon":"😴","label":"Tình trạng tạm thời gần đây (với lately, recently)"},{"en":"How long have you been waiting?","vi":"Bạn đã đợi bao lâu rồi?","icon":"❓","label":"Hỏi khoảng thời gian với How long"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + have/has been + V-ing","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + haven't/hasn't been + V-ing","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Have/Has + S + been + V-ing?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["by","before","when","for","since","this time"],"examples":[{"en":"I have been studying for three hours.","vi":"Tôi đã học được ba tiếng rồi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"auxiliary","word":"have","start":2},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":20,"role":"verb","word":"studying","start":12},{"end":24,"role":"preposition","word":"for","start":21},{"end":30,"role":"other","word":"three","start":25},{"end":36,"role":"noun","word":"hours","start":31}]},{"en":"She has been crying; her eyes are red.","vi":"Cô ấy vừa khóc; mắt cô ấy đỏ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"has","start":4},{"end":12,"role":"auxiliary","word":"been","start":8},{"end":19,"role":"verb","word":"crying","start":13},{"end":24,"role":"pronoun","word":"her","start":21},{"end":29,"role":"noun","word":"eyes","start":25},{"end":33,"role":"auxiliary","word":"are","start":30},{"end":37,"role":"adjective","word":"red","start":34}]},{"en":"We haven't been sleeping well lately.","vi":"Gần đây chúng tôi ngủ không ngon.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":10,"role":"auxiliary","word":"haven't","start":3},{"end":15,"role":"auxiliary","word":"been","start":11},{"end":24,"role":"verb","word":"sleeping","start":16},{"end":29,"role":"adverb","word":"well","start":25},{"end":36,"role":"adverb","word":"lately","start":30}]},{"en":"How long have you been waiting?","vi":"Bạn đã chờ bao lâu rồi?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"How","start":0},{"end":8,"role":"adverb","word":"long","start":4},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":17,"role":"pronoun","word":"you","start":14},{"end":22,"role":"auxiliary","word":"been","start":18},{"end":30,"role":"verb","word":"waiting","start":23}]},{"en":"It has been raining since noon.","vi":"Trời đã mưa từ trưa.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":6,"role":"auxiliary","word":"has","start":3},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":19,"role":"verb","word":"raining","start":12},{"end":25,"role":"preposition","word":"since","start":20},{"end":30,"role":"noun","word":"noon","start":26}]},{"en":"They have been working here since 2022.","vi":"Họ đã làm việc ở đây từ năm 2022.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":9,"role":"auxiliary","word":"have","start":5},{"end":14,"role":"auxiliary","word":"been","start":10},{"end":22,"role":"verb","word":"working","start":15},{"end":27,"role":"adverb","word":"here","start":23},{"end":33,"role":"preposition","word":"since","start":28},{"end":38,"role":"other","word":"2022","start":34}]}],"mistakes":[{"wrong":"I am learning English for five years.","right":"I have been learning English for five years.","why":"Quá trình kéo dài đến nay + for dùng present perfect continuous."},{"wrong":"She has been knowing him for years.","right":"She has known him for years.","why":"Know là động từ trạng thái — dùng present perfect đơn."},{"wrong":"He has been work all day.","right":"He has been working all day.","why":"Sau has been phải là V-ing."},{"wrong":"They have been played since morning.","right":"They have been playing since morning.","why":"Dạng tiếp diễn dùng V-ing, không phải quá khứ phân từ."}],"timeline":{"points":[{"note":"mốc trước","label":"quá khứ"},{"note":"trọng tâm","label":"điểm tham chiếu"},{"note":"mốc sau","label":"tương lai"}],"caption":"Đặt một mốc tham chiếu và quan sát hành động của Present Perfect Continuous diễn ra trước, tại hoặc hướng tới mốc đó."},"comparison":"**HTHT tiếp diễn vs HTHT đơn:** Tiếp diễn nhấn vào QUÁ TRÌNH kéo dài bao lâu (*I've been reading all afternoon* — suốt cả chiều). Đơn nhấn vào KẾT QUẢ đã xong bao nhiêu (*I've read 200 pages* — được 200 trang).","definition":"Present Perfect Continuous dùng **hiện tại hoàn thành tiếp diễn** để nhấn mạnh quá trình bắt đầu trong quá khứ và còn tiếp tục hoặc vừa dừng nhưng có kết quả hiện tại. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ been crying; her eyes are red.","answer":["has"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 30
from public.grammar_topics t where t.slug = 'present-perfect-continuous'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 31. past-perfect
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('past-perfect', 'Past Perfect', 'Thì Quá khứ hoàn thành', 'intermediate', 31)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Quá khứ hoàn thành', 'Thì **Quá khứ hoàn thành** (Past Perfect) được cấu tạo bởi ''had'' và phân từ hai của động từ chính. Thì này dùng để diễn tả một hành động đã hoàn thành xong xuôi trước một thời điểm hoặc một hành động khác xảy ra trong quá khứ.', $grammar$[{"en":"The train had left before we arrived.","vi":"Tàu đã rời đi trước khi chúng tôi đến.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"noun","word":"train","start":4},{"end":13,"role":"auxiliary","word":"had","start":10},{"end":18,"role":"verb","word":"left","start":14},{"end":25,"role":"preposition","word":"before","start":19},{"end":28,"role":"pronoun","word":"we","start":26},{"end":36,"role":"verb","word":"arrived","start":29}]},{"en":"She had never flown before that trip.","vi":"Trước chuyến đi đó cô ấy chưa từng bay.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"had","start":4},{"end":13,"role":"adverb","word":"never","start":8},{"end":19,"role":"verb","word":"flown","start":14},{"end":26,"role":"preposition","word":"before","start":20},{"end":31,"role":"determiner","word":"that","start":27},{"end":36,"role":"noun","word":"trip","start":32}]},{"en":"Had you finished when he called?","vi":"Bạn đã làm xong khi anh ấy gọi chưa?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":16,"role":"verb","word":"finished","start":8},{"end":21,"role":"conjunction","word":"when","start":17},{"end":24,"role":"pronoun","word":"he","start":22},{"end":31,"role":"verb","word":"called","start":25}]},{"en":"I hadn't seen the warning.","vi":"Tôi đã không nhìn thấy cảnh báo.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":8,"role":"auxiliary","word":"hadn't","start":2},{"end":13,"role":"verb","word":"seen","start":9},{"end":17,"role":"article","word":"the","start":14},{"end":25,"role":"noun","word":"warning","start":18}]},{"en":"After they had eaten, they went out.","vi":"Sau khi ăn xong, họ ra ngoài.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"preposition","word":"After","start":0},{"end":10,"role":"pronoun","word":"they","start":6},{"end":14,"role":"auxiliary","word":"had","start":11},{"end":20,"role":"verb","word":"eaten","start":15},{"end":26,"role":"pronoun","word":"they","start":22},{"end":31,"role":"verb","word":"went","start":27},{"end":35,"role":"adverb","word":"out","start":32}]},{"en":"By noon, we had completed the report.","vi":"Đến trưa, chúng tôi đã hoàn thành báo cáo.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"By","start":0},{"end":7,"role":"noun","word":"noon","start":3},{"end":11,"role":"pronoun","word":"we","start":9},{"end":15,"role":"auxiliary","word":"had","start":12},{"end":25,"role":"verb","word":"completed","start":16},{"end":29,"role":"article","word":"the","start":26},{"end":36,"role":"noun","word":"report","start":30}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + had + V3** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + had + V3","example":"The train had left before we arrived."},{"case":"Kiểm tra thành phần theo sau","rule":"S + had not + V3","example":"She had never flown before that trip."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Had + S + V3?","example":"Had you finished when he called?"}],"usage":[{"en":"The train had left before we arrived.","vi":"Tàu đã rời ga trước khi chúng tôi đến.","icon":"🚆","label":"Hành động xảy ra TRƯỚC một hành động khác trong quá khứ"},{"en":"She had never flown before that trip.","vi":"Trước chuyến đi đó, cô ấy chưa từng đi máy bay.","icon":"🛫","label":"Trải nghiệm tính đến một mốc trong quá khứ (never... before)"},{"en":"Had you finished when he called?","vi":"Lúc anh ấy gọi thì bạn đã làm xong chưa?","icon":"❓","label":"Hỏi xem việc đã xong chưa tại mốc quá khứ"},{"en":"I was hungry because I hadn't eaten anything.","vi":"Tôi đói vì trước đó tôi chưa ăn gì cả.","icon":"🧩","label":"Giải thích nguyên nhân của sự việc quá khứ"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + had + V3","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + had not + V3","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Had + S + V3?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["by","before","when","for","since","this time"],"examples":[{"en":"The train had left before we arrived.","vi":"Tàu đã rời đi trước khi chúng tôi đến.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"noun","word":"train","start":4},{"end":13,"role":"auxiliary","word":"had","start":10},{"end":18,"role":"verb","word":"left","start":14},{"end":25,"role":"preposition","word":"before","start":19},{"end":28,"role":"pronoun","word":"we","start":26},{"end":36,"role":"verb","word":"arrived","start":29}]},{"en":"She had never flown before that trip.","vi":"Trước chuyến đi đó cô ấy chưa từng bay.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"had","start":4},{"end":13,"role":"adverb","word":"never","start":8},{"end":19,"role":"verb","word":"flown","start":14},{"end":26,"role":"preposition","word":"before","start":20},{"end":31,"role":"determiner","word":"that","start":27},{"end":36,"role":"noun","word":"trip","start":32}]},{"en":"Had you finished when he called?","vi":"Bạn đã làm xong khi anh ấy gọi chưa?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":16,"role":"verb","word":"finished","start":8},{"end":21,"role":"conjunction","word":"when","start":17},{"end":24,"role":"pronoun","word":"he","start":22},{"end":31,"role":"verb","word":"called","start":25}]},{"en":"I hadn't seen the warning.","vi":"Tôi đã không nhìn thấy cảnh báo.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":8,"role":"auxiliary","word":"hadn't","start":2},{"end":13,"role":"verb","word":"seen","start":9},{"end":17,"role":"article","word":"the","start":14},{"end":25,"role":"noun","word":"warning","start":18}]},{"en":"After they had eaten, they went out.","vi":"Sau khi ăn xong, họ ra ngoài.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"preposition","word":"After","start":0},{"end":10,"role":"pronoun","word":"they","start":6},{"end":14,"role":"auxiliary","word":"had","start":11},{"end":20,"role":"verb","word":"eaten","start":15},{"end":26,"role":"pronoun","word":"they","start":22},{"end":31,"role":"verb","word":"went","start":27},{"end":35,"role":"adverb","word":"out","start":32}]},{"en":"By noon, we had completed the report.","vi":"Đến trưa, chúng tôi đã hoàn thành báo cáo.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"By","start":0},{"end":7,"role":"noun","word":"noon","start":3},{"end":11,"role":"pronoun","word":"we","start":9},{"end":15,"role":"auxiliary","word":"had","start":12},{"end":25,"role":"verb","word":"completed","start":16},{"end":29,"role":"article","word":"the","start":26},{"end":36,"role":"noun","word":"report","start":30}]}],"mistakes":[{"wrong":"When I arrived, the train already left.","right":"When I arrived, the train had already left.","why":"Việc xảy ra trước một mốc quá khứ dùng past perfect (had + P2)."},{"wrong":"She had went home before I called.","right":"She had gone home before I called.","why":"Sau had dùng quá khứ phân từ (gone), không dùng quá khứ đơn."},{"wrong":"After he had ate, he slept.","right":"After he had eaten, he slept.","why":"P2 của eat là eaten, không phải ate."},{"wrong":"I had never see snow before that trip.","right":"I had never seen snow before that trip.","why":"P2 của see là seen sau had."}],"timeline":{"points":[{"note":"mốc trước","label":"quá khứ"},{"note":"trọng tâm","label":"điểm tham chiếu"},{"note":"mốc sau","label":"tương lai"}],"caption":"Đặt một mốc tham chiếu và quan sát hành động của Past Perfect diễn ra trước, tại hoặc hướng tới mốc đó."},"comparison":"**Quá khứ hoàn thành vs Quá khứ đơn:** Past perfect đánh dấu hành động xảy ra TRƯỚC một hành động quá khứ khác: *When we arrived, the film HAD STARTED* (phim chiếu trước khi tới — lỡ đoạn đầu). Quá khứ đơn cả hai vế = chuỗi sự kiện theo thứ tự: *When we arrived, the film STARTED* (tới xong phim mới chiếu). Một chữ had đổi cả trật tự thời gian.","definition":"Thì **Quá khứ hoàn thành** (Past Perfect) được cấu tạo bởi 'had' và phân từ hai của động từ chính. Thì này dùng để diễn tả một hành động đã hoàn thành xong xuôi trước một thời điểm hoặc một hành động khác xảy ra trong quá khứ."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ never flown before that trip.","answer":["had"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 31
from public.grammar_topics t where t.slug = 'past-perfect'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 32. used-to
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('used-to', 'Used to / Be used to / Get used to', 'Cấu trúc Used to', 'intermediate', 32)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Cấu trúc Used to', 'Used to / Be used to / Get used to phân biệt **used to, be used to và get used to** khi nói thói quen cũ, sự quen thuộc và quá trình thích nghi. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"I used to live in Hue.","vi":"Tôi từng sống ở Huế.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"used","start":2},{"end":9,"role":"other","word":"to","start":7},{"end":14,"role":"verb","word":"live","start":10},{"end":17,"role":"preposition","word":"in","start":15},{"end":21,"role":"noun","word":"Hue","start":18}]},{"en":"She didn't use to drink coffee.","vi":"Cô ấy trước đây không uống cà phê.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"auxiliary","word":"didn't","start":4},{"end":14,"role":"verb","word":"use","start":11},{"end":17,"role":"other","word":"to","start":15},{"end":23,"role":"verb","word":"drink","start":18},{"end":30,"role":"noun","word":"coffee","start":24}]},{"en":"Are you used to the heat?","vi":"Bạn có quen với cái nóng không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Are","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":12,"role":"adjective","word":"used","start":8},{"end":15,"role":"preposition","word":"to","start":13},{"end":19,"role":"article","word":"the","start":16},{"end":24,"role":"noun","word":"heat","start":20}]},{"en":"I'm used to working late.","vi":"Tôi quen làm việc muộn.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"I'm","start":0},{"end":8,"role":"adjective","word":"used","start":4},{"end":11,"role":"preposition","word":"to","start":9},{"end":19,"role":"verb","word":"working","start":12},{"end":24,"role":"adverb","word":"late","start":20}]},{"en":"He is getting used to his new job.","vi":"Anh ấy đang dần quen việc mới.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":13,"role":"verb","word":"getting","start":6},{"end":18,"role":"adjective","word":"used","start":14},{"end":21,"role":"preposition","word":"to","start":19},{"end":25,"role":"determiner","word":"his","start":22},{"end":29,"role":"adjective","word":"new","start":26},{"end":33,"role":"noun","word":"job","start":30}]},{"en":"It took me weeks to get used to driving here.","vi":"Tôi mất nhiều tuần để quen lái xe ở đây.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":7,"role":"verb","word":"took","start":3},{"end":10,"role":"pronoun","word":"me","start":8},{"end":16,"role":"noun","word":"weeks","start":11},{"end":19,"role":"other","word":"to","start":17},{"end":23,"role":"verb","word":"get","start":20},{"end":28,"role":"adjective","word":"used","start":24},{"end":31,"role":"preposition","word":"to","start":29},{"end":39,"role":"verb","word":"driving","start":32},{"end":44,"role":"adverb","word":"here","start":40}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **used to + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"used to + V","example":"I used to live in Hue."},{"case":"Kiểm tra thành phần theo sau","rule":"be used to + noun/V-ing","example":"She didn't use to drink coffee."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"get used to + noun/V-ing","example":"Are you used to the heat?"}],"usage":[{"en":"I used to live in Hue.","vi":"Tôi từng sống ở Huế (giờ không còn nữa).","icon":"🏠","label":"USED TO + V — thói quen, tình trạng quá khứ nay không còn"},{"en":"She didn't use to drink coffee.","vi":"Hồi trước cô ấy không uống cà phê.","icon":"☕","label":"DIDN'T USE TO — phủ định thói quen quá khứ"},{"en":"Are you used to the heat in Saigon?","vi":"Bạn đã quen với cái nóng ở Sài Gòn chưa?","icon":"🌡️","label":"BE USED TO + V-ing — đã quen với điều gì"},{"en":"I'm getting used to working late.","vi":"Tôi đang dần quen với việc làm việc muộn.","icon":"🌙","label":"GET USED TO + V-ing — dần dần quen với điều gì"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"used to + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"be used to + noun/V-ing","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"get used to + noun/V-ing","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["used to","be used to","get used to","anymore","when I was young"],"examples":[{"en":"I used to live in Hue.","vi":"Tôi từng sống ở Huế.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"used","start":2},{"end":9,"role":"other","word":"to","start":7},{"end":14,"role":"verb","word":"live","start":10},{"end":17,"role":"preposition","word":"in","start":15},{"end":21,"role":"noun","word":"Hue","start":18}]},{"en":"She didn't use to drink coffee.","vi":"Cô ấy trước đây không uống cà phê.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"auxiliary","word":"didn't","start":4},{"end":14,"role":"verb","word":"use","start":11},{"end":17,"role":"other","word":"to","start":15},{"end":23,"role":"verb","word":"drink","start":18},{"end":30,"role":"noun","word":"coffee","start":24}]},{"en":"Are you used to the heat?","vi":"Bạn có quen với cái nóng không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Are","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":12,"role":"adjective","word":"used","start":8},{"end":15,"role":"preposition","word":"to","start":13},{"end":19,"role":"article","word":"the","start":16},{"end":24,"role":"noun","word":"heat","start":20}]},{"en":"I'm used to working late.","vi":"Tôi quen làm việc muộn.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"I'm","start":0},{"end":8,"role":"adjective","word":"used","start":4},{"end":11,"role":"preposition","word":"to","start":9},{"end":19,"role":"verb","word":"working","start":12},{"end":24,"role":"adverb","word":"late","start":20}]},{"en":"He is getting used to his new job.","vi":"Anh ấy đang dần quen việc mới.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":13,"role":"verb","word":"getting","start":6},{"end":18,"role":"adjective","word":"used","start":14},{"end":21,"role":"preposition","word":"to","start":19},{"end":25,"role":"determiner","word":"his","start":22},{"end":29,"role":"adjective","word":"new","start":26},{"end":33,"role":"noun","word":"job","start":30}]},{"en":"It took me weeks to get used to driving here.","vi":"Tôi mất nhiều tuần để quen lái xe ở đây.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":7,"role":"verb","word":"took","start":3},{"end":10,"role":"pronoun","word":"me","start":8},{"end":16,"role":"noun","word":"weeks","start":11},{"end":19,"role":"other","word":"to","start":17},{"end":23,"role":"verb","word":"get","start":20},{"end":28,"role":"adjective","word":"used","start":24},{"end":31,"role":"preposition","word":"to","start":29},{"end":39,"role":"verb","word":"driving","start":32},{"end":44,"role":"adverb","word":"here","start":40}]}],"mistakes":[{"wrong":"I use to play football when I was young.","right":"I used to play football when I was young.","why":"Khẳng định dùng USED to (có d)."},{"wrong":"I didn't used to like coffee.","right":"I didn't use to like coffee.","why":"Sau didn't dùng USE to (bỏ d)."},{"wrong":"She is used to get up early now.","right":"She is used to getting up early now.","why":"Be used to + V-ing (đã quen với việc gì)."},{"wrong":"He used to smoking a lot.","right":"He used to smoke a lot.","why":"Used to + động từ nguyên thể (thói quen quá khứ)."}],"timeline":{"points":[{"note":"quá khứ kéo dài","label":"▓▓▓ used to live alone"},{"note":"","label":"✂ đã thay đổi"},{"note":"hiện tại","label":"NOW: sống cùng gia đình"}],"caption":"Used to vẽ một dải thói quen trong quá khứ rồi CẮT ĐỨT trước hiện tại: trước kia có, giờ không còn."},"comparison":"**Used to do vs Be used to doing:** *used to do* = thói quen QUÁ KHỨ nay không còn (*I used to drive to work* — trước hay lái, giờ thì không). *be / get used to doing* = đã QUEN, không còn lạ lẫm ở hiện tại (*She is used to driving on the left* — quen rồi).","definition":"Used to / Be used to / Get used to phân biệt **used to, be used to và get used to** khi nói thói quen cũ, sự quen thuộc và quá trình thích nghi. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"Hồi nhỏ tôi thường đi bộ đến trường, giờ thì không. Chọn câu đúng.","options":["I used to walk to school.","I am used to walk to school.","I use to walked to school."],"correct_answer":"I used to walk to school.","explanation":"Used to + động từ nguyên thể diễn tả thói quen quá khứ nay đã thay đổi."},{"type":"multiple_choice","question":"She is used to ___ early.","options":["wake up","waking up","woke up"],"correct_answer":"waking up","explanation":"Be used to + V-ing/danh từ nghĩa là đã quen với việc gì."},{"type":"multiple_choice","question":"Phủ định của 'He used to smoke' là gì?","options":["He didn't used to smoke.","He didn't use to smoke.","He wasn't use to smoke."],"correct_answer":"He didn't use to smoke.","explanation":"Sau didn't, động từ trở về dạng nguyên thể: use to."},{"type":"multiple_choice","question":"'I am getting used to the cold' nghĩa là gì?","options":["Tôi từng chịu lạnh.","Tôi đang dần quen với cái lạnh.","Tôi sẽ tránh cái lạnh."],"correct_answer":"Tôi đang dần quen với cái lạnh.","explanation":"Get used to diễn tả quá trình trở nên quen."}]$grammar$::jsonb, 'ai-golden', 32
from public.grammar_topics t where t.slug = 'used-to'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 33. future-continuous
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('future-continuous', 'Future Continuous', 'Thì Tương lai tiếp diễn', 'intermediate', 33)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Tương lai tiếp diễn', 'Thì **Tương lai tiếp diễn** (Future Continuous) được dùng để diễn tả một hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai, hoặc một hành động xảy ra theo diễn biến tự nhiên của sự việc và nằm trong kế hoạch, lịch trình tương lai.', $grammar$[{"en":"This time tomorrow, I will be flying to Seoul.","vi":"Giờ này ngày mai tôi sẽ đang bay đến Seoul.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":9,"role":"noun","word":"time","start":5},{"end":18,"role":"adverb","word":"tomorrow","start":10},{"end":21,"role":"pronoun","word":"I","start":20},{"end":26,"role":"modal","word":"will","start":22},{"end":29,"role":"auxiliary","word":"be","start":27},{"end":36,"role":"verb","word":"flying","start":30},{"end":39,"role":"preposition","word":"to","start":37},{"end":45,"role":"noun","word":"Seoul","start":40}]},{"en":"She will be working at nine.","vi":"Lúc chín giờ cô ấy sẽ đang làm việc.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"She","start":0},{"end":8,"role":"modal","word":"will","start":4},{"end":11,"role":"auxiliary","word":"be","start":9},{"end":19,"role":"verb","word":"working","start":12},{"end":22,"role":"preposition","word":"at","start":20},{"end":27,"role":"other","word":"nine","start":23}]},{"en":"Will you be using the car tonight?","vi":"Tối nay bạn có dùng xe không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"modal","word":"Will","start":0},{"end":8,"role":"pronoun","word":"you","start":5},{"end":11,"role":"auxiliary","word":"be","start":9},{"end":17,"role":"verb","word":"using","start":12},{"end":21,"role":"article","word":"the","start":18},{"end":25,"role":"noun","word":"car","start":22},{"end":33,"role":"adverb","word":"tonight","start":26}]},{"en":"They won't be staying long.","vi":"Họ sẽ không ở lâu.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":10,"role":"auxiliary","word":"won't","start":5},{"end":13,"role":"auxiliary","word":"be","start":11},{"end":21,"role":"verb","word":"staying","start":14},{"end":26,"role":"adverb","word":"long","start":22}]},{"en":"Don't call at noon; I'll be sleeping.","vi":"Đừng gọi lúc trưa; tôi sẽ đang ngủ.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"auxiliary","word":"Don't","start":0},{"end":10,"role":"verb","word":"call","start":6},{"end":13,"role":"preposition","word":"at","start":11},{"end":18,"role":"noun","word":"noon","start":14},{"end":24,"role":"pronoun","word":"I'll","start":20},{"end":27,"role":"auxiliary","word":"be","start":25},{"end":36,"role":"verb","word":"sleeping","start":28}]},{"en":"We will be waiting for you outside.","vi":"Chúng tôi sẽ chờ bạn ở ngoài.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"modal","word":"will","start":3},{"end":10,"role":"auxiliary","word":"be","start":8},{"end":18,"role":"verb","word":"waiting","start":11},{"end":22,"role":"preposition","word":"for","start":19},{"end":26,"role":"pronoun","word":"you","start":23},{"end":34,"role":"adverb","word":"outside","start":27}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + will be + V-ing** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + will be + V-ing","example":"This time tomorrow, I will be flying to Seoul."},{"case":"Kiểm tra thành phần theo sau","rule":"S + will not be + V-ing","example":"She will be working at nine."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Will + S + be + V-ing?","example":"Will you be using the car tonight?"}],"usage":[{"en":"This time tomorrow, I will be flying to Seoul.","vi":"Giờ này ngày mai, tôi sẽ đang bay đến Seoul.","icon":"✈️","label":"Hành động đang diễn ra tại một thời điểm xác định ở tương lai"},{"en":"She will be working at nine as usual.","vi":"Chín giờ cô ấy sẽ đang làm việc như thường lệ.","icon":"📅","label":"Việc sẽ diễn ra như một phần của lịch trình bình thường"},{"en":"Will you be using the car tonight?","vi":"Tối nay bạn có dùng xe không?","icon":"🚗","label":"Hỏi lịch sự về kế hoạch của người khác"},{"en":"They won't be staying long.","vi":"Họ sẽ không ở lại lâu đâu.","icon":"⏱️","label":"Phủ định — việc sẽ không đang diễn ra"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + will be + V-ing","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + will not be + V-ing","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Will + S + be + V-ing?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["by","before","when","for","since","this time"],"examples":[{"en":"This time tomorrow, I will be flying to Seoul.","vi":"Giờ này ngày mai tôi sẽ đang bay đến Seoul.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":9,"role":"noun","word":"time","start":5},{"end":18,"role":"adverb","word":"tomorrow","start":10},{"end":21,"role":"pronoun","word":"I","start":20},{"end":26,"role":"modal","word":"will","start":22},{"end":29,"role":"auxiliary","word":"be","start":27},{"end":36,"role":"verb","word":"flying","start":30},{"end":39,"role":"preposition","word":"to","start":37},{"end":45,"role":"noun","word":"Seoul","start":40}]},{"en":"She will be working at nine.","vi":"Lúc chín giờ cô ấy sẽ đang làm việc.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"She","start":0},{"end":8,"role":"modal","word":"will","start":4},{"end":11,"role":"auxiliary","word":"be","start":9},{"end":19,"role":"verb","word":"working","start":12},{"end":22,"role":"preposition","word":"at","start":20},{"end":27,"role":"other","word":"nine","start":23}]},{"en":"Will you be using the car tonight?","vi":"Tối nay bạn có dùng xe không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"modal","word":"Will","start":0},{"end":8,"role":"pronoun","word":"you","start":5},{"end":11,"role":"auxiliary","word":"be","start":9},{"end":17,"role":"verb","word":"using","start":12},{"end":21,"role":"article","word":"the","start":18},{"end":25,"role":"noun","word":"car","start":22},{"end":33,"role":"adverb","word":"tonight","start":26}]},{"en":"They won't be staying long.","vi":"Họ sẽ không ở lâu.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":10,"role":"auxiliary","word":"won't","start":5},{"end":13,"role":"auxiliary","word":"be","start":11},{"end":21,"role":"verb","word":"staying","start":14},{"end":26,"role":"adverb","word":"long","start":22}]},{"en":"Don't call at noon; I'll be sleeping.","vi":"Đừng gọi lúc trưa; tôi sẽ đang ngủ.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"auxiliary","word":"Don't","start":0},{"end":10,"role":"verb","word":"call","start":6},{"end":13,"role":"preposition","word":"at","start":11},{"end":18,"role":"noun","word":"noon","start":14},{"end":24,"role":"pronoun","word":"I'll","start":20},{"end":27,"role":"auxiliary","word":"be","start":25},{"end":36,"role":"verb","word":"sleeping","start":28}]},{"en":"We will be waiting for you outside.","vi":"Chúng tôi sẽ chờ bạn ở ngoài.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"modal","word":"will","start":3},{"end":10,"role":"auxiliary","word":"be","start":8},{"end":18,"role":"verb","word":"waiting","start":11},{"end":22,"role":"preposition","word":"for","start":19},{"end":26,"role":"pronoun","word":"you","start":23},{"end":34,"role":"adverb","word":"outside","start":27}]}],"mistakes":[{"wrong":"At 8pm I will have dinner (đang ăn dở).","right":"At 8pm I will be having dinner.","why":"Hành động đang diễn ra tại mốc tương lai dùng will be + V-ing."},{"wrong":"This time tomorrow I will flying to Paris.","right":"This time tomorrow I will be flying to Paris.","why":"Thiếu BE trong cấu trúc will be + V-ing."},{"wrong":"While I will be waiting, I will read.","right":"While I am waiting, I will read.","why":"Mệnh đề thời gian (while) không dùng will."},{"wrong":"The meeting will be start at seven.","right":"The meeting will be starting at seven.","why":"Sau will be phải là V-ing, không phải nguyên thể."}],"timeline":{"points":[{"note":"mốc trước","label":"quá khứ"},{"note":"trọng tâm","label":"điểm tham chiếu"},{"note":"mốc sau","label":"tương lai"}],"caption":"Đặt một mốc tham chiếu và quan sát hành động của Future Continuous diễn ra trước, tại hoặc hướng tới mốc đó."},"comparison":"**Tương lai tiếp diễn vs Tương lai đơn:** Future continuous tả hành động ĐANG DIỄN RA tại một thời điểm tương lai: *At 8pm tonight, I will be having dinner* (8 giờ đang ăn dở). Future simple là quyết định/lời hứa trọn vẹn: *I will have dinner at 8pm* (sẽ ăn lúc 8 giờ). Đang giữa chừng → will be V-ing.","definition":"Thì **Tương lai tiếp diễn** (Future Continuous) được dùng để diễn tả một hành động sẽ đang diễn ra tại một thời điểm cụ thể trong tương lai, hoặc một hành động xảy ra theo diễn biến tự nhiên của sự việc và nằm trong kế hoạch, lịch trình tương lai."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ be working at nine.","answer":["will"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."},{"type":"multiple_choice","question":"Choose the sentence with the correct **Future Continuous** form for a future action in progress at 10 p.m.","options":["At 10 p.m., I will be revising for my exam.","At 10 p.m., I will revise for my exam yesterday.","At 10 p.m., I will be revise for my exam.","At 10 p.m., I am revise for my exam."],"correct_answer":"At 10 p.m., I will be revising for my exam.","explanation":"Đáp án đúng dùng cấu trúc will be + V-ing để diễn tả hành động đang diễn ra tại một thời điểm tương lai. Các lựa chọn khác sai vì thiếu V-ing, dùng sai thì, hoặc kết hợp thời gian không hợp lý.","difficulty":1},{"type":"multiple_choice","question":"Choose the most natural **question form** for asking about someone’s plan tonight.","options":["Will you be attending the meeting tonight?","Will you attending the meeting tonight?","Do you will be attending the meeting tonight?","Are you be attending the meeting tonight?"],"correct_answer":"Will you be attending the meeting tonight?","explanation":"Câu hỏi Future Continuous đúng có dạng Will + S + be + V-ing. Các phương án khác sai vì thiếu be hoặc dùng trợ động từ thừa/sai cấu trúc.","difficulty":1},{"type":"multiple_choice","question":"Which sentence uses the correct **negative form** of Future Continuous?","options":["They won’t be driving through the city at rush hour.","They won’t driving through the city at rush hour.","They won’t be drive through the city at rush hour.","They don’t will be driving through the city at rush hour."],"correct_answer":"They won’t be driving through the city at rush hour.","explanation":"Dạng phủ định đúng là will not/won’t be + V-ing. Các lựa chọn còn lại thiếu be, dùng động từ nguyên mẫu sau be, hoặc dùng don’t sai với will.","difficulty":1},{"type":"multiple_choice","question":"Choose the sentence that best shows a **temporary action** in progress next week.","options":["Next week, I’ll be staying with my cousin while my flat is repaired.","Next week, I stay with my cousin while my flat was repaired.","Next week, I’ll be stay with my cousin while my flat is repaired.","Next week, I was staying with my cousin while my flat is repaired."],"correct_answer":"Next week, I’ll be staying with my cousin while my flat is repaired.","explanation":"Future Continuous phù hợp để nói về việc tạm thời sẽ đang diễn ra trong tương lai. Các câu khác sai vì dùng sai dạng động từ hoặc trộn thì quá khứ với tương lai.","difficulty":2},{"type":"multiple_choice","question":"Select the correct **time expression** sentence using Future Continuous.","options":["At this time on Friday, we will be presenting our proposal.","Last Friday, we will be presenting our proposal.","Every Friday, we will be presenting our proposal now.","At this time yesterday, we will be presenting our proposal."],"correct_answer":"At this time on Friday, we will be presenting our proposal.","explanation":"“At this time on Friday” chỉ một thời điểm cụ thể trong tương lai nên hợp với will be presenting. Các lựa chọn khác dùng thời gian quá khứ hoặc mâu thuẫn thời gian.","difficulty":2},{"type":"multiple_choice","question":"Choose the sentence with the correct **verb spelling** after adding -ing.","options":["She will be running the workshop tomorrow afternoon.","She will be runing the workshop tomorrow afternoon.","She will be runs the workshop tomorrow afternoon.","She will be ran the workshop tomorrow afternoon."],"correct_answer":"She will be running the workshop tomorrow afternoon.","explanation":"Với run, nhân đôi phụ âm cuối rồi thêm -ing: running. Các đáp án khác sai chính tả hoặc dùng sai dạng động từ sau will be.","difficulty":1},{"type":"multiple_choice","question":"Which option sounds most polite as a **future arrangement** question?","options":["Will you be taking the early train tomorrow?","Will you take the early train yesterday?","Do you be taking the early train tomorrow?","Will you be took the early train tomorrow?"],"correct_answer":"Will you be taking the early train tomorrow?","explanation":"Future Continuous thường dùng để hỏi lịch trình một cách tự nhiên, lịch sự. Các câu khác sai do thời gian không khớp, dùng trợ động từ sai, hoặc dùng quá khứ phân từ sau be.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct sentence for an action that will be in progress **during** another future event.","options":["While you are giving your speech, I will be taking notes.","While you will give your speech, I will taking notes.","While you are giving your speech, I will be take notes.","While you gave your speech, I will be taking notes."],"correct_answer":"While you are giving your speech, I will be taking notes.","explanation":"Mệnh đề while có thể dùng hiện tại tiếp diễn để nói về bối cảnh tương lai, và mệnh đề chính dùng will be + V-ing. Các câu khác sai vì thiếu be, dùng sai dạng động từ, hoặc lệch thì.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **scheduled activity** sentence.","options":["The engineers will be testing the system all morning tomorrow.","The engineers will testing the system all morning tomorrow.","The engineers will be tested the system all morning tomorrow.","The engineers are be testing the system all morning tomorrow."],"correct_answer":"The engineers will be testing the system all morning tomorrow.","explanation":"Câu đúng diễn tả hoạt động đã nằm trong lịch trình và sẽ kéo dài trong tương lai. Các lựa chọn khác sai vì thiếu be hoặc dùng sai dạng động từ.","difficulty":2},{"type":"fill_blank","question":"Complete the **verb form**: At 7 a.m. tomorrow, my brother ___ to Hanoi.","options":["will be flying","will flying","will be fly","is fly"],"correct_answer":"will be flying","explanation":"Future Continuous cần will be + V-ing, nên “will be flying” là đúng. Các đáp án khác thiếu be, thiếu V-ing hoặc dùng sai cấu trúc hiện tại tiếp diễn.","difficulty":1},{"type":"fill_blank","question":"Fill in the blank with the correct **negative form**: We ___ late tonight.","options":["won’t be working","won’t working","will not working","don’t be working"],"correct_answer":"won’t be working","explanation":"Dạng phủ định đúng là won’t be + V-ing. Các lựa chọn khác thiếu be hoặc dùng trợ động từ không phù hợp với Future Continuous.","difficulty":1},{"type":"fill_blank","question":"Complete the polite **question**: ___ you ___ the printer this afternoon?","options":["Will / be using","Do / be using","Will / using","Are / be using"],"correct_answer":"Will / be using","explanation":"Câu hỏi Future Continuous có dạng Will + S + be + V-ing. Các đáp án khác thiếu will/be hoặc dùng trợ động từ sai.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **-ing spelling**: At noon, they will be ___ lunch with the clients.","options":["having","haveing","have","had"],"correct_answer":"having","explanation":"Động từ have bỏ e rồi thêm -ing thành having. Các đáp án khác sai chính tả hoặc không phải dạng V-ing cần dùng sau will be.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with Future Continuous **duration**: I ___ online from 8 to 10 tonight.","options":["will be studying","will study","will be studied","am study"],"correct_answer":"will be studying","explanation":"Khoảng thời gian “from 8 to 10 tonight” nhấn mạnh hành động đang diễn ra trong tương lai, nên dùng will be studying. Các lựa chọn khác không diễn tả đúng hành động tiếp diễn hoặc sai dạng động từ.","difficulty":2},{"type":"fill_blank","question":"Fill in the blank with the best **future action**: Don’t call at midnight; I ___ then.","options":["will be sleeping","will sleep","sleep","will be sleep"],"correct_answer":"will be sleeping","explanation":"“Then” chỉ thời điểm trong tương lai khi hành động đang diễn ra, nên cần will be + V-ing. Các đáp án khác hoặc quá chung, hoặc sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the **natural plan** sentence: The team ___ the new app throughout July.","options":["will be developing","will develops","will be develop","developed"],"correct_answer":"will be developing","explanation":"“Throughout July” cho thấy hoạt động kéo dài trong tương lai, phù hợp với Future Continuous. Các lựa chọn khác sai vì chia động từ sai hoặc dùng thì quá khứ.","difficulty":2},{"type":"fill_blank","question":"Choose the correct **word order**: What time ___ the guests ___ tomorrow?","options":["will / be arriving","will / arriving","are / be arriving","do / be arriving"],"correct_answer":"will / be arriving","explanation":"Câu hỏi Future Continuous với từ hỏi có dạng Wh-word + will + S + be + V-ing. Các lựa chọn khác thiếu be hoặc dùng trợ động từ sai.","difficulty":2},{"type":"error_correction","question":"Find the error: **Future Continuous** sentence: At 6 p.m., Lisa will be cook dinner for her family.","options":["At 6 p.m.","Lisa","will be cook","dinner for her family"],"correct_answer":"will be cook","explanation":"Sau will be phải dùng V-ing, nên cần sửa thành “will be cooking”. Các phần còn lại đúng về nghĩa và vị trí trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: **question form** sentence: Will be you waiting outside the station at noon?","options":["Will be","you","waiting outside","at noon"],"correct_answer":"Will be","explanation":"Câu hỏi đúng phải là “Will you be waiting...?” với thứ tự Will + S + be + V-ing. Các cụm còn lại phù hợp với cấu trúc và nghĩa của câu.","difficulty":2},{"type":"error_correction","question":"Find the error: **negative form** sentence: They will not watching the match at that time.","options":["They","will not watching","the match","at that time"],"correct_answer":"will not watching","explanation":"Dạng phủ định Future Continuous cần “will not be watching”. Cụm hiện tại thiếu be nên sai, còn các phần khác đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: **verb spelling** sentence: This time next month, we will be travelng around Europe.","options":["This time next month","we","will be travelng","around Europe"],"correct_answer":"will be travelng","explanation":"Dạng -ing đúng của travel là “travelling” hoặc “traveling”, không phải “travelng”. Cấu trúc will be là đúng, nhưng chính tả của V-ing sai.","difficulty":2},{"type":"error_correction","question":"Find the error: **time clause** sentence: When you will arrive tomorrow, I will be preparing dinner.","options":["When you will arrive","tomorrow","I","will be preparing dinner"],"correct_answer":"When you will arrive","explanation":"Trong mệnh đề thời gian nói về tương lai sau when, thường dùng hiện tại đơn: “When you arrive tomorrow”. Mệnh đề chính “I will be preparing dinner” là Future Continuous đúng.","difficulty":3},{"type":"error_correction","question":"Find the error: **auxiliary verb** sentence: At this time Sunday, Mark will be plays football with his friends.","options":["At this time Sunday","Mark","will be plays","with his friends"],"correct_answer":"will be plays","explanation":"Sau will be phải dùng V-ing, nên sửa thành “will be playing”. “Plays” là dạng hiện tại đơn ngôi thứ ba, không dùng trong cấu trúc này.","difficulty":1},{"type":"error_correction","question":"Find the error: **future schedule** sentence: The nurses will be worked the night shift this weekend.","options":["The nurses","will be worked","the night shift","this weekend"],"correct_answer":"will be worked","explanation":"Future Continuous dùng will be + V-ing, nên đúng là “will be working”. “Worked” là quá khứ/quá khứ phân từ, không phù hợp sau will be trong câu chủ động này.","difficulty":2},{"type":"error_correction","question":"Find the error: **polite question** sentence: Will you be useing your laptop after class?","options":["Will you","be useing","your laptop","after class"],"correct_answer":"be useing","explanation":"Động từ use bỏ e rồi thêm -ing thành “using”, nên cụm đúng là “be using”. Các phần khác đúng với mẫu câu hỏi Future Continuous.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **Future Continuous** sentence for an action in progress at 8 a.m. tomorrow.","options":["At 8 a.m. tomorrow, I will be taking my driving test.","At 8 a.m. tomorrow, I will take my driving test.","At 8 a.m. tomorrow, I am take my driving test.","At 8 a.m. tomorrow, I will be take my driving test."],"correct_answer":"At 8 a.m. tomorrow, I will be taking my driving test.","explanation":"Đáp án đúng dùng cấu trúc will be + V-ing để nhấn mạnh hành động đang diễn ra tại một thời điểm tương lai. Các lựa chọn khác dùng Future Simple, sai dạng động từ, hoặc thiếu V-ing sau will be.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **question form** to ask about a future activity in progress.","options":["Will Sarah be giving the presentation at 3 p.m.?","Will Sarah giving the presentation at 3 p.m.?","Sarah will be giving the presentation at 3 p.m.?","Will be Sarah giving the presentation at 3 p.m.?"],"correct_answer":"Will Sarah be giving the presentation at 3 p.m.?","explanation":"Câu hỏi Future Continuous có trật tự Will + S + be + V-ing. Các đáp án sai thiếu be, sai trật tự trợ động từ, hoặc chỉ lên giọng từ câu khẳng định.","difficulty":1},{"type":"multiple_choice","question":"Which sentence correctly uses the **negative form** for Future Continuous?","options":["The students won't be attending the workshop on Friday morning.","The students won't attending the workshop on Friday morning.","The students won't be attend the workshop on Friday morning.","The students aren't be attending the workshop on Friday morning."],"correct_answer":"The students won't be attending the workshop on Friday morning.","explanation":"Dạng phủ định đúng là will not/won't be + V-ing. Các câu còn lại thiếu be, dùng động từ nguyên mẫu sau be, hoặc kết hợp sai aren't be.","difficulty":1},{"type":"multiple_choice","question":"Choose the sentence that shows a **future interruption** correctly.","options":["At 6:30, we will be eating dinner when the delivery arrives.","At 6:30, we will eat dinner when the delivery will arrive.","At 6:30, we will be eat dinner when the delivery arrives.","At 6:30, we are eating dinner when the delivery will arrive."],"correct_answer":"At 6:30, we will be eating dinner when the delivery arrives.","explanation":"Hành động đang diễn ra trong tương lai dùng will be eating, còn mệnh đề thời gian với when dùng hiện tại đơn arrives. Các đáp án khác sai dạng Future Continuous hoặc dùng will trong mệnh đề when.","difficulty":2},{"type":"multiple_choice","question":"Choose the most natural **polite inquiry** about someone's future schedule.","options":["Will you be joining the client call later today?","Do you join the client call later today?","Will you join the client call later today?","Are you join the client call later today?"],"correct_answer":"Will you be joining the client call later today?","explanation":"Will you be + V-ing thường dùng lịch sự để hỏi về kế hoạch/sắp xếp tương lai. Future Simple vẫn hiểu được nhưng kém tự nhiên hơn trong ngữ cảnh hỏi lịch trình; are you join sai ngữ pháp.","difficulty":2},{"type":"multiple_choice","question":"Which option best expresses a **background action** in the future?","options":["While you are taking the exam, I will be waiting in the lobby.","While you will take the exam, I will wait in the lobby.","While you are taking the exam, I will waiting in the lobby.","While you take the exam, I will be waited in the lobby."],"correct_answer":"While you are taking the exam, I will be waiting in the lobby.","explanation":"Mệnh đề while dùng hiện tại tiếp diễn để chỉ hành động tương lai, còn hành động nền dùng will be waiting. Các lựa chọn khác dùng will sai trong mệnh đề thời gian hoặc sai dạng động từ.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct sentence with **by then** and Future Continuous.","options":["By then, the engineers will be testing the new security system.","By then, the engineers will test the new security system.","By then, the engineers will be tested the new security system.","By then, the engineers will testing the new security system."],"correct_answer":"By then, the engineers will be testing the new security system.","explanation":"By then có thể chỉ một thời điểm tương lai, nên will be testing diễn tả hành động đang diễn ra lúc đó. Các đáp án khác là Future Simple, dạng bị động không phù hợp, hoặc thiếu be.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **scheduled plan** sentence.","options":["Next Monday at noon, the director will be meeting the regional managers.","Next Monday at noon, the director will meeting the regional managers.","Next Monday at noon, the director will be meet the regional managers.","Next Monday at noon, the director is be meeting the regional managers."],"correct_answer":"Next Monday at noon, the director will be meeting the regional managers.","explanation":"Một hoạt động đã nằm trong lịch trình tương lai có thể dùng will be + V-ing. Các lựa chọn sai vì thiếu be, dùng động từ nguyên mẫu sau be, hoặc dùng is be không đúng.","difficulty":1},{"type":"multiple_choice","question":"Which sentence has the correct **-ing form** after will be?","options":["At this time next year, she will be running her own studio.","At this time next year, she will be runing her own studio.","At this time next year, she will be ran her own studio.","At this time next year, she will be runs her own studio."],"correct_answer":"At this time next year, she will be running her own studio.","explanation":"Run nhân đôi phụ âm n trước -ing thành running. Các dạng runing, ran, runs đều không phải V-ing đúng sau will be.","difficulty":2},{"type":"fill_blank","question":"Complete the **verb phrase**: At this time tomorrow morning, the committee ___ the final proposal.","options":["will be reviewing","will review","will reviewed","will be review"],"correct_answer":"will be reviewing","explanation":"At this time tomorrow morning chỉ thời điểm cụ thể trong tương lai, nên dùng will be reviewing. Will review không nhấn mạnh hành động đang diễn ra; hai lựa chọn còn lại sai dạng động từ sau will/be.","difficulty":1},{"type":"fill_blank","question":"Fill in the blank with the correct **negative form**: Please don't call during lunch; I ___ with a recruiter.","options":["won't be available because I will be speaking","won't available because I speak","will not be speak","am not will be speaking"],"correct_answer":"won't be available because I will be speaking","explanation":"Cụm đúng diễn tả trạng thái không rảnh và hành động đang diễn ra trong tương lai: will be speaking. Các đáp án khác thiếu be, sai trật tự trợ động từ, hoặc sai dạng động từ.","difficulty":2},{"type":"fill_blank","question":"Complete the **question word order**: Where ___ during the conference next week?","options":["will you be staying","you will be staying","will you staying","you will staying"],"correct_answer":"will you be staying","explanation":"Câu hỏi với từ để hỏi dùng Where + will + S + be + V-ing. Các lựa chọn khác sai trật tự câu hỏi hoặc thiếu be.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **-ing spelling**: Around midnight, the technicians will be ___ the server logs.","options":["checking","checkking","checked","checks"],"correct_answer":"checking","explanation":"Check thêm -ing thành checking; không nhân đôi k trong cách viết này. Checked là quá khứ/phân từ, checks là hiện tại đơn, không dùng sau will be.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with Future Continuous **duration**: From 2 to 5 tomorrow, Maya ___ interviews for the research project.","options":["will be conducting","will conduct","will be conducted","will conducting"],"correct_answer":"will be conducting","explanation":"From 2 to 5 tomorrow nhấn mạnh khoảng thời gian hành động đang diễn ra trong tương lai, nên dùng will be conducting. Will conduct chỉ nói chung về tương lai; hai đáp án còn lại sai dạng chủ động hoặc thiếu be.","difficulty":2},{"type":"fill_blank","question":"Fill in the blank for a **future plan**: Don't worry about the airport; Alex ___ you there after the meeting.","options":["will be driving","will driving","will be drive","drives"],"correct_answer":"will be driving","explanation":"Câu này nói về diễn biến/kế hoạch tự nhiên trong tương lai, dùng will be driving. Các lựa chọn khác thiếu be, sai dạng sau be, hoặc dùng hiện tại đơn không phù hợp.","difficulty":2},{"type":"fill_blank","question":"Complete the **time clause** sentence: When the manager calls tomorrow, we ___ the budget figures.","options":["will be discussing","will discuss","are discuss","will be discussed"],"correct_answer":"will be discussing","explanation":"Mệnh đề when dùng hiện tại đơn calls, còn hành động đang diễn ra lúc đó dùng will be discussing. Will discuss không nhấn mạnh tiến trình; are discuss và will be discussed sai dạng trong câu này.","difficulty":2},{"type":"fill_blank","question":"Choose the best **continuous form**: This evening at seven, the orchestra ___ on the main stage.","options":["will be performing","will perform","will be perform","is performed"],"correct_answer":"will be performing","explanation":"At seven là thời điểm cụ thể trong tương lai, nên dùng will be performing. Will perform là tương lai đơn; will be perform và is performed sai dạng/nghĩa.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **future form** sentence: At 4 p.m. tomorrow, Nora will be writes the monthly report.","options":["At 4 p.m. tomorrow","Nora","will be writes","the monthly report"],"correct_answer":"will be writes","explanation":"Sau will be phải dùng V-ing: will be writing. Các cụm còn lại không sai về cấu trúc Future Continuous trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **question order** sentence: What will be the interns doing during the training session?","options":["What","will be the interns","doing","during the training session"],"correct_answer":"will be the interns","explanation":"Trật tự đúng là What will the interns be doing...? Chủ ngữ the interns phải đứng sau will và trước be; các phần khác phù hợp.","difficulty":2},{"type":"error_correction","question":"Find the error: In the **negative sentence**: The speakers will not be answer questions after the panel.","options":["The speakers","will not be answer","questions","after the panel"],"correct_answer":"will not be answer","explanation":"Sau will not be cần V-ing, nên phải là will not be answering. Các cụm còn lại đúng và không gây lỗi chính.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **time expression** sentence: Tomorrow at noon, I will eating with my project team.","options":["Tomorrow at noon","I","will eating","with my project team"],"correct_answer":"will eating","explanation":"Future Continuous cần đầy đủ will be + V-ing: will be eating. Cụm thời gian, chủ ngữ và tân ngữ/giới từ đều đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **time clause** sentence: While the guests will arrive, the staff will be setting up the buffet.","options":["While the guests will arrive","the staff","will be setting up","the buffet"],"correct_answer":"While the guests will arrive","explanation":"Trong mệnh đề thời gian với while/when để chỉ tương lai, không dùng will; nên viết While the guests arrive hoặc While the guests are arriving. Vế chính will be setting up là đúng Future Continuous.","difficulty":3},{"type":"error_correction","question":"Find the error: In the **verb spelling** sentence: By 9 p.m., the volunteers will be makeing signs for the event.","options":["By 9 p.m.","the volunteers","will be makeing","signs for the event"],"correct_answer":"will be makeing","explanation":"Make bỏ e trước khi thêm -ing: will be making. Các phần còn lại đúng về nghĩa và cấu trúc câu.","difficulty":2},{"type":"error_correction","question":"Find the error: In the **auxiliary phrase** sentence: At this time next Friday, the sales team will being presenting the quarterly results.","options":["At this time next Friday","the sales team","will being presenting","the quarterly results"],"correct_answer":"will being presenting","explanation":"Sau will dùng động từ nguyên mẫu be, không dùng being: will be presenting. Các cụm khác không sai trong cấu trúc này.","difficulty":2},{"type":"error_correction","question":"Find the error: In the **future question** sentence: Will they be works remotely during the renovation?","options":["Will they","be works","remotely","during the renovation"],"correct_answer":"be works","explanation":"Sau be trong Future Continuous phải là V-ing: be working. Will they là mở đầu câu hỏi đúng; các cụm còn lại không sai.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **natural plan** sentence: The marketing team will be launches the campaign throughout September.","options":["The marketing team","will be launches","the campaign","throughout September"],"correct_answer":"will be launches","explanation":"Cấu trúc đúng là will be launching, không phải will be launches. Chủ ngữ, tân ngữ và cụm thời gian đều phù hợp.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **Future Continuous** sentence for an action in progress at 6 p.m. next Monday.","options":["At 6 p.m. next Monday, I will be attending a client meeting.","At 6 p.m. next Monday, I will attend a client meeting yesterday.","At 6 p.m. next Monday, I will be attend a client meeting.","At 6 p.m. next Monday, I will attending a client meeting."],"correct_answer":"At 6 p.m. next Monday, I will be attending a client meeting.","explanation":"Đáp án đúng dùng cấu trúc Future Continuous: will be + V-ing để diễn tả hành động đang diễn ra tại một thời điểm tương lai. Các lựa chọn khác sai vì thiếu be, thiếu will be, hoặc dùng trạng từ thời gian không phù hợp.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **polite question** about someone's plans tonight.","options":["Will you be joining the online class tonight?","Do you be joining the online class tonight?","Will you joining the online class tonight?","Are you be joining the online class tonight?"],"correct_answer":"Will you be joining the online class tonight?","explanation":"Câu hỏi Future Continuous đúng có trật tự Will + S + be + V-ing. Các câu còn lại sai vì dùng trợ động từ sai hoặc thiếu be sau will.","difficulty":1},{"type":"multiple_choice","question":"Which sentence correctly uses the **negative form** of Future Continuous?","options":["We will not be discussing salaries in tomorrow's meeting.","We will not discussing salaries in tomorrow's meeting.","We will be not discuss salaries in tomorrow's meeting.","We will not be discuss salaries in tomorrow's meeting."],"correct_answer":"We will not be discussing salaries in tomorrow's meeting.","explanation":"Dạng phủ định đúng là will not be + V-ing. Các phương án sai vì thiếu be, đặt not sai, hoặc dùng động từ nguyên mẫu sau be.","difficulty":1},{"type":"multiple_choice","question":"Choose the sentence with correct **time clause** use.","options":["When the train leaves, I will be waiting near the information desk.","When the train will leave, I will be waiting near the information desk.","When the train leaves, I will waiting near the information desk.","When the train leaving, I will be waiting near the information desk."],"correct_answer":"When the train leaves, I will be waiting near the information desk.","explanation":"Trong mệnh đề thời gian với when, ta dùng hiện tại đơn cho sự việc tương lai; mệnh đề chính dùng will be + V-ing. Các đáp án khác sai vì dùng will trong mệnh đề when hoặc thiếu cấu trúc Future Continuous.","difficulty":2},{"type":"multiple_choice","question":"Choose the most natural **planned activity** sentence.","options":["The design team will be reviewing the new logo all afternoon tomorrow.","The design team will reviewing the new logo all afternoon tomorrow.","The design team will be reviewed the new logo all afternoon tomorrow.","The design team will be review the new logo all afternoon tomorrow."],"correct_answer":"The design team will be reviewing the new logo all afternoon tomorrow.","explanation":"Future Continuous phù hợp để nói một hoạt động đã được dự kiến sẽ diễn ra trong một khoảng thời gian tương lai. Các lựa chọn sai vì thiếu be hoặc dùng sai dạng động từ sau be.","difficulty":2},{"type":"multiple_choice","question":"Which sentence correctly shows a **future background** action?","options":["At the festival, music will be playing while people browse the stalls.","At the festival, music will playing while people browse the stalls.","At the festival, music will be played while people browse the stalls.","At the festival, music will play while people will browse the stalls."],"correct_answer":"At the festival, music will be playing while people browse the stalls.","explanation":"Will be playing diễn tả âm nhạc như một hành động nền đang diễn ra trong tương lai. Các câu khác sai vì thiếu be, chuyển sang bị động không đúng ý, hoặc dùng will trong mệnh đề while không tự nhiên.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **question order** for a future arrangement.","options":["What will your team be testing on Friday afternoon?","What your team will be testing on Friday afternoon?","What will be your team testing on Friday afternoon?","What will your team testing be on Friday afternoon?"],"correct_answer":"What will your team be testing on Friday afternoon?","explanation":"Câu hỏi với từ để hỏi theo trật tự Wh-word + will + subject + be + V-ing. Các lựa chọn khác sai vì đảo sai vị trí chủ ngữ, be hoặc cụm V-ing.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **-ing spelling** sentence.","options":["At sunrise, the hikers will be beginning their final climb.","At sunrise, the hikers will be begining their final climb.","At sunrise, the hikers will be begginning their final climb.","At sunrise, the hikers will be begun their final climb."],"correct_answer":"At sunrise, the hikers will be beginning their final climb.","explanation":"Begin thêm -ing thành beginning vì nhân đôi n trước -ing. Các lựa chọn khác sai chính tả hoặc dùng quá khứ phân từ sau be.","difficulty":2},{"type":"multiple_choice","question":"Which option best expresses a **temporary future** situation?","options":["For the next two weeks, I will be staying with my aunt.","For the next two weeks, I will staying with my aunt.","For the next two weeks, I will be stay with my aunt.","For the next two weeks, I will stayed with my aunt."],"correct_answer":"For the next two weeks, I will be staying with my aunt.","explanation":"Will be staying diễn tả tình huống tạm thời kéo dài trong tương lai. Các đáp án khác sai vì thiếu be, sai dạng động từ, hoặc dùng quá khứ.","difficulty":1},{"type":"fill_blank","question":"Complete the **verb phrase**: Tomorrow at 11 a.m., the legal team ___ the contract details.","options":["will be checking","will checking","will be check","will checked"],"correct_answer":"will be checking","explanation":"Cấu trúc đúng là will be + V-ing: will be checking. Các lựa chọn khác thiếu be, dùng động từ nguyên mẫu sau be, hoặc dùng quá khứ sai.","difficulty":1},{"type":"fill_blank","question":"Fill in the blank with the correct **negative form**: I can't join the call at noon because I ___ my final exam.","options":["will not be taking","will be not taking","will not taking","will not be take"],"correct_answer":"will not be taking","explanation":"Dạng phủ định chuẩn là will not be + V-ing. Các đáp án khác sai vị trí not, thiếu be, hoặc dùng sai dạng động từ sau be.","difficulty":1},{"type":"fill_blank","question":"Complete the **question form**: ___ the projector during the workshop tomorrow?","options":["Will you be using","Will you using","Do you be using","Will be you using"],"correct_answer":"Will you be using","explanation":"Câu hỏi Future Continuous dùng Will + S + be + V-ing. Các lựa chọn khác sai vì thiếu be, dùng do không phù hợp, hoặc đảo sai trật tự.","difficulty":1},{"type":"fill_blank","question":"Choose the correct **time expression** form: This time next month, Sarah ___ in a new department.","options":["will be working","will work yesterday","will be work","will working"],"correct_answer":"will be working","explanation":"This time next month chỉ một thời điểm cụ thể trong tương lai, nên dùng will be working. Các lựa chọn còn lại sai về thời gian hoặc thiếu thành phần của Future Continuous.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **future action**: While you are presenting, I ___ notes for the report.","options":["will be taking","will taking","will be took","will takeing"],"correct_answer":"will be taking","explanation":"Mệnh đề chính dùng will be taking để diễn tả hành động đang diễn ra song song trong tương lai. Các đáp án khác thiếu be, sai dạng động từ, hoặc sai chính tả taking.","difficulty":2},{"type":"fill_blank","question":"Fill in the blank for a **scheduled process**: From Monday to Wednesday, the engineers ___ the new payment system.","options":["will be monitoring","will monitor yesterday","will be monitor","will monitoring"],"correct_answer":"will be monitoring","explanation":"Khoảng thời gian từ Monday to Wednesday trong tương lai phù hợp với will be monitoring. Các lựa chọn khác sai vì mâu thuẫn thời gian, thiếu be, hoặc dùng sai dạng động từ.","difficulty":2},{"type":"fill_blank","question":"Complete the **polite inquiry**: ___ the conference room at 3 p.m.?","options":["Will Ms. Tran be using","Will Ms. Tran using","Will be Ms. Tran using","Does Ms. Tran be using"],"correct_answer":"Will Ms. Tran be using","explanation":"Câu hỏi lịch sự về kế hoạch tương lai dùng Will + subject + be + V-ing. Các đáp án khác sai vì thiếu be, đảo sai vị trí be, hoặc dùng does với be không đúng.","difficulty":2},{"type":"fill_blank","question":"Choose the correct **-ing form**: At 8 tonight, the chef will be ___ fresh pasta for the guests.","options":["making","makeing","made","make"],"correct_answer":"making","explanation":"Make bỏ e rồi thêm -ing thành making. Makeing sai chính tả, còn made và make không phải dạng V-ing sau will be.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **verb form** sentence: At 7 tomorrow morning, Dana will be driveing across the bridge.","options":["At 7 tomorrow morning","Dana","will be driveing","across the bridge"],"correct_answer":"will be driveing","explanation":"Drive bỏ e rồi thêm -ing thành driving, nên cụm đúng là will be driving. Các phần còn lại phù hợp với câu Future Continuous.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **auxiliary phrase** sentence: Next Friday at noon, the director will presenting the annual plan.","options":["Next Friday at noon","the director","will presenting","the annual plan"],"correct_answer":"will presenting","explanation":"Future Continuous cần đầy đủ will be + V-ing, nên phải là will be presenting. Các cụm còn lại không sai về ngữ pháp trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **question form** sentence: Will the students be writes essays during the exam period?","options":["Will","the students","be writes","during the exam period"],"correct_answer":"be writes","explanation":"Sau be trong Future Continuous phải dùng V-ing: be writing. Writes là dạng hiện tại đơn ngôi thứ ba, không dùng sau be ở đây.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **negative form** sentence: The visitors won't be enter the gallery during the private tour.","options":["The visitors","won't be enter","the gallery","during the private tour"],"correct_answer":"won't be enter","explanation":"Sau won't be phải là V-ing, nên đúng là won't be entering. Các cụm còn lại chỉ đóng vai trò chủ ngữ, tân ngữ và trạng ngữ thời gian.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **time clause** sentence: As soon as the bell will ring, the teachers will be collecting the papers.","options":["As soon as","the bell will ring","the teachers","will be collecting"],"correct_answer":"the bell will ring","explanation":"Trong mệnh đề thời gian với as soon as, dùng hiện tại đơn cho tương lai: the bell rings. Mệnh đề chính will be collecting đã đúng Future Continuous.","difficulty":2},{"type":"error_correction","question":"Find the error: In the **word order** sentence: Why will be your brother sleeping in the guest room tonight?","options":["Why","will be your brother sleeping","in the guest room","tonight"],"correct_answer":"will be your brother sleeping","explanation":"Trật tự đúng là Why will your brother be sleeping...? Be phải đứng sau chủ ngữ, không đứng trước chủ ngữ trong cấu trúc này.","difficulty":2},{"type":"error_correction","question":"Find the error: In the **future duration** sentence: Between 1 and 3 tomorrow, the analysts will be compared the sales data.","options":["Between 1 and 3 tomorrow","the analysts","will be compared","the sales data"],"correct_answer":"will be compared","explanation":"Future Continuous dùng will be + V-ing, nên phải là will be comparing. Compared là quá khứ/quá khứ phân từ, không đúng sau will be khi diễn tả tiếp diễn.","difficulty":2},{"type":"error_correction","question":"Find the error: In the **natural plan** sentence: During the renovation, our staff will be works from a nearby office.","options":["During the renovation","our staff","will be works","from a nearby office"],"correct_answer":"will be works","explanation":"Sau will be phải dùng V-ing: will be working. Works là hiện tại đơn ngôi thứ ba nên không phù hợp trong Future Continuous.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **verb phrase** for an action in progress at 10 a.m. tomorrow.","options":["At 10 a.m. tomorrow, Maya will be attending a client meeting.","At 10 a.m. tomorrow, Maya will attending a client meeting.","At 10 a.m. tomorrow, Maya will be attend a client meeting.","At 10 a.m. tomorrow, Maya is be attending a client meeting."],"correct_answer":"At 10 a.m. tomorrow, Maya will be attending a client meeting.","explanation":"Future Continuous có dạng S + will be + V-ing, nên 'will be attending' là đúng. Các lựa chọn khác sai vì thiếu 'be', dùng động từ nguyên mẫu sau 'be', hoặc kết hợp sai 'is be'.","difficulty":1},{"type":"multiple_choice","question":"Choose the most natural **polite inquiry** about a future plan.","options":["Will you be taking the early train tomorrow?","Will you take the early train tomorrow now?","Are you be taking the early train tomorrow?","Will you be take the early train tomorrow?"],"correct_answer":"Will you be taking the early train tomorrow?","explanation":"Câu hỏi Future Continuous 'Will you be taking...?' thường dùng để hỏi lịch trình một cách lịch sự, tự nhiên. Các câu còn lại sai cấu trúc hoặc thêm 'now' không phù hợp với tương lai.","difficulty":2},{"type":"multiple_choice","question":"Which sentence correctly uses the **negative continuous** form?","options":["We won't be accepting new orders during the system upgrade.","We won't accepting new orders during the system upgrade.","We won't be accept new orders during the system upgrade.","We won't are accepting new orders during the system upgrade."],"correct_answer":"We won't be accepting new orders during the system upgrade.","explanation":"Dạng phủ định đúng là S + won't be + V-ing. Các đáp án khác thiếu 'be', dùng sai dạng động từ sau 'be', hoặc ghép sai trợ động từ với 'are'.","difficulty":1},{"type":"fill_blank","question":"Complete the **continuous form**: At this time next week, Omar ___ for his driving test.","options":["will be practicing","will practice","will be practice","is practice"],"correct_answer":"will be practicing","explanation":"Với thời điểm cụ thể trong tương lai 'At this time next week', cần dùng Future Continuous: 'will be practicing'. 'Will practice' là tương lai đơn, còn hai lựa chọn kia sai cấu trúc động từ.","difficulty":1},{"type":"fill_blank","question":"Fill in the blank with the correct **question form**: ___ near the stadium after the concert?","options":["Will you be parking","Will you parking","You will be parking","Will be you parking"],"correct_answer":"Will you be parking","explanation":"Câu hỏi Future Continuous có trật tự Will + S + be + V-ing. Các lựa chọn khác thiếu 'be', không đảo trợ động từ, hoặc đảo sai vị trí của chủ ngữ.","difficulty":2},{"type":"fill_blank","question":"Complete the **planned process**: Throughout July, the museum ___ its main entrance.","options":["will be restoring","will restoring","will be restored","will restoreing"],"correct_answer":"will be restoring","explanation":"'Throughout July' nhấn mạnh một quá trình kéo dài trong tương lai, nên dùng 'will be restoring'. Các đáp án khác sai vì thiếu 'be', dùng phân từ bị động không đúng nghĩa, hoặc viết sai dạng -ing.","difficulty":2},{"type":"fill_blank","question":"Choose the correct **negative phrase**: Please don't call at six; I ___ dinner with my manager.","options":["won't be having","will not having","won't have been","won't be have"],"correct_answer":"won't be having","explanation":"Hành động đang diễn ra tại một thời điểm tương lai dùng 'won't be having' khi ở dạng phủ định. Các phương án khác thiếu 'be', dùng thì khác, hoặc dùng sai dạng động từ sau 'be'.","difficulty":2},{"type":"error_correction","question":"Find the error: In the **verb form** sentence: At sunrise tomorrow, the hikers will be climb the northern trail.","options":["At sunrise tomorrow","hikers","will be climb","northern trail"],"correct_answer":"will be climb","explanation":"Sau 'will be' phải dùng V-ing, nên 'will be climb' phải sửa thành 'will be climbing'. Các cụm còn lại phù hợp về nghĩa và vị trí trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: In the **word order** sentence: What will be the technician checking during the inspection?","options":["What","will be the technician checking","during","the inspection"],"correct_answer":"will be the technician checking","explanation":"Câu hỏi Future Continuous đúng là 'What will the technician be checking...?'. Cụm sai đã đặt 'be' trước chủ ngữ, còn các phần khác không sai.","difficulty":3},{"type":"error_correction","question":"Find the error: In the **time clause** sentence: Before the CEO will speak, the translators will be testing their microphones.","options":["Before","the CEO will speak","will be testing","their microphones"],"correct_answer":"the CEO will speak","explanation":"Trong mệnh đề thời gian sau 'before', không dùng 'will'; phải nói 'Before the CEO speaks'. Mệnh đề chính 'will be testing' dùng đúng Future Continuous.","difficulty":3},{"type":"error_correction","question":"Find the error: In the **spelling rule** sentence: Around 5 p.m., Nina will be writeing updates for the project blog.","options":["Around 5 p.m.","Nina","will be writeing","project blog"],"correct_answer":"will be writeing","explanation":"Động từ 'write' bỏ 'e' trước khi thêm '-ing', nên dạng đúng là 'will be writing'. Các cụm còn lại không có lỗi ngữ pháp trong câu này.","difficulty":2},{"type":"error_correction","question":"Find the error related to the **auxiliary verb phrase** in the sentence: \"At this time next year, I will being studying abroad.\"","options":["A. \"At this time next year\"","B. \"I will being studying\"","C. \"studying abroad\"","D. No error"],"correct_answer":"B. \"I will being studying\"","explanation":"Lỗi sai nằm ở cụm \"will being studying\". Cấu trúc đúng của thì Tương lai tiếp diễn là S + will be + V-ing. Trong câu này, \"being\" đã bị dùng sai thay vì \"be\". Câu đúng phải là \"At this time next year, I will be studying abroad.\"","difficulty":2}]$grammar$::jsonb, 'ai-golden', 33
from public.grammar_topics t where t.slug = 'future-continuous'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 34. conjunctions-linking
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('conjunctions-linking', 'Conjunctions & Linking Words', 'Liên từ & từ nối', 'intermediate', 34)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Liên từ & từ nối', '**Conjunctions & Linking Words** là các từ hoặc cụm từ đóng vai trò kết nối các mệnh đề và câu, thiết lập mối quan hệ logic như nguyên nhân-kết quả, sự đối lập hoặc trình tự thời gian. Công dụng chính của chúng là đảm bảo tính **gắn kết (cohesion)** và logic trong văn bản, giúp người đọc theo sát luồng tư duy của người viết.', $grammar$[{"en":"I stayed home because I was ill.","vi":"Tôi ở nhà vì bị ốm.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":8,"role":"verb","word":"stayed","start":2},{"end":13,"role":"noun","word":"home","start":9},{"end":21,"role":"conjunction","word":"because","start":14},{"end":23,"role":"pronoun","word":"I","start":22},{"end":27,"role":"auxiliary","word":"was","start":24},{"end":31,"role":"adjective","word":"ill","start":28}]},{"en":"Although it was late, we continued.","vi":"Mặc dù muộn, chúng tôi vẫn tiếp tục.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":8,"role":"conjunction","word":"Although","start":0},{"end":11,"role":"pronoun","word":"it","start":9},{"end":15,"role":"auxiliary","word":"was","start":12},{"end":20,"role":"adjective","word":"late","start":16},{"end":24,"role":"pronoun","word":"we","start":22},{"end":34,"role":"verb","word":"continued","start":25}]},{"en":"She studied hard; therefore, she passed.","vi":"Cô ấy học chăm; vì vậy cô ấy đã đỗ.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"She","start":0},{"end":11,"role":"verb","word":"studied","start":4},{"end":16,"role":"adverb","word":"hard","start":12},{"end":27,"role":"conjunction","word":"therefore","start":18},{"end":32,"role":"pronoun","word":"she","start":29},{"end":39,"role":"verb","word":"passed","start":33}]},{"en":"You can call or send a message.","vi":"Bạn có thể gọi hoặc nhắn tin.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":7,"role":"modal","word":"can","start":4},{"end":12,"role":"verb","word":"call","start":8},{"end":15,"role":"conjunction","word":"or","start":13},{"end":20,"role":"verb","word":"send","start":16},{"end":22,"role":"article","word":"a","start":21},{"end":30,"role":"noun","word":"message","start":23}]},{"en":"He is kind, whereas his brother is reserved.","vi":"Anh ấy thân thiện, trong khi em trai khá kín đáo.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":10,"role":"adjective","word":"kind","start":6},{"end":19,"role":"conjunction","word":"whereas","start":12},{"end":23,"role":"determiner","word":"his","start":20},{"end":31,"role":"noun","word":"brother","start":24},{"end":34,"role":"auxiliary","word":"is","start":32},{"end":43,"role":"adjective","word":"reserved","start":35}]},{"en":"Take an umbrella in case it rains.","vi":"Hãy mang ô phòng khi trời mưa.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"verb","word":"Take","start":0},{"end":7,"role":"article","word":"an","start":5},{"end":16,"role":"noun","word":"umbrella","start":8},{"end":19,"role":"preposition","word":"in","start":17},{"end":24,"role":"conjunction","word":"case","start":20},{"end":27,"role":"pronoun","word":"it","start":25},{"end":33,"role":"verb","word":"rains","start":28}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **clause + coordinating conjunction + clause** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"clause + coordinating conjunction + clause","example":"I stayed home because I was ill."},{"case":"Kiểm tra thành phần theo sau","rule":"subordinator + clause, main clause","example":"Although it was late, we continued."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"sentence connector, sentence","example":"She studied hard; therefore, she passed."}],"usage":[{"en":"I stayed home because I was ill.","vi":"Tôi ở nhà vì tôi bị ốm.","icon":"🧩","label":"Chỉ nguyên nhân với because / since"},{"en":"Although it was late, we continued.","vi":"Mặc dù đã muộn, chúng tôi vẫn tiếp tục.","icon":"🔄","label":"Chỉ sự tương phản với although / but"},{"en":"She studied hard; therefore, she passed.","vi":"Cô ấy học chăm chỉ; vì vậy cô ấy đã đỗ.","icon":"🎯","label":"Chỉ kết quả với so / therefore"},{"en":"You can call or send a message.","vi":"Bạn có thể gọi điện hoặc nhắn tin.","icon":"🔀","label":"Nêu lựa chọn với or, bổ sung với and"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"clause + coordinating conjunction + clause","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"subordinator + clause, main clause","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"sentence connector, sentence","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["although","even though","despite","in spite of","unless","as long as","provided","in case"],"examples":[{"en":"I stayed home because I was ill.","vi":"Tôi ở nhà vì bị ốm.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":8,"role":"verb","word":"stayed","start":2},{"end":13,"role":"noun","word":"home","start":9},{"end":21,"role":"conjunction","word":"because","start":14},{"end":23,"role":"pronoun","word":"I","start":22},{"end":27,"role":"auxiliary","word":"was","start":24},{"end":31,"role":"adjective","word":"ill","start":28}]},{"en":"Although it was late, we continued.","vi":"Mặc dù muộn, chúng tôi vẫn tiếp tục.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":8,"role":"conjunction","word":"Although","start":0},{"end":11,"role":"pronoun","word":"it","start":9},{"end":15,"role":"auxiliary","word":"was","start":12},{"end":20,"role":"adjective","word":"late","start":16},{"end":24,"role":"pronoun","word":"we","start":22},{"end":34,"role":"verb","word":"continued","start":25}]},{"en":"She studied hard; therefore, she passed.","vi":"Cô ấy học chăm; vì vậy cô ấy đã đỗ.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"She","start":0},{"end":11,"role":"verb","word":"studied","start":4},{"end":16,"role":"adverb","word":"hard","start":12},{"end":27,"role":"conjunction","word":"therefore","start":18},{"end":32,"role":"pronoun","word":"she","start":29},{"end":39,"role":"verb","word":"passed","start":33}]},{"en":"You can call or send a message.","vi":"Bạn có thể gọi hoặc nhắn tin.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":7,"role":"modal","word":"can","start":4},{"end":12,"role":"verb","word":"call","start":8},{"end":15,"role":"conjunction","word":"or","start":13},{"end":20,"role":"verb","word":"send","start":16},{"end":22,"role":"article","word":"a","start":21},{"end":30,"role":"noun","word":"message","start":23}]},{"en":"He is kind, whereas his brother is reserved.","vi":"Anh ấy thân thiện, trong khi em trai khá kín đáo.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":10,"role":"adjective","word":"kind","start":6},{"end":19,"role":"conjunction","word":"whereas","start":12},{"end":23,"role":"determiner","word":"his","start":20},{"end":31,"role":"noun","word":"brother","start":24},{"end":34,"role":"auxiliary","word":"is","start":32},{"end":43,"role":"adjective","word":"reserved","start":35}]},{"en":"Take an umbrella in case it rains.","vi":"Hãy mang ô phòng khi trời mưa.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"verb","word":"Take","start":0},{"end":7,"role":"article","word":"an","start":5},{"end":16,"role":"noun","word":"umbrella","start":8},{"end":19,"role":"preposition","word":"in","start":17},{"end":24,"role":"conjunction","word":"case","start":20},{"end":27,"role":"pronoun","word":"it","start":25},{"end":33,"role":"verb","word":"rains","start":28}]}],"mistakes":[{"wrong":"Because of he was late, he missed the bus.","right":"Because he was late, he missed the bus.","why":"Because of đi với danh từ; có mệnh đề dùng because."},{"wrong":"Although his tiredness, he kept working.","right":"Despite his tiredness, he kept working.","why":"Although đi với mệnh đề; trước danh từ dùng despite."},{"wrong":"Although it was late, but we continued.","right":"Although it was late, we continued.","why":"Không ghép đôi although...but trong một câu."},{"wrong":"I couldn't sleep despite I was tired.","right":"I couldn't sleep despite being tired.","why":"Despite là giới từ — theo sau là danh từ/V-ing, không phải mệnh đề."}],"timeline":null,"comparison":"**Although vs Despite:** *Although/even though* là LIÊN TỪ → theo sau là MỆNH ĐỀ đủ chủ-vị (*Because he was late, he missed the bus*). *Despite/in spite of/because of* là GIỚI TỪ → theo sau là DANH TỪ/V-ing (*Because of his lateness...*). Cùng nghĩa, khác cấu trúc theo sau.","definition":"**Conjunctions & Linking Words** là các từ hoặc cụm từ đóng vai trò kết nối các mệnh đề và câu, thiết lập mối quan hệ logic như nguyên nhân-kết quả, sự đối lập hoặc trình tự thời gian. Công dụng chính của chúng là đảm bảo tính **gắn kết (cohesion)** và logic trong văn bản, giúp người đọc theo sát luồng tư duy của người viết."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"I am not rich. If I ____ (be) rich, I ____ (build) a big library for my village.","opts":[],"answer":"were / would build","fb":"trái với sự thật vừa nêu → loại 2, to be dùng were"},{"type":"fill","q":"Trang is always busy. If she ____ (have) more free time, she ____ (learn) the piano.","opts":[],"answer":"had / would learn","fb":"trái với sự thật Trang rất bận → loại 2"},{"type":"fill","q":"I live in Hue. If I ____ (live) in Ha Noi, I ____ (visit) the Old Quarter every week.","opts":[],"answer":"lived / would visit","fb":"trái với sự thật đang sống ở Huế → loại 2"},{"type":"fill","q":"Viết lại dùng if: Unless she says sorry, I won't talk to her again.","opts":[],"answer":"If she doesn't say sorry, I won't talk to her again.","fb":"bỏ unless thì trả lại doesn't, động từ về dạng trơ"},{"type":"fill","q":"Mai is afraid of water. If she ____ (not / be) afraid, she ____ (learn) to swim.","opts":[],"answer":"weren't / would learn","fb":"trái với sự thật Mai sợ nước → loại 2, phủ định to be là weren't"},{"type":"fill","q":"____ he got up early, he was late for the first train.","opts":[],"answer":"Although","fb":"he got up là chủ ngữ + động từ → although"},{"type":"fill","q":"The city council demolished the house ____ its bad condition.","opts":[],"answer":"because of","fb":"its bad condition là cụm danh từ, nêu lý do → because of"},{"type":"fill","q":"____ the hotel prices were too high, we decided to stay at home.","opts":[],"answer":"Because","fb":"the hotel prices were là chủ ngữ + động từ, nêu lý do → because"},{"type":"fill","q":"____ not trying his best, he failed the exam.","opts":[],"answer":"Because of","fb":"not trying là V-ing → because of"},{"type":"fill","q":"____ (Despite / Although) her poverty, everyone in the village respects her.","opts":[],"answer":"Despite","fb":"her poverty là cụm danh từ → Despite"},{"type":"fill","q":"He failed the exam because of his ____ (lazy).","opts":[],"answer":"laziness","fb":"sau his → cần danh từ"}]$grammar$::jsonb, 'ai-golden', 34
from public.grammar_topics t where t.slug = 'conjunctions-linking'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 35. gerunds-infinitives
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('gerunds-infinitives', 'Gerunds & Infinitives', 'Danh động từ & động từ nguyên mẫu', 'intermediate', 35)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Danh động từ & động từ nguyên mẫu', 'Gerunds & Infinitives dùng **V-ing và to-infinitive** sau các động từ/cấu trúc nhất định; lựa chọn đôi khi làm đổi nghĩa. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"I enjoy reading before bed.","vi":"Tôi thích đọc trước khi ngủ.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":7,"role":"verb","word":"enjoy","start":2},{"end":15,"role":"verb","word":"reading","start":8},{"end":22,"role":"preposition","word":"before","start":16},{"end":26,"role":"noun","word":"bed","start":23}]},{"en":"She decided to leave early.","vi":"Cô ấy quyết định rời đi sớm.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":11,"role":"verb","word":"decided","start":4},{"end":14,"role":"preposition","word":"to","start":12},{"end":20,"role":"verb","word":"leave","start":15},{"end":26,"role":"adverb","word":"early","start":21}]},{"en":"Thank you for helping me.","vi":"Cảm ơn bạn đã giúp tôi.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"verb","word":"Thank","start":0},{"end":9,"role":"pronoun","word":"you","start":6},{"end":13,"role":"preposition","word":"for","start":10},{"end":21,"role":"verb","word":"helping","start":14},{"end":24,"role":"pronoun","word":"me","start":22}]},{"en":"He stopped smoking.","vi":"Anh ấy đã bỏ hút thuốc.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":10,"role":"verb","word":"stopped","start":3},{"end":18,"role":"verb","word":"smoking","start":11}]},{"en":"He stopped to smoke.","vi":"Anh ấy dừng lại để hút thuốc.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":10,"role":"verb","word":"stopped","start":3},{"end":13,"role":"preposition","word":"to","start":11},{"end":19,"role":"verb","word":"smoke","start":14}]},{"en":"We hope to see you soon.","vi":"Chúng tôi hy vọng sớm gặp bạn.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"verb","word":"hope","start":3},{"end":10,"role":"preposition","word":"to","start":8},{"end":14,"role":"verb","word":"see","start":11},{"end":18,"role":"pronoun","word":"you","start":15},{"end":23,"role":"adverb","word":"soon","start":19}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **verb + V-ing** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"verb + V-ing","example":"I enjoy reading before bed."},{"case":"Kiểm tra thành phần theo sau","rule":"verb + to + V","example":"She decided to leave early."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"preposition + V-ing","example":"Thank you for helping me."}],"usage":[{"en":"I enjoy reading before bed.","vi":"Tôi thích đọc sách trước khi ngủ.","icon":"📖","label":"V-ing sau động từ chỉ sở thích (enjoy, love, hate)"},{"en":"She decided to leave early.","vi":"Cô ấy quyết định về sớm.","icon":"🎯","label":"To + V sau động từ chỉ quyết định, mong muốn (decide, want, hope)"},{"en":"Thank you for helping me.","vi":"Cảm ơn bạn đã giúp tôi.","icon":"🔗","label":"V-ing sau giới từ"},{"en":"He stopped smoking. / He stopped to smoke.","vi":"Anh ấy bỏ thuốc lá. / Anh ấy dừng lại để hút thuốc.","icon":"⚠️","label":"Động từ đổi nghĩa tùy theo V-ing hay to V (stop, remember, try)"},{"en":"Swimming is good for your health.","vi":"Bơi lội tốt cho sức khỏe của bạn.","icon":"🏁","label":"V-ing làm chủ ngữ của câu"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"verb + V-ing","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"verb + to + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"preposition + V-ing","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["enjoy","mind","avoid","suggest","decide","promise","learn","fail"],"examples":[{"en":"I enjoy reading before bed.","vi":"Tôi thích đọc trước khi ngủ.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":7,"role":"verb","word":"enjoy","start":2},{"end":15,"role":"verb","word":"reading","start":8},{"end":22,"role":"preposition","word":"before","start":16},{"end":26,"role":"noun","word":"bed","start":23}]},{"en":"She decided to leave early.","vi":"Cô ấy quyết định rời đi sớm.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":11,"role":"verb","word":"decided","start":4},{"end":14,"role":"preposition","word":"to","start":12},{"end":20,"role":"verb","word":"leave","start":15},{"end":26,"role":"adverb","word":"early","start":21}]},{"en":"Thank you for helping me.","vi":"Cảm ơn bạn đã giúp tôi.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"verb","word":"Thank","start":0},{"end":9,"role":"pronoun","word":"you","start":6},{"end":13,"role":"preposition","word":"for","start":10},{"end":21,"role":"verb","word":"helping","start":14},{"end":24,"role":"pronoun","word":"me","start":22}]},{"en":"He stopped smoking.","vi":"Anh ấy đã bỏ hút thuốc.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":10,"role":"verb","word":"stopped","start":3},{"end":18,"role":"verb","word":"smoking","start":11}]},{"en":"He stopped to smoke.","vi":"Anh ấy dừng lại để hút thuốc.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":10,"role":"verb","word":"stopped","start":3},{"end":13,"role":"preposition","word":"to","start":11},{"end":19,"role":"verb","word":"smoke","start":14}]},{"en":"We hope to see you soon.","vi":"Chúng tôi hy vọng sớm gặp bạn.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"verb","word":"hope","start":3},{"end":10,"role":"preposition","word":"to","start":8},{"end":14,"role":"verb","word":"see","start":11},{"end":18,"role":"pronoun","word":"you","start":15},{"end":23,"role":"adverb","word":"soon","start":19}]}],"mistakes":[{"wrong":"I enjoy to read books.","right":"I enjoy reading books.","why":"Sau enjoy dùng V-ing, không dùng to-infinitive."},{"wrong":"She wants going home.","right":"She wants to go home.","why":"Sau want dùng to-infinitive, không dùng V-ing."},{"wrong":"He avoided to meet her.","right":"He avoided meeting her.","why":"Sau avoid dùng V-ing."},{"wrong":"They decided buying a house.","right":"They decided to buy a house.","why":"Sau decide dùng to-infinitive."}],"timeline":null,"comparison":"**Danh động từ vs nguyên mẫu (đổi nghĩa):** Vài động từ đổi nghĩa theo dạng đi sau. *remember + V-ing* = nhớ việc ĐÃ làm (*I remember locking the door* — đã khóa, giờ nhớ lại). *remember + to V* = nhớ ĐỂ làm (*I remembered to lock the door* — nhớ mà đi khóa).","definition":"Gerunds & Infinitives dùng **V-ing và to-infinitive** sau các động từ/cấu trúc nhất định; lựa chọn đôi khi làm đổi nghĩa. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"The ____ (high) you climb, the colder it becomes.","opts":[],"answer":"higher","fb":"high là tính từ ngắn → higher"},{"type":"fill","q":"The ____ (careful) you are, the fewer mistakes you make.","opts":[],"answer":"more careful","fb":"careful là tính từ dài → more careful"},{"type":"fill","q":"The ____ (little) I sleep, the worse I feel.","opts":[],"answer":"less","fb":"little bất quy tắc → less"},{"type":"fill","q":"The days are getting ____ (short) in winter.","opts":[],"answer":"shorter and shorter","fb":"short ngắn → -er and -er"},{"type":"fill","q":"The story is becoming ____ (interesting).","opts":[],"answer":"more and more interesting","fb":"interesting là tính từ dài → more and more"},{"type":"fill","q":"Smartphones are getting ____ (cheap) every year.","opts":[],"answer":"cheaper and cheaper","fb":"cheap là tính từ ngắn → -er and -er"},{"type":"fill","q":"The ____ (much) you practise, the better you get.","opts":[],"answer":"more","fb":"much bất quy tắc → more"},{"type":"fill","q":"My brother enjoys ____ (play) computer games.","opts":[],"answer":"playing","fb":"enjoy nằm nhóm V-ing"},{"type":"fill","q":"Would you mind ____ (turn) down the music?","opts":[],"answer":"turning","fb":"mind nằm nhóm V-ing"},{"type":"fill","q":"My father stopped ____ (drink) coffee after the doctor's advice.","opts":[],"answer":"drinking","fb":"bỏ hẳn cà phê → V-ing"},{"type":"fill","q":"I still remember ____ (visit) Ha Long Bay when I was ten.","opts":[],"answer":"visiting","fb":"nhớ chuyện đã xảy ra → V-ing"},{"type":"fill","q":"He enjoys ____ football with his friends.  (A play · B to play · C playing · D played)","opts":[],"answer":"C playing","fb":"Sau enjoy luôn là V-ing · buổi 19"}]$grammar$::jsonb, 'ai-golden', 35
from public.grammar_topics t where t.slug = 'gerunds-infinitives'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
