values ('passive-voice', 'Passive Voice', 'Câu bị động', 'intermediate', 36)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu bị động', 'Passive Voice dùng **câu bị động** khi muốn nhấn mạnh người/vật chịu tác động hoặc khi tác nhân không rõ/không quan trọng. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"The bridge was built in 2010.","vi":"Cây cầu được xây năm 2010.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"bridge","start":4},{"end":14,"role":"auxiliary","word":"was","start":11},{"end":20,"role":"verb","word":"built","start":15},{"end":23,"role":"preposition","word":"in","start":21},{"end":28,"role":"other","word":"2010","start":24}]},{"en":"English is spoken worldwide.","vi":"Tiếng Anh được nói trên toàn thế giới.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":7,"role":"noun","word":"English","start":0},{"end":10,"role":"auxiliary","word":"is","start":8},{"end":17,"role":"verb","word":"spoken","start":11},{"end":27,"role":"adverb","word":"worldwide","start":18}]},{"en":"The package will be delivered tomorrow.","vi":"Gói hàng sẽ được giao ngày mai.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"package","start":4},{"end":16,"role":"modal","word":"will","start":12},{"end":19,"role":"auxiliary","word":"be","start":17},{"end":29,"role":"verb","word":"delivered","start":20},{"end":38,"role":"adverb","word":"tomorrow","start":30}]},{"en":"The road is being repaired.","vi":"Con đường đang được sửa.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"road","start":4},{"end":11,"role":"auxiliary","word":"is","start":9},{"end":17,"role":"auxiliary","word":"being","start":12},{"end":26,"role":"verb","word":"repaired","start":18}]},{"en":"The form must be signed.","vi":"Biểu mẫu phải được ký.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"form","start":4},{"end":13,"role":"modal","word":"must","start":9},{"end":16,"role":"auxiliary","word":"be","start":14},{"end":23,"role":"verb","word":"signed","start":17}]},{"en":"My bike has been stolen.","vi":"Xe đạp của tôi đã bị lấy cắp.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"determiner","word":"My","start":0},{"end":7,"role":"noun","word":"bike","start":3},{"end":11,"role":"auxiliary","word":"has","start":8},{"end":16,"role":"auxiliary","word":"been","start":12},{"end":23,"role":"verb","word":"stolen","start":17}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + be + V3** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + be + V3","example":"The bridge was built in 2010."},{"case":"Kiểm tra thành phần theo sau","rule":"S + modal + be + V3","example":"English is spoken worldwide."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"S + be + being/been + V3","example":"The package will be delivered tomorrow."}],"usage":[{"en":"The bridge was built in 2010.","vi":"Cây cầu được xây vào năm 2010.","icon":"🌉","label":"Nhấn mạnh đối tượng chịu tác động, không phải người làm"},{"en":"English is spoken worldwide.","vi":"Tiếng Anh được sử dụng trên toàn thế giới.","icon":"🌍","label":"Khi người thực hiện không quan trọng hoặc ai cũng biết"},{"en":"The package will be delivered tomorrow.","vi":"Gói hàng sẽ được giao vào ngày mai.","icon":"📦","label":"Bị động với thì tương lai (will be + V3)"},{"en":"The road is being repaired.","vi":"Con đường đang được sửa chữa.","icon":"🚧","label":"Bị động tiếp diễn (is being + V3) — việc đang được thực hiện"},{"en":"This novel was written by a Vietnamese author.","vi":"Cuốn tiểu thuyết này do một tác giả người Việt viết.","icon":"👤","label":"Thêm BY khi cần nêu rõ người thực hiện"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + be + V3","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + modal + be + V3","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + be + being/been + V3","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["be + P2","by","was made","is done","were built"],"examples":[{"en":"The bridge was built in 2010.","vi":"Cây cầu được xây năm 2010.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"bridge","start":4},{"end":14,"role":"auxiliary","word":"was","start":11},{"end":20,"role":"verb","word":"built","start":15},{"end":23,"role":"preposition","word":"in","start":21},{"end":28,"role":"other","word":"2010","start":24}]},{"en":"English is spoken worldwide.","vi":"Tiếng Anh được nói trên toàn thế giới.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":7,"role":"noun","word":"English","start":0},{"end":10,"role":"auxiliary","word":"is","start":8},{"end":17,"role":"verb","word":"spoken","start":11},{"end":27,"role":"adverb","word":"worldwide","start":18}]},{"en":"The package will be delivered tomorrow.","vi":"Gói hàng sẽ được giao ngày mai.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"package","start":4},{"end":16,"role":"modal","word":"will","start":12},{"end":19,"role":"auxiliary","word":"be","start":17},{"end":29,"role":"verb","word":"delivered","start":20},{"end":38,"role":"adverb","word":"tomorrow","start":30}]},{"en":"The road is being repaired.","vi":"Con đường đang được sửa.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"road","start":4},{"end":11,"role":"auxiliary","word":"is","start":9},{"end":17,"role":"auxiliary","word":"being","start":12},{"end":26,"role":"verb","word":"repaired","start":18}]},{"en":"The form must be signed.","vi":"Biểu mẫu phải được ký.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"form","start":4},{"end":13,"role":"modal","word":"must","start":9},{"end":16,"role":"auxiliary","word":"be","start":14},{"end":23,"role":"verb","word":"signed","start":17}]},{"en":"My bike has been stolen.","vi":"Xe đạp của tôi đã bị lấy cắp.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"determiner","word":"My","start":0},{"end":7,"role":"noun","word":"bike","start":3},{"end":11,"role":"auxiliary","word":"has","start":8},{"end":16,"role":"auxiliary","word":"been","start":12},{"end":23,"role":"verb","word":"stolen","start":17}]}],"mistakes":[{"wrong":"The house was build in 1990.","right":"The house was built in 1990.","why":"Bị động dùng quá khứ phân từ (built), không dùng nguyên thể."},{"wrong":"English is speak here.","right":"English is spoken here.","why":"Sau is/are dùng P2 (spoken)."},{"wrong":"The letter was wrote by Tom.","right":"The letter was written by Tom.","why":"P2 của write là written."},{"wrong":"This song was sang by her.","right":"This song was sung by her.","why":"P2 của sing là sung, không phải sang."}],"timeline":null,"comparison":"**Câu bị động vs chủ động:** Chủ động nhấn vào AI làm (*Somebody built this house in 1981*). Bị động nhấn vào ĐIỀU GÌ xảy ra với chủ thể, khi tác nhân không rõ / không quan trọng (*This house was built in 1981*).","definition":"Passive Voice dùng **câu bị động** khi muốn nhấn mạnh người/vật chịu tác động hoặc khi tác nhân không rõ/không quan trọng. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"The telephone ____ (invent) by Alexander Graham Bell.","opts":[],"answer":"was invented","fb":"chuyện đã xong trong quá khứ → was + V3"},{"type":"fill","q":"Trees ____ (plant) in our schoolyard since Monday.","opts":[],"answer":"have been planted","fb":"since Monday = kéo tới giờ → have been + V3"},{"type":"fill","q":"Nobody can answer this question.  →  This question ____.","opts":[],"answer":"can't be answered","fb":"Nobody + can → can't be + V3, cắt by"},{"type":"fill","q":"Rút gọn: The cakes which are sold in that shop are delicious.","opts":[],"answer":"The cakes sold in that shop are delicious.","fb":"are sold bị động → giữ sold"},{"type":"fill","q":"Rút gọn: The letters which were written by my grandfather are in this box.","opts":[],"answer":"The letters written by my grandfather are in this box.","fb":"were written bị động → giữ written"},{"type":"fill","q":"The homework ____ by the students last night.  (A did · B was done · C is done · D does)","opts":[],"answer":"B was done","fb":"Bài tập được làm, mốc last night → bị động quá khứ · buổi 9"}]$grammar$::jsonb, 'ai-golden', 36
from public.grammar_topics t where t.slug = 'passive-voice'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 37. reported-speech
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('reported-speech', 'Reported Speech', 'Câu tường thuật', 'intermediate', 37)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu tường thuật', 'Reported Speech dùng **câu tường thuật** để kể lại lời nói mà không lặp nguyên văn. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"She said that she was tired.","vi":"Cô ấy nói rằng cô ấy mệt.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":8,"role":"verb","word":"said","start":4},{"end":13,"role":"conjunction","word":"that","start":9},{"end":17,"role":"pronoun","word":"she","start":14},{"end":21,"role":"verb","word":"was","start":18},{"end":27,"role":"adjective","word":"tired","start":22}]},{"en":"He told me to wait.","vi":"Anh ấy bảo tôi chờ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":7,"role":"verb","word":"told","start":3},{"end":10,"role":"pronoun","word":"me","start":8},{"end":13,"role":"preposition","word":"to","start":11},{"end":18,"role":"verb","word":"wait","start":14}]},{"en":"Lan asked whether I was free.","vi":"Lan hỏi tôi có rảnh không.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"Lan","start":0},{"end":9,"role":"verb","word":"asked","start":4},{"end":17,"role":"conjunction","word":"whether","start":10},{"end":19,"role":"pronoun","word":"I","start":18},{"end":23,"role":"verb","word":"was","start":20},{"end":28,"role":"adjective","word":"free","start":24}]},{"en":"They said they had finished.","vi":"Họ nói họ đã làm xong.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":9,"role":"verb","word":"said","start":5},{"end":14,"role":"pronoun","word":"they","start":10},{"end":18,"role":"auxiliary","word":"had","start":15},{"end":27,"role":"verb","word":"finished","start":19}]},{"en":"My boss told me not to be late.","vi":"Sếp bảo tôi đừng đến muộn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"determiner","word":"My","start":0},{"end":7,"role":"noun","word":"boss","start":3},{"end":12,"role":"verb","word":"told","start":8},{"end":15,"role":"pronoun","word":"me","start":13},{"end":19,"role":"adverb","word":"not","start":16},{"end":22,"role":"preposition","word":"to","start":20},{"end":25,"role":"verb","word":"be","start":23},{"end":30,"role":"adjective","word":"late","start":26}]},{"en":"He asked where I lived.","vi":"Anh ấy hỏi tôi sống ở đâu.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":8,"role":"verb","word":"asked","start":3},{"end":14,"role":"adverb","word":"where","start":9},{"end":16,"role":"pronoun","word":"I","start":15},{"end":22,"role":"verb","word":"lived","start":17}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **said (that) + clause** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"said (that) + clause","example":"She said that she was tired."},{"case":"Kiểm tra thành phần theo sau","rule":"told + object + clause","example":"He told me to wait."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"asked + if/wh-clause","example":"Lan asked whether I was free."}],"usage":[{"en":"\"I am tired.\" → She said that she was tired.","vi":"\"Tôi mệt.\" → Cô ấy nói rằng cô ấy mệt.","icon":"💬","label":"Tường thuật câu kể — lùi thì, đổi ngôi"},{"en":"He told me to wait outside.","vi":"Anh ấy bảo tôi đợi ở ngoài.","icon":"📢","label":"Tường thuật mệnh lệnh với told + O + to V"},{"en":"Lan asked whether I was free.","vi":"Lan hỏi liệu tôi có rảnh không.","icon":"❓","label":"Tường thuật câu hỏi Yes/No với whether / if"},{"en":"\"We finished.\" → They said they had finished.","vi":"\"Bọn tôi xong rồi.\" → Họ nói họ đã hoàn thành rồi.","icon":"⏪","label":"Lùi quá khứ đơn thành quá khứ hoàn thành"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"said (that) + clause","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"told + object + clause","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"asked + if/wh-clause","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["say","tell","ask","said that","told me","whether","if"],"examples":[{"en":"She said that she was tired.","vi":"Cô ấy nói rằng cô ấy mệt.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":8,"role":"verb","word":"said","start":4},{"end":13,"role":"conjunction","word":"that","start":9},{"end":17,"role":"pronoun","word":"she","start":14},{"end":21,"role":"verb","word":"was","start":18},{"end":27,"role":"adjective","word":"tired","start":22}]},{"en":"He told me to wait.","vi":"Anh ấy bảo tôi chờ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":7,"role":"verb","word":"told","start":3},{"end":10,"role":"pronoun","word":"me","start":8},{"end":13,"role":"preposition","word":"to","start":11},{"end":18,"role":"verb","word":"wait","start":14}]},{"en":"Lan asked whether I was free.","vi":"Lan hỏi tôi có rảnh không.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"Lan","start":0},{"end":9,"role":"verb","word":"asked","start":4},{"end":17,"role":"conjunction","word":"whether","start":10},{"end":19,"role":"pronoun","word":"I","start":18},{"end":23,"role":"verb","word":"was","start":20},{"end":28,"role":"adjective","word":"free","start":24}]},{"en":"They said they had finished.","vi":"Họ nói họ đã làm xong.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":9,"role":"verb","word":"said","start":5},{"end":14,"role":"pronoun","word":"they","start":10},{"end":18,"role":"auxiliary","word":"had","start":15},{"end":27,"role":"verb","word":"finished","start":19}]},{"en":"My boss told me not to be late.","vi":"Sếp bảo tôi đừng đến muộn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"determiner","word":"My","start":0},{"end":7,"role":"noun","word":"boss","start":3},{"end":12,"role":"verb","word":"told","start":8},{"end":15,"role":"pronoun","word":"me","start":13},{"end":19,"role":"adverb","word":"not","start":16},{"end":22,"role":"preposition","word":"to","start":20},{"end":25,"role":"verb","word":"be","start":23},{"end":30,"role":"adjective","word":"late","start":26}]},{"en":"He asked where I lived.","vi":"Anh ấy hỏi tôi sống ở đâu.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":8,"role":"verb","word":"asked","start":3},{"end":14,"role":"adverb","word":"where","start":9},{"end":16,"role":"pronoun","word":"I","start":15},{"end":22,"role":"verb","word":"lived","start":17}]}],"mistakes":[{"wrong":"He said he will come.","right":"He said he would come.","why":"Câu tường thuật quá khứ: will lùi thành would."},{"wrong":"She told that she was tired.","right":"She said that she was tired.","why":"Tell cần tân ngữ (told me); không tân ngữ dùng said."},{"wrong":"He asked where do I live.","right":"He asked where I lived.","why":"Câu hỏi tường thuật dùng trật tự câu kể, lùi thì."},{"wrong":"She said me she was busy.","right":"She told me she was busy.","why":"Có tân ngữ (me) dùng told, không dùng said me."}],"timeline":null,"comparison":"**Câu tường thuật vs trực tiếp:** Trực tiếp = trích NGUYÊN VĂN, giữ thì gốc (*He said \"I have to go\"*). Tường thuật = thuật lại, LÙI THÌ về quá khứ khi không còn đúng ở hiện tại (*He said he had to go*).","definition":"Reported Speech dùng **câu tường thuật** để kể lại lời nói mà không lặp nguyên văn. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"She said, 'I am tired.' → She said that she ___ tired.","options":["is","was","were"],"correct_answer":"was","explanation":"Với động từ tường thuật said ở quá khứ, am thường lùi thành was."},{"type":"multiple_choice","question":"He said, 'I will call you.' → He said he ___ call me.","options":["will","would","can"],"correct_answer":"would","explanation":"Will thường lùi thành would trong lời tường thuật quá khứ."},{"type":"multiple_choice","question":"She asked me, 'Where do you live?' → She asked me where ___ .","options":["did I live","I lived","do I live"],"correct_answer":"I lived","explanation":"Câu hỏi tường thuật dùng trật tự câu kể: chủ ngữ + động từ."},{"type":"multiple_choice","question":"He said, 'I saw her yesterday.' → He said he had seen her ___ .","options":["the day before","tomorrow","next day"],"correct_answer":"the day before","explanation":"Yesterday thường đổi thành the day before."}]$grammar$::jsonb, 'ai-golden', 37
from public.grammar_topics t where t.slug = 'reported-speech'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 38. relative-clauses
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('relative-clauses', 'Relative Clauses', 'Mệnh đề quan hệ', 'intermediate', 38)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Mệnh đề quan hệ', 'Relative Clauses dùng **mệnh đề quan hệ** để bổ sung thông tin cho danh từ mà không phải mở câu mới. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"The woman who called is my aunt.","vi":"Người phụ nữ đã gọi là dì tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"noun","word":"woman","start":4},{"end":13,"role":"pronoun","word":"who","start":10},{"end":20,"role":"verb","word":"called","start":14},{"end":23,"role":"verb","word":"is","start":21},{"end":26,"role":"determiner","word":"my","start":24},{"end":31,"role":"noun","word":"aunt","start":27}]},{"en":"This is the book that I mentioned.","vi":"Đây là cuốn sách tôi đã nhắc.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":7,"role":"verb","word":"is","start":5},{"end":11,"role":"article","word":"the","start":8},{"end":16,"role":"noun","word":"book","start":12},{"end":21,"role":"pronoun","word":"that","start":17},{"end":23,"role":"pronoun","word":"I","start":22},{"end":33,"role":"verb","word":"mentioned","start":24}]},{"en":"The café where we met has closed.","vi":"Quán cà phê nơi chúng ta gặp đã đóng cửa.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"café","start":4},{"end":14,"role":"adverb","word":"where","start":9},{"end":17,"role":"pronoun","word":"we","start":15},{"end":21,"role":"verb","word":"met","start":18},{"end":25,"role":"auxiliary","word":"has","start":22},{"end":32,"role":"verb","word":"closed","start":26}]},{"en":"Students whose work is late must email me.","vi":"Học sinh nộp bài muộn phải gửi email cho tôi.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":8,"role":"noun","word":"Students","start":0},{"end":14,"role":"determiner","word":"whose","start":9},{"end":19,"role":"noun","word":"work","start":15},{"end":22,"role":"verb","word":"is","start":20},{"end":27,"role":"adjective","word":"late","start":23},{"end":32,"role":"modal","word":"must","start":28},{"end":38,"role":"verb","word":"email","start":33},{"end":41,"role":"pronoun","word":"me","start":39}]},{"en":"My laptop, which is old, still works.","vi":"Laptop của tôi, vốn đã cũ, vẫn hoạt động.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"determiner","word":"My","start":0},{"end":9,"role":"noun","word":"laptop","start":3},{"end":16,"role":"pronoun","word":"which","start":11},{"end":19,"role":"verb","word":"is","start":17},{"end":23,"role":"adjective","word":"old","start":20},{"end":30,"role":"adverb","word":"still","start":25},{"end":36,"role":"verb","word":"works","start":31}]},{"en":"The man I spoke to was helpful.","vi":"Người đàn ông tôi nói chuyện cùng rất nhiệt tình.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":7,"role":"noun","word":"man","start":4},{"end":9,"role":"pronoun","word":"I","start":8},{"end":15,"role":"verb","word":"spoke","start":10},{"end":18,"role":"preposition","word":"to","start":16},{"end":22,"role":"verb","word":"was","start":19},{"end":30,"role":"adjective","word":"helpful","start":23}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **person + who/that + clause** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"person + who/that + clause","example":"The woman who called is my aunt."},{"case":"Kiểm tra thành phần theo sau","rule":"thing + which/that + clause","example":"This is the book that I mentioned."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"place + where + clause","example":"The café where we met has closed."}],"usage":[{"en":"The woman who called is my aunt.","vi":"Người phụ nữ đã gọi điện là dì của tôi.","icon":"👩","label":"WHO — bổ nghĩa cho danh từ chỉ người"},{"en":"This is the book that I mentioned.","vi":"Đây là cuốn sách mà tôi đã nhắc đến.","icon":"📕","label":"THAT / WHICH — bổ nghĩa cho danh từ chỉ vật"},{"en":"The café where we met has closed.","vi":"Quán cà phê nơi chúng ta gặp nhau đã đóng cửa.","icon":"☕","label":"WHERE — bổ nghĩa cho danh từ chỉ nơi chốn"},{"en":"Students whose work is late must email me.","vi":"Những học sinh nộp bài muộn phải email cho tôi.","icon":"🧑‍🎓","label":"WHOSE — chỉ sự sở hữu"},{"en":"The film (that) we watched was great.","vi":"Bộ phim (mà) chúng tôi xem rất hay.","icon":"✂️","label":"Lược bỏ đại từ quan hệ khi nó làm tân ngữ"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"person + who/that + clause","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"thing + which/that + clause","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"place + where + clause","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["who","that","which","whose","whom","where"],"examples":[{"en":"The woman who called is my aunt.","vi":"Người phụ nữ đã gọi là dì tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"noun","word":"woman","start":4},{"end":13,"role":"pronoun","word":"who","start":10},{"end":20,"role":"verb","word":"called","start":14},{"end":23,"role":"verb","word":"is","start":21},{"end":26,"role":"determiner","word":"my","start":24},{"end":31,"role":"noun","word":"aunt","start":27}]},{"en":"This is the book that I mentioned.","vi":"Đây là cuốn sách tôi đã nhắc.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":7,"role":"verb","word":"is","start":5},{"end":11,"role":"article","word":"the","start":8},{"end":16,"role":"noun","word":"book","start":12},{"end":21,"role":"pronoun","word":"that","start":17},{"end":23,"role":"pronoun","word":"I","start":22},{"end":33,"role":"verb","word":"mentioned","start":24}]},{"en":"The café where we met has closed.","vi":"Quán cà phê nơi chúng ta gặp đã đóng cửa.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"café","start":4},{"end":14,"role":"adverb","word":"where","start":9},{"end":17,"role":"pronoun","word":"we","start":15},{"end":21,"role":"verb","word":"met","start":18},{"end":25,"role":"auxiliary","word":"has","start":22},{"end":32,"role":"verb","word":"closed","start":26}]},{"en":"Students whose work is late must email me.","vi":"Học sinh nộp bài muộn phải gửi email cho tôi.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":8,"role":"noun","word":"Students","start":0},{"end":14,"role":"determiner","word":"whose","start":9},{"end":19,"role":"noun","word":"work","start":15},{"end":22,"role":"verb","word":"is","start":20},{"end":27,"role":"adjective","word":"late","start":23},{"end":32,"role":"modal","word":"must","start":28},{"end":38,"role":"verb","word":"email","start":33},{"end":41,"role":"pronoun","word":"me","start":39}]},{"en":"My laptop, which is old, still works.","vi":"Laptop của tôi, vốn đã cũ, vẫn hoạt động.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"determiner","word":"My","start":0},{"end":9,"role":"noun","word":"laptop","start":3},{"end":16,"role":"pronoun","word":"which","start":11},{"end":19,"role":"verb","word":"is","start":17},{"end":23,"role":"adjective","word":"old","start":20},{"end":30,"role":"adverb","word":"still","start":25},{"end":36,"role":"verb","word":"works","start":31}]},{"en":"The man I spoke to was helpful.","vi":"Người đàn ông tôi nói chuyện cùng rất nhiệt tình.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":7,"role":"noun","word":"man","start":4},{"end":9,"role":"pronoun","word":"I","start":8},{"end":15,"role":"verb","word":"spoke","start":10},{"end":18,"role":"preposition","word":"to","start":16},{"end":22,"role":"verb","word":"was","start":19},{"end":30,"role":"adjective","word":"helpful","start":23}]}],"mistakes":[{"wrong":"The man which lives here is kind.","right":"The man who lives here is kind.","why":"Chỉ người dùng who, không dùng which."},{"wrong":"The book who I read was good.","right":"The book which I read was good.","why":"Chỉ vật dùng which/that, không dùng who."},{"wrong":"This is the house where I live in it.","right":"This is the house where I live.","why":"Where đã thay cho \"in which\" — không lặp giới từ/đại từ."},{"wrong":"The keys that we were looking for them are here.","right":"The keys that we were looking for are here.","why":"That đã làm tân ngữ — không lặp them thừa."}],"timeline":null,"comparison":"**Mệnh đề quan hệ xác định vs không xác định:** Xác định = thông tin THIẾT YẾU để hiểu danh từ, KHÔNG dấu phẩy (*The woman who called is my aunt* — bỏ đi thì không rõ ai). Không xác định = thông tin THÊM, đặt giữa dấu phẩy, bỏ vẫn hiểu (*My aunt, who called yesterday, is a doctor*).","definition":"Relative Clauses dùng **mệnh đề quan hệ** để bổ sung thông tin cho danh từ mà không phải mở câu mới. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"People say that this castle is 500 years old.  →  It ____ that this castle is 500 years old.","opts":[],"answer":"is said","fb":"Kiểu It: It + is said + that, vế sau giữ nguyên"},{"type":"fill","q":"This chair is ____ (comfortable) than that one.","opts":[],"answer":"more comfortable","fb":"comfortable dài → more + tính từ"},{"type":"fill","q":"Which is ____ (dangerous) animal in the world?","opts":[],"answer":"the most dangerous","fb":"in the world → nhất, dangerous dài nên the most"},{"type":"fill","q":"This exercise is ____ (easy) than that one.","opts":[],"answer":"easier","fb":"easy đuôi -y → bỏ y thêm -ier"},{"type":"fill","q":"It was ____ a cold night that the lake froze. (so / such)","opts":[],"answer":"such","fb":"sau chỗ trống là a + adj + danh từ → such"},{"type":"fill","q":"He has ____ many friends that he is never alone. (so / such)","opts":[],"answer":"so","fb":"many luôn đi với so"},{"type":"fill","q":"The man ____ is standing at the door is my father.","opts":[],"answer":["who","that"],"fb":"the man = người → who"},{"type":"fill","q":"I like the picture ____ hangs on the wall.","opts":[],"answer":["which","that"],"fb":"the picture = vật → which"},{"type":"fill","q":"Do you know the girl ____ brother won the race?","opts":[],"answer":"whose","fb":"sau chỗ trống là danh từ brother → whose"},{"type":"fill","q":"Hue, ____ is famous for its food, is my hometown.","opts":[],"answer":"which","fb":"có phẩy + vật → which, cấm that"},{"type":"fill","q":"The people ____ live upstairs are very noisy.","opts":[],"answer":["who","that"],"fb":"people = người → who"},{"type":"fill","q":"This is the dictionary ____ I borrowed from Lan.","opts":[],"answer":["which","that"],"fb":"the dictionary = vật → which"},{"type":"fill","q":"Mr Hung, ____ son studies with me, is a driver.","opts":[],"answer":"whose","fb":"sau chỗ trống là danh từ son → whose"},{"type":"fill","q":"The house ____ roof is red belongs to my aunt.","opts":[],"answer":"whose","fb":"sau chỗ trống là danh từ roof → whose"},{"type":"fill","q":"The song ____ we heard on the radio is very old.","opts":[],"answer":["which","that"],"fb":"the song = vật → which"},{"type":"fill","q":"Rút gọn: The man who is waiting outside wants to see you.","opts":[],"answer":"The man waiting outside wants to see you.","fb":"is waiting chủ động → waiting"},{"type":"fill","q":"Rút gọn: Neil Armstrong was the first man who walked on the Moon.","opts":[],"answer":"Neil Armstrong was the first man to walk on the Moon.","fb":"the first → dùng to V"},{"type":"fill","q":"Rút gọn: The people who live next door are very friendly.","opts":[],"answer":"The people living next door are very friendly.","fb":"live chủ động → living"},{"type":"fill","q":"Viết lại dùng in which: This is the house which my family lived in for ten years.","opts":[],"answer":"This is the house in which my family lived for ten years.","fb":"giới từ in lên trước which thì bỏ in ở cuối"},{"type":"fill","q":"Viết lại dùng what: I don't believe the thing which she told me.","opts":[],"answer":"I don't believe what she told me.","fb":"the thing which gộp lại thành what"},{"type":"fill","q":"Rút gọn: My father was the only person who noticed my mistake.","opts":[],"answer":"My father was the only person to notice my mistake.","fb":"the only → dùng to V"},{"type":"fill","q":"Viết lại dùng with whom: That is the friend who I often go to the cinema with.","opts":[],"answer":"That is the friend with whom I often go to the cinema.","fb":"giới từ with lên trước thì phải dùng whom"},{"type":"fill","q":"Đổi sang gián tiếp: He said: “Someone has stolen my bag.”","opts":[],"answer":"He said (that) someone had stolen his bag.","fb":"has stolen lùi thành had stolen"},{"type":"fill","q":"Đổi sang gián tiếp: She said: “We are learning English now.”","opts":[],"answer":"She said (that) they were learning English then.","fb":"are lùi thành were · now → then"},{"type":"fill","q":"Đổi sang gián tiếp: Huong said: “We are going to have a party next weekend.”","opts":[],"answer":"Huong said (that) they were going to have a party the following weekend.","fb":"are going to lùi thành were going to · next weekend → the following weekend"},{"type":"fill","q":"Who is that man standing ____ the school gate?","opts":[],"answer":"at","fb":"cổng trường là một điểm → at"},{"type":"fill","q":"My friend wants to buy that new car ____ she doesn't have enough money.","opts":[],"answer":"although","fb":"she doesn't have là chủ ngữ + động từ, ý trái ngược → although"},{"type":"fill","q":"The book ____ I borrowed from you is very interesting.  (A who · B whom · C which · D whose)","opts":[],"answer":"C which","fb":"Thay cho vật là quyển sách → which · buổi 13"}]$grammar$::jsonb, 'ai-golden', 38
from public.grammar_topics t where t.slug = 'relative-clauses'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 39. second-conditional
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('second-conditional', 'Second Conditional', 'Câu điều kiện loại 2', 'intermediate', 39)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu điều kiện loại 2', 'Second Conditional dùng **điều kiện loại 2** cho tình huống không có thật hoặc khó xảy ra ở hiện tại/tương lai. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"If I had more time, I would learn Korean.","vi":"Nếu có thêm thời gian, tôi sẽ học tiếng Hàn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":8,"role":"verb","word":"had","start":5},{"end":13,"role":"determiner","word":"more","start":9},{"end":18,"role":"noun","word":"time","start":14},{"end":21,"role":"pronoun","word":"I","start":20},{"end":27,"role":"modal","word":"would","start":22},{"end":33,"role":"verb","word":"learn","start":28},{"end":40,"role":"noun","word":"Korean","start":34}]},{"en":"She would travel more if she were rich.","vi":"Cô ấy sẽ đi du lịch nhiều hơn nếu giàu.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":9,"role":"modal","word":"would","start":4},{"end":16,"role":"verb","word":"travel","start":10},{"end":21,"role":"determiner","word":"more","start":17},{"end":24,"role":"preposition","word":"if","start":22},{"end":28,"role":"pronoun","word":"she","start":25},{"end":33,"role":"verb","word":"were","start":29},{"end":38,"role":"adjective","word":"rich","start":34}]},{"en":"What would you do if you lost your phone?","vi":"Bạn sẽ làm gì nếu mất điện thoại?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"What","start":0},{"end":10,"role":"modal","word":"would","start":5},{"end":14,"role":"pronoun","word":"you","start":11},{"end":17,"role":"verb","word":"do","start":15},{"end":20,"role":"preposition","word":"if","start":18},{"end":24,"role":"pronoun","word":"you","start":21},{"end":29,"role":"verb","word":"lost","start":25},{"end":34,"role":"determiner","word":"your","start":30},{"end":40,"role":"noun","word":"phone","start":35}]},{"en":"If he lived closer, we could meet often.","vi":"Nếu anh ấy sống gần hơn, chúng tôi có thể gặp thường xuyên.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":5,"role":"pronoun","word":"he","start":3},{"end":11,"role":"verb","word":"lived","start":6},{"end":18,"role":"adverb","word":"closer","start":12},{"end":22,"role":"pronoun","word":"we","start":20},{"end":28,"role":"modal","word":"could","start":23},{"end":33,"role":"verb","word":"meet","start":29},{"end":39,"role":"adverb","word":"often","start":34}]},{"en":"Were I you, I would decline.","vi":"Nếu là bạn, tôi sẽ từ chối.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"modal","word":"Were","start":0},{"end":6,"role":"pronoun","word":"I","start":5},{"end":10,"role":"noun","word":"you","start":7},{"end":13,"role":"pronoun","word":"I","start":12},{"end":19,"role":"modal","word":"would","start":14},{"end":27,"role":"verb","word":"decline","start":20}]},{"en":"If it weren't so expensive, I'd buy it.","vi":"Nếu nó không đắt thế, tôi sẽ mua.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":5,"role":"pronoun","word":"it","start":3},{"end":13,"role":"auxiliary","word":"weren't","start":6},{"end":16,"role":"adverb","word":"so","start":14},{"end":26,"role":"adjective","word":"expensive","start":17},{"end":31,"role":"pronoun","word":"I'd","start":28},{"end":35,"role":"verb","word":"buy","start":32},{"end":38,"role":"pronoun","word":"it","start":36}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **If + past simple, would + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"If + past simple, would + V","example":"If I had more time, I would learn Korean."},{"case":"Kiểm tra thành phần theo sau","rule":"If + past simple, could/might + V","example":"She would travel more if she were rich."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Were + S ..., S + would ...","example":"What would you do if you lost your phone?"}],"usage":[{"en":"If I had more time, I would learn Korean.","vi":"Nếu tôi có nhiều thời gian hơn, tôi sẽ học tiếng Hàn.","icon":"🌈","label":"Giả định trái với hiện tại — điều không có thật bây giờ"},{"en":"She would travel more if she were rich.","vi":"Cô ấy sẽ đi du lịch nhiều hơn nếu cô ấy giàu.","icon":"💭","label":"Mơ ước, tưởng tượng điều khó xảy ra"},{"en":"What would you do if you lost your phone?","vi":"Bạn sẽ làm gì nếu bạn làm mất điện thoại?","icon":"❓","label":"Hỏi giả định 'nếu... thì bạn sẽ làm gì?'"},{"en":"If I were you, I would accept the offer.","vi":"Nếu tôi là bạn, tôi sẽ nhận lời đề nghị đó.","icon":"🧑‍🏫","label":"Khuyên nhủ với If I were you"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"If + past simple, would + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"If + past simple, could/might + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Were + S ..., S + would ...","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["if","would","could","might","were","right now"],"examples":[{"en":"If I had more time, I would learn Korean.","vi":"Nếu có thêm thời gian, tôi sẽ học tiếng Hàn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":8,"role":"verb","word":"had","start":5},{"end":13,"role":"determiner","word":"more","start":9},{"end":18,"role":"noun","word":"time","start":14},{"end":21,"role":"pronoun","word":"I","start":20},{"end":27,"role":"modal","word":"would","start":22},{"end":33,"role":"verb","word":"learn","start":28},{"end":40,"role":"noun","word":"Korean","start":34}]},{"en":"She would travel more if she were rich.","vi":"Cô ấy sẽ đi du lịch nhiều hơn nếu giàu.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":9,"role":"modal","word":"would","start":4},{"end":16,"role":"verb","word":"travel","start":10},{"end":21,"role":"determiner","word":"more","start":17},{"end":24,"role":"preposition","word":"if","start":22},{"end":28,"role":"pronoun","word":"she","start":25},{"end":33,"role":"verb","word":"were","start":29},{"end":38,"role":"adjective","word":"rich","start":34}]},{"en":"What would you do if you lost your phone?","vi":"Bạn sẽ làm gì nếu mất điện thoại?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"What","start":0},{"end":10,"role":"modal","word":"would","start":5},{"end":14,"role":"pronoun","word":"you","start":11},{"end":17,"role":"verb","word":"do","start":15},{"end":20,"role":"preposition","word":"if","start":18},{"end":24,"role":"pronoun","word":"you","start":21},{"end":29,"role":"verb","word":"lost","start":25},{"end":34,"role":"determiner","word":"your","start":30},{"end":40,"role":"noun","word":"phone","start":35}]},{"en":"If he lived closer, we could meet often.","vi":"Nếu anh ấy sống gần hơn, chúng tôi có thể gặp thường xuyên.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":5,"role":"pronoun","word":"he","start":3},{"end":11,"role":"verb","word":"lived","start":6},{"end":18,"role":"adverb","word":"closer","start":12},{"end":22,"role":"pronoun","word":"we","start":20},{"end":28,"role":"modal","word":"could","start":23},{"end":33,"role":"verb","word":"meet","start":29},{"end":39,"role":"adverb","word":"often","start":34}]},{"en":"Were I you, I would decline.","vi":"Nếu là bạn, tôi sẽ từ chối.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"modal","word":"Were","start":0},{"end":6,"role":"pronoun","word":"I","start":5},{"end":10,"role":"noun","word":"you","start":7},{"end":13,"role":"pronoun","word":"I","start":12},{"end":19,"role":"modal","word":"would","start":14},{"end":27,"role":"verb","word":"decline","start":20}]},{"en":"If it weren't so expensive, I'd buy it.","vi":"Nếu nó không đắt thế, tôi sẽ mua.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":5,"role":"pronoun","word":"it","start":3},{"end":13,"role":"auxiliary","word":"weren't","start":6},{"end":16,"role":"adverb","word":"so","start":14},{"end":26,"role":"adjective","word":"expensive","start":17},{"end":31,"role":"pronoun","word":"I'd","start":28},{"end":35,"role":"verb","word":"buy","start":32},{"end":38,"role":"pronoun","word":"it","start":36}]}],"mistakes":[{"wrong":"If I was you, I would apologize.","right":"If I were you, I would apologize.","why":"Loại 2 dùng WERE cho mọi ngôi trong giả định."},{"wrong":"If I had money, I will buy a car.","right":"If I had money, I would buy a car.","why":"Loại 2 vế kết quả dùng would, không dùng will."},{"wrong":"If I would have time, I would help.","right":"If I had time, I would help.","why":"Mệnh đề if loại 2 dùng quá khứ đơn, không dùng would."},{"wrong":"If she studied, she will pass.","right":"If she studied, she would pass.","why":"Giả định hiện tại không thực: vế kết quả dùng would."}],"timeline":{"points":[{"note":"dòng thật","label":"Thực tế NOW: không có cánh"},{"note":"dòng tưởng tượng","label":"Giả định: had wings → would fly"}],"caption":"Loại 2 = dòng thời gian TƯỞNG TƯỢNG chạy song song hiện tại: thực tế NOW không có, giả định thì khác (If I had wings, I would fly)."},"comparison":"**Điều kiện loại 2 vs loại 1:** Loại 2 = giả định KHÔNG có thật ở hiện tại / tương lai (*If Jack was playing, they would win* — Jack không chơi). Loại 1 = khả năng CÓ THẬT (*If you are late, I will be angry* — có thể xảy ra).","definition":"Second Conditional dùng **điều kiện loại 2** cho tình huống không có thật hoặc khó xảy ra ở hiện tại/tương lai. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ travel more if she were rich.","answer":["would"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 39
from public.grammar_topics t where t.slug = 'second-conditional'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 40. third-conditional
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('third-conditional', 'Third Conditional', 'Câu điều kiện loại 3', 'intermediate', 40)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu điều kiện loại 3', 'Third Conditional dùng **điều kiện loại 3** để tưởng tượng một quá khứ khác và kết quả đã không xảy ra. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt.', $grammar$[{"en":"If I had left earlier, I would have caught the train.","vi":"Nếu rời đi sớm hơn, tôi đã bắt kịp tàu.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":8,"role":"auxiliary","word":"had","start":5},{"end":13,"role":"verb","word":"left","start":9},{"end":21,"role":"adverb","word":"earlier","start":14},{"end":24,"role":"pronoun","word":"I","start":23},{"end":30,"role":"modal","word":"would","start":25},{"end":35,"role":"auxiliary","word":"have","start":31},{"end":42,"role":"verb","word":"caught","start":36},{"end":46,"role":"article","word":"the","start":43},{"end":52,"role":"noun","word":"train","start":47}]},{"en":"She would have passed if she had studied.","vi":"Cô ấy đã đỗ nếu chịu học.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":9,"role":"modal","word":"would","start":4},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":21,"role":"verb","word":"passed","start":15},{"end":24,"role":"preposition","word":"if","start":22},{"end":28,"role":"pronoun","word":"she","start":25},{"end":32,"role":"auxiliary","word":"had","start":29},{"end":40,"role":"verb","word":"studied","start":33}]},{"en":"Had we known, we would have helped.","vi":"Nếu biết, chúng tôi đã giúp.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":6,"role":"pronoun","word":"we","start":4},{"end":12,"role":"verb","word":"known","start":7},{"end":16,"role":"pronoun","word":"we","start":14},{"end":22,"role":"modal","word":"would","start":17},{"end":27,"role":"auxiliary","word":"have","start":23},{"end":34,"role":"verb","word":"helped","start":28}]},{"en":"If they hadn't called, I might have forgotten.","vi":"Nếu họ không gọi, có lẽ tôi đã quên.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":7,"role":"pronoun","word":"they","start":3},{"end":14,"role":"auxiliary","word":"hadn't","start":8},{"end":21,"role":"verb","word":"called","start":15},{"end":24,"role":"pronoun","word":"I","start":23},{"end":30,"role":"modal","word":"might","start":25},{"end":35,"role":"auxiliary","word":"have","start":31},{"end":45,"role":"verb","word":"forgotten","start":36}]},{"en":"Could you have won if you had trained more?","vi":"Bạn có thể đã thắng nếu tập nhiều hơn không?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"modal","word":"Could","start":0},{"end":9,"role":"pronoun","word":"you","start":6},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":18,"role":"verb","word":"won","start":15},{"end":21,"role":"preposition","word":"if","start":19},{"end":25,"role":"pronoun","word":"you","start":22},{"end":29,"role":"auxiliary","word":"had","start":26},{"end":37,"role":"verb","word":"trained","start":30},{"end":42,"role":"determiner","word":"more","start":38}]},{"en":"He wouldn't have fallen if he had been careful.","vi":"Anh ấy đã không ngã nếu cẩn thận.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":11,"role":"auxiliary","word":"wouldn't","start":3},{"end":16,"role":"auxiliary","word":"have","start":12},{"end":23,"role":"verb","word":"fallen","start":17},{"end":26,"role":"conjunction","word":"if","start":24},{"end":29,"role":"pronoun","word":"he","start":27},{"end":33,"role":"auxiliary","word":"had","start":30},{"end":38,"role":"verb","word":"been","start":34},{"end":46,"role":"adjective","word":"careful","start":39}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **If + had + V3, would have + V3** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"If + had + V3, would have + V3","example":"If I had left earlier, I would have caught the train."},{"case":"Kiểm tra thành phần theo sau","rule":"If + had + V3, could/might have + V3","example":"She would have passed if she had studied."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Had + S + V3, ...","example":"Had we known, we would have helped."}],"usage":[{"en":"If I had left earlier, I would have caught the train.","vi":"Nếu tôi rời đi sớm hơn, tôi đã bắt kịp chuyến tàu.","icon":"🚉","label":"Giả định trái với quá khứ — việc đã không xảy ra"},{"en":"She would have passed if she had studied.","vi":"Cô ấy đã đỗ rồi nếu cô ấy chịu học.","icon":"😞","label":"Bày tỏ tiếc nuối, trách móc về quá khứ"},{"en":"Had we known, we would have helped.","vi":"Nếu chúng tôi biết thì chúng tôi đã giúp rồi.","icon":"🎩","label":"Đảo ngữ trang trọng: Had + S + V3 (bỏ if)"},{"en":"If they hadn't called, I might have forgotten.","vi":"Nếu họ không gọi, có lẽ tôi đã quên mất.","icon":"🎲","label":"Kết quả không chắc chắn với might/could have"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"If + had + V3, would have + V3","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"If + had + V3, could/might have + V3","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Had + S + V3, ...","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["If + had + P2","would have + P2","yesterday","last year"],"examples":[{"en":"If I had left earlier, I would have caught the train.","vi":"Nếu rời đi sớm hơn, tôi đã bắt kịp tàu.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":8,"role":"auxiliary","word":"had","start":5},{"end":13,"role":"verb","word":"left","start":9},{"end":21,"role":"adverb","word":"earlier","start":14},{"end":24,"role":"pronoun","word":"I","start":23},{"end":30,"role":"modal","word":"would","start":25},{"end":35,"role":"auxiliary","word":"have","start":31},{"end":42,"role":"verb","word":"caught","start":36},{"end":46,"role":"article","word":"the","start":43},{"end":52,"role":"noun","word":"train","start":47}]},{"en":"She would have passed if she had studied.","vi":"Cô ấy đã đỗ nếu chịu học.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":9,"role":"modal","word":"would","start":4},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":21,"role":"verb","word":"passed","start":15},{"end":24,"role":"preposition","word":"if","start":22},{"end":28,"role":"pronoun","word":"she","start":25},{"end":32,"role":"auxiliary","word":"had","start":29},{"end":40,"role":"verb","word":"studied","start":33}]},{"en":"Had we known, we would have helped.","vi":"Nếu biết, chúng tôi đã giúp.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":6,"role":"pronoun","word":"we","start":4},{"end":12,"role":"verb","word":"known","start":7},{"end":16,"role":"pronoun","word":"we","start":14},{"end":22,"role":"modal","word":"would","start":17},{"end":27,"role":"auxiliary","word":"have","start":23},{"end":34,"role":"verb","word":"helped","start":28}]},{"en":"If they hadn't called, I might have forgotten.","vi":"Nếu họ không gọi, có lẽ tôi đã quên.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":7,"role":"pronoun","word":"they","start":3},{"end":14,"role":"auxiliary","word":"hadn't","start":8},{"end":21,"role":"verb","word":"called","start":15},{"end":24,"role":"pronoun","word":"I","start":23},{"end":30,"role":"modal","word":"might","start":25},{"end":35,"role":"auxiliary","word":"have","start":31},{"end":45,"role":"verb","word":"forgotten","start":36}]},{"en":"Could you have won if you had trained more?","vi":"Bạn có thể đã thắng nếu tập nhiều hơn không?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"modal","word":"Could","start":0},{"end":9,"role":"pronoun","word":"you","start":6},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":18,"role":"verb","word":"won","start":15},{"end":21,"role":"preposition","word":"if","start":19},{"end":25,"role":"pronoun","word":"you","start":22},{"end":29,"role":"auxiliary","word":"had","start":26},{"end":37,"role":"verb","word":"trained","start":30},{"end":42,"role":"determiner","word":"more","start":38}]},{"en":"He wouldn't have fallen if he had been careful.","vi":"Anh ấy đã không ngã nếu cẩn thận.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":11,"role":"auxiliary","word":"wouldn't","start":3},{"end":16,"role":"auxiliary","word":"have","start":12},{"end":23,"role":"verb","word":"fallen","start":17},{"end":26,"role":"conjunction","word":"if","start":24},{"end":29,"role":"pronoun","word":"he","start":27},{"end":33,"role":"auxiliary","word":"had","start":30},{"end":38,"role":"verb","word":"been","start":34},{"end":46,"role":"adjective","word":"careful","start":39}]}],"mistakes":[{"wrong":"If I had studied, I would passed.","right":"If I had studied, I would have passed.","why":"Loại 3 vế kết quả cần would HAVE + P2."},{"wrong":"If I would have known, I would have come.","right":"If I had known, I would have come.","why":"Mệnh đề if loại 3 dùng past perfect (had + P2), không dùng would have."},{"wrong":"If she had came earlier, she would have seen him.","right":"If she had come earlier, she would have seen him.","why":"P2 của come là come sau had."},{"wrong":"If they had left, they would catch the train.","right":"If they had left, they would have caught the train.","why":"Việc đã qua: vế kết quả loại 3 dùng would have + P2."}],"timeline":{"points":[{"note":"quá khứ thật","label":"Thực tế: không học → trượt"},{"note":"quá khứ tưởng tượng","label":"Giả định: had studied → would have passed"}],"caption":"Cả điều kiện lẫn kết quả đều nằm trong quá khứ đã đóng — chỉ là dòng thời gian tưởng tượng chạy song song dòng thật."},"comparison":"**Điều kiện loại 3 vs loại 2:** Loại 3 = giả định trái với QUÁ KHỨ, không thể đổi (*If you had seen him, you could have spoken to him* — nhưng đã không gặp). Loại 2 = giả định trái với HIỆN TẠI / tương lai (*If I had his address, I could write to him* — giờ không có địa chỉ).","definition":"Third Conditional dùng **điều kiện loại 3** để tưởng tượng một quá khứ khác và kết quả đã không xảy ra. Bài học tập trung vào **ý nghĩa**, **cấu trúc** và cách tránh lỗi dịch máy móc thường gặp ở người Việt."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ have passed if she had studied.","answer":["would"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 40
from public.grammar_topics t where t.slug = 'third-conditional'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 41. modals-deduction
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('modals-deduction', 'Modals: Deduction (must/might/can''t)', 'Khuyết thiếu: suy đoán (must/might/can''t)', 'intermediate', 41)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Khuyết thiếu: suy đoán (must/might/can''t)', '**Động từ khuyết thiếu chỉ sự suy đoán** (như must, might, can''t) cho phép người nói đánh giá mức độ chắc chắn của một sự việc dựa trên các bằng chứng thực tế. Chúng giúp thiết lập phạm vi tin cậy của thông tin, từ khẳng định chắc chắn (must) đến khả năng có thể xảy ra (might/may) hoặc sự bất khả thi (can''t).', $grammar$[{"en":"She must be at work; her car is gone.","vi":"Chắc cô ấy đang ở chỗ làm; xe cô ấy không còn đây.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":8,"role":"modal","word":"must","start":4},{"end":11,"role":"verb","word":"be","start":9},{"end":14,"role":"preposition","word":"at","start":12},{"end":19,"role":"noun","word":"work","start":15},{"end":24,"role":"pronoun","word":"her","start":21},{"end":28,"role":"noun","word":"car","start":25},{"end":31,"role":"auxiliary","word":"is","start":29},{"end":36,"role":"adjective","word":"gone","start":32}]},{"en":"He might know the answer.","vi":"Có thể anh ấy biết đáp án.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":8,"role":"modal","word":"might","start":3},{"end":13,"role":"verb","word":"know","start":9},{"end":17,"role":"article","word":"the","start":14},{"end":24,"role":"noun","word":"answer","start":18}]},{"en":"That can't be true.","vi":"Điều đó không thể đúng.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"That","start":0},{"end":10,"role":"modal","word":"can't","start":5},{"end":13,"role":"auxiliary","word":"be","start":11},{"end":18,"role":"adjective","word":"true","start":14}]},{"en":"They may arrive late.","vi":"Có thể họ sẽ đến muộn.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":8,"role":"modal","word":"may","start":5},{"end":15,"role":"verb","word":"arrive","start":9},{"end":20,"role":"adverb","word":"late","start":16}]},{"en":"This could be the right key.","vi":"Đây có thể là chìa khóa đúng.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":10,"role":"modal","word":"could","start":5},{"end":13,"role":"auxiliary","word":"be","start":11},{"end":17,"role":"article","word":"the","start":14},{"end":23,"role":"adjective","word":"right","start":18},{"end":27,"role":"noun","word":"key","start":24}]},{"en":"You must be tired after the journey.","vi":"Hẳn bạn mệt sau chuyến đi.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":8,"role":"modal","word":"must","start":4},{"end":11,"role":"auxiliary","word":"be","start":9},{"end":17,"role":"adjective","word":"tired","start":12},{"end":23,"role":"preposition","word":"after","start":18},{"end":27,"role":"article","word":"the","start":24},{"end":35,"role":"noun","word":"journey","start":28}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **must + V: gần như chắc chắn** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"must + V: gần như chắc chắn","example":"She must be at work; her car is gone."},{"case":"Kiểm tra thành phần theo sau","rule":"might/may/could + V: có thể","example":"He might know the answer."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"can't + V: gần như không thể","example":"That can't be true."}],"usage":[{"en":"She must be at work; her car is gone.","vi":"Chắc chắn cô ấy đang ở chỗ làm; xe cô ấy không còn ở đây.","icon":"🕵️","label":"MUST — suy đoán gần như chắc chắn đúng"},{"en":"He might know the answer.","vi":"Có thể anh ấy biết câu trả lời.","icon":"🤷","label":"MIGHT / MAY — suy đoán có thể đúng, chưa chắc"},{"en":"That can't be true. He was with me all day.","vi":"Điều đó không thể đúng được. Anh ấy ở với tôi cả ngày mà.","icon":"🙅","label":"CAN'T — suy đoán chắc chắn KHÔNG thể đúng"},{"en":"The keys could be in the drawer.","vi":"Chìa khóa có thể nằm trong ngăn kéo.","icon":"🌦️","label":"COULD — nêu một khả năng trong nhiều khả năng"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"must + V: gần như chắc chắn","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"might/may/could + V: có thể","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"can't + V: gần như không thể","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["must","can't","might","could","may"],"examples":[{"en":"She must be at work; her car is gone.","vi":"Chắc cô ấy đang ở chỗ làm; xe cô ấy không còn đây.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":8,"role":"modal","word":"must","start":4},{"end":11,"role":"verb","word":"be","start":9},{"end":14,"role":"preposition","word":"at","start":12},{"end":19,"role":"noun","word":"work","start":15},{"end":24,"role":"pronoun","word":"her","start":21},{"end":28,"role":"noun","word":"car","start":25},{"end":31,"role":"auxiliary","word":"is","start":29},{"end":36,"role":"adjective","word":"gone","start":32}]},{"en":"He might know the answer.","vi":"Có thể anh ấy biết đáp án.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":8,"role":"modal","word":"might","start":3},{"end":13,"role":"verb","word":"know","start":9},{"end":17,"role":"article","word":"the","start":14},{"end":24,"role":"noun","word":"answer","start":18}]},{"en":"That can't be true.","vi":"Điều đó không thể đúng.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"That","start":0},{"end":10,"role":"modal","word":"can't","start":5},{"end":13,"role":"auxiliary","word":"be","start":11},{"end":18,"role":"adjective","word":"true","start":14}]},{"en":"They may arrive late.","vi":"Có thể họ sẽ đến muộn.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":8,"role":"modal","word":"may","start":5},{"end":15,"role":"verb","word":"arrive","start":9},{"end":20,"role":"adverb","word":"late","start":16}]},{"en":"This could be the right key.","vi":"Đây có thể là chìa khóa đúng.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":10,"role":"modal","word":"could","start":5},{"end":13,"role":"auxiliary","word":"be","start":11},{"end":17,"role":"article","word":"the","start":14},{"end":23,"role":"adjective","word":"right","start":18},{"end":27,"role":"noun","word":"key","start":24}]},{"en":"You must be tired after the journey.","vi":"Hẳn bạn mệt sau chuyến đi.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":8,"role":"modal","word":"must","start":4},{"end":11,"role":"auxiliary","word":"be","start":9},{"end":17,"role":"adjective","word":"tired","start":12},{"end":23,"role":"preposition","word":"after","start":18},{"end":27,"role":"article","word":"the","start":24},{"end":35,"role":"noun","word":"journey","start":28}]}],"mistakes":[{"wrong":"He must to be tired.","right":"He must be tired.","why":"Sau must là động từ nguyên thể không to."},{"wrong":"She must has left already.","right":"She must have left already.","why":"Suy đoán quá khứ dùng must HAVE + P2 (have nguyên thể)."},{"wrong":"It can't to be true.","right":"It can't be true.","why":"Sau can't là động từ nguyên thể không to."},{"wrong":"He can't saw me yesterday.","right":"He can't have seen me yesterday.","why":"Phủ định suy đoán quá khứ dùng can't have + P2."}],"timeline":null,"comparison":"**Suy đoán (deduction) vs Điều kiện quá khứ:** *He must have heard the noise* = suy luận logic từ bằng chứng (chắc chắn anh ấy đã nghe). *He would have heard the noise (if he had been there)* = kết quả giả định của điều kiện không có thật. Must have = kết luận; would have = tưởng tượng.","definition":"**Động từ khuyết thiếu chỉ sự suy đoán** (như must, might, can't) cho phép người nói đánh giá mức độ chắc chắn của một sự việc dựa trên các bằng chứng thực tế. Chúng giúp thiết lập phạm vi tin cậy của thông tin, từ khẳng định chắc chắn (must) đến khả năng có thể xảy ra (might/may) hoặc sự bất khả thi (can't)."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Đổi sang gián tiếp: My teacher said to us: “You may use dictionaries for this test.”","opts":[],"answer":"My teacher told us (that) we might use dictionaries for that test.","fb":"may lùi thành might · this → that"}]$grammar$::jsonb, 'ai-golden', 41
from public.grammar_topics t where t.slug = 'modals-deduction'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 42. question-tags
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('question-tags', 'Question Tags', 'Câu hỏi đuôi', 'intermediate', 42)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu hỏi đuôi', '**Câu hỏi đuôi** là các cụm từ ngắn được thêm vào cuối câu khẳng định hoặc phủ định để xác nhận thông tin, bày tỏ sự ngạc nhiên hoặc mời người nghe đồng tình. Cấu trúc phổ biến là câu khẳng định đi với đuôi phủ định và ngược lại.', $grammar$[{"en":"You're coming, aren't you?","vi":"Bạn sẽ đến, phải không?","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"pronoun","word":"You're","start":0},{"end":13,"role":"verb","word":"coming","start":7},{"end":21,"role":"auxiliary","word":"aren't","start":15},{"end":25,"role":"pronoun","word":"you","start":22}]},{"en":"She doesn't drive, does she?","vi":"Cô ấy không lái xe, đúng không?","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":11,"role":"auxiliary","word":"doesn't","start":4},{"end":17,"role":"verb","word":"drive","start":12},{"end":23,"role":"auxiliary","word":"does","start":19},{"end":27,"role":"pronoun","word":"she","start":24}]},{"en":"They left early, didn't they?","vi":"Họ đã rời đi sớm, phải không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":9,"role":"verb","word":"left","start":5},{"end":15,"role":"adverb","word":"early","start":10},{"end":23,"role":"auxiliary","word":"didn't","start":17},{"end":28,"role":"pronoun","word":"they","start":24}]},{"en":"Let's start, shall we?","vi":"Chúng ta bắt đầu nhé?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"modal","word":"Let's","start":0},{"end":11,"role":"verb","word":"start","start":6},{"end":18,"role":"modal","word":"shall","start":13},{"end":21,"role":"pronoun","word":"we","start":19}]},{"en":"I'm late, aren't I?","vi":"Tôi muộn, phải không?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"I'm","start":0},{"end":8,"role":"adjective","word":"late","start":4},{"end":16,"role":"auxiliary","word":"aren't","start":10},{"end":18,"role":"pronoun","word":"I","start":17}]},{"en":"Nobody called, did they?","vi":"Không ai gọi, phải không?","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"noun","word":"Nobody","start":0},{"end":13,"role":"verb","word":"called","start":7},{"end":18,"role":"auxiliary","word":"did","start":15},{"end":23,"role":"pronoun","word":"they","start":19}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **mệnh đề khẳng định, trợ động từ phủ định + đại từ?** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"mệnh đề khẳng định, trợ động từ phủ định + đại từ?","example":"You're coming, aren't you?"},{"case":"Kiểm tra thành phần theo sau","rule":"mệnh đề phủ định, trợ động từ khẳng định + đại từ?","example":"She doesn't drive, does she?"},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Let's ..., shall we?","example":"They left early, didn't they?"}],"usage":[{"en":"You're coming to the party, aren't you?","vi":"Bạn sẽ đến bữa tiệc, đúng không?","icon":"✅","label":"Câu khẳng định + đuôi phủ định"},{"en":"She doesn't drive, does she?","vi":"Cô ấy không lái xe, phải không?","icon":"❌","label":"Câu phủ định + đuôi khẳng định"},{"en":"They left early, didn't they?","vi":"Họ về sớm, đúng không nhỉ?","icon":"🔁","label":"Đuôi lặp lại đúng trợ động từ và thì của mệnh đề chính"},{"en":"Let's start, shall we?","vi":"Chúng ta bắt đầu nhé?","icon":"🤝","label":"Trường hợp đặc biệt: Let's... đuôi là shall we?"},{"en":"It's cold today, isn't it?","vi":"Hôm nay trời lạnh nhỉ?","icon":"🗣️","label":"Xuống giọng = xác nhận; lên giọng = hỏi thật"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"mệnh đề khẳng định, trợ động từ phủ định + đại từ?","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"mệnh đề phủ định, trợ động từ khẳng định + đại từ?","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Let's ..., shall we?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["isn't it?","aren't you?","don't you?","will you?","shall we?"],"examples":[{"en":"You're coming, aren't you?","vi":"Bạn sẽ đến, phải không?","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"pronoun","word":"You're","start":0},{"end":13,"role":"verb","word":"coming","start":7},{"end":21,"role":"auxiliary","word":"aren't","start":15},{"end":25,"role":"pronoun","word":"you","start":22}]},{"en":"She doesn't drive, does she?","vi":"Cô ấy không lái xe, đúng không?","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":11,"role":"auxiliary","word":"doesn't","start":4},{"end":17,"role":"verb","word":"drive","start":12},{"end":23,"role":"auxiliary","word":"does","start":19},{"end":27,"role":"pronoun","word":"she","start":24}]},{"en":"They left early, didn't they?","vi":"Họ đã rời đi sớm, phải không?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":9,"role":"verb","word":"left","start":5},{"end":15,"role":"adverb","word":"early","start":10},{"end":23,"role":"auxiliary","word":"didn't","start":17},{"end":28,"role":"pronoun","word":"they","start":24}]},{"en":"Let's start, shall we?","vi":"Chúng ta bắt đầu nhé?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"modal","word":"Let's","start":0},{"end":11,"role":"verb","word":"start","start":6},{"end":18,"role":"modal","word":"shall","start":13},{"end":21,"role":"pronoun","word":"we","start":19}]},{"en":"I'm late, aren't I?","vi":"Tôi muộn, phải không?","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"I'm","start":0},{"end":8,"role":"adjective","word":"late","start":4},{"end":16,"role":"auxiliary","word":"aren't","start":10},{"end":18,"role":"pronoun","word":"I","start":17}]},{"en":"Nobody called, did they?","vi":"Không ai gọi, phải không?","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"noun","word":"Nobody","start":0},{"end":13,"role":"verb","word":"called","start":7},{"end":18,"role":"auxiliary","word":"did","start":15},{"end":23,"role":"pronoun","word":"they","start":19}]}],"mistakes":[{"wrong":"You are a student, are you?","right":"You are a student, aren't you?","why":"Câu khẳng định đi với tag PHỦ ĐỊNH."},{"wrong":"She can swim, can she?","right":"She can swim, can't she?","why":"Câu khẳng định phải đi với tag phủ định."},{"wrong":"You travel a lot, travel you?","right":"You travel a lot, don't you?","why":"Động từ thường hiện tại đơn dùng do/does trong tag."},{"wrong":"He won't be late, won't he?","right":"He won't be late, will he?","why":"Câu phủ định đi với tag KHẲNG ĐỊNH."}],"timeline":null,"comparison":"**Question tag vs câu hỏi thường:** Tag là câu hỏi mini gắn CUỐI câu kể để xác nhận/hỏi ý kiến (*He is Spanish, isn't he?*), còn câu hỏi thường đảo trợ động từ lên ĐẦU (*Is he Spanish?*). Quy tắc vàng: câu khẳng định → tag phủ định, câu phủ định → tag khẳng định.","definition":"**Câu hỏi đuôi** là các cụm từ ngắn được thêm vào cuối câu khẳng định hoặc phủ định để xác nhận thông tin, bày tỏ sự ngạc nhiên hoặc mời người nghe đồng tình. Cấu trúc phổ biến là câu khẳng định đi với đuôi phủ định và ngược lại."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"She is a teacher, ___?","options":["is she","isn't she","doesn't she"],"correct_answer":"isn't she","explanation":"Mệnh đề khẳng định với is đi cùng đuôi phủ định isn't she."},{"type":"multiple_choice","question":"They don't live here, ___?","options":["do they","don't they","are they"],"correct_answer":"do they","explanation":"Mệnh đề phủ định với don't đi cùng đuôi khẳng định do they."},{"type":"multiple_choice","question":"You can swim, ___?","options":["do you","can't you","can you"],"correct_answer":"can't you","explanation":"Giữ trợ động từ can và đảo khẳng định thành phủ định."},{"type":"multiple_choice","question":"Let's go, ___?","options":["shall we","will you","do we"],"correct_answer":"shall we","explanation":"Với lời rủ rê Let's..., đuôi thông dụng là shall we?"}]$grammar$::jsonb, 'ai-golden', 42
from public.grammar_topics t where t.slug = 'question-tags'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
