insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('phrasal-verbs', 'Phrasal Verbs (intro)', 'Cụm động từ (nhập môn)', 'intermediate', 43)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Cụm động từ (nhập môn)', '**Cụm động từ** là sự kết hợp của một động từ với một hoặc hai tiểu từ (trạng từ hoặc giới từ) để tạo thành một đơn vị nghĩa mới, thường khác biệt với nghĩa gốc của động từ. Ví dụ: *look up*, *give in*. Chúng đóng vai trò quan trọng trong giao tiếp tiếng Anh tự nhiên.', $grammar$[{"en":"Please turn off the lights.","vi":"Vui lòng tắt đèn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"adverb","word":"Please","start":0},{"end":11,"role":"verb","word":"turn","start":7},{"end":15,"role":"adverb","word":"off","start":12},{"end":19,"role":"article","word":"the","start":16},{"end":26,"role":"noun","word":"lights","start":20}]},{"en":"I ran into an old friend.","vi":"Tôi tình cờ gặp một người bạn cũ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"verb","word":"ran","start":2},{"end":10,"role":"preposition","word":"into","start":6},{"end":13,"role":"article","word":"an","start":11},{"end":17,"role":"adjective","word":"old","start":14},{"end":24,"role":"noun","word":"friend","start":18}]},{"en":"She looked after the children.","vi":"Cô ấy chăm sóc bọn trẻ.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"verb","word":"looked","start":4},{"end":16,"role":"preposition","word":"after","start":11},{"end":20,"role":"article","word":"the","start":17},{"end":29,"role":"noun","word":"children","start":21}]},{"en":"Don't give up.","vi":"Đừng bỏ cuộc.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"auxiliary","word":"Don't","start":0},{"end":10,"role":"verb","word":"give","start":6},{"end":13,"role":"adverb","word":"up","start":11}]},{"en":"Please pick it up.","vi":"Vui lòng nhặt nó lên.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"adverb","word":"Please","start":0},{"end":11,"role":"verb","word":"pick","start":7},{"end":14,"role":"pronoun","word":"it","start":12},{"end":17,"role":"adverb","word":"up","start":15}]},{"en":"We need to find out the truth.","vi":"Chúng ta cần tìm ra sự thật.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"verb","word":"need","start":3},{"end":10,"role":"preposition","word":"to","start":8},{"end":15,"role":"verb","word":"find","start":11},{"end":19,"role":"adverb","word":"out","start":16},{"end":23,"role":"article","word":"the","start":20},{"end":29,"role":"noun","word":"truth","start":24}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **verb + particle** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"verb + particle","example":"Please turn off the lights."},{"case":"Kiểm tra thành phần theo sau","rule":"verb + particle + object","example":"I ran into an old friend."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"verb + object + particle (cụm tách được)","example":"She looked after the children."}],"usage":[{"en":"Please turn off the lights. / Turn them off.","vi":"Làm ơn tắt đèn. / Tắt chúng đi.","icon":"💡","label":"Cụm tách được — tân ngữ chen giữa động từ và tiểu từ"},{"en":"I ran into an old friend yesterday.","vi":"Hôm qua tôi tình cờ gặp một người bạn cũ.","icon":"🤝","label":"Cụm không tách được — tân ngữ luôn đứng sau"},{"en":"She looked after the children all day.","vi":"Cô ấy chăm sóc bọn trẻ cả ngày.","icon":"👶","label":"Nghĩa của cụm khác hẳn nghĩa động từ gốc"},{"en":"Don't give up! Keep going.","vi":"Đừng bỏ cuộc! Cứ tiếp tục đi.","icon":"🚀","label":"Cụm động từ không cần tân ngữ"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"verb + particle","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"verb + particle + object","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"verb + object + particle (cụm tách được)","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["give up","take off","find out","look out","get on","break down","put off"],"examples":[{"en":"Please turn off the lights.","vi":"Vui lòng tắt đèn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"adverb","word":"Please","start":0},{"end":11,"role":"verb","word":"turn","start":7},{"end":15,"role":"adverb","word":"off","start":12},{"end":19,"role":"article","word":"the","start":16},{"end":26,"role":"noun","word":"lights","start":20}]},{"en":"I ran into an old friend.","vi":"Tôi tình cờ gặp một người bạn cũ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"verb","word":"ran","start":2},{"end":10,"role":"preposition","word":"into","start":6},{"end":13,"role":"article","word":"an","start":11},{"end":17,"role":"adjective","word":"old","start":14},{"end":24,"role":"noun","word":"friend","start":18}]},{"en":"She looked after the children.","vi":"Cô ấy chăm sóc bọn trẻ.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"verb","word":"looked","start":4},{"end":16,"role":"preposition","word":"after","start":11},{"end":20,"role":"article","word":"the","start":17},{"end":29,"role":"noun","word":"children","start":21}]},{"en":"Don't give up.","vi":"Đừng bỏ cuộc.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"auxiliary","word":"Don't","start":0},{"end":10,"role":"verb","word":"give","start":6},{"end":13,"role":"adverb","word":"up","start":11}]},{"en":"Please pick it up.","vi":"Vui lòng nhặt nó lên.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"adverb","word":"Please","start":0},{"end":11,"role":"verb","word":"pick","start":7},{"end":14,"role":"pronoun","word":"it","start":12},{"end":17,"role":"adverb","word":"up","start":15}]},{"en":"We need to find out the truth.","vi":"Chúng ta cần tìm ra sự thật.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"verb","word":"need","start":3},{"end":10,"role":"preposition","word":"to","start":8},{"end":15,"role":"verb","word":"find","start":11},{"end":19,"role":"adverb","word":"out","start":16},{"end":23,"role":"article","word":"the","start":20},{"end":29,"role":"noun","word":"truth","start":24}]}],"mistakes":[{"wrong":"Don't throw away it.","right":"Don't throw it away.","why":"Tân ngữ là đại từ (it) phải đứng GIỮA động từ và particle."},{"wrong":"Please turn on it.","right":"Please turn it on.","why":"Đại từ (it) đứng giữa turn và on."},{"wrong":"I gave up to smoke.","right":"I gave up smoking.","why":"Sau give up dùng V-ing, không dùng to-infinitive."},{"wrong":"Why did you run away of me?","right":"Why did you run away from me?","why":"Phrasal verb run away đi với from, không dùng of."}],"timeline":null,"comparison":"**Phrasal verb vs Prepositional verb:** Phrasal verb (verb + particle) cho phép tân ngữ danh từ đứng trước HOẶC sau particle (*throw the box away / throw away the box*) — nhưng đại từ BẮT BUỘC đứng giữa (*throw it away*). Prepositional verb có giới từ cố định, tân ngữ luôn đứng sau (*look at it*, không tách được).","definition":"**Cụm động từ** là sự kết hợp của một động từ với một hoặc hai tiểu từ (trạng từ hoặc giới từ) để tạo thành một đơn vị nghĩa mới, thường khác biệt với nghĩa gốc của động từ. Ví dụ: *look up*, *give in*. Chúng đóng vai trò quan trọng trong giao tiếp tiếng Anh tự nhiên."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"My family decided ____ (buy) a new fridge.","opts":[],"answer":"to buy","fb":"decide nằm nhóm to V"},{"type":"fill","q":"I hope ____ (pass) the entrance exam next year.","opts":[],"answer":"to pass","fb":"hope nằm nhóm to V"},{"type":"fill","q":"Remember ____ (water) the flowers this afternoon.","opts":[],"answer":"to water","fb":"dặn việc chưa làm → to V"},{"type":"fill","q":"The teacher wants us ____ (be) quiet in the library.","opts":[],"answer":"to be","fb":"want ai làm gì → vẫn to V"}]$grammar$::jsonb, 'ai-golden', 43
from public.grammar_topics t where t.slug = 'phrasal-verbs'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 44. past-perfect-continuous
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('past-perfect-continuous', 'Past Perfect Continuous', 'Quá khứ hoàn thành tiếp diễn', 'advanced', 44)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Quá khứ hoàn thành tiếp diễn', 'Thì **Quá khứ hoàn thành tiếp diễn** (Past Perfect Continuous) với cấu trúc ''had been'' + V-ing, dùng để nhấn mạnh khoảng thời gian diễn ra liên tục của một hành động trong quá khứ cho đến trước một sự kiện hoặc kết quả khác trong quá khứ.', $grammar$[{"en":"I had been waiting for an hour when the bus came.","vi":"Tôi đã chờ một tiếng khi xe buýt đến.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"auxiliary","word":"had","start":2},{"end":10,"role":"auxiliary","word":"been","start":6},{"end":18,"role":"verb","word":"waiting","start":11},{"end":22,"role":"preposition","word":"for","start":19},{"end":25,"role":"article","word":"an","start":23},{"end":30,"role":"noun","word":"hour","start":26},{"end":35,"role":"conjunction","word":"when","start":31},{"end":39,"role":"article","word":"the","start":36},{"end":43,"role":"noun","word":"bus","start":40},{"end":48,"role":"verb","word":"came","start":44}]},{"en":"She was tired because she had been working all night.","vi":"Cô ấy mệt vì đã làm việc cả đêm.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"was","start":4},{"end":13,"role":"adjective","word":"tired","start":8},{"end":21,"role":"conjunction","word":"because","start":14},{"end":25,"role":"pronoun","word":"she","start":22},{"end":29,"role":"auxiliary","word":"had","start":26},{"end":34,"role":"auxiliary","word":"been","start":30},{"end":42,"role":"verb","word":"working","start":35},{"end":46,"role":"determiner","word":"all","start":43},{"end":52,"role":"noun","word":"night","start":47}]},{"en":"They hadn't been living there long.","vi":"Họ đã chưa sống ở đó lâu.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":11,"role":"auxiliary","word":"hadn't","start":5},{"end":16,"role":"auxiliary","word":"been","start":12},{"end":23,"role":"verb","word":"living","start":17},{"end":29,"role":"adverb","word":"there","start":24},{"end":34,"role":"adverb","word":"long","start":30}]},{"en":"Had it been raining before you arrived?","vi":"Trời đã mưa trước khi bạn đến à?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":6,"role":"pronoun","word":"it","start":4},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":19,"role":"verb","word":"raining","start":12},{"end":26,"role":"preposition","word":"before","start":20},{"end":30,"role":"pronoun","word":"you","start":27},{"end":38,"role":"verb","word":"arrived","start":31}]},{"en":"His hands were dirty because he had been gardening.","vi":"Tay anh ấy bẩn vì đã làm vườn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"determiner","word":"His","start":0},{"end":9,"role":"noun","word":"hands","start":4},{"end":14,"role":"auxiliary","word":"were","start":10},{"end":20,"role":"adjective","word":"dirty","start":15},{"end":28,"role":"conjunction","word":"because","start":21},{"end":31,"role":"pronoun","word":"he","start":29},{"end":35,"role":"auxiliary","word":"had","start":32},{"end":40,"role":"auxiliary","word":"been","start":36},{"end":50,"role":"verb","word":"gardening","start":41}]},{"en":"We had been talking until midnight.","vi":"Chúng tôi đã trò chuyện đến nửa đêm.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":6,"role":"auxiliary","word":"had","start":3},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":19,"role":"verb","word":"talking","start":12},{"end":25,"role":"preposition","word":"until","start":20},{"end":34,"role":"noun","word":"midnight","start":26}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + had been + V-ing** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + had been + V-ing","example":"I had been waiting for an hour when the bus came."},{"case":"Kiểm tra thành phần theo sau","rule":"S + had not been + V-ing","example":"She was tired because she had been working all night."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Had + S + been + V-ing?","example":"They hadn't been living there long."}],"usage":[{"en":"I had been waiting for an hour when the bus came.","vi":"Tôi đã đợi suốt một tiếng thì xe buýt mới đến.","icon":"🚌","label":"Hành động kéo dài liên tục TRƯỚC một mốc quá khứ"},{"en":"She was tired because she had been working all night.","vi":"Cô ấy mệt vì đã làm việc suốt đêm.","icon":"😩","label":"Giải thích nguyên nhân của trạng thái trong quá khứ"},{"en":"They hadn't been living there long when the flood hit.","vi":"Họ chưa sống ở đó được bao lâu thì lũ ập đến.","icon":"🏠","label":"Phủ định — quá trình chưa kéo dài lâu tính đến mốc quá khứ"},{"en":"Had it been raining before you arrived?","vi":"Trước khi bạn đến trời có mưa không?","icon":"🌧️","label":"Hỏi về quá trình diễn ra trước mốc quá khứ"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + had been + V-ing","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + had not been + V-ing","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Had + S + been + V-ing?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["by","before","when","for","since","this time"],"examples":[{"en":"I had been waiting for an hour when the bus came.","vi":"Tôi đã chờ một tiếng khi xe buýt đến.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"auxiliary","word":"had","start":2},{"end":10,"role":"auxiliary","word":"been","start":6},{"end":18,"role":"verb","word":"waiting","start":11},{"end":22,"role":"preposition","word":"for","start":19},{"end":25,"role":"article","word":"an","start":23},{"end":30,"role":"noun","word":"hour","start":26},{"end":35,"role":"conjunction","word":"when","start":31},{"end":39,"role":"article","word":"the","start":36},{"end":43,"role":"noun","word":"bus","start":40},{"end":48,"role":"verb","word":"came","start":44}]},{"en":"She was tired because she had been working all night.","vi":"Cô ấy mệt vì đã làm việc cả đêm.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"was","start":4},{"end":13,"role":"adjective","word":"tired","start":8},{"end":21,"role":"conjunction","word":"because","start":14},{"end":25,"role":"pronoun","word":"she","start":22},{"end":29,"role":"auxiliary","word":"had","start":26},{"end":34,"role":"auxiliary","word":"been","start":30},{"end":42,"role":"verb","word":"working","start":35},{"end":46,"role":"determiner","word":"all","start":43},{"end":52,"role":"noun","word":"night","start":47}]},{"en":"They hadn't been living there long.","vi":"Họ đã chưa sống ở đó lâu.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":11,"role":"auxiliary","word":"hadn't","start":5},{"end":16,"role":"auxiliary","word":"been","start":12},{"end":23,"role":"verb","word":"living","start":17},{"end":29,"role":"adverb","word":"there","start":24},{"end":34,"role":"adverb","word":"long","start":30}]},{"en":"Had it been raining before you arrived?","vi":"Trời đã mưa trước khi bạn đến à?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":6,"role":"pronoun","word":"it","start":4},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":19,"role":"verb","word":"raining","start":12},{"end":26,"role":"preposition","word":"before","start":20},{"end":30,"role":"pronoun","word":"you","start":27},{"end":38,"role":"verb","word":"arrived","start":31}]},{"en":"His hands were dirty because he had been gardening.","vi":"Tay anh ấy bẩn vì đã làm vườn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"determiner","word":"His","start":0},{"end":9,"role":"noun","word":"hands","start":4},{"end":14,"role":"auxiliary","word":"were","start":10},{"end":20,"role":"adjective","word":"dirty","start":15},{"end":28,"role":"conjunction","word":"because","start":21},{"end":31,"role":"pronoun","word":"he","start":29},{"end":35,"role":"auxiliary","word":"had","start":32},{"end":40,"role":"auxiliary","word":"been","start":36},{"end":50,"role":"verb","word":"gardening","start":41}]},{"en":"We had been talking until midnight.","vi":"Chúng tôi đã trò chuyện đến nửa đêm.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":6,"role":"auxiliary","word":"had","start":3},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":19,"role":"verb","word":"talking","start":12},{"end":25,"role":"preposition","word":"until","start":20},{"end":34,"role":"noun","word":"midnight","start":26}]}],"mistakes":[{"wrong":"She was tired because she worked all night.","right":"She was tired because she had been working all night.","why":"Quá trình kéo dài trước một mốc quá khứ dùng had been + V-ing."},{"wrong":"I had been knowing him for years.","right":"I had known him for years.","why":"Know là động từ trạng thái — dùng past perfect đơn."},{"wrong":"They had been play for hours.","right":"They had been playing for hours.","why":"Sau had been dùng V-ing."},{"wrong":"He had being working since noon.","right":"He had been working since noon.","why":"Cấu trúc là had BEEN + V-ing, không phải had being."}],"timeline":{"points":[{"note":"mốc trước","label":"quá khứ"},{"note":"trọng tâm","label":"điểm tham chiếu"},{"note":"mốc sau","label":"tương lai"}],"caption":"Đặt một mốc tham chiếu và quan sát hành động của Past Perfect Continuous diễn ra trước, tại hoặc hướng tới mốc đó."},"comparison":"**Quá khứ hoàn thành tiếp diễn vs Quá khứ hoàn thành:** Dạng tiếp diễn nhấn QUÁ TRÌNH kéo dài trước mốc quá khứ: *It had been raining for hours* (mưa suốt nhiều giờ — nhấn độ dài). Dạng đơn nhấn KẾT QUẢ đã xong: *The rain had stopped* (đã tạnh — nhấn trạng thái). Quá trình → been + V-ing; kết quả → P2.","definition":"Thì **Quá khứ hoàn thành tiếp diễn** (Past Perfect Continuous) với cấu trúc 'had been' + V-ing, dùng để nhấn mạnh khoảng thời gian diễn ra liên tục của một hành động trong quá khứ cho đến trước một sự kiện hoặc kết quả khác trong quá khứ."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ tired because she had been working all night.","answer":["was"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 44
from public.grammar_topics t where t.slug = 'past-perfect-continuous'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 45. future-perfect
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('future-perfect', 'Future Perfect', 'Thì Tương lai hoàn thành', 'advanced', 45)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thì Tương lai hoàn thành', 'Thì **Tương lai hoàn thành** (Future Perfect) được sử dụng để diễn tả một hành động sẽ hoàn tất trước một thời điểm hoặc sự kiện cụ thể trong tương lai. Nó thường đi kèm với các cụm từ chỉ thời gian như ''by...'', ''until...'', ''by the time''.', $grammar$[{"en":"By Friday, I will have finished the report.","vi":"Đến thứ Sáu tôi sẽ hoàn thành báo cáo.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"By","start":0},{"end":9,"role":"noun","word":"Friday","start":3},{"end":12,"role":"pronoun","word":"I","start":11},{"end":17,"role":"modal","word":"will","start":13},{"end":22,"role":"auxiliary","word":"have","start":18},{"end":31,"role":"verb","word":"finished","start":23},{"end":35,"role":"article","word":"the","start":32},{"end":42,"role":"noun","word":"report","start":36}]},{"en":"She will have left before noon.","vi":"Cô ấy sẽ rời đi trước trưa.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":8,"role":"modal","word":"will","start":4},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":18,"role":"verb","word":"left","start":14},{"end":25,"role":"preposition","word":"before","start":19},{"end":30,"role":"noun","word":"noon","start":26}]},{"en":"Will they have arrived by then?","vi":"Đến lúc đó họ sẽ tới chưa?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"modal","word":"Will","start":0},{"end":9,"role":"pronoun","word":"they","start":5},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":22,"role":"verb","word":"arrived","start":15},{"end":25,"role":"preposition","word":"by","start":23},{"end":30,"role":"adverb","word":"then","start":26}]},{"en":"We won't have saved enough by June.","vi":"Đến tháng Sáu chúng tôi sẽ chưa tiết kiệm đủ.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":8,"role":"auxiliary","word":"won't","start":3},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":19,"role":"verb","word":"saved","start":14},{"end":26,"role":"adverb","word":"enough","start":20},{"end":29,"role":"preposition","word":"by","start":27},{"end":34,"role":"noun","word":"June","start":30}]},{"en":"By next year, he will have worked here for a decade.","vi":"Đến năm sau anh ấy sẽ làm ở đây tròn một thập kỷ.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"By","start":0},{"end":7,"role":"adjective","word":"next","start":3},{"end":12,"role":"noun","word":"year","start":8},{"end":16,"role":"pronoun","word":"he","start":14},{"end":21,"role":"modal","word":"will","start":17},{"end":26,"role":"auxiliary","word":"have","start":22},{"end":33,"role":"verb","word":"worked","start":27},{"end":38,"role":"adverb","word":"here","start":34},{"end":42,"role":"preposition","word":"for","start":39},{"end":44,"role":"article","word":"a","start":43},{"end":51,"role":"noun","word":"decade","start":45}]},{"en":"The guests will have eaten before the show starts.","vi":"Khách sẽ ăn xong trước khi buổi diễn bắt đầu.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"guests","start":4},{"end":15,"role":"modal","word":"will","start":11},{"end":20,"role":"auxiliary","word":"have","start":16},{"end":26,"role":"verb","word":"eaten","start":21},{"end":33,"role":"preposition","word":"before","start":27},{"end":37,"role":"article","word":"the","start":34},{"end":42,"role":"noun","word":"show","start":38},{"end":49,"role":"verb","word":"starts","start":43}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **S + will have + V3** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"S + will have + V3","example":"By Friday, I will have finished the report."},{"case":"Kiểm tra thành phần theo sau","rule":"S + will not have + V3","example":"She will have left before noon."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Will + S + have + V3?","example":"Will they have arrived by then?"}],"usage":[{"en":"By Friday, I will have finished the report.","vi":"Trước thứ Sáu, tôi sẽ hoàn thành xong báo cáo.","icon":"📄","label":"Việc sẽ hoàn tất TRƯỚC một mốc tương lai (thường với by)"},{"en":"She will have left before you arrive.","vi":"Cô ấy sẽ đi khỏi trước khi bạn đến.","icon":"🕛","label":"Việc kết thúc trước một sự kiện tương lai khác"},{"en":"Will they have arrived by then?","vi":"Đến lúc đó liệu họ đã tới nơi chưa?","icon":"❓","label":"Hỏi xem việc đã xong chưa tính đến mốc tương lai"},{"en":"We won't have saved enough by June.","vi":"Đến tháng Sáu chúng tôi vẫn chưa tiết kiệm đủ đâu.","icon":"💰","label":"Phủ định — việc chưa kịp hoàn thành trước mốc"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"S + will have + V3","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + will not have + V3","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Will + S + have + V3?","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["by","before","when","for","since","this time"],"examples":[{"en":"By Friday, I will have finished the report.","vi":"Đến thứ Sáu tôi sẽ hoàn thành báo cáo.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"By","start":0},{"end":9,"role":"noun","word":"Friday","start":3},{"end":12,"role":"pronoun","word":"I","start":11},{"end":17,"role":"modal","word":"will","start":13},{"end":22,"role":"auxiliary","word":"have","start":18},{"end":31,"role":"verb","word":"finished","start":23},{"end":35,"role":"article","word":"the","start":32},{"end":42,"role":"noun","word":"report","start":36}]},{"en":"She will have left before noon.","vi":"Cô ấy sẽ rời đi trước trưa.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":8,"role":"modal","word":"will","start":4},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":18,"role":"verb","word":"left","start":14},{"end":25,"role":"preposition","word":"before","start":19},{"end":30,"role":"noun","word":"noon","start":26}]},{"en":"Will they have arrived by then?","vi":"Đến lúc đó họ sẽ tới chưa?","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"modal","word":"Will","start":0},{"end":9,"role":"pronoun","word":"they","start":5},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":22,"role":"verb","word":"arrived","start":15},{"end":25,"role":"preposition","word":"by","start":23},{"end":30,"role":"adverb","word":"then","start":26}]},{"en":"We won't have saved enough by June.","vi":"Đến tháng Sáu chúng tôi sẽ chưa tiết kiệm đủ.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":8,"role":"auxiliary","word":"won't","start":3},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":19,"role":"verb","word":"saved","start":14},{"end":26,"role":"adverb","word":"enough","start":20},{"end":29,"role":"preposition","word":"by","start":27},{"end":34,"role":"noun","word":"June","start":30}]},{"en":"By next year, he will have worked here for a decade.","vi":"Đến năm sau anh ấy sẽ làm ở đây tròn một thập kỷ.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"By","start":0},{"end":7,"role":"adjective","word":"next","start":3},{"end":12,"role":"noun","word":"year","start":8},{"end":16,"role":"pronoun","word":"he","start":14},{"end":21,"role":"modal","word":"will","start":17},{"end":26,"role":"auxiliary","word":"have","start":22},{"end":33,"role":"verb","word":"worked","start":27},{"end":38,"role":"adverb","word":"here","start":34},{"end":42,"role":"preposition","word":"for","start":39},{"end":44,"role":"article","word":"a","start":43},{"end":51,"role":"noun","word":"decade","start":45}]},{"en":"The guests will have eaten before the show starts.","vi":"Khách sẽ ăn xong trước khi buổi diễn bắt đầu.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"guests","start":4},{"end":15,"role":"modal","word":"will","start":11},{"end":20,"role":"auxiliary","word":"have","start":16},{"end":26,"role":"verb","word":"eaten","start":21},{"end":33,"role":"preposition","word":"before","start":27},{"end":37,"role":"article","word":"the","start":34},{"end":42,"role":"noun","word":"show","start":38},{"end":49,"role":"verb","word":"starts","start":43}]}],"mistakes":[{"wrong":"By 2030 I will finish my degree.","right":"By 2030 I will have finished my degree.","why":"Việc sẽ xong TRƯỚC một mốc tương lai dùng will have + P2."},{"wrong":"By next month she will have finish it.","right":"By next month she will have finished it.","why":"Sau will have dùng quá khứ phân từ (finished)."},{"wrong":"By 6pm they will had left.","right":"By 6pm they will have left.","why":"Cấu trúc là will HAVE + P2, không phải will had."},{"wrong":"By next year I will have work here for ten years.","right":"By next year I will have worked here for ten years.","why":"Sau will have dùng P2 (worked)."}],"timeline":{"points":[{"note":"mốc trước","label":"quá khứ"},{"note":"trọng tâm","label":"điểm tham chiếu"},{"note":"mốc sau","label":"tương lai"}],"caption":"Đặt một mốc tham chiếu và quan sát hành động của Future Perfect diễn ra trước, tại hoặc hướng tới mốc đó."},"comparison":"**Tương lai hoàn thành vs Tương lai đơn:** Future perfect nhìn NGƯỢC từ một mốc tương lai — việc sẽ ĐÃ XONG trước mốc đó: *By 2030, I will have finished my degree* (trước 2030 là xong). Future simple chỉ nói việc sẽ xảy ra: *I will finish my degree in 2030.* Có \"by + mốc thời gian\" → nghĩ ngay đến will have + P2.","definition":"Thì **Tương lai hoàn thành** (Future Perfect) được sử dụng để diễn tả một hành động sẽ hoàn tất trước một thời điểm hoặc sự kiện cụ thể trong tương lai. Nó thường đi kèm với các cụm từ chỉ thời gian như 'by...', 'until...', 'by the time'."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ have left before noon.","answer":["will"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 45
from public.grammar_topics t where t.slug = 'future-perfect'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 46. future-in-the-past
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('future-in-the-past', 'Future in the Past', 'Tương lai trong quá khứ', 'advanced', 46)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Tương lai trong quá khứ', '**Future in the Past** diễn đạt các dự định, dự đoán hoặc sự kiện đã được xem là tương lai tại một thời điểm cụ thể trong quá khứ. Cấu trúc thường dùng **would** hoặc **was/were going to** để chuyển đổi góc nhìn thời gian, giúp việc kể chuyện hoặc thuật lại thông tin trở nên mạch lạc và chính xác về mặt ngữ pháp.', $grammar$[{"en":"I knew she would succeed.","vi":"Tôi biết cô ấy sẽ thành công.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"knew","start":2},{"end":10,"role":"pronoun","word":"she","start":7},{"end":16,"role":"modal","word":"would","start":11},{"end":24,"role":"verb","word":"succeed","start":17}]},{"en":"They were going to leave, but it rained.","vi":"Họ định rời đi nhưng trời mưa.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":9,"role":"auxiliary","word":"were","start":5},{"end":15,"role":"verb","word":"going","start":10},{"end":18,"role":"preposition","word":"to","start":16},{"end":24,"role":"verb","word":"leave","start":19},{"end":29,"role":"conjunction","word":"but","start":26},{"end":32,"role":"pronoun","word":"it","start":30},{"end":39,"role":"verb","word":"rained","start":33}]},{"en":"He was about to speak when the phone rang.","vi":"Anh ấy sắp nói thì điện thoại reo.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":6,"role":"auxiliary","word":"was","start":3},{"end":12,"role":"adverb","word":"about","start":7},{"end":15,"role":"preposition","word":"to","start":13},{"end":21,"role":"verb","word":"speak","start":16},{"end":26,"role":"conjunction","word":"when","start":22},{"end":30,"role":"article","word":"the","start":27},{"end":36,"role":"noun","word":"phone","start":31},{"end":41,"role":"verb","word":"rang","start":37}]},{"en":"She promised she would call.","vi":"Cô ấy hứa sẽ gọi.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":12,"role":"verb","word":"promised","start":4},{"end":16,"role":"pronoun","word":"she","start":13},{"end":22,"role":"modal","word":"would","start":17},{"end":27,"role":"verb","word":"call","start":23}]},{"en":"We were to meet the next day.","vi":"Chúng tôi dự kiến gặp nhau ngày hôm sau.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"auxiliary","word":"were","start":3},{"end":10,"role":"preposition","word":"to","start":8},{"end":15,"role":"verb","word":"meet","start":11},{"end":19,"role":"article","word":"the","start":16},{"end":24,"role":"adjective","word":"next","start":20},{"end":28,"role":"noun","word":"day","start":25}]},{"en":"I thought the journey would be easy.","vi":"Tôi đã nghĩ chuyến đi sẽ dễ dàng.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":9,"role":"verb","word":"thought","start":2},{"end":13,"role":"article","word":"the","start":10},{"end":21,"role":"noun","word":"journey","start":14},{"end":27,"role":"modal","word":"would","start":22},{"end":30,"role":"auxiliary","word":"be","start":28},{"end":35,"role":"adjective","word":"easy","start":31}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **would + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"would + V","example":"I knew she would succeed."},{"case":"Kiểm tra thành phần theo sau","rule":"was/were going to + V","example":"They were going to leave, but it rained."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"was/were about to + V","example":"He was about to speak when the phone rang."}],"usage":[{"en":"I knew she would succeed.","vi":"Tôi đã biết cô ấy rồi sẽ thành công.","icon":"🔮","label":"WOULD — điều tương lai nhìn từ một thời điểm quá khứ"},{"en":"They were going to leave, but it started raining.","vi":"Họ đã định rời đi, nhưng trời bắt đầu mưa.","icon":"🌧️","label":"WAS/WERE GOING TO — dự định quá khứ (thường không thành)"},{"en":"He was about to speak when the phone rang.","vi":"Anh ấy vừa định nói thì điện thoại reo.","icon":"📞","label":"WAS ABOUT TO — sắp sửa làm gì thì bị gián đoạn"},{"en":"She promised she would call me back.","vi":"Cô ấy hứa sẽ gọi lại cho tôi.","icon":"🤙","label":"WOULD trong lời hứa, lời nói được thuật lại"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"would + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"was/were going to + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"was/were about to + V","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["by","before","when","for","since","this time"],"examples":[{"en":"I knew she would succeed.","vi":"Tôi biết cô ấy sẽ thành công.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"knew","start":2},{"end":10,"role":"pronoun","word":"she","start":7},{"end":16,"role":"modal","word":"would","start":11},{"end":24,"role":"verb","word":"succeed","start":17}]},{"en":"They were going to leave, but it rained.","vi":"Họ định rời đi nhưng trời mưa.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":9,"role":"auxiliary","word":"were","start":5},{"end":15,"role":"verb","word":"going","start":10},{"end":18,"role":"preposition","word":"to","start":16},{"end":24,"role":"verb","word":"leave","start":19},{"end":29,"role":"conjunction","word":"but","start":26},{"end":32,"role":"pronoun","word":"it","start":30},{"end":39,"role":"verb","word":"rained","start":33}]},{"en":"He was about to speak when the phone rang.","vi":"Anh ấy sắp nói thì điện thoại reo.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":6,"role":"auxiliary","word":"was","start":3},{"end":12,"role":"adverb","word":"about","start":7},{"end":15,"role":"preposition","word":"to","start":13},{"end":21,"role":"verb","word":"speak","start":16},{"end":26,"role":"conjunction","word":"when","start":22},{"end":30,"role":"article","word":"the","start":27},{"end":36,"role":"noun","word":"phone","start":31},{"end":41,"role":"verb","word":"rang","start":37}]},{"en":"She promised she would call.","vi":"Cô ấy hứa sẽ gọi.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":12,"role":"verb","word":"promised","start":4},{"end":16,"role":"pronoun","word":"she","start":13},{"end":22,"role":"modal","word":"would","start":17},{"end":27,"role":"verb","word":"call","start":23}]},{"en":"We were to meet the next day.","vi":"Chúng tôi dự kiến gặp nhau ngày hôm sau.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":7,"role":"auxiliary","word":"were","start":3},{"end":10,"role":"preposition","word":"to","start":8},{"end":15,"role":"verb","word":"meet","start":11},{"end":19,"role":"article","word":"the","start":16},{"end":24,"role":"adjective","word":"next","start":20},{"end":28,"role":"noun","word":"day","start":25}]},{"en":"I thought the journey would be easy.","vi":"Tôi đã nghĩ chuyến đi sẽ dễ dàng.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":9,"role":"verb","word":"thought","start":2},{"end":13,"role":"article","word":"the","start":10},{"end":21,"role":"noun","word":"journey","start":14},{"end":27,"role":"modal","word":"would","start":22},{"end":30,"role":"auxiliary","word":"be","start":28},{"end":35,"role":"adjective","word":"easy","start":31}]}],"mistakes":[{"wrong":"He said he will come.","right":"He said he would come.","why":"Nhìn tương lai từ quá khứ: will lùi thành would."},{"wrong":"I knew she is going to win.","right":"I knew she was going to win.","why":"Mệnh đề chính quá khứ kéo vế sau về was going to."},{"wrong":"We thought it will rain.","right":"We thought it would rain.","why":"Sau động từ quá khứ (thought), will → would."},{"wrong":"She promised she will help.","right":"She promised she would help.","why":"Tường thuật lời hứa quá khứ dùng would."}],"timeline":{"points":[{"note":"mốc trước","label":"quá khứ"},{"note":"trọng tâm","label":"điểm tham chiếu"},{"note":"mốc sau","label":"tương lai"}],"caption":"Đặt một mốc tham chiếu và quan sát hành động của Future in the Past diễn ra trước, tại hoặc hướng tới mốc đó."},"comparison":"**Tương lai trong quá khứ vs Quá khứ đơn:** Was/were going to + would tả dự định/dự đoán ĐỨNG TỪ QUÁ KHỨ nhìn tới: *He said he WOULD come* (lúc đó anh ấy nói sẽ đến — đến hay không chưa biết). Quá khứ đơn tả việc đã xảy ra: *He came.* Trong reported speech, will luôn lùi thành would.","definition":"**Future in the Past** diễn đạt các dự định, dự đoán hoặc sự kiện đã được xem là tương lai tại một thời điểm cụ thể trong quá khứ. Cấu trúc thường dùng **would** hoặc **was/were going to** để chuyển đổi góc nhìn thời gian, giúp việc kể chuyện hoặc thuật lại thông tin trở nên mạch lạc và chính xác về mặt ngữ pháp."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: They ___ going to leave, but it rained.","answer":["were"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."},{"type":"multiple_choice","question":"Choose the correct **reported future**: Maria told me she ___ the report by Friday.","options":["would finish","will finish","finishes","finished"],"correct_answer":"would finish","explanation":"Sau động từ quá khứ “told”, ý tương lai được lùi thì thành “would + V”. “Will finish” không hòa hợp thì, “finishes” là hiện tại đơn, còn “finished” diễn tả hành động đã xong trong quá khứ.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **past plan** form: We ___ visit the museum, but it was closed.","options":["were going to","will","are going to","would to"],"correct_answer":"were going to","explanation":"“Were going to + V” diễn tả một dự định trong quá khứ. “Will” và “are going to” nhìn từ hiện tại, còn “would to” sai cấu trúc vì “would” đi trực tiếp với động từ nguyên mẫu.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **near future** in the past: The train ___ depart when the alarm sounded.","options":["was about to","is about to","would about to","was about"],"correct_answer":"was about to","explanation":"“Was about to + V” diễn tả việc sắp xảy ra tại một thời điểm trong quá khứ. “Is about to” là hiện tại, “would about to” sai cấu trúc, còn “was about” thiếu “to”.","difficulty":2},{"type":"multiple_choice","question":"Choose the natural **would** sentence.","options":["He believed the plan would work.","He believed the plan will worked.","He believed the plan would worked.","He believes the plan would work yesterday."],"correct_answer":"He believed the plan would work.","explanation":"Câu đúng dùng “believed” ở quá khứ và “would + V” để diễn tả tương lai nhìn từ quá khứ. Các lựa chọn khác sai dạng động từ sau “will/would” hoặc trộn mốc thời gian không tự nhiên.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **intention** from the past: I bought flour because I ___ bake a cake that evening.","options":["was going to","would going to","am going to","will bake"],"correct_answer":"was going to","explanation":"“Was going to bake” diễn tả ý định đã có trong quá khứ. “Would going to” sai cấu trúc, “am going to” và “will bake” đặt góc nhìn ở hiện tại.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **time viewpoint**: In 2015, nobody knew the company ___ become so successful.","options":["would","will","is going to","be going to"],"correct_answer":"would","explanation":"Mốc nhìn là “In 2015” trong quá khứ, nên tương lai sau đó dùng “would + V”. “Will” và “is going to” nhìn từ hiện tại, còn “be going to” thiếu chia động từ “be”.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **promise** form: Liam promised that he ___ send the documents before noon.","options":["would","will","was going","would to"],"correct_answer":"would","explanation":"Sau “promised” ở quá khứ, lời hứa về tương lai thường dùng “would + V”. “Will” không lùi thì, “was going” thiếu “to + V”, còn “would to” sai cấu trúc.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **scheduled future** in the past: The ceremony ___ begin at nine, but the storm delayed it.","options":["was to","is to","will to","would to"],"correct_answer":"was to","explanation":"“Was to + V” diễn tả lịch trình hoặc sắp xếp chính thức nhìn từ quá khứ. “Is to” là hiện tại, còn “will to” và “would to” sai vì không dùng “to” sau will/would theo cách này.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **negative form**: She said she ___ attend the meeting after all.","options":["would not","will not","did not would","was not would"],"correct_answer":"would not","explanation":"Phủ định của “would + V” là “would not + V”. “Will not” không lùi thì, còn “did not would” và “was not would” sai cấu trúc trợ động từ.","difficulty":1},{"type":"fill_blank","question":"Complete the **future-in-past** sentence: Tom realized he ___ miss the last bus.","options":["would","will","does","is"],"correct_answer":"would","explanation":"“Realized” đặt câu ở góc nhìn quá khứ, nên dự đoán tương lai dùng “would + V”. “Will” là tương lai từ hiện tại, còn “does” và “is” không phù hợp trước động từ nguyên mẫu “miss”.","difficulty":1},{"type":"fill_blank","question":"Complete the **going to** form: They ___ going to announce the results, but the director stopped them.","options":["were","was","are","be"],"correct_answer":"were","explanation":"Chủ ngữ “They” cần “were” trong cấu trúc “were going to + V” ở quá khứ. “Was” sai hòa hợp chủ ngữ, “are” là hiện tại, còn “be” chưa được chia.","difficulty":1},{"type":"fill_blank","question":"Complete the **about to** structure: I was ___ to leave when my manager called.","options":["about","going","would","will"],"correct_answer":"about","explanation":"Cấu trúc đúng là “was about to + V”, diễn tả hành động sắp xảy ra trong quá khứ. “Going” cần “to” nhưng nghĩa là dự định, còn “would” và “will” không đi sau “was” trong cấu trúc này.","difficulty":1},{"type":"fill_blank","question":"Complete the **reported speech** sentence: Dad said the repair ___ take longer than expected.","options":["would","will","takes","took"],"correct_answer":"would","explanation":"Trong lời nói gián tiếp với “said” ở quá khứ, “will take” thường lùi thành “would take”. “Takes” là hiện tại, “took” là quá khứ đơn, còn “will” không hòa hợp với mốc quá khứ.","difficulty":2},{"type":"fill_blank","question":"Complete the **past intention** sentence: She had packed a swimsuit because she ___ going to swim after lunch.","options":["was","were","is","would"],"correct_answer":"was","explanation":"Chủ ngữ “she” đi với “was” trong “was going to + V”. “Were” sai hòa hợp chủ ngữ, “is” là hiện tại, còn “would going to” không đúng cấu trúc.","difficulty":1},{"type":"fill_blank","question":"Complete the **would** clause: We hoped the weather ___ improve before the match.","options":["would","will","was","did"],"correct_answer":"would","explanation":"“Hoped” là động từ quá khứ, nên điều được mong đợi xảy ra sau đó dùng “would + V”. “Will” nhìn từ hiện tại, “was improve” và “did improve” không phù hợp trong cấu trúc này.","difficulty":1},{"type":"fill_blank","question":"Complete the **official plan** form: The guests were ___ arrive at 7 p.m., but traffic was terrible.","options":["to","about","going","would"],"correct_answer":"to","explanation":"“Were to arrive” diễn tả lịch trình hoặc kế hoạch chính thức trong quá khứ. “About” cần “to” nhưng nghĩa là sắp xảy ra ngay, “going” cần “to”, còn “would arrive” không nhấn mạnh lịch trình chính thức.","difficulty":3},{"type":"fill_blank","question":"Complete the **interrupted plan**: Ben ___ going to explain everything, but Anna changed the subject.","options":["was","were","will","would"],"correct_answer":"was","explanation":"“Ben” là chủ ngữ số ít nên dùng “was going to explain”. “Were” sai hòa hợp chủ ngữ, “will going to” và “would going to” đều sai cấu trúc.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **verb form** error: Nina said she will call us after dinner.","options":["said","will call","us","after dinner"],"correct_answer":"will call","explanation":"Sau “said” ở quá khứ, tương lai trong quá khứ cần “would call”. “Said”, “us” và “after dinner” đều đúng trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **past plan** error: We was going to ask for help, but the office was closed.","options":["We","was going to","ask for help","was closed"],"correct_answer":"was going to","explanation":"Chủ ngữ “We” phải đi với “were going to”, không phải “was going to”. Các cụm còn lại phù hợp về nghĩa và ngữ pháp.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **about to** error: He was about speak when the teacher entered.","options":["He","was about speak","when","entered"],"correct_answer":"was about speak","explanation":"Cấu trúc đúng là “was about to speak”, phải có “to” trước động từ nguyên mẫu. “He”, “when” và “entered” không sai trong câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **reported future** error: They believed the new bridge will reduce traffic in the area.","options":["believed","will reduce","traffic","in the area"],"correct_answer":"will reduce","explanation":"Với “believed” ở quá khứ, ý tương lai sau đó nên dùng “would reduce”. Các phần còn lại đúng và không cần sửa.","difficulty":2},{"type":"error_correction","question":"Find the error: Identify the **future-in-past** error: I knew that Sarah would arrives late because her train was delayed.","options":["knew","would arrives","because","was delayed"],"correct_answer":"would arrives","explanation":"Sau “would” phải dùng động từ nguyên mẫu “arrive”, không thêm “s”. “Knew”, “because” và “was delayed” đều đúng trong ngữ cảnh này.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **intention** error: Mark was going to joined the gym, but he changed his mind.","options":["Mark","was going to joined","the gym","changed his mind"],"correct_answer":"was going to joined","explanation":"Sau “was going to” phải dùng động từ nguyên mẫu “join”, không dùng quá khứ “joined”. Các cụm khác đúng về nghĩa và cấu trúc.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **scheduled future** error: The flight was to leaving at six, but it was canceled.","options":["The flight","was to leaving","at six","was canceled"],"correct_answer":"was to leaving","explanation":"Cấu trúc lịch trình trong quá khứ là “was to leave”, không dùng V-ing sau “was to”. Các phần còn lại đều hợp ngữ pháp.","difficulty":3},{"type":"error_correction","question":"Find the error: Identify the **time shift** error: She thought the interview is going to be difficult.","options":["She thought","is going to be","difficult","interview"],"correct_answer":"is going to be","explanation":"Sau “thought” ở quá khứ, dự đoán tương lai nên là “was going to be” hoặc “would be”. “She thought”, “difficult” và “interview” không phải lỗi chính.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **future past** form: At that moment, I was sure the plan ___ fail.","options":["would","will","is going to","has to"],"correct_answer":"would","explanation":"Sau một mốc nhìn trong quá khứ (“At that moment, I was sure”), ta dùng “would + V” để nói về tương lai được nhìn từ quá khứ. “Will” và “is going to” là góc nhìn hiện tại; “has to” diễn tả nghĩa bắt buộc, không phù hợp.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **past intention** form: Chloe saved some money because she ___ buy a new laptop later that year.","options":["was going to","will","is going to","would to"],"correct_answer":"was going to","explanation":"“Was going to + V” diễn tả dự định đã có trong quá khứ cho một thời điểm sau đó. “Will/is going to” không phù hợp với mốc quá khứ, còn “would to” sai cấu trúc vì sau “would” không có “to”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **about to** structure: The speaker ___ start his presentation when the lights went out.","options":["was about to","would about to","is about to","was about"],"correct_answer":"was about to","explanation":"“Was about to + V” diễn tả việc sắp xảy ra trong quá khứ thì bị một sự kiện khác chen vào. Các lựa chọn còn lại sai thì hoặc thiếu “to”, hoặc kết hợp sai với “would”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **reported plan**: Emma said they ___ move into the apartment the following week.","options":["were going to","are going to","will","would going to"],"correct_answer":"were going to","explanation":"Trong lời thuật lại từ quá khứ, “are going to” thường lùi thành “were going to”. “Will” không lùi thì; “would going to” sai vì không kết hợp “would” với “going to” như vậy.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **base verb** form: The coach believed the team would ___ stronger after the break.","options":["become","became","becomes","becoming"],"correct_answer":"become","explanation":"Sau “would” phải dùng động từ nguyên mẫu không “to”: “would become”. “Became”, “becomes” và “becoming” đều sai dạng sau modal verb.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **official arrangement**: The delegates ___ meet the mayor at noon, but the visit was postponed.","options":["were to","were going","would to","are to"],"correct_answer":"were to","explanation":"“Were to + V” diễn tả một kế hoạch/lịch trình chính thức được nhìn từ quá khứ. “Were going” thiếu “to + V”, “would to” sai cấu trúc, còn “are to” là thì hiện tại.","difficulty":3},{"type":"multiple_choice","question":"Choose the natural **prediction**: In 1998, few people imagined that online banking ___ become normal.","options":["would","will","was going","is about to"],"correct_answer":"would","explanation":"Với dự đoán từ một thời điểm trong quá khứ, ta dùng “would + V”. “Will” là dự đoán từ hiện tại; “was going” thiếu “to + V”; “is about to” chỉ việc sắp xảy ra ở hiện tại.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **negative plan**: I was tired, so I told them I ___ stay for the whole concert.","options":["wasn't going to","am not going to","wouldn't to","didn't going to"],"correct_answer":"wasn't going to","explanation":"“Wasn’t going to + V” diễn tả dự định không làm gì trong quá khứ. “Am not going to” là hiện tại; “wouldn’t to” và “didn’t going to” sai cấu trúc.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **future clause**: We suspected the road ___ be closed after the heavy snow.","options":["would","will","was","has"],"correct_answer":"would","explanation":"Sau động từ quá khứ “suspected”, tương lai nhìn từ quá khứ thường dùng “would + V”. “Will” giữ góc nhìn hiện tại; “was/has” không tạo cấu trúc tương lai trong quá khứ ở câu này.","difficulty":1},{"type":"fill_blank","question":"Complete the **would** sentence: Maya believed her brother ___ apologize before the evening ended.","options":["would","will","was going","is going"],"correct_answer":"would","explanation":"“Believed” đặt câu trong quá khứ, nên dự đoán sau đó dùng “would apologize”. “Will/is going” không lùi thì, còn “was going” thiếu “to” trước động từ chính.","difficulty":1},{"type":"fill_blank","question":"Complete the **going to** form: The workers ___ going to repair the roof, but the owner changed the schedule.","options":["were","was","are","be"],"correct_answer":"were","explanation":"Chủ ngữ số nhiều “The workers” cần “were going to + V” trong quá khứ. “Was” sai hòa hợp, “are” là hiện tại, còn “be” không đứng trực tiếp sau chủ ngữ như vậy.","difficulty":1},{"type":"fill_blank","question":"Complete the **about to** phrase: She was about ___ press send when she noticed a mistake.","options":["to","for","with","at"],"correct_answer":"to","explanation":"Cấu trúc đúng là “was about to + V” để nói việc sắp xảy ra. Các giới từ “for/with/at” không tạo được cấu trúc này.","difficulty":1},{"type":"fill_blank","question":"Complete the **past schedule**: The new policy was ___ take effect in April, but it was delayed.","options":["to","about","going","would"],"correct_answer":"to","explanation":"“Was to take effect” diễn tả kế hoạch/lịch trình chính thức trong quá khứ. “About” cần “about to” và nghĩa là sắp xảy ra ngay; “going” cần “going to”; “would” không đi sau “was” ở đây.","difficulty":3},{"type":"fill_blank","question":"Complete the **reported future** sentence: The guide explained that the tour ___ end near the old market.","options":["would","will","is going to","has to"],"correct_answer":"would","explanation":"“Explained” là động từ quá khứ, nên tương lai trong lời giải thích được lùi thành “would end”. “Will/is going to” không phù hợp góc nhìn quá khứ; “has to” đổi nghĩa thành sự bắt buộc.","difficulty":2},{"type":"fill_blank","question":"Complete the **interrupted intention**: I ___ going to ask a question, but the meeting ended suddenly.","options":["was","were","am","be"],"correct_answer":"was","explanation":"Chủ ngữ “I” đi với “was going to + V” trong quá khứ. “Were” thường không dùng với “I” trong câu khẳng định thông thường này, “am” là hiện tại, còn “be” sai dạng.","difficulty":1},{"type":"fill_blank","question":"Complete the **verb form**: They thought the software would ___ the problem automatically.","options":["solve","solved","solves","solving"],"correct_answer":"solve","explanation":"Sau “would” phải dùng động từ nguyên mẫu “solve”. Các dạng “solved/solves/solving” đều sai sau modal verb.","difficulty":1},{"type":"fill_blank","question":"Complete the **future past** sentence: The doctor warned that the pain ___ get worse without treatment.","options":["would","will","is going to","does"],"correct_answer":"would","explanation":"“Warned” là mốc quá khứ, nên điều sẽ xảy ra sau đó được diễn đạt bằng “would get worse”. “Will/is going to” là góc nhìn hiện tại; “does” không diễn tả tương lai trong quá khứ.","difficulty":2},{"type":"error_correction","question":"Find the error: Identify the **time shift** error: I believed the package will arrive before the weekend.","options":["believed","will arrive","before","the weekend"],"correct_answer":"will arrive","explanation":"Sau “believed” ở quá khứ, cần dùng “would arrive” để diễn tả tương lai trong quá khứ. “Before the weekend” chỉ thời gian và không sai; “believed” là mốc quá khứ đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **going to** error: The students was going to present their project, but the projector failed.","options":["The students","was going to","present","the projector"],"correct_answer":"was going to","explanation":"Chủ ngữ “The students” là số nhiều nên phải dùng “were going to”. “Present” là động từ nguyên mẫu đúng sau “going to”; các cụm còn lại không gây lỗi ngữ pháp chính.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **modal verb** error: Lena hoped the medicine would helps her sleep better.","options":["hoped","would helps","her","sleep better"],"correct_answer":"would helps","explanation":"Sau “would” phải dùng động từ nguyên mẫu, nên đúng là “would help”. “Hoped” đặt mốc quá khứ đúng, còn “her” và “sleep better” phù hợp trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **about to** error: We were about leaving the cafe when Sam called.","options":["were","about leaving","the cafe","called"],"correct_answer":"about leaving","explanation":"Cấu trúc đúng là “were about to leave”, không dùng “about leaving” cho nghĩa sắp làm gì. “Were” hòa hợp với “We”, và “called” là hành động xen vào trong quá khứ.","difficulty":2},{"type":"error_correction","question":"Find the error: Identify the **past plan** error: I was going buy tickets online, but the website crashed.","options":["was going","buy tickets","online","crashed"],"correct_answer":"was going","explanation":"Cần có “to” trong cấu trúc “was going to buy”. “Buy tickets” là động từ chính đúng nếu có “to” trước nó; “online” và “crashed” không sai trong ngữ cảnh này.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **reported promise** error: Daniel promised he will return the camera the next day.","options":["promised","will return","the camera","the next day"],"correct_answer":"will return","explanation":"Vì “promised” ở quá khứ, lời hứa về tương lai nên lùi thành “would return”. Các cụm còn lại đúng nghĩa và đúng vị trí trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the **official plan** error: The conference was to starts after lunch, but the keynote ran late.","options":["The conference","was to starts","after lunch","ran late"],"correct_answer":"was to starts","explanation":"Sau “was to” phải dùng động từ nguyên mẫu: “was to start”. “After lunch” và “ran late” diễn tả thời gian và sự kiện quá khứ đúng.","difficulty":3},{"type":"error_correction","question":"Find the error: Identify the **future past** error: She realized the decision is going to affect everyone in the team.","options":["realized","is going to affect","everyone","in the team"],"correct_answer":"is going to affect","explanation":"Sau “realized” ở quá khứ, nên dùng “was going to affect” hoặc “would affect”. “Everyone” và “in the team” không sai; lỗi nằm ở việc chưa lùi “is going to”.","difficulty":2}]$grammar$::jsonb, 'ai-golden', 46
from public.grammar_topics t where t.slug = 'future-in-the-past'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 47. mixed-conditionals
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('mixed-conditionals', 'Mixed Conditionals', 'Câu điều kiện hỗn hợp', 'advanced', 47)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu điều kiện hỗn hợp', '**Câu điều kiện hỗn hợp** kết hợp hai loại câu điều kiện khác nhau về thời gian, ví dụ: điều kiện ở quá khứ và kết quả ở hiện tại, hoặc ngược lại. Chúng giúp diễn tả những tình huống giả định phức tạp, không có thật hoặc khác với thực tế ở các mốc thời gian khác nhau.', $grammar$[{"en":"If I had slept earlier, I wouldn't be tired now.","vi":"Nếu tối qua ngủ sớm hơn, giờ tôi đã không mệt.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":8,"role":"auxiliary","word":"had","start":5},{"end":14,"role":"verb","word":"slept","start":9},{"end":22,"role":"adverb","word":"earlier","start":15},{"end":25,"role":"pronoun","word":"I","start":24},{"end":34,"role":"modal","word":"wouldn't","start":26},{"end":37,"role":"auxiliary","word":"be","start":35},{"end":43,"role":"adjective","word":"tired","start":38},{"end":47,"role":"adverb","word":"now","start":44}]},{"en":"If she were more organized, she wouldn't have missed the deadline.","vi":"Nếu cô ấy ngăn nắp hơn, cô ấy đã không lỡ hạn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":6,"role":"pronoun","word":"she","start":3},{"end":11,"role":"auxiliary","word":"were","start":7},{"end":16,"role":"adjective","word":"more","start":12},{"end":26,"role":"adjective","word":"organized","start":17},{"end":31,"role":"pronoun","word":"she","start":28},{"end":40,"role":"modal","word":"wouldn't","start":32},{"end":45,"role":"auxiliary","word":"have","start":41},{"end":52,"role":"verb","word":"missed","start":46},{"end":56,"role":"article","word":"the","start":53},{"end":65,"role":"noun","word":"deadline","start":57}]},{"en":"Had we taken the map, we would know where we are.","vi":"Nếu mang bản đồ, giờ chúng tôi đã biết mình ở đâu.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":6,"role":"pronoun","word":"we","start":4},{"end":12,"role":"verb","word":"taken","start":7},{"end":16,"role":"article","word":"the","start":13},{"end":20,"role":"noun","word":"map","start":17},{"end":24,"role":"pronoun","word":"we","start":22},{"end":30,"role":"modal","word":"would","start":25},{"end":35,"role":"verb","word":"know","start":31},{"end":41,"role":"adverb","word":"where","start":36},{"end":44,"role":"pronoun","word":"we","start":42},{"end":48,"role":"verb","word":"are","start":45}]},{"en":"If he weren't afraid of flying, he would have joined us.","vi":"Nếu không sợ bay, anh ấy đã đi cùng.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":5,"role":"pronoun","word":"he","start":3},{"end":13,"role":"auxiliary","word":"weren't","start":6},{"end":20,"role":"adjective","word":"afraid","start":14},{"end":23,"role":"preposition","word":"of","start":21},{"end":30,"role":"verb","word":"flying","start":24},{"end":34,"role":"pronoun","word":"he","start":32},{"end":40,"role":"modal","word":"would","start":35},{"end":45,"role":"auxiliary","word":"have","start":41},{"end":52,"role":"verb","word":"joined","start":46},{"end":55,"role":"pronoun","word":"us","start":53}]},{"en":"If I had accepted that job, I would live in Tokyo now.","vi":"Nếu nhận việc đó, giờ tôi đã sống ở Tokyo.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":8,"role":"auxiliary","word":"had","start":5},{"end":17,"role":"verb","word":"accepted","start":9},{"end":22,"role":"determiner","word":"that","start":18},{"end":26,"role":"noun","word":"job","start":23},{"end":29,"role":"pronoun","word":"I","start":28},{"end":35,"role":"modal","word":"would","start":30},{"end":40,"role":"verb","word":"live","start":36},{"end":43,"role":"preposition","word":"in","start":41},{"end":49,"role":"noun","word":"Tokyo","start":44},{"end":53,"role":"adverb","word":"now","start":50}]},{"en":"She would be happier now if she had followed her passion.","vi":"Giờ cô ấy đã vui hơn nếu từng theo đuổi đam mê.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":9,"role":"modal","word":"would","start":4},{"end":12,"role":"verb","word":"be","start":10},{"end":20,"role":"adjective","word":"happier","start":13},{"end":24,"role":"adverb","word":"now","start":21},{"end":27,"role":"conjunction","word":"if","start":25},{"end":31,"role":"pronoun","word":"she","start":28},{"end":35,"role":"auxiliary","word":"had","start":32},{"end":44,"role":"verb","word":"followed","start":36},{"end":48,"role":"determiner","word":"her","start":45},{"end":56,"role":"noun","word":"passion","start":49}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **If + had + V3, would + V (quá khứ → hiện tại)** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"If + had + V3, would + V (quá khứ → hiện tại)","example":"If I had slept earlier, I wouldn't be tired now."},{"case":"Kiểm tra thành phần theo sau","rule":"If + past simple, would have + V3 (hiện tại → quá khứ)","example":"If she were more organized, she wouldn't have missed the deadline."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"đảo Had ... thay If","example":"Had we taken the map, we would know where we are."}],"usage":[{"en":"If I had slept earlier, I wouldn't be tired now.","vi":"Nếu tối qua tôi ngủ sớm thì bây giờ tôi đã không mệt.","icon":"😪","label":"Điều kiện quá khứ → kết quả hiện tại (had V3 → would V)"},{"en":"If she were more organized, she wouldn't have missed the deadline.","vi":"Nếu cô ấy ngăn nắp hơn thì đã không lỡ hạn chót.","icon":"🗂️","label":"Điều kiện hiện tại → kết quả quá khứ (were → would have V3)"},{"en":"Had we taken the map, we would know where we are.","vi":"Nếu chúng ta mang bản đồ thì giờ đã biết mình đang ở đâu.","icon":"🗺️","label":"Đảo ngữ trang trọng với Had + S + V3"},{"en":"If he weren't afraid of flying, he would have joined us.","vi":"Nếu anh ấy không sợ đi máy bay thì anh ấy đã đi cùng chúng tôi rồi.","icon":"✈️","label":"Tính cách/trạng thái hiện tại giải thích quyết định quá khứ"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"If + had + V3, would + V (quá khứ → hiện tại)","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"If + past simple, would have + V3 (hiện tại → quá khứ)","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"đảo Had ... thay If","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["If + had + P2","would + V (now)","now","today"],"examples":[{"en":"If I had slept earlier, I wouldn't be tired now.","vi":"Nếu tối qua ngủ sớm hơn, giờ tôi đã không mệt.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":8,"role":"auxiliary","word":"had","start":5},{"end":14,"role":"verb","word":"slept","start":9},{"end":22,"role":"adverb","word":"earlier","start":15},{"end":25,"role":"pronoun","word":"I","start":24},{"end":34,"role":"modal","word":"wouldn't","start":26},{"end":37,"role":"auxiliary","word":"be","start":35},{"end":43,"role":"adjective","word":"tired","start":38},{"end":47,"role":"adverb","word":"now","start":44}]},{"en":"If she were more organized, she wouldn't have missed the deadline.","vi":"Nếu cô ấy ngăn nắp hơn, cô ấy đã không lỡ hạn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":6,"role":"pronoun","word":"she","start":3},{"end":11,"role":"auxiliary","word":"were","start":7},{"end":16,"role":"adjective","word":"more","start":12},{"end":26,"role":"adjective","word":"organized","start":17},{"end":31,"role":"pronoun","word":"she","start":28},{"end":40,"role":"modal","word":"wouldn't","start":32},{"end":45,"role":"auxiliary","word":"have","start":41},{"end":52,"role":"verb","word":"missed","start":46},{"end":56,"role":"article","word":"the","start":53},{"end":65,"role":"noun","word":"deadline","start":57}]},{"en":"Had we taken the map, we would know where we are.","vi":"Nếu mang bản đồ, giờ chúng tôi đã biết mình ở đâu.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":6,"role":"pronoun","word":"we","start":4},{"end":12,"role":"verb","word":"taken","start":7},{"end":16,"role":"article","word":"the","start":13},{"end":20,"role":"noun","word":"map","start":17},{"end":24,"role":"pronoun","word":"we","start":22},{"end":30,"role":"modal","word":"would","start":25},{"end":35,"role":"verb","word":"know","start":31},{"end":41,"role":"adverb","word":"where","start":36},{"end":44,"role":"pronoun","word":"we","start":42},{"end":48,"role":"verb","word":"are","start":45}]},{"en":"If he weren't afraid of flying, he would have joined us.","vi":"Nếu không sợ bay, anh ấy đã đi cùng.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":5,"role":"pronoun","word":"he","start":3},{"end":13,"role":"auxiliary","word":"weren't","start":6},{"end":20,"role":"adjective","word":"afraid","start":14},{"end":23,"role":"preposition","word":"of","start":21},{"end":30,"role":"verb","word":"flying","start":24},{"end":34,"role":"pronoun","word":"he","start":32},{"end":40,"role":"modal","word":"would","start":35},{"end":45,"role":"auxiliary","word":"have","start":41},{"end":52,"role":"verb","word":"joined","start":46},{"end":55,"role":"pronoun","word":"us","start":53}]},{"en":"If I had accepted that job, I would live in Tokyo now.","vi":"Nếu nhận việc đó, giờ tôi đã sống ở Tokyo.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":8,"role":"auxiliary","word":"had","start":5},{"end":17,"role":"verb","word":"accepted","start":9},{"end":22,"role":"determiner","word":"that","start":18},{"end":26,"role":"noun","word":"job","start":23},{"end":29,"role":"pronoun","word":"I","start":28},{"end":35,"role":"modal","word":"would","start":30},{"end":40,"role":"verb","word":"live","start":36},{"end":43,"role":"preposition","word":"in","start":41},{"end":49,"role":"noun","word":"Tokyo","start":44},{"end":53,"role":"adverb","word":"now","start":50}]},{"en":"She would be happier now if she had followed her passion.","vi":"Giờ cô ấy đã vui hơn nếu từng theo đuổi đam mê.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":9,"role":"modal","word":"would","start":4},{"end":12,"role":"verb","word":"be","start":10},{"end":20,"role":"adjective","word":"happier","start":13},{"end":24,"role":"adverb","word":"now","start":21},{"end":27,"role":"conjunction","word":"if","start":25},{"end":31,"role":"pronoun","word":"she","start":28},{"end":35,"role":"auxiliary","word":"had","start":32},{"end":44,"role":"verb","word":"followed","start":36},{"end":48,"role":"determiner","word":"her","start":45},{"end":56,"role":"noun","word":"passion","start":49}]}],"mistakes":[{"wrong":"If I had saved money, I will be rich now.","right":"If I had saved money, I would be rich now.","why":"Kết quả hiện tại của điều kiện quá khứ dùng would + V."},{"wrong":"If I would have won, I would be happy now.","right":"If I had won, I would be happy now.","why":"Mệnh đề if dùng past perfect, không dùng would have."},{"wrong":"If we didn't spend all our money, we could travel now.","right":"If we hadn't spent all our money, we could travel now.","why":"Điều kiện xảy ra trong quá khứ dùng past perfect dù kết quả ở hiện tại."},{"wrong":"If she was more careful yesterday, she wouldn't be hurt now.","right":"If she had been more careful yesterday, she wouldn't be hurt now.","why":"Điều kiện quá khứ (yesterday) dùng had been."}],"timeline":{"points":[{"note":"điều kiện không xảy ra","label":"❌ had won (quá khứ)"},{"note":"kết quả giả định hiện tại","label":"→ would be rich NOW"}],"caption":"Điều kiện nằm ở QUÁ KHỨ, kết quả ngược nằm ở HIỆN TẠI: hai mốc thời gian khác nhau trong một câu."},"comparison":"**Mixed vs Third conditional:** Câu điều kiện HỖN HỢP nối điều kiện quá khứ với kết quả HIỆN TẠI: *If I had won the lottery, I would be rich now.* Câu điều kiện loại 3 giữ cả hai vế trong QUÁ KHỨ: *If I had won the lottery, I would have bought a house last year.* Nhìn trạng ngữ thời gian (now vs last year) để chọn vế sau.","definition":"**Câu điều kiện hỗn hợp** kết hợp hai loại câu điều kiện khác nhau về thời gian, ví dụ: điều kiện ở quá khứ và kết quả ở hiện tại, hoặc ngược lại. Chúng giúp diễn tả những tình huống giả định phức tạp, không có thật hoặc khác với thực tế ở các mốc thời gian khác nhau."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: If she ___ more organized, she wouldn't have missed the deadline.","answer":["were"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 47
from public.grammar_topics t where t.slug = 'mixed-conditionals'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
