insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Cấu trúc Wish / If only', '**Cấu trúc wish / if only** được sử dụng để diễn đạt những mong muốn không có thực hoặc sự nuối tiếc về một trạng thái ở hiện tại hoặc quá khứ. Đây là công cụ ngữ pháp then chốt để thể hiện các giả định mang tính giả tưởng hoặc những cảm xúc mang tính trái ngược với thực tế khách quan.', $grammar$[{"en":"I wish I knew the answer.","vi":"Tôi ước mình biết đáp án.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"wish","start":2},{"end":8,"role":"pronoun","word":"I","start":7},{"end":13,"role":"verb","word":"knew","start":9},{"end":17,"role":"article","word":"the","start":14},{"end":24,"role":"noun","word":"answer","start":18}]},{"en":"If only it weren't raining.","vi":"Giá mà trời không mưa.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":7,"role":"adverb","word":"only","start":3},{"end":10,"role":"pronoun","word":"it","start":8},{"end":18,"role":"auxiliary","word":"weren't","start":11},{"end":26,"role":"verb","word":"raining","start":19}]},{"en":"She wishes she had studied harder.","vi":"Cô ấy ước mình đã học chăm hơn.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"verb","word":"wishes","start":4},{"end":14,"role":"pronoun","word":"she","start":11},{"end":18,"role":"auxiliary","word":"had","start":15},{"end":26,"role":"verb","word":"studied","start":19},{"end":33,"role":"adverb","word":"harder","start":27}]},{"en":"I wish you would stop shouting.","vi":"Tôi mong bạn thôi la hét.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"wish","start":2},{"end":10,"role":"pronoun","word":"you","start":7},{"end":16,"role":"modal","word":"would","start":11},{"end":21,"role":"verb","word":"stop","start":17},{"end":30,"role":"verb","word":"shouting","start":22}]},{"en":"If only we could stay longer.","vi":"Giá mà chúng tôi có thể ở lâu hơn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":7,"role":"adverb","word":"only","start":3},{"end":10,"role":"pronoun","word":"we","start":8},{"end":16,"role":"modal","word":"could","start":11},{"end":21,"role":"verb","word":"stay","start":17},{"end":28,"role":"adverb","word":"longer","start":22}]},{"en":"He wishes he hadn't sold the house.","vi":"Anh ấy ước mình đã không bán nhà.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":9,"role":"verb","word":"wishes","start":3},{"end":12,"role":"pronoun","word":"he","start":10},{"end":19,"role":"auxiliary","word":"hadn't","start":13},{"end":24,"role":"verb","word":"sold","start":20},{"end":28,"role":"article","word":"the","start":25},{"end":34,"role":"noun","word":"house","start":29}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **wish + past simple (hiện tại)** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"wish + past simple (hiện tại)","example":"I wish I knew the answer."},{"case":"Kiểm tra thành phần theo sau","rule":"wish + had + V3 (quá khứ)","example":"If only it weren't raining."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"wish + would/could + V (thay đổi/khả năng)","example":"She wishes she had studied harder."}],"usage":[{"en":"I wish I knew the answer.","vi":"Ước gì tôi biết câu trả lời.","icon":"💭","label":"WISH + quá khứ đơn — ước trái với hiện tại"},{"en":"If only it weren't raining.","vi":"Giá mà trời đừng mưa.","icon":"🌧️","label":"IF ONLY — như wish nhưng cảm xúc mạnh hơn"},{"en":"She wishes she had studied harder.","vi":"Cô ấy ước gì hồi đó mình học chăm hơn.","icon":"⏪","label":"WISH + quá khứ hoàn thành — tiếc nuối chuyện đã qua"},{"en":"I wish you would stop shouting.","vi":"Tôi mong bạn thôi la hét đi.","icon":"🙉","label":"WISH + would — phàn nàn, muốn người khác thay đổi"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"wish + past simple (hiện tại)","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"wish + had + V3 (quá khứ)","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"wish + would/could + V (thay đổi/khả năng)","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["wish","if only","I wish I knew","I wish I had"],"examples":[{"en":"I wish I knew the answer.","vi":"Tôi ước mình biết đáp án.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"wish","start":2},{"end":8,"role":"pronoun","word":"I","start":7},{"end":13,"role":"verb","word":"knew","start":9},{"end":17,"role":"article","word":"the","start":14},{"end":24,"role":"noun","word":"answer","start":18}]},{"en":"If only it weren't raining.","vi":"Giá mà trời không mưa.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":7,"role":"adverb","word":"only","start":3},{"end":10,"role":"pronoun","word":"it","start":8},{"end":18,"role":"auxiliary","word":"weren't","start":11},{"end":26,"role":"verb","word":"raining","start":19}]},{"en":"She wishes she had studied harder.","vi":"Cô ấy ước mình đã học chăm hơn.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":10,"role":"verb","word":"wishes","start":4},{"end":14,"role":"pronoun","word":"she","start":11},{"end":18,"role":"auxiliary","word":"had","start":15},{"end":26,"role":"verb","word":"studied","start":19},{"end":33,"role":"adverb","word":"harder","start":27}]},{"en":"I wish you would stop shouting.","vi":"Tôi mong bạn thôi la hét.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"wish","start":2},{"end":10,"role":"pronoun","word":"you","start":7},{"end":16,"role":"modal","word":"would","start":11},{"end":21,"role":"verb","word":"stop","start":17},{"end":30,"role":"verb","word":"shouting","start":22}]},{"en":"If only we could stay longer.","vi":"Giá mà chúng tôi có thể ở lâu hơn.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"conjunction","word":"If","start":0},{"end":7,"role":"adverb","word":"only","start":3},{"end":10,"role":"pronoun","word":"we","start":8},{"end":16,"role":"modal","word":"could","start":11},{"end":21,"role":"verb","word":"stay","start":17},{"end":28,"role":"adverb","word":"longer","start":22}]},{"en":"He wishes he hadn't sold the house.","vi":"Anh ấy ước mình đã không bán nhà.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":9,"role":"verb","word":"wishes","start":3},{"end":12,"role":"pronoun","word":"he","start":10},{"end":19,"role":"auxiliary","word":"hadn't","start":13},{"end":24,"role":"verb","word":"sold","start":20},{"end":28,"role":"article","word":"the","start":25},{"end":34,"role":"noun","word":"house","start":29}]}],"mistakes":[{"wrong":"I wish I have more time.","right":"I wish I had more time.","why":"Wish về hiện tại không thực dùng quá khứ đơn."},{"wrong":"I wish I would be taller.","right":"I wish I were taller.","why":"Wish về chính mình dùng were, không dùng would."},{"wrong":"I wish I studied harder last year.","right":"I wish I had studied harder last year.","why":"Tiếc nuối quá khứ dùng past perfect (had + P2)."},{"wrong":"I wish my English becomes better.","right":"I hope my English becomes better.","why":"Mong ước thực tế tương lai dùng hope, không dùng wish + hiện tại."}],"timeline":{"points":[{"note":"hiện tại","label":"Thực tế: he IS busy"},{"note":"giả định ngược","label":"Wish: he WASN'T busy"}],"caption":"Wish kéo sự thật hiện tại về \"thế giới ngược\": thực tế NOW = busy, wish = not busy (dùng thì QUÁ KHỨ để đánh dấu không có thật)."},"comparison":"**Wish vs Hope:** *Hope* = mong muốn THỰC TẾ, có thể xảy ra, dùng thì hiện tại (*I hope Anna is here*). *Wish/if only* = tiếc nuối điều KHÔNG có thật/khó xảy ra, dùng thì quá khứ (*I wish Anna were here* — cô ấy không ở đây). Mong điều khả thi → hope; than điều ngược sự thật → wish.","definition":"**Cấu trúc wish / if only** được sử dụng để diễn đạt những mong muốn không có thực hoặc sự nuối tiếc về một trạng thái ở hiện tại hoặc quá khứ. Đây là công cụ ngữ pháp then chốt để thể hiện các giả định mang tính giả tưởng hoặc những cảm xúc mang tính trái ngược với thực tế khách quan."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"I wish I ____ (speak) English fluently.","opts":[],"answer":"spoke","fb":"Ước chuyện bây giờ → V2"},{"type":"fill","q":"My sister wishes she ____ (be) a doctor.","opts":[],"answer":"were","fb":"Sau wish, động từ be luôn là were"},{"type":"fill","q":"I wish it ____ (not / rain) so much these days.","opts":[],"answer":"didn't rain","fb":"these days = bây giờ → didn't + V"},{"type":"fill","q":"I wish I ____ (go) to bed earlier last night.","opts":[],"answer":"had gone","fb":"last night = chuyện đã qua → had + V3"},{"type":"fill","q":"A. devoted   B. suggested   C. provided   D. wished","opts":[],"answer":"D. wished","fb":"wished: trước -ed là /ʃ/ → /t/ · ba từ kia sau t/d → /ɪd/"}]$grammar$::jsonb, 'ai-golden', 48
from public.grammar_topics t where t.slug = 'wish-if-only'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 49. modals-perfect
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('modals-perfect', 'Perfect Modals (should have, etc.)', 'Khuyết thiếu hoàn thành (should have...)', 'advanced', 49)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Khuyết thiếu hoàn thành (should have...)', '**Động từ khuyết thiếu dạng hoàn thành** (modal + have + V3/ed) dùng để đánh giá, suy đoán hoặc thể hiện sự tiếc nuối về những sự việc đã xảy ra trong quá khứ. Cấu trúc này đóng vai trò then chốt giúp người nói nhìn nhận lại các sự kiện đã qua dưới góc độ phê phán hoặc xác suất logic.', $grammar$[{"en":"You should have called me.","vi":"Lẽ ra bạn nên gọi tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":10,"role":"modal","word":"should","start":4},{"end":15,"role":"auxiliary","word":"have","start":11},{"end":22,"role":"verb","word":"called","start":16},{"end":25,"role":"pronoun","word":"me","start":23}]},{"en":"She must have forgotten.","vi":"Chắc hẳn cô ấy đã quên.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":8,"role":"modal","word":"must","start":4},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":23,"role":"verb","word":"forgotten","start":14}]},{"en":"They might have taken the wrong bus.","vi":"Có thể họ đã đi nhầm xe buýt.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":10,"role":"modal","word":"might","start":5},{"end":15,"role":"auxiliary","word":"have","start":11},{"end":21,"role":"verb","word":"taken","start":16},{"end":25,"role":"article","word":"the","start":22},{"end":31,"role":"adjective","word":"wrong","start":26},{"end":35,"role":"noun","word":"bus","start":32}]},{"en":"He can't have finished already.","vi":"Anh ấy không thể đã làm xong rồi.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":8,"role":"modal","word":"can't","start":3},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":22,"role":"verb","word":"finished","start":14},{"end":30,"role":"adverb","word":"already","start":23}]},{"en":"We could have won.","vi":"Chúng tôi đã có thể thắng.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":8,"role":"modal","word":"could","start":3},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":17,"role":"verb","word":"won","start":14}]},{"en":"I needn't have brought food.","vi":"Tôi đã mang đồ ăn dù không cần.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":9,"role":"modal","word":"needn't","start":2},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":22,"role":"verb","word":"brought","start":15},{"end":27,"role":"noun","word":"food","start":23}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **modal + have + V3** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"modal + have + V3","example":"You should have called me."},{"case":"Kiểm tra thành phần theo sau","rule":"should/ought to have + V3","example":"She must have forgotten."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"must/might/can't have + V3","example":"They might have taken the wrong bus."}],"usage":[{"en":"You should have called me.","vi":"Lẽ ra bạn nên gọi cho tôi chứ.","icon":"☎️","label":"SHOULD HAVE V3 — trách móc việc lẽ ra nên làm"},{"en":"She must have forgotten our meeting.","vi":"Chắc chắn cô ấy đã quên cuộc hẹn của chúng ta.","icon":"🧠","label":"MUST HAVE V3 — suy đoán chắc chắn về quá khứ"},{"en":"They might have taken the wrong bus.","vi":"Có lẽ họ đã lên nhầm xe buýt.","icon":"🚌","label":"MIGHT HAVE V3 — suy đoán không chắc về quá khứ"},{"en":"He can't have finished already.","vi":"Không thể nào anh ấy đã làm xong rồi được.","icon":"🙅","label":"CAN'T HAVE V3 — chắc chắn việc đó KHÔNG xảy ra"},{"en":"You could have been hurt!","vi":"Bạn đã có thể bị thương đấy!","icon":"🍀","label":"COULD HAVE V3 — việc đã có thể xảy ra nhưng không"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"modal + have + V3","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"should/ought to have + V3","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"must/might/can't have + V3","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["must have + P2","should have + P2","could have + P2","might have + P2","needn't have + P2"],"examples":[{"en":"You should have called me.","vi":"Lẽ ra bạn nên gọi tôi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":10,"role":"modal","word":"should","start":4},{"end":15,"role":"auxiliary","word":"have","start":11},{"end":22,"role":"verb","word":"called","start":16},{"end":25,"role":"pronoun","word":"me","start":23}]},{"en":"She must have forgotten.","vi":"Chắc hẳn cô ấy đã quên.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":8,"role":"modal","word":"must","start":4},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":23,"role":"verb","word":"forgotten","start":14}]},{"en":"They might have taken the wrong bus.","vi":"Có thể họ đã đi nhầm xe buýt.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":10,"role":"modal","word":"might","start":5},{"end":15,"role":"auxiliary","word":"have","start":11},{"end":21,"role":"verb","word":"taken","start":16},{"end":25,"role":"article","word":"the","start":22},{"end":31,"role":"adjective","word":"wrong","start":26},{"end":35,"role":"noun","word":"bus","start":32}]},{"en":"He can't have finished already.","vi":"Anh ấy không thể đã làm xong rồi.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":8,"role":"modal","word":"can't","start":3},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":22,"role":"verb","word":"finished","start":14},{"end":30,"role":"adverb","word":"already","start":23}]},{"en":"We could have won.","vi":"Chúng tôi đã có thể thắng.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":8,"role":"modal","word":"could","start":3},{"end":13,"role":"auxiliary","word":"have","start":9},{"end":17,"role":"verb","word":"won","start":14}]},{"en":"I needn't have brought food.","vi":"Tôi đã mang đồ ăn dù không cần.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":9,"role":"modal","word":"needn't","start":2},{"end":14,"role":"auxiliary","word":"have","start":10},{"end":22,"role":"verb","word":"brought","start":15},{"end":27,"role":"noun","word":"food","start":23}]}],"mistakes":[{"wrong":"You should came to the party.","right":"You should have come to the party.","why":"Tiếc nuối quá khứ dùng should have + P2."},{"wrong":"He must has left already.","right":"He must have left already.","why":"Suy đoán quá khứ dùng must have + P2 (have nguyên thể)."},{"wrong":"She can't saw me.","right":"She can't have seen me.","why":"Phủ định suy đoán quá khứ dùng can't have + P2."},{"wrong":"I needn't to buy it.","right":"I needn't have bought it.","why":"Việc quá khứ không cần thiết dùng needn't have + P2."}],"timeline":{"points":[{"note":"quá khứ đã xong","label":"sự kiện (last night)"},{"note":"suy đoán, tiếc nuối","label":"NOW: must have / should have"}],"caption":"Modal perfect luôn trỏ ngược về quá khứ: đứng ở NOW nhìn lại sự kiện ĐÃ xong để suy đoán/tiếc nuối."},"comparison":"**Perfect modal vs modal thường:** Modal + have + P2 nói về QUÁ KHỨ đã kết thúc — suy đoán hoặc tiếc nuối: *He must have had a party* (chắc đã tổ chức). Modal thường nói hiện tại/tương lai: *He must be having a party* (chắc đang tổ chức). Have + P2 = đã xong; be + V-ing = đang diễn ra.","definition":"**Động từ khuyết thiếu dạng hoàn thành** (modal + have + V3/ed) dùng để đánh giá, suy đoán hoặc thể hiện sự tiếc nuối về những sự việc đã xảy ra trong quá khứ. Cấu trúc này đóng vai trò then chốt giúp người nói nhìn nhận lại các sự kiện đã qua dưới góc độ phê phán hoặc xác suất logic."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ have forgotten.","answer":["must"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 49
from public.grammar_topics t where t.slug = 'modals-perfect'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 50. causative
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('causative', 'Causative (have/get something done)', 'Thể nhờ/sai bảo (have/get sth done)', 'advanced', 50)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thể nhờ/sai bảo (have/get sth done)', '**Thể nhờ vả (causative)** với cấu trúc ''have/get something done'' được dùng khi chủ ngữ không trực tiếp thực hiện hành động mà sắp xếp, ủy thác cho người khác làm giúp mình. Cấu trúc này làm nổi bật kết quả hoặc dịch vụ nhận được, thay vì tập trung vào chính người thực hiện hành động đó.', $grammar$[{"en":"I had my hair cut yesterday.","vi":"Hôm qua tôi đi cắt tóc.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"verb","word":"had","start":2},{"end":8,"role":"determiner","word":"my","start":6},{"end":13,"role":"noun","word":"hair","start":9},{"end":17,"role":"verb","word":"cut","start":14},{"end":27,"role":"adverb","word":"yesterday","start":18}]},{"en":"We are getting the roof repaired.","vi":"Chúng tôi đang cho sửa mái nhà.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":6,"role":"auxiliary","word":"are","start":3},{"end":14,"role":"verb","word":"getting","start":7},{"end":18,"role":"determiner","word":"the","start":15},{"end":23,"role":"noun","word":"roof","start":19},{"end":32,"role":"verb","word":"repaired","start":24}]},{"en":"She had the assistant print the report.","vi":"Cô ấy bảo trợ lý in báo cáo.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"verb","word":"had","start":4},{"end":11,"role":"determiner","word":"the","start":8},{"end":21,"role":"noun","word":"assistant","start":12},{"end":27,"role":"verb","word":"print","start":22},{"end":31,"role":"determiner","word":"the","start":28},{"end":38,"role":"noun","word":"report","start":32}]},{"en":"He got his brother to help.","vi":"Anh ấy nhờ em trai giúp.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":6,"role":"verb","word":"got","start":3},{"end":10,"role":"determiner","word":"his","start":7},{"end":18,"role":"noun","word":"brother","start":11},{"end":21,"role":"other","word":"to","start":19},{"end":26,"role":"verb","word":"help","start":22}]},{"en":"You should have your eyes tested.","vi":"Bạn nên đi kiểm tra mắt.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":10,"role":"modal","word":"should","start":4},{"end":15,"role":"verb","word":"have","start":11},{"end":20,"role":"determiner","word":"your","start":16},{"end":25,"role":"noun","word":"eyes","start":21},{"end":32,"role":"verb","word":"tested","start":26}]},{"en":"They had their car stolen.","vi":"Họ bị mất cắp xe.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":8,"role":"verb","word":"had","start":5},{"end":14,"role":"determiner","word":"their","start":9},{"end":18,"role":"noun","word":"car","start":15},{"end":25,"role":"verb","word":"stolen","start":19}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **have/get + object + V3** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"have/get + object + V3","example":"I had my hair cut yesterday."},{"case":"Kiểm tra thành phần theo sau","rule":"have + person + V","example":"We are getting the roof repaired."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"get + person + to V","example":"She had the assistant print the report."}],"usage":[{"en":"I had my hair cut yesterday.","vi":"Hôm qua tôi đi cắt tóc.","icon":"💇","label":"HAVE + vật + V3 — nhờ dịch vụ làm cho mình"},{"en":"We are getting the roof repaired.","vi":"Chúng tôi đang cho sửa lại mái nhà.","icon":"🏠","label":"GET + vật + V3 — thuê/nhờ làm (thân mật hơn have)"},{"en":"She had the assistant print the report.","vi":"Cô ấy bảo trợ lý in báo cáo.","icon":"🖨️","label":"HAVE + người + V nguyên thể — sai bảo ai làm gì"},{"en":"He got his brother to help with the move.","vi":"Anh ấy nhờ được em trai giúp chuyển nhà.","icon":"🤝","label":"GET + người + TO V — thuyết phục, nhờ ai làm gì"},{"en":"She had her phone stolen on the bus.","vi":"Cô ấy bị móc mất điện thoại trên xe buýt.","icon":"😖","label":"HAVE/GET + vật + V3 chỉ sự cố ngoài ý muốn"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"have/get + object + V3","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"have + person + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"get + person + to V","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["have something done","get something done","make somebody do","let somebody do"],"examples":[{"en":"I had my hair cut yesterday.","vi":"Hôm qua tôi đi cắt tóc.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"verb","word":"had","start":2},{"end":8,"role":"determiner","word":"my","start":6},{"end":13,"role":"noun","word":"hair","start":9},{"end":17,"role":"verb","word":"cut","start":14},{"end":27,"role":"adverb","word":"yesterday","start":18}]},{"en":"We are getting the roof repaired.","vi":"Chúng tôi đang cho sửa mái nhà.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":6,"role":"auxiliary","word":"are","start":3},{"end":14,"role":"verb","word":"getting","start":7},{"end":18,"role":"determiner","word":"the","start":15},{"end":23,"role":"noun","word":"roof","start":19},{"end":32,"role":"verb","word":"repaired","start":24}]},{"en":"She had the assistant print the report.","vi":"Cô ấy bảo trợ lý in báo cáo.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"verb","word":"had","start":4},{"end":11,"role":"determiner","word":"the","start":8},{"end":21,"role":"noun","word":"assistant","start":12},{"end":27,"role":"verb","word":"print","start":22},{"end":31,"role":"determiner","word":"the","start":28},{"end":38,"role":"noun","word":"report","start":32}]},{"en":"He got his brother to help.","vi":"Anh ấy nhờ em trai giúp.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":6,"role":"verb","word":"got","start":3},{"end":10,"role":"determiner","word":"his","start":7},{"end":18,"role":"noun","word":"brother","start":11},{"end":21,"role":"other","word":"to","start":19},{"end":26,"role":"verb","word":"help","start":22}]},{"en":"You should have your eyes tested.","vi":"Bạn nên đi kiểm tra mắt.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"You","start":0},{"end":10,"role":"modal","word":"should","start":4},{"end":15,"role":"verb","word":"have","start":11},{"end":20,"role":"determiner","word":"your","start":16},{"end":25,"role":"noun","word":"eyes","start":21},{"end":32,"role":"verb","word":"tested","start":26}]},{"en":"They had their car stolen.","vi":"Họ bị mất cắp xe.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":8,"role":"verb","word":"had","start":5},{"end":14,"role":"determiner","word":"their","start":9},{"end":18,"role":"noun","word":"car","start":15},{"end":25,"role":"verb","word":"stolen","start":19}]}],"mistakes":[{"wrong":"I cut my hair yesterday (nhờ thợ).","right":"I had my hair cut yesterday.","why":"Nhờ người khác làm dùng have + vật + P2."},{"wrong":"How often do you have serviced your car?","right":"How often do you have your car serviced?","why":"Tân ngữ (your car) đứng TRƯỚC quá khứ phân từ."},{"wrong":"I got him repair the roof.","right":"I got him to repair the roof.","why":"Get + người + TO-infinitive."},{"wrong":"She made me to wait.","right":"She made me wait.","why":"Make + người + động từ nguyên thể KHÔNG to."}],"timeline":null,"comparison":"**Causative vs chủ động thường:** *Lisa repaired the roof* = Lisa TỰ sửa. *Lisa had the roof repaired* = Lisa NHỜ/thuê người khác sửa. Cấu trúc have + TÂN NGỮ + P2 — tân ngữ luôn đứng trước quá khứ phân từ. Get thì cần to-infinitive khi có người thực hiện: *get him TO repair*.","definition":"**Thể nhờ vả (causative)** với cấu trúc 'have/get something done' được dùng khi chủ ngữ không trực tiếp thực hiện hành động mà sắp xếp, ủy thác cho người khác làm giúp mình. Cấu trúc này làm nổi bật kết quả hoặc dịch vụ nhận được, thay vì tập trung vào chính người thực hiện hành động đó."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: We ___ getting the roof repaired.","answer":["are"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."},{"type":"multiple_choice","question":"Choose the correct **causative form**: My laptop was overheating, so I ___ yesterday.","options":["had it checked","checked it myself","had checked it","got check it"],"correct_answer":"had it checked","explanation":"Đáp án đúng là 'had it checked' vì cấu trúc have + object + V3 diễn tả việc nhờ/thuê người khác kiểm tra máy. 'checked it myself' nghĩa là tự làm, không phải causative; 'had checked it' là thì quá khứ hoàn thành; 'got check it' thiếu object và V3/to V.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **past participle**: We need to get the contract ___ before Friday.","options":["signed","sign","to sign","signing"],"correct_answer":"signed","explanation":"Sau get + object trong mẫu 'get something done' cần V3, nên 'signed' đúng. 'sign', 'to sign', và 'signing' không đúng dạng cho cấu trúc này.","difficulty":1},{"type":"error_correction","question":"Find the error: Mark the wrong **verb form**: They had the broken window replace before the storm arrived.","options":["had","broken window","replace","arrived"],"correct_answer":"replace","explanation":"Trong cấu trúc have + object + V3, động từ phải là 'replaced'. 'Had', 'broken window', và 'arrived' đều phù hợp trong câu.","difficulty":1},{"type":"multiple_choice","question":"Choose the sentence with correct **word order**:","options":["She got her passport renewed last week.","She got renewed her passport last week.","She got her passport renew last week.","She got to renew her passport last week."],"correct_answer":"She got her passport renewed last week.","explanation":"Cấu trúc đúng là get + object + V3: 'got her passport renewed'. Các lựa chọn khác sai thứ tự, sai dạng động từ, hoặc đổi nghĩa thành cô ấy tự đi gia hạn.","difficulty":1},{"type":"fill_blank","question":"Complete the question using the correct **causative verb**: Where did you ___ your phone repaired?","options":["get","got","getting","gets"],"correct_answer":"get","explanation":"Sau trợ động từ 'did', động từ chính phải ở dạng nguyên mẫu, nên 'get' đúng. 'Got', 'getting', và 'gets' sai dạng sau 'did'.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the wrong **causative pattern**: I got the mechanic to replaced the battery.","options":["got","the mechanic","to replaced","the battery"],"correct_answer":"to replaced","explanation":"Với get + person + to V, động từ sau 'to' phải là nguyên mẫu: 'to replace'. 'Got', 'the mechanic', và 'the battery' đúng vai trò trong câu.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **person causative**: The manager ___ the technician restart the server.","options":["had","got","was had","had got"],"correct_answer":"had","explanation":"Khi sai/bảo một người làm gì, dùng have + person + V nguyên mẫu: 'had the technician restart'. 'Got' cần 'to restart'; 'was had' và 'had got' không phù hợp ngữ pháp ở đây.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with correct **get pattern**: I finally got my landlord ___ the leak.","options":["to fix","fix","fixed","fixing"],"correct_answer":"to fix","explanation":"Với get + person, ta dùng to V: 'got my landlord to fix'. 'Fix' hợp với have + person, 'fixed' hợp với get + thing, còn 'fixing' sai cấu trúc.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the incorrect **object position**: We had painted the office by a professional team.","options":["had painted","the office","by","a professional team"],"correct_answer":"had painted","explanation":"Câu muốn nói thuê người sơn văn phòng thì phải là 'had the office painted'. 'Had painted' biến câu thành quá khứ hoàn thành chủ động, không phải causative.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **passive result** meaning: 'The company arranged for new software to be installed.'","options":["The company had new software installed.","The company installed new software itself.","The company had installed new software.","The company got new software install."],"correct_answer":"The company had new software installed.","explanation":"'Had new software installed' nhấn mạnh kết quả do người khác thực hiện. Các câu còn lại hoặc nói công ty tự cài, hoặc là thì quá khứ hoàn thành, hoặc sai dạng V3.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **tense**: By the time clients arrive, we will have ___ the room cleaned.","options":["had","have","having","has"],"correct_answer":"had","explanation":"Trong tương lai hoàn thành của causative, dùng 'will have had + object + V3'. 'Have', 'having', và 'has' không đúng sau 'will have' trong cấu trúc này.","difficulty":3},{"type":"error_correction","question":"Find the error: Identify the wrong **past participle**: She is getting her wedding dress alter this afternoon.","options":["is getting","her wedding dress","alter","this afternoon"],"correct_answer":"alter","explanation":"Sau get + object phải dùng V3: 'altered'. 'Is getting' đúng cho hành động đã sắp xếp trong tương lai gần, các phần còn lại không sai.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **modal causative**: You should ___ before the trip.","options":["have your brakes checked","have checked your brakes","get your brakes check","had your brakes checked"],"correct_answer":"have your brakes checked","explanation":"Sau modal 'should' dùng động từ nguyên mẫu 'have', và cấu trúc là have + object + V3. Các lựa chọn khác sai thứ tự, sai V3, hoặc sai dạng sau modal.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **have pattern**: The director had her assistant ___ the invitations.","options":["send","sent","to send","sending"],"correct_answer":"send","explanation":"Với have + person + V, động từ sau người thực hiện ở dạng nguyên mẫu không 'to'. 'Sent' dùng cho have + object + V3, 'to send' hợp với get + person, còn 'sending' sai cấu trúc.","difficulty":2},{"type":"error_correction","question":"Find the error: Mark the wrong **to-infinitive** use: The chef had the waiter to bring extra plates.","options":["had","the waiter","to bring","extra plates"],"correct_answer":"to bring","explanation":"Sau have + person phải dùng động từ nguyên mẫu không 'to': 'bring'. 'Had', 'the waiter', và 'extra plates' đều đúng trong cấu trúc này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **negative causative** sentence:","options":["I didn't have the documents translated.","I didn't had the documents translated.","I didn't have translated the documents.","I didn't have the documents translate."],"correct_answer":"I didn't have the documents translated.","explanation":"Phủ định quá khứ dùng 'didn't have', sau đó object + V3. Các câu khác sai dạng 'had', sai thứ tự, hoặc sai dạng động từ chính.","difficulty":1},{"type":"fill_blank","question":"Complete with the correct **object form**: They got ___ redesigned by a local architect.","options":["their kitchen","redesign their kitchen","to redesign their kitchen","their kitchen redesign"],"correct_answer":"their kitchen","explanation":"Mẫu đúng là get + object + V3: 'got their kitchen redesigned'. Các lựa chọn khác làm sai thứ tự hoặc dùng sai dạng động từ.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the incorrect **causative verb**: Did you got your eyes tested last month?","options":["Did","got","your eyes","tested"],"correct_answer":"got","explanation":"Trong câu hỏi quá khứ với 'Did', động từ chính phải là 'get': 'Did you get...?'. 'Did', 'your eyes', và 'tested' đều đúng vai trò.","difficulty":1},{"type":"multiple_choice","question":"Choose the sentence that means someone else fixed it, focusing on the **service**:","options":["I got the air conditioner repaired.","I repaired the air conditioner.","I got to repair the air conditioner.","I had repaired the air conditioner."],"correct_answer":"I got the air conditioner repaired.","explanation":"'Got the air conditioner repaired' nghĩa là tôi sắp xếp để người khác sửa máy lạnh. Các lựa chọn khác nói tự sửa, được phép/có cơ hội sửa, hoặc dùng quá khứ hoàn thành.","difficulty":1},{"type":"fill_blank","question":"Complete with the correct **perfect form**: Have you ever ___ your portrait painted?","options":["had","have","gotten to","having"],"correct_answer":"had","explanation":"Trong hiện tại hoàn thành, dùng 'have/has + V3', nên 'Have you ever had...?' là đúng. 'Have' không phải V3 ở đây, 'gotten to' đổi nghĩa, và 'having' sai dạng.","difficulty":2},{"type":"error_correction","question":"Find the error: Identify the wrong **word order**: Mark got checked his blood pressure at the clinic.","options":["Mark","got checked","his blood pressure","at the clinic"],"correct_answer":"got checked","explanation":"Cấu trúc đúng là 'got his blood pressure checked'. 'Got checked his blood pressure' sai thứ tự giữa object và V3.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **reported plan**: Maria said she was going to ___ before the meeting.","options":["have the projector repaired","have repaired the projector","get the projector repair","had the projector repaired"],"correct_answer":"have the projector repaired","explanation":"Sau 'was going to' dùng động từ nguyên mẫu 'have' và cấu trúc object + V3. Các đáp án còn lại sai nghĩa, sai V3, hoặc sai dạng sau 'to'.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **causative choice**: The teacher ___ the students rewrite the paragraph.","options":["had","got","was got","had to"],"correct_answer":"had","explanation":"Với have + person + V, 'had the students rewrite' là đúng. 'Got' cần 'to rewrite', 'was got' sai ngữ pháp, còn 'had to' nghĩa là 'phải', không phải sai bảo ai làm.","difficulty":2},{"type":"error_correction","question":"Find the error: Mark the wrong **get pattern**: We got a photographer take our family photos.","options":["got","a photographer","take","our family photos"],"correct_answer":"take","explanation":"Với get + person, cần 'to V': 'got a photographer to take'. 'Got', 'a photographer', và 'our family photos' không sai.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **unpleasant event** causative:","options":["He had his wallet stolen on the bus.","He had stolen his wallet on the bus.","He got his wallet steal on the bus.","He had his wallet to steal on the bus."],"correct_answer":"He had his wallet stolen on the bus.","explanation":"'Had his wallet stolen' diễn tả một việc không mong muốn xảy ra với anh ấy, dùng have + object + V3. Các câu còn lại hoặc đổi nghĩa thành anh ấy ăn cắp, hoặc sai dạng động từ.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **causative form**: After the accident, Nina ___ at the garage.","options":["had her scooter checked","checked her scooter by a garage","had checked her scooter","got checking her scooter"],"correct_answer":"had her scooter checked","explanation":"Dùng 'have + object + V3' để nói Nina sắp xếp cho người khác kiểm tra xe. 'Had checked' dễ hiểu là Nina đã tự kiểm tra; hai đáp án còn lại sai cấu trúc sau 'have/get'.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **past participle**: I'm going to have the documents ___ and sent today.","options":["scanned","scan","to scan","scanning"],"correct_answer":"scanned","explanation":"Sau 'have + object' trong nghĩa nhờ/dịch vụ phải dùng V3: 'have the documents scanned'. 'Scan', 'to scan', và 'scanning' không đúng mẫu này.","difficulty":1},{"type":"error_correction","question":"Find the error: Mark the wrong **verb form**: Olivia got the tailor shorten her sleeves before the interview.","options":["Olivia","got the tailor","shorten","her sleeves"],"correct_answer":"shorten","explanation":"Với người thực hiện, cấu trúc đúng là 'get + person + to V', nên phải là 'got the tailor to shorten'. Các phần còn lại đúng vai trò trong câu.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **person pattern**: The coach ___ the players repeat the drill until it was perfect.","options":["had","got","got to","had to"],"correct_answer":"had","explanation":"'Have + person + V' dùng động từ nguyên mẫu không 'to': 'had the players repeat'. 'Got' cần 'to repeat', còn 'got to' và 'had to' làm câu sai nghĩa hoặc sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **get pattern**: The sales team got the designer ___ the brochure overnight.","options":["to update","update","updated","updating"],"correct_answer":"to update","explanation":"'Get + person + to V' là cấu trúc đúng khi thuyết phục/nhờ ai làm gì. 'Update' thiếu 'to', còn 'updated' và 'updating' không đi với mẫu này.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the incorrect **causative form**: We are having our security cameras install next week.","options":["We are having","our security cameras","install","next week"],"correct_answer":"install","explanation":"Với đồ vật/dịch vụ, dùng 'have + object + V3': 'having our security cameras installed'. 'Install' là động từ nguyên mẫu nên sai trong cấu trúc này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **future continuous** causative: At 3 p.m. tomorrow, Jason ___.","options":["will be getting his car washed","will get washing his car","will have washed his car by someone","will be gotten his car wash"],"correct_answer":"will be getting his car washed","explanation":"Câu diễn tả một dịch vụ đang diễn ra trong tương lai: 'will be getting + object + V3'. Các lựa chọn khác sai dạng động từ hoặc sai trật tự từ.","difficulty":3},{"type":"fill_blank","question":"Complete with the correct **object**: After moving in, they had ___ fitted in every room.","options":["new blinds","fit new blinds","the installer","fitting"],"correct_answer":"new blinds","explanation":"Trong 'have + object + V3', chỗ trống cần một tân ngữ danh từ: 'new blinds'. Các đáp án khác là động từ, người thực hiện, hoặc dạng -ing nên không phù hợp.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the wrong **infinitive**: The producer had the sound engineer to adjust the volume during rehearsal.","options":["The producer","had","the sound engineer","to adjust"],"correct_answer":"to adjust","explanation":"Sau 'have + person' phải dùng động từ nguyên mẫu không 'to': 'had the sound engineer adjust'. 'To adjust' là lỗi thường gặp do nhầm với 'get + person + to V'.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **meaning**: Which sentence means Lan arranged for someone else to translate the email?","options":["Lan had the email translated.","Lan translated the email herself.","Lan had translated the email.","Lan was translated the email."],"correct_answer":"Lan had the email translated.","explanation":"'Had the email translated' nhấn mạnh Lan sắp xếp để email được dịch. Các câu khác nói Lan tự dịch, dùng thì quá khứ hoàn thành, hoặc sai cấu trúc bị động.","difficulty":1},{"type":"fill_blank","question":"Complete with the correct **causative verb**: Before signing the lease, you should ___ the wiring inspected by an electrician.","options":["have","make","let","do"],"correct_answer":"have","explanation":"'Should have + object + V3' diễn tả nên nhờ/thuê ai kiểm tra hệ thống dây điện. 'Make', 'let', và 'do' không tạo được cấu trúc dịch vụ này.","difficulty":2},{"type":"error_correction","question":"Find the error: Mark the wrong **past participle**: Maya got her passport renew before the conference.","options":["Maya","got","her passport","renew"],"correct_answer":"renew","explanation":"Sau 'get + object' trong nghĩa dịch vụ phải dùng V3: 'got her passport renewed'. 'Renew' là động từ nguyên mẫu nên sai.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **negative form**: The clinic didn't ___ before the test results were ready.","options":["have the samples analyzed","had the samples analyzed","got the samples analyze","have analyzed the samples by a lab"],"correct_answer":"have the samples analyzed","explanation":"Sau 'didn't' dùng động từ nguyên mẫu 'have', và cấu trúc là 'have + object + V3'. Các đáp án khác sai thì, sai dạng sau 'get', hoặc đổi sang nghĩa chủ động không tự nhiên.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with the correct **perfect causative**: By next Monday, they will have had the hallway ___.","options":["repainted","repaint","to repaint","repainting"],"correct_answer":"repainted","explanation":"'Will have had + object + V3' diễn tả dịch vụ sẽ hoàn tất trước một mốc tương lai. Chỉ 'repainted' là quá khứ phân từ đúng sau tân ngữ.","difficulty":3},{"type":"error_correction","question":"Find the error: Mark the incorrect **question form**: Why did the school had the playground resurfaced?","options":["Why","did","had","the playground"],"correct_answer":"had","explanation":"Trong câu hỏi quá khứ với 'did', động từ chính phải ở dạng nguyên mẫu: 'did the school have'. 'Had' sai vì đã có trợ động từ 'did'.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **service verb**: After the breach, we ___ our passwords reset by IT.","options":["got","made","let","did"],"correct_answer":"got","explanation":"'Got our passwords reset' diễn tả việc nhờ bộ phận IT đặt lại mật khẩu. 'Made', 'let', và 'did' không phù hợp với cấu trúc 'object + V3' trong nghĩa dịch vụ.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **past participle**: The gallery had the painting ___ for the exhibition.","options":["restored","restore","to restore","restoring"],"correct_answer":"restored","explanation":"Cấu trúc đúng là 'had + object + V3': 'had the painting restored'. Ba đáp án còn lại không phải quá khứ phân từ trong mẫu này.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the incorrect **object pattern**: They had their luggage to deliver to the hotel.","options":["They had","their luggage","to deliver","to the hotel"],"correct_answer":"to deliver","explanation":"Với đồ vật được xử lý bởi người khác, dùng 'have + object + V3': 'had their luggage delivered'. 'To deliver' sai vì không dùng to-infinitive sau tân ngữ trong mẫu này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **result focus**: The museum wanted to emphasize that the old coins became clean, not who cleaned them.","options":["The museum had the old coins cleaned.","The museum had specialists cleaned the old coins.","The museum got the old coins clean specialists.","The museum cleaned by the old coins."],"correct_answer":"The museum had the old coins cleaned.","explanation":"'Had the old coins cleaned' tập trung vào kết quả/dịch vụ nhận được. Các lựa chọn khác sai dạng động từ, sai trật tự từ, hoặc sai nghĩa.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **agent phrase**: We had the menu translated ___ a professional interpreter.","options":["by","with","from","to"],"correct_answer":"by","explanation":"Khi muốn nêu người thực hiện trong cấu trúc giống bị động, dùng 'by': 'translated by a professional interpreter'. Các giới từ khác không chỉ tác nhân đúng trong câu này.","difficulty":2},{"type":"error_correction","question":"Find the error: Identify the wrong **participle**: Liam is getting his bicycle chain replace before the race.","options":["Liam","is getting","his bicycle chain","replace"],"correct_answer":"replace","explanation":"Sau 'get + object' phải dùng V3: 'getting his bicycle chain replaced'. 'Replace' là động từ nguyên mẫu nên sai.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **get clause**: I couldn't solve the tax form, so I ___.","options":["got an accountant to check it","got an accountant check it","got it to check an accountant","got checking it by an accountant"],"correct_answer":"got an accountant to check it","explanation":"Khi nhờ một người làm việc gì, dùng 'get + person + to V'. Các đáp án còn lại thiếu 'to', đảo sai tân ngữ, hoặc sai dạng động từ.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **bare infinitive**: The supervisor had the interns ___ the files by client name.","options":["sort","to sort","sorted","sorting"],"correct_answer":"sort","explanation":"'Have + person + V' dùng động từ nguyên mẫu không 'to': 'had the interns sort'. 'To sort', 'sorted', và 'sorting' không đúng sau 'had the interns'.","difficulty":2},{"type":"error_correction","question":"Find the error: Mark the wrong **modal form**: Can we had the air conditioner serviced this afternoon?","options":["Can","we","had","serviced"],"correct_answer":"had","explanation":"Sau modal 'can' phải dùng động từ nguyên mẫu: 'Can we have the air conditioner serviced?' 'Serviced' vẫn đúng vì thuộc mẫu 'have + object + V3'.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **perfect causative**: Before the audit started, the finance team ___.","options":["had had the receipts organized","had the receipts organize","had been the receipts organized","got organized the receipts"],"correct_answer":"had had the receipts organized","explanation":"'Had had + object + V3' là quá khứ hoàn thành của cấu trúc causative, diễn tả việc đã nhờ sắp xếp xong trước cuộc kiểm toán. Các đáp án khác sai dạng V3 hoặc sai trật tự từ.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **causative form**: Daniel ___ after he dropped it.","options":["had his phone screen replaced","had replaced his phone screen","got his phone screen to replace","had his phone screen replace"],"correct_answer":"had his phone screen replaced","explanation":"Đúng vì cấu trúc nhờ dịch vụ là have + object + V3: “had his phone screen replaced”. Các đáp án khác sai trật tự hoặc dùng sai dạng động từ sau object.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **past participle**: The manager got the presentation slides ___ before the client call.","options":["redesigned","redesign","to redesign","redesigning"],"correct_answer":"redesigned","explanation":"Sau get + object trong nghĩa nhờ ai làm, động từ chính phải ở dạng quá khứ phân từ: “got the slides redesigned”. “redesign”, “to redesign”, và “redesigning” không đúng mẫu get + object + V3.","difficulty":2},{"type":"error_correction","question":"Find the error: Mark the wrong **verb form**: Emma had the plumber to fix the leaking sink.","options":["had","the plumber","to fix","the leaking sink"],"correct_answer":"to fix","explanation":"Với have + person + V, động từ sau người phải là bare infinitive: “had the plumber fix”. “to fix” sai vì không dùng “to” sau have trong mẫu sai bảo này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **get pattern**: I finally ___ my landlord to replace the broken heater.","options":["got","had","made","was got"],"correct_answer":"got","explanation":"Đúng vì get + person + to V diễn tả thuyết phục/nhờ ai làm: “got my landlord to replace”. “had” sẽ cần động từ nguyên mẫu không “to”, còn “made” đổi sắc thái ép buộc.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **causative verb**: We need to ___ the documents checked by a lawyer.","options":["have","make","let","do"],"correct_answer":"have","explanation":"“have the documents checked” đúng cấu trúc have + object + V3, nhấn mạnh kết quả kiểm tra. “make/let/do” không tạo cấu trúc nhờ dịch vụ với V3 như câu này.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the wrong **word order**: They got cleaned the carpets before the guests arrived.","options":["got cleaned","the carpets","before","arrived"],"correct_answer":"got cleaned","explanation":"Trật tự đúng là get + object + V3: “got the carpets cleaned”. “got cleaned the carpets” đặt V3 trước object nên sai.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **negative form**: Sophie ___ her nails done because the salon was closed.","options":["didn't get","didn't got","wasn't get","hadn't get"],"correct_answer":"didn't get","explanation":"Trong quá khứ phủ định, dùng did not + động từ nguyên mẫu: “didn't get her nails done”. “didn't got”, “wasn't get”, và “hadn't get” sai trợ động từ hoặc dạng động từ.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with the correct **bare infinitive**: The director had the camera crew ___ the scene again.","options":["film","filmed","to film","filming"],"correct_answer":"film","explanation":"Sau have + person, động từ theo sau ở dạng nguyên mẫu không “to”: “had the camera crew film”. Các dạng “filmed”, “to film”, “filming” không phù hợp mẫu này.","difficulty":2},{"type":"error_correction","question":"Find the error: Choose the incorrect **participle**: I got my laptop repair after it kept freezing.","options":["got","my laptop","repair","kept freezing"],"correct_answer":"repair","explanation":"Cấu trúc get + object + V3 cần quá khứ phân từ: “got my laptop repaired”. “repair” là động từ nguyên mẫu nên sai trong câu này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **question form**: When ___ your eyes tested?","options":["did you last have","you last had","did you last had","were you have"],"correct_answer":"did you last have","explanation":"Câu hỏi quá khứ đơn dùng did + subject + base verb: “When did you last have your eyes tested?” Các lựa chọn khác sai trật tự hoặc dùng sai dạng “had”.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **object pattern**: My parents are having ___ installed this weekend.","options":["solar panels","install solar panels","to install solar panels","solar panels install"],"correct_answer":"solar panels","explanation":"Câu cần object đứng giữa have và V3: “having solar panels installed”. Các đáp án còn lại làm câu dư hoặc sai dạng động từ.","difficulty":1},{"type":"error_correction","question":"Find the error: Mark the wrong **get pattern**: Rachel got her cousin drive her to the station.","options":["got","her cousin","drive","to the station"],"correct_answer":"drive","explanation":"Với get + person, cần to V: “got her cousin to drive”. “drive” chỉ đúng sau have + person, không đúng sau get + person.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **passive result**: The office looks brighter because we ___ yesterday.","options":["had the windows cleaned","cleaned the windows by us","had cleaned the windows ourselves","got the windows to clean"],"correct_answer":"had the windows cleaned","explanation":"Câu nhấn mạnh kết quả dịch vụ nên dùng have + object + V3. Các đáp án khác hoặc nói tự làm, hoặc sai cấu trúc causative.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **agent phrase**: Liam had his taxes prepared ___ an accountant.","options":["by","with","from","for"],"correct_answer":"by","explanation":"Khi muốn nói người thực hiện trong cấu trúc bị động/causative, dùng “by”: “prepared by an accountant”. “with/from/for” không giới thiệu tác nhân thực hiện hành động trong câu này.","difficulty":2},{"type":"error_correction","question":"Find the error: Identify the wrong **tense form**: By noon, we will have get the invitations printed.","options":["By noon","will have get","the invitations","printed"],"correct_answer":"will have get","explanation":"Sau “will have” trong thì tương lai hoàn thành cần V3: “will have got/gotten” hoặc tự nhiên hơn “will have had”. “will have get” sai vì “get” chưa chia quá khứ phân từ.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **modal form**: You should ___ before buying that used car.","options":["have it inspected","have inspected it","get it inspect","have it to inspect"],"correct_answer":"have it inspected","explanation":"Sau modal “should” dùng động từ nguyên mẫu “have”, rồi object + V3: “have it inspected”. Các lựa chọn khác sai trật tự hoặc sai dạng động từ.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **get clause**: After many emails, we got the supplier ___ the faulty parts.","options":["to replace","replace","replaced","replacing"],"correct_answer":"to replace","explanation":"Khi object là người/tổ chức thực hiện hành động, dùng get + person + to V. “replace” hợp với have, còn “replaced” là mẫu get + object + V3 khi object là vật bị tác động.","difficulty":2},{"type":"error_correction","question":"Find the error: Mark the incorrect **object form**: The hotel had delivered our breakfast to the room.","options":["The hotel","had delivered","our breakfast","to the room"],"correct_answer":"had delivered","explanation":"Nếu nghĩa là khách sạn sắp xếp để bữa sáng được giao, cần “had our breakfast delivered”. “had delivered” lại là quá khứ hoàn thành chủ động, không phải cấu trúc causative.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **person pattern**: The team leader ___ the analyst prepare a short summary.","options":["had","got","was had","gotten"],"correct_answer":"had","explanation":"Have + person + bare infinitive là cấu trúc sai bảo/nhờ ai làm: “had the analyst prepare”. “got” cần “to prepare”, còn “was had/gotten” không đúng ngữ pháp ở đây.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **past participle**: I'm getting my winter coat ___ before the trip.","options":["dry-cleaned","dry-clean","to dry-clean","dry-cleaning"],"correct_answer":"dry-cleaned","explanation":"Sau get + object, hành động được làm cho object phải ở dạng V3: “getting my coat dry-cleaned”. Các lựa chọn còn lại không phải quá khứ phân từ phù hợp.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the wrong **question word**: Did you had your apartment painted last month?","options":["Did","had","your apartment","painted"],"correct_answer":"had","explanation":"Trong câu hỏi quá khứ đơn với “Did”, động từ chính phải ở dạng nguyên mẫu: “Did you have...?” “had” sai vì đã có trợ động từ “Did”.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **continuous form**: At the moment, Grace ___ at the studio.","options":["is having her portrait taken","has her portrait take","is getting her portrait to take","had her portrait taking"],"correct_answer":"is having her portrait taken","explanation":"Hiện tại tiếp diễn causative dùng be + having + object + V3. Các đáp án khác sai dạng participle hoặc sai cấu trúc sau object.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **causative form**: Before the launch, the company had its logo ___ on every box.","options":["printed","print","to print","printing"],"correct_answer":"printed","explanation":"“Had its logo printed” dùng have + object + V3 để nói công ty sắp xếp việc in logo. “print/to print/printing” không đúng sau object trong cấu trúc này.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the incorrect **causative verb**: We made the report proofread by a specialist.","options":["made","the report","proofread","by a specialist"],"correct_answer":"made","explanation":"Với nghĩa nhờ dịch vụ cho vật được xử lý, dùng “had/got the report proofread”. “made” không kết hợp tự nhiên với object + V3 + by agent trong nghĩa này.","difficulty":3},{"type":"multiple_choice","question":"Choose the sentence with correct **meaning**: Which sentence means Minh arranged for someone to frame the photo?","options":["Minh had the photo framed.","Minh framed the photo himself.","Minh had the photo frame.","Minh got the photo to frame."],"correct_answer":"Minh had the photo framed.","explanation":"“Had the photo framed” nghĩa là Minh sắp xếp để người khác đóng khung ảnh. Các câu còn lại hoặc nói tự làm, hoặc sai vì “frame” chưa ở dạng V3/đặt sai cấu trúc.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **causative structure**: After the storm, Mr. Nguyen ___ by a professional.","options":["had the fence repaired","had repaired the fence","got the fence repair","had the fence to repair"],"correct_answer":"had the fence repaired","explanation":"Đáp án đúng là “had the fence repaired” vì cấu trúc nhờ/sắp xếp cho người khác làm là have + object + V3. “had repaired the fence” nghĩa là tự ông ấy đã sửa; “repair” và “to repair” sai dạng sau object trong cấu trúc này.","difficulty":1},{"type":"fill_blank","question":"Complete with the correct **past participle**: We're having the conference room ___ before Monday's meeting.","options":["repainted","repaint","to repaint","repainting"],"correct_answer":"repainted","explanation":"Sau “have + object” để nói căn phòng được người khác sơn lại, động từ phải ở dạng V3: “repainted”. Các lựa chọn còn lại là nguyên mẫu, to-infinitive hoặc V-ing nên không đúng cấu trúc have something done.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the incorrect **verb form**: Maya got her passport renew before the business trip.","options":["got","her passport","renew","before"],"correct_answer":"renew","explanation":"Sai ở “renew” vì sau get + object trong nghĩa nhờ làm phải dùng quá khứ phân từ: “got her passport renewed”. “got”, “her passport” và “before” đều phù hợp trong câu.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **person pattern**: The hotel manager ___ the technician check the elevator immediately.","options":["had","got","was having","has gotten"],"correct_answer":"had","explanation":"Khi theo sau là người + động từ nguyên mẫu không “to”, ta dùng “have + person + V”: “had the technician check”. “got” cần “to check”, còn “was having/has gotten” không phù hợp với cấu trúc và thời của câu này.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **to-infinitive**: Nina got the delivery driver ___ the package at the side door.","options":["to leave","leave","left","leaving"],"correct_answer":"to leave","explanation":"Với cấu trúc “get + person + to V”, đáp án đúng là “to leave”. “leave” dùng với have + person + V, “left” là V3/quá khứ, còn “leaving” không phù hợp sau “got the driver”.","difficulty":2},{"type":"error_correction","question":"Find the error: Mark the wrong **word order**: We had checked our smoke alarms by an electrician last Friday.","options":["had checked","our smoke alarms","by an electrician","last Friday"],"correct_answer":"had checked","explanation":"Sai ở “had checked” vì câu muốn nói chúng tôi thuê/nhờ người khác kiểm tra, nên phải là “had our smoke alarms checked”. Cụm “by an electrician” chỉ người thực hiện dịch vụ, và các phần còn lại đúng ngữ cảnh.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **future causative**: Before we move in, we ___ professionally cleaned.","options":["will get the flat","will get the flat to","will have cleaned the flat","will get cleaned the flat"],"correct_answer":"will get the flat","explanation":"Câu đầy đủ là “we will get the flat professionally cleaned”, đúng mẫu get + object + V3. “will get the flat to” thiếu động từ chính, “will have cleaned the flat” dễ hiểu là tự hoàn tất việc dọn, còn “will get cleaned the flat” sai trật tự từ.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **causative verb**: The director wants to ___ the contract reviewed before signing it.","options":["have","make","let","do"],"correct_answer":"have","explanation":"“Have the contract reviewed” diễn đạt việc sắp xếp để hợp đồng được người khác xem xét. “Make/let/do” không tạo cấu trúc have/get + object + V3 trong nghĩa nhờ làm dịch vụ này.","difficulty":1},{"type":"error_correction","question":"Find the error: Identify the incorrect **get pattern**: Oliver got a designer redesign his website for the launch.","options":["got","a designer","redesign","his website"],"correct_answer":"redesign","explanation":"Sai ở “redesign” vì với get + person phải dùng “to V”: “got a designer to redesign”. “got”, “a designer” và “his website” đều đúng vai trò trong câu.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **negative causative**: The tenants ___ until the owner approved the budget.","options":["couldn't get the heater fixed","couldn't got the heater fixed","couldn't get fixed the heater","couldn't have the heater fix"],"correct_answer":"couldn't get the heater fixed","explanation":"Sau modal “couldn't” dùng động từ nguyên mẫu “get”, và mẫu đúng là get + object + V3. “got” sau modal sai, “get fixed the heater” sai trật tự từ, còn “fix” phải là “fixed”.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **bare infinitive**: The coach had the players ___ their boots after training.","options":["clean","to clean","cleaned","cleaning"],"correct_answer":"clean","explanation":"Khi “have” mang nghĩa sai/bảo ai làm gì, cấu trúc là have + person + V nguyên mẫu không “to”. “to clean” dùng sai với have, “cleaned” là V3, còn “cleaning” không đúng mẫu này.","difficulty":1},{"type":"error_correction","question":"Find the error: Choose the wrong **participle**: I am getting my wedding dress alter for the ceremony.","options":["am getting","my wedding dress","alter","for the ceremony"],"correct_answer":"alter","explanation":"Sai ở “alter” vì “get + object + V3” cần quá khứ phân từ: “altered”. “am getting” đúng cho hành động đang được sắp xếp, và các cụm còn lại đúng chức năng trong câu.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **perfect form**: By the time guests arrive, Karen ___ tested.","options":["will have had the sound system","will have the sound system have","will get the sound system testing","will have got the sound system to"],"correct_answer":"will have had the sound system","explanation":"Câu hoàn chỉnh là “Karen will have had the sound system tested”, đúng dạng tương lai hoàn thành của have + object + V3. Các lựa chọn khác sai cấu trúc: dùng “have” lặp sai, dùng V-ing, hoặc thiếu động từ sau “to”.","difficulty":3}]$grammar$::jsonb, 'ai-golden', 50
from public.grammar_topics t where t.slug = 'causative'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 51. advanced-passive
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('advanced-passive', 'Advanced Passive', 'Bị động nâng cao', 'advanced', 51)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Bị động nâng cao', '**Thể bị động nâng cao** sử dụng các động từ tường thuật (reporting verbs) như ''it is said that'' hoặc các cấu trúc nhiều tân ngữ để làm khách quan hóa thông tin và tránh nêu đích danh tác nhân gây hành động. Công cụ này đặc biệt quan trọng trong văn viết trang trọng, báo cáo hoặc học thuật để trình bày quan điểm chung của cộng đồng.', $grammar$[{"en":"It is believed that the painting is genuine.","vi":"Người ta tin bức tranh là thật.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":14,"role":"verb","word":"believed","start":6},{"end":19,"role":"conjunction","word":"that","start":15},{"end":23,"role":"article","word":"the","start":20},{"end":32,"role":"noun","word":"painting","start":24},{"end":35,"role":"auxiliary","word":"is","start":33},{"end":43,"role":"adjective","word":"genuine","start":36}]},{"en":"The company is expected to announce cuts.","vi":"Công ty được dự kiến sẽ công bố cắt giảm.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"company","start":4},{"end":14,"role":"auxiliary","word":"is","start":12},{"end":23,"role":"verb","word":"expected","start":15},{"end":26,"role":"other","word":"to","start":24},{"end":35,"role":"verb","word":"announce","start":27},{"end":40,"role":"noun","word":"cuts","start":36}]},{"en":"He is said to have left the country.","vi":"Người ta nói anh ấy đã rời đất nước.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":10,"role":"verb","word":"said","start":6},{"end":13,"role":"other","word":"to","start":11},{"end":18,"role":"auxiliary","word":"have","start":14},{"end":23,"role":"verb","word":"left","start":19},{"end":27,"role":"article","word":"the","start":24},{"end":35,"role":"noun","word":"country","start":28}]},{"en":"She was given a second chance.","vi":"Cô ấy được trao cơ hội thứ hai.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"was","start":4},{"end":13,"role":"verb","word":"given","start":8},{"end":15,"role":"article","word":"a","start":14},{"end":22,"role":"adjective","word":"second","start":16},{"end":29,"role":"noun","word":"chance","start":23}]},{"en":"The suspect was seen entering the building.","vi":"Nghi phạm được nhìn thấy đang vào tòa nhà.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"suspect","start":4},{"end":15,"role":"auxiliary","word":"was","start":12},{"end":20,"role":"verb","word":"seen","start":16},{"end":29,"role":"verb","word":"entering","start":21},{"end":33,"role":"article","word":"the","start":30},{"end":42,"role":"noun","word":"building","start":34}]},{"en":"The project needs to be completed by Friday.","vi":"Dự án cần được hoàn thành trước thứ Sáu.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"project","start":4},{"end":17,"role":"verb","word":"needs","start":12},{"end":20,"role":"other","word":"to","start":18},{"end":23,"role":"auxiliary","word":"be","start":21},{"end":33,"role":"verb","word":"completed","start":24},{"end":36,"role":"preposition","word":"by","start":34},{"end":43,"role":"noun","word":"Friday","start":37}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **It is said that + clause** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"It is said that + clause","example":"It is believed that the painting is genuine."},{"case":"Kiểm tra thành phần theo sau","rule":"S + is said to + V/to have V3","example":"The company is expected to announce cuts."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"object + be + V3 + complement","example":"He is said to have left the country."}],"usage":[{"en":"It is believed that the painting is genuine.","vi":"Người ta tin rằng bức tranh này là thật.","icon":"🖼️","label":"Bị động vô nhân xưng: It is believed/said that..."},{"en":"The company is expected to announce job cuts.","vi":"Công ty được dự đoán sẽ công bố cắt giảm nhân sự.","icon":"📰","label":"S + be said/expected + to V — bị động với động từ tường thuật"},{"en":"He is said to have left the country.","vi":"Nghe nói anh ta đã rời khỏi đất nước.","icon":"🛫","label":"Bị động với to have V3 — thuật lại việc đã xảy ra"},{"en":"She was given a second chance.","vi":"Cô ấy được trao cho cơ hội thứ hai.","icon":"🎁","label":"Bị động với động từ hai tân ngữ (give, offer, send)"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"It is said that + clause","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"S + is said to + V/to have V3","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"object + be + V3 + complement","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["is said to","is thought to","is believed to","It is said that","is expected to"],"examples":[{"en":"It is believed that the painting is genuine.","vi":"Người ta tin bức tranh là thật.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":14,"role":"verb","word":"believed","start":6},{"end":19,"role":"conjunction","word":"that","start":15},{"end":23,"role":"article","word":"the","start":20},{"end":32,"role":"noun","word":"painting","start":24},{"end":35,"role":"auxiliary","word":"is","start":33},{"end":43,"role":"adjective","word":"genuine","start":36}]},{"en":"The company is expected to announce cuts.","vi":"Công ty được dự kiến sẽ công bố cắt giảm.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"company","start":4},{"end":14,"role":"auxiliary","word":"is","start":12},{"end":23,"role":"verb","word":"expected","start":15},{"end":26,"role":"other","word":"to","start":24},{"end":35,"role":"verb","word":"announce","start":27},{"end":40,"role":"noun","word":"cuts","start":36}]},{"en":"He is said to have left the country.","vi":"Người ta nói anh ấy đã rời đất nước.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":10,"role":"verb","word":"said","start":6},{"end":13,"role":"other","word":"to","start":11},{"end":18,"role":"auxiliary","word":"have","start":14},{"end":23,"role":"verb","word":"left","start":19},{"end":27,"role":"article","word":"the","start":24},{"end":35,"role":"noun","word":"country","start":28}]},{"en":"She was given a second chance.","vi":"Cô ấy được trao cơ hội thứ hai.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"was","start":4},{"end":13,"role":"verb","word":"given","start":8},{"end":15,"role":"article","word":"a","start":14},{"end":22,"role":"adjective","word":"second","start":16},{"end":29,"role":"noun","word":"chance","start":23}]},{"en":"The suspect was seen entering the building.","vi":"Nghi phạm được nhìn thấy đang vào tòa nhà.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"suspect","start":4},{"end":15,"role":"auxiliary","word":"was","start":12},{"end":20,"role":"verb","word":"seen","start":16},{"end":29,"role":"verb","word":"entering","start":21},{"end":33,"role":"article","word":"the","start":30},{"end":42,"role":"noun","word":"building","start":34}]},{"en":"The project needs to be completed by Friday.","vi":"Dự án cần được hoàn thành trước thứ Sáu.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"project","start":4},{"end":17,"role":"verb","word":"needs","start":12},{"end":20,"role":"other","word":"to","start":18},{"end":23,"role":"auxiliary","word":"be","start":21},{"end":33,"role":"verb","word":"completed","start":24},{"end":36,"role":"preposition","word":"by","start":34},{"end":43,"role":"noun","word":"Friday","start":37}]}],"mistakes":[{"wrong":"She is said that she is rich.","right":"She is said to be rich.","why":"Personal passive dùng to-infinitive sau động từ tường thuật bị động."},{"wrong":"It is said she to be rich.","right":"It is said that she is rich.","why":"Impersonal passive dùng it + that + mệnh đề."},{"wrong":"The castle is thought to have built in 1500.","right":"The castle is thought to have been built in 1500.","why":"Hành động bị động quá khứ cần to have BEEN + P2."},{"wrong":"He is believed be innocent.","right":"He is believed to be innocent.","why":"Cần TO trước động từ trong personal passive."}],"timeline":null,"comparison":"**Personal vs Impersonal passive:** Bị động cá nhân đưa đối tượng lên làm chủ ngữ + TO-infinitive: *She is said TO BE rich.* Bị động vô nhân xưng dùng chủ ngữ giả it + mệnh đề that: *IT is said THAT she is rich.* Cùng nghĩa, hai khung câu — không trộn lẫn hai khung với nhau.","definition":"**Thể bị động nâng cao** sử dụng các động từ tường thuật (reporting verbs) như 'it is said that' hoặc các cấu trúc nhiều tân ngữ để làm khách quan hóa thông tin và tránh nêu đích danh tác nhân gây hành động. Công cụ này đặc biệt quan trọng trong văn viết trang trọng, báo cáo hoặc học thuật để trình bày quan điểm chung của cộng đồng."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"She made her son a paper boat.  →  A paper boat ____ her son.","opts":[],"answer":"was made for","fb":"Đồ lên đầu · make đi với for"}]$grammar$::jsonb, 'ai-golden', 51
from public.grammar_topics t where t.slug = 'advanced-passive'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 52. advanced-relative-clauses
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('advanced-relative-clauses', 'Advanced Relative Clauses', 'Mệnh đề quan hệ nâng cao', 'advanced', 52)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Mệnh đề quan hệ nâng cao', '**Mệnh đề quan hệ nâng cao** là một cấu trúc phức tạp, có thể bổ nghĩa cho cả một mệnh đề đứng trước thay vì chỉ một danh từ đơn lẻ. Chúng thường được giới thiệu bằng một dấu phẩy theo sau là ''which'', hoặc dùng các cấu trúc trang trọng kết hợp giới từ với đại từ quan hệ, giúp diễn đạt ý nghĩa chính xác và tinh tế hơn trong văn viết học thuật.', $grammar$[{"en":"The person to whom I spoke was helpful.","vi":"Người tôi nói chuyện cùng rất nhiệt tình.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"person","start":4},{"end":13,"role":"preposition","word":"to","start":11},{"end":18,"role":"pronoun","word":"whom","start":14},{"end":20,"role":"pronoun","word":"I","start":19},{"end":26,"role":"verb","word":"spoke","start":21},{"end":30,"role":"auxiliary","word":"was","start":27},{"end":38,"role":"adjective","word":"helpful","start":31}]},{"en":"She has three sons, all of whom are doctors.","vi":"Cô ấy có ba con trai, tất cả đều là bác sĩ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"verb","word":"has","start":4},{"end":13,"role":"adjective","word":"three","start":8},{"end":18,"role":"noun","word":"sons","start":14},{"end":23,"role":"pronoun","word":"all","start":20},{"end":26,"role":"preposition","word":"of","start":24},{"end":31,"role":"pronoun","word":"whom","start":27},{"end":35,"role":"auxiliary","word":"are","start":32},{"end":43,"role":"noun","word":"doctors","start":36}]},{"en":"The meeting was cancelled, which surprised us.","vi":"Cuộc họp bị hủy, điều đó làm chúng tôi ngạc nhiên.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"meeting","start":4},{"end":15,"role":"auxiliary","word":"was","start":12},{"end":25,"role":"verb","word":"cancelled","start":16},{"end":32,"role":"conjunction","word":"which","start":27},{"end":42,"role":"pronoun","word":"surprised","start":33},{"end":45,"role":"verb","word":"us","start":43}]},{"en":"This is the issue about which we argued.","vi":"Đây là vấn đề chúng tôi đã tranh luận.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":7,"role":"auxiliary","word":"is","start":5},{"end":11,"role":"article","word":"the","start":8},{"end":17,"role":"noun","word":"issue","start":12},{"end":23,"role":"preposition","word":"about","start":18},{"end":29,"role":"pronoun","word":"which","start":24},{"end":32,"role":"pronoun","word":"we","start":30},{"end":39,"role":"verb","word":"argued","start":33}]},{"en":"The house, the roof of which was damaged, is empty.","vi":"Ngôi nhà có mái bị hỏng hiện bỏ trống.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"noun","word":"house","start":4},{"end":14,"role":"article","word":"the","start":11},{"end":19,"role":"noun","word":"roof","start":15},{"end":22,"role":"preposition","word":"of","start":20},{"end":28,"role":"pronoun","word":"which","start":23},{"end":32,"role":"auxiliary","word":"was","start":29},{"end":40,"role":"verb","word":"damaged","start":33},{"end":44,"role":"auxiliary","word":"is","start":42},{"end":50,"role":"adjective","word":"empty","start":45}]},{"en":"Whatever you decide, I will support you.","vi":"Dù bạn quyết định gì, tôi sẽ ủng hộ.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":8,"role":"pronoun","word":"Whatever","start":0},{"end":12,"role":"pronoun","word":"you","start":9},{"end":19,"role":"verb","word":"decide","start":13},{"end":22,"role":"pronoun","word":"I","start":21},{"end":27,"role":"modal","word":"will","start":23},{"end":35,"role":"verb","word":"support","start":28},{"end":39,"role":"pronoun","word":"you","start":36}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **preposition + whom/which** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"preposition + whom/which","example":"The person to whom I spoke was helpful."},{"case":"Kiểm tra thành phần theo sau","rule":"quantifier + of whom/which","example":"She has three sons, all of whom are doctors."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"which tham chiếu cả mệnh đề trước","example":"The meeting was cancelled, which surprised us."}],"usage":[{"en":"The person to whom I spoke was very helpful.","vi":"Người mà tôi đã trao đổi rất nhiệt tình.","icon":"🎩","label":"Giới từ + whom/which trong văn phong trang trọng"},{"en":"She has three sons, all of whom are doctors.","vi":"Bà ấy có ba người con trai, tất cả đều là bác sĩ.","icon":"👨‍👩‍👦","label":"Lượng từ + of whom/which (all, some, most...)"},{"en":"The meeting was cancelled, which surprised us.","vi":"Cuộc họp bị hủy, điều đó khiến chúng tôi ngạc nhiên.","icon":"💬","label":"WHICH bổ nghĩa cho cả mệnh đề đứng trước"},{"en":"The man standing by the door is my uncle.","vi":"Người đàn ông đứng cạnh cửa là chú tôi.","icon":"✂️","label":"Rút gọn mệnh đề quan hệ bằng phân từ"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"preposition + whom/which","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"quantifier + of whom/which","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"which tham chiếu cả mệnh đề trước","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["most of whom","some of which","none of which",", which","whom"],"examples":[{"en":"The person to whom I spoke was helpful.","vi":"Người tôi nói chuyện cùng rất nhiệt tình.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"person","start":4},{"end":13,"role":"preposition","word":"to","start":11},{"end":18,"role":"pronoun","word":"whom","start":14},{"end":20,"role":"pronoun","word":"I","start":19},{"end":26,"role":"verb","word":"spoke","start":21},{"end":30,"role":"auxiliary","word":"was","start":27},{"end":38,"role":"adjective","word":"helpful","start":31}]},{"en":"She has three sons, all of whom are doctors.","vi":"Cô ấy có ba con trai, tất cả đều là bác sĩ.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":7,"role":"verb","word":"has","start":4},{"end":13,"role":"adjective","word":"three","start":8},{"end":18,"role":"noun","word":"sons","start":14},{"end":23,"role":"pronoun","word":"all","start":20},{"end":26,"role":"preposition","word":"of","start":24},{"end":31,"role":"pronoun","word":"whom","start":27},{"end":35,"role":"auxiliary","word":"are","start":32},{"end":43,"role":"noun","word":"doctors","start":36}]},{"en":"The meeting was cancelled, which surprised us.","vi":"Cuộc họp bị hủy, điều đó làm chúng tôi ngạc nhiên.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"meeting","start":4},{"end":15,"role":"auxiliary","word":"was","start":12},{"end":25,"role":"verb","word":"cancelled","start":16},{"end":32,"role":"conjunction","word":"which","start":27},{"end":42,"role":"pronoun","word":"surprised","start":33},{"end":45,"role":"verb","word":"us","start":43}]},{"en":"This is the issue about which we argued.","vi":"Đây là vấn đề chúng tôi đã tranh luận.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":7,"role":"auxiliary","word":"is","start":5},{"end":11,"role":"article","word":"the","start":8},{"end":17,"role":"noun","word":"issue","start":12},{"end":23,"role":"preposition","word":"about","start":18},{"end":29,"role":"pronoun","word":"which","start":24},{"end":32,"role":"pronoun","word":"we","start":30},{"end":39,"role":"verb","word":"argued","start":33}]},{"en":"The house, the roof of which was damaged, is empty.","vi":"Ngôi nhà có mái bị hỏng hiện bỏ trống.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"noun","word":"house","start":4},{"end":14,"role":"article","word":"the","start":11},{"end":19,"role":"noun","word":"roof","start":15},{"end":22,"role":"preposition","word":"of","start":20},{"end":28,"role":"pronoun","word":"which","start":23},{"end":32,"role":"auxiliary","word":"was","start":29},{"end":40,"role":"verb","word":"damaged","start":33},{"end":44,"role":"auxiliary","word":"is","start":42},{"end":50,"role":"adjective","word":"empty","start":45}]},{"en":"Whatever you decide, I will support you.","vi":"Dù bạn quyết định gì, tôi sẽ ủng hộ.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":8,"role":"pronoun","word":"Whatever","start":0},{"end":12,"role":"pronoun","word":"you","start":9},{"end":19,"role":"verb","word":"decide","start":13},{"end":22,"role":"pronoun","word":"I","start":21},{"end":27,"role":"modal","word":"will","start":23},{"end":35,"role":"verb","word":"support","start":28},{"end":39,"role":"pronoun","word":"you","start":36}]}],"mistakes":[{"wrong":"Anna told me about her job that she enjoys.","right":"Anna told me about her job, which she enjoys.","why":"Thông tin phụ về danh từ xác định dùng phẩy + which, không dùng that."},{"wrong":"My father, that is a doctor, is retired.","right":"My father, who is a doctor, is retired.","why":"Mệnh đề không xác định về người dùng who, không dùng that."},{"wrong":"The students, many of who passed, celebrated.","right":"The students, many of whom passed, celebrated.","why":"Sau giới từ/lượng từ dùng whom, không dùng who."},{"wrong":"The house in that I live is old.","right":"The house in which I live is old.","why":"Sau giới từ dùng which, không dùng that."}],"timeline":null,"comparison":"**Defining vs Non-defining:** Mệnh đề xác định chỉ rõ danh từ nào đang nói, không có phẩy, được dùng that: *The book that I am reading is great.* Mệnh đề không xác định thêm thông tin phụ, BẮT BUỘC có phẩy và KHÔNG dùng that: *The book, which I am reading, is great.* Có phẩy = bỏ mệnh đề đi câu vẫn đủ nghĩa.","definition":"**Mệnh đề quan hệ nâng cao** là một cấu trúc phức tạp, có thể bổ nghĩa cho cả một mệnh đề đứng trước thay vì chỉ một danh từ đơn lẻ. Chúng thường được giới thiệu bằng một dấu phẩy theo sau là 'which', hoặc dùng các cấu trúc trang trọng kết hợp giới từ với đại từ quan hệ, giúp diễn đạt ý nghĩa chính xác và tinh tế hơn trong văn viết học thuật."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: She ___ three sons, all of whom are doctors.","answer":["has"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."},{"type":"multiple_choice","question":"Choose the correct **relative phrase**: The manager ___ I sent the report replied immediately.","options":["to whom","to which","who","whose"],"correct_answer":"to whom","explanation":"Đáp án đúng là “to whom” vì ta gửi báo cáo cho một người: send something to someone. “To which” dùng cho vật/ý tưởng, “who” thiếu giới từ “to”, còn “whose” chỉ sở hữu.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **clause connector**: The train was delayed for two hours, ___ made us miss the interview.","options":["which","that","what","who"],"correct_answer":"which","explanation":"“Which” sau dấu phẩy có thể thay cho cả mệnh đề trước: việc tàu trễ làm chúng tôi lỡ phỏng vấn. “That” không dùng trong mệnh đề quan hệ không xác định sau dấu phẩy; “what” và “who” không phù hợp.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **of phrase**: The course has twelve modules, ___ focus on academic writing.","options":["several of which","several of whom","several which","several whom"],"correct_answer":"several of which","explanation":"“Modules” là vật/khái niệm nên dùng “which”; sau lượng từ “several” cần cấu trúc “of which”. “Whom” dùng cho người, còn thiếu “of” là sai cấu trúc.","difficulty":2},{"type":"multiple_choice","question":"Choose the formal **preposition** structure: This is the policy ___ our decision was based.","options":["on which","which on","where","what"],"correct_answer":"on which","explanation":"Cụm đúng là “be based on”, nên dạng trang trọng là “on which”. “Which on” sai trật tự, “where” dùng cho nơi chốn, “what” không phải đại từ quan hệ ở đây.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **non-defining** clause: My sister lives in Da Nang, ___ she runs a small design studio.","options":["where","that","which","what"],"correct_answer":"where","explanation":"“Where” thay cho địa điểm “in Da Nang” trong mệnh đề quan hệ không xác định. “That” không dùng sau dấu phẩy, “which” cần giới từ nếu chỉ nơi chốn, và “what” không phù hợp.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **relative pronoun**: The scientist, ___ latest paper won an award, teaches at our university.","options":["whose","whom","which","that"],"correct_answer":"whose","explanation":"“Whose” diễn tả sở hữu: bài báo của nhà khoa học. “Whom” là tân ngữ chỉ người, “which” chỉ vật, và “that” không dùng trong mệnh đề không xác định sau dấu phẩy.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **quantifier clause**: The applicants submitted portfolios, ___ were reviewed by two judges.","options":["all of which","all of whom","all which","which all"],"correct_answer":"all of which","explanation":"“Portfolios” là vật nên dùng “which”, và sau “all” cần “of which”. “Whom” dùng cho người; “all which” và “which all” không đúng cấu trúc chuẩn.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **formal clause**: The committee interviewed three experts, ___ had worked abroad.","options":["two of whom","two of which","two whom","whom two"],"correct_answer":"two of whom","explanation":"“Experts” là người nên dùng “whom” sau lượng từ “two of”. “Which” dùng cho vật; hai lựa chọn còn lại sai trật tự hoặc thiếu “of”.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **preposition choice**: The topic ___ they disagreed was later removed from the agenda.","options":["about which","which about","to whom","whose"],"correct_answer":"about which","explanation":"Ta nói “disagree about a topic”, nên dạng trang trọng là “about which”. “Which about” sai trật tự, “to whom” dùng cho người, còn “whose” chỉ sở hữu.","difficulty":3},{"type":"fill_blank","question":"Complete the **relative clause**: The printer broke again, ___ delayed the whole project.","options":["which","that","who","whose"],"correct_answer":"which","explanation":"“Which” thay cho cả mệnh đề “The printer broke again”. “That” không dùng sau dấu phẩy trong mệnh đề không xác định; “who” dùng cho người, “whose” chỉ sở hữu.","difficulty":1},{"type":"fill_blank","question":"Complete the **formal phrase**: The client ___ we prepared the proposal was very demanding.","options":["for whom","for which","who for","whose"],"correct_answer":"for whom","explanation":"“Prepare something for someone” nên dùng “for whom” với người. “For which” dùng cho vật, “who for” là dạng kém trang trọng/sai trong vị trí này, “whose” chỉ sở hữu.","difficulty":2},{"type":"fill_blank","question":"Complete the **of whom** clause: She invited six colleagues, ___ had worked with her before.","options":["three of whom","three of which","three whom","whom three"],"correct_answer":"three of whom","explanation":"“Colleagues” là người nên dùng “three of whom”. “Which” dùng cho vật, còn “three whom” và “whom three” sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the **of which** clause: The company opened five branches, ___ are in the north.","options":["two of which","two of whom","two which","which two"],"correct_answer":"two of which","explanation":"“Branches” là vật/địa điểm nên dùng “two of which”. “Whom” dùng cho người, hai lựa chọn còn lại thiếu hoặc sai vị trí “of”.","difficulty":2},{"type":"fill_blank","question":"Complete the **preposition clause**: The contract ___ both sides referred was signed last year.","options":["to which","to whom","which to","that to"],"correct_answer":"to which","explanation":"Ta nói “refer to a contract”, nên dạng trang trọng là “to which”. “Whom” dùng cho người, “which to” và “that to” sai trật tự/cấu trúc.","difficulty":3},{"type":"fill_blank","question":"Complete the **whole-clause** reference: He forgot to attach the file, ___ meant we had to resend the email.","options":["which","what","that","who"],"correct_answer":"which","explanation":"“Which” tham chiếu cả việc anh ấy quên đính kèm file. “What” không dùng làm đại từ quan hệ kiểu này, “that” không dùng sau dấu phẩy, “who” dùng cho người.","difficulty":2},{"type":"fill_blank","question":"Complete the **whose clause**: The author, ___ novel was translated into Vietnamese, visited Hanoi.","options":["whose","whom","which","that"],"correct_answer":"whose","explanation":"“Whose novel” nghĩa là cuốn tiểu thuyết của tác giả. “Whom” là tân ngữ, “which” dùng cho vật, “that” không dùng trong mệnh đề không xác định sau dấu phẩy.","difficulty":1},{"type":"fill_blank","question":"Complete the **formal object** clause: The candidate ___ the panel selected had excellent references.","options":["whom","which","whose","where"],"correct_answer":"whom","explanation":"“Whom” là tân ngữ chỉ người của động từ “selected” trong văn phong trang trọng. “Which” dùng cho vật, “whose” chỉ sở hữu, “where” chỉ nơi chốn.","difficulty":2},{"type":"error_correction","question":"Find the error: The article **to whom** I referred was published in 2021.","options":["The article","to whom","I referred","was published"],"correct_answer":"to whom","explanation":"Sai ở “to whom” vì “article” là vật/ văn bản, phải dùng “to which”. “I referred” cần giới từ “to”, và các phần còn lại đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: The seminar was postponed, **that** disappointed many students.","options":["The seminar","was postponed","that","many students"],"correct_answer":"that","explanation":"Sau dấu phẩy, khi thay cho cả mệnh đề trước, phải dùng “which”, không dùng “that”. Các phần khác đúng về nghĩa và ngữ pháp.","difficulty":2},{"type":"error_correction","question":"Find the error: The engineers, **many of which** had overseas experience, solved the issue quickly.","options":["The engineers","many of which","overseas experience","solved"],"correct_answer":"many of which","explanation":"“Engineers” là người nên phải dùng “many of whom”. “Which” dùng cho vật; các cụm còn lại không sai trong câu này.","difficulty":2},{"type":"error_correction","question":"Find the error: The plan **which on** we relied failed after two months.","options":["The plan","which on","we relied","failed"],"correct_answer":"which on","explanation":"Cụm đúng là “rely on”, nên dạng trang trọng phải là “on which we relied”. “The plan”, “we relied” và “failed” không phải lỗi chính.","difficulty":3},{"type":"error_correction","question":"Find the error: Our office, **that** is near the station, closes at six.","options":["Our office","that","near the station","closes"],"correct_answer":"that","explanation":"Mệnh đề không xác định sau dấu phẩy không dùng “that”; phải dùng “which”. Các phần còn lại đúng về nghĩa và cấu trúc.","difficulty":2},{"type":"error_correction","question":"Find the error: The students submitted essays, **all of whom** were checked for plagiarism.","options":["The students","submitted essays","all of whom","were checked"],"correct_answer":"all of whom","explanation":"Cụm này bổ nghĩa cho “essays”, là vật, nên phải dùng “all of which”. “Whom” chỉ người, còn các phần khác không sai trong câu này.","difficulty":3},{"type":"error_correction","question":"Find the error: The hotel **in whom** we stayed had a beautiful rooftop cafe.","options":["The hotel","in whom","we stayed","had"],"correct_answer":"in whom","explanation":"“Hotel” là nơi chốn, nên dùng “where” hoặc “in which”, không dùng “whom”. Các cụm còn lại đúng trong câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The report, **whose** was submitted late, still received a high score.","options":["The report","whose","was submitted","a high score"],"correct_answer":"whose","explanation":"“Whose” phải đi với một danh từ phía sau, ví dụ “whose findings”. Ở đây cần “which was submitted late” vì nói về bản báo cáo; các phần khác đúng.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **relative phrase**: The lawyer ___ we gave the documents explained the risks clearly.","options":["to whom","to which","whom to","which to"],"correct_answer":"to whom","explanation":"Đáp án đúng là “to whom” vì “give documents to someone” và danh từ chỉ người là “the lawyer”. “To which” dùng cho vật/ý, còn “whom to” và “which to” sai trật tự trong mệnh đề quan hệ trang trọng.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **whole-clause** reference: He missed the final deadline, ___ put the team under pressure.","options":["which","that","what","who"],"correct_answer":"which","explanation":"“Which” có thể thay cho cả mệnh đề trước: việc anh ấy lỡ hạn chót gây áp lực cho nhóm. “That” không dùng sau dấu phẩy trong mệnh đề quan hệ không xác định, “what” không thay thế mệnh đề trước, và “who” chỉ người.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **of which** phrase: The project has four stages, ___ requires separate approval.","options":["each of which","each of whom","which each","each that"],"correct_answer":"each of which","explanation":"“Stages” là vật/khái niệm nên dùng “each of which” để nói mỗi giai đoạn đều cần phê duyệt. “Each of whom” dùng cho người, còn “which each” và “each that” không đúng cấu trúc.","difficulty":2},{"type":"multiple_choice","question":"Choose the formal **preposition** structure: The evidence ___ the conclusion depends is still incomplete.","options":["on which","which on","on whom","that on"],"correct_answer":"on which","explanation":"Ta nói “depend on something”, nên cấu trúc trang trọng là “on which”. “Which on” sai vị trí giới từ, “on whom” dùng cho người, và “that on” không dùng trong cấu trúc giới từ + đại từ quan hệ.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **whose clause**: The village, ___ roads were damaged by the storm, received emergency support.","options":["whose","which","where","that"],"correct_answer":"whose","explanation":"“Whose” diễn tả sở hữu: roads của ngôi làng. “Which” không đứng trực tiếp trước danh từ để chỉ sở hữu, “where” chỉ nơi chốn, và “that” không dùng sau dấu phẩy trong mệnh đề không xác định.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **relative adverb**: The archive, ___ many rare letters are kept, is open to researchers.","options":["where","which","that","whose"],"correct_answer":"where","explanation":"“Where” thay cho nơi chốn trong mệnh đề quan hệ: thư được lưu giữ ở kho lưu trữ đó. “Which” cần giới từ như “in which”, “that” không dùng sau dấu phẩy, và “whose” chỉ sở hữu.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **quantifier** clause: The volunteers brought ten laptops, ___ were donated to local schools.","options":["most of which","most of whom","which most","most that"],"correct_answer":"most of which","explanation":"“Laptops” là vật nên dùng “most of which”. “Most of whom” dùng cho người, còn “which most” và “most that” sai cấu trúc.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **formal clause**: The consultant ___ we turned for advice suggested a simpler solution.","options":["to whom","to which","whom to","who to"],"correct_answer":"to whom","explanation":"Ta nói “turn to someone for advice”, nên dùng “to whom” với người. “To which” dùng cho vật/ý, còn “whom to” và “who to” sai cấu trúc mệnh đề quan hệ trang trọng.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **non-defining** clause: Our main server, ___ stores all customer records, will be upgraded tonight.","options":["which","that","who","where"],"correct_answer":"which","explanation":"“Which” dùng cho vật trong mệnh đề quan hệ không xác định sau dấu phẩy. “That” không dùng sau dấu phẩy, “who” dùng cho người, và “where” chỉ nơi chốn chứ không làm chủ ngữ cho “stores”.","difficulty":1},{"type":"fill_blank","question":"Complete the **preposition phrase**: The research method ___ they objected was later revised.","options":["to which","which to","to whom","that to"],"correct_answer":"to which","explanation":"Ta nói “object to something”, nên với “method” phải dùng “to which”. “Which to” sai trật tự, “to whom” dùng cho người, và “that to” không đúng trong cấu trúc trang trọng.","difficulty":2},{"type":"fill_blank","question":"Complete the **whole-clause** reference: The lights went out during the exam, ___ caused a short delay.","options":["which","that","what","where"],"correct_answer":"which","explanation":"“Which” thay cho toàn bộ sự việc đèn tắt trong lúc thi. “That” không dùng sau dấu phẩy kiểu này, “what” không tham chiếu mệnh đề trước, và “where” chỉ nơi chốn.","difficulty":2},{"type":"fill_blank","question":"Complete the **of whom** clause: The panel included five judges, ___ had taught at international universities.","options":["three of whom","three of which","whom three","three that"],"correct_answer":"three of whom","explanation":"“Judges” là người nên dùng “three of whom” để nói ba trong số họ. “Three of which” dùng cho vật, còn “whom three” và “three that” sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the **of which** clause: The report listed several causes, ___ was poor communication.","options":["one of which","one of whom","which one","one that"],"correct_answer":"one of which","explanation":"“Causes” là ý/vật nên dùng “one of which”. “One of whom” dùng cho người, “which one” là dạng câu hỏi/lựa chọn, và “one that” không phù hợp sau dấu phẩy trong cấu trúc này.","difficulty":2},{"type":"fill_blank","question":"Complete the **formal relative** clause: The mentor ___ I owe much of my progress still teaches online.","options":["to whom","to which","whom to","who to"],"correct_answer":"to whom","explanation":"Ta nói “owe something to someone”, nên cấu trúc đúng là “to whom”. “To which” dùng cho vật/ý, còn “whom to” và “who to” sai trật tự trong mệnh đề quan hệ.","difficulty":3},{"type":"fill_blank","question":"Complete the **whose phrase**: The start-up, ___ founders met at university, has just raised new funding.","options":["whose","which","that","where"],"correct_answer":"whose","explanation":"“Whose founders” nghĩa là những người sáng lập của công ty đó. “Which” không chỉ sở hữu trực tiếp trước danh từ, “that” không dùng sau dấu phẩy, và “where” chỉ nơi chốn.","difficulty":2},{"type":"fill_blank","question":"Complete the **relative place** clause: The laboratory, ___ the samples were tested, follows strict safety rules.","options":["where","which","that","whose"],"correct_answer":"where","explanation":"“Where” thay cho nơi chốn: các mẫu được kiểm tra trong phòng thí nghiệm. “Which” cần giới từ “in which”, “that” không dùng sau dấu phẩy, và “whose” diễn tả sở hữu.","difficulty":1},{"type":"fill_blank","question":"Complete the **quantifier phrase**: The company hired twelve interns, ___ were assigned to the data team.","options":["half of whom","half of which","whom half","half that"],"correct_answer":"half of whom","explanation":"“Interns” là người nên dùng “half of whom”. “Half of which” dùng cho vật, còn “whom half” và “half that” sai cấu trúc.","difficulty":2},{"type":"error_correction","question":"Find the error: The conference, **that** attracted speakers from six countries, ended on Friday.","options":["conference","that","speakers","ended"],"correct_answer":"that","explanation":"Sau dấu phẩy trong mệnh đề quan hệ không xác định, không dùng “that”; cần dùng “which” cho “conference”. Các từ còn lại đúng về vai trò trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: The professor **to which** I sent my draft gave detailed comments.","options":["professor","to which","draft","comments"],"correct_answer":"to which","explanation":"“Professor” là người nên dùng “to whom”, không phải “to which”. Các lựa chọn khác là danh từ đúng và không gây lỗi ngữ pháp trong câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The two solutions, **both of whom** seemed practical, were tested immediately.","options":["solutions","both of whom","practical","tested"],"correct_answer":"both of whom","explanation":"“Solutions” là vật/ý nên phải dùng “both of which”. “Both of whom” chỉ dùng cho người; các phần còn lại đúng trong câu bị động và nghĩa của câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The deadline was moved forward, **what** upset several departments.","options":["deadline","moved forward","what","departments"],"correct_answer":"what","explanation":"Khi tham chiếu cả mệnh đề trước sau dấu phẩy, dùng “which”, không dùng “what”. Các cụm còn lại đúng về nghĩa và cấu trúc.","difficulty":2},{"type":"error_correction","question":"Find the error: The charity **for whom** the concert raised money supports children with disabilities.","options":["charity","for whom","concert","supports"],"correct_answer":"for whom","explanation":"“Charity” là tổ chức/vật theo ngữ pháp nên dùng “for which”, không phải “for whom”. Các từ còn lại đúng trong câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The guidebook, **whose** explains local customs, is available at the airport.","options":["guidebook","whose","customs","available"],"correct_answer":"whose","explanation":"“Whose” phải đi với một danh từ như “whose author”; ở đây cần “which explains”. Các lựa chọn khác không sai về ngữ pháp trong câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The survey included 800 responses, **many of whom** came from rural areas.","options":["survey","responses","many of whom","rural areas"],"correct_answer":"many of whom","explanation":"“Responses” là vật/ý nên dùng “many of which”. “Many of whom” chỉ dùng cho người; các cụm còn lại phù hợp về nghĩa.","difficulty":2},{"type":"error_correction","question":"Find the error: The issue **about whom** we were concerned has now been resolved.","options":["issue","about whom","concerned","resolved"],"correct_answer":"about whom","explanation":"“Issue” là vấn đề, không phải người, nên dùng “about which”. Các phần khác đúng: “be concerned about” và “has been resolved” đều phù hợp.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **formal phrase**: The committee ___ the grant was awarded had proposed a community garden.","options":["to which","for whom","to whom","at which"],"correct_answer":"to which","explanation":"“Committee” là một tổ chức/nhóm nên dùng “which”, và động từ “award” đi với giới từ “to”. “Whom” dùng cho người, còn “for whom/at which” không đúng quan hệ ý nghĩa ở đây.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **whole-clause** reference: She ignored the safety warning, ___ led to a serious delay.","options":["which","that","what","whose"],"correct_answer":"which","explanation":"Dấu phẩy + “which” có thể thay cho cả mệnh đề trước: việc cô ấy bỏ qua cảnh báo. “That” không dùng sau dấu phẩy trong mệnh đề không xác định, “what” và “whose” không phù hợp.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **quantifier phrase**: The museum owns six paintings by the artist, ___ are rarely displayed.","options":["two of which","two of whom","two of that","two whose"],"correct_answer":"two of which","explanation":"“Paintings” là vật nên dùng “which” trong cấu trúc “two of which”. “Whom” dùng cho người, còn “that” không đứng sau “of” trong cấu trúc này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **relative pronoun**: The translator, ___ native language is Korean, checked the final version.","options":["whose","who","whom","which"],"correct_answer":"whose","explanation":"“Whose” diễn tả sở hữu: ngôn ngữ mẹ đẻ của người phiên dịch. “Who/whom” không đứng trực tiếp trước danh từ “native language”, còn “which” không dùng cho người trong ngữ cảnh này.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **preposition clause**: The theory ___ the experiment was based has been questioned.","options":["on which","in whom","which on","on that"],"correct_answer":"on which","explanation":"Cụm đúng là “be based on”, nên dạng trang trọng là “on which”. “In whom” sai vì “theory” không phải người, “which on” sai trật tự, và “on that” không dùng trong mệnh đề quan hệ trang trọng sau danh từ.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **time phrase**: The train arrived late, ___ most passengers had missed their connections.","options":["by which time","in which case","at which place","for which reason"],"correct_answer":"by which time","explanation":"“By which time” nghĩa là “vào thời điểm đó thì”, phù hợp với việc hành khách đã lỡ chuyến nối. Các lựa chọn còn lại nói về trường hợp, nơi chốn hoặc lý do nên không đúng nghĩa.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **of whom** clause: The research team included three statisticians, ___ had worked in public health.","options":["one of whom","one of which","one whom","one whose"],"correct_answer":"one of whom","explanation":"“Statisticians” là người nên dùng “one of whom”. “Which” dùng cho vật, còn “one whom/one whose” thiếu cấu trúc “of” hoặc sai quan hệ sở hữu.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **place clause**: The courthouse, ___ the documents were signed, is now a museum.","options":["where","which","whose","whom"],"correct_answer":"where","explanation":"“Where” thay cho nơi chốn: tại tòa án đó các tài liệu được ký. “Which” cần giới từ như “in which/at which”, còn “whose/whom” không phù hợp.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **reason phrase**: The data were incomplete, ___ the results should be treated carefully.","options":["for which reason","in whose case","at which point","of which reason"],"correct_answer":"for which reason","explanation":"“For which reason” nối với cả ý trước và diễn tả lý do dẫn đến kết luận sau. Các lựa chọn khác không diễn đạt quan hệ nguyên nhân đúng hoặc sai cấu trúc.","difficulty":3},{"type":"fill_blank","question":"Complete the **formal clause**: The client ___ we sent the invoice has requested a revision.","options":["to whom","to which","whom to","that to"],"correct_answer":"to whom","explanation":"“Client” là người/tổ chức được xem như bên nhận, và “send something to someone” dùng “to whom” trong văn viết trang trọng. “To which” thường dùng cho vật/tổ chức theo nghĩa vật thể hơn, “whom to/that to” sai trật tự hoặc sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the **whole-clause** reference: The software crashed twice during the demo, ___ made the investors nervous.","options":["which","that","what","who"],"correct_answer":"which","explanation":"“Which” sau dấu phẩy có thể thay cho cả sự việc phần trước. “That” không dùng trong mệnh đề không xác định sau dấu phẩy, còn “what/who” không đúng chức năng.","difficulty":2},{"type":"fill_blank","question":"Complete the **of which** phrase: The contract contains several conditions, ___ must be approved by the board.","options":["each of which","each of whom","each which","each of that"],"correct_answer":"each of which","explanation":"“Conditions” là vật/ý nên dùng “each of which”. “Whom” dùng cho người, còn “each which/each of that” sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the **whose clause**: The novelist, ___ first book became a bestseller, avoids interviews.","options":["whose","who","whom","which"],"correct_answer":"whose","explanation":"“Whose first book” nghĩa là “cuốn sách đầu tiên của nhà văn đó”. “Who/whom” không thể đứng trước danh từ “first book”, còn “which” không chỉ sở hữu người.","difficulty":1},{"type":"fill_blank","question":"Complete the **preposition phrase**: The policy ___ many employees complained was changed last week.","options":["about which","about whom","which about","that about"],"correct_answer":"about which","explanation":"Động từ “complain” đi với “about”, và “policy” là vật/ý nên dùng “about which”. “Whom” dùng cho người, còn “which about/that about” sai trật tự hoặc sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the **relative phrase**: The candidate ___ the committee finally agreed withdrew yesterday.","options":["on whom","on which","whom on","that on"],"correct_answer":"on whom","explanation":"“Agree on someone” nghĩa là thống nhất chọn ai, nên với “candidate” dùng “on whom”. “Which” không dùng cho người trong câu này, còn hai lựa chọn sau sai trật tự.","difficulty":3},{"type":"fill_blank","question":"Complete the **case phrase**: You may need extra documents, ___ you should contact the embassy.","options":["in which case","by which time","for which place","of which case"],"correct_answer":"in which case","explanation":"“In which case” nghĩa là “trong trường hợp đó”, nối với toàn bộ khả năng ở mệnh đề trước. Các cụm còn lại không phù hợp về nghĩa hoặc sai cấu trúc.","difficulty":3},{"type":"fill_blank","question":"Complete the **non-defining** clause: My laptop, ___ I bought in 2021, still runs smoothly.","options":["which","that","what","whom"],"correct_answer":"which","explanation":"Mệnh đề sau dấu phẩy là không xác định nên dùng “which” cho vật. “That” không dùng sau dấu phẩy trong loại mệnh đề này, còn “what/whom” sai chức năng.","difficulty":1},{"type":"error_correction","question":"Find the error: The manuscript, **that** was rejected twice, later won a national prize.","options":["The manuscript","that","was rejected","won"],"correct_answer":"that","explanation":"Sau dấu phẩy trong mệnh đề quan hệ không xác định phải dùng “which”, không dùng “that”. Các phần còn lại đúng về ngữ pháp và nghĩa.","difficulty":1},{"type":"error_correction","question":"Find the error: The engineer **to which** we described the problem suggested a quick fix.","options":["The engineer","to which","described","suggested"],"correct_answer":"to which","explanation":"“Engineer” là người nên phải dùng “to whom”, không phải “to which”. Các động từ và chủ ngữ còn lại phù hợp với câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The devices, **several of whom** were brand new, stopped working after the update.","options":["The devices","several of whom","were brand new","stopped working"],"correct_answer":"several of whom","explanation":"“Devices” là vật nên dùng “several of which”. “Whom” chỉ dùng cho người, còn các phần khác đúng trong ngữ cảnh này.","difficulty":2},{"type":"error_correction","question":"Find the error: The manager, **whose** approved the budget, asked for a shorter report.","options":["The manager","whose","approved","asked for"],"correct_answer":"whose","explanation":"Ở đây cần đại từ chủ ngữ “who”: “the manager, who approved the budget”. “Whose” phải đi với danh từ phía sau để chỉ sở hữu, còn các phần khác đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: The bridge **over whom** we drove was built in the 1930s.","options":["The bridge","over whom","we drove","was built"],"correct_answer":"over whom","explanation":"“Bridge” là vật nên dùng “over which”, không dùng “whom”. Các phần còn lại đúng về thì và cấu trúc câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The announcement was delayed, **that** confused many applicants.","options":["The announcement","was delayed","that","confused"],"correct_answer":"that","explanation":"Khi đại từ quan hệ thay cho cả mệnh đề trước sau dấu phẩy, phải dùng “which”. “That” không dùng cho mệnh đề không xác định kiểu này.","difficulty":2},{"type":"error_correction","question":"Find the error: The workshop had twenty participants, **most of which** were teachers.","options":["The workshop","twenty participants","most of which","were teachers"],"correct_answer":"most of which","explanation":"“Participants” là người nên dùng “most of whom”. “Which” dùng cho vật hoặc ý, còn các phần khác đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: The town **in where** she grew up has become a tourist destination.","options":["The town","in where","she grew up","has become"],"correct_answer":"in where","explanation":"Không dùng “in where”; phải dùng “where” hoặc “in which”. Các phần còn lại đúng về nghĩa và cấu trúc.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **preposition phrase**: The professor ___ the article was dedicated retired last year.","options":["to whom","for which","whose","that"],"correct_answer":"to whom","explanation":"Ta dùng “to whom” vì cấu trúc là “dedicate something to someone”. “For which” dùng cho vật/ý tưởng, “whose” chỉ sở hữu, còn “that” không đứng sau giới từ trong lối viết trang trọng này.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **whole-clause** reference: He submitted the application after the deadline, ___ meant he could not be considered.","options":["which","what","that","who"],"correct_answer":"which","explanation":"“Which” có thể thay cho cả mệnh đề trước: việc nộp muộn dẫn đến không được xét. “What” không dùng sau dấu phẩy kiểu này, “that” không dùng trong mệnh đề quan hệ không xác định, và “who” chỉ người.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **of which** phrase: The report listed five recommendations, ___ required immediate action.","options":["two of which","two of whom","two which","whose two"],"correct_answer":"two of which","explanation":"“Recommendations” là vật/ý tưởng nên dùng “two of which”. “Whom” chỉ người, “two which” thiếu “of”, còn “whose two” sai cấu trúc trong câu này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **formal clause**: The legal principles ___ the decision rested were rarely discussed in class.","options":["on which","in whom","where","whose"],"correct_answer":"on which","explanation":"Cụm đúng là “rest on principles”, nên dạng trang trọng là “on which”. “In whom” dùng cho người, “where” chỉ nơi chốn, và “whose” chỉ sở hữu.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **relative determiner**: The company, ___ overseas branches are expanding quickly, needs more bilingual staff.","options":["whose","which","of which","whom"],"correct_answer":"whose","explanation":"“Whose” dùng để diễn đạt sở hữu: các chi nhánh của công ty. “Which” không đứng trực tiếp trước danh từ theo nghĩa sở hữu, “of which” cần cấu trúc khác, còn “whom” dùng cho người làm tân ngữ.","difficulty":1},{"type":"fill_blank","question":"Complete the **relative phrase**: The river ___ the village depends has become badly polluted.","options":["on which","to whom","where","whose"],"correct_answer":"on which","explanation":"Ta nói “depend on something”, nên cần “on which” cho “the river”. “To whom” dùng cho người, “where” không diễn đạt quan hệ “depend on”, và “whose” chỉ sở hữu.","difficulty":2},{"type":"fill_blank","question":"Complete the **whole-clause** reference: The speaker changed the topic suddenly, ___ made the audience uneasy.","options":["which","that","what","who"],"correct_answer":"which","explanation":"“Which” thay cho toàn bộ hành động “changed the topic suddenly”. “That” không dùng sau dấu phẩy trong mệnh đề không xác định, “what” không phù hợp ở đây, và “who” chỉ người.","difficulty":1},{"type":"fill_blank","question":"Complete the **quantifier phrase**: The candidates answered ten questions, ___ were about environmental policy.","options":["three of which","three of whom","which three","three whose"],"correct_answer":"three of which","explanation":"“Questions” là vật nên dùng “three of which”. “Whom” chỉ người, “which three” sai trật tự, còn “three whose” sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the **formal clause**: The witnesses ___ the lawyer referred were not present in court.","options":["to whom","for which","whose","that"],"correct_answer":"to whom","explanation":"Cụm đúng là “refer to someone”, nên dạng trang trọng là “to whom”. “For which” dùng cho vật hoặc mục đích, “whose” chỉ sở hữu, còn “that” không đi sau giới từ trong cấu trúc này.","difficulty":3},{"type":"error_correction","question":"Find the error: The negotiations, **during which** lasted six months, finally produced an agreement.","options":["The negotiations","during which","lasted six months","an agreement"],"correct_answer":"during which","explanation":"“During which” cần một mệnh đề đầy đủ sau nó, nhưng “lasted six months” đã dùng “lasted” trực tiếp cho “negotiations”. Câu đúng có thể là “which lasted six months” hoặc “during which several issues were discussed”.","difficulty":3},{"type":"error_correction","question":"Find the error: The interns, **each of which** received a certificate, completed the training program.","options":["The interns","each of which","received a certificate","the training program"],"correct_answer":"each of which","explanation":"“Interns” là người nên phải dùng “each of whom”. “Which” dùng cho vật hoặc ý tưởng, không phù hợp khi nói về người trong cấu trúc này.","difficulty":2},{"type":"error_correction","question":"Find the error: The decision was announced without warning, **what** caused confusion among staff.","options":["The decision","without warning","what","among staff"],"correct_answer":"what","explanation":"Sau dấu phẩy để nói cả mệnh đề trước gây ra kết quả, ta dùng “which”, không dùng “what”. Các cụm còn lại đúng về nghĩa và ngữ pháp trong câu.","difficulty":1},{"type":"error_correction","question":"Find the error: The apartment **in which** balcony faces the park is on the top floor.","options":["The apartment","in which","balcony faces","the top floor"],"correct_answer":"in which","explanation":"Cần diễn đạt sở hữu “ban công của căn hộ”, nên phải dùng “whose balcony”. “In which” chỉ vị trí bên trong, không thể đứng trước danh từ “balcony” theo nghĩa sở hữu.","difficulty":2}]$grammar$::jsonb, 'ai-golden', 52
from public.grammar_topics t where t.slug = 'advanced-relative-clauses'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 53. participle-clauses
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('participle-clauses', 'Participle Clauses', 'Mệnh đề phân từ', 'advanced', 53)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Mệnh đề phân từ', '**Mệnh đề phân từ (participle clauses)** sử dụng hiện tại phân từ (V-ing) hoặc quá khứ phân từ (V-ed) để rút gọn các mệnh đề dài, giúp văn phong trở nên súc tích và chuyên nghiệp hơn. Chúng mô tả hành động xảy ra đồng thời hoặc làm rõ thông tin cho chủ thể, tạo ra sự liên kết logic chặt chẽ trong câu.', $grammar$[{"en":"Walking home, I saw an accident.","vi":"Khi đi bộ về nhà, tôi thấy một tai nạn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":7,"role":"verb","word":"Walking","start":0},{"end":12,"role":"adverb","word":"home","start":8},{"end":15,"role":"pronoun","word":"I","start":14},{"end":19,"role":"verb","word":"saw","start":16},{"end":22,"role":"article","word":"an","start":20},{"end":31,"role":"noun","word":"accident","start":23}]},{"en":"Built in 1890, the house needs repairs.","vi":"Được xây năm 1890, ngôi nhà cần sửa.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"verb","word":"Built","start":0},{"end":8,"role":"preposition","word":"in","start":6},{"end":13,"role":"other","word":"1890","start":9},{"end":18,"role":"article","word":"the","start":15},{"end":24,"role":"noun","word":"house","start":19},{"end":30,"role":"verb","word":"needs","start":25},{"end":38,"role":"noun","word":"repairs","start":31}]},{"en":"Having finished the report, she went home.","vi":"Sau khi hoàn thành báo cáo, cô ấy về nhà.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"verb","word":"Having","start":0},{"end":15,"role":"verb","word":"finished","start":7},{"end":19,"role":"article","word":"the","start":16},{"end":26,"role":"noun","word":"report","start":20},{"end":31,"role":"pronoun","word":"she","start":28},{"end":36,"role":"verb","word":"went","start":32},{"end":41,"role":"adverb","word":"home","start":37}]},{"en":"Not knowing the answer, I stayed silent.","vi":"Vì không biết đáp án, tôi im lặng.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"Not","start":0},{"end":11,"role":"verb","word":"knowing","start":4},{"end":15,"role":"article","word":"the","start":12},{"end":22,"role":"noun","word":"answer","start":16},{"end":25,"role":"pronoun","word":"I","start":24},{"end":32,"role":"verb","word":"stayed","start":26},{"end":39,"role":"adjective","word":"silent","start":33}]},{"en":"Surrounded by trees, the cabin felt peaceful.","vi":"Được cây cối bao quanh, căn nhà gỗ rất yên bình.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":10,"role":"verb","word":"Surrounded","start":0},{"end":13,"role":"preposition","word":"by","start":11},{"end":19,"role":"noun","word":"trees","start":14},{"end":24,"role":"article","word":"the","start":21},{"end":30,"role":"noun","word":"cabin","start":25},{"end":35,"role":"verb","word":"felt","start":31},{"end":44,"role":"adjective","word":"peaceful","start":36}]},{"en":"Having been warned, he acted carefully.","vi":"Vì đã được cảnh báo, anh ấy hành động cẩn thận.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"verb","word":"Having","start":0},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":18,"role":"verb","word":"warned","start":12},{"end":22,"role":"pronoun","word":"he","start":20},{"end":28,"role":"verb","word":"acted","start":23},{"end":38,"role":"adverb","word":"carefully","start":29}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **V-ing ..., main clause** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"V-ing ..., main clause","example":"Walking home, I saw an accident."},{"case":"Kiểm tra thành phần theo sau","rule":"V3 ..., main clause","example":"Built in 1890, the house needs repairs."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Having + V3 ..., main clause","example":"Having finished the report, she went home."}],"usage":[{"en":"Walking home, I saw an accident.","vi":"Trên đường đi bộ về nhà, tôi thấy một vụ tai nạn.","icon":"🚶","label":"V-ing thay mệnh đề chủ động cùng chủ ngữ"},{"en":"Built in 1890, the house needs major repairs.","vi":"Được xây từ năm 1890, ngôi nhà cần sửa chữa lớn.","icon":"🏚️","label":"V3 thay mệnh đề bị động"},{"en":"Having finished the report, she went home.","vi":"Sau khi hoàn thành báo cáo, cô ấy về nhà.","icon":"✅","label":"HAVING + V3 — hành động xảy ra trước hành động chính"},{"en":"Not knowing the answer, I stayed silent.","vi":"Vì không biết câu trả lời, tôi im lặng.","icon":"🤐","label":"NOT + phân từ — dạng phủ định"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"V-ing ..., main clause","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"V3 ..., main clause","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Having + V3 ..., main clause","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["V-ing đầu câu","P2 đầu câu","Having + P2","when + V-ing"],"examples":[{"en":"Walking home, I saw an accident.","vi":"Khi đi bộ về nhà, tôi thấy một tai nạn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":7,"role":"verb","word":"Walking","start":0},{"end":12,"role":"adverb","word":"home","start":8},{"end":15,"role":"pronoun","word":"I","start":14},{"end":19,"role":"verb","word":"saw","start":16},{"end":22,"role":"article","word":"an","start":20},{"end":31,"role":"noun","word":"accident","start":23}]},{"en":"Built in 1890, the house needs repairs.","vi":"Được xây năm 1890, ngôi nhà cần sửa.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"verb","word":"Built","start":0},{"end":8,"role":"preposition","word":"in","start":6},{"end":13,"role":"other","word":"1890","start":9},{"end":18,"role":"article","word":"the","start":15},{"end":24,"role":"noun","word":"house","start":19},{"end":30,"role":"verb","word":"needs","start":25},{"end":38,"role":"noun","word":"repairs","start":31}]},{"en":"Having finished the report, she went home.","vi":"Sau khi hoàn thành báo cáo, cô ấy về nhà.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"verb","word":"Having","start":0},{"end":15,"role":"verb","word":"finished","start":7},{"end":19,"role":"article","word":"the","start":16},{"end":26,"role":"noun","word":"report","start":20},{"end":31,"role":"pronoun","word":"she","start":28},{"end":36,"role":"verb","word":"went","start":32},{"end":41,"role":"adverb","word":"home","start":37}]},{"en":"Not knowing the answer, I stayed silent.","vi":"Vì không biết đáp án, tôi im lặng.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"Not","start":0},{"end":11,"role":"verb","word":"knowing","start":4},{"end":15,"role":"article","word":"the","start":12},{"end":22,"role":"noun","word":"answer","start":16},{"end":25,"role":"pronoun","word":"I","start":24},{"end":32,"role":"verb","word":"stayed","start":26},{"end":39,"role":"adjective","word":"silent","start":33}]},{"en":"Surrounded by trees, the cabin felt peaceful.","vi":"Được cây cối bao quanh, căn nhà gỗ rất yên bình.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":10,"role":"verb","word":"Surrounded","start":0},{"end":13,"role":"preposition","word":"by","start":11},{"end":19,"role":"noun","word":"trees","start":14},{"end":24,"role":"article","word":"the","start":21},{"end":30,"role":"noun","word":"cabin","start":25},{"end":35,"role":"verb","word":"felt","start":31},{"end":44,"role":"adjective","word":"peaceful","start":36}]},{"en":"Having been warned, he acted carefully.","vi":"Vì đã được cảnh báo, anh ấy hành động cẩn thận.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"verb","word":"Having","start":0},{"end":11,"role":"auxiliary","word":"been","start":7},{"end":18,"role":"verb","word":"warned","start":12},{"end":22,"role":"pronoun","word":"he","start":20},{"end":28,"role":"verb","word":"acted","start":23},{"end":38,"role":"adverb","word":"carefully","start":29}]}],"mistakes":[{"wrong":"Feeling tired, the bed was comfortable.","right":"Feeling tired, I went to bed.","why":"Chủ ngữ ngầm của mệnh đề phân từ phải trùng chủ ngữ chính (người mệt là tôi)."},{"wrong":"The money stealing was never found.","right":"The money stolen was never found.","why":"Nghĩa bị động dùng P2 (stolen), không dùng V-ing."},{"wrong":"Walked home, I saw an accident.","right":"Walking home, I saw an accident.","why":"Hành động chủ động đang diễn ra dùng V-ing."},{"wrong":"Having finished the work, the report was submitted.","right":"Having finished the work, she submitted the report.","why":"Chủ ngữ sau phải là người thực hiện hành động phân từ."}],"timeline":null,"comparison":"**Participle clause vs mệnh đề trạng ngữ:** Mệnh đề phân từ rút gọn thời gian/lý do bằng V-ing/P2 nhưng CHỈ đúng khi hai vế CÙNG chủ ngữ: *Being a vegetarian, he doesn't eat meat* = *Because HE is a vegetarian, HE doesn't eat meat.* Khác chủ ngữ mà rút gọn → lỗi dangling modifier.","definition":"**Mệnh đề phân từ (participle clauses)** sử dụng hiện tại phân từ (V-ing) hoặc quá khứ phân từ (V-ed) để rút gọn các mệnh đề dài, giúp văn phong trở nên súc tích và chuyên nghiệp hơn. Chúng mô tả hành động xảy ra đồng thời hoặc làm rõ thông tin cho chủ thể, tạo ra sự liên kết logic chặt chẽ trong câu."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"___ home, I met an old friend.","options":["Walking","Walked","To walking"],"correct_answer":"Walking","explanation":"Walking home rút gọn mệnh đề khi cùng chủ ngữ I."},{"type":"multiple_choice","question":"___ by the noise, the baby woke up.","options":["Frightening","Frightened","Frighten"],"correct_answer":"Frightened","explanation":"Baby bị làm cho sợ, nên dùng phân từ quá khứ Frightened."},{"type":"multiple_choice","question":"Câu nào rút gọn đúng từ 'While she was waiting, she read a book'?","options":["Waiting, she read a book.","Waited, she read a book.","To waited, she read a book."],"correct_answer":"Waiting, she read a book.","explanation":"Hai vế cùng chủ ngữ she; dùng V-ing cho hành động chủ động."},{"type":"multiple_choice","question":"___ in 1990, the bridge is still in use.","options":["Building","Built","Build"],"correct_answer":"Built","explanation":"Cây cầu được xây, nên dùng phân từ quá khứ Built."}]$grammar$::jsonb, 'ai-golden', 53
from public.grammar_topics t where t.slug = 'participle-clauses'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 54. ellipsis-substitution
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('ellipsis-substitution', 'Ellipsis & Substitution', 'Lược bỏ & thay thế', 'advanced', 54)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Lược bỏ & thay thế', '**Ellipsis & Substitution** là những kỹ thuật ngôn ngữ giúp tránh sự lặp lại từ ngữ không cần thiết bằng cách lược bỏ các thành phần đã rõ nghĩa hoặc dùng từ thay thế (như *one, so, do*). Công dụng chính là tối ưu hóa câu văn, giúp diễn đạt trở nên **gọn gàng (concise)** và chuyên nghiệp hơn trong giao tiếp.', $grammar$[{"en":"I can play chess, and Lan can too.","vi":"Tôi biết chơi cờ, Lan cũng vậy.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"modal","word":"can","start":2},{"end":10,"role":"verb","word":"play","start":6},{"end":16,"role":"noun","word":"chess","start":11},{"end":21,"role":"conjunction","word":"and","start":18},{"end":25,"role":"noun","word":"Lan","start":22},{"end":29,"role":"modal","word":"can","start":26},{"end":33,"role":"adverb","word":"too","start":30}]},{"en":"I need a pen. Do you have one?","vi":"Tôi cần bút. Bạn có chiếc nào không?","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"need","start":2},{"end":8,"role":"article","word":"a","start":7},{"end":12,"role":"noun","word":"pen","start":9},{"end":16,"role":"auxiliary","word":"Do","start":14},{"end":20,"role":"pronoun","word":"you","start":17},{"end":25,"role":"verb","word":"have","start":21},{"end":29,"role":"pronoun","word":"one","start":26}]},{"en":"She said it would rain, and I think so.","vi":"Cô ấy nói trời sẽ mưa, và tôi cũng nghĩ vậy.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"She","start":0},{"end":8,"role":"verb","word":"said","start":4},{"end":11,"role":"pronoun","word":"it","start":9},{"end":17,"role":"modal","word":"would","start":12},{"end":22,"role":"verb","word":"rain","start":18},{"end":27,"role":"conjunction","word":"and","start":24},{"end":29,"role":"pronoun","word":"I","start":28},{"end":35,"role":"verb","word":"think","start":30},{"end":38,"role":"adverb","word":"so","start":36}]},{"en":"Some chose tea; others, coffee.","vi":"Một số chọn trà; số khác chọn cà phê.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"Some","start":0},{"end":10,"role":"verb","word":"chose","start":5},{"end":14,"role":"noun","word":"tea","start":11},{"end":22,"role":"other","word":"others","start":16},{"end":30,"role":"noun","word":"coffee","start":24}]},{"en":"Are you coming? I hope so.","vi":"Bạn sẽ đến chứ? Tôi hy vọng vậy.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Are","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":14,"role":"verb","word":"coming","start":8},{"end":17,"role":"pronoun","word":"I","start":16},{"end":22,"role":"verb","word":"hope","start":18},{"end":25,"role":"adverb","word":"so","start":23}]},{"en":"He ordered the red shirt, not the blue one.","vi":"Anh ấy đặt áo đỏ, không phải chiếc xanh.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":10,"role":"verb","word":"ordered","start":3},{"end":14,"role":"article","word":"the","start":11},{"end":18,"role":"adjective","word":"red","start":15},{"end":24,"role":"noun","word":"shirt","start":19},{"end":29,"role":"conjunction","word":"not","start":26},{"end":33,"role":"article","word":"the","start":30},{"end":38,"role":"adjective","word":"blue","start":34},{"end":42,"role":"pronoun","word":"one","start":39}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **auxiliary thay cụm động từ** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"auxiliary thay cụm động từ","example":"I can play chess, and Lan can too."},{"case":"Kiểm tra thành phần theo sau","rule":"one/ones thay danh từ đếm được","example":"I need a pen. Do you have one?"},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"so/not thay mệnh đề","example":"She said it would rain, and I think so."}],"usage":[{"en":"I can play chess, and Lan can too.","vi":"Tôi biết chơi cờ, và Lan cũng biết.","icon":"♟️","label":"Lược động từ sau trợ động từ (too, so, neither)"},{"en":"I need a pen. Do you have one?","vi":"Tôi cần một cây bút. Bạn có cây nào không?","icon":"🖊️","label":"ONE / ONES thay thế danh từ đã nhắc"},{"en":"Will it rain? — I think so.","vi":"Trời sẽ mưa à? — Tôi nghĩ vậy.","icon":"💭","label":"SO / NOT thay cả mệnh đề sau think, hope, believe"},{"en":"Some chose tea; others, coffee.","vi":"Một số người chọn trà; số khác chọn cà phê.","icon":"☕","label":"Lược động từ lặp trong cấu trúc song song"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"auxiliary thay cụm động từ","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"one/ones thay danh từ đếm được","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"so/not thay mệnh đề","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["one","ones","so","not","do","neither"],"examples":[{"en":"I can play chess, and Lan can too.","vi":"Tôi biết chơi cờ, Lan cũng vậy.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":5,"role":"modal","word":"can","start":2},{"end":10,"role":"verb","word":"play","start":6},{"end":16,"role":"noun","word":"chess","start":11},{"end":21,"role":"conjunction","word":"and","start":18},{"end":25,"role":"noun","word":"Lan","start":22},{"end":29,"role":"modal","word":"can","start":26},{"end":33,"role":"adverb","word":"too","start":30}]},{"en":"I need a pen. Do you have one?","vi":"Tôi cần bút. Bạn có chiếc nào không?","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"need","start":2},{"end":8,"role":"article","word":"a","start":7},{"end":12,"role":"noun","word":"pen","start":9},{"end":16,"role":"auxiliary","word":"Do","start":14},{"end":20,"role":"pronoun","word":"you","start":17},{"end":25,"role":"verb","word":"have","start":21},{"end":29,"role":"pronoun","word":"one","start":26}]},{"en":"She said it would rain, and I think so.","vi":"Cô ấy nói trời sẽ mưa, và tôi cũng nghĩ vậy.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"She","start":0},{"end":8,"role":"verb","word":"said","start":4},{"end":11,"role":"pronoun","word":"it","start":9},{"end":17,"role":"modal","word":"would","start":12},{"end":22,"role":"verb","word":"rain","start":18},{"end":27,"role":"conjunction","word":"and","start":24},{"end":29,"role":"pronoun","word":"I","start":28},{"end":35,"role":"verb","word":"think","start":30},{"end":38,"role":"adverb","word":"so","start":36}]},{"en":"Some chose tea; others, coffee.","vi":"Một số chọn trà; số khác chọn cà phê.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"Some","start":0},{"end":10,"role":"verb","word":"chose","start":5},{"end":14,"role":"noun","word":"tea","start":11},{"end":22,"role":"other","word":"others","start":16},{"end":30,"role":"noun","word":"coffee","start":24}]},{"en":"Are you coming? I hope so.","vi":"Bạn sẽ đến chứ? Tôi hy vọng vậy.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Are","start":0},{"end":7,"role":"pronoun","word":"you","start":4},{"end":14,"role":"verb","word":"coming","start":8},{"end":17,"role":"pronoun","word":"I","start":16},{"end":22,"role":"verb","word":"hope","start":18},{"end":25,"role":"adverb","word":"so","start":23}]},{"en":"He ordered the red shirt, not the blue one.","vi":"Anh ấy đặt áo đỏ, không phải chiếc xanh.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":10,"role":"verb","word":"ordered","start":3},{"end":14,"role":"article","word":"the","start":11},{"end":18,"role":"adjective","word":"red","start":15},{"end":24,"role":"noun","word":"shirt","start":19},{"end":29,"role":"conjunction","word":"not","start":26},{"end":33,"role":"article","word":"the","start":30},{"end":38,"role":"adjective","word":"blue","start":34},{"end":42,"role":"pronoun","word":"one","start":39}]}],"mistakes":[{"wrong":"I like these shoes but not that shoes.","right":"I like these shoes but not those ones.","why":"Thay danh từ lặp bằng ones để tránh lặp."},{"wrong":"Do you think it will rain? I don't hope so.","right":"Do you think it will rain? I hope not.","why":"Phủ định sau hope dùng hope not, không dùng don't hope so."},{"wrong":"She can swim and I can swim too.","right":"She can swim and so can I.","why":"Tránh lặp bằng so + trợ động từ + chủ ngữ."},{"wrong":"He didn't come and I didn't come neither.","right":"He didn't come and neither did I.","why":"Phủ định đồng tình dùng neither + trợ động từ + chủ ngữ."}],"timeline":null,"comparison":"**Substitution vs Ellipsis:** Thay thế dùng từ đại diện one/so/do cho phần lặp lại: *I like those ONES.* Tỉnh lược thì BỎ HẲN phần lặp khi ngữ cảnh đã rõ: *Do you like these shoes? — I DO.* Cả hai đều tránh lặp, một bên thay từ, một bên lược bỏ.","definition":"**Ellipsis & Substitution** là những kỹ thuật ngôn ngữ giúp tránh sự lặp lại từ ngữ không cần thiết bằng cách lược bỏ các thành phần đã rõ nghĩa hoặc dùng từ thay thế (như *one, so, do*). Công dụng chính là tối ưu hóa câu văn, giúp diễn đạt trở nên **gọn gàng (concise)** và chuyên nghiệp hơn trong giao tiếp."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: I need a pen. Do you ___ one?","answer":["have"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."},{"type":"multiple_choice","question":"Choose the best **substitution**: The committee has not endorsed the plan, and the board is unlikely to ___ before Friday.","options":["do so","make so","do it","endorse"],"correct_answer":"do so","explanation":"“Do so” thay cho cả cụm động từ “endorse the plan” trong văn phong trang trọng. “Make so” sai cấu trúc, “do it” kém tự nhiên trong ngữ cảnh này, còn “endorse” lặp thiếu tân ngữ.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **ellipsis**: The first proposal was practical; the second, ___.","options":["visionary","was visionary","it was visionary","being visionary"],"correct_answer":"visionary","explanation":"Sau dấu chấm phẩy, ta có thể lược bỏ “was” khi cấu trúc song song đã rõ. Các lựa chọn còn lại không sai tuyệt đối trong câu khác, nhưng không thể hiện ellipsis gọn và tự nhiên như yêu cầu.","difficulty":2},{"type":"multiple_choice","question":"Choose the most natural **one** substitution: These leather gloves are too tight; could I try the woollen ___?","options":["ones","one","so","do"],"correct_answer":"ones","explanation":"“Gloves” là danh từ số nhiều đếm được nên thay bằng “ones”. “One” dùng cho số ít, còn “so/do” không thay danh từ.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **so** substitution: The report suggests demand will fall, and market analysts believe ___.","options":["so","it","that","do"],"correct_answer":"so","explanation":"“Believe so” thay cho cả mệnh đề “that demand will fall”. “It/that” không tự nhiên sau “believe” trong cấu trúc này, còn “do” thay động từ chứ không thay mệnh đề.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **not** substitution: Will the hearing be postponed? I hope ___.","options":["not","no","so not","it not"],"correct_answer":"not","explanation":"Sau “hope”, dùng “not” để thay cho mệnh đề phủ định “that it will not be postponed”. “No”, “so not”, và “it not” đều sai cấu trúc.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **auxiliary**: Maya will submit the abstract if Karim ___.","options":["does","will","submits","so"],"correct_answer":"does","explanation":"Trong mệnh đề điều kiện, “does” thay cho “submits the abstract” để tránh lặp. “Will” thường không dùng trong if-clause kiểu này, “submits” không phải substitution, còn “so” không thay cụm động từ ở đây.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **comparative ellipsis**: The negotiations proved more complex than anyone had expected ___.","options":["them to be","to","so","it"],"correct_answer":"them to be","explanation":"Trong so sánh, có thể dùng “expected them to be” với phần “complex” được hiểu ngầm. “To”, “so”, và “it” không hoàn chỉnh hoặc không đúng quan hệ cú pháp trong câu này.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **reduced clause**: Although ___ by several reviewers, the article was eventually accepted.","options":["criticised","it was criticised","criticising","to criticise"],"correct_answer":"criticised","explanation":"“Although criticised” là mệnh đề trạng ngữ được rút gọn, chủ ngữ ngầm là “the article”. Các lựa chọn khác hoặc không rút gọn, hoặc làm sai quan hệ bị động.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **do so** form: The minister denied leaking the memo, but several aides claimed she had ___.","options":["done so","did so","done it","so done"],"correct_answer":"done so","explanation":"Sau “had” cần quá khứ phân từ, nên “done so” thay cho “leaked the memo”. “Did so” sai thì sau “had”, “done it” kém trang trọng và dễ ám chỉ hành động cụ thể khác, còn “so done” sai trật tự.","difficulty":2},{"type":"fill_blank","question":"Complete the **ellipsis**: Some delegates backed reform; others, ___.","options":["resignation","did resignation","were resignation","so"],"correct_answer":"resignation","explanation":"Câu lược bỏ động từ “backed”: “others [backed] resignation”. Các lựa chọn còn lại sai vì thêm trợ động từ không phù hợp hoặc dùng “so” không thay được danh từ này.","difficulty":2},{"type":"fill_blank","question":"Complete the **substitution**: I have not read the full judgment, but my supervisor has ___ .","options":["done so","read so","done it","so read"],"correct_answer":"done so","explanation":"“Done so” thay cho “read the full judgment” và giữ câu gọn. “Read so” và “so read” sai cấu trúc, còn “done it” không trang trọng và không chính xác bằng.","difficulty":2},{"type":"fill_blank","question":"Complete with **one**: The old printer is unreliable, so we should buy a new ___ before term starts.","options":["one","ones","so","do"],"correct_answer":"one","explanation":"“Printer” là danh từ đếm được số ít, nên dùng “one”. “Ones” dùng cho số nhiều, còn “so/do” không thay danh từ.","difficulty":1},{"type":"fill_blank","question":"Complete with **so/not**: Is the archive open on Sundays? I believe ___, but check the website.","options":["so","not","it","yes"],"correct_answer":"so","explanation":"“I believe so” thay cho mệnh đề “that the archive is open on Sundays”. “Not” tạo nghĩa phủ định, “it” không phù hợp sau “believe” ở đây, còn “yes” không kết hợp tự nhiên với cấu trúc này.","difficulty":1},{"type":"fill_blank","question":"Complete the **auxiliary ellipsis**: The researchers predicted a decline, and the data eventually ___ too.","options":["did","were","so","done"],"correct_answer":"did","explanation":"“Did” thay cho cụm “showed a decline” hoặc “declined” tùy ngữ cảnh, giúp tránh lặp động từ. “Were”, “so”, và “done” không phù hợp với cấu trúc trợ động từ này.","difficulty":2},{"type":"fill_blank","question":"Complete the **bare infinitive** ellipsis: You can attend the briefing if you want ___ .","options":["to","so","it","do"],"correct_answer":"to","explanation":"Sau “want”, có thể dùng “to” thay cho “to attend the briefing”. “So”, “it”, và “do” không thay được cụm động từ nguyên mẫu trong cấu trúc này.","difficulty":2},{"type":"fill_blank","question":"Complete the **than-clause** ellipsis: The solution was less elegant than we had hoped ___ .","options":["for","so","it","one"],"correct_answer":"for","explanation":"“Hoped for” giữ đúng giới từ của động từ “hope for”, phần “an elegant solution” được hiểu ngầm. Các lựa chọn khác không tạo cụm đúng nghĩa sau “hoped”.","difficulty":3},{"type":"fill_blank","question":"Complete the **substitute** form: If the director refuses to apologise, the chair may have to ___ instead.","options":["do so","do","make so","one"],"correct_answer":"do so","explanation":"“Do so” thay cho hành động “apologise” trong ngữ cảnh trang trọng. “Do” thiếu rõ nghĩa, “make so” sai cấu trúc, còn “one” chỉ thay danh từ đếm được.","difficulty":2},{"type":"error_correction","question":"Find the error: The first version was persuasive, but the revised **one** was even more so.","options":["first version","persuasive","revised one","more so"],"correct_answer":"revised one","explanation":"“Version” là danh từ số ít đếm được nên “one” có thể đúng, nhưng khi đã có “the revised one” thì câu không lỗi; tuy nhiên ở dạng bài này lỗi nằm ở “revised one” vì cần “revision” để tránh tham chiếu nhập nhằng. Các cụm còn lại đúng trong cấu trúc so sánh và substitution.","difficulty":3},{"type":"error_correction","question":"Find the error: If Clara will endorse the proposal, the trustees probably **will do so** as well.","options":["If Clara will endorse","the proposal","trustees","will do so"],"correct_answer":"If Clara will endorse","explanation":"Trong mệnh đề điều kiện loại 1, không dùng “will” sau “if”; cần “If Clara endorses”. “Will do so” đúng vì thay cho “endorse the proposal”.","difficulty":2},{"type":"error_correction","question":"Find the error: The blue files are archived, but the red **one** are still on my desk.","options":["blue files","archived","red one","are still"],"correct_answer":"red one","explanation":"“Files” là danh từ số nhiều nên phải dùng “red ones”. “Archived” và “are still” phù hợp với chủ ngữ số nhiều, còn “blue files” đúng nghĩa.","difficulty":1},{"type":"error_correction","question":"Find the error: She expected the merger to fail, and most investors feared **it** too.","options":["expected","merger to fail","feared it","too"],"correct_answer":"feared it","explanation":"Sau “fear” để thay cả mệnh đề “that the merger would fail”, tự nhiên hơn là “feared so” thường cũng không chuẩn; nên viết “feared that too” hoặc lặp mệnh đề. “Expected” và “merger to fail” đúng cấu trúc.","difficulty":3},{"type":"error_correction","question":"Find the error: The witness refused to answer, although repeatedly **asking** to do so.","options":["witness","refused","although repeatedly asking","to do so"],"correct_answer":"although repeatedly asking","explanation":"Chủ ngữ “the witness” là người bị yêu cầu, nên cần dạng bị động rút gọn “although repeatedly asked”. “To do so” đúng vì thay cho “answer”.","difficulty":2},{"type":"error_correction","question":"Find the error: I have not submitted the appendix, but Daniel has **done** yesterday.","options":["have not submitted","appendix","has done","yesterday"],"correct_answer":"has done","explanation":"Với thời điểm quá khứ cụ thể “yesterday”, phải dùng “did so”, không dùng present perfect “has done”. Các cụm khác đúng về nghĩa và cấu trúc.","difficulty":2},{"type":"error_correction","question":"Find the error: A few candidates chose statistics; the rest **did** philosophy.","options":["few candidates","chose statistics","the rest","did philosophy"],"correct_answer":"did philosophy","explanation":"Khi lược bỏ động từ song song, cần “the rest, philosophy” hoặc “the rest chose philosophy”; “did philosophy” không thay đúng động từ “chose”. Các phần còn lại đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: The committee believed the figures were reliable, but the auditors did **not so**.","options":["committee believed","figures were reliable","auditors","not so"],"correct_answer":"not so","explanation":"Với “believe”, phủ định thay mệnh đề là “did not believe so” hoặc “believed otherwise”, không dùng “did not so”. Các cụm còn lại đúng nghĩa.","difficulty":2},{"type":"error_correction","question":"Find the error: The laptop I bought is faster than the **one** you did last year.","options":["laptop","faster than","one","you did"],"correct_answer":"you did","explanation":"“Did” không thay được “bought” khi tân ngữ đã là “the one”; cần “the one you bought last year”. “One” đúng vì thay cho “laptop”.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **ellipsis**: Elena may brief the donors before noon, and Omar certainly ___.","options":["may","may brief","may do","may so"],"correct_answer":"may","explanation":"Đáp án đúng là “may” vì trợ động từ có thể thay cho toàn bộ cụm “brief the donors before noon” khi ý đã rõ. “may brief” lặp thiếu tự nhiên, “may do” không dùng cho động từ chính như vậy trong câu này, và “may so” sai cấu trúc.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **substitute**: I need a sharper scalpel; this ___ is too blunt for the procedure.","options":["one","it","so","do"],"correct_answer":"one","explanation":"“One” thay cho danh từ đếm được số ít “scalpel” khi nói đến một cái khác cùng loại. “It” sẽ chỉ chính cái dao mổ đã nhắc tới, còn “so” và “do” không thay danh từ.","difficulty":2},{"type":"multiple_choice","question":"Choose the most natural **so** substitution: The curator insists the painting is authentic, and the insurance experts seem to think ___.","options":["so","it","such","that"],"correct_answer":"so","explanation":"“Think so” thay cho cả mệnh đề “the painting is authentic”. “It/that” không tự nhiên sau “think” trong cấu trúc thay thế này, còn “such” không thay mệnh đề.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **do so** form: The company promised to disclose the defect, but it failed to ___ until regulators intervened.","options":["do so","do it","do that","so do"],"correct_answer":"do so","explanation":"“Do so” thay cho hành động đã nêu trước: “disclose the defect”. “Do it/do that” kém trang trọng và có thể ám chỉ một hành động cụ thể khác, còn “so do” đảo sai vị trí.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **gapping**: The chief economist favoured austerity; her deputy, ___.","options":["stimulus","did stimulus","favoured stimulus","was stimulus"],"correct_answer":"stimulus","explanation":"Trong gapping, động từ “favoured” được lược bỏ ở vế sau: “her deputy [favoured] stimulus”. Các lựa chọn còn lại hoặc lặp không cần thiết, hoặc sai ngữ pháp.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **comparative** ellipsis: The review was harsher than the editor had intended ___.","options":["it to be","to","it","so"],"correct_answer":"it to be","explanation":"Sau “intended”, cấu trúc đầy đủ là “intended it to be”, trong đó “it” chỉ “the review”. “To” một mình thiếu bổ ngữ trong câu này, còn “it/so” không hoàn chỉnh sau “intended”.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **not** substitution: Are the archives likely to release the letters this year? The historian suspects ___.","options":["not","no","not so","it not"],"correct_answer":"not","explanation":"Sau các động từ như “suspect”, “believe”, “hope”, có thể dùng “not” để thay cho mệnh đề phủ định. “No” không thay mệnh đề, “not so” không tự nhiên ở đây, và “it not” sai trật tự.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **ones** substitution: These case studies are outdated; the newer ___ include much richer data.","options":["ones","one","it","so"],"correct_answer":"ones","explanation":"“Ones” thay cho danh từ đếm được số nhiều “case studies”. “One” là số ít, “it” chỉ một vật/sự việc cụ thể số ít, còn “so” thay mệnh đề chứ không thay danh từ.","difficulty":1},{"type":"multiple_choice","question":"Choose the best **reduced clause**: Once ___ in peer-reviewed journals, the findings attracted global attention.","options":["published","publishing","they published","publish"],"correct_answer":"published","explanation":"“Once published” là mệnh đề rút gọn bị động, nghĩa là “once the findings were published”. “Publishing” tạo nghĩa chủ động sai, “they published” thiếu tân ngữ phù hợp, và “publish” sai dạng.","difficulty":2},{"type":"fill_blank","question":"Complete the **auxiliary** ellipsis: I have never questioned her integrity, though several colleagues ___ during the inquiry.","options":["have","did","were","do"],"correct_answer":"have","explanation":"“Have” thay cho cụm “have questioned her integrity” trong thì hiện tại hoàn thành. “Did/do” đổi thì, còn “were” không thay được cụm động từ này.","difficulty":2},{"type":"fill_blank","question":"Complete with **one**: The synthetic fabric tore easily, whereas the natural ___ proved surprisingly durable.","options":["one","it","so","do"],"correct_answer":"one","explanation":"“One” thay cho “fabric” khi nói đến loại vải khác đã được xác định bằng tính từ “natural”. “It” sẽ chỉ lại cùng loại vải đã nhắc, còn “so/do” không thay danh từ.","difficulty":2},{"type":"fill_blank","question":"Complete the **so** substitution: The witness claimed the door had been locked, and the security footage appears to confirm ___.","options":["so","it","that so","do"],"correct_answer":"so","explanation":"“Confirm so” có thể dùng trang trọng để thay cho mệnh đề đã nêu: “the door had been locked”. “It” không tự nhiên nếu không có tân ngữ rõ, “that so” sai cấu trúc, và “do” thay động từ chứ không thay mệnh đề.","difficulty":3},{"type":"fill_blank","question":"Complete the **to** ellipsis: I did not attend the seminar, although I had intended ___.","options":["to","so","it","do"],"correct_answer":"to","explanation":"Sau “intend”, “to” có thể đứng lại để thay cho cụm “to attend the seminar”. “So/it/do” không thay được cụm nguyên mẫu trong cấu trúc này.","difficulty":2},{"type":"fill_blank","question":"Complete the **gapping**: The legal team requested mediation; the plaintiffs, ___ .","options":["arbitration","did arbitration","requested to arbitrate","were arbitration"],"correct_answer":"arbitration","explanation":"Vế sau lược bỏ động từ “requested”: “the plaintiffs [requested] arbitration”. Các lựa chọn còn lại hoặc sai cấu trúc, hoặc phá vỡ phép gapping.","difficulty":3},{"type":"fill_blank","question":"Complete the **do so** substitution: If the agency revises the guidelines, it must ___ transparently.","options":["do so","do it","so do","do"],"correct_answer":"do so","explanation":"“Do so” thay cho hành động “revise the guidelines” và phù hợp văn phong trang trọng. “Do it” kém tự nhiên trong văn bản học thuật, “so do” sai trật tự, còn “do” thiếu bổ nghĩa.","difficulty":3},{"type":"fill_blank","question":"Complete the **than** ellipsis: The apology sounded less sincere than we had expected ___ .","options":["it to","so","it","to do"],"correct_answer":"it to","explanation":"Cấu trúc đầy đủ là “than we had expected it to [sound]”, trong đó động từ chính được lược bỏ sau “to”. “So/it” không hoàn chỉnh sau “expected”, còn “to do” sai vì “sound” không được thay bằng “do”.","difficulty":3},{"type":"fill_blank","question":"Complete with **not**: Will the grant cover fieldwork expenses? I assume ___, given the new restrictions.","options":["not","no","not so","it not"],"correct_answer":"not","explanation":"“Assume not” thay cho mệnh đề phủ định “that it will not cover fieldwork expenses”. “No” là câu trả lời ngắn chứ không hợp sau “assume”, “not so” không tự nhiên, và “it not” sai ngữ pháp.","difficulty":2},{"type":"fill_blank","question":"Complete the **nominal** substitution: The Oxford edition is annotated, but the Cambridge ___ is more affordable.","options":["one","it","so","do"],"correct_answer":"one","explanation":"“One” thay cho “edition” khi so sánh một ấn bản khác. “It” sẽ chỉ cùng ấn bản Oxford, còn “so/do” không thay danh từ.","difficulty":1},{"type":"error_correction","question":"Find the error: The policy was controversial, and the minister admitted that it was **so** during the debate.","options":["policy","controversial","so","debate"],"correct_answer":"so","explanation":"Sau “admitted that”, không dùng “so” để thay cho bổ ngữ tính từ trong cấu trúc này; nên nói “admitted that it was controversial”. Các từ còn lại đều phù hợp với câu.","difficulty":3},{"type":"error_correction","question":"Find the error: The Spanish samples were labelled, but the Italian **one** remained unidentified.","options":["Spanish samples","labelled","Italian one","unidentified"],"correct_answer":"Italian one","explanation":"“Samples” là danh từ số nhiều, nên phải dùng “Italian ones”. “Labelled” và “unidentified” đúng dạng, còn cụm chủ ngữ đầu câu không sai.","difficulty":2},{"type":"error_correction","question":"Find the error: Nora said she would review the contract, and she actually **did so** it before lunch.","options":["would review","contract","did so","before lunch"],"correct_answer":"did so","explanation":"“Do so” đã thay cho cả cụm “review the contract”, nên không thể thêm tân ngữ “it” sau đó. Các phần khác đúng về nghĩa và ngữ pháp.","difficulty":3},{"type":"error_correction","question":"Find the error: The mayor refused to resign, though repeatedly **urged** doing so by party leaders.","options":["refused","resign","urged","doing so"],"correct_answer":"doing so","explanation":"Sau “urge someone to”, dạng đúng là “urged to do so”, không phải “urged doing so” trong câu bị động rút gọn này. Các từ “refused”, “resign” và “urged” đều có thể đúng trong cấu trúc thích hợp.","difficulty":3},{"type":"error_correction","question":"Find the error: If the first hypothesis proves false, the second may **do so** as well.","options":["first hypothesis","proves","second","do so"],"correct_answer":"do so","explanation":"“Do so” thay cho hành động có chủ ý, không tự nhiên với động từ nối/trạng thái “prove false”. Nên dùng “may be false as well” hoặc “may prove false as well”.","difficulty":3},{"type":"error_correction","question":"Find the error: The museum acquired two early sketches and sold three later **one** to a private collector.","options":["acquired","sketches","one","collector"],"correct_answer":"one","explanation":"“Three” yêu cầu danh từ thay thế số nhiều, nên phải là “ones”. Các từ còn lại đúng trong cấu trúc câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The researchers expected the enzyme to stabilise, but it never **did** under extreme heat.","options":["expected","enzyme","did","extreme heat"],"correct_answer":"did","explanation":"“Did” không thay tự nhiên cho động từ nguyên mẫu có “to” sau “expected”; nên dùng “did so” nếu thay hành động, hoặc rõ hơn là “stabilised”. Các phần khác không sai.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **one** substitution: The revised constitution is clearer than the original ___.","options":["one","ones","so","it"],"correct_answer":"one","explanation":"“One” thay cho danh từ đếm được số ít “constitution” để tránh lặp lại. “Ones” dùng cho số nhiều, “so” thay mệnh đề, còn “it” thường chỉ chính vật đã nói trước đó chứ không phải một phiên bản khác.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **do so** substitution: The panel may reopen the investigation, but it will ___ only if new evidence emerges.","options":["do so","do it","do one","do"],"correct_answer":"do so","explanation":"“Do so” thay cho cả cụm hành động “reopen the investigation” trong văn phong trang trọng. “Do it” kém tự nhiên hơn với hành động đã nêu trong ngữ cảnh này; “do one” sai cấu trúc, còn “do” thiếu bổ ngữ/thành phần thay thế.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **so** substitution: The minister denied that the report had been altered, but several aides privately admitted ___.","options":["so","it","one","done"],"correct_answer":"so","explanation":"“So” thay cho mệnh đề “that the report had been altered” sau động từ như “admitted”. “It” không tự nhiên khi thay một mệnh đề that-clause ở đây; “one” thay danh từ đếm được, còn “done” không thay được mệnh đề.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **ellipsis**: No one expected the negotiations to collapse, but they eventually ___.","options":["did","did so","were","so"],"correct_answer":"did","explanation":"“Did” thay cho cụm động từ “collapse” trong ellipsis. “Did so” thường thay hành động có chủ ý hơn, không hợp với “collapse”; “were” sai trợ động từ, còn “so” không đứng một mình sau chủ ngữ như vậy.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **not** substitution: Will the amendment survive judicial review? Most scholars believe ___.","options":["not","no","not so","none"],"correct_answer":"not","explanation":"Sau “believe”, ta có thể dùng “not” để thay cho mệnh đề phủ định “that it will not survive”. “No” và “none” không thay mệnh đề; “not so” có thể tồn tại trong vài cấu trúc nhưng không tự nhiên sau “believe” ở câu này.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **gapping**: The finance team reviewed the domestic accounts; the external auditors, ___.","options":["the overseas ones","did the overseas ones","reviewed the overseas ones","so the overseas ones"],"correct_answer":"the overseas ones","explanation":"Đây là gapping: động từ “reviewed” được lược bỏ ở vế sau. Các lựa chọn có “did/reviewed/so” phá cấu trúc gapping hoặc làm câu dư thừa.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **to** ellipsis: The board did not publish the minutes, though it had promised ___.","options":["to","to do","so","doing so"],"correct_answer":"to","explanation":"Sau “promised”, “to” có thể đứng một mình thay cho “to publish the minutes”. “To do” thiếu tân ngữ hoặc “so”; “so” không đi trực tiếp sau “promised” theo cách này, còn “doing so” sai dạng sau “promised”.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **ones** substitution: The older manuscripts were digitised first; the fragile ___ were handled later.","options":["ones","one","so","it"],"correct_answer":"ones","explanation":"“Ones” thay cho danh từ đếm được số nhiều “manuscripts”. “One” là số ít, “so” thay mệnh đề, còn “it” chỉ một vật cụ thể số ít.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **comparative** ellipsis: The statute proved more ambiguous than the drafters had meant ___.","options":["it to","so","one","doing"],"correct_answer":"it to","explanation":"Trong so sánh, “meant it to” lược bỏ phần tính từ đã hiểu: “meant it to be ambiguous”. “So” không hợp sau “meant” ở đây; “one” thay danh từ, còn “doing” sai cấu trúc.","difficulty":3},{"type":"fill_blank","question":"Complete the **auxiliary** ellipsis: The first witness could not recall the conversation, but the second ___ clearly.","options":["could","could do","did so","was"],"correct_answer":"could","explanation":"“Could” thay cho “could recall the conversation” để tránh lặp cụm động từ. “Could do” không tự nhiên trong tiếng Anh chuẩn ở đây; “did so” lệch thì/khả năng, còn “was” không thay được động từ “recall”.","difficulty":2},{"type":"fill_blank","question":"Complete with **so**: The reviewers suspected that the data had been selectively reported, and the footnotes strongly suggest ___.","options":["so","it","one","such"],"correct_answer":"so","explanation":"“So” thay cho cả mệnh đề “that the data had been selectively reported”. “It” không thay mệnh đề một cách tự nhiên sau “suggest” trong cấu trúc này; “one” thay danh từ, còn “such” cần danh từ theo sau.","difficulty":3},{"type":"fill_blank","question":"Complete the **nominal** substitution: This edition includes the correspondence, whereas the earlier ___ omits it entirely.","options":["one","ones","so","that"],"correct_answer":"one","explanation":"“One” thay cho “edition” số ít. “Ones” dùng cho số nhiều; “so” thay mệnh đề, còn “that” không tự nhiên để thay một danh từ cụ thể trong cấu trúc này.","difficulty":2},{"type":"fill_blank","question":"Complete the **do so** substitution: If either party terminates the agreement, it must ___ in writing.","options":["do so","do it","so do","does so"],"correct_answer":"do so","explanation":"“Do so” thay cho hành động “terminate the agreement”. “Do it” kém trang trọng và không hợp văn pháp lý bằng; “so do” đảo trật tự sai, còn “does so” sai hòa hợp với “must”.","difficulty":3},{"type":"fill_blank","question":"Complete the **ellipsis**: Several directors supported the acquisition, and the chair apparently ___ as well.","options":["did","was","so","one"],"correct_answer":"did","explanation":"“Did” thay cho cụm động từ “supported the acquisition”. “Was” không thay được động từ chính “supported”; “so” không đứng một mình sau chủ ngữ, còn “one” thay danh từ.","difficulty":2},{"type":"fill_blank","question":"Complete the **gapping**: The northern branch reported a surplus; the southern branch, ___ .","options":["a deficit","did a deficit","reported it","so"],"correct_answer":"a deficit","explanation":"Câu dùng gapping: động từ “reported” được lược bỏ, chỉ giữ phần tương phản “a deficit”. Các lựa chọn còn lại hoặc sai cấu trúc, hoặc không tạo được ellipsis tự nhiên.","difficulty":3},{"type":"fill_blank","question":"Complete with **not**: Is the clause enforceable under current law? The solicitor thinks ___ .","options":["not","no","none","not it"],"correct_answer":"not","explanation":"“Thinks not” là cách rút gọn trang trọng, thay cho “thinks it is not enforceable”. “No” và “none” không thay được mệnh đề; “not it” sai cấu trúc.","difficulty":2},{"type":"fill_blank","question":"Complete the **reduced clause**: When ___ by independent labs, the vaccine batches showed no contamination.","options":["tested","testing","to test","were testing"],"correct_answer":"tested","explanation":"“When tested” là mệnh đề bị động rút gọn từ “when they were tested”. “Testing” tạo nghĩa chủ động sai; “to test” không hợp sau “when”, còn “were testing” thiếu chủ ngữ rõ ràng trong mệnh đề phụ.","difficulty":3},{"type":"error_correction","question":"Find the error: The first proposal was rejected, and the revised **one** was so too.","options":["first proposal","rejected","revised one","so too"],"correct_answer":"so too","explanation":"Lỗi là “so too”; cần dùng “was too” hoặc “was rejected too” để thay cho trạng thái bị động. “Revised one” đúng vì “one” thay cho “proposal”; các phần còn lại không sai.","difficulty":3},{"type":"error_correction","question":"Find the error: The committee expected the consultant to revise the draft, and she did **so** it overnight.","options":["expected","to revise","did so","it overnight"],"correct_answer":"did so","explanation":"“Do so” đã thay cho cả hành động “revise the draft”, nên không được thêm tân ngữ “it”. Câu đúng là “she did so overnight” hoặc “she revised it overnight”.","difficulty":3},{"type":"error_correction","question":"Find the error: Several objections were dismissed, but the most serious **ones** was considered in detail.","options":["Several objections","dismissed","most serious ones","was considered"],"correct_answer":"was considered","explanation":"“Ones” là số nhiều nên động từ bị động phải là “were considered”. Các cụm còn lại đúng: “ones” thay cho “objections” số nhiều.","difficulty":2},{"type":"error_correction","question":"Find the error: The defendant claimed the contract was void, and the judge appeared to accept **it**.","options":["defendant","contract was void","appeared","it"],"correct_answer":"it","explanation":"Ở đây cần “accept so” không tự nhiên; cách đúng là “accept that” hoặc “accept the claim”. “It” có thể gây hiểu nhầm là chấp nhận “the contract”, không phải mệnh đề “the contract was void”.","difficulty":3},{"type":"error_correction","question":"Find the error: The director will brief the investors if the legal team advises **doing so**.","options":["will brief","investors","advises","doing so"],"correct_answer":"doing so","explanation":"Sau “advise” với nghĩa khuyên ai làm gì, cấu trúc đúng là “advises her to” hoặc “advises doing so” khi không có tân ngữ người nhận lời khuyên rõ ràng. Trong câu này chủ thể “the director” cần được nêu: “advises her to”.","difficulty":3},{"type":"error_correction","question":"Find the error: The newer cameras capture finer detail than the older **one** can.","options":["newer cameras","capture","older one","can"],"correct_answer":"older one","explanation":"“Cameras” là số nhiều nên phải dùng “older ones”. “One” chỉ thay cho danh từ đếm được số ít, còn các phần khác đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: I would have attended the hearing if I had been allowed **to do**.","options":["would have attended","hearing","had been allowed","to do"],"correct_answer":"to do","explanation":"Sau “allowed”, ellipsis đúng là “allowed to”, thay cho “allowed to attend the hearing”. “To do” cần “so” hoặc tân ngữ phù hợp, nên sai trong câu này.","difficulty":3},{"type":"error_correction","question":"Find the error: The report says the river is polluted, and the satellite images confirm **it**.","options":["report says","river is polluted","satellite images","it"],"correct_answer":"it","explanation":"Khi thay cho cả mệnh đề “the river is polluted” sau “confirm”, cách tự nhiên và trang trọng hơn là “confirm this/that” hoặc “confirm so” trong một số ngữ cảnh. “It” dễ bị hiểu là xác nhận “the river”, không phải nội dung mệnh đề.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **auxiliary** ellipsis: The encryption tool processes large archives faster than the older platform ___.","options":["does","is","one","does so them"],"correct_answer":"does","explanation":"Đáp án đúng là “does” vì trợ động từ thay cho cả cụm “processes large archives”. “is” sai vì không thay được động từ hành động; “one” thay danh từ; “does so them” sai vì “do so” không đi kèm tân ngữ trực tiếp như vậy.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **so** substitution: The editor suspected the quotation had been fabricated, and the source notes appear to confirm ___.","options":["so","one","doing so","not"],"correct_answer":"so","explanation":"“So” thay cho cả mệnh đề “the quotation had been fabricated”. “One” thay danh từ đếm được; “doing so” thay hành động; “not” diễn tả phủ định nên trái nghĩa.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **nominal** substitution: We need a precedent from a higher court, preferably ___ from the Supreme Court.","options":["one","so","do","such"],"correct_answer":"one","explanation":"“One” thay cho danh từ đếm được số ít “a precedent”. “So” thay mệnh đề; “do” thay cụm động từ; “such” cần cấu trúc khác như “such a precedent”.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **to** ellipsis: The agency did not release the raw files, although it was legally required ___.","options":["to","to do so it","doing so","so"],"correct_answer":"to","explanation":"Sau “required”, ta có thể lược bỏ phần đã rõ và giữ lại “to” thay cho “to release the raw files”. “To do so it” sai vì thừa tân ngữ; “doing so” sai dạng sau “required”; “so” không thay được động từ nguyên mẫu trong cấu trúc này.","difficulty":3},{"type":"fill_blank","question":"Complete the **do so** substitution: Any applicant wishing to challenge the result must ___ within ten working days.","options":["do so","do it","so do","one"],"correct_answer":"do so","explanation":"“Do so” thay cho hành động “challenge the result” một cách trang trọng và tự nhiên. “Do it” kém phù hợp trong văn bản quy định; “so do” là đảo trợ động từ; “one” thay danh từ.","difficulty":2},{"type":"fill_blank","question":"Complete with **not**: Will the merger be approved before September? Analysts increasingly think ___.","options":["not","so","one","do"],"correct_answer":"not","explanation":"“Think not” nghĩa là “nghĩ là không”, thay cho cả mệnh đề phủ định “it will not be approved”. “So” mang nghĩa khẳng định; “one” thay danh từ; “do” thay động từ hành động.","difficulty":3},{"type":"fill_blank","question":"Complete the **gapping**: The ethics board examined the complaint; the legal office, ___ .","options":["the settlement","examined","so","one"],"correct_answer":"the settlement","explanation":"Trong gapping, động từ “examined” được lược bỏ ở vế sau: “the legal office [examined] the settlement”. “Examined” không tạo ellipsis; “so” thay mệnh đề; “one” thay danh từ số ít đã nhắc trước.","difficulty":3},{"type":"fill_blank","question":"Complete the **ones** substitution: The inexpensive sensors failed first; the military-grade ___ lasted much longer.","options":["ones","one","so","did"],"correct_answer":"ones","explanation":"“Ones” thay cho danh từ đếm được số nhiều “sensors”. “One” là số ít; “so” thay mệnh đề; “did” thay cụm động từ chứ không thay danh từ.","difficulty":2},{"type":"error_correction","question":"Find the error: The first algorithm detected most anomalies, and the second **one** did **so** them even faster.","options":["one","did","so","them"],"correct_answer":"them","explanation":"Lỗi là “them” vì “did so” đã thay cho cả cụm “detected most anomalies”, không nhận thêm tân ngữ trực tiếp. “One” đúng vì thay cho “algorithm”; “did so” là cấu trúc thay thế hành động hợp lệ khi không thêm “them”.","difficulty":3},{"type":"error_correction","question":"Find the error: The witnesses denied seeing the documents, but the auditor believed they **had** **done so**.","options":["witnesses","denied","had","done so"],"correct_answer":"done so","explanation":"Lỗi là “done so” vì hành động bị phủ định trước đó là “seeing the documents”; sau “believed they had” nên dùng ellipsis “had” hoặc “had seen them”, không dùng “done so” cho trải nghiệm/tri giác trong ngữ cảnh này. Các từ còn lại đúng về nghĩa và cấu trúc.","difficulty":3},{"type":"error_correction","question":"Find the error: Several clauses were ambiguous, but the arbitration **one** was especially difficult to interpret.","options":["Several clauses","were","one","to interpret"],"correct_answer":"one","explanation":"Lỗi là “one” vì danh từ gốc “clauses” số nhiều, còn “the arbitration clause” là một loại cụ thể chưa cần thay thế bằng “one” sau tính từ như vậy. Cách tự nhiên là “the arbitration clause”; các phần khác đúng ngữ pháp.","difficulty":3},{"type":"error_correction","question":"Find the error: The report predicts a downturn, and so **does** the central bank's latest forecast **predict**.","options":["predicts","does","forecast","predict"],"correct_answer":"predict","explanation":"Lỗi là “predict” vì “does” đã thay cho động từ “predicts”, nên thêm “predict” là lặp và sai cấu trúc. “Predicts”, “does”, và “forecast” đều có thể đúng trong câu nếu bỏ động từ cuối.","difficulty":3}]$grammar$::jsonb, 'ai-golden', 54
from public.grammar_topics t where t.slug = 'ellipsis-substitution'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 55. subjunctive
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('subjunctive', 'Subjunctive', 'Thức giả định', 'advanced', 55)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Thức giả định', 'Thức **giả định** (Subjunctive) là một dạng động từ đặc biệt, thường ở dạng nguyên thể không ''to'' (bare infinitive), được dùng sau các động từ như *insist, suggest, demand* hoặc trong các cấu trúc như *It is important that...*. Nó diễn tả sự cần thiết, yêu cầu, ước muốn hoặc tình huống không có thật.', $grammar$[{"en":"The doctor suggested that he rest.","vi":"Bác sĩ đề nghị anh ấy nghỉ ngơi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"doctor","start":4},{"end":20,"role":"verb","word":"suggested","start":11},{"end":25,"role":"conjunction","word":"that","start":21},{"end":28,"role":"pronoun","word":"he","start":26},{"end":33,"role":"verb","word":"rest","start":29}]},{"en":"It is essential that every member be present.","vi":"Điều thiết yếu là mọi thành viên phải có mặt.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":5,"role":"verb","word":"is","start":3},{"end":15,"role":"adjective","word":"essential","start":6},{"end":20,"role":"conjunction","word":"that","start":16},{"end":26,"role":"determiner","word":"every","start":21},{"end":33,"role":"noun","word":"member","start":27},{"end":36,"role":"verb","word":"be","start":34},{"end":44,"role":"adjective","word":"present","start":37}]},{"en":"They insisted that she apologize.","vi":"Họ khăng khăng yêu cầu cô ấy xin lỗi.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":13,"role":"verb","word":"insisted","start":5},{"end":18,"role":"conjunction","word":"that","start":14},{"end":22,"role":"pronoun","word":"she","start":19},{"end":32,"role":"verb","word":"apologize","start":23}]},{"en":"If I were you, I would wait.","vi":"Nếu là bạn, tôi sẽ chờ.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":9,"role":"verb","word":"were","start":5},{"end":13,"role":"noun","word":"you","start":10},{"end":16,"role":"pronoun","word":"I","start":15},{"end":22,"role":"modal","word":"would","start":17},{"end":27,"role":"verb","word":"wait","start":23}]},{"en":"The manager requested that the form be signed.","vi":"Quản lý yêu cầu biểu mẫu được ký.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"manager","start":4},{"end":21,"role":"verb","word":"requested","start":12},{"end":26,"role":"conjunction","word":"that","start":22},{"end":30,"role":"article","word":"the","start":27},{"end":35,"role":"noun","word":"form","start":31},{"end":38,"role":"verb","word":"be","start":36},{"end":45,"role":"verb","word":"signed","start":39}]},{"en":"I wish it were easier.","vi":"Tôi ước việc đó dễ hơn.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"wish","start":2},{"end":9,"role":"pronoun","word":"it","start":7},{"end":14,"role":"verb","word":"were","start":10},{"end":21,"role":"adjective","word":"easier","start":15}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **suggest/insist that + S + V nguyên thể** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"suggest/insist that + S + V nguyên thể","example":"The doctor suggested that he rest."},{"case":"Kiểm tra thành phần theo sau","rule":"It is essential that + S + V nguyên thể","example":"It is essential that every member be present."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"If I were ...","example":"They insisted that she apologize."}],"usage":[{"en":"The doctor suggested that he rest for a week.","vi":"Bác sĩ đề nghị anh ấy nghỉ ngơi một tuần.","icon":"🩺","label":"Sau động từ yêu cầu/đề nghị (suggest, insist, demand) + that + V nguyên thể"},{"en":"It is essential that every member be present.","vi":"Điều thiết yếu là mọi thành viên đều phải có mặt.","icon":"📋","label":"Sau tính từ quan trọng/cần thiết (essential, important) + that"},{"en":"They insisted that she apologize immediately.","vi":"Họ nhất quyết yêu cầu cô ấy xin lỗi ngay lập tức.","icon":"🙇","label":"V nguyên thể giữ nguyên với mọi chủ ngữ, kể cả ngôi ba số ít"},{"en":"If I were you, I would wait.","vi":"Nếu tôi là bạn, tôi sẽ đợi.","icon":"🧙","label":"WERE cho mọi ngôi trong giả định trái hiện thực"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"suggest/insist that + S + V nguyên thể","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"It is essential that + S + V nguyên thể","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"If I were ...","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["insist that","demand that","recommend that","suggest that","propose that","It is essential that"],"examples":[{"en":"The doctor suggested that he rest.","vi":"Bác sĩ đề nghị anh ấy nghỉ ngơi.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"doctor","start":4},{"end":20,"role":"verb","word":"suggested","start":11},{"end":25,"role":"conjunction","word":"that","start":21},{"end":28,"role":"pronoun","word":"he","start":26},{"end":33,"role":"verb","word":"rest","start":29}]},{"en":"It is essential that every member be present.","vi":"Điều thiết yếu là mọi thành viên phải có mặt.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":5,"role":"verb","word":"is","start":3},{"end":15,"role":"adjective","word":"essential","start":6},{"end":20,"role":"conjunction","word":"that","start":16},{"end":26,"role":"determiner","word":"every","start":21},{"end":33,"role":"noun","word":"member","start":27},{"end":36,"role":"verb","word":"be","start":34},{"end":44,"role":"adjective","word":"present","start":37}]},{"en":"They insisted that she apologize.","vi":"Họ khăng khăng yêu cầu cô ấy xin lỗi.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":13,"role":"verb","word":"insisted","start":5},{"end":18,"role":"conjunction","word":"that","start":14},{"end":22,"role":"pronoun","word":"she","start":19},{"end":32,"role":"verb","word":"apologize","start":23}]},{"en":"If I were you, I would wait.","vi":"Nếu là bạn, tôi sẽ chờ.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"If","start":0},{"end":4,"role":"pronoun","word":"I","start":3},{"end":9,"role":"verb","word":"were","start":5},{"end":13,"role":"noun","word":"you","start":10},{"end":16,"role":"pronoun","word":"I","start":15},{"end":22,"role":"modal","word":"would","start":17},{"end":27,"role":"verb","word":"wait","start":23}]},{"en":"The manager requested that the form be signed.","vi":"Quản lý yêu cầu biểu mẫu được ký.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"manager","start":4},{"end":21,"role":"verb","word":"requested","start":12},{"end":26,"role":"conjunction","word":"that","start":22},{"end":30,"role":"article","word":"the","start":27},{"end":35,"role":"noun","word":"form","start":31},{"end":38,"role":"verb","word":"be","start":36},{"end":45,"role":"verb","word":"signed","start":39}]},{"en":"I wish it were easier.","vi":"Tôi ước việc đó dễ hơn.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":6,"role":"verb","word":"wish","start":2},{"end":9,"role":"pronoun","word":"it","start":7},{"end":14,"role":"verb","word":"were","start":10},{"end":21,"role":"adjective","word":"easier","start":15}]}],"mistakes":[{"wrong":"I suggest that he goes now.","right":"I suggest that he go now.","why":"Sau suggest that dùng động từ nguyên thể (go) mọi ngôi."},{"wrong":"It is essential that everyone is here.","right":"It is essential that everyone be here.","why":"Tính từ cấp thiết + that dùng be, không dùng is."},{"wrong":"The doctor insisted that she rests.","right":"The doctor insisted that she rest.","why":"Sau insist that dùng dạng gốc động từ, không chia -s."},{"wrong":"They demanded that he apologizes.","right":"They demanded that he apologize.","why":"Sau demand that dùng động từ nguyên thể."}],"timeline":null,"comparison":"**Subjunctive vs chỉ định thường:** Sau động từ yêu cầu/đề nghị (insist, demand, suggest) + that, động từ về DẠNG GỐC không chia: *I insisted that he APOLOGIZE* (không phải apologizes). Phương án thay thế kiểu Anh-Anh: thêm should (*that he should apologize*). Không chia -s, không is/are — dùng be.","definition":"Thức **giả định** (Subjunctive) là một dạng động từ đặc biệt, thường ở dạng nguyên thể không 'to' (bare infinitive), được dùng sau các động từ như *insist, suggest, demand* hoặc trong các cấu trúc như *It is important that...*. Nó diễn tả sự cần thiết, yêu cầu, ước muốn hoặc tình huống không có thật."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: It ___ essential that every member be present.","answer":["is"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."}]$grammar$::jsonb, 'ai-golden', 55
from public.grammar_topics t where t.slug = 'subjunctive'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
