insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('emphasis-structures', 'Emphasis Structures', 'Cấu trúc nhấn mạnh', 'advanced', 56)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Cấu trúc nhấn mạnh', '**Emphasis Structures** là các dạng câu đặc biệt (như *cleft sentences* hoặc *negative inversion*) được sử dụng để làm nổi bật một thông tin cụ thể hoặc tạo sự kịch tính cho câu nói. Bằng cách thay đổi trật tự từ thông thường hoặc thêm các từ trợ ngữ, người dùng có thể điều hướng sự chú ý của người nghe đến **trọng tâm (focus)** của thông điệp một cách hiệu quả.', $grammar$[{"en":"I do understand your concern.","vi":"Tôi thực sự hiểu mối lo của bạn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":4,"role":"auxiliary","word":"do","start":2},{"end":15,"role":"verb","word":"understand","start":5},{"end":20,"role":"determiner","word":"your","start":16},{"end":28,"role":"noun","word":"concern","start":21}]},{"en":"She did call you yesterday.","vi":"Cô ấy quả thực đã gọi bạn hôm qua.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"did","start":4},{"end":12,"role":"verb","word":"call","start":8},{"end":16,"role":"pronoun","word":"you","start":13},{"end":26,"role":"adverb","word":"yesterday","start":17}]},{"en":"The film was so moving that I cried.","vi":"Bộ phim cảm động đến mức tôi khóc.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"film","start":4},{"end":12,"role":"auxiliary","word":"was","start":9},{"end":15,"role":"adverb","word":"so","start":13},{"end":22,"role":"adjective","word":"moving","start":16},{"end":27,"role":"conjunction","word":"that","start":23},{"end":29,"role":"pronoun","word":"I","start":28},{"end":35,"role":"verb","word":"cried","start":30}]},{"en":"It was such a difficult test that many failed.","vi":"Đó là bài kiểm tra khó đến mức nhiều người trượt.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":6,"role":"auxiliary","word":"was","start":3},{"end":11,"role":"determiner","word":"such","start":7},{"end":13,"role":"article","word":"a","start":12},{"end":23,"role":"adjective","word":"difficult","start":14},{"end":28,"role":"noun","word":"test","start":24},{"end":33,"role":"conjunction","word":"that","start":29},{"end":38,"role":"determiner","word":"many","start":34},{"end":45,"role":"noun","word":"failed","start":39}]},{"en":"I myself checked every figure.","vi":"Chính tôi đã kiểm tra từng con số.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":8,"role":"pronoun","word":"myself","start":2},{"end":16,"role":"verb","word":"checked","start":9},{"end":22,"role":"determiner","word":"every","start":17},{"end":29,"role":"noun","word":"figure","start":23}]},{"en":"What I need most is time.","vi":"Điều tôi cần nhất chính là thời gian.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"What","start":0},{"end":6,"role":"pronoun","word":"I","start":5},{"end":11,"role":"verb","word":"need","start":7},{"end":16,"role":"adverb","word":"most","start":12},{"end":19,"role":"auxiliary","word":"is","start":17},{"end":24,"role":"noun","word":"time","start":20}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **do/does/did + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"do/does/did + V","example":"I do understand your concern."},{"case":"Kiểm tra thành phần theo sau","rule":"so/such ... that","example":"She did call you yesterday."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"reflexive pronoun / emphatic adverb","example":"The film was so moving that I cried."}],"usage":[{"en":"I do understand your concern.","vi":"Tôi thật sự hiểu mối lo của bạn.","icon":"💪","label":"Trợ động từ DO/DOES nhấn mạnh động từ ở hiện tại"},{"en":"She did call you yesterday.","vi":"Cô ấy thật sự đã gọi cho bạn hôm qua mà.","icon":"📞","label":"DID nhấn mạnh động từ ở quá khứ"},{"en":"The film was so moving that I cried.","vi":"Bộ phim cảm động đến mức tôi đã khóc.","icon":"😢","label":"SO + tính từ/trạng từ + that — nhấn mạnh mức độ dẫn đến kết quả"},{"en":"It was such a difficult test that many students failed.","vi":"Bài kiểm tra khó đến nỗi nhiều học sinh trượt.","icon":"📝","label":"SUCH + (a/an) + danh từ + that — nhấn mạnh cụm danh từ"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"do/does/did + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"so/such ... that","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"reflexive pronoun / emphatic adverb","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["do + V","does + V","did + V","even","so","neither"],"examples":[{"en":"I do understand your concern.","vi":"Tôi thực sự hiểu mối lo của bạn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":4,"role":"auxiliary","word":"do","start":2},{"end":15,"role":"verb","word":"understand","start":5},{"end":20,"role":"determiner","word":"your","start":16},{"end":28,"role":"noun","word":"concern","start":21}]},{"en":"She did call you yesterday.","vi":"Cô ấy quả thực đã gọi bạn hôm qua.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"noun","word":"She","start":0},{"end":7,"role":"auxiliary","word":"did","start":4},{"end":12,"role":"verb","word":"call","start":8},{"end":16,"role":"pronoun","word":"you","start":13},{"end":26,"role":"adverb","word":"yesterday","start":17}]},{"en":"The film was so moving that I cried.","vi":"Bộ phim cảm động đến mức tôi khóc.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":8,"role":"noun","word":"film","start":4},{"end":12,"role":"auxiliary","word":"was","start":9},{"end":15,"role":"adverb","word":"so","start":13},{"end":22,"role":"adjective","word":"moving","start":16},{"end":27,"role":"conjunction","word":"that","start":23},{"end":29,"role":"pronoun","word":"I","start":28},{"end":35,"role":"verb","word":"cried","start":30}]},{"en":"It was such a difficult test that many failed.","vi":"Đó là bài kiểm tra khó đến mức nhiều người trượt.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":6,"role":"auxiliary","word":"was","start":3},{"end":11,"role":"determiner","word":"such","start":7},{"end":13,"role":"article","word":"a","start":12},{"end":23,"role":"adjective","word":"difficult","start":14},{"end":28,"role":"noun","word":"test","start":24},{"end":33,"role":"conjunction","word":"that","start":29},{"end":38,"role":"determiner","word":"many","start":34},{"end":45,"role":"noun","word":"failed","start":39}]},{"en":"I myself checked every figure.","vi":"Chính tôi đã kiểm tra từng con số.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":1,"role":"pronoun","word":"I","start":0},{"end":8,"role":"pronoun","word":"myself","start":2},{"end":16,"role":"verb","word":"checked","start":9},{"end":22,"role":"determiner","word":"every","start":17},{"end":29,"role":"noun","word":"figure","start":23}]},{"en":"What I need most is time.","vi":"Điều tôi cần nhất chính là thời gian.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"What","start":0},{"end":6,"role":"pronoun","word":"I","start":5},{"end":11,"role":"verb","word":"need","start":7},{"end":16,"role":"adverb","word":"most","start":12},{"end":19,"role":"auxiliary","word":"is","start":17},{"end":24,"role":"noun","word":"time","start":20}]}],"mistakes":[{"wrong":"He does likes it.","right":"He does like it.","why":"Sau does nhấn mạnh, động từ về nguyên thể — không thêm -s."},{"wrong":"We did enjoyed the trip.","right":"We did enjoy the trip.","why":"Sau did nhấn mạnh, động từ về nguyên thể."},{"wrong":"I do wanted to help.","right":"I did want to help.","why":"Nhấn mạnh quá khứ dùng did + động từ nguyên thể."},{"wrong":"She do love music.","right":"She does love music.","why":"Ngôi 3 số ít nhấn mạnh dùng DOES, không dùng do."}],"timeline":null,"comparison":"**Câu nhấn mạnh vs câu thường:** Thêm trợ động từ do/does/did trước động từ để KHẲNG ĐỊNH mạnh: *I DO like it* (tôi thích thật mà!) vs câu thường *I like it.* Sau do/does/did nhấn mạnh, động từ chính về NGUYÊN THỂ.","definition":"**Emphasis Structures** là các dạng câu đặc biệt (như *cleft sentences* hoặc *negative inversion*) được sử dụng để làm nổi bật một thông tin cụ thể hoặc tạo sự kịch tính cho câu nói. Bằng cách thay đổi trật tự từ thông thường hoặc thêm các từ trợ ngữ, người dùng có thể điều hướng sự chú ý của người nghe đến **trọng tâm (focus)** của thông điệp một cách hiệu quả."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"Choose the correct **cleft sentence**: Normal sentence: “Maya solved the funding problem.” Focus on Maya.","options":["It was Maya who solved the funding problem.","It was the funding problem which Maya solved it.","What Maya solved was she the funding problem.","Maya was it who solved the funding problem."],"correct_answer":"It was Maya who solved the funding problem.","explanation":"Câu chẻ “It was Maya who...” nhấn mạnh chủ thể Maya. Các lựa chọn khác sai vì thừa đại từ “it”, đảo cấu trúc không đúng, hoặc dùng “what” không hợp lý.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **negative inversion**:","options":["Rarely do senior officials admit mistakes publicly.","Rarely senior officials do admit mistakes publicly.","Rarely admit senior officials do mistakes publicly.","Rarely senior officials admit do mistakes publicly."],"correct_answer":"Rarely do senior officials admit mistakes publicly.","explanation":"Với trạng từ phủ định/giới hạn “Rarely” đứng đầu câu, cần đảo trợ động từ trước chủ ngữ: “do senior officials admit”. Các phương án còn lại giữ trật tự thường hoặc đặt trợ động từ sai vị trí.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **what-cleft** sentence:","options":["What the committee needs is a credible timeline.","What needs the committee is a credible timeline.","What the committee needs it is a credible timeline.","What is the committee needs a credible timeline."],"correct_answer":"What the committee needs is a credible timeline.","explanation":"What-cleft có dạng “What + clause + be + focus”, nên “What the committee needs is...” là đúng. Các câu khác sai do đảo từ sai, thừa “it”, hoặc thiếu mệnh đề hoàn chỉnh.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **so inversion** structure:","options":["So convincing was her explanation that nobody questioned it.","So convincing her explanation was that nobody questioned it.","So was convincing her explanation that nobody questioned it.","So convincing did her explanation was that nobody questioned it."],"correct_answer":"So convincing was her explanation that nobody questioned it.","explanation":"Khi “So + adjective” đứng đầu để nhấn mạnh, cần đảo “be” trước chủ ngữ: “So convincing was her explanation...”. Các lựa chọn khác dùng trật tự thường hoặc kết hợp sai trợ động từ với “was”.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **emphatic do** sentence:","options":["I do appreciate how carefully you handled the complaint.","I am do appreciate how carefully you handled the complaint.","I do appreciating how carefully you handled the complaint.","I did appreciate how carefully you handles the complaint."],"correct_answer":"I do appreciate how carefully you handled the complaint.","explanation":"“Do + V nguyên mẫu” dùng để nhấn mạnh ở hiện tại, nên “do appreciate” đúng. Các câu khác sai vì thêm “am”, dùng V-ing, hoặc sai hòa hợp động từ “handles”.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **such that** sentence:","options":["It was such a compelling argument that even the skeptics listened.","It was so a compelling argument that even the skeptics listened.","It was such compelling argument that even the skeptics listened.","It was a so compelling argument that even the skeptics listened."],"correct_answer":"It was such a compelling argument that even the skeptics listened.","explanation":"Với cụm danh từ đếm được số ít, dùng “such + a/an + adjective + noun + that”. “So” không đứng trước cụm danh từ theo cách này, và “such compelling argument” thiếu mạo từ.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **only inversion** sentence:","options":["Only after the contract was signed did the risks become obvious.","Only after the contract was signed the risks became obvious.","Only after did the contract was signed the risks become obvious.","Only after the contract signed did the risks became obvious."],"correct_answer":"Only after the contract was signed did the risks become obvious.","explanation":"Khi “Only after...” đứng đầu câu, mệnh đề chính phải đảo trợ động từ: “did the risks become”. Các câu khác thiếu đảo ngữ, sai bị động, hoặc dùng sai dạng động từ sau “did”.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **reflexive emphasis** sentence:","options":["The director herself rejected the proposal.","The director herselves rejected the proposal.","The director her rejected the proposal herself.","The director by herself rejected the proposal meaning personally."],"correct_answer":"The director herself rejected the proposal.","explanation":"Đại từ phản thân “herself” đặt ngay sau danh từ để nhấn mạnh chính giám đốc là người làm việc đó. “Herselves” không tồn tại, “her” sai dạng, còn “by herself” thiên về nghĩa một mình hơn là nhấn mạnh danh tính.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **not only** inversion:","options":["Not only did he ignore the warning, but he also deleted the evidence.","Not only he ignored the warning, but he also deleted the evidence.","Not only did he ignored the warning, but he also deleted the evidence.","Not only he did ignore the warning, but deleted also the evidence."],"correct_answer":"Not only did he ignore the warning, but he also deleted the evidence.","explanation":"“Not only” đầu câu cần đảo trợ động từ “did” và động từ chính về nguyên mẫu “ignore”. Các lựa chọn khác thiếu đảo, dùng “ignored” sau “did”, hoặc đặt “also” sai vị trí.","difficulty":3},{"type":"fill_blank","question":"Complete the **negative inversion**: Under no circumstances ___ the data be shared with third parties.","options":["should","the team should","the team must to","does the team should"],"correct_answer":"should","explanation":"Sau “Under no circumstances” cần đảo trợ động từ trước chủ ngữ: “should the data be shared”. Ở đây chủ ngữ “the data” đã có sẵn sau chỗ trống, nên chỉ cần “should”; các lựa chọn còn lại phá vỡ trật tự hoặc sai cấu trúc modal.","difficulty":3},{"type":"fill_blank","question":"Complete the **cleft sentence**: It was the sudden change in policy ___ caused the confusion.","options":["that","what","where","which it"],"correct_answer":"that","explanation":"Câu chẻ nhấn mạnh nguyên nhân dùng “It was + focus + that...”. “What” tạo cấu trúc khác, “where” chỉ nơi chốn, còn “which it” thừa đại từ.","difficulty":2},{"type":"fill_blank","question":"Complete the **emphatic auxiliary**: She ___ insist that the figures had been misreported.","options":["did","was","has","does"],"correct_answer":"did","explanation":"Vì mệnh đề sau dùng quá khứ “had been misreported”, “did + V nguyên mẫu” nhấn mạnh hành động trong quá khứ. “Does” sai thì, “was” và “has” không đi trực tiếp với “insist” nguyên mẫu theo nghĩa này.","difficulty":2},{"type":"fill_blank","question":"Complete the **hardly inversion**: Hardly ___ the CEO begun speaking when the microphones failed.","options":["had","did","has","was"],"correct_answer":"had","explanation":"Cấu trúc “Hardly had + subject + past participle + when...” diễn tả hai sự việc xảy ra sát nhau. “Did” không đi với phân từ “begun”, “has” lệch thì, còn “was” không tạo được thì hoàn thành.","difficulty":3},{"type":"fill_blank","question":"Complete the **so that** structure: The evidence was ___ inconclusive that the jury requested further analysis.","options":["so","such","too","very"],"correct_answer":"so","explanation":"Với tính từ “inconclusive”, dùng “so + adjective + that”. “Such” cần danh từ, “too” thường đi với “to-infinitive”, còn “very” không tạo cấu trúc kết quả với “that” theo cách này.","difficulty":2},{"type":"fill_blank","question":"Complete the **what-cleft**: What I object to ___ the assumption that silence means consent.","options":["is","are","be","being"],"correct_answer":"is","explanation":"Chủ ngữ của what-cleft là cả mệnh đề “What I object to”, được xem như số ít, nên dùng “is”. “Are” sai hòa hợp, còn “be/being” không phù hợp với câu hữu hạn.","difficulty":3},{"type":"fill_blank","question":"Complete the **little inversion**: Little ___ the researchers realise how controversial their findings would become.","options":["did","were","had","do"],"correct_answer":"did","explanation":"“Little” đầu câu mang nghĩa phủ định nên cần đảo trợ động từ; với động từ thường ở quá khứ dùng “did + realise”. “Were” không đi với động từ thường, “had” cần phân từ, “do” sai thì.","difficulty":3},{"type":"fill_blank","question":"Complete the **such inversion**: Such ___ the pressure on the minister that she resigned within days.","options":["was","did","were","had"],"correct_answer":"was","explanation":"Cấu trúc nhấn mạnh “Such was + noun phrase + that...” dùng đảo với động từ “be”. “Pressure” là danh từ không đếm được số ít nên “was” đúng; các lựa chọn khác sai trợ động từ hoặc sai số.","difficulty":3},{"type":"fill_blank","question":"Complete the **focus cleft**: The person ___ I blame is the consultant, not the junior analyst.","options":["whom","what","where","whose"],"correct_answer":"whom","explanation":"“The person whom I blame” dùng “whom” làm tân ngữ của “blame” trong mệnh đề quan hệ trang trọng. “What” không thay cho người trong cấu trúc này, “where” chỉ nơi chốn, “whose” chỉ sở hữu.","difficulty":3},{"type":"error_correction","question":"Find the error: Never before **I had seen** such a carefully staged apology.","options":["Never before","I had seen","such","a carefully staged apology"],"correct_answer":"I had seen","explanation":"Sau “Never before” đầu câu phải đảo: “had I seen”. Các cụm còn lại đúng về nghĩa và hình thức trong câu nhấn mạnh phủ định.","difficulty":3},{"type":"error_correction","question":"Find the error: It was the auditors **who they** discovered the discrepancy.","options":["It was","the auditors","who they","discovered the discrepancy"],"correct_answer":"who they","explanation":"Trong câu chẻ, sau “who” không lặp lại chủ ngữ “they”: đúng là “It was the auditors who discovered...”. Các phần khác đúng cho cấu trúc nhấn mạnh chủ thể.","difficulty":3},{"type":"error_correction","question":"Find the error: So **persuasively she spoke** that the opposition withdrew its objection.","options":["So","persuasively she spoke","that","withdrew its objection"],"correct_answer":"persuasively she spoke","explanation":"Với “So + adverb” đứng đầu, cần đảo trợ động từ: “So persuasively did she speak...”. Các phần còn lại phù hợp với cấu trúc kết quả “so...that”.","difficulty":3},{"type":"error_correction","question":"Find the error: Not until the archive was opened **historians understood** the scale of the cover-up.","options":["Not until","the archive was opened","historians understood","the scale of the cover-up"],"correct_answer":"historians understood","explanation":"Sau “Not until...” đầu câu, mệnh đề chính phải đảo: “did historians understand”. Các cụm khác đúng và tạo bối cảnh thời gian cho nhấn mạnh.","difficulty":3},{"type":"error_correction","question":"Find the error: What makes the proposal risky **are** its reliance on untested assumptions.","options":["What makes","the proposal risky","are","its reliance on untested assumptions"],"correct_answer":"are","explanation":"Chủ ngữ thật được nhấn mạnh là “its reliance”, số ít, nên dùng “is”. Các phần khác đúng cho cấu trúc what-cleft nhấn mạnh lý do.","difficulty":3},{"type":"error_correction","question":"Find the error: It was such **convincing evidence** that the judge dismissed the case immediately.","options":["It was","such","convincing evidence","that the judge dismissed"],"correct_answer":"such","explanation":"Với danh từ không đếm được “evidence”, “such convincing evidence that...” thực ra đúng nếu không có “a”; lỗi nằm ở việc câu thiếu vấn đề? Câu này không có lỗi, nên cần chọn một câu khác trong dạng bài này.","difficulty":3},{"type":"error_correction","question":"Find the error: Only when the final witness testified **the truth became** undeniable.","options":["Only when","the final witness testified","the truth became","undeniable"],"correct_answer":"the truth became","explanation":"Sau “Only when...” đứng đầu, mệnh đề chính cần đảo: “did the truth become undeniable”. Các cụm còn lại đúng về nghĩa và trật tự trong mệnh đề phụ.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **it-cleft**: Normal sentence: “The board rejected the proposal because of its hidden costs.” Focus on the reason.","options":["It was because of its hidden costs that the board rejected the proposal.","It was its hidden costs because the board rejected the proposal.","Because of its hidden costs was it that the board rejected the proposal.","It was the board that because of its hidden costs rejected the proposal."],"correct_answer":"It was because of its hidden costs that the board rejected the proposal.","explanation":"Cấu trúc cleft đúng là “It was + focus + that + clause”, và phần được nhấn mạnh ở đây là lý do. Các lựa chọn khác sai vì đảo trật tự không tự nhiên, thiếu mệnh đề “that”, hoặc nhấn mạnh sai thành phần.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **pseudo-cleft** sentence: Normal sentence: “The committee needs a transparent audit, not another promise.”","options":["What the committee needs is a transparent audit, not another promise.","What needs the committee is a transparent audit, not another promise.","What the committee does need are a transparent audit, not another promise.","It what the committee needs is a transparent audit, not another promise."],"correct_answer":"What the committee needs is a transparent audit, not another promise.","explanation":"Trong pseudo-cleft, “What + clause” làm chủ ngữ và cần động từ “is” khi trọng tâm là một danh ngữ số ít. Các phương án khác sai vì đảo sai trật tự, sai hòa hợp “are”, hoặc thêm “It” không đúng cấu trúc.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **no sooner** inversion:","options":["No sooner had the report been published than the minister denied its conclusions.","No sooner the report had been published than the minister denied its conclusions.","No sooner had the report been published when the minister denied its conclusions.","No sooner was the report published that the minister denied its conclusions."],"correct_answer":"No sooner had the report been published than the minister denied its conclusions.","explanation":"“No sooner” đứng đầu câu yêu cầu đảo trợ động từ và đi với “than”. Các lựa chọn khác sai vì không đảo, dùng “when/that” thay vì “than”, hoặc dùng cấu trúc không chuẩn.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **scarcely inversion** sentence:","options":["Scarcely had the witness left the room when the lawyers began arguing.","Scarcely the witness had left the room when the lawyers began arguing.","Scarcely had left the witness the room when the lawyers began arguing.","Scarcely did the witness left the room when the lawyers began arguing."],"correct_answer":"Scarcely had the witness left the room when the lawyers began arguing.","explanation":"Với “Scarcely” đầu câu, ta dùng đảo ngữ “had + subject + past participle” và thường đi với “when”. Các câu khác sai vì thiếu đảo, đảo sai vị trí chủ ngữ, hoặc dùng “did” với động từ quá khứ phân từ sai.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **all-cleft** sentence: Normal sentence: “We simply want a clear explanation.”","options":["All we want is a clear explanation.","All what we want is a clear explanation.","All we want are a clear explanation.","All is we want a clear explanation."],"correct_answer":"All we want is a clear explanation.","explanation":"“All + clause + be + focus” là cấu trúc nhấn mạnh tự nhiên, và “a clear explanation” là số ít nên dùng “is”. Các lựa chọn khác sai vì “All what” không chuẩn, sai hòa hợp, hoặc sai trật tự câu.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **fronting** for emphasis: Normal sentence: “I will not tolerate this level of negligence.”","options":["This level of negligence I will not tolerate.","This level of negligence will not I tolerate.","Not tolerate I will this level of negligence.","This level of negligence I not will tolerate."],"correct_answer":"This level of negligence I will not tolerate.","explanation":"Fronting đưa tân ngữ lên đầu để nhấn mạnh nhưng vẫn giữ trật tự chủ ngữ + trợ động từ + động từ chính. Các phương án khác đảo trợ động từ sai hoặc đặt phủ định sai vị trí.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **only after** inversion:","options":["Only after the data had been verified did the team release the findings.","Only after the data had been verified the team released the findings.","Only after had the data been verified did the team release the findings.","Only after the data verified did the team released the findings."],"correct_answer":"Only after the data had been verified did the team release the findings.","explanation":"Khi cụm “Only after + clause” đứng đầu, mệnh đề chính phải đảo trợ động từ: “did the team release”. Các lựa chọn khác thiếu đảo ở mệnh đề chính, đảo nhầm trong mệnh đề phụ, hoặc sai dạng động từ sau “did”.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **so emphatic** structure:","options":["So damaging were the allegations that the company withdrew the campaign.","So damaging the allegations were that the company withdrew the campaign.","So were damaging the allegations that the company withdrew the campaign.","So damaging were the allegations which the company withdrew the campaign."],"correct_answer":"So damaging were the allegations that the company withdrew the campaign.","explanation":"Cấu trúc nhấn mạnh đúng là “So + adjective + be + subject + that + clause”. Các phương án khác sai vì không đảo sau “so”, đảo sai vị trí tính từ, hoặc dùng “which” thay cho “that” trong cấu trúc kết quả.","difficulty":3},{"type":"fill_blank","question":"Complete the **not until** structure: Not until the accounts were independently audited ___ investors regain confidence.","options":["did","had","were","do"],"correct_answer":"did","explanation":"“Not until” đứng đầu câu yêu cầu đảo trợ động từ ở mệnh đề chính: “did investors regain”. “Had/were/do” sai vì không phù hợp thì, động từ chính “regain”, hoặc chủ ngữ số nhiều trong ngữ cảnh này.","difficulty":3},{"type":"fill_blank","question":"Complete the **it-cleft** sentence: It is the lack of accountability, not the initial mistake, ___ concerns the public most.","options":["that","what","which","who"],"correct_answer":"that","explanation":"Trong cleft sentence, “It is + focus + that + clause” là lựa chọn chuẩn khi nhấn mạnh sự vật/ý tưởng. “What” tạo pseudo-cleft khác, “which” kém tự nhiên trong cấu trúc này, còn “who” chỉ dùng cho người.","difficulty":2},{"type":"fill_blank","question":"Complete the **emphatic auxiliary**: The mayor ___ accept responsibility for the delay, although she denied misconduct.","options":["did","does","had","was"],"correct_answer":"did","explanation":"Câu nói về quá khứ nên dùng “did + V nguyên mẫu” để nhấn mạnh hành động “accept”. “Does” sai thì, còn “had/was” không đi trực tiếp với động từ nguyên mẫu “accept” trong cấu trúc này.","difficulty":1},{"type":"fill_blank","question":"Complete the **such inversion**: Such ___ the complexity of the case that even senior lawyers disagreed.","options":["was","were","did","had"],"correct_answer":"was","explanation":"Với “Such + be + noun phrase + that”, chủ ngữ thật là “the complexity” số ít nên dùng “was”. “Were” sai hòa hợp, còn “did/had” không phù hợp với cấu trúc “such + be”.","difficulty":3},{"type":"fill_blank","question":"Complete the **what-cleft**: What the report fails to explain ___ why the figures changed overnight.","options":["is","are","be","being"],"correct_answer":"is","explanation":"Mệnh đề “What the report fails to explain” được xem như một đơn vị số ít, nên dùng “is”. “Are” sai hòa hợp, còn “be/being” không chia theo thì và chủ ngữ.","difficulty":2},{"type":"fill_blank","question":"Complete the **on no account** inversion: On no account ___ visitors enter the laboratory without protective clothing.","options":["may","they may","are","do"],"correct_answer":"may","explanation":"“On no account” đầu câu yêu cầu đảo trợ động từ: “may visitors enter”. “They may” không đảo, “are” không đi với động từ nguyên mẫu “enter”, còn “do” không phù hợp với sắc thái cấm đoán bằng modal.","difficulty":3},{"type":"fill_blank","question":"Complete the **so that** structure: The explanation was ___ technical that several board members asked for a summary.","options":["so","such","too","very"],"correct_answer":"so","explanation":"Với tính từ “technical”, cấu trúc đúng là “so + adjective + that”. “Such” đi với danh từ/cụm danh từ, “too” thường đi với “to”, còn “very” không tạo cấu trúc kết quả “that” mạnh như vậy.","difficulty":1},{"type":"fill_blank","question":"Complete the **reflexive emphasis**: The director ___ approved the revised safety protocol.","options":["herself","her","she","hers"],"correct_answer":"herself","explanation":"Đại từ phản thân “herself” nhấn mạnh chính giám đốc là người phê duyệt. “Her/hers” sai chức năng, còn “she” không thể đứng sau danh từ để tạo nhấn mạnh kiểu này.","difficulty":1},{"type":"fill_blank","question":"Complete the **inversion**: Rarely ___ a policy caused such widespread confusion so quickly.","options":["has","did","was","does"],"correct_answer":"has","explanation":"“Rarely” đầu câu với nghĩa trải nghiệm đến hiện tại thường dùng đảo hiện tại hoàn thành: “has a policy caused”. “Did/does” không phù hợp với “caused” trong cấu trúc này, còn “was” không đi với động từ chính dạng quá khứ phân từ như vậy.","difficulty":3},{"type":"error_correction","question":"Find the error: Seldom **the committee has** faced a decision of such constitutional significance.","options":["Seldom","the committee has","a decision","constitutional significance"],"correct_answer":"the committee has","explanation":"Sau trạng từ phủ định “Seldom” ở đầu câu phải đảo trợ động từ: “has the committee faced”. Các cụm còn lại đúng về vị trí và nghĩa trong câu.","difficulty":3},{"type":"error_correction","question":"Find the error: It was the confidential memo **which revealed** the extent of the internal disagreement.","options":["It was","confidential memo","which revealed","internal disagreement"],"correct_answer":"which revealed","explanation":"Trong it-cleft trang trọng, nên dùng “that revealed” để nối phần nhấn mạnh với mệnh đề còn lại. Các cụm khác đúng: “It was” mở cleft, “confidential memo” là trọng tâm, và “internal disagreement” là danh ngữ hợp lệ.","difficulty":2},{"type":"error_correction","question":"Find the error: Only if the contract is amended **the supplier will** accept the revised schedule.","options":["Only if","the contract","is amended","the supplier will"],"correct_answer":"the supplier will","explanation":"“Only if” đứng đầu câu yêu cầu đảo ở mệnh đề chính: “will the supplier accept”. Các phần “Only if”, “the contract”, và “is amended” đều đúng trong mệnh đề điều kiện bị động.","difficulty":3},{"type":"error_correction","question":"Find the error: What the negotiators demanded **were** immediate safeguards for local workers.","options":["What the negotiators demanded","were","immediate safeguards","local workers"],"correct_answer":"were","explanation":"Trong pseudo-cleft này, mệnh đề “What the negotiators demanded” thường được xử lý như một đơn vị số ít, nên dùng “was”. Các cụm còn lại đúng về cấu trúc và nghĩa.","difficulty":2},{"type":"error_correction","question":"Find the error: So severe **the backlash was** that the publisher withdrew the article within hours.","options":["So severe","the backlash was","the publisher withdrew","within hours"],"correct_answer":"the backlash was","explanation":"Khi “So + adjective” đứng đầu để nhấn mạnh, cần đảo “was the backlash”. Các phần khác đúng: “So severe” mở cấu trúc kết quả, mệnh đề “that...” nêu hệ quả, và “within hours” là trạng ngữ thời gian.","difficulty":3},{"type":"error_correction","question":"Find the error: The policy itself **were** not controversial; what angered voters was the timing.","options":["The policy itself","were","what angered voters","the timing"],"correct_answer":"were","explanation":"Chủ ngữ “The policy itself” là số ít nên động từ phải là “was”. “Itself” dùng đúng để nhấn mạnh, và cấu trúc “what angered voters was...” cũng đúng.","difficulty":1},{"type":"error_correction","question":"Find the error: In no way **the report suggests** that the witnesses coordinated their stories.","options":["In no way","the report suggests","the witnesses","their stories"],"correct_answer":"the report suggests","explanation":"“In no way” đứng đầu câu yêu cầu đảo trợ động từ: “does the report suggest”. Các cụm còn lại đúng về nghĩa và chức năng trong câu.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **it-cleft**: Normal sentence: “The whistleblower exposed the fraud through encrypted emails.” Focus on the means.","options":["It was through encrypted emails that the whistleblower exposed the fraud.","It was encrypted emails who the whistleblower exposed the fraud through.","It was through encrypted emails which exposed the whistleblower the fraud.","It was the fraud that through encrypted emails the whistleblower exposed."],"correct_answer":"It was through encrypted emails that the whistleblower exposed the fraud.","explanation":"Câu chẻ it-cleft nhấn mạnh phương tiện bằng cấu trúc “It was + phrase + that + clause”. “Who” không dùng cho phương tiện, còn các lựa chọn khác sai trật tự từ hoặc làm mờ trọng tâm.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **what-cleft** sentence: Normal sentence: “The researchers discovered a flaw in the sampling method.”","options":["What the researchers discovered was a flaw in the sampling method.","What discovered the researchers was a flaw in the sampling method.","What the researchers discovered were a flaw in the sampling method.","What was the researchers discovered a flaw in the sampling method."],"correct_answer":"What the researchers discovered was a flaw in the sampling method.","explanation":"What-cleft dùng “What + clause + be + focus”; chủ ngữ “What the researchers discovered” xem như một đơn vị nên dùng “was”. Các câu khác sai đảo trật tự, sai hòa hợp hoặc ghép mệnh đề không đúng.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **negative inversion** sentence:","options":["Under no circumstances should confidential data be shared with contractors.","Under no circumstances confidential data should be shared with contractors.","Under no circumstances should be shared confidential data with contractors.","Under no circumstances data confidential should be shared with contractors."],"correct_answer":"Under no circumstances should confidential data be shared with contractors.","explanation":"Sau cụm phủ định đầu câu “Under no circumstances”, cần đảo trợ động từ trước chủ ngữ: “should confidential data”. Các lựa chọn khác giữ trật tự thường hoặc đảo sai vị trí thành phần.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **little inversion** sentence:","options":["Little did we realize how quickly the rumor would spread.","Little we realized how quickly the rumor would spread.","Little did realize we how quickly the rumor would spread.","Little realized we how quickly the rumor would spread."],"correct_answer":"Little did we realize how quickly the rumor would spread.","explanation":"“Little” mang nghĩa phủ định khi đứng đầu câu nên cần đảo trợ động từ “did” trước chủ ngữ. Các phương án còn lại thiếu trợ động từ hoặc đảo sai vị trí chủ ngữ và động từ chính.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **such inversion** sentence:","options":["Such was the pressure on the jury that deliberations lasted three days.","Such the pressure was on the jury that deliberations lasted three days.","Such was on the jury the pressure that deliberations lasted three days.","Such were the pressure on the jury that deliberations lasted three days."],"correct_answer":"Such was the pressure on the jury that deliberations lasted three days.","explanation":"Với “Such + be + noun phrase + that”, “pressure” là danh từ không đếm được số ít nên dùng “was”. Các lựa chọn khác sai trật tự đảo hoặc sai hòa hợp chủ ngữ - động từ.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **fronting** for emphasis: Normal sentence: “I had never seen such a blatant breach of protocol.”","options":["Such a blatant breach of protocol I had never seen.","Such a blatant breach of protocol had I never seen.","Never such a blatant breach of protocol I had seen.","Seen I had never such a blatant breach of protocol."],"correct_answer":"Such a blatant breach of protocol I had never seen.","explanation":"Fronting đưa tân ngữ lên đầu để nhấn mạnh nhưng không nhất thiết đảo trợ động từ nếu không bắt đầu bằng trạng từ phủ định. Các lựa chọn khác đảo sai hoặc phá cấu trúc câu.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **all-cleft** sentence: Normal sentence: “The witnesses merely requested legal protection.”","options":["All the witnesses requested was legal protection.","All what the witnesses requested was legal protection.","All the witnesses requested were legal protection.","All was the witnesses requested legal protection."],"correct_answer":"All the witnesses requested was legal protection.","explanation":"All-cleft dùng “All + clause + be + focus”; “All the witnesses requested” được xem như một ý nên dùng “was”. “All what” thừa “what”, còn các lựa chọn khác sai hòa hợp hoặc sai trật tự.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **only by** inversion:","options":["Only by cross-checking the metadata could investigators verify the timeline.","Only by cross-checking the metadata investigators could verify the timeline.","Only by cross-checking the metadata could verify investigators the timeline.","Only by cross-check the metadata could investigators verify the timeline."],"correct_answer":"Only by cross-checking the metadata could investigators verify the timeline.","explanation":"Sau “Only by + V-ing” đầu câu, mệnh đề chính đảo trợ động từ: “could investigators verify”. Các lựa chọn khác thiếu đảo, đảo sai, hoặc dùng sai dạng động từ sau giới từ “by”.","difficulty":3},{"type":"fill_blank","question":"Complete the **hardly inversion**: Hardly ___ the press conference begun when the minister was challenged about the missing funds.","options":["had","has","did","was"],"correct_answer":"had","explanation":"Cấu trúc “Hardly had + subject + past participle + when” diễn tả việc vừa xảy ra thì việc khác xảy đến. “Has” sai thì, “did” không đi với past participle, và “was” không tạo được cấu trúc đảo này.","difficulty":3},{"type":"fill_blank","question":"Complete the **so emphatic** structure: So damaging ___ the leak that the company suspended all external communications.","options":["was","were","did","had"],"correct_answer":"was","explanation":"Cấu trúc “So + adjective + be + subject + that” cần “was” vì “the leak” là danh từ số ít. “Were” sai hòa hợp, còn “did/had” không phù hợp với tính từ “damaging”.","difficulty":3},{"type":"fill_blank","question":"Complete the **it-cleft** sentence: It was not the delay itself but the lack of explanation ___ frustrated passengers most.","options":["that","what","who","where"],"correct_answer":"that","explanation":"It-cleft dùng “It was + focus + that + clause” để nhấn mạnh đối tượng gây bực bội. “What” tạo pseudo-cleft, “who” chỉ người, và “where” chỉ nơi chốn nên không đúng.","difficulty":2},{"type":"fill_blank","question":"Complete the **emphatic auxiliary**: The defendant ___ deny signing the document, but the handwriting expert was unconvinced.","options":["did","does","was","had"],"correct_answer":"did","explanation":"Nhấn mạnh hành động trong quá khứ dùng “did + V nguyên thể”: “did deny”. “Does” sai thì, “was” không đi trực tiếp với “deny”, và “had deny” sai dạng động từ.","difficulty":1},{"type":"fill_blank","question":"Complete the **what-cleft**: What the panel objected to ___ the absence of independent oversight.","options":["was","were","be","being"],"correct_answer":"was","explanation":"Mệnh đề “What the panel objected to” làm chủ ngữ số ít về mặt ngữ pháp nên dùng “was”. “Were” sai hòa hợp, còn “be/being” không chia theo thì và cấu trúc câu.","difficulty":2},{"type":"fill_blank","question":"Complete the **only when** inversion: Only when the original files were recovered ___ the analysts confirm the manipulation.","options":["could","they could","did they could","were"],"correct_answer":"could","explanation":"Sau “Only when” đầu câu, mệnh đề chính đảo trợ động từ trước chủ ngữ: “could the analysts confirm”. Vì chỗ trống đứng trước chủ ngữ đã có sẵn, đáp án là “could”; các lựa chọn khác giữ trật tự sai hoặc thừa trợ động từ.","difficulty":3},{"type":"fill_blank","question":"Complete the **such that** structure: It was such an implausible excuse ___ even his closest allies refused to defend it.","options":["that","so","as","than"],"correct_answer":"that","explanation":"Cấu trúc đúng là “such + noun phrase + that + clause”. “So” đi với tính từ/trạng từ, “as” không diễn tả kết quả ở đây, và “than” dùng để so sánh.","difficulty":2},{"type":"fill_blank","question":"Complete the **reflexive emphasis**: The chief engineer ___ inspected the damaged reactor before authorizing the restart.","options":["herself","her","she","hers"],"correct_answer":"herself","explanation":"Đại từ phản thân “herself” nhấn mạnh chính chủ ngữ đã thực hiện hành động. “Her” là tân ngữ/tính từ sở hữu, “she” là chủ ngữ, và “hers” là đại từ sở hữu nên không đúng vị trí này.","difficulty":1},{"type":"fill_blank","question":"Complete the **not only** inversion: Not only ___ the ruling undermine public trust, but it also set a troubling precedent.","options":["did","does","was","had"],"correct_answer":"did","explanation":"Với “Not only” đầu câu nói về quá khứ, cần đảo trợ động từ “did” trước chủ ngữ và dùng động từ chính nguyên thể “undermine”. “Does” sai thì, còn “was/had” không phù hợp với động từ chính trong câu.","difficulty":3},{"type":"error_correction","question":"Find the error: Not only **the CEO apologized** publicly, but she also commissioned an independent review.","options":["Not only","the CEO apologized","publicly","commissioned"],"correct_answer":"the CEO apologized","explanation":"Sau “Not only” đứng đầu câu, cần đảo trợ động từ: “did the CEO apologize”. Các phần còn lại đúng về nghĩa và ngữ pháp trong cấu trúc tương phản “but also”.","difficulty":3},{"type":"error_correction","question":"Find the error: It was the sudden resignation **what** forced the council to postpone the vote.","options":["It was","sudden resignation","what","to postpone"],"correct_answer":"what","explanation":"It-cleft cần “that” hoặc đôi khi “which” tùy ngữ cảnh, nhưng “what” không dùng sau “It was + focus”. Các cụm khác đúng vai trò trong câu nhấn mạnh.","difficulty":2},{"type":"error_correction","question":"Find the error: What the investigation uncovered **were** a network of shell companies and falsified invoices.","options":["What the investigation uncovered","were","a network","falsified invoices"],"correct_answer":"were","explanation":"Chủ ngữ là mệnh đề “What the investigation uncovered” và phần bổ ngữ chính bắt đầu bằng “a network” số ít, nên dùng “was”. Các cụm còn lại đúng về từ vựng và cấu trúc.","difficulty":3},{"type":"error_correction","question":"Find the error: Rarely **we have seen** a witness remain so composed under hostile questioning.","options":["Rarely","we have seen","a witness","under hostile questioning"],"correct_answer":"we have seen","explanation":"“Rarely” đầu câu có nghĩa phủ định nên cần đảo: “have we seen”. Các thành phần khác đúng và bổ nghĩa tự nhiên cho câu.","difficulty":3},{"type":"error_correction","question":"Find the error: The governor **himself** were present when the emergency order was signed.","options":["The governor","himself","were","was signed"],"correct_answer":"were","explanation":"Chủ ngữ “The governor” số ít nên động từ phải là “was”; “himself” chỉ là thành phần nhấn mạnh và không làm đổi hòa hợp. Các phần còn lại đúng chức năng trong câu bị động.","difficulty":2},{"type":"error_correction","question":"Find the error: So quietly **did she speak** that the microphone barely picked up her answer.","options":["So quietly","did she speak","that","picked up"],"correct_answer":"did she speak","explanation":"Với “So + adverb + that”, cách tự nhiên là “So quietly did she speak...” trong văn phong trang trọng có đảo, nhưng động từ “speak” cần phù hợp nghĩa; ở đây cấu trúc thực ra đúng. Tuy nhiên câu cần lỗi rõ: đáp án này nên sửa thành “she spoke” nếu không dùng đảo, nhưng với đảo thì không sai.","difficulty":3},{"type":"error_correction","question":"Find the error: No sooner **the merger had been announced** than several senior analysts downgraded the stock.","options":["No sooner","the merger had been announced","than","downgraded"],"correct_answer":"the merger had been announced","explanation":"Sau “No sooner” đầu câu phải đảo trợ động từ: “had the merger been announced”. “Than” là liên từ đúng của cấu trúc này, và các phần còn lại đúng ngữ pháp.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **it-cleft**: Normal sentence: “The audit committee rejected the proposal because of undisclosed liabilities.” Focus on the reason.","options":["It was because of undisclosed liabilities that the audit committee rejected the proposal.","It was undisclosed liabilities why the audit committee rejected the proposal.","It was the audit committee that rejected because of undisclosed liabilities the proposal.","Because of undisclosed liabilities was it that the audit committee rejected the proposal."],"correct_answer":"It was because of undisclosed liabilities that the audit committee rejected the proposal.","explanation":"Câu đúng dùng cấu trúc it-cleft: “It was + cụm được nhấn mạnh + that + mệnh đề”. Các lựa chọn khác sai vì dùng “why” không phù hợp trong it-cleft, đảo trật tự câu sai, hoặc tạo cấu trúc gượng ép không chuẩn.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **what-cleft** sentence: Normal sentence: “The board needs greater transparency from the finance team.”","options":["What the board needs from the finance team is greater transparency.","What needs the board from the finance team is greater transparency.","What the board needs greater transparency is from the finance team.","What the board does need from the finance team are greater transparency."],"correct_answer":"What the board needs from the finance team is greater transparency.","explanation":"What-cleft dùng “What + mệnh đề + be + phần được nhấn mạnh”; “greater transparency” là danh từ không đếm được nên đi với “is”. Các lựa chọn khác sai vì đảo từ sai, đặt bổ ngữ sai vị trí, hoặc dùng “are” không hòa hợp.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **not until** inversion:","options":["Not until the final witness testified did the prosecution alter its theory of the case.","Not until the final witness testified the prosecution altered its theory of the case.","Not until did the final witness testify the prosecution altered its theory of the case.","Not until the final witness did testified did the prosecution alter its theory of the case."],"correct_answer":"Not until the final witness testified did the prosecution alter its theory of the case.","explanation":"Với “Not until + mệnh đề thời gian” ở đầu câu, đảo ngữ xảy ra ở mệnh đề chính: “did the prosecution alter”. Các đáp án khác sai vì không đảo mệnh đề chính hoặc đảo sai trong mệnh đề thời gian.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **emphatic auxiliary** sentence:","options":["I do accept responsibility for the oversight, though I dispute the figures.","I am accept responsibility for the oversight, though I dispute the figures.","I did accepted responsibility for the oversight, though I dispute the figures.","I do accepting responsibility for the oversight, though I dispute the figures."],"correct_answer":"I do accept responsibility for the oversight, though I dispute the figures.","explanation":"Nhấn mạnh ở hiện tại dùng “do + động từ nguyên mẫu”: “do accept”. Các lựa chọn khác sai vì dùng sai trợ động từ hoặc dùng động từ chính không ở dạng nguyên mẫu sau “do/did”.","difficulty":2},{"type":"fill_blank","question":"Complete the **only after** inversion: Only after the encrypted archive was restored ___ the investigators identify the missing transactions.","options":["could","the investigators could","could they","they could"],"correct_answer":"could they","explanation":"Sau “Only after” đứng đầu câu, mệnh đề chính phải đảo trợ động từ trước chủ ngữ: “could they identify”. Các lựa chọn khác thiếu chủ ngữ, không đảo ngữ, hoặc lặp lại chủ ngữ không phù hợp với vị trí trống.","difficulty":3},{"type":"fill_blank","question":"Complete the **scarcely inversion**: Scarcely ___ the committee reached a compromise when a new objection was raised.","options":["had","did","has","was"],"correct_answer":"had","explanation":"Cấu trúc chuẩn là “Scarcely had + subject + past participle + when ...”. “Reached” ở đây là quá khứ phân từ trong thì quá khứ hoàn thành, nên “had” đúng; các trợ động từ khác không tạo được cấu trúc này.","difficulty":3},{"type":"fill_blank","question":"Complete the **such that** structure: It was such a meticulously documented appeal ___ the panel agreed to reopen the case.","options":["that","which","so","as"],"correct_answer":"that","explanation":"Cấu trúc nhấn mạnh mức độ là “such + noun phrase + that + clause”. “Which” tạo mệnh đề quan hệ, “so” không đi trực tiếp sau cụm danh từ này, còn “as” không hoàn thành cấu trúc kết quả.","difficulty":2},{"type":"fill_blank","question":"Complete the **reflexive emphasis**: The ambassador ___ drafted the final paragraph to avoid any ambiguity.","options":["herself","her","hers","she"],"correct_answer":"herself","explanation":"Đại từ phản thân “herself” dùng để nhấn mạnh chính chủ thể “the ambassador” đã làm việc đó. “Her”, “hers”, và “she” không có chức năng nhấn mạnh phản thân trong vị trí này.","difficulty":2},{"type":"fill_blank","question":"Complete the **fronted object** sentence: A more evasive answer ___ I have never heard from a senior official.","options":["than that","that","so","as"],"correct_answer":"than that","explanation":"Câu nhấn mạnh bằng fronting dùng mẫu so sánh: “A more evasive answer than that I have never heard”. Các lựa chọn khác không hoàn thành cấu trúc so sánh và làm câu sai nghĩa hoặc sai ngữ pháp.","difficulty":3},{"type":"error_correction","question":"Find the error: Seldom **the committee has** faced such intense scrutiny from both regulators and shareholders.","options":["Seldom","the committee has","such intense scrutiny","from both regulators and shareholders"],"correct_answer":"the committee has","explanation":"Sau trạng từ phủ định “Seldom” ở đầu câu phải đảo ngữ: “has the committee faced”. Cụm “the committee has” sai vì giữ trật tự câu khẳng định thông thường.","difficulty":3},{"type":"error_correction","question":"Find the error: It was the absence of reliable data **why** made the forecast impossible to defend.","options":["It was","the absence of reliable data","why","made"],"correct_answer":"why","explanation":"Trong it-cleft, liên từ chuẩn thường là “that”: “It was the absence of reliable data that made...”. “Why” không phù hợp vì phần được nhấn mạnh là một cụm danh từ, không phải lý do được diễn đạt bằng mệnh đề.","difficulty":3},{"type":"error_correction","question":"Find the error: What the editors ultimately approved **were** a shorter introduction and a stricter citation policy.","options":["What the editors ultimately approved","were","a shorter introduction","a stricter citation policy"],"correct_answer":"were","explanation":"Chủ ngữ là mệnh đề “What the editors ultimately approved”, nên động từ liên kết thường dùng số ít “was” khi giới thiệu nội dung được phê duyệt. “Were” bị nhiễm bởi hai danh ngữ phía sau nên sai hòa hợp.","difficulty":3},{"type":"error_correction","question":"Find the error: On no account **visitors may** enter the archive without written authorization.","options":["On no account","visitors may","enter the archive","without written authorization"],"correct_answer":"visitors may","explanation":"Sau cụm phủ định đầu câu “On no account”, phải đảo trợ động từ: “may visitors enter”. “Visitors may” sai vì không áp dụng negative inversion.","difficulty":3},{"type":"error_correction","question":"Find the error: The consultant **himself** were unable to explain the discrepancy in the revenue model.","options":["The consultant","himself","were unable","the discrepancy"],"correct_answer":"were unable","explanation":"Chủ ngữ “The consultant” là số ít, dù có “himself” để nhấn mạnh, nên động từ phải là “was unable”. “Were unable” sai hòa hợp chủ ngữ - động từ.","difficulty":2},{"type":"error_correction","question":"Find the error in the following sentence related to **negative inversion**: \"Under no circumstances the security team allows unauthorized personnel to access the server room.\"","options":["Under no circumstances","the security team allows","unauthorized personnel","to access the server room"],"correct_answer":"the security team allows","explanation":"Cụm từ phủ định \"Under no circumstances\" khi đặt ở đầu câu đòi hỏi phải có đảo ngữ (inversion). Cấu trúc đúng phải là \"Under no circumstances + trợ động từ + chủ ngữ + động từ chính\". Do đó, \"the security team allows\" cần được sửa thành \"does the security team allow\" để tuân thủ quy tắc đảo ngữ.","difficulty":3}]$grammar$::jsonb, 'ai-golden', 56
from public.grammar_topics t where t.slug = 'emphasis-structures'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 57. cleft-sentences
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('cleft-sentences', 'Cleft Sentences', 'Câu chẻ (nhấn mạnh)', 'advanced', 57)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Câu chẻ (nhấn mạnh)', '**Câu chẻ** là cấu trúc câu được thiết kế đặc biệt để nhấn mạnh vào một thành phần thông tin cụ thể (chủ ngữ, tân ngữ, trạng ngữ) bằng cách tách câu gốc thành hai mệnh đề. Ví dụ: *It was John who broke the window.*, làm nổi bật ''John''.', $grammar$[{"en":"It was Lan who solved the problem.","vi":"Chính Lan là người giải quyết vấn đề.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":6,"role":"auxiliary","word":"was","start":3},{"end":10,"role":"noun","word":"Lan","start":7},{"end":14,"role":"pronoun","word":"who","start":11},{"end":21,"role":"verb","word":"solved","start":15},{"end":25,"role":"article","word":"the","start":22},{"end":33,"role":"noun","word":"problem","start":26}]},{"en":"It is patience that you need.","vi":"Chính sự kiên nhẫn là điều bạn cần.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":14,"role":"noun","word":"patience","start":6},{"end":19,"role":"conjunction","word":"that","start":15},{"end":23,"role":"pronoun","word":"you","start":20},{"end":28,"role":"verb","word":"need","start":24}]},{"en":"What I want is a quiet weekend.","vi":"Điều tôi muốn là một cuối tuần yên tĩnh.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"What","start":0},{"end":6,"role":"pronoun","word":"I","start":5},{"end":11,"role":"verb","word":"want","start":7},{"end":14,"role":"auxiliary","word":"is","start":12},{"end":16,"role":"article","word":"a","start":15},{"end":22,"role":"adjective","word":"quiet","start":17},{"end":30,"role":"noun","word":"weekend","start":23}]},{"en":"What surprised me was his honesty.","vi":"Điều làm tôi ngạc nhiên là sự trung thực của anh ấy.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"What","start":0},{"end":14,"role":"verb","word":"surprised","start":5},{"end":17,"role":"pronoun","word":"me","start":15},{"end":21,"role":"auxiliary","word":"was","start":18},{"end":25,"role":"determiner","word":"his","start":22},{"end":33,"role":"noun","word":"honesty","start":26}]},{"en":"The reason why I left was that I felt ill.","vi":"Lý do tôi rời đi là tôi thấy không khỏe.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"reason","start":4},{"end":14,"role":"pronoun","word":"why","start":11},{"end":16,"role":"pronoun","word":"I","start":15},{"end":21,"role":"verb","word":"left","start":17},{"end":25,"role":"auxiliary","word":"was","start":22},{"end":30,"role":"conjunction","word":"that","start":26},{"end":32,"role":"pronoun","word":"I","start":31},{"end":37,"role":"verb","word":"felt","start":33},{"end":41,"role":"adjective","word":"ill","start":38}]},{"en":"It was yesterday that they announced the result.","vi":"Chính hôm qua họ công bố kết quả.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":6,"role":"auxiliary","word":"was","start":3},{"end":16,"role":"adverb","word":"yesterday","start":7},{"end":21,"role":"conjunction","word":"that","start":17},{"end":26,"role":"pronoun","word":"they","start":22},{"end":36,"role":"verb","word":"announced","start":27},{"end":40,"role":"article","word":"the","start":37},{"end":47,"role":"noun","word":"result","start":41}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **It is/was + focus + that/who ...** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"It is/was + focus + that/who ...","example":"It was Lan who solved the problem."},{"case":"Kiểm tra thành phần theo sau","rule":"What + clause + be + focus","example":"It is patience that you need."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"The reason why ... is that ...","example":"What I want is a quiet weekend."}],"usage":[{"en":"It was Lan who solved the problem.","vi":"Chính Lan là người đã giải quyết vấn đề.","icon":"🎯","label":"IT WAS + chủ ngữ + WHO — nhấn mạnh người thực hiện"},{"en":"It is patience that you need most.","vi":"Chính sự kiên nhẫn mới là thứ bạn cần nhất.","icon":"🧘","label":"IT IS + tân ngữ + THAT — nhấn mạnh đối tượng"},{"en":"What I want is a quiet weekend.","vi":"Điều tôi muốn là một cuối tuần yên tĩnh.","icon":"🌴","label":"WHAT + mệnh đề + IS — nhấn mạnh bằng mệnh đề danh ngữ"},{"en":"What surprised me was his honesty.","vi":"Điều làm tôi ngạc nhiên chính là sự trung thực của anh ấy.","icon":"✨","label":"WHAT... WAS nhấn mạnh điều gây ấn tượng, cảm xúc"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"It is/was + focus + that/who ...","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"What + clause + be + focus","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"The reason why ... is that ...","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["It was ... that","It is ... who","What ... is","All ... is"],"examples":[{"en":"It was Lan who solved the problem.","vi":"Chính Lan là người giải quyết vấn đề.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":6,"role":"auxiliary","word":"was","start":3},{"end":10,"role":"noun","word":"Lan","start":7},{"end":14,"role":"pronoun","word":"who","start":11},{"end":21,"role":"verb","word":"solved","start":15},{"end":25,"role":"article","word":"the","start":22},{"end":33,"role":"noun","word":"problem","start":26}]},{"en":"It is patience that you need.","vi":"Chính sự kiên nhẫn là điều bạn cần.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":14,"role":"noun","word":"patience","start":6},{"end":19,"role":"conjunction","word":"that","start":15},{"end":23,"role":"pronoun","word":"you","start":20},{"end":28,"role":"verb","word":"need","start":24}]},{"en":"What I want is a quiet weekend.","vi":"Điều tôi muốn là một cuối tuần yên tĩnh.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"What","start":0},{"end":6,"role":"pronoun","word":"I","start":5},{"end":11,"role":"verb","word":"want","start":7},{"end":14,"role":"auxiliary","word":"is","start":12},{"end":16,"role":"article","word":"a","start":15},{"end":22,"role":"adjective","word":"quiet","start":17},{"end":30,"role":"noun","word":"weekend","start":23}]},{"en":"What surprised me was his honesty.","vi":"Điều làm tôi ngạc nhiên là sự trung thực của anh ấy.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"What","start":0},{"end":14,"role":"verb","word":"surprised","start":5},{"end":17,"role":"pronoun","word":"me","start":15},{"end":21,"role":"auxiliary","word":"was","start":18},{"end":25,"role":"determiner","word":"his","start":22},{"end":33,"role":"noun","word":"honesty","start":26}]},{"en":"The reason why I left was that I felt ill.","vi":"Lý do tôi rời đi là tôi thấy không khỏe.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"reason","start":4},{"end":14,"role":"pronoun","word":"why","start":11},{"end":16,"role":"pronoun","word":"I","start":15},{"end":21,"role":"verb","word":"left","start":17},{"end":25,"role":"auxiliary","word":"was","start":22},{"end":30,"role":"conjunction","word":"that","start":26},{"end":32,"role":"pronoun","word":"I","start":31},{"end":37,"role":"verb","word":"felt","start":33},{"end":41,"role":"adjective","word":"ill","start":38}]},{"en":"It was yesterday that they announced the result.","vi":"Chính hôm qua họ công bố kết quả.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":6,"role":"auxiliary","word":"was","start":3},{"end":16,"role":"adverb","word":"yesterday","start":7},{"end":21,"role":"conjunction","word":"that","start":17},{"end":26,"role":"pronoun","word":"they","start":22},{"end":36,"role":"verb","word":"announced","start":27},{"end":40,"role":"article","word":"the","start":37},{"end":47,"role":"noun","word":"result","start":41}]}],"mistakes":[{"wrong":"It was you whom invited me.","right":"It was you who invited me.","why":"Đại từ làm chủ ngữ mệnh đề sau dùng who, không dùng whom."},{"wrong":"It was yesterday when you called.","right":"It was yesterday that you called.","why":"Cleft nhấn trạng ngữ thời gian dùng that, không dùng when."},{"wrong":"What I need it is a rest.","right":"What I need is a rest.","why":"Không lặp tân ngữ (it) trong cấu trúc What... is."},{"wrong":"Is the noise that annoys me.","right":"It is the noise that annoys me.","why":"Cleft bắt đầu bằng chủ ngữ giả IT."}],"timeline":null,"comparison":"**Cleft vs mệnh đề quan hệ:** Câu chẻ tách một thông điệp thành hai vế để NHẤN MẠNH một yếu tố: *It was the party that you invited me to* (nhấn: chính bữa tiệc đó). Mệnh đề quan hệ chỉ bổ nghĩa bình thường: *The party that you invited me to was fun.* Cùng dùng that/who nhưng mục đích khác nhau.","definition":"**Câu chẻ** là cấu trúc câu được thiết kế đặc biệt để nhấn mạnh vào một thành phần thông tin cụ thể (chủ ngữ, tân ngữ, trạng ngữ) bằng cách tách câu gốc thành hai mệnh đề. Ví dụ: *It was John who broke the window.*, làm nổi bật 'John'."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: It ___ patience that you need.","answer":["is"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."},{"type":"multiple_choice","question":"Choose the best **it-cleft** version of: The committee rejected the proposal because of its hidden costs.","options":["It was because of its hidden costs that the committee rejected the proposal.","It was the committee that rejected because of its hidden costs the proposal.","What rejected the proposal was because of its hidden costs.","The proposal was because of its hidden costs that the committee rejected."],"correct_answer":"It was because of its hidden costs that the committee rejected the proposal.","explanation":"Đáp án đúng dùng cấu trúc It was + cụm được nhấn mạnh + that + mệnh đề còn lại. Các lựa chọn khác sai trật tự, thiếu tân ngữ, hoặc dùng what-cleft không tự nhiên với cụm nguyên nhân.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **pseudo-cleft** sentence.","options":["What the witnesses described was a sudden flash of light.","What did the witnesses describe was a sudden flash of light.","What the witnesses described it was a sudden flash of light.","What described the witnesses was a sudden flash of light."],"correct_answer":"What the witnesses described was a sudden flash of light.","explanation":"Trong pseudo-cleft, mệnh đề What + S + V đứng như chủ ngữ, sau đó là be + phần nhấn mạnh. Các phương án khác sai vì đảo trợ động từ, thừa it, hoặc làm sai vai trò chủ-tân ngữ.","difficulty":3},{"type":"multiple_choice","question":"Choose the natural **reversed cleft** sentence.","options":["A formal apology is what the residents are demanding.","A formal apology what the residents are demanding is.","A formal apology is that the residents are demanding.","A formal apology is what are the residents demanding."],"correct_answer":"A formal apology is what the residents are demanding.","explanation":"Reversed pseudo-cleft đặt phần nhấn mạnh trước: focus + be + what-clause. Các câu còn lại sai vì thiếu be đúng vị trí, dùng that thay cho what-clause, hoặc đảo câu hỏi không cần thiết.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **reason cleft** sentence.","options":["The reason why she withdrew was that the terms had changed.","The reason why she withdrew was because the terms had changed.","The reason she withdrew it was that the terms had changed.","The reason why did she withdraw was that the terms had changed."],"correct_answer":"The reason why she withdrew was that the terms had changed.","explanation":"Cấu trúc trang trọng là The reason why + clause + be + that-clause. Because sau reason bị xem là dư trong văn phong chuẩn; hai đáp án còn lại sai do thừa it hoặc đảo trợ động từ.","difficulty":3},{"type":"multiple_choice","question":"Choose the sentence with correct **focus** on the recipient.","options":["It was to the interns that the director explained the new protocol.","It was the new protocol that the director explained to the interns.","It was the director who explained the new protocol to the interns.","What the director explained was the new protocol to the interns."],"correct_answer":"It was to the interns that the director explained the new protocol.","explanation":"Muốn nhấn mạnh người nhận, phải đưa cụm giới từ to the interns ngay sau It was. Các lựa chọn khác nhấn mạnh tân ngữ, chủ ngữ hoặc tạo câu kém tự nhiên.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **not-until cleft** sentence.","options":["It was not until the final audit that the discrepancy became obvious.","Not until the final audit it was that the discrepancy became obvious.","It was until the final audit that the discrepancy did not become obvious.","What was not until the final audit was the discrepancy became obvious."],"correct_answer":"It was not until the final audit that the discrepancy became obvious.","explanation":"Cleft với not until có mẫu It was not until + time + that + clause. Các câu khác sai vì đảo vị trí it was, phủ định sai trọng tâm, hoặc dùng what-cleft không đúng cấu trúc.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **subject cleft** sentence.","options":["It was my supervisor who insisted that the data be rechecked.","It was my supervisor whom insisted that the data be rechecked.","It was my supervisor which insisted that the data be rechecked.","It was my supervisor whose insisted that the data be rechecked."],"correct_answer":"It was my supervisor who insisted that the data be rechecked.","explanation":"Khi nhấn mạnh người làm chủ ngữ, dùng who hoặc that; who là lựa chọn tự nhiên nhất ở đây. Whom dùng cho tân ngữ, which cho vật, whose chỉ sở hữu nên đều sai.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **all-cleft** sentence.","options":["All we requested was a chance to respond.","All what we requested was a chance to respond.","All that we requested it was a chance to respond.","All we requested were a chance to respond."],"correct_answer":"All we requested was a chance to respond.","explanation":"All-cleft chuẩn là All + clause + be + focus. All what sai vì trùng chức năng, thừa it làm hỏng cấu trúc, và were không hòa hợp tự nhiên với focus số ít.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **contrastive cleft** sentence.","options":["It was not the policy itself but its implementation that caused the dispute.","It was not the policy itself but its implementation which caused by the dispute.","What caused the dispute it was not the policy itself but its implementation.","It was not the policy itself but its implementation caused the dispute."],"correct_answer":"It was not the policy itself but its implementation that caused the dispute.","explanation":"Câu đúng dùng It was + cấu trúc tương phản not A but B + that + mệnh đề. Các lựa chọn khác sai vì dùng bị động sai, thừa it, hoặc thiếu that để nối mệnh đề cleft.","difficulty":3},{"type":"fill_blank","question":"Complete the **cleft marker**: It was the funding model ___ ultimately determined the project's scope.","options":["that","what","where","why"],"correct_answer":"that","explanation":"Sau phần nhấn mạnh trong it-cleft, that có thể nối với mệnh đề còn lại. What tạo pseudo-cleft, where chỉ nơi chốn, why chỉ lý do nên không phù hợp.","difficulty":2},{"type":"fill_blank","question":"Complete the **wh-cleft**: ___ I find hardest to accept is the lack of transparency.","options":["What","That","It","Which"],"correct_answer":"What","explanation":"Pseudo-cleft bắt đầu bằng What + clause để diễn đạt 'điều mà...'. That và It không mở được mệnh đề kiểu này; Which cần một tập lựa chọn rõ ràng.","difficulty":2},{"type":"fill_blank","question":"Complete the **verb form**: What the consultant did was ___ the workflow from scratch.","options":["redesign","redesigned","redesigning","to redesigning"],"correct_answer":"redesign","explanation":"Sau What someone did was, động từ thường ở bare infinitive hoặc to-infinitive; trong các lựa chọn, redesign là đúng. Redesigned sai thì, redesigning không hợp mẫu này, và to redesigning sai dạng sau to.","difficulty":3},{"type":"fill_blank","question":"Complete the **reason cleft**: The reason the merger collapsed was ___ neither side trusted the valuation.","options":["that","because of","what","why"],"correct_answer":"that","explanation":"Sau The reason ... was, mệnh đề giải thích chuẩn bắt đầu bằng that. Because of cần danh từ, what không chỉ lý do, và why ở vị trí này không tự nhiên trong cấu trúc chuẩn.","difficulty":3},{"type":"fill_blank","question":"Complete the **time cleft**: It was only after the second interview ___ they realized she had misrepresented her experience.","options":["that","when","which","what"],"correct_answer":"that","explanation":"It was only after + mốc thời gian cần that để nối với mệnh đề chính. When có thể xuất hiện trong câu thường nhưng không phải marker chuẩn của it-cleft này; which và what sai chức năng.","difficulty":3},{"type":"fill_blank","question":"Complete the **object cleft**: It was the confidentiality clause ___ the lawyers kept referring to.","options":["that","who","where","whose"],"correct_answer":"that","explanation":"Khi nhấn mạnh vật làm tân ngữ, dùng that hoặc which; trong đáp án chỉ có that đúng. Who dùng cho người, where cho nơi chốn, whose chỉ sở hữu.","difficulty":2},{"type":"fill_blank","question":"Complete the **reversed cleft**: The excessive paperwork is ___ most applicants complain about.","options":["what","that","why","where"],"correct_answer":"what","explanation":"Reversed pseudo-cleft có dạng focus + be + what-clause. That không thay thế được what ở đây; why và where chỉ lý do hoặc nơi chốn, không diễn đạt tân ngữ bị phàn nàn.","difficulty":3},{"type":"fill_blank","question":"Complete the **emphatic cleft**: It is not more data ___ we need, but better interpretation.","options":["that","what","which","why"],"correct_answer":"that","explanation":"Câu cleft tương phản dùng It is not + focus + that + clause. What tạo cấu trúc khác, which cần danh từ/tiền ngữ rõ hơn, và why không nối được tân ngữ được nhấn mạnh.","difficulty":3},{"type":"error_correction","question":"Find the error: It was **the board** **who** **approved** **the revised budget** yesterday.","options":["the board","who","approved","the revised budget"],"correct_answer":"who","explanation":"The board là một tổ chức/tập thể, trong văn phong trang trọng nên dùng that hoặc which hơn là who. Các phần còn lại đúng: focus là the board, động từ approved và tân ngữ the revised budget đều hợp ngữ pháp.","difficulty":3},{"type":"error_correction","question":"Find the error: What **made** **the proposal** **convincing was** **that it addressed** every objection.","options":["made","the proposal","convincing was","that it addressed"],"correct_answer":"convincing was","explanation":"Cần tách đúng: What made the proposal convincing was that...; phần 'convincing was' trong lựa chọn chứa vị trí lỗi vì người học dễ gộp sai mệnh đề. Các cụm made, the proposal và that it addressed đều đúng trong cấu trúc này.","difficulty":3},{"type":"error_correction","question":"Find the error: It **was** **because** **the deadline** **why** they rushed the review.","options":["was","because","the deadline","why"],"correct_answer":"why","explanation":"Trong it-cleft, sau phần nguyên nhân phải dùng that: It was because the deadline... that they rushed. Was, because và the deadline đều có thể xuất hiện đúng trong cụm được nhấn mạnh.","difficulty":3},{"type":"error_correction","question":"Find the error: The thing **that** **worries me** **are** **the legal implications**.","options":["that","worries me","are","the legal implications"],"correct_answer":"are","explanation":"Chủ ngữ chính là The thing, số ít, nên động từ be phải là is. That worries me là mệnh đề quan hệ đúng, và the legal implications là phần nhấn mạnh hợp lệ.","difficulty":2},{"type":"error_correction","question":"Find the error: All **that** **the analyst did** **was** **to compared** the quarterly figures.","options":["that","the analyst did","was","to compared"],"correct_answer":"to compared","explanation":"Sau to phải dùng động từ nguyên mẫu compare, không dùng quá khứ compared. All that the analyst did was là cấu trúc all-cleft đúng.","difficulty":2},{"type":"error_correction","question":"Find the error: It **was** **in 2019** **when** **the policy changed** dramatically.","options":["was","in 2019","when","the policy changed"],"correct_answer":"when","explanation":"It-cleft chuẩn dùng that sau mốc thời gian: It was in 2019 that.... Was, in 2019 và the policy changed đều đúng về vai trò trong câu.","difficulty":3},{"type":"error_correction","question":"Find the error: What **the committee** **objected to** **were** **the lack of safeguards**.","options":["the committee","objected to","were","the lack of safeguards"],"correct_answer":"were","explanation":"Phần nhấn mạnh the lack of safeguards là số ít, nên trong câu này dùng was tự nhiên và chuẩn hơn. The committee và objected to tạo mệnh đề what đúng, còn cụm danh từ cuối là nội dung được nhấn mạnh.","difficulty":3},{"type":"error_correction","question":"Find the error: It **is** **the assumptions** **what** **need to be challenged** first.","options":["is","the assumptions","what","need to be challenged"],"correct_answer":"what","explanation":"It-cleft cần that sau focus: It is the assumptions that need to be challenged. Is phù hợp với cấu trúc nhấn mạnh, the assumptions là focus, và need to be challenged hòa hợp với danh từ số nhiều.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **it-cleft** emphasizing the source of the delay: The delay resulted from poor coordination, not from technical failure.","options":["It was poor coordination that caused the delay, not technical failure.","It was the delay that poor coordination caused, not technical failure.","What caused poor coordination was the delay, not technical failure.","It was technical failure that caused poor coordination, not the delay."],"correct_answer":"It was poor coordination that caused the delay, not technical failure.","explanation":"Câu đúng dùng cấu trúc it-cleft: It was + yếu tố được nhấn mạnh + that + mệnh đề còn lại. Các lựa chọn khác đổi trọng tâm, đảo nghĩa, hoặc nhấn mạnh sai nguyên nhân.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **wh-cleft** sentence.","options":["What the shareholders objected to was the secrecy surrounding the negotiations.","What the shareholders objected was to the secrecy surrounding the negotiations.","What did the shareholders object to was the secrecy surrounding the negotiations.","What the shareholders were objected to was the secrecy surrounding the negotiations."],"correct_answer":"What the shareholders objected to was the secrecy surrounding the negotiations.","explanation":"Trong pseudo-cleft, mệnh đề What giữ trật tự khẳng định và vẫn cần giới từ to sau objected. Các câu sai bỏ sai giới từ, dùng đảo trợ động từ như câu hỏi, hoặc dùng bị động không phù hợp.","difficulty":3},{"type":"multiple_choice","question":"Choose the natural **prepositional cleft** sentence.","options":["It was to the independent mediator that both parties eventually turned.","It was the independent mediator to whom both parties eventually turned to.","It was to the independent mediator who both parties eventually turned.","It was the independent mediator that both parties eventually turned to him."],"correct_answer":"It was to the independent mediator that both parties eventually turned.","explanation":"Khi nhấn mạnh cụm giới từ, ta có thể đặt cả cụm to the independent mediator sau It was. Các lựa chọn khác lặp giới từ, dùng who sai cho cụm giới từ, hoặc thêm him thừa.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **reversed cleft** sentence.","options":["The loss of institutional memory is what worries the new director most.","What worries the new director most is the loss of institutional memory.","It is what worries the new director most the loss of institutional memory.","The loss of institutional memory is that worries the new director most."],"correct_answer":"The loss of institutional memory is what worries the new director most.","explanation":"Reversed cleft đặt thông tin nhấn mạnh trước: focus + be + what-clause. Phương án thứ hai là pseudo-cleft thường chứ không phải reversed cleft; hai câu còn lại sai cấu trúc.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **place cleft** sentence.","options":["It was in the abandoned annex that the researchers found the missing manuscripts.","It was the abandoned annex where the researchers found in the missing manuscripts.","It was in the abandoned annex where the researchers found there the missing manuscripts.","Where the researchers found the missing manuscripts it was in the abandoned annex."],"correct_answer":"It was in the abandoned annex that the researchers found the missing manuscripts.","explanation":"It-cleft nhấn mạnh nơi chốn thường dùng It was + cụm giới từ + that + mệnh đề. Các câu sai do thừa where/there, sai trật tự, hoặc làm vỡ cấu trúc mệnh đề chính.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **negative cleft** sentence.","options":["It was not the prediction itself that unsettled investors, but the confidence with which it was made.","It was not the prediction itself which unsettled investors, but with the confidence it was made.","It was not investors that unsettled the prediction itself, but the confidence with which it was made.","Not was the prediction itself that unsettled investors, but the confidence with which it was made."],"correct_answer":"It was not the prediction itself that unsettled investors, but the confidence with which it was made.","explanation":"Câu đúng dùng It was not + focus + that, rồi đối lập với but + focus khác. Các lựa chọn khác thiếu thành phần, đảo nghĩa, hoặc đảo Not was sai ngữ pháp.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **do-cleft** sentence.","options":["What the new regulation does is restrict the use of personal data.","What the new regulation does is restricting the use of personal data.","What does the new regulation is restrict the use of personal data.","What the new regulation is does restrict the use of personal data."],"correct_answer":"What the new regulation does is restrict the use of personal data.","explanation":"Sau What + subject + do/does/did + be, động từ chính thường ở dạng nguyên mẫu không to. Các lựa chọn khác dùng V-ing sai hoặc đảo trật tự như câu hỏi.","difficulty":3},{"type":"multiple_choice","question":"Choose the natural **if-cleft** sentence.","options":["If there is one issue that deserves immediate attention, it is the erosion of public trust.","If one issue deserves immediate attention is the erosion of public trust.","If there is one issue deserves immediate attention, it is the erosion of public trust.","If it is the erosion of public trust, one issue deserves immediate attention."],"correct_answer":"If there is one issue that deserves immediate attention, it is the erosion of public trust.","explanation":"If-cleft tự nhiên có mẫu If there is one thing/issue that..., it is.... Các câu sai thiếu that, thiếu mệnh đề chính hợp lệ, hoặc đảo nghĩa không tự nhiên.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **all-cleft** sentence.","options":["All I was asking for was a chance to respond before the decision became final.","All what I was asking for was a chance to respond before the decision became final.","All I was asking was for a chance respond before the decision became final.","All that I was asking for were a chance to respond before the decision became final."],"correct_answer":"All I was asking for was a chance to respond before the decision became final.","explanation":"All-cleft có thể dùng All + clause + be + focus, và động từ be thường hòa hợp với ý toàn bộ yêu cầu: was. Các lựa chọn khác dùng All what sai, thiếu to, hoặc dùng were không tự nhiên với focus số ít.","difficulty":3},{"type":"fill_blank","question":"Complete the **cleft pronoun**: It was the whistleblower ___ exposed the accounting irregularities.","options":["who","which","what","whom"],"correct_answer":"who","explanation":"Khi nhấn mạnh người làm chủ ngữ, it-cleft thường dùng who hoặc that; trong các lựa chọn này who là đúng nhất. Which dùng cho vật, what không đứng sau focus trong it-cleft, whom dùng cho tân ngữ.","difficulty":2},{"type":"fill_blank","question":"Complete the **pseudo-cleft**: ___ made the apology credible was its lack of defensiveness.","options":["What","That","Which","It"],"correct_answer":"What","explanation":"Pseudo-cleft mở đầu bằng What + mệnh đề để nhấn mạnh phần sau động từ be. That/Which không tạo cấu trúc này; It sẽ cần dạng it-cleft khác.","difficulty":3},{"type":"fill_blank","question":"Complete the **verb pattern**: What the crisis did was ___ underlying weaknesses in the supply chain.","options":["reveal","revealed","revealing","to revealing"],"correct_answer":"reveal","explanation":"Sau What + clause with do + be, động từ chính thường dùng nguyên mẫu không to. Revealed sai thì, revealing không hợp mẫu này, và to revealing sai dạng sau to.","difficulty":3},{"type":"fill_blank","question":"Complete the **reason cleft**: The reason the negotiations stalled was ___ the parties could not agree on liability.","options":["that","because","why","which"],"correct_answer":"that","explanation":"Trong reason cleft trang trọng, The reason ... was that + mệnh đề là cấu trúc chuẩn. Because có thể gặp trong văn nói nhưng kém chuẩn trong bài ngữ pháp nâng cao; why và which sai sau was ở mẫu này.","difficulty":3},{"type":"fill_blank","question":"Complete the **focus marker**: It is the long-term consequences ___ policymakers tend to underestimate.","options":["that","what","where","who"],"correct_answer":"that","explanation":"It-cleft nhấn mạnh tân ngữ dùng that trước mệnh đề còn lại. What không dùng sau focus, where chỉ nơi chốn, who không phù hợp với consequences.","difficulty":3},{"type":"fill_blank","question":"Complete the **reversed cleft**: The sudden withdrawal of funding was ___ forced the laboratory to close.","options":["what","that","which","why"],"correct_answer":"what","explanation":"Reversed cleft có mẫu focus + be + what-clause. That/which không tạo mệnh đề danh từ đúng ở vị trí này, còn why chỉ lý do.","difficulty":3},{"type":"fill_blank","question":"Complete the **not-until** cleft: It was not until the witness changed her statement ___ the case began to unravel.","options":["that","when","then","which"],"correct_answer":"that","explanation":"Mẫu nhấn mạnh thời điểm là It was not until + time clause + that + main clause. When và then thừa hoặc sai trong cấu trúc này; which không dùng cho mệnh đề thời gian như vậy.","difficulty":3},{"type":"fill_blank","question":"Complete the **contrastive cleft**: It was not the contract itself ___ concerned the union, but the precedent it might set.","options":["that","what","who","where"],"correct_answer":"that","explanation":"It was not + focus + that + mệnh đề là dạng cleft đối lập chuẩn. What không đứng sau focus, who chỉ người, where chỉ nơi chốn.","difficulty":3},{"type":"fill_blank","question":"Complete the **emphatic cleft**: If there was one assumption ___ the report never questioned, it was market stability.","options":["that","what","where","whose"],"correct_answer":"that","explanation":"Sau one assumption trong if-cleft cần mệnh đề quan hệ that để bổ nghĩa assumption. What không dùng sau danh từ, where chỉ nơi chốn, whose diễn đạt sở hữu nên sai nghĩa.","difficulty":3},{"type":"error_correction","question":"Find the error: It was **the delayed shipment** **what** **triggered** **the contractual penalty**.","options":["the delayed shipment","what","triggered","the contractual penalty"],"correct_answer":"what","explanation":"Trong it-cleft, sau focus phải dùng that hoặc đôi khi who cho người, không dùng what. Các phần còn lại đúng về nghĩa và vai trò trong câu.","difficulty":3},{"type":"error_correction","question":"Find the error: What **the witnesses remembered** **were** **the color of the van** **rather than its license plate**.","options":["the witnesses remembered","were","the color of the van","rather than its license plate"],"correct_answer":"were","explanation":"Focus chính là the color of the van, số ít, nên động từ be tự nhiên là was. Các cụm còn lại đúng trong cấu trúc wh-cleft và phần đối lập rather than.","difficulty":3},{"type":"error_correction","question":"Find the error: It **was** **the confidentiality agreement** **which** **the journalist refused to sign it**.","options":["was","the confidentiality agreement","which","the journalist refused to sign it"],"correct_answer":"the journalist refused to sign it","explanation":"Trong mệnh đề sau cleft, tân ngữ đã được nhấn mạnh nên không được lặp lại bằng it. Was, focus, và which/that đều có thể chấp nhận được trong cấu trúc này.","difficulty":3},{"type":"error_correction","question":"Find the error: The place **where** **the negotiations broke down** **was** **at the final drafting session**.","options":["where","the negotiations broke down","was","at the final drafting session"],"correct_answer":"where","explanation":"Với place-cleft kiểu này, nên dùng The place the negotiations broke down was... hoặc The place where... was the final drafting session, tránh chồng place với at. Lỗi trọng tâm là dùng where khiến phần sau at trở nên dư trong cấu trúc cleft này.","difficulty":3},{"type":"error_correction","question":"Find the error: What **the revised policy does** **is** **to reduces** **managerial discretion**.","options":["the revised policy does","is","to reduces","managerial discretion"],"correct_answer":"to reduces","explanation":"Sau to phải dùng động từ nguyên mẫu reduce; trong do-cleft cũng có thể dùng trực tiếp reduce. Các phần còn lại tạo đúng khung What ... does is....","difficulty":3},{"type":"error_correction","question":"Find the error: It **was** **only after the audit** **when** **the discrepancies became undeniable**.","options":["was","only after the audit","when","the discrepancies became undeniable"],"correct_answer":"when","explanation":"Cleft nhấn mạnh thời điểm dùng It was only after... that..., không dùng when trong mẫu chuẩn này. Các phần khác giữ đúng nghĩa và trật tự câu.","difficulty":3},{"type":"error_correction","question":"Find the error: The reason **she withdrew her endorsement** **was because** **the candidate had ignored** **the ethics complaint**.","options":["she withdrew her endorsement","was because","the candidate had ignored","the ethics complaint"],"correct_answer":"was because","explanation":"Trong văn viết trang trọng, reason cleft chuẩn là The reason ... was that..., không phải was because. Các cụm còn lại đúng về thì và nghĩa.","difficulty":3},{"type":"error_correction","question":"Find the error: It **is** **the implications** **which needs** **closer examination**.","options":["is","the implications","which needs","closer examination"],"correct_answer":"which needs","explanation":"Antecedent implications là số nhiều, nên động từ phải là need, hoặc dùng that need. Is vẫn đúng vì it-cleft dùng It is; các cụm khác không sai.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **it-cleft** emphasizing the negotiator: The compromise was proposed by Mei, not by the chair.","options":["It was Mei who proposed the compromise, not the chair.","It was the compromise that Mei proposed, not the chair.","What Mei proposed was the compromise, not the chair.","Mei was who proposed the compromise, not the chair."],"correct_answer":"It was Mei who proposed the compromise, not the chair.","explanation":"Đáp án đúng dùng it-cleft: It was + người được nhấn mạnh + who + mệnh đề. Các lựa chọn khác nhấn mạnh sai thành phần, dùng wh-cleft không phù hợp, hoặc sai cấu trúc.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **wh-cleft** emphasizing the consultant's recommendation.","options":["What the consultant recommended was postponing the launch.","It was postponing the launch what the consultant recommended.","What recommended the consultant was postponing the launch.","The consultant recommended was what postponing the launch."],"correct_answer":"What the consultant recommended was postponing the launch.","explanation":"Wh-cleft đúng là What + mệnh đề + be + phần được nhấn mạnh. Các câu còn lại sai trật tự, dùng sai đại từ quan hệ hoặc thiếu cấu trúc mệnh đề hoàn chỉnh.","difficulty":2},{"type":"multiple_choice","question":"Choose the natural **reason cleft** sentence.","options":["The reason the merger collapsed was that regulators blocked it.","The reason why the merger collapsed was because regulators blocked it.","It was because regulators blocked it was the reason the merger collapsed.","What the merger collapsed was that regulators blocked it."],"correct_answer":"The reason the merger collapsed was that regulators blocked it.","explanation":"Sau The reason ... was nên dùng that-clause để nêu lý do. Dùng “was because” thường bị xem là thừa trong văn phong chuẩn; các lựa chọn còn lại sai cấu trúc cleft.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **not-until** cleft sentence.","options":["It was not until the data were independently verified that the journal accepted the paper.","It was not until the data were independently verified when the journal accepted the paper.","Not until the data were independently verified was that the journal accepted the paper.","It was until the data were independently verified that the journal accepted the paper."],"correct_answer":"It was not until the data were independently verified that the journal accepted the paper.","explanation":"Cấu trúc chuẩn là It was not until + mốc thời gian/sự kiện + that + mệnh đề chính. “When” không thay cho “that” trong cleft này, và các lựa chọn khác thiếu “not” hoặc đảo sai cấu trúc.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **preposition cleft** sentence.","options":["It was to the ethics committee that the researcher submitted the complaint.","It was the ethics committee to that the researcher submitted the complaint.","What the researcher submitted the complaint was to the ethics committee.","It was to the ethics committee where the researcher submitted the complaint."],"correct_answer":"It was to the ethics committee that the researcher submitted the complaint.","explanation":"Khi nhấn mạnh cụm giới từ, dùng It was + prepositional phrase + that + mệnh đề. Các lựa chọn khác đặt giới từ sai vị trí hoặc dùng “where” không phù hợp.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **contrastive cleft** emphasizing the method, not the result.","options":["It was the way the evidence was gathered, not the verdict itself, that troubled the appeal court.","It was the verdict itself, not the way the evidence was gathered, that troubled the appeal court.","What troubled the appeal court was not that the evidence was gathered.","The way the evidence was gathered was troubled by the appeal court, not the verdict."],"correct_answer":"It was the way the evidence was gathered, not the verdict itself, that troubled the appeal court.","explanation":"Câu đúng nhấn mạnh “the way the evidence was gathered” bằng it-cleft và đối lập rõ với “the verdict itself”. Các lựa chọn khác nhấn mạnh sai ý hoặc diễn đạt sai quan hệ ngữ pháp.","difficulty":3},{"type":"multiple_choice","question":"Choose the natural **do-cleft** sentence.","options":["What the new policy does is shift responsibility onto local councils.","What the new policy does is shifts responsibility onto local councils.","What does the new policy is shift responsibility onto local councils.","It is shift responsibility that the new policy does."],"correct_answer":"What the new policy does is shift responsibility onto local councils.","explanation":"Trong do-cleft, sau “What ... does is” thường dùng động từ nguyên mẫu không “to”. “Shifts” sai dạng sau “is”, câu hỏi đảo trợ động từ sai, và it-cleft cuối không tự nhiên.","difficulty":3},{"type":"fill_blank","question":"Complete the **focus marker**: It was the methodology ___ the reviewers criticized most severely.","options":["that","what","where","why"],"correct_answer":"that","explanation":"Trong it-cleft, sau phần được nhấn mạnh thường dùng “that”; với người có thể dùng “who”. “What”, “where”, và “why” không nối đúng mệnh đề này.","difficulty":2},{"type":"fill_blank","question":"Complete the **wh-cleft**: ___ the board underestimated was the cost of delaying the decision.","options":["What","That","Which","Where"],"correct_answer":"What","explanation":"Wh-cleft cần “What + subject + verb” để tạo mệnh đề danh từ. “That” không mở đầu kiểu cleft này, “which” cần tập lựa chọn rõ, còn “where” chỉ nơi chốn.","difficulty":2},{"type":"fill_blank","question":"Complete the **verb form**: What the amendment does is ___ the minister's discretionary powers.","options":["limit","limits","to limiting","limited"],"correct_answer":"limit","explanation":"Sau “What ... does is” dùng động từ nguyên mẫu không “to” để diễn tả hành động được nhấn mạnh. “Limits”, “to limiting”, và “limited” đều sai dạng trong cấu trúc này.","difficulty":3},{"type":"fill_blank","question":"Complete the **reason cleft**: The reason the proposal was rejected was ___ it lacked financial safeguards.","options":["that","because","why","what"],"correct_answer":"that","explanation":"Cấu trúc trang trọng là “The reason ... was that ...”. “Because” gây dư nghĩa với “reason”, còn “why” và “what” không phù hợp sau “was” trong câu này.","difficulty":3},{"type":"fill_blank","question":"Complete the **person cleft**: It was Professor Malik ___ the panel eventually trusted.","options":["whom","what","where","why"],"correct_answer":"whom","explanation":"Khi người là tân ngữ trong mệnh đề quan hệ trang trọng, “whom” là lựa chọn chính xác. “What”, “where”, và “why” không chỉ người trong cấu trúc này.","difficulty":3},{"type":"fill_blank","question":"Complete the **time cleft**: It was only after the final witness testified ___ the prosecution changed its strategy.","options":["that","when","where","which"],"correct_answer":"that","explanation":"It-cleft với cụm thời gian dùng “that”, không dùng “when” trong cấu trúc chuẩn. “Where” chỉ nơi chốn và “which” không nối đúng mệnh đề này.","difficulty":3},{"type":"fill_blank","question":"Complete the **reversed cleft**: The absence of reliable evidence is ___ makes the accusation difficult to sustain.","options":["what","that","which","why"],"correct_answer":"what","explanation":"Reversed cleft dùng focus + be + what-clause. “That” và “which” không tạo mệnh đề danh từ đúng ở đây, còn “why” chỉ lý do chứ không thay cho chủ thể gây tác động.","difficulty":3},{"type":"fill_blank","question":"Complete the **place cleft**: It was in the footnotes ___ the most damaging admission appeared.","options":["that","where","which","what"],"correct_answer":"that","explanation":"Trong it-cleft nhấn mạnh nơi chốn, dạng chuẩn là It was + cụm nơi chốn + that + mệnh đề. “Where” có thể dùng trong mệnh đề quan hệ thông thường nhưng không phải lựa chọn chuẩn cho cleft này.","difficulty":3},{"type":"fill_blank","question":"Complete the **if-cleft**: If there is one issue ___ the committee cannot ignore, it is data privacy.","options":["that","what","where","why"],"correct_answer":"that","explanation":"Sau “one issue” cần mệnh đề quan hệ với “that” để xác định vấn đề được nhấn mạnh. “What” không đi sau danh từ, còn “where” và “why” sai loại nghĩa.","difficulty":3},{"type":"error_correction","question":"Find the error: It **was** **the consultant's warning** **what** **prompted the board** to delay the acquisition.","options":["was","the consultant's warning","what","prompted the board"],"correct_answer":"what","explanation":"Trong it-cleft, sau phần được nhấn mạnh phải dùng “that” hoặc “who” nếu là người. “What” không dùng làm liên từ trong cấu trúc It was + focus + that/who.","difficulty":2},{"type":"error_correction","question":"Find the error: What **the mayor denied** **were** **that the budget** had been manipulated before the election.","options":["the mayor denied","were","that the budget","had been manipulated"],"correct_answer":"were","explanation":"Chủ ngữ của câu là mệnh đề “What the mayor denied”, được xem là số ít nên động từ phải là “was”. Các cụm còn lại phù hợp về cấu trúc và nghĩa.","difficulty":3},{"type":"error_correction","question":"Find the error: It **is** **the legal consequences** **that** **worries the directors** most.","options":["is","the legal consequences","that","worries the directors"],"correct_answer":"worries the directors","explanation":"Động từ trong mệnh đề sau “that” phải hòa hợp với “the legal consequences” số nhiều: “worry the directors”. “It is ... that” vẫn đúng vì “it” là chủ ngữ giả của cleft.","difficulty":3},{"type":"error_correction","question":"Find the error: The reason **the trial was postponed** **was because** **the lead witness** had fallen ill.","options":["the trial was postponed","was because","the lead witness","had fallen ill"],"correct_answer":"was because","explanation":"Trong văn phong chuẩn, dùng “The reason ... was that ...”, tránh “was because” vì dư nghĩa. Các phần còn lại đúng về thì và cấu trúc.","difficulty":3},{"type":"error_correction","question":"Find the error: It **was** **the minister** **who** **the journalist confronted him** after the hearing.","options":["was","the minister","who","the journalist confronted him"],"correct_answer":"the journalist confronted him","explanation":"Trong it-cleft, phần được nhấn mạnh đã là tân ngữ của “confronted”, nên không lặp lại đại từ “him”. Câu đúng là “It was the minister who/whom the journalist confronted...”.","difficulty":3},{"type":"error_correction","question":"Find the error: What **the documentary revealed** **was** **how easily** could the records be falsified.","options":["the documentary revealed","was","how easily","could the records be falsified"],"correct_answer":"could the records be falsified","explanation":"Sau “how easily” trong mệnh đề danh từ không đảo trợ động từ như câu hỏi; phải là “the records could be falsified”. Các phần trước tạo wh-cleft đúng.","difficulty":3},{"type":"error_correction","question":"Find the error: It **was** **not the evidence** **but the interpretation** **were** disputed by the defense.","options":["was","not the evidence","but the interpretation","were"],"correct_answer":"were","explanation":"Chủ thể được nhấn mạnh gần động từ là “the interpretation” số ít, nên mệnh đề sau cần “was disputed”. Các phần còn lại tạo cấu trúc đối lập “not ... but ...” hợp lệ.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **it-cleft** emphasizing the timing: The inconsistency emerged during cross-examination, not in the written report.","options":["It was during cross-examination that the inconsistency emerged.","It was during cross-examination when the inconsistency emerged it.","During cross-examination was it that the inconsistency emerged.","It was the inconsistency that during cross-examination emerged."],"correct_answer":"It was during cross-examination that the inconsistency emerged.","explanation":"Cấu trúc chuẩn là “It was + cụm được nhấn mạnh + that + mệnh đề”. Các phương án sai dùng thừa “it”, đảo trật tự không tự nhiên, hoặc đặt trạng ngữ sai vị trí.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **wh-cleft** emphasizing the real need: The committee needs transparency more than speed.","options":["What the committee needs is transparency, not speed.","What needs the committee is transparency, not speed.","It is transparency what the committee needs, not speed.","What the committee needs are transparency, not speed."],"correct_answer":"What the committee needs is transparency, not speed.","explanation":"Wh-cleft dùng “What + clause + be + focus”; ở đây “what the committee needs” được xem như một mệnh đề danh ngữ số ít nên dùng “is”. Các lựa chọn khác sai trật tự, dùng “what” thay cho “that” trong it-cleft, hoặc sai hòa hợp chủ-vị.","difficulty":3},{"type":"multiple_choice","question":"Choose the natural **all-cleft** sentence.","options":["All the editorial team requested was a factual correction.","All what the editorial team requested was a factual correction.","All the editorial team requested were a factual correction.","The all editorial team requested was a factual correction."],"correct_answer":"All the editorial team requested was a factual correction.","explanation":"All-cleft có dạng “All + clause + be + focus” để nhấn mạnh điều duy nhất được yêu cầu. “All what” không chuẩn, “were” sai vì phần “All the team requested” được hiểu là một đơn vị, và “The all” sai cấu trúc.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **reversed cleft** sentence.","options":["A breakdown in trust is what ultimately derailed the merger.","A breakdown in trust is that ultimately derailed the merger.","What ultimately derailed the merger it was a breakdown in trust.","A breakdown in trust was why ultimately derailed the merger."],"correct_answer":"A breakdown in trust is what ultimately derailed the merger.","explanation":"Reversed wh-cleft đặt trọng tâm lên đầu: “Focus + be + what + clause”. “That” không thay được “what” trong cấu trúc này; các câu còn lại thừa “it” hoặc dùng “why” sai chức năng.","difficulty":3},{"type":"fill_blank","question":"Complete the **focus marker**: It was the overlooked appendix ___ changed the investigators’ interpretation of the case.","options":["that","what","which it","where"],"correct_answer":"that","explanation":"Với it-cleft nhấn mạnh vật/sự việc, dùng “that” sau thành phần được nhấn mạnh. “What” không dùng trong it-cleft, “which it” thừa đại từ, và “where” chỉ nơi chốn nên không phù hợp.","difficulty":3},{"type":"fill_blank","question":"Complete the **wh-cleft**: ___ the panel found most troubling was the silence of the senior auditors.","options":["What","That","It","Which"],"correct_answer":"What","explanation":"Wh-cleft cần mệnh đề danh ngữ bắt đầu bằng “What”: “What the panel found most troubling was...”. “That” không tạo câu chẻ kiểu này, “It” cần cấu trúc it-cleft khác, còn “Which” đòi hỏi lựa chọn trong một tập xác định.","difficulty":3},{"type":"fill_blank","question":"Complete the **reason cleft**: The reason the witness hesitated was ___ answering fully might incriminate her colleagues.","options":["that","because","why","what"],"correct_answer":"that","explanation":"Trong văn phong chuẩn, “The reason ... was that ...” là dạng reason cleft chính xác. “Because” bị xem là dư nghĩa sau “reason was”, còn “why” và “what” không nối đúng mệnh đề giải thích nguyên nhân ở đây.","difficulty":3},{"type":"fill_blank","question":"Complete the **verb form**: What the settlement achieved was ___ years of litigation without admitting liability.","options":["to end","ended","ending","ends"],"correct_answer":"to end","explanation":"Sau “What + clause + achieved was” có thể dùng “to + V” để diễn tả mục đích/kết quả được nhấn mạnh. “Ended/ends” sai dạng sau “was”, còn “ending” kém tự nhiên trong cấu trúc do-cleft này.","difficulty":3},{"type":"fill_blank","question":"Complete the **negative cleft**: It was not the data itself ___ the analysts questioned, but the assumptions behind it.","options":["that","what","which they","why"],"correct_answer":"that","explanation":"Cấu trúc “It was not X that...” dùng “that” để nối phần nhấn mạnh với mệnh đề còn lại. “What” không dùng sau focus trong it-cleft, “which they” thừa chủ ngữ/đại từ, và “why” chỉ lý do nên sai.","difficulty":3},{"type":"error_correction","question":"Find the error: What **the union demanded** **were** **binding safety guarantees** **before any restart**.","options":["the union demanded","were","binding safety guarantees","before any restart"],"correct_answer":"were","explanation":"Chủ ngữ “What the union demanded” là một mệnh đề danh ngữ được xem như số ít, nên động từ phải là “was”. Các cụm còn lại đúng nghĩa và đúng vai trò trong câu chẻ.","difficulty":3},{"type":"error_correction","question":"Find the error: It **was** **the whistleblower** **that** **the executives tried to discredit her**.","options":["was","the whistleblower","that","the executives tried to discredit her"],"correct_answer":"the executives tried to discredit her","explanation":"Trong it-cleft, phần sau “that” đã có “the whistleblower” làm tân ngữ được nhấn mạnh, nên không được lặp lại bằng “her”. Các phần “It was”, focus, và “that” đều đúng cấu trúc.","difficulty":3},{"type":"error_correction","question":"Find the error: The point **what** **the report emphasizes** **is** **the fragility of informal agreements**.","options":["what","the report emphasizes","is","the fragility of informal agreements"],"correct_answer":"what","explanation":"Sau danh từ “The point” cần mệnh đề quan hệ “that/which” hoặc có thể lược bỏ đại từ quan hệ, không dùng “what”. Các phần còn lại đúng: mệnh đề quan hệ, động từ “is”, và trọng tâm được nhấn mạnh.","difficulty":3},{"type":"error_correction","question":"Find the error: It **was** **by withholding key evidence** **that** **the verdict was undermined by the prosecutor**.","options":["was","by withholding key evidence","that","the verdict was undermined by the prosecutor"],"correct_answer":"the verdict was undermined by the prosecutor","explanation":"Focus “by withholding key evidence” ngụ ý tác nhân là “the prosecutor”, nên mệnh đề sau nên là “the prosecutor undermined the verdict”, không phải bị động khiến nghĩa lệch và lủng củng. “It was + by + V-ing + that” là cấu trúc nhấn mạnh cách thức hợp lệ.","difficulty":3},{"type":"multiple_choice","question":"Choose the most effective cleft sentence to emphasize the **unintended consequence** of the recent policy change.","options":["It was the recent policy change that accidentally created a loophole that several companies exploited.","What the recent policy change accidentally created was a loophole that several companies exploited.","A loophole that several companies exploited was what the recent policy change accidentally created.","The reason a loophole was exploited by several companies was the recent policy change."],"correct_answer":"What the recent policy change accidentally created was a loophole that several companies exploited.","explanation":"Cấu trúc \"What... be...\" (wh-cleft) là hiệu quả nhất để nhấn mạnh vào \"điều đã xảy ra\" hoặc \"kết quả\" của một hành động. Trong trường hợp này, \"What the recent policy change accidentally created\" làm nổi bật \"a loophole that several companies exploited\" như là hệ quả trực tiếp. Các lựa chọn khác nhấn mạnh vào chủ thể hành động (A) hoặc đưa ra lý do (D), không tập trung vào hệ quả một cách trực tiếp và tự nhiên bằng lựa chọn B.","difficulty":3}]$grammar$::jsonb, 'ai-golden', 57
from public.grammar_topics t where t.slug = 'cleft-sentences'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 58. inversion
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('inversion', 'Inversion', 'Đảo ngữ', 'advanced', 58)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Đảo ngữ', '**Đảo ngữ** là cấu trúc đảo ngược trật tự chủ ngữ-động từ thông thường, thường xảy ra sau các trạng từ phủ định hoặc hạn định ở đầu câu như *never, rarely, not only*. Mục đích chính là để nhấn mạnh hoặc tạo sắc thái trang trọng, văn phong học thuật.', $grammar$[{"en":"Never have I seen such a view.","vi":"Tôi chưa bao giờ thấy cảnh như vậy.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"Never","start":0},{"end":10,"role":"auxiliary","word":"have","start":6},{"end":12,"role":"pronoun","word":"I","start":11},{"end":17,"role":"verb","word":"seen","start":13},{"end":22,"role":"determiner","word":"such","start":18},{"end":24,"role":"article","word":"a","start":23},{"end":29,"role":"noun","word":"view","start":25}]},{"en":"Rarely does he complain.","vi":"Anh ấy hiếm khi phàn nàn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"adverb","word":"Rarely","start":0},{"end":11,"role":"auxiliary","word":"does","start":7},{"end":14,"role":"pronoun","word":"he","start":12},{"end":23,"role":"verb","word":"complain","start":15}]},{"en":"Only then did I understand.","vi":"Chỉ lúc đó tôi mới hiểu.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"adverb","word":"Only","start":0},{"end":9,"role":"adverb","word":"then","start":5},{"end":13,"role":"auxiliary","word":"did","start":10},{"end":15,"role":"pronoun","word":"I","start":14},{"end":26,"role":"verb","word":"understand","start":16}]},{"en":"Not only did she apologize, but she also paid.","vi":"Cô ấy không chỉ xin lỗi mà còn trả tiền.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"Not","start":0},{"end":8,"role":"adjective","word":"only","start":4},{"end":12,"role":"auxiliary","word":"did","start":9},{"end":16,"role":"pronoun","word":"she","start":13},{"end":26,"role":"verb","word":"apologize","start":17},{"end":31,"role":"conjunction","word":"but","start":28},{"end":35,"role":"pronoun","word":"she","start":32},{"end":40,"role":"adverb","word":"also","start":36},{"end":45,"role":"verb","word":"paid","start":41}]},{"en":"Had I known, I would have stayed.","vi":"Nếu biết, tôi đã ở lại.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":5,"role":"pronoun","word":"I","start":4},{"end":11,"role":"verb","word":"known","start":6},{"end":14,"role":"pronoun","word":"I","start":13},{"end":20,"role":"modal","word":"would","start":15},{"end":25,"role":"auxiliary","word":"have","start":21},{"end":32,"role":"verb","word":"stayed","start":26}]},{"en":"Under no circumstances should you open this door.","vi":"Trong bất kỳ hoàn cảnh nào bạn cũng không được mở cửa này.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"preposition","word":"Under","start":0},{"end":8,"role":"determiner","word":"no","start":6},{"end":22,"role":"noun","word":"circumstances","start":9},{"end":29,"role":"modal","word":"should","start":23},{"end":33,"role":"pronoun","word":"you","start":30},{"end":38,"role":"verb","word":"open","start":34},{"end":43,"role":"determiner","word":"this","start":39},{"end":48,"role":"noun","word":"door","start":44}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **negative adverbial + auxiliary + S + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"negative adverbial + auxiliary + S + V","example":"Never have I seen such a view."},{"case":"Kiểm tra thành phần theo sau","rule":"Only + expression + auxiliary + S + V","example":"Rarely does he complain."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"Had/Were/Should + S ...","example":"Only then did I understand."}],"usage":[{"en":"Never have I seen such a beautiful view.","vi":"Chưa bao giờ tôi thấy cảnh đẹp đến vậy.","icon":"🏔️","label":"Nhấn mạnh trang trọng khi mở đầu bằng trạng ngữ phủ định (Never, Rarely)"},{"en":"Rarely does he complain about anything.","vi":"Hiếm khi nào anh ấy phàn nàn về điều gì.","icon":"🤐","label":"Đảo trợ động từ lên trước chủ ngữ như câu hỏi"},{"en":"Only then did I understand the truth.","vi":"Chỉ đến lúc đó tôi mới hiểu ra sự thật.","icon":"💡","label":"Đảo ngữ sau Only then / Only when / Only after"},{"en":"Not only did she apologize, but she also paid for the damage.","vi":"Cô ấy không những xin lỗi mà còn bồi thường thiệt hại.","icon":"🎁","label":"NOT ONLY... BUT ALSO với đảo ngữ ở vế đầu"},{"en":"Hardly had I sat down when the phone rang.","vi":"Tôi vừa mới ngồi xuống thì điện thoại reo.","icon":"🚪","label":"Đảo ngữ với Hardly... when / No sooner... than"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"negative adverbial + auxiliary + S + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Only + expression + auxiliary + S + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"Had/Were/Should + S ...","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["Never","Rarely","Seldom","No sooner","Not only","Only then"],"examples":[{"en":"Never have I seen such a view.","vi":"Tôi chưa bao giờ thấy cảnh như vậy.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"Never","start":0},{"end":10,"role":"auxiliary","word":"have","start":6},{"end":12,"role":"pronoun","word":"I","start":11},{"end":17,"role":"verb","word":"seen","start":13},{"end":22,"role":"determiner","word":"such","start":18},{"end":24,"role":"article","word":"a","start":23},{"end":29,"role":"noun","word":"view","start":25}]},{"en":"Rarely does he complain.","vi":"Anh ấy hiếm khi phàn nàn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":6,"role":"adverb","word":"Rarely","start":0},{"end":11,"role":"auxiliary","word":"does","start":7},{"end":14,"role":"pronoun","word":"he","start":12},{"end":23,"role":"verb","word":"complain","start":15}]},{"en":"Only then did I understand.","vi":"Chỉ lúc đó tôi mới hiểu.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"adverb","word":"Only","start":0},{"end":9,"role":"adverb","word":"then","start":5},{"end":13,"role":"auxiliary","word":"did","start":10},{"end":15,"role":"pronoun","word":"I","start":14},{"end":26,"role":"verb","word":"understand","start":16}]},{"en":"Not only did she apologize, but she also paid.","vi":"Cô ấy không chỉ xin lỗi mà còn trả tiền.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"adverb","word":"Not","start":0},{"end":8,"role":"adjective","word":"only","start":4},{"end":12,"role":"auxiliary","word":"did","start":9},{"end":16,"role":"pronoun","word":"she","start":13},{"end":26,"role":"verb","word":"apologize","start":17},{"end":31,"role":"conjunction","word":"but","start":28},{"end":35,"role":"pronoun","word":"she","start":32},{"end":40,"role":"adverb","word":"also","start":36},{"end":45,"role":"verb","word":"paid","start":41}]},{"en":"Had I known, I would have stayed.","vi":"Nếu biết, tôi đã ở lại.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"auxiliary","word":"Had","start":0},{"end":5,"role":"pronoun","word":"I","start":4},{"end":11,"role":"verb","word":"known","start":6},{"end":14,"role":"pronoun","word":"I","start":13},{"end":20,"role":"modal","word":"would","start":15},{"end":25,"role":"auxiliary","word":"have","start":21},{"end":32,"role":"verb","word":"stayed","start":26}]},{"en":"Under no circumstances should you open this door.","vi":"Trong bất kỳ hoàn cảnh nào bạn cũng không được mở cửa này.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"preposition","word":"Under","start":0},{"end":8,"role":"determiner","word":"no","start":6},{"end":22,"role":"noun","word":"circumstances","start":9},{"end":29,"role":"modal","word":"should","start":23},{"end":33,"role":"pronoun","word":"you","start":30},{"end":38,"role":"verb","word":"open","start":34},{"end":43,"role":"determiner","word":"this","start":39},{"end":48,"role":"noun","word":"door","start":44}]}],"mistakes":[{"wrong":"Never I have seen such beauty.","right":"Never have I seen such beauty.","why":"Trạng ngữ phủ định đầu câu bắt buộc đảo trợ động từ lên trước chủ ngữ."},{"wrong":"No sooner we had arrived than it rained.","right":"No sooner had we arrived than it rained.","why":"No sooner đầu câu yêu cầu đảo ngữ (had + chủ ngữ)."},{"wrong":"Not only she sings, but she dances.","right":"Not only does she sing, but she also dances.","why":"Not only đầu câu yêu cầu đảo trợ động từ."},{"wrong":"Rarely I go out at night.","right":"Rarely do I go out at night.","why":"Rarely đầu câu cần đảo ngữ với do/does."}],"timeline":null,"comparison":"**Đảo ngữ vs câu hỏi:** Cả hai đều đặt trợ động từ trước chủ ngữ, nhưng đảo ngữ là CÂU KỂ trang trọng nhấn mạnh, kết thúc bằng dấu chấm: *Never have I seen such beauty.* Câu hỏi thật kết thúc bằng dấu hỏi: *Have I ever seen such beauty?* Trạng ngữ phủ định đầu câu → bắt buộc đảo.","definition":"**Đảo ngữ** là cấu trúc đảo ngược trật tự chủ ngữ-động từ thông thường, thường xảy ra sau các trạng từ phủ định hoặc hạn định ở đầu câu như *never, rarely, not only*. Mục đích chính là để nhấn mạnh hoặc tạo sắc thái trang trọng, văn phong học thuật."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"Never ___ such a beautiful view.","options":["I have seen","have I seen","I saw have"],"correct_answer":"have I seen","explanation":"Sau Never ở đầu câu, đảo trợ động từ have lên trước chủ ngữ I."},{"type":"multiple_choice","question":"Rarely ___ late.","options":["is she","she is","does she is"],"correct_answer":"is she","explanation":"Rarely đứng đầu câu kéo động từ to be lên trước chủ ngữ."},{"type":"multiple_choice","question":"Not only ___ English, but she also speaks French.","options":["she speaks","does she speak","she does speak"],"correct_answer":"does she speak","explanation":"Sau Not only ở đầu câu, dùng đảo ngữ does + chủ ngữ + động từ nguyên thể."},{"type":"multiple_choice","question":"Only then ___ the mistake.","options":["did I understand","I understood","I did understood"],"correct_answer":"did I understand","explanation":"Only then ở đầu câu cần đảo trợ động từ did; động từ chính dùng nguyên thể."}]$grammar$::jsonb, 'ai-golden', 58
from public.grammar_topics t where t.slug = 'inversion'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 59. discourse-markers
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('discourse-markers', 'Discourse Markers', 'Từ nối diễn ngôn', 'advanced', 59)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Từ nối diễn ngôn', '**Discourse Markers** là các từ hoặc cụm từ định hướng dùng để tổ chức và cấu trúc hóa giao tiếp, giúp người nghe hoặc người đọc nhận diện sự chuyển hướng chủ đề hoặc thái độ của người nói. Chúng đóng vai trò như các **tín hiệu chỉ dẫn (signposts)**, giúp việc điều phối thông tin trong cả văn viết lẫn văn nói trở nên tự nhiên và thuyết phục hơn.', $grammar$[{"en":"First of all, we need a clear goal.","vi":"Trước hết, chúng ta cần mục tiêu rõ ràng.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"First","start":0},{"end":8,"role":"preposition","word":"of","start":6},{"end":12,"role":"other","word":"all","start":9},{"end":16,"role":"pronoun","word":"we","start":14},{"end":21,"role":"verb","word":"need","start":17},{"end":23,"role":"article","word":"a","start":22},{"end":29,"role":"adjective","word":"clear","start":24},{"end":34,"role":"noun","word":"goal","start":30}]},{"en":"However, the plan is expensive.","vi":"Tuy nhiên, kế hoạch tốn kém.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":7,"role":"conjunction","word":"However","start":0},{"end":12,"role":"determiner","word":"the","start":9},{"end":17,"role":"noun","word":"plan","start":13},{"end":20,"role":"auxiliary","word":"is","start":18},{"end":30,"role":"adjective","word":"expensive","start":21}]},{"en":"In other words, we need more time.","vi":"Nói cách khác, chúng ta cần thêm thời gian.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"In","start":0},{"end":8,"role":"determiner","word":"other","start":3},{"end":14,"role":"noun","word":"words","start":9},{"end":18,"role":"pronoun","word":"we","start":16},{"end":23,"role":"verb","word":"need","start":19},{"end":28,"role":"determiner","word":"more","start":24},{"end":33,"role":"noun","word":"time","start":29}]},{"en":"By the way, have you called Mai?","vi":"Nhân tiện, bạn đã gọi Mai chưa?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"By","start":0},{"end":6,"role":"determiner","word":"the","start":3},{"end":10,"role":"noun","word":"way","start":7},{"end":16,"role":"auxiliary","word":"have","start":12},{"end":20,"role":"pronoun","word":"you","start":17},{"end":27,"role":"verb","word":"called","start":21},{"end":31,"role":"noun","word":"Mai","start":28}]},{"en":"On the whole, the event went well.","vi":"Nhìn chung, sự kiện diễn ra tốt đẹp.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"On","start":0},{"end":6,"role":"determiner","word":"the","start":3},{"end":12,"role":"other","word":"whole","start":7},{"end":17,"role":"determiner","word":"the","start":14},{"end":23,"role":"noun","word":"event","start":18},{"end":28,"role":"verb","word":"went","start":24},{"end":33,"role":"adverb","word":"well","start":29}]},{"en":"Admittedly, the evidence is limited.","vi":"Phải thừa nhận rằng bằng chứng còn hạn chế.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":10,"role":"adverb","word":"Admittedly","start":0},{"end":15,"role":"determiner","word":"the","start":12},{"end":24,"role":"noun","word":"evidence","start":16},{"end":27,"role":"auxiliary","word":"is","start":25},{"end":35,"role":"adjective","word":"limited","start":28}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **marker + comma + clause** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"marker + comma + clause","example":"First of all, we need a clear goal."},{"case":"Kiểm tra thành phần theo sau","rule":"clause; however, clause","example":"However, the plan is expensive."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"spoken marker + message","example":"In other words, we need more time."}],"usage":[{"en":"First of all, we need a clear goal.","vi":"Trước hết, chúng ta cần một mục tiêu rõ ràng.","icon":"1️⃣","label":"Mở đầu, sắp xếp trình tự ý (first of all, next, finally)"},{"en":"However, the plan is too expensive.","vi":"Tuy nhiên, kế hoạch này quá tốn kém.","icon":"⚖️","label":"Chuyển ý tương phản (however, on the other hand)"},{"en":"In other words, we need more time.","vi":"Nói cách khác, chúng ta cần thêm thời gian.","icon":"🔁","label":"Diễn đạt lại cho rõ (in other words, that is to say)"},{"en":"By the way, have you called Mai?","vi":"Nhân tiện, bạn đã gọi cho Mai chưa?","icon":"💬","label":"Đổi chủ đề trong hội thoại (by the way, anyway)"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"marker + comma + clause","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"clause; however, clause","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"spoken marker + message","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["however","moreover","therefore","nevertheless","on the other hand","in addition"],"examples":[{"en":"First of all, we need a clear goal.","vi":"Trước hết, chúng ta cần mục tiêu rõ ràng.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"adverb","word":"First","start":0},{"end":8,"role":"preposition","word":"of","start":6},{"end":12,"role":"other","word":"all","start":9},{"end":16,"role":"pronoun","word":"we","start":14},{"end":21,"role":"verb","word":"need","start":17},{"end":23,"role":"article","word":"a","start":22},{"end":29,"role":"adjective","word":"clear","start":24},{"end":34,"role":"noun","word":"goal","start":30}]},{"en":"However, the plan is expensive.","vi":"Tuy nhiên, kế hoạch tốn kém.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":7,"role":"conjunction","word":"However","start":0},{"end":12,"role":"determiner","word":"the","start":9},{"end":17,"role":"noun","word":"plan","start":13},{"end":20,"role":"auxiliary","word":"is","start":18},{"end":30,"role":"adjective","word":"expensive","start":21}]},{"en":"In other words, we need more time.","vi":"Nói cách khác, chúng ta cần thêm thời gian.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"In","start":0},{"end":8,"role":"determiner","word":"other","start":3},{"end":14,"role":"noun","word":"words","start":9},{"end":18,"role":"pronoun","word":"we","start":16},{"end":23,"role":"verb","word":"need","start":19},{"end":28,"role":"determiner","word":"more","start":24},{"end":33,"role":"noun","word":"time","start":29}]},{"en":"By the way, have you called Mai?","vi":"Nhân tiện, bạn đã gọi Mai chưa?","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"By","start":0},{"end":6,"role":"determiner","word":"the","start":3},{"end":10,"role":"noun","word":"way","start":7},{"end":16,"role":"auxiliary","word":"have","start":12},{"end":20,"role":"pronoun","word":"you","start":17},{"end":27,"role":"verb","word":"called","start":21},{"end":31,"role":"noun","word":"Mai","start":28}]},{"en":"On the whole, the event went well.","vi":"Nhìn chung, sự kiện diễn ra tốt đẹp.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"On","start":0},{"end":6,"role":"determiner","word":"the","start":3},{"end":12,"role":"other","word":"whole","start":7},{"end":17,"role":"determiner","word":"the","start":14},{"end":23,"role":"noun","word":"event","start":18},{"end":28,"role":"verb","word":"went","start":24},{"end":33,"role":"adverb","word":"well","start":29}]},{"en":"Admittedly, the evidence is limited.","vi":"Phải thừa nhận rằng bằng chứng còn hạn chế.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":10,"role":"adverb","word":"Admittedly","start":0},{"end":15,"role":"determiner","word":"the","start":12},{"end":24,"role":"noun","word":"evidence","start":16},{"end":27,"role":"auxiliary","word":"is","start":25},{"end":35,"role":"adjective","word":"limited","start":28}]}],"mistakes":[{"wrong":"Although he was tired, but he continued.","right":"Although he was tired, he continued.","why":"Không ghép although...but trong một câu."},{"wrong":"I like it. However I won't buy it.","right":"I like it. However, I won't buy it.","why":"However đầu câu cần dấu phẩy sau nó."},{"wrong":"Despite of the rain, we went out.","right":"Despite the rain, we went out.","why":"Despite không đi với of (khác in spite OF)."},{"wrong":"On the other hands, it is cheaper.","right":"On the other hand, it is cheaper.","why":"Cụm cố định là on the other HAND (số ít)."}],"timeline":null,"comparison":"**Liên từ nhượng bộ vs giới từ tương phản:** *Although it rained, we had a good time* (although + mệnh đề) vs *Despite the rain, we had a good time* (despite + danh từ). Và tiếng Anh chuẩn KHÔNG cho ghép đôi although...but trong cùng một câu như tiếng Việt \"mặc dù...nhưng\".","definition":"**Discourse Markers** là các từ hoặc cụm từ định hướng dùng để tổ chức và cấu trúc hóa giao tiếp, giúp người nghe hoặc người đọc nhận diện sự chuyển hướng chủ đề hoặc thái độ của người nói. Chúng đóng vai trò như các **tín hiệu chỉ dẫn (signposts)**, giúp việc điều phối thông tin trong cả văn viết lẫn văn nói trở nên tự nhiên và thuyết phục hơn."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"Hoàn thành theo mẫu: However, the plan ___ expensive.","answer":["is"],"fb":"Chọn từ phù hợp với chủ ngữ, thời điểm và cấu trúc."},{"type":"multiple_choice","question":"Choose the best **concession marker**: The data set is relatively small; ___, the trend is statistically robust.","options":["nevertheless","for instance","namely","by the way"],"correct_answer":"nevertheless","explanation":"“Nevertheless” diễn tả sự nhượng bộ: dù dữ liệu nhỏ, xu hướng vẫn đáng tin cậy. “For instance” đưa ví dụ, “namely” giải thích cụ thể, còn “by the way” chuyển sang chuyện phụ nên không phù hợp.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **reformulation marker**: The policy would centralize decision-making; ___, local teams would lose much of their autonomy.","options":["in other words","on the contrary","meanwhile","all the same"],"correct_answer":"in other words","explanation":"“In other words” dùng để nói lại cùng ý theo cách rõ hơn. “On the contrary” phản bác, “meanwhile” chỉ sự đồng thời, “all the same” diễn tả tương phản/nhượng bộ.","difficulty":2},{"type":"multiple_choice","question":"Choose the most natural **topic shift**: The budget figures look stable. ___, has the client approved the new timeline?","options":["Incidentally","Therefore","Likewise","For that reason"],"correct_answer":"Incidentally","explanation":"“Incidentally” dùng để chuyển nhẹ sang thông tin liên quan hoặc phụ thêm. “Therefore” và “For that reason” nêu kết quả, còn “Likewise” nêu sự tương đồng.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **ordering marker**: ___, the committee must define what counts as a successful outcome.","options":["To begin with","Conversely","Be that as it may","In the meantime"],"correct_answer":"To begin with","explanation":"“To begin with” mở đầu chuỗi lập luận hoặc bước đầu tiên. Các lựa chọn còn lại lần lượt chỉ tương phản, nhượng bộ/chuyển hướng, và khoảng thời gian xen giữa.","difficulty":1},{"type":"multiple_choice","question":"Choose the correct **emphasis marker**: The method is not merely convenient; ___, it reduces measurement bias.","options":["more importantly","otherwise","instead","for example"],"correct_answer":"more importantly","explanation":"“More importantly” nhấn mạnh ý sau là quan trọng hơn. “Otherwise” nêu điều kiện/kết quả trái lại, “instead” thay thế, “for example” đưa ví dụ.","difficulty":2},{"type":"multiple_choice","question":"Choose the best **contrast marker**: The first report blamed poor training. ___, the second pointed to flawed incentives.","options":["By contrast","In short","As a result","In particular"],"correct_answer":"By contrast","explanation":"“By contrast” so sánh hai ý trái chiều. “In short” tóm tắt, “As a result” nêu kết quả, “In particular” làm rõ một phần cụ thể.","difficulty":2},{"type":"multiple_choice","question":"Choose the appropriate **generalizing marker**: The interviews varied in detail, but ___, participants supported the reform.","options":["on the whole","after all","for one thing","that is to say"],"correct_answer":"on the whole","explanation":"“On the whole” nghĩa là xét tổng thể, phù hợp khi rút ra nhận định chung. “After all” đưa lý do nhắc lại, “for one thing” mở lý do đầu tiên, “that is to say” diễn giải lại.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **clarification marker**: The contract excludes consequential loss, ___ losses that arise indirectly from the breach.","options":["that is","meanwhile","still","otherwise"],"correct_answer":"that is","explanation":"“That is” dùng để làm rõ hoặc định nghĩa lại cụm trước. “Meanwhile” chỉ đồng thời, “still” nhượng bộ, “otherwise” nêu hệ quả trái lại.","difficulty":3},{"type":"fill_blank","question":"Complete with the best **result marker**: The deadline was brought forward; ___, several teams had to reassign staff.","options":["as a result","for example","in contrast","to put it mildly"],"correct_answer":"as a result","explanation":"“As a result” nối nguyên nhân với kết quả: hạn chót đổi nên các nhóm phải điều phối lại nhân sự. Các đáp án khác lần lượt đưa ví dụ, tương phản, hoặc giảm nhẹ sắc thái đánh giá.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with a **limiting marker**: The proposal is persuasive. ___, it says little about long-term maintenance costs.","options":["Having said that","Similarly","In fact","For instance"],"correct_answer":"Having said that","explanation":"“Having said that” dùng để giới hạn hoặc cân bằng nhận xét vừa nêu. “Similarly” chỉ tương đồng, “In fact” bổ sung/nhấn mạnh sự thật, “For instance” đưa ví dụ.","difficulty":3},{"type":"fill_blank","question":"Complete with an **additive marker**: The model is cheaper to run. ___, it can be audited more easily.","options":["Moreover","Conversely","Instead","Hence"],"correct_answer":"Moreover","explanation":"“Moreover” thêm một luận điểm cùng chiều và có tính tăng cường. “Conversely” là tương phản, “Instead” là thay thế, “Hence” là kết quả.","difficulty":2},{"type":"fill_blank","question":"Complete the **stance marker**: ___, I find the evidence too anecdotal to support such a strong conclusion.","options":["Frankly","Consequently","For example","In the meantime"],"correct_answer":"Frankly","explanation":"“Frankly” thể hiện thái độ thẳng thắn của người nói trước nhận định. Các lựa chọn khác không diễn tả stance cá nhân mà chỉ kết quả, ví dụ hoặc thời gian xen giữa.","difficulty":2},{"type":"fill_blank","question":"Complete with the correct **summary marker**: The figures are volatile, the sample is narrow, and the controls are weak. ___, the claim is premature.","options":["In short","On the contrary","By the way","In the same vein"],"correct_answer":"In short","explanation":"“In short” dùng để tóm tắt kết luận từ các ý trước. “On the contrary” phản bác, “By the way” chuyển chủ đề, “In the same vein” nối ý tương tự.","difficulty":1},{"type":"fill_blank","question":"Complete the sentence with a **counterargument marker**: The software is expensive. ___, the cost of manual processing is higher.","options":["Then again","For instance","Likewise","To begin with"],"correct_answer":"Then again","explanation":"“Then again” đưa một góc nhìn đối lập để cân bằng nhận định trước. “For instance” đưa ví dụ, “Likewise” chỉ tương đồng, “To begin with” mở đầu lập luận.","difficulty":3},{"type":"fill_blank","question":"Complete with the best **example marker**: Several safeguards are missing; ___, there is no independent appeal process.","options":["for one thing","nevertheless","therefore","in brief"],"correct_answer":"for one thing","explanation":"“For one thing” giới thiệu một lý do hoặc ví dụ đầu tiên trong chuỗi lập luận. “Nevertheless” nhượng bộ, “therefore” kết luận, “in brief” tóm tắt.","difficulty":2},{"type":"fill_blank","question":"Complete the sentence with an **inference marker**: The witness changed his account three times; ___, the jury may doubt his reliability.","options":["accordingly","incidentally","in particular","all the same"],"correct_answer":"accordingly","explanation":"“Accordingly” diễn tả kết quả hoặc suy luận hợp lý từ thông tin trước. “Incidentally” chuyển ý phụ, “in particular” nêu chi tiết cụ thể, “all the same” nhượng bộ.","difficulty":3},{"type":"fill_blank","question":"Complete with the best **return marker**: The funding issue can wait. ___, the immediate question is whether the pilot is safe.","options":["To return to the point","On top of that","For that matter","In comparison"],"correct_answer":"To return to the point","explanation":"“To return to the point” đưa cuộc nói chuyện quay lại trọng tâm. Các đáp án khác thêm ý, mở rộng liên quan, hoặc so sánh.","difficulty":3},{"type":"error_correction","question":"Find the error: The evidence is preliminary; **therefore**, the authors wisely avoid firm conclusions.","options":["The evidence","therefore","wisely avoid","firm conclusions"],"correct_answer":"therefore","explanation":"Ý sau không phải kết quả logic của “preliminary” mà là sự nhượng bộ/cân bằng, nên nên dùng “nevertheless” hoặc “even so”. “Therefore” chỉ kết quả trực tiếp, làm quan hệ ý nghĩa bị sai.","difficulty":3},{"type":"error_correction","question":"Find the error: **For example**, the study has two main limitations: sample size and selection bias.","options":["For example","two main limitations","sample size","selection bias"],"correct_answer":"For example","explanation":"Sau dấu hai chấm là liệt kê/định danh hai hạn chế, không phải đưa ví dụ. Marker tự nhiên hơn là “Specifically” hoặc “Namely”.","difficulty":3},{"type":"error_correction","question":"Find the error: The merger may reduce costs; **similarly**, it could eliminate hundreds of jobs.","options":["The merger","may reduce costs","similarly","could eliminate"],"correct_answer":"similarly","explanation":"Hai ý không tương đồng về tác động mà có sắc thái bổ sung gây bất lợi hoặc chuyển hướng đánh giá. Nên dùng “however”, “at the same time” hoặc “more worryingly” tùy ý định.","difficulty":3},{"type":"error_correction","question":"Find the error: The experiment failed to replicate; **in other words**, the hypothesis remains fully confirmed.","options":["failed to replicate","in other words","the hypothesis","fully confirmed"],"correct_answer":"in other words","explanation":"“In other words” phải diễn giải lại cùng ý, nhưng mệnh đề sau lại nói điều trái với “failed to replicate”. Cần dùng marker tương phản mạnh như “despite this” nếu muốn giữ ý sau, hoặc sửa nội dung sau cho phù hợp.","difficulty":3},{"type":"error_correction","question":"Find the error: The city expanded the subway network; **by the way**, average commute times fell.","options":["expanded","by the way","average commute times","fell"],"correct_answer":"by the way","explanation":"Ý sau là kết quả hoặc hệ quả liên quan trực tiếp, không phải thông tin chen ngang. Nên dùng “as a result” hoặc “consequently”.","difficulty":2},{"type":"error_correction","question":"Find the error: **On the contrary**, I agree with most of your analysis, although I question the conclusion.","options":["On the contrary","agree with","most of","the conclusion"],"correct_answer":"On the contrary","explanation":"“On the contrary” dùng để bác bỏ điều vừa nói, nhưng câu này chỉ giới hạn mức độ đồng ý. Marker phù hợp hơn là “By and large” hoặc “For the most part”.","difficulty":3},{"type":"error_correction","question":"Find the error: The report is concise; **namely**, it omits the methodology section.","options":["The report","concise","namely","omits"],"correct_answer":"namely","explanation":"“Namely” dùng để nêu tên hoặc giải thích cụ thể, không diễn tả mặt hạn chế trái chiều. Nên dùng “however” hoặc “that said”.","difficulty":2},{"type":"error_correction","question":"Find the error: **Meanwhile**, the CEO resigned last night, the board has appointed an interim chair.","options":["Meanwhile","resigned","last night","has appointed"],"correct_answer":"Meanwhile","explanation":"Câu đang nối hai mệnh đề theo quan hệ kết quả/tiếp nối, không phải hai sự kiện đồng thời độc lập. Cần dùng “Subsequently” hoặc tách câu; nếu giữ “Meanwhile”, phải làm rõ hành động xảy ra song song.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **concession marker**: The archive is incomplete; ___, it remains the only source that records the negotiations in detail.","options":["even so","therefore","for instance","in the meantime"],"correct_answer":"even so","explanation":"“Even so” diễn đạt nhượng bộ: dù hồ sơ không đầy đủ, nó vẫn có giá trị. “Therefore” chỉ kết quả, “for instance” nêu ví dụ, còn “in the meantime” chỉ thời gian song song nên không phù hợp.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **dismissal marker**: The legal issue is complex. ___, the real obstacle is political will, not interpretation.","options":["In any case","Likewise","That is to say","For this reason"],"correct_answer":"In any case","explanation":"“In any case” chuyển hướng và gạt bớt chi tiết trước đó để nhấn mạnh điểm chính hơn. “Likewise” so sánh tương đồng, “that is to say” diễn giải lại, “for this reason” nêu nguyên nhân-kết quả.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **balancing marker**: The treatment is costly and uncomfortable; ___, it has produced unusually durable results.","options":["on the other hand","namely","as a result","by the same token"],"correct_answer":"on the other hand","explanation":"“On the other hand” đặt hai mặt trái chiều của cùng vấn đề lên bàn cân. “Namely” nêu cụ thể, “as a result” chỉ kết quả, “by the same token” dùng cho lập luận tương tự.","difficulty":2},{"type":"multiple_choice","question":"Choose the most natural **stance marker**: ___, the committee underestimated how strongly residents would oppose the rezoning plan.","options":["If anything","Meanwhile","For example","In short"],"correct_answer":"If anything","explanation":"“If anything” dùng để điều chỉnh hoặc nhấn mạnh nhận định theo hướng mạnh hơn: nếu có gì thì họ còn đánh giá thấp mức phản đối. Các lựa chọn khác lần lượt chỉ thời gian, ví dụ, hoặc tóm tắt.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **qualification marker**: The survey suggests broad approval. ___, its respondents were mostly urban professionals.","options":["That said","Consequently","More specifically","To begin with"],"correct_answer":"That said","explanation":"“That said” đưa ra giới hạn hoặc điểm làm mềm nhận định trước đó. “Consequently” là kết quả, “more specifically” làm rõ chi tiết, “to begin with” mở đầu chuỗi ý.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **correction marker**: The witness did not contradict herself; ___, she supplied details that were absent from her first statement.","options":["rather","similarly","after all","on top of that"],"correct_answer":"rather","explanation":"“Rather” dùng để sửa hoặc thay thế cách hiểu trước đó. “Similarly” chỉ tương đồng, “after all” củng cố lý do đã biết, “on top of that” thêm thông tin.","difficulty":3},{"type":"multiple_choice","question":"Choose the most suitable **comparison marker**: The new policy rewards short-term output. ___, the old system rewarded long-term mentoring.","options":["By contrast","In particular","All the same","In effect"],"correct_answer":"By contrast","explanation":"“By contrast” đối chiếu trực tiếp hai hệ thống khác nhau. “In particular” nêu cụ thể, “all the same” nhượng bộ, còn “in effect” nói về tác động thực chất.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **concluding marker**: The samples were contaminated, the logs were incomplete, and the protocol was changed mid-trial. ___, the findings cannot be treated as decisive.","options":["Taken together","Incidentally","In the first place","For one thing"],"correct_answer":"Taken together","explanation":"“Taken together” gom nhiều dữ kiện lại để rút ra kết luận chung. “Incidentally” thêm ý phụ, “in the first place” quay về điểm nền tảng, “for one thing” mở một lý do trong danh sách.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **digression marker**: The manuscript needs stronger evidence. ___, did the journal ever reply to your appeal?","options":["On a separate note","Accordingly","In the same vein","That is"],"correct_answer":"On a separate note","explanation":"“On a separate note” báo hiệu chuyển sang vấn đề khác nhưng vẫn trong mạch hội thoại. “Accordingly” chỉ hệ quả, “in the same vein” giữ cùng hướng ý, “that is” diễn giải lại.","difficulty":2},{"type":"fill_blank","question":"Complete with a **hedging marker**: The figures are encouraging; ___, they should be interpreted with caution because the follow-up period was short.","options":["nevertheless","arguably","for example","instead"],"correct_answer":"nevertheless","explanation":"“Nevertheless” phù hợp vì câu sau làm giảm sức mạnh của nhận định tích cực trước đó. “Arguably” thể hiện lập trường tranh luận nhưng không nối quan hệ nhượng bộ rõ bằng; “for example” nêu ví dụ, “instead” thay thế.","difficulty":3},{"type":"fill_blank","question":"Complete the **return marker**: The staffing problem is serious, but it is not urgent today. ___, the immediate decision concerns whether to publish the audit.","options":["To return to the point","As a result","For comparison","In other respects"],"correct_answer":"To return to the point","explanation":"“To return to the point” đưa cuộc thảo luận quay lại vấn đề chính sau một đoạn lệch hướng. Các lựa chọn còn lại chỉ kết quả, so sánh hoặc phạm vi khác nên sai quan hệ diễn ngôn.","difficulty":3},{"type":"fill_blank","question":"Complete with an **amplifying marker**: The proposal would reduce paperwork. ___, it would make the approval process transparent to applicants.","options":["More importantly","On the contrary","For that reason","Meanwhile"],"correct_answer":"More importantly","explanation":"“More importantly” thêm một ý có trọng lượng lớn hơn ý trước. “On the contrary” phủ định ý trước, “for that reason” chỉ kết quả, “meanwhile” chỉ đồng thời hoặc chuyển cảnh.","difficulty":2},{"type":"fill_blank","question":"Complete the **reframing marker**: The reform is not a cost-cutting exercise. ___, it is an attempt to change how risk is distributed.","options":["Put differently","Moreover","Otherwise","At first"],"correct_answer":"Put differently","explanation":"“Put differently” diễn đạt lại vấn đề theo khung nhìn khác. “Moreover” thêm ý, “otherwise” nêu điều kiện trái lại, “at first” chỉ thời điểm ban đầu.","difficulty":3},{"type":"fill_blank","question":"Complete with the best **sequencing marker**: ___, the board should decide whether the complaint falls within its mandate at all.","options":["Before anything else","In the same way","As it happens","On balance"],"correct_answer":"Before anything else","explanation":"“Before anything else” nhấn mạnh việc cần làm đầu tiên trong trình tự xử lý. Các lựa chọn khác lần lượt chỉ tương đồng, tình cờ xảy ra, hoặc cân nhắc tổng thể.","difficulty":2},{"type":"fill_blank","question":"Complete the **illustration marker**: Some safeguards are merely symbolic; ___, the review panel can advise ministers but cannot block a decision.","options":["for one","thereby","conversely","still"],"correct_answer":"for one","explanation":"“For one” đưa ra một ví dụ tiêu biểu trong số nhiều khả năng. “Thereby” chỉ phương tiện/kết quả, “conversely” đảo chiều đối lập, “still” nhượng bộ.","difficulty":3},{"type":"fill_blank","question":"Complete with a **causal marker**: The regulator had ignored repeated warnings. ___, public confidence collapsed after the breach became known.","options":["Unsurprisingly","Alternatively","To be precise","Likewise"],"correct_answer":"Unsurprisingly","explanation":"“Unsurprisingly” nối nguyên nhân ngầm với kết quả dễ đoán, đồng thời thể hiện thái độ của người nói. “Alternatively” nêu phương án khác, “to be precise” làm chính xác hơn, “likewise” chỉ tương tự.","difficulty":3},{"type":"fill_blank","question":"Complete the **limiting marker**: The model predicts demand well in stable markets. ___, it performs poorly during sudden regulatory changes.","options":["Even then","In addition","For example","In brief"],"correct_answer":"Even then","explanation":"“Even then” giới hạn hiệu lực của nhận định trước: ngay cả trong/ở trường hợp đó vẫn có vấn đề. “In addition” thêm ý, “for example” nêu ví dụ, “in brief” tóm tắt.","difficulty":3},{"type":"error_correction","question":"Find the error: The court accepted the evidence; **alternatively**, it dismissed the defendant's appeal.","options":["The court","accepted","alternatively","dismissed"],"correct_answer":"alternatively","explanation":"“Alternatively” dùng để nêu lựa chọn thay thế, không phù hợp khi câu sau là hệ quả hoặc diễn biến tiếp theo. Có thể dùng “subsequently” nếu nhấn mạnh trình tự, hoặc “therefore” nếu muốn chỉ kết quả.","difficulty":3},{"type":"error_correction","question":"Find the error: **To sum up**, the first objection concerns cost, while the second concerns legality.","options":["To sum up","first objection","while","second concerns"],"correct_answer":"To sum up","explanation":"“To sum up” dùng để kết luận sau khi đã trình bày các ý, không tự nhiên khi bắt đầu liệt kê hai điểm mới. Ở đây nên dùng “To begin with” hoặc “First”.","difficulty":2},{"type":"error_correction","question":"Find the error: The amendment protects tenants; **for one thing**, it also caps annual rent increases.","options":["amendment","protects tenants","for one thing","also caps"],"correct_answer":"for one thing","explanation":"“For one thing” mở một lý do hoặc ví dụ, nhưng “also” cho thấy đây là ý bổ sung trực tiếp. “Moreover” hoặc “in addition” tự nhiên hơn trong quan hệ này.","difficulty":3},{"type":"error_correction","question":"Find the error: The product was marketed as sustainable; **indeed**, later tests found unsafe levels of lead.","options":["marketed","sustainable","indeed","unsafe levels"],"correct_answer":"indeed","explanation":"“Indeed” thường củng cố hoặc nhấn mạnh ý trước, trong khi câu sau lại bác bỏ hình ảnh “sustainable”. Nên dùng “however” hoặc “in fact” tùy ý muốn nhấn mạnh sự trái ngược.","difficulty":3},{"type":"error_correction","question":"Find the error: The committee postponed the vote; **to be precise**, members had not yet received the legal opinion.","options":["postponed","to be precise","members","legal opinion"],"correct_answer":"to be precise","explanation":"“To be precise” dùng để làm chính xác một thông tin vừa nêu, không nối lý do giải thích cho việc hoãn. “Because” hoặc “as” phù hợp hơn để chỉ nguyên nhân.","difficulty":3},{"type":"error_correction","question":"Find the error: **Conversely**, both departments reported higher productivity after the new system was introduced.","options":["Conversely","both departments","higher productivity","was introduced"],"correct_answer":"Conversely","explanation":"“Conversely” cần quan hệ đảo ngược hoặc đối lập với ý trước, nhưng câu này chỉ nói hai bộ phận có cùng kết quả. Nên dùng “Similarly” hoặc “Likewise” nếu muốn nhấn mạnh sự tương đồng.","difficulty":2},{"type":"error_correction","question":"Find the error: The contract is valid until June; **hence**, either party may terminate it without notice before then.","options":["contract","valid until June","hence","without notice"],"correct_answer":"hence","explanation":"“Hence” chỉ kết quả logic, nhưng quyền chấm dứt không báo trước không suy ra tự nhiên từ việc hợp đồng còn hiệu lực đến tháng Sáu. Cần một marker đối lập như “however” nếu điều khoản sau là ngoại lệ.","difficulty":3},{"type":"error_correction","question":"Find the error: The minister denied receiving the memo; **in fact**, she had never been briefed on the issue.","options":["denied receiving","in fact","never been briefed","on the issue"],"correct_answer":"in fact","explanation":"“In fact” thường củng cố hoặc sửa thông tin trước bằng sự thật mạnh hơn, và ở đây câu sau lại phù hợp với việc bà ấy phủ nhận nhận memo nên không phải lỗi rõ về nghĩa? Trong ngữ cảnh muốn bổ sung cùng hướng, “indeed” tự nhiên hơn; “in fact” vẫn có thể đúng, nhưng nếu câu hỏi yêu cầu lỗi thì marker này là điểm kém chính xác nhất.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **contrast marker**: The policy was designed to reduce inequality; ___, its benefits have flowed mainly to households that were already secure.","options":["paradoxically","similarly","for example","meanwhile"],"correct_answer":"paradoxically","explanation":"“Paradoxically” đúng vì diễn tả kết quả trái ngược với mục tiêu ban đầu của chính sách. “Similarly” chỉ sự tương đồng, “for example” đưa ví dụ, còn “meanwhile” nhấn mạnh sự việc xảy ra cùng lúc hoặc chuyển sang diễn biến khác.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **reformulation marker**: The proposal does not abolish oversight. ___, it moves oversight from the ministry to an independent panel.","options":["Rather","Besides","Consequently","Meanwhile"],"correct_answer":"Rather","explanation":"“Rather” đúng vì câu sau sửa lại hoặc diễn đạt chính xác hơn điều vừa phủ định. “Besides” thêm ý, “consequently” chỉ kết quả, còn “meanwhile” không phù hợp với quan hệ cải chính này.","difficulty":2},{"type":"multiple_choice","question":"Choose the most natural **resumption marker**: We can discuss the budget later. ___, the urgent question is whether the safety review should be released today.","options":["To return to the point","For instance","All the same","In comparison"],"correct_answer":"To return to the point","explanation":"“To return to the point” đúng vì đưa cuộc thảo luận quay lại vấn đề chính. “For instance” nêu ví dụ, “all the same” chỉ nhượng bộ, còn “in comparison” dùng để so sánh.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **emphasis marker**: The witness was not merely uncertain; ___, she gave three mutually incompatible accounts of the meeting.","options":["more importantly","otherwise","by contrast","incidentally"],"correct_answer":"more importantly","explanation":"“More importantly” đúng vì nhấn mạnh thông tin nghiêm trọng hơn sau đó. “Otherwise” chỉ điều kiện trái lại, “by contrast” đối lập hai đối tượng, còn “incidentally” thêm thông tin ngoài lề.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **exemplification marker**: The platform rewards superficial engagement. ___, posts with provocative headlines are promoted even when users do not read them.","options":["For example","Nevertheless","Instead","In short"],"correct_answer":"For example","explanation":"“For example” đúng vì câu sau minh họa cho nhận định chung ở câu trước. “Nevertheless” chỉ tương phản, “instead” chỉ thay thế, còn “in short” dùng để tóm tắt.","difficulty":1},{"type":"multiple_choice","question":"Choose the most suitable **qualification marker**: The data support the claim in broad terms. ___, they say little about poorer regions where sampling was sparse.","options":["Even so","Specifically","Conversely","To begin with"],"correct_answer":"Even so","explanation":"“Even so” đúng vì thừa nhận ý trước nhưng giới hạn sức mạnh của kết luận. “Specifically” làm rõ chi tiết, “conversely” chỉ sự đối lập đảo chiều, còn “to begin with” dùng để mở đầu chuỗi lập luận.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **transition marker**: The paper explains why the reform failed. ___, it considers what future legislation might learn from that failure.","options":["Having said that","Next","On the contrary","After all"],"correct_answer":"Next","explanation":"“Next” đúng vì chuyển sang phần tiếp theo trong trình tự trình bày. “Having said that” thường mở ý nhượng bộ, “on the contrary” bác bỏ ý trước, còn “after all” đưa lý do củng cố.","difficulty":2},{"type":"multiple_choice","question":"Choose the correct **inference marker**: No minutes were kept, and the participants now disagree about what was promised. ___, the committee cannot reconstruct the decision with confidence.","options":["Accordingly","Likewise","Incidentally","Alternatively"],"correct_answer":"Accordingly","explanation":"“Accordingly” đúng vì câu sau là kết luận hợp lý từ các dữ kiện trước. “Likewise” chỉ tương tự, “incidentally” thêm ý phụ, còn “alternatively” đưa lựa chọn khác.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **clarification marker**: The author uses “community” in a narrow sense. ___, she means residents with voting rights, not all people who live nearby.","options":["That is","Still","Meanwhile","For one thing"],"correct_answer":"That is","explanation":"“That is” đúng vì câu sau giải thích chính xác nghĩa của thuật ngữ trước đó. “Still” chỉ tương phản nhẹ, “meanwhile” chỉ đồng thời hoặc chuyển cảnh, còn “for one thing” đưa lý do đầu tiên.","difficulty":2},{"type":"fill_blank","question":"Complete with a **concession marker**: The interview sample was small; ___, the responses were unusually detailed and internally consistent.","options":["nonetheless","therefore","for instance","similarly"],"correct_answer":"nonetheless","explanation":"“Nonetheless” đúng vì diễn tả sự nhượng bộ: dù mẫu nhỏ, dữ liệu vẫn có giá trị. “Therefore” chỉ kết quả, “for instance” nêu ví dụ, còn “similarly” chỉ sự tương đồng.","difficulty":2},{"type":"fill_blank","question":"Complete the **topic shift**: The merger still requires regulatory approval. ___, have you seen the revised timetable for staff consultations?","options":["By the way","In conclusion","As a result","For this reason"],"correct_answer":"By the way","explanation":"“By the way” đúng vì chuyển sang thông tin liên quan nhưng không phải trọng tâm ban đầu. “In conclusion” kết luận, còn “as a result” và “for this reason” chỉ quan hệ kết quả.","difficulty":1},{"type":"fill_blank","question":"Complete with a **corrective marker**: The speaker did not promise immediate reform; ___, she promised to appoint a commission to study it.","options":["rather","therefore","meanwhile","similarly"],"correct_answer":"rather","explanation":"“Rather” đúng vì sửa lại một cách hiểu sai ở mệnh đề trước. “Therefore” chỉ kết quả, “meanwhile” chỉ đồng thời hoặc chuyển cảnh, còn “similarly” chỉ sự giống nhau.","difficulty":2},{"type":"fill_blank","question":"Complete the **summative marker**: The proposal is legally uncertain, administratively costly, and politically fragile. ___, it is unlikely to survive in its present form.","options":["In short","For example","On the other hand","Incidentally"],"correct_answer":"In short","explanation":"“In short” đúng vì tóm tắt các lý do trước thành một kết luận ngắn gọn. “For example” nêu ví dụ, “on the other hand” đưa mặt đối lập, còn “incidentally” thêm ý phụ.","difficulty":2},{"type":"fill_blank","question":"Complete with an **additive marker**: The new archive preserves official correspondence. ___, it includes private diaries that reveal how decisions were negotiated informally.","options":["Moreover","Nevertheless","Otherwise","In contrast"],"correct_answer":"Moreover","explanation":"“Moreover” đúng vì bổ sung một lợi ích quan trọng hơn hoặc thêm vào cùng hướng lập luận. “Nevertheless” chỉ nhượng bộ, “otherwise” chỉ điều kiện trái lại, còn “in contrast” chỉ đối lập.","difficulty":1},{"type":"fill_blank","question":"Complete the **stance marker**: ___, the report treats a political compromise as if it were a neutral technical solution.","options":["To my mind","For example","In the meantime","As a result"],"correct_answer":"To my mind","explanation":"“To my mind” đúng vì báo hiệu quan điểm hoặc đánh giá của người nói. “For example” đưa ví dụ, “in the meantime” chỉ thời gian chờ đợi, còn “as a result” chỉ kết quả.","difficulty":2},{"type":"fill_blank","question":"Complete with a **causal marker**: The instructions were ambiguous and the deadline changed twice. ___, several teams submitted incompatible versions of the form.","options":["As a result","By comparison","In other words","At any rate"],"correct_answer":"As a result","explanation":"“As a result” đúng vì câu sau là hệ quả của các vấn đề nêu trước. “By comparison” dùng để so sánh, “in other words” diễn đạt lại, còn “at any rate” chuyển sang hoặc chốt lại ý chính.","difficulty":2},{"type":"fill_blank","question":"Complete the **counterargument marker**: The law may discourage some frivolous claims. ___, it could also deter legitimate complaints from workers who fear retaliation.","options":["On the other hand","Namely","To put it briefly","Meanwhile"],"correct_answer":"On the other hand","explanation":"“On the other hand” đúng vì đưa mặt trái hoặc lập luận đối trọng với lợi ích vừa nêu. “Namely” nêu cụ thể, “to put it briefly” tóm tắt, còn “meanwhile” không thể hiện đối trọng lập luận rõ ràng.","difficulty":2},{"type":"error_correction","question":"Find the error: The grant was not renewed; **for example**, the laboratory had to suspend two long-term projects.","options":["The grant","for example","had to suspend","long-term projects"],"correct_answer":"for example","explanation":"“For example” sai vì câu sau là hệ quả, không phải ví dụ minh họa cho câu trước. Nên dùng “therefore” hoặc “as a result”; các cụm còn lại đúng về ngữ pháp và nghĩa.","difficulty":2},{"type":"error_correction","question":"Find the error: **Nevertheless**, the report is comprehensive, it overlooks how rural clinics collect patient data.","options":["Nevertheless","the report","it overlooks","patient data"],"correct_answer":"Nevertheless","explanation":"“Nevertheless” không phù hợp khi hai mệnh đề được nối trực tiếp bằng dấu phẩy như vậy; cần cấu trúc “The report is comprehensive; nevertheless, it overlooks...” hoặc “Although the report is comprehensive, it overlooks...”. Các lựa chọn còn lại không phải lỗi chính của câu.","difficulty":3},{"type":"error_correction","question":"Find the error: The algorithm performs well on curated images; **similarly**, it fails on noisy images from mobile phones.","options":["performs well","similarly","fails on","mobile phones"],"correct_answer":"similarly","explanation":"“Similarly” sai vì hai ý đối lập: hoạt động tốt trên ảnh chọn lọc nhưng thất bại trên ảnh nhiễu. Nên dùng “however” hoặc “by contrast”; các cụm khác phù hợp với nội dung câu.","difficulty":2},{"type":"error_correction","question":"Find the error: The committee rejected the first option; **in addition**, it chose the second instead.","options":["rejected","in addition","chose","instead"],"correct_answer":"in addition","explanation":"“In addition” sai vì câu sau không chỉ thêm thông tin cùng hướng mà nêu lựa chọn thay thế. “Instead” đã báo hiệu quan hệ thay thế, nên marker phù hợp hơn là bỏ “in addition” hoặc dùng “instead” ở vị trí nối.","difficulty":2},{"type":"error_correction","question":"Find the error: The figures look impressive at first sight; **that is**, the underlying measurements are too inconsistent to support them.","options":["figures","that is","underlying measurements","support them"],"correct_answer":"that is","explanation":"“That is” sai vì câu sau không giải thích lại câu trước mà phủ định độ tin cậy của nó. Nên dùng “however” hoặc “on closer inspection”; các cụm còn lại không sai trong ngữ cảnh.","difficulty":3},{"type":"error_correction","question":"Find the error: **For this reason**, I am not convinced by the proposal, although several of its assumptions seem plausible.","options":["For this reason","not convinced","proposal","several of"],"correct_answer":"For this reason","explanation":"“For this reason” sai vì trước đó không có lý do nào được nêu để “vì lý do này”. Trong câu độc lập này, marker phù hợp hơn là “Overall” hoặc “Still”; các phần còn lại đúng.","difficulty":3},{"type":"error_correction","question":"Find the error: The museum has expanded its public programs; **to be sure**, attendance has increased by nearly forty percent.","options":["has expanded","to be sure","attendance","forty percent"],"correct_answer":"to be sure","explanation":"“To be sure” thường thừa nhận một điểm trước khi đưa ý đối lập hoặc giới hạn, nhưng ở đây câu sau là hệ quả hoặc bằng chứng cùng hướng. Nên dùng “indeed” hoặc “as a result”; các cụm khác phù hợp.","difficulty":3},{"type":"error_correction","question":"Find the error: The regulation applies to commercial operators; **in particular**, it does not apply to private households.","options":["applies to","commercial operators","in particular","private households"],"correct_answer":"in particular","explanation":"“In particular” sai vì câu sau không nêu một trường hợp cụ thể thuộc nhóm trước mà loại trừ một nhóm khác. Nên dùng “however” hoặc “by contrast”; các lựa chọn còn lại đúng trong câu.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **concession marker**: The manuscript contains several factual errors; ___, its central argument remains difficult to dismiss.","options":["all the same","as a result","by the same token","in the meantime"],"correct_answer":"all the same","explanation":"“All the same” diễn tả sự nhượng bộ: dù có lỗi, lập luận chính vẫn mạnh. “As a result” chỉ kết quả, “by the same token” chỉ sự tương đồng về lập luận, còn “in the meantime” chỉ thời gian xen giữa.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **specification marker**: The funding will support public-interest technology; ___, tools that improve access to legal and medical information.","options":["namely","meanwhile","nevertheless","otherwise"],"correct_answer":"namely","explanation":"“Namely” dùng để nêu cụ thể điều vừa nói: các công cụ cải thiện khả năng tiếp cận thông tin. “Meanwhile” nói về thời gian/đối chiếu, “nevertheless” là nhượng bộ, “otherwise” là điều kiện hoặc hậu quả khác.","difficulty":2},{"type":"multiple_choice","question":"Choose the most natural **focus marker**: The design is visually elegant, but ___, it can be maintained by a small engineering team.","options":["more to the point","for instance","on the contrary","in passing"],"correct_answer":"more to the point","explanation":"“More to the point” chuyển sự chú ý sang điểm quan trọng hơn: khả năng bảo trì. “For instance” đưa ví dụ, “on the contrary” phủ định ý trước, còn “in passing” chỉ ý được nhắc thoáng qua.","difficulty":3},{"type":"multiple_choice","question":"Choose the best **reconsideration marker**: The witness sounded confident. ___, confidence is not the same as accuracy.","options":["Then again","Accordingly","To begin with","Likewise"],"correct_answer":"Then again","explanation":"“Then again” dùng khi người nói xem xét lại hoặc thêm một ý làm suy yếu nhận định trước. “Accordingly” chỉ kết quả, “to begin with” mở đầu lập luận, còn “likewise” chỉ sự tương tự.","difficulty":3},{"type":"multiple_choice","question":"Choose the correct **digression marker**: The lecture will focus on judicial independence. ___, the speaker trained as a historian before studying law.","options":["Incidentally","Consequently","Even so","That is to say"],"correct_answer":"Incidentally","explanation":"“Incidentally” dùng để thêm một thông tin phụ bên lề. “Consequently” chỉ hệ quả, “even so” chỉ nhượng bộ, còn “that is to say” dùng để giải thích lại.","difficulty":2},{"type":"fill_blank","question":"Complete with a **limiting marker**: The clinical trial shows promise in adults; ___, its relevance to children remains untested.","options":["even so","in this respect","as a rule","for that matter"],"correct_answer":"even so","explanation":"“Even so” tạo quan hệ nhượng bộ và giới hạn: dù có triển vọng, phạm vi áp dụng vẫn chưa chắc. “In this respect” chỉ một khía cạnh cụ thể, “as a rule” nói quy luật chung, “for that matter” thêm một điểm liên quan.","difficulty":3},{"type":"fill_blank","question":"Complete the **resumption marker**: The historical background is useful, but we cannot cover every detail today. ___, the central issue is how the treaty was interpreted afterward.","options":["At any rate","By contrast","For example","As such"],"correct_answer":"At any rate","explanation":"“At any rate” đưa cuộc thảo luận trở lại điểm chính hoặc chốt lại hướng nói. “By contrast” so sánh đối lập, “for example” nêu ví dụ, còn “as such” chỉ tư cách/bản chất đã nêu.","difficulty":3},{"type":"fill_blank","question":"Complete with a **stance marker**: ___, the editorial mistakes administrative convenience for democratic legitimacy.","options":["If anything","In the meantime","On the other hand","For instance"],"correct_answer":"If anything","explanation":"“If anything” nhấn mạnh rằng nếu có kết luận nào thì nó còn theo hướng mạnh hơn hoặc khác kỳ vọng. “In the meantime” nói về thời gian, “on the other hand” nêu mặt đối lập, còn “for instance” đưa ví dụ.","difficulty":3},{"type":"fill_blank","question":"Complete the **temporal marker**: The archive will not be digitized until next year. ___, researchers must request physical copies in advance.","options":["In the interim","On balance","To put it differently","All things considered"],"correct_answer":"In the interim","explanation":"“In the interim” nghĩa là trong thời gian chờ đợi giữa hai mốc. “On balance” và “all things considered” dùng để đánh giá tổng hợp, còn “to put it differently” dùng để diễn đạt lại.","difficulty":2},{"type":"error_correction","question":"Find the error: The satellite images are unusually clear; **on the contrary**, they reveal damage that earlier surveys had missed.","options":["unusually clear","on the contrary","reveal damage","earlier surveys"],"correct_answer":"on the contrary","explanation":"“On the contrary” dùng để bác bỏ hoặc phủ định ý trước, nhưng câu sau bổ sung hệ quả tích cực của độ rõ nét. Cần dùng “indeed” hoặc “in fact”; các cụm còn lại đúng về nghĩa và ngữ pháp.","difficulty":3},{"type":"error_correction","question":"Find the error: The novelist rarely discusses politics directly; **moreover**, her private letters show a deep concern with censorship.","options":["rarely discusses","moreover","private letters","deep concern"],"correct_answer":"moreover","explanation":"“Moreover” chỉ bổ sung cùng hướng, nhưng ở đây ý sau tạo sự điều chỉnh/đối lập với việc bà hiếm khi nói trực tiếp. Nên dùng “however” hoặc “nevertheless”; các phần còn lại không sai.","difficulty":3},{"type":"error_correction","question":"Find the error: The app does not store precise location data; **namely**, it records only the city selected by the user.","options":["does not store","precise location data","namely","selected by the user"],"correct_answer":"namely","explanation":"“Namely” nêu tên hoặc liệt kê chính xác cho danh từ trước, nhưng câu sau đang làm rõ bằng cách diễn đạt lại giới hạn dữ liệu. “That is” hoặc “in other words” tự nhiên hơn; các cụm khác đúng.","difficulty":3},{"type":"error_correction","question":"Find the error: The gallery is closed for restoration; **by the same token**, online tours will remain available throughout the summer.","options":["closed for restoration","by the same token","online tours","throughout the summer"],"correct_answer":"by the same token","explanation":"“By the same token” dùng khi cùng một lý do dẫn tới kết luận tương tự, nhưng ở đây ý sau là thông tin bù lại hoặc chuyển hướng. Nên dùng “nevertheless” hoặc “meanwhile”; các lựa chọn khác phù hợp trong câu.","difficulty":3}]$grammar$::jsonb, 'ai-golden', 59
from public.grammar_topics t where t.slug = 'discourse-markers'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 60. nominalisation
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('nominalisation', 'Nominalisation', 'Danh từ hóa', 'advanced', 60)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Danh từ hóa', '**Danh từ hóa (Nominalisation)** là quá trình biến đổi một động từ hoặc tính từ thành danh từ, giúp tóm lược ý tưởng và tạo ra một văn phong trang trọng, cô đọng hơn. Việc sử dụng cấu trúc này cho phép chúng ta diễn đạt các hành động, sự kiện hoặc khái niệm một cách trừu tượng và hàm súc trong câu.', $grammar$[{"en":"The committee decided to postpone the vote.","vi":"Ủy ban quyết định hoãn bỏ phiếu.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":13,"role":"noun","word":"committee","start":4},{"end":21,"role":"verb","word":"decided","start":14},{"end":24,"role":"preposition","word":"to","start":22},{"end":33,"role":"verb","word":"postpone","start":25},{"end":37,"role":"article","word":"the","start":34},{"end":42,"role":"noun","word":"vote","start":38}]},{"en":"The committee's decision led to a delay.","vi":"Quyết định của ủy ban dẫn đến trì hoãn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":15,"role":"noun","word":"committee's","start":4},{"end":24,"role":"noun","word":"decision","start":16},{"end":28,"role":"verb","word":"led","start":25},{"end":31,"role":"preposition","word":"to","start":29},{"end":33,"role":"article","word":"a","start":32},{"end":39,"role":"noun","word":"delay","start":34}]},{"en":"The rapid expansion caused concern.","vi":"Sự mở rộng nhanh chóng gây lo ngại.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"adjective","word":"rapid","start":4},{"end":19,"role":"noun","word":"expansion","start":10},{"end":26,"role":"verb","word":"caused","start":20},{"end":34,"role":"noun","word":"concern","start":27}]},{"en":"There was a significant improvement in sales.","vi":"Doanh số đã có sự cải thiện đáng kể.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"other","word":"There","start":0},{"end":9,"role":"auxiliary","word":"was","start":6},{"end":11,"role":"article","word":"a","start":10},{"end":23,"role":"adjective","word":"significant","start":12},{"end":35,"role":"noun","word":"improvement","start":24},{"end":38,"role":"preposition","word":"in","start":36},{"end":44,"role":"noun","word":"sales","start":39}]},{"en":"Their refusal surprised us.","vi":"Việc họ từ chối làm chúng tôi ngạc nhiên.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"determiner","word":"Their","start":0},{"end":13,"role":"noun","word":"refusal","start":6},{"end":23,"role":"verb","word":"surprised","start":14},{"end":26,"role":"pronoun","word":"us","start":24}]},{"en":"The implementation of the policy took months.","vi":"Việc triển khai chính sách mất nhiều tháng.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":18,"role":"noun","word":"implementation","start":4},{"end":21,"role":"preposition","word":"of","start":19},{"end":25,"role":"article","word":"the","start":22},{"end":32,"role":"noun","word":"policy","start":26},{"end":37,"role":"verb","word":"took","start":33},{"end":44,"role":"noun","word":"months","start":38}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **verb → noun** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"verb → noun","example":"The committee decided to postpone the vote."},{"case":"Kiểm tra thành phần theo sau","rule":"adjective → noun","example":"The committee's decision led to a delay."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"the + noun + of ...","example":"The rapid expansion caused concern."}],"usage":[{"en":"They decided to postpone. → Their decision to postpone...","vi":"Họ quyết định hoãn. → Quyết định hoãn của họ...","icon":"🏛️","label":"Biến động từ thành danh từ để văn phong trang trọng hơn"},{"en":"The committee's decision led to a long delay.","vi":"Quyết định của ủy ban dẫn đến sự trì hoãn kéo dài.","icon":"🔗","label":"Danh từ hóa để nối ý giữa hai câu mạch lạc"},{"en":"The rapid expansion of the city caused concern.","vi":"Sự mở rộng nhanh chóng của thành phố gây lo ngại.","icon":"📈","label":"Biến tính từ, động từ thành danh từ trừu tượng (expand → expansion)"},{"en":"There was a significant improvement in sales.","vi":"Đã có sự cải thiện đáng kể về doanh số.","icon":"📊","label":"Cấu trúc There + be + danh từ hóa trong văn học thuật"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"verb → noun","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"adjective → noun","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"the + noun + of ...","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["-tion","-ment","-ity","-ance","decision","solution","explanation"],"examples":[{"en":"The committee decided to postpone the vote.","vi":"Ủy ban quyết định hoãn bỏ phiếu.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":13,"role":"noun","word":"committee","start":4},{"end":21,"role":"verb","word":"decided","start":14},{"end":24,"role":"preposition","word":"to","start":22},{"end":33,"role":"verb","word":"postpone","start":25},{"end":37,"role":"article","word":"the","start":34},{"end":42,"role":"noun","word":"vote","start":38}]},{"en":"The committee's decision led to a delay.","vi":"Quyết định của ủy ban dẫn đến trì hoãn.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":15,"role":"noun","word":"committee's","start":4},{"end":24,"role":"noun","word":"decision","start":16},{"end":28,"role":"verb","word":"led","start":25},{"end":31,"role":"preposition","word":"to","start":29},{"end":33,"role":"article","word":"a","start":32},{"end":39,"role":"noun","word":"delay","start":34}]},{"en":"The rapid expansion caused concern.","vi":"Sự mở rộng nhanh chóng gây lo ngại.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":9,"role":"adjective","word":"rapid","start":4},{"end":19,"role":"noun","word":"expansion","start":10},{"end":26,"role":"verb","word":"caused","start":20},{"end":34,"role":"noun","word":"concern","start":27}]},{"en":"There was a significant improvement in sales.","vi":"Doanh số đã có sự cải thiện đáng kể.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"other","word":"There","start":0},{"end":9,"role":"auxiliary","word":"was","start":6},{"end":11,"role":"article","word":"a","start":10},{"end":23,"role":"adjective","word":"significant","start":12},{"end":35,"role":"noun","word":"improvement","start":24},{"end":38,"role":"preposition","word":"in","start":36},{"end":44,"role":"noun","word":"sales","start":39}]},{"en":"Their refusal surprised us.","vi":"Việc họ từ chối làm chúng tôi ngạc nhiên.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"determiner","word":"Their","start":0},{"end":13,"role":"noun","word":"refusal","start":6},{"end":23,"role":"verb","word":"surprised","start":14},{"end":26,"role":"pronoun","word":"us","start":24}]},{"en":"The implementation of the policy took months.","vi":"Việc triển khai chính sách mất nhiều tháng.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":18,"role":"noun","word":"implementation","start":4},{"end":21,"role":"preposition","word":"of","start":19},{"end":25,"role":"article","word":"the","start":22},{"end":32,"role":"noun","word":"policy","start":26},{"end":37,"role":"verb","word":"took","start":33},{"end":44,"role":"noun","word":"months","start":38}]}],"mistakes":[{"wrong":"The government decided to reduce tax. This decide was popular.","right":"The government decided to reduce tax. This decision was popular.","why":"Danh hóa động từ decide thành danh từ decision."},{"wrong":"I had no trouble to find a place.","right":"I had no trouble finding a place.","why":"Have trouble + V-ing."},{"wrong":"The analyse of the data took time.","right":"The analysis of the data took time.","why":"Danh từ của analyse là analysis."},{"wrong":"Her explain was clear.","right":"Her explanation was clear.","why":"Danh hóa explain thành explanation."}],"timeline":null,"comparison":"**Danh hóa vs mệnh đề động từ:** Danh hóa biến động từ/tính từ thành danh từ để câu trang trọng, học thuật: *APOLOGIZING to them is important* (V-ing làm chủ ngữ) thay vì *To apologize...* Văn academic chuộng danh hóa: decide → decision, explain → explanation.","definition":"**Danh từ hóa (Nominalisation)** là quá trình biến đổi một động từ hoặc tính từ thành danh từ, giúp tóm lược ý tưởng và tạo ra một văn phong trang trọng, cô đọng hơn. Việc sử dụng cấu trúc này cho phép chúng ta diễn đạt các hành động, sự kiện hoặc khái niệm một cách trừu tượng và hàm súc trong câu."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"Danh từ của 'decide' là gì?","options":["decisive","decision","deciding"],"correct_answer":"decision","explanation":"Decision là danh từ chỉ quyết định; decisive là tính từ."},{"type":"multiple_choice","question":"'We investigated the problem' có thể danh từ hóa thành câu nào?","options":["We conducted an investigation of the problem.","We conducted an investigate of the problem.","We conducted an investigative of the problem."],"correct_answer":"We conducted an investigation of the problem.","explanation":"Investigate → investigation (danh từ)."},{"type":"multiple_choice","question":"Chọn danh từ của 'improve'.","options":["improvingly","improvement","improved"],"correct_answer":"improvement","explanation":"Improve → improvement."},{"type":"multiple_choice","question":"'The company expanded rapidly' → 'The company's rapid ___'.","options":["expansion","expand","expansive"],"correct_answer":"expansion","explanation":"Expansion là danh từ của expand."}]$grammar$::jsonb, 'ai-golden', 60
from public.grammar_topics t where t.slug = 'nominalisation'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 61. hedging-language
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('hedging-language', 'Hedging Language', 'Ngôn ngữ rào đón (hedging)', 'advanced', 61)
