insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Ngôn ngữ rào đón (hedging)', '**Ngôn ngữ rào đón (Hedging Language)** là việc sử dụng các từ hoặc cụm từ để giảm bớt tính chắc chắn hoặc mạnh mẽ của một phát ngôn, giúp thể hiện sự lịch sự, khiêm tốn hoặc duy trì khoảng cách chuyên nghiệp. Chúng ta dùng hedging để làm cho lời nói hoặc văn viết trở nên mềm mại, ít mang tính khẳng định tuyệt đối hơn.', $grammar$[{"en":"This may indicate a broader problem.","vi":"Điều này có thể cho thấy một vấn đề rộng hơn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":8,"role":"modal","word":"may","start":5},{"end":17,"role":"verb","word":"indicate","start":9},{"end":19,"role":"article","word":"a","start":18},{"end":27,"role":"adjective","word":"broader","start":20},{"end":35,"role":"noun","word":"problem","start":28}]},{"en":"The results appear to support the theory.","vi":"Kết quả dường như ủng hộ lý thuyết.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"results","start":4},{"end":18,"role":"verb","word":"appear","start":12},{"end":21,"role":"preposition","word":"to","start":19},{"end":29,"role":"verb","word":"support","start":22},{"end":33,"role":"article","word":"the","start":30},{"end":40,"role":"noun","word":"theory","start":34}]},{"en":"It is likely that prices will rise.","vi":"Có khả năng giá sẽ tăng.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":12,"role":"adjective","word":"likely","start":6},{"end":17,"role":"conjunction","word":"that","start":13},{"end":24,"role":"noun","word":"prices","start":18},{"end":29,"role":"modal","word":"will","start":25},{"end":34,"role":"verb","word":"rise","start":30}]},{"en":"Some participants tended to respond slowly.","vi":"Một số người tham gia có xu hướng phản hồi chậm.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"Some","start":0},{"end":17,"role":"noun","word":"participants","start":5},{"end":24,"role":"verb","word":"tended","start":18},{"end":27,"role":"preposition","word":"to","start":25},{"end":35,"role":"verb","word":"respond","start":28},{"end":42,"role":"adverb","word":"slowly","start":36}]},{"en":"The policy could be more effective in cities.","vi":"Chính sách có thể hiệu quả hơn ở thành phố.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"policy","start":4},{"end":16,"role":"modal","word":"could","start":11},{"end":19,"role":"auxiliary","word":"be","start":17},{"end":24,"role":"adverb","word":"more","start":20},{"end":34,"role":"adjective","word":"effective","start":25},{"end":37,"role":"preposition","word":"in","start":35},{"end":44,"role":"noun","word":"cities","start":38}]},{"en":"To some extent, the criticism is fair.","vi":"Ở mức độ nào đó, lời chỉ trích là hợp lý.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"To","start":0},{"end":7,"role":"determiner","word":"some","start":3},{"end":14,"role":"noun","word":"extent","start":8},{"end":19,"role":"article","word":"the","start":16},{"end":29,"role":"noun","word":"criticism","start":20},{"end":32,"role":"auxiliary","word":"is","start":30},{"end":37,"role":"adjective","word":"fair","start":33}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **modal + V** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"modal + V","example":"This may indicate a broader problem."},{"case":"Kiểm tra thành phần theo sau","rule":"seem/appear/tend to + V","example":"The results appear to support the theory."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"It is possible/likely that ...","example":"It is likely that prices will rise."}],"usage":[{"en":"This may indicate a broader problem.","vi":"Điều này có thể cho thấy một vấn đề rộng hơn.","icon":"🌫️","label":"Động từ khuyết thiếu giảm mức khẳng định (may, might, could)"},{"en":"The results appear to support the theory.","vi":"Các kết quả dường như ủng hộ lý thuyết này.","icon":"🔬","label":"Động từ rào đón (appear, seem, suggest) thay khẳng định trực tiếp"},{"en":"It is likely that prices will rise.","vi":"Nhiều khả năng giá cả sẽ tăng.","icon":"📊","label":"Cấu trúc vô nhân xưng It is likely/possible that..."},{"en":"Some participants tended to respond slowly.","vi":"Một số người tham gia có xu hướng phản hồi chậm.","icon":"🧪","label":"Trạng từ và động từ giảm nhẹ (tend to, generally, relatively)"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"modal + V","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"seem/appear/tend to + V","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"It is possible/likely that ...","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["would","might","may","perhaps","possibly","tend to","It seems that"],"examples":[{"en":"This may indicate a broader problem.","vi":"Điều này có thể cho thấy một vấn đề rộng hơn.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"This","start":0},{"end":8,"role":"modal","word":"may","start":5},{"end":17,"role":"verb","word":"indicate","start":9},{"end":19,"role":"article","word":"a","start":18},{"end":27,"role":"adjective","word":"broader","start":20},{"end":35,"role":"noun","word":"problem","start":28}]},{"en":"The results appear to support the theory.","vi":"Kết quả dường như ủng hộ lý thuyết.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":11,"role":"noun","word":"results","start":4},{"end":18,"role":"verb","word":"appear","start":12},{"end":21,"role":"preposition","word":"to","start":19},{"end":29,"role":"verb","word":"support","start":22},{"end":33,"role":"article","word":"the","start":30},{"end":40,"role":"noun","word":"theory","start":34}]},{"en":"It is likely that prices will rise.","vi":"Có khả năng giá sẽ tăng.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"It","start":0},{"end":5,"role":"auxiliary","word":"is","start":3},{"end":12,"role":"adjective","word":"likely","start":6},{"end":17,"role":"conjunction","word":"that","start":13},{"end":24,"role":"noun","word":"prices","start":18},{"end":29,"role":"modal","word":"will","start":25},{"end":34,"role":"verb","word":"rise","start":30}]},{"en":"Some participants tended to respond slowly.","vi":"Một số người tham gia có xu hướng phản hồi chậm.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"determiner","word":"Some","start":0},{"end":17,"role":"noun","word":"participants","start":5},{"end":24,"role":"verb","word":"tended","start":18},{"end":27,"role":"preposition","word":"to","start":25},{"end":35,"role":"verb","word":"respond","start":28},{"end":42,"role":"adverb","word":"slowly","start":36}]},{"en":"The policy could be more effective in cities.","vi":"Chính sách có thể hiệu quả hơn ở thành phố.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"article","word":"The","start":0},{"end":10,"role":"noun","word":"policy","start":4},{"end":16,"role":"modal","word":"could","start":11},{"end":19,"role":"auxiliary","word":"be","start":17},{"end":24,"role":"adverb","word":"more","start":20},{"end":34,"role":"adjective","word":"effective","start":25},{"end":37,"role":"preposition","word":"in","start":35},{"end":44,"role":"noun","word":"cities","start":38}]},{"en":"To some extent, the criticism is fair.","vi":"Ở mức độ nào đó, lời chỉ trích là hợp lý.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"preposition","word":"To","start":0},{"end":7,"role":"determiner","word":"some","start":3},{"end":14,"role":"noun","word":"extent","start":8},{"end":19,"role":"article","word":"the","start":16},{"end":29,"role":"noun","word":"criticism","start":20},{"end":32,"role":"auxiliary","word":"is","start":30},{"end":37,"role":"adjective","word":"fair","start":33}]}],"mistakes":[{"wrong":"This is completely wrong.","right":"This might not be entirely correct.","why":"Văn học thuật dùng hedging để mềm hóa nhận định."},{"wrong":"If the weather changes, I hope you would remember.","right":"If the weather changes, I hope you'll remember.","why":"Hope về khả năng thực tế dùng will, không dùng would."},{"wrong":"They would likely to benefit.","right":"They would likely benefit.","why":"Likely ở đây là trạng từ — không chèn to trước động từ."},{"wrong":"It is obvious true.","right":"It seems to be true.","why":"Diễn đạt rào đón dùng seem thay vì khẳng định tuyệt đối."}],"timeline":null,"comparison":"**Hedging vs khẳng định thẳng:** Ngôn ngữ rào đón dùng would/might/perhaps để mềm hóa nhận định, dễ được đồng tình: *Many WOULD think he is too young* (nhiều người có lẽ sẽ nghĩ...). Khẳng định thẳng dùng will/hiện tại đơn: *Many WILL think...* Văn học thuật và giao tiếp lịch sự chuộng hedging.","definition":"**Ngôn ngữ rào đón (Hedging Language)** là việc sử dụng các từ hoặc cụm từ để giảm bớt tính chắc chắn hoặc mạnh mẽ của một phát ngôn, giúp thể hiện sự lịch sự, khiêm tốn hoặc duy trì khoảng cách chuyên nghiệp. Chúng ta dùng hedging để làm cho lời nói hoặc văn viết trở nên mềm mại, ít mang tính khẳng định tuyệt đối hơn."}$grammar$::jsonb, $grammar$[{"type":"multiple_choice","question":"Cách nói nào thể hiện sự chưa chắc chắn?","options":["This is certainly the only cause.","This might be one cause.","This must be the only cause."],"correct_answer":"This might be one cause.","explanation":"Might làm giảm mức độ chắc chắn của nhận định."},{"type":"multiple_choice","question":"___, the results suggest a small improvement.","options":["It seems that","It proves beyond doubt that","It guarantees that"],"correct_answer":"It seems that","explanation":"It seems that báo hiệu kết luận thận trọng."},{"type":"multiple_choice","question":"Chọn câu lịch sự hơn khi góp ý.","options":["Your plan is wrong.","Your plan may need some changes.","Your plan can never work."],"correct_answer":"Your plan may need some changes.","explanation":"May need làm lời góp ý mềm hơn mà vẫn rõ ý."},{"type":"multiple_choice","question":"Từ nào là dấu hiệu rào đón?","options":["definitely","perhaps","always"],"correct_answer":"perhaps","explanation":"Perhaps nghĩa là có lẽ, không khẳng định tuyệt đối."}]$grammar$::jsonb, 'ai-golden', 61
from public.grammar_topics t where t.slug = 'hedging-language'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
-- 62. grammatical-collocations
insert into public.grammar_topics (slug, title, title_vi, level, order_index)
values ('grammatical-collocations', 'Grammatical Collocations', 'Kết hợp ngữ pháp (collocations)', 'advanced', 62)
on conflict (slug) do nothing;
insert into public.grammar_lessons (topic_id, title, theory_vi, examples, sections, exercises, source, order_index)
select t.id, 'Kết hợp ngữ pháp (collocations)', '**Kết hợp ngữ pháp (Grammatical Collocations)** là cách các từ ngữ thường đi đôi với nhau theo quy tắc ngữ pháp cố định, ví dụ như sự kết hợp giữa động từ và giới từ hay tính từ và giới từ. Nắm vững những cặp từ này giúp người học sử dụng tiếng Anh một cách tự nhiên và chính xác hơn, tránh các lỗi diễn đạt không mong muốn.', $grammar$[{"en":"She is interested in design.","vi":"Cô ấy quan tâm đến thiết kế.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":6,"role":"auxiliary","word":"is","start":4},{"end":17,"role":"adjective","word":"interested","start":7},{"end":20,"role":"preposition","word":"in","start":18},{"end":27,"role":"noun","word":"design","start":21}]},{"en":"We depend on public transport.","vi":"Chúng tôi phụ thuộc vào giao thông công cộng.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":9,"role":"verb","word":"depend","start":3},{"end":12,"role":"preposition","word":"on","start":10},{"end":19,"role":"noun","word":"public","start":13},{"end":29,"role":"noun","word":"transport","start":20}]},{"en":"He apologized for being late.","vi":"Anh ấy xin lỗi vì đến muộn.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":13,"role":"verb","word":"apologized","start":3},{"end":17,"role":"preposition","word":"for","start":14},{"end":23,"role":"verb","word":"being","start":18},{"end":28,"role":"noun","word":"late","start":24}]},{"en":"There has been an increase in demand.","vi":"Nhu cầu đã tăng.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"pronoun","word":"There","start":0},{"end":9,"role":"auxiliary","word":"has","start":6},{"end":14,"role":"auxiliary","word":"been","start":10},{"end":17,"role":"article","word":"an","start":15},{"end":26,"role":"noun","word":"increase","start":18},{"end":29,"role":"preposition","word":"in","start":27},{"end":36,"role":"noun","word":"demand","start":30}]},{"en":"They prevented us from entering.","vi":"Họ ngăn chúng tôi vào.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":14,"role":"verb","word":"prevented","start":5},{"end":17,"role":"pronoun","word":"us","start":15},{"end":22,"role":"preposition","word":"from","start":18},{"end":31,"role":"verb","word":"entering","start":23}]},{"en":"I'm responsible for preparing the report.","vi":"Tôi chịu trách nhiệm chuẩn bị báo cáo.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"I'm","start":0},{"end":15,"role":"adjective","word":"responsible","start":4},{"end":19,"role":"preposition","word":"for","start":16},{"end":29,"role":"verb","word":"preparing","start":20},{"end":33,"role":"article","word":"the","start":30},{"end":40,"role":"noun","word":"report","start":34}]}]$grammar$::jsonb, $grammar${"tips":"**Mẹo nhớ:** học mẫu **adjective + preposition** cùng một câu hoàn chỉnh. Sau đó đổi chủ ngữ, thời điểm và dạng câu để thấy phần nào phải thay đổi.","rules":[{"case":"Chọn cấu trúc theo ý nghĩa","rule":"adjective + preposition","example":"She is interested in design."},{"case":"Kiểm tra thành phần theo sau","rule":"verb + preposition","example":"We depend on public transport."},{"case":"Nguyên âm và phụ âm","rule":"Nguyên âm tiếng Anh gồm a, e, i, o, u; các chữ cái còn lại thường là phụ âm. Phân biệt này quan trọng khi thêm hậu tố hoặc chọn a/an.","example":"study → studies (d là phụ âm); play → plays (a là nguyên âm)"},{"case":"Giữ sự hòa hợp và đúng dạng động từ","rule":"noun + preposition / verb pattern","example":"He apologized for being late."}],"usage":[{"en":"She is interested in graphic design.","vi":"Cô ấy quan tâm đến thiết kế đồ họa.","icon":"🎨","label":"Tính từ + giới từ cố định (interested in, good at)"},{"en":"We depend on public transport.","vi":"Chúng tôi phụ thuộc vào phương tiện công cộng.","icon":"🚌","label":"Động từ + giới từ cố định (depend on, belong to)"},{"en":"He apologized for being late.","vi":"Anh ấy xin lỗi vì đã đến muộn.","icon":"🙏","label":"Động từ + giới từ + V-ing (apologize for, insist on)"},{"en":"There has been an increase in demand.","vi":"Nhu cầu đã có sự gia tăng.","icon":"📈","label":"Danh từ + giới từ cố định (increase in, reason for)"}],"formula":{"note":"S = chủ ngữ; V = động từ nguyên thể; V3 = quá khứ phân từ; V-ing = dạng động từ thêm -ing. Luôn kiểm tra chủ ngữ, thời điểm và ý nghĩa trước khi chọn mẫu.","rows":[{"base":"adjective + preposition","form":"Cấu trúc chính","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"verb + preposition","form":"Biến thể quan trọng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"},{"base":"noun + preposition / verb pattern","form":"Dạng mở rộng","third":"Áp dụng theo ngữ cảnh và ý nghĩa của câu"}]},"signals":["interested in","good at","depend on","reason for","listen to","afraid of"],"examples":[{"en":"She is interested in design.","vi":"Cô ấy quan tâm đến thiết kế.","note":"Ví dụ 1: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"She","start":0},{"end":6,"role":"auxiliary","word":"is","start":4},{"end":17,"role":"adjective","word":"interested","start":7},{"end":20,"role":"preposition","word":"in","start":18},{"end":27,"role":"noun","word":"design","start":21}]},{"en":"We depend on public transport.","vi":"Chúng tôi phụ thuộc vào giao thông công cộng.","note":"Ví dụ 2: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"We","start":0},{"end":9,"role":"verb","word":"depend","start":3},{"end":12,"role":"preposition","word":"on","start":10},{"end":19,"role":"noun","word":"public","start":13},{"end":29,"role":"noun","word":"transport","start":20}]},{"en":"He apologized for being late.","vi":"Anh ấy xin lỗi vì đến muộn.","note":"Ví dụ 3: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":2,"role":"pronoun","word":"He","start":0},{"end":13,"role":"verb","word":"apologized","start":3},{"end":17,"role":"preposition","word":"for","start":14},{"end":23,"role":"verb","word":"being","start":18},{"end":28,"role":"noun","word":"late","start":24}]},{"en":"There has been an increase in demand.","vi":"Nhu cầu đã tăng.","note":"Ví dụ 4: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":5,"role":"pronoun","word":"There","start":0},{"end":9,"role":"auxiliary","word":"has","start":6},{"end":14,"role":"auxiliary","word":"been","start":10},{"end":17,"role":"article","word":"an","start":15},{"end":26,"role":"noun","word":"increase","start":18},{"end":29,"role":"preposition","word":"in","start":27},{"end":36,"role":"noun","word":"demand","start":30}]},{"en":"They prevented us from entering.","vi":"Họ ngăn chúng tôi vào.","note":"Ví dụ 5: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":4,"role":"pronoun","word":"They","start":0},{"end":14,"role":"verb","word":"prevented","start":5},{"end":17,"role":"pronoun","word":"us","start":15},{"end":22,"role":"preposition","word":"from","start":18},{"end":31,"role":"verb","word":"entering","start":23}]},{"en":"I'm responsible for preparing the report.","vi":"Tôi chịu trách nhiệm chuẩn bị báo cáo.","note":"Ví dụ 6: minh họa cách dùng và vị trí cấu trúc trong câu.","annotations":[{"end":3,"role":"pronoun","word":"I'm","start":0},{"end":15,"role":"adjective","word":"responsible","start":4},{"end":19,"role":"preposition","word":"for","start":16},{"end":29,"role":"verb","word":"preparing","start":20},{"end":33,"role":"article","word":"the","start":30},{"end":40,"role":"noun","word":"report","start":34}]}],"mistakes":[{"wrong":"She is interested about music.","right":"She is interested in music.","why":"Interested luôn đi với IN."},{"wrong":"It depends of the weather.","right":"It depends on the weather.","why":"Depend luôn đi với ON."},{"wrong":"I am good in English.","right":"I am good at English.","why":"Good luôn đi với AT."},{"wrong":"He listened the music.","right":"He listened to the music.","why":"Listen luôn đi với TO."}],"timeline":null,"comparison":"**Collocation ngữ pháp vs dịch word-by-word:** Cặp từ + giới từ trong tiếng Anh là CỐ ĐỊNH, không suy ra từ tiếng Việt: *listen TO music* (nghe nhạc — tiếng Việt không có \"to\"), *depend ON* (phụ thuộc VÀO — không phải of). Học cả cụm, đừng dịch từng chữ.","definition":"**Kết hợp ngữ pháp (Grammatical Collocations)** là cách các từ ngữ thường đi đôi với nhau theo quy tắc ngữ pháp cố định, ví dụ như sự kết hợp giữa động từ và giới từ hay tính từ và giới từ. Nắm vững những cặp từ này giúp người học sử dụng tiếng Anh một cách tự nhiên và chính xác hơn, tránh các lỗi diễn đạt không mong muốn."}$grammar$::jsonb, $grammar$[{"type":"fill","q":"There is ____ old man waiting at the gate.","opts":[],"answer":"an","fb":"old bắt đầu bằng nguyên âm → an"},{"type":"fill","q":"She has ____ (many / much) homework tonight.","opts":[],"answer":"much","fb":"homework không đếm được → much"},{"type":"fill","q":"____ (A few / Few) people came to her party, so it was really boring.","opts":[],"answer":"Few","fb":"nghĩa xấu, gần như chẳng ai đến → Few"},{"type":"fill","q":"My brother plays ____ guitar very well.","opts":[],"answer":"the","fb":"nhạc cụ đứng sau play → the"},{"type":"fill","q":"There are ____ (a lot of / much) students in the library today.","opts":[],"answer":"a lot of","fb":"students đếm được → a lot of, không dùng much"}]$grammar$::jsonb, 'ai-golden', 62
from public.grammar_topics t where t.slug = 'grammatical-collocations'
and not exists (select 1 from public.grammar_lessons l where l.topic_id = t.id);
commit;
